(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("plut-lives-3-e", [{"sp": "HDR", "t": "Βίοι Παράλληλοι"}, {"sp": "HDR", "t": "Πύρρος"}, {"sp": "N", "t": "Θεσπρωτῶν καὶ Μολοσσῶν μετὰ τὸν κατακλυσμὸν ἱστοροῦσι Φαέθοντα βασιλεῦσαι πρῶτον, ἕνα τῶν μετὰ Πελασγοῦ παραγενομένων εἰς τὴν Ἤπειρον ἔνιοι δὲ Δευκαλίωνα καὶ Πύρραν εἱσαμένους τὸ περὶ Δωδώνην ἱερὸν αὐτόθι κατοικεῖν ἐν Μολοσσοῖς. χρόνῳ δὲ ὕστερον Νεοπτόλεμος ὁ Ἀχιλλέως λαὸν ἀγαγὼν αὐτός τε τὴν χώραν κατέσχε καὶ διαδοχὴν βασιλέων ἀφ’ αὑτοῦ κατέλιπε, Πυρρίδας ἐπικαλουμένους· καὶ γὰρ αὐτῷ Πύρρος ἦν παιδικὸν ἐπωνύμιον. καὶ τῶν γνησίων παίδων ἐκ Λανάσσης τῆς Κλεοδαίου τοῦ Ὕλλου γενομένων ἕνα Πύρρον ὠνόμασεν. ἐκ τούτου δὲ καὶ Ἀχιλλεὺς ἐν Ἠπείρῳ τιμὰς ἰσοθέους ἔσχεν, Ἄσπετος ἐπιχωρίῳ φωνῇ προσαγορευόμενος. μετὰ δὲ τοὺς πρώτους, τῶν διὰ μέσου βασιλέων ἐκβαρβαρωθέντων καὶ γενομένων τῇ τε δυνάμει καὶ τοῖς βίοις ἀμαυροτέρων, Θαρρύπαν πρῶτον ἱστοροῦσιν Ἑλληνικοῖς ἔθεσι καὶ γράμμασι καὶ νόμοις φιλανθρώποις διακοσμήσαντα τὰς πόλεις ὀνομαστὸν γενέσθαι, Θαρρύπου δὲ Ἀλκέτας υἱὸς ἦν, Ἀλκέτα δὲ Ἀρύβας, Ἀρύβου δὲ καὶ Τρῳάδος Αἰακίδης. οὗτος ἔγημε τὴν Μένωνος τοῦ Θεσσαλοῦ θυγατέρα Φθίαν, ἀνδρὸς εὐδοκίμου περὶ τὸν Λαμιακὸν πόλεμον γενομένου καὶ μέγιστον ἀξίωμα τῶν συμμάχων μετὰ Λεωσθένην λαβόντος. ἐκ δὲ τῆς Φθίας τῷ Αἰακίδῃ γίνονται θυγατέρες Δηιδάμεια καὶ Τρῳάς, υἱὸς δὲ Πύρρος.", "st": "Pyrrh. 1.1"}, {"sp": "N", "t": "ἐπεὶ δὲ στασιάσαντες οἱ Μολοσσοὶ καὶ τὸν Αἰακίδην ἐκβαλόντες ἐπηγάγοντο τοὺς Νεοπτολέμου παῖδας, οἱ μὲν φίλοι τοῦ Αἰακίδου διεφθάρησαν καταληφθέντες, τὸν δὲ Πύρρον ἔτι νήπιον ὄντα καὶ ζητούμενον ὑπὸ τῶν πολεμίων ἐκκλέψαντες οἱ περὶ Ἀνδροκλείδην καὶ Ἄγγελον ἔφευγον, οἰκέτας ὀλίγους καὶ γύναια τιθηνούμενα τὸ παιδίον ἀναγκαίως ἐφελκόμενοι. καὶ διὰ τοῦτο τῆς φυγῆς αὐτοῖς γινομένης δυσέργου καὶ βραδείας καταλαμβανόμενοι τὸ μὲν παιδίον ἐγχειρίζουσιν Ἀνδροκλείωνι καὶ Ἱππίᾳ καὶ Νεάνδρῳ, νεανίσκοις οὖσι πιστοῖς καὶ ῥωμαλέοις, ἀνὰ κράτος φεύγειν καὶ Μεγάρων ἔχεσθαι χωρίου Μακεδονικοῦ προστάξαντες, αὐτοὶ δὲ τὰ μὲν δεόμενοι, τὰ δὲ ἀπομαχόμενοι τοῖς διώκουσιν ἐμποδὼν ἦσαν ἄχρι δείλης ὀψίας. ἀποτραπομένων δὲ μόλις ἐκείνων μετέθεον τοὺς τὸν Πύρρον κομίζοντας, ἤδη δὲ τοῦ ἡλίου καταδεδυκότος ἐγγὺς γενόμενοι τῆς ἐλπίδος ἐξαίφνης ἀπεκόπησαν, ἐντυχόντες τῷ παρὰ τὴν πόλιν παραρρέοντι ποταμῷ, χαλεπῷ μὲν ὀφθῆναι καὶ ἀγρίῳ, πειρωμένοις δὲ διαβαίνειν παντάπασιν ἀπορωτάτῳ. πολύ τε γὰρ ἐξέπιπτε ῥεῦμα καὶ θολερὸν ὄμβρων ἐπιγενομένων, καὶ τὸ σκότος ἐποίει πάντα φοβερώτερα. καθ’ αὑτοὺς μὲν οὖν ἀπέγνωσαν ἐπιχειρεῖν παιδίον φερόμενοι καὶ γύναια τὰ τρέφοντα τὸ παιδίον, αἰσθόμενοι δὲ τῶν ἐπιχωρίων τινὰς ἐν τῷ πέραν ἑστῶτας ἐδέοντο συλλαβέσθαι πρὸς τὴν διάβασιν, καὶ τὸν Πύρρον ἀνεδείκνυσαν βοῶντες καὶ ἱκετεύοντες. οἱ δὲ οὐ κατήκουον διὰ τραχύτητα καὶ πάταγον τὸν ῥεύματος, ἀλλ’ ἦν διατριβὴ τῶν μὲν βοώντων, τῶν δὲ μὴ συνιέντων, ἄχρι τις ἐννοήσας καὶ περιελὼν δρυὸς φλοιὸν ἐνέγραψε πόρπῃ γράμματα φράζοντα τήν τε χρείαν καὶ τὴν τύχην τοῦ παιδός, εἶτα λίθῳ τὸν φλοιὸν περιελίξας καὶ χρησάμενος οἷον ἕρματι τῆς βολῆς ἀφῆκεν εἰς τὸ πέραν ἔνιοι δέ φασι σαυνίῳ περιπήξαντας ἀκοντίσαι τὸν φλοιόν. ὡς δ’ οὖν ἀνέγνωσαν οἱ πέραν τὰ γράμματα καὶ συνεῖδον τὴν ὀξύτητα τοῦ καιροῦ, κόπτοντες ξύλα καὶ πρὸς ἄλληλα συνδέοντες ἐπεραιοῦντο. καὶ κατὰ τύχην ὁ πρῶτος αὐτῶν περαιωθεὶς Ἀχιλλεὺς τοὔνομα τὸν Πύρρον ἐδέξατο· τοὺς δὲ ἄλλους ὡς ἔτυχον ἄλλοι διεκόμιζον.", "st": "Pyrrh. 2.1"}, {"sp": "N", "t": "οὕτω δὲ σωθέντες καὶ φθάσαντες τὴν δίωξιν εἰς Ἰλλυριοὺς παρεγένοντο πρὸς Γλαυκίαν τὸν βασιλέα· καὶ καθεζόμενον εὑρόντες οἴκοι μετὰ τῆς γυναικὸς ἐν μέσῳ τὸ παιδίον ἐπὶ τῆς γῆς κατέθεσαν, ὁ δὲ ἦν ἐπὶ γνώμης, Κάσανδρον δεδοικὼς ἐχθρὸν ὄντα τοῦ Αἰακίδου, καὶ σιωπὴν εἶχε πολὺν χρόνον βουλευόμενος. ἐν τούτῳ δὲ ὁ Πύρρος ἀπ’ αὐτομάτου προσερπύσας καὶ λαβόμενος τοῦ ἱματίου ταῖς χερσὶ καὶ προσεξαναστὰς πρὸς τὰ γόνατα τοῦ Γλαυκίου γέλωτα πρῶτον, εἶτα οἶκτον παρέσχεν, ὥσπερ τις ἱκέτης ἐχόμενος καὶ δακρύων, ἔνιοι δέ φασιν οὐ τῷ Γλαυκίᾳ προσπεσεῖν αὐτόν, ἀλλὰ βωμοῦ θεῶν προσαψάμενον ἑστάναι πρὸς αὐτὸν περιβαλόντα τὰς χεῖρας, καὶ τὸ πρᾶγμα τῷ Γλαυκίᾳ θεῖον φανῆναι. διὸ καὶ παραυτίκα τὸν Πύρρον ἐνεχείρισε τῇ γυναικί, κελεύσας ἅμα τοῖς τέκνοις τρέφεσθαι, καὶ μικρὸν ὕστερον ἐξαιτουμένων τῶν πολεμίων, Κασάνδρου δὲ καὶ διακόσια τάλαντα διδόντος, οὐκ ἐξέδωκεν, ἀλλὰ καὶ γενόμενον δυοκαίδεκα ἐτῶν καταγαγὼν εἰς τὴν Ἤπειρον μετὰ δυνάμεως βασιλέα κατέστησεν.", "st": "Pyrrh. 3.1"}, {"sp": "N", "t": "ἦν δὲ ὁ Πύρρος τῇ μὲν ἰδέᾳ τοῦ προσώπου φοβερώτερον ἔχων ἢ σεμνότερον τὸ βασιλικόν, πολλοὺς δὲ ὀδόντας οὐκ εἶχεν, ἀλλ’ ἓν ὀστέον συνεχὲς ἦν ἄνωθεν, οἷον λεπταῖς ἀμυχαῖς τὰς διαφυὰς ὑπογεγραμμένον τῶν ὀδόντων. τοῖς δὲ σπληνιῶσιν ἐδόκει βοηθεῖν, ἀλεκτρυόνα θύων λευκόν, ὑπτίων τε κατακειμένων τῷ δεξιῷ ποδὶ πιέζων ἀτρέμα τὸ σπλάγχνον. οὐδεὶς δὲ ἦν πένης οὐδὲ ἄδοξος οὕτως ὥστε μὴ τυχεῖν τῆς ἰατρείας δεηθείς. ἐλάμβανε δὲ καὶ τὸν ἀλεκτρυόνα θύσας, καὶ τὸ γέρας τοῦτο ἥδιστον ἦν αὐτῷ. λέγεται δὲ τοῦ ποδὸς ἐκείνου τὸν μείζονα δάκτυλον ἔχειν δύναμιν θείαν, ὥστε μετὰ τὴν τελευτὴν τοῦ λοιποῦ σώματος κατακαέντος ἀπαθῆ καὶ ἄθικτον ὑπὸ τοῦ πυρὸς εὑρεθῆναι. ταῦτα μὲν οὖν ὕστερον.", "st": "Pyrrh. 3.4"}, {"sp": "N", "t": "γενομένῳ δὲ περὶ ἑπτακαίδεκα ἔτη καὶ δοκοῦντι τὴν ἀρχὴν ἔχειν βεβαίως ἀποδημία τις συνέτυχε, τῶν Γλαυκίου παίδων ἑνὸς, οἷς συνετέθραπτο, γυναῖκα λαμβάνοντος. πάλιν οὖν οἱ Μολοττοὶ συστάντες ἐξέβαλον τοὺς φίλους αὐτοῦ καὶ τὰ χρήματα διήρπασαν καὶ Νεοπτολέμῳ παρέδωκαν ἑαυτούς. ὁ δὲ Πύρρος οὕτω τὴν ἀρχὴν ἀποβαλὼν καὶ γενόμενος πάντων ἔρημος Δημητρίῳ τῷ Ἀντιγόνου προσέμιξεν ἑαυτόν, ἔχοντι τὴν ἀδελφὴν αὐτοῦ Δηιδάμειαν, ἣν ἔτι μὲν οὖσαν κόρην ὠνόμαζον Ἀλεξάνδρου τοῦ Ῥωξάνης γυναῖκα, τῶν δὲ κατ’ ἐκείνους δυστυχηθέντων ὥραν ἔχουσαν αὐτὴν ἔγημεν ὁ Δημήτριος. τῆς δὲ μεγάλης μάχης ἣν ἐν Ἰψῷ πάντες οἱ βασιλεῖς ἠγωνίσαντο, παρὼν ὁ Πύρρος τοῖς περὶ Δημήτριον συμμετεῖχε μειράκιον ὢν ἔτι, καὶ τοὺς καθ’ ἑαυτὸν ἐτρέψατο, καὶ διεφάνη λαμπρὸς ἐν τοῖς μαχομένοις. πταίσαντα δὲ Δημήτριον οὐκ ἐγκατέλιπεν, ἀλλὰ καὶ τὰς ἐν τῇ Ἑλλάδι πόλεις πιστευθεὶς διεφύλαξε, καὶ συμβάσεων αὐτῷ γενομένων πρὸς Πτολεμαῖον ἔπλευσεν εἰς Αἴγυπτον ὁμηρεύσων. καὶ Πτολεμαίῳ μὲν ἔν τε θήραις καὶ γυμνασίοις ἐπίδειξιν ἀλκῆς καὶ καρτερίας παρεῖχε, τὴν δὲ Βερενίκην ὁρῶν μέγιστον δυναμένην καὶ πρωτεύουσαν ἀρετῇ καὶ φρονήσει τῶν Πτολεμαίου γυναικῶν, ἐθεράπευε μάλιστα· καὶ δεινὸς ὢν ὑπελθεῖν ἐπ’ ὠφελείᾳ τοὺς κρείττονας, ὥσπερ ὑπερόπτης τῶν ταπεινοτέρων, κόσμιος δὲ καὶ σώφρων περὶ δίαιταν, ἐκ πολλῶν νέων ἡγεμονικῶν προεκρίθη λαβεῖν Ἀντιγόνην γυναῖκα τῶν Βερενίκης θυγατέρων, ἣν ἔσχεν ἐκ Φιλίππου πρὶν ἢ Πτολεμαίῳ συνοικεῖν.", "st": "Pyrrh. 4.1"}, {"sp": "N", "t": "μετὰ δὲ τὸν γάμον τοῦτον ἔτι μᾶλλον εὐδοκιμῶν, καὶ γυναικὸς ἀγαθῆς τῆς Ἀντιγόνης περὶ αὐτὸν οὔσης, διεπράξατο χρήματα λαβὼν καὶ δύναμιν εἰς Ἤπειρον ἐπὶ τὴν βασιλείαν ἀποσταλῆναι. καὶ παρῆν οὐκ ἄκουσι τοῖς πολλοῖς διὰ τὴν ἀπέχθειαν τὸν Νεοπτολέμου χαλεπῶς καὶ βιαίως ἄρχοντος, πλὴν ἀλλὰ δείσας μὴ πρός τινα τῶν ἄλλων βασιλέων ὁ Νεοπτόλεμος τράπηται, διαλύσεις ἔθετο καὶ φιλίαν πρὸς αὐτὸν ἐπὶ κοινωνίᾳ τῆς ἀρχῆς. χρόνου δὲ προϊόντος ἦσαν οἱ παροξύνοντες αὐτοὺς κρύφα καὶ κατ’ ἀλλήλων ἐμποιοῦντες ὑποψίας, ἡ μέντοι μάλιστα κινήσασα τὸν Πύρρον αἰτία λέγεται τοιαύτην ἀρχὴν λαβεῖν.", "st": "Pyrrh. 5.1"}, {"sp": "N", "t": "εἰώθεισαν οἱ βασιλεῖς ἐν Πασσαρῶνι, χωρίῳ τῆς Μολοττίδος, Ἀρείῳ Διί· θύσαντες ὁρκωμοτεῖν τοῖς Ἠπειρώταις καὶ ὁρκίζειν, αὐτοὶ μὲν ἄρξειν κατὰ τοὺς νόμους, ἐκείνους δὲ τὴν βασιλείαν διαφυλάξειν κατὰ τοὺς νόμους. ταῦτ’ οὖν ἐδρᾶτο ἀμφοτέρων τῶν βασιλέων παρόντων, καὶ συνῆσαν ἀλλήλοις μετὰ τῶν φίλων, δῶρα πολλὰ τὰ μὲν διδόντες, τὰ δὲ λαμβάνοντες, ἐνταῦθα δὴ Γέλων, ἀνήρ πιστὸς Νεοπτολέμῳ, δεξιωσάμενος φιλοφρόνως τὸν Πύρρον ἐδωρήσατο βοῶν ἀροτήρων δυσὶ ζεύγεσι. ταῦτα Μυρτίλος ὁ ἐπὶ τοῦ οἴνου παρὼν ᾔτει τὸν Πύρρον· ἐκείνου δὲ μὴ διδόντος, ἀλλ’ ἑτέρῳ, χαλεπῶς ἐνεγκὼν ὁ Μυρτίλος οὐκ ἔλαθε τὸν Γέλωνα. καλέσας οὖν αὐτὸν ἐπὶ δεῖπνον, ὡς δέ φασιν ἔνιοι, καὶ χρησάμενος παρ’ οἶνον ὥραν ἔχοντι, λόγους προσήνεγκε παρακαλῶν ἑλέσθαι τὰ τοῦ Νεοπτολέμου καὶ φαρμάκοις διαφθεῖραι τὸν Πύρρον. ὁ δὲ Μυρτίλος ἐδέξατο μὲν τὴν πεῖραν ὡς ἐπαινῶν καὶ συμπεπεισμένος, ἐμήνυσε δὲ τῷ Πύρρῳ· καὶ κελεύσαντος ἐκείνου τὸν ἀρχιοινοχόον Ἀλεξικράτην τῷ Γέλωνι συνέστησεν, ὡς δὴ μεθέξοντα τῆς πράξεως αὐτοῖς· ἐβούλετο γὰρ ἐν πλείοσιν ὁ Πύρρος τὸν ἔλεγχον γενέσθαι τοῦ ἀδικήματος. οὕτω δὲ τοῦ Γέλωνος ἐξαπατωμένου συνεξαπατώμενος ὁ Νεοπτόλεμος, καὶ τὴν ἐπιβουλὴν ὁδῷ βαδίζειν οἰόμενος οὐ κατεῖχεν, ἀλλ’ ὑπὸ χαρᾶς ἐξέφερε πρὸς τοὺς φίλους, καί ποτε κωμάσας παρὰ τὴν ἀδελφὴν Καδμείαν ἐχρῆτο λαλιᾷ περὶ τούτων, οὐδένα συνακούειν οἰόμενος· οὐδεὶς γὰρ ἦν πλησίον ἄλλος ἢ Φαιναρέτη γυνὴ Σάμωνος τοῦ τὰ ποίμνια καὶ τὰ βουκόλια τῷ Νεοπτολέμῳ διοικοῦντος, αὕτη δὲ ἀπεστραμμένη πρὸς τὸν τοῖχον ἐπὶ κλίνης τινὸς ἐδόκει καθεύδειν. συνήκοος δὲ πάντων γενομένη καὶ λαθοῦσα μεθ’ ἡμέραν ἧκε πρὸς Ἀντιγόνην τὴν Πύρρου γυναῖκα, καὶ πάντα κατεῖπεν ὅσα τοῦ Νεοπτολέμου πρὸς τὴν ἀδελφὴν ἤκουσε λέγοντος, πυθόμενος δὲ ὁ Πύρρος ἐκεῖ μὲν ἡσυχίαν ἦγεν, ἐν δὲ θυσίᾳ καλέσας ἐπὶ δεῖπνον τὸν Νεοπτόλεμον ἀπέκτεινεν, αἰσθόμενος τῶν Ἠπειρωτῶν τοὺς κρατίστους προσέχοντας αὑτῷ, καὶ παρακελευομένους ἀπαλλαγῆναι τοῦ Νεοπτολέμου, καὶ μὴ μερίδα μικρὰν ἔχοντα βασιλείας ἀγαπᾶν, ἀλλὰ τῇ φύσει χρήσασθαι μειζόνων πραγμάτων ἀντιλαμβανόμενον, καί τινος ὑποψίας ἅμα προσγενομένης τὸν Νεοπτόλεμον φθάσας ἀνελεῖν.", "st": "Pyrrh. 5.3"}, {"sp": "N", "t": "μεμνημένος δὲ Βερενίκης καὶ Πτολεμαίου παιδίον μὲν αὐτῷ γενόμενον ἐξ Ἀντιγόνης Πτολεμαῖον ὠνόμασεν, οἰκίσας δὲ πόλιν ἐν τῇ χερρονήσῳ τῆς Ἠπείρου Βερονικίδα προσηγόρευσεν. ἐκ δὲ τούτου πολλὰ μὲν περινοῶν καὶ μεγάλα τῇ γνώμῃ, ταῖς δὲ ἐλπίσι μάλιστα καὶ πρῶτον ἀντιλαμβανόμενος τῶν πλησίον, εὗρεν ἐμφῦναι τοῖς Μακεδόνων πράγμασιν ἐκ τοιᾶσδέ τινος προφάσεως.", "st": "Pyrrh. 6.1"}, {"sp": "N", "t": "τῶν Κασάνδρου παίδων ὁ πρεσβύτερος Ἀντίπατρος τήν τε μητέρα Θεσσαλονίκην ἀνεῖλε καὶ τὸν ἀδελφὸν Ἀλέξανδρον ἤλαυνεν. ὁ δὲ πρός τε Δημήτριον ἔπεμψε δεόμενος βοηθεῖν καὶ Πύρρον ἐκάλει. Δημητρίου δὲ ὑπὸ ἀσχολιῶν βραδύνοντος ἐπελθὼν ὁ Πύρρος ᾔτησε μισθὸν τῆς συμμαχίας τήν τε Στυμφαίαν καὶ τὴν Παραυαίαν τῆς Μακεδονίας, καὶ τῶν ἐπικτήτων ἐθνῶν Ἀμβρακίαν, Ἀκαρνανίαν, Ἀμφιλοχίαν. προεμένου δὲ τοῦ νεανίσκου ταῦτα μὲν αὐτὸς εἶχε φρουραῖς καταλαβών, τὰ δὲ λοιπὰ κτώμενος ἐκείνῳ περιέκοπτε τὸν Ἀντίπατρον. Λυσίμαχος δὲ ὁ βασιλεὺς αὐτὸς μὲν ἦν ἐν ἀσχολίαις προθυμούμενος Ἀντιπάτρῳ βοηθεῖν, εἰδὼς δὲ τὸν Πύρρον οὐδὲν ἀχαριστεῖν οὐδὲ ἀρνεῖσθαι Πτολεμαίῳ βουλόμενον ἔπεμψε πλαστὰ γράμματα πρὸς αὐτόν, ὡς Πτολεμαίου κελεύοντος ἀπαλλάττεσθαι τῆς στρατείας τριακόσια τάλαντα παρὰ τοῦ Ἀντιπάτρου λαβόντα. λύσας δὲ τὴν ἐπιστολὴν ὁ Πύρρος εὐθὺς τὸ ῥᾳδιούργημα τοῦ Λυσιμάχου συνεῖδεν· οὐδὲ γὰρ ἦν ἡ συνήθης γεγραμμένη προσαγόρευσις, ὁ πατήρ τῷ υἱῷ χαίρειν ἀλλά, βασιλεὺς Πτολεμαῖος βασιλεῖ Πύρρῳ χαίρειν. λοιδορήσας δὲ τὸν Λυσίμαχον ὅμως ἐποιεῖτο τὴν εἰρήνην, καὶ συνῄεσαν ὡς κατὰ σφαγίων ὁρκωμοτήσοντες. ἐπεὶ δὲ ταύρου καὶ κάπρου καὶ κριοῦ προσαχθέντος ὁ κριὸς αὐτομάτως ἀπέθανε, τοῖς μὲν ἄλλοις γελᾶν ἐπῄει, τὸν δὲ Πύρρον ὁ μάντις Θεόδοτος ὀμόσαι διεκώλυσε, φήσας τὸ δαιμόνιον ἑνὶ προσημαίνειν τῶν τριῶν βασιλέων θάνατον, ὁ μὲν οὖν Πύρρος οὕτως ἀπέστη τῆς εἰρήνης.", "st": "Pyrrh. 6.2"}, {"sp": "N", "t": "τῷ δὲ Ἀλεξάνδρῳ τῶν πραγμάτων ἤδη κατάστασιν ἐχόντων ὅμως ὁ Δημήτριος ἀφίκετο· καὶ δῆλος μὲν ἦν εὐθὺς ἥκων μὴ δεομένῳ, καὶ φόβον παρεῖχεν, ὀλίγας δ’· ἡμέρας συγγενόμενοι δι’ ἀπιστίας ἐπεβούλευσαν ἀλλήλοις ἀμφότεροι, καιρῷ δὲ χρησάμενος καὶ φθάσας ἀποκτίννυσιν ὁ Δημήτριος τὸ μειράκιον, καὶ βασιλεὺς ἀνηγορεύθη Μακεδονίας. ἦν μὲν οὖν καὶ πρότερον αὐτῷ πρὸς τὸν Πύρρον ἐγκλήματα, καὶ καταδρομαὶ τῆς Θεσσαλίας ἐγεγόνεισαν ὑπ’ ἐκείνου, καὶ τὸ σύμφυτον νόσημα ταῖς δυναστείαις, ἡ πλεονεξία, τὴν γειτνίασιν αὐτοῖς ἐπίφοβον καὶ ἄπιστον παρεῖχε, καὶ μᾶλλον ἔτι μετὰ τὴν τῆς Δηϊδαμείας τελευτήν. ἐπεὶ δὲ καὶ κατασχόντες ἀμφότεροι Μακεδονίας συνέπιπτον εἰς τὸ αὐτὸ καὶ μείζονας ἐλάμβανε προφάσεις ἡ διαφορά, Δημήτριος μὲν ἐπ’ Αἰτωλοὺς στρατευσάμενος καὶ κρατήσας, Πάνταυχον αὐτόθι μετὰ πολλῆς δυνάμεως καταλιπὼν αὐτὸς ἐβάδιζεν ἐπὶ Πύρρον, καὶ Πύρρος ἐπ’ ἐκεῖνον, ὡς ᾔσθετο. γενομένης δὲ διαμαρτίας καθ’ ὁδὸν ἀλλήλους παρήλλαξαν καὶ Δημήτριος μὲν ἐμβαλὼν εἰς Ἤπειρον ἐλεηλάτει, Πύρρος δὲ Πανταύχῳ περιπεσὼν εἰς μάχην κατέστη. καὶ τῶν στρατιωτῶν συμπεσόντων δεινὸς ἦν καὶ μέγας ἀγὼν, μάλιστα κατὰ τοὺς ἡγεμόνας, ὅ τε γάρ Πάνταυχος ἀνδρείᾳ καὶ χειρὶ καὶ ῥώμῃ σώματος ἄριστος ὢν ὁμολογουμένως τῶν περὶ Δημήτριον στρατηγῶν, καὶ θάρσος ἔχων καὶ φρόνημα, προὐκαλεῖτο τὸν Πύρρον εἰς χεῖρας, ὅ τε Πύρρος οὐδενὶ τῶν βασιλέων ὑφιέμενος ἀλκῆς καὶ τόλμης, καὶ τὴν Ἀχιλλέως δόξαν αὑτῷ δι’· ἀρετὴν μᾶλλον ἢ κατὰ γένος συνοικειοῦν βουλόμενος, ἐναντίος ἐχώρει διὰ τῶν προμάχων ἐπὶ τὸν Πάνταυχον. ἦν δὲ δορατισμὸς τὸ πρῶτον, εἶτα ἐν χεροῖν γενόμενοι μετὰ τέχνης ἅμα καὶ βίας ἐχρῶντο τοῖς ξίφεσι. λαβὼν δὲ ὁ Πύρρος ἓν τραῦμα, δοὺς δὲ δύο, τὸ μὲν εἰς τὸν μηρόν, τὸ δὲ παρὰ τὸν τράχηλον, ἐτρέψατο καὶ κατέβαλε τὸν Πάνταυχον οὐ μὴν ἀνεῖλεν, ἀνηρπάγη γάρ ὑπὸ τῶν φίλων, οἱ δὲ Ἠ πειρῶται τῇ νίκῃ τοῦ βασιλέως ἐπαρθέντες καὶ θαυμάσαντες τὴν ἀρετὴν ἐβιάσαντο καὶ διέκοψαν τὴν φάλαγγα τῶν Μακεδόνων, καὶ φεύγοντας διώκοντες ἀπέκτεινάν τε πολλοὺς καὶ πεντακισχιλίους ζῶντας εἷλον.", "st": "Pyrrh. 7.1"}, {"sp": "N", "t": "ὁ δὲ ἀγὼν οὗτος οὐ τοσοῦτον ὀργῆς ὧν ἔπαθον οὐδὲ μίσους ἐνέπλησε τοὺς Μακεδόνας πρὸς τὸν Πύρρον, ὅσην δόξαν αὐτοῦ καὶ θαῦμα τῆς ἀρετῆς καὶ λόγον ἐνειργάσατο τοῖς ἰδοῦσι τὰ ἔργα καὶ συνενεχθεῖσι κατὰ τὴν μάχην. καὶ γὰρ ὄψιν ᾤοντο καὶ τάχος ἐοικέναι καὶ κίνημα τοῖς Ἀλεξάνδρου, καὶ τῆς φορᾶς ἐκεῖνον καὶ βίας παρὰ τοὺς ἀγῶνας ἐν τούτῳ σκιάς τινας ὁρᾶσθαι καὶ μιμήματα, τῶν μὲν ἄλλων βασιλέων ἔν πορφύραις καὶ δορυφόροις καὶ κλίσει τραχήλου καὶ τῷ μεῖζον διαλέγεσθαι, μόνου δὲ Πύρρου τοῖς ὅπλοις καὶ ταῖς χερσὶν ἐπιδεικνυμένου τὸν Ἀλέξανδρον.", "st": "Pyrrh. 8.1"}, {"sp": "N", "t": "τῆς δὲ περὶ τάξεις καὶ στρατηγίας ἐπιστήμης αὐτοῦ καὶ δεινότητος ἔνεστι δείγματα λαβεῖν ἐκ τῶν γραμμάτων ἃ περὶ τούτων ἀπολέλοιπε. λέγεται δὲ καὶ ’ Ἀντίγονος ἐρωτηθεὶς τίς ἄριστος τῶν στρατηγῶν, φάναι, Πύρρος, ἂν γηράσῃ περὶ τῶν καθ’ αὑτὸν οὕτως ἀποφηνάμενος μόνον. Ἀννίβας δὲ συμπάντων ἀπέφηνε τῶν στρατηγῶν πρῶτον μὲν ἐμπειρίᾳ καὶ δεινότητι Πύρρον, Σκηπίωνα δὲ δεύτερον, ἑαυτὸν δὲ τρίτον, ὡς ἐν τοῖς περὶ Σκηπίωνος γέγραπται. καὶ ὅλως τοῦτο μελετῶν ἔοικε καὶ φιλοσοφῶν ἀεὶ διατελεῖν ὁ Πύρρος, ὡς μαθημάτων βασιλικώτατον, τὰς δὲ ἄλλας γλαφυρίας ἐν οὐδενὶ λόγῳ τίθεσθαι. λέγεται γάρ ὡς ἐρωτηθεὶς ἔν τινι πότῳ, πότερον αὐτῷ φαίνεται Πύθων αὐλητὴς ἀμείνων ἢ Καφισίας, εἰπεῖν ὅτι Πολυπέρχων στρατηγός, ὡς ταῦτα τῷ βασιλεῖ ζητεῖν μόνα καὶ γινώσκειν προσῆκον.", "st": "Pyrrh. 8.2"}, {"sp": "N", "t": "ἦν δὲ καὶ πρὸς τοὺς συνήθεις ἐπιεικὴς καὶ πρᾶος ὀργήν, σφοδρὸς δὲ καὶ πρόθυμος ἐν ταῖς χάρισιν. Ἀερόπου γοῦν ἀποθανόντος οὐκ ἤνεγκε μετρίως, ἐκεῖνον μὲν ἀνθρώπινα πεπονθέναι φάσκων, ἑαυτὸν δὲ μεμφόμενος καὶ κακίζων ὅτι μέλλων ἀεὶ καὶ βραδύνων χάριν οὐκ ἀπέδωκεν αὐτῷ. τὰ μὲν γὰρ χρέα καὶ κληρονόμοις ἔστιν ἀποδοῦναι τῶν δανεισάντων, αἱ δὲ τῶν χαρίτων ἀμοιβαὶ μὴ γενόμεναι πρὸς αἰσθανομένους ἀνιῶσι τὸν χρηστὸν καὶ δίκαιον. ἐν δὲ Ἀμβρακίᾳ κακολόγον τινὰ καὶ βλάσφημον ἄνθρωπον οἰομένων δεῖν μεταστῆσαι τὸν Πύρρον αὐτοῦ μένων, ἔφη, μᾶλλον ἡμᾶς ἐν ὀλίγοις ἢ περιιὼν πρὸς ἅπαντας ἀνθρώπους κακῶς λεγέτω. καὶ τοὺς παρ’ οἶνον αὑτὸν λοιδορήσαντας, εἶτα ἐλεγχομένους ἠρώτησεν εἰ ταῦτα εἶπον· ἀποκριναμένου δὲ τῶν νεανίσκων ἑνός, ταῦτα, ὦ βασιλεῦ· πλείονα δ’ ἂν ἔτι τούτων εἰρήκειμεν, εἰ πλείων παρῆν οἶνος ἡμῖν, γελάσας ἀφῆκε.", "st": "Pyrrh. 8.4"}, {"sp": "N", "t": "γυναῖκας δὲ πραγμάτων ἕνεκα καὶ δυνάμεως πλείονας ἔγημε μετὰ τὴν Ἀντιγόνης τελευτήν. καὶ γὰρ Αὐτολέοντος τοῦ Παιόνων βασιλέως ἔλαβε θυγατέρα, καὶ Βιρκένναν τὴν Βαρδύλλιος τοῦ Ἰλλυριῶν, καὶ Λάνασσαν τὴν Ἀγαθοκλέους τοῦ Συρακουσίου, προῖκα προσφερομένην αὐτῷ τὴν Κερκυραίων πόλιν ἡλωκυῖαν ὑπὸ Ἀγαθοκλέους, ἐκ μὲν οὖν Ἀντιγόνης Πτολεμαῖον υἱὸν ἔσχεν, ἐκ δὲ Λανάσσης Ἀλέξανδρον, Ἕλενον δὲ τὸν νεώτατον ἐκ Βιρκέννης. καὶ πάντας ἀγαθοὺς ἐν τοῖς ὅπλοις ἐθρέψατο καὶ διαπύρους, εὐθὺς ἐκ γενετῆς ἐπὶ τοῦτο θηγομένους ὑπ’ αὐτοῦ, λέγεται γὰρ ὡς ἐρωτηθεὶς ὑφ’ ἑνὸς αὐτῶν ἔτι παιδὸς ὄντος, τίνι καταλείψει τὴν βασιλείαν, εἰπεῖν, ὃς ἂν ὑμῶν τὴν μάχαιραν ὀξυτάτην ἔχῃ. τοῦτο δὲ οὐδὲν ἀποδεῖ τῆς τραγικῆς ἀρᾶς ἐκείνης· θηκτῷ σιδήρῳ δῶμα διαλαχεῖν τοὺς ἀδελφούς, οὕτως ἄμικτός ἐστι καὶ θηριώδης ἡ τῆς πλεονεξίας ὑπόθεσις.", "st": "Pyrrh. 9.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην ταύτην ὁ Πύρρος ἐπανελθὼν οἴκαδε λαμπρὸς ὑπὸ δόξης καὶ φρονήματος ἔχαιρε· καὶ Ἀετὸς ὑπὸ τῶν Ἠπειρωτῶν προσαγορευόμενος, δι’ ὑμᾶς, ἔλεγεν, ἀετὸς εἰμι· πῶς γὰρ οὐ μέλλω, τοῖς ὑμετέροις ὅπλοις ὥσπερ ὠκυπτέροις ἐπαιρόμενος; ὀλίγῳ δὲ ὕστερον πυθόμενος νοσεῖν τὸν Δημήτριον ἐπισφαλῶς ἐνέβαλε μὲν ἐξαίφνης εἰς Μακεδονίαν ὡς ἐπιδρομήν τινα καὶ λεηλασίαν ποιησόμενος, παρ’ ὀλίγον δὲ ἦλθε πάντων ὁμοῦ κρατῆσαι καὶ λαβεῖν ἀμαχεὶ τὴν βασιλείαν, ἐλάσας ἄχρι Ἐδέσσης μηδενὸς ἀμυνομένου, πολλῶν δὲ καὶ προστιθεμένων καὶ συστρατευόντων. αὐτόν τε δὴ τὸν Δημήτριον ὁ κίνδυνος ἐξανέστησε παρὰ δύναμιν, οἵ τε φίλοι καὶ ἡγεμόνες ὀλίγῳ χρόνῳ πολλοὺς ἀθροίσαντες ἐρρωμένως καὶ προθύμως ἐπὶ τὸν Πύρρον ὥρμησαν. ὁ δὲ λῃστρικώτερον ἀφιγμένος οὐκ ἔμεινεν, ἀλλὰ φεύγων μέρος τι τῆς στρατιᾶς ἀπέβαλε καθ’ ὁδὸν ἐπιθεμένων τῶν Μακεδόνων.", "st": "Pyrrh. 10.1"}, {"sp": "N", "t": "οὐ μὴν ὅτι ῥᾳδίως καὶ ταχὺ τὸν Πύρρον ἐξέβαλε τῆς χώρας ὁ Δημήτριος ἠμέλησεν, ἐγνωκὼς δὲ μεγάλων πραγμάτων ἀντιλαμβάνεσθαι καὶ τὴν πατρῴαν ἀρχὴν ἀνακτᾶσθαι δέκα μυριάσι στρατοῦ καὶ ναυσὶ πεντακοσίαις οὐκ ἐβούλετο τῷ Πύρρῳ προσπταῖσαι, οὐδὲ ἀπολιπεῖν Μακεδόσι πάροικον ἐργώδη καὶ χαλεπόν, ἀλλ’, ἐπεὶ μὴ ἐσχόλαζε πολεμεῖν πρὸς αὐτόν, διαλυθεὶς καὶ θέμενος εἰρήνην οὕτως ἐπὶ τοὺς ἄλλους βασιλεῖς τραπέσθαι. γενομένων δὲ διὰ ταῦτα τῶν ὁμολογιῶν, καὶ τῆς γνώμης ἅμα τῷ μεγέθει τῆς παρασκευῆς ἐκφανείσης τοῦ Δημητρίου, φοβηθέντες οἱ βασιλεῖς διεπέμποντο πρὸς τὸν Πύρρον ἀγγέλους καὶ γράμματα, θαυμάζειν φάσκοντες εἰ τὸν αὑτοῦ προέμενος καιρόν, ἐν τῷ Δημητρίου πολεμῆσαι περιμένει, καὶ δυνάμενος Μακεδονίας ἐκβαλεῖν αὐτὸν πολλὰ πράττοντα καὶ ταραττόμενον, ἐκδέχεται καὶ σχολάζοντι καὶ μεγάλῳ γενομένῳ περὶ τῶν ἐν Μολοσσοῖς ἱερῶν καὶ τάφων διαγωνίσασθαι, καὶ ταῦτα Κέρκυραν ἔναγχος ἀφῃρημένος ὑπ’ αὐτοῦ μετὰ τῆς γυναικός. ἡ γάρ Λάνασσα μεμψαμένη τὸν Πύρρον ὡς μᾶλλον προσέχοντα ταῖς βαρβάροις γυναιξίν εἰς Κέρκυραν ἀπεχώρησε, καὶ δεομένη γάμων βασιλικῶν ἐκάλει Δημήτριον, ἐπισταμένη μάλιστα τῶν βασιλέων εὐκόλως ἔχοντα πρὸς γάμους γυναικῶν, ἐκεῖνος δὲ πλεύσας τῇ τε Λανάσσῃ συνῆλθε καὶ φρουρὰν ἐν τῇ πόλει κατέλιπε.", "st": "Pyrrh. 10.3"}, {"sp": "N", "t": "ταῦτα πρὸς τὸν Πύρρον οἱ βασιλεῖς γράφοντες ἅμα καὶ δι’ ἑαυτῶν ἔτι μέλλοντα καὶ παρασκευαζόμενον τὸν Δημήτριον ἐκίνουν. Πτολεμαῖος μὲν γὰρ ἐπιπλεύσας μεγάλῳ στόλῳ τὰς Ἑλληνίδας ἀφίστη πόλεις, Λυσίμαχος δὲ τὴν ἄνω Μακεδονίαν ἐκ Θρᾴκης ἐμβαλὼν ἐπόρθει. Πύρρος δὲ τούτοις ἅμα συνεξαναστὰς ἐπὶ Βέροιαν ἤλαυνε, προσδοκῶν, ὅπερ συνέβη, Δημήτριον ὑπαντιάζοντα Λυσιμάχῳ τὴν κάτω χώραν ἀπολείψειν ἔρημον. ἐκείνης δὲ τῆς νυκτὸς ἔδοξε κατὰ τοὺς ὕπνους ὑπὸ Ἀλεξάνδρου καλεῖσθαι τοῦ μεγάλου, καὶ παραγενόμενος κλινήρη μὲν αὐτὸν ἰδεῖν, λόγων δὲ χρηστῶν τυχεῖν καὶ φιλοφροσύνης ἐπαγγελλομένου προθύμως βοηθήσειν. αὐτοῦ δὲ τολμήσαντος εἰπεῖν, καὶ πῶς ἄν, ὦ βασιλεῦ, νοσῶν δυνατὸς εἴης ἐμοὶ βοηθεῖν; αὐτῷ φάναι τῷ ὀνόματι, καὶ περιβάντα Νισαῖον ἵππον ἡγεῖσθαι.", "st": "Pyrrh. 11.1"}, {"sp": "N", "t": "ταύτην ἰδὼν τὴν ὄψιν ἐπερρώσθη· τάχει δὲ χρησάμενος καὶ διαδραμὼν τὰ μεταξὺ καταλαμβάνει τὴν Βέροιαν· καὶ τὸ πλεῖστον αὐτόθι τῆς στρατιᾶς ἱδρύσας τὰ λοιπὰ προσήγετο διὰ τῶν στρατηγῶν, ὁ δὲ Δημήτριος ἐπεὶ ταῦτα ἤκουσε καὶ πονηρὸν ἐν τῷ στρατοπέδῳ θόρυβον ᾔσθετο τῶν Μακεδόνων, ἔδεισε πορρωτέρω προαγαγεῖν, μὴ πλησίον γενόμενοι βασιλέως Μακεδόνος καὶ δόξαν ἔχοντος μεταβάλωνται πρὸς αὐτόν. ὅθεν ἐπιστρέψας ἐπὶ τὸν Πύρρον ἦγεν ὡς ξένον καὶ μισούμενον ὑπὸ τῶν Μακεδόνων, ἐπεὶ δὲ παρεστρατοπέδευσεν αὐτόθι, πολλοὶ τῶν ἐκ τῆς Βεροίας ἀφικνούμενοι τὸν Πύρρον ἐνεκωμίαζον, ὡς ἄμαχον μὲν ἐν τοῖς ὅπλοις καὶ λαμπρὸν ἄνδρα, πράως δὲ καὶ φιλανθρώπως τοῖς ἡλωκόσι χρώμενον. ἦσαν δέ τινες οὓς αὐτὸς ὁ Πύρρος ἐγκαθίει προσποιουμένους εἶναι Μακεδόνας, καὶ λέγοντας ὅτι νῦν καιρός ἐστι τῆς Δημητρίου βαρύτητος ἀπαλλαγῆναι, πρὸς ἄνδρα δημοτικὸν καὶ φιλοστρατιώτην μεταβαλομένους τὸν Πύρρον. ἐκ τούτου τὸ πλεῖστον ἀνηρέθιστο τῆς στρατιᾶς, καὶ τὸν Πύρρον ἐζήτουν περισκοποῦντες. ἔτυχε γὰρ ἀφῃρημένος τὸ κράνος, ἄχρι οὗ συμφρονήσας καὶ πάλιν περιθέμενος ἐγνώσθη τῷ τε λόφῳ διαπρέποντι καὶ τοῖς τραγικοῖς κέρασιν, ὥστε τοὺς Μακεδόνας σύνθημα προστρέχοντας αἰτεῖν, ἄλλους δὲ κλάδους δρυὸς ἀναστέφεσθαι διὰ τὸ καὶ τοὺς περὶ ἐκεῖνον ἐστεφανωμένους ὁρᾶν· ἤδη δὲ καὶ πρὸς αὐτόν τινες ἐτόλμων λέγειν τὸν Δημήτριον ὡς ὑπεκστὰς καὶ προέμενος τὰ πράγματα καλῶς δόξει βεβουλεῦσθαι. τούτοις τοῖς λόγοις ὅμοιον ὁρῶν τὸ κίνημα τοῦ στρατοπέδου καὶ φοβηθεὶς κρύφα διεξέπεσε, καυσίᾳ τινὶ καὶ λιτῷ χλαμυδίῳ περιστείλας ἑαυτόν, ἐπελθὼν δὲ ὁ Πύρρος ἀμαχεὶ παρέλαβε τὸ στρατόπεδον καὶ βασιλεὺς ἀνηγορεύθη Μακεδόνων.", "st": "Pyrrh. 11.3"}, {"sp": "N", "t": "ἐπιφανέντος δὲ Λυσιμάχου καὶ κοινὸν ἔργον ἀμφοῖν ποιουμένου τὴν Δημητρίου κατάλυσιν καὶ νέμεσθαι τὴν βασιλείαν ἀξιοῦντος, οὔπω πάνυ βεβαίως τοῖς Μακεδόσι πιστεύων ὁ Πύρρος, ἀλλ’ ἀμφίβολος ὢν ἐν αὐτοῖς ἐδέξατο τοῦ Λυσιμάχου τὴν πρόκλησιν, καὶ διενείμαντο τὰς πόλεις καὶ τὴν χώραν πρὸς ἀλλήλους. τοῦτο δὲ ὤνησε μὲν ἐν τῷ παρόντι καὶ κατέπαυσε τὸν πόλεμον αὐτοῖς, ὀλίγῳ δὲ ὕστερον ἔγνωσαν οὐκ ἀπαλλαγὴν ἔχθρας, ἀλλ’ ἐγκλημάτων καὶ διαφορᾶς ἀρχὴν πεποιημένοι τὴν νέμησιν. οἷς γάρ οὐ πέλαγος, οὐκ ὄρος, οὐκ ἀοίκητος ἐρημία πέρας ἐστὶ πλεονεξίας, οὐδ’ οἱ διαιροῦντες Εὐρώπην καὶ Ἀσίαν τέρμονες ὁρίζουσι τὰς ἐπιθυμίας, πῶς ἂν ἁπτόμενοι καὶ ψαύοντες ἀλλήλων ἀτρεμοῖεν ἐν τοῖς παροῦσι μὴ ἀδικοῦντες, οὐκ ἔστιν εἰπεῖν, ἀλλὰ πολεμοῦσι μὲν ἀεί, τὸ ἐπιβουλεύειν καὶ φθονεῖν ἔμφυτον ἔχοντες, δυεῖν δὲ ὀνομάτων, ὥσπερ νομισμάτων, πολέμου καὶ εἰρήνης, τῷ παρατυχόντι χρῶνται πρὸς τὸ συμφέρον, οὐ πρὸς τὸ δίκαιον, ἐπεὶ βελτίους γε πολεμεῖν ὁμολογοῦντές εἰσιν ἢ τῆς ἀδικίας τὸ ἀργοῦν καὶ σχολάζον δικαιοσύνην καὶ φιλίαν ὀνομάζοντες. ἐδήλωσε δὲ ὁ Πύρρος· ἐμποδὼν γάρ αὐξομένῳ τῷ Δημητρίῳ πάλιν ἱστάμενος, καὶ κωλύων τὴν δύναμιν ὥσπερ ἐξ ἀρρωστίας μεγάλης ἀναλαμβάνουσαν, ἐβοήθει τοῖς Ἕλλησι καὶ παρῆλθεν εἰς τὰς Ἀθήνας, ἀναβὰς δὲ εἰς τὴν ἀκρόπολιν καὶ θύσας τῇ θεῷ καὶ καταβὰς αὐθημερὸν ἀγαπᾶν μὲν ἔφησε τοῦ δήμου τὴν πρὸς αὐτὸν εὔνοιαν καὶ πίστιν, ἂν μέντοι σωφρονῶσι μηδένα τῶν βασιλέων ἔτι παρήσειν αὐτοὺς εἰς τὴν πόλιν μηδὲ τὰς πύλας ἀνοίξειν· ἐκ τούτου καὶ πρὸς Δημήτριον εἰρήνην ἐποιήσατο, καὶ μετ’ ὀλίγον χρόνον, εἰς Ἀσίαν ἀπάραντος αὐτοῦ, πάλιν πεισθεὶς ὑπὸ Λυσιμάχου Θετταλίαν ἀφίστη καὶ ταῖς Ἑλληνικαῖς φρουραῖς προσεπολέμει, βελτίοσι χρώμενος τοῖς Μακεδόσι στρατευομένοις ἢ σχολάζουσι, καὶ ὅλως αὐτὸς οὐκ ἐν πρὸς ἡσυχίαν πεφυκώς.", "st": "Pyrrh. 12.1"}, {"sp": "N", "t": "τέλος δὲ Δημητρίου καταπολεμηθέντος ἐν Συρίᾳ Λυσίμαχος ἐπ’ ἀδείας γενόμενος καὶ σχολάζων εὐθὺς ἐπὶ τὸν Πύρρον ὥρμησε. καὶ καθημένου περὶ τὴν Ἔδεσσαν αὐτοῦ ταῖς ἀγοραῖς κομιζομέναις ἐπιπεσὼν καὶ κρατήσας ἀπορίαν πρῶτον αὐτῷ περιέστησεν, εἶτα γράμμασι καὶ λόγοις διέφθειρε τοὺς πρώτους τῶν Μακεδόνων, ὀνειδίζων εἰ ξένον ἄνδρα καὶ προγόνων ἀεὶ δεδουλευκότων Μακεδόσι δεσπότην ἑλόμενοι τοὺς Ἀλεξάνδρου φίλους καὶ συνήθεις ἀπωθοῦσι Μακεδονίας. ἀναπειθομένων δὲ πολλῶν δείσας ὁ Πύρρος ἀπηλλάγη μετὰ τῆς Ἠπειρωτικῆς καὶ συμμαχικῆς δυνάμεως, ἀποβαλὼν Μακεδονίαν ᾧ τρόπῳ παρέλαβεν. ὅθεν οὐδ’ αἰτιᾶσθαι τοὺς πολλοὺς ἔχουσιν οἱ βασιλεῖς μετατιθεμένους πρὸς τὸ συμφέρον ἐκείνους γάρ αὐτοὺς ταῦτα μιμοῦνται ποιοῦντες, ἀπιστίας καὶ προδοσίας διδασκάλους ὄντας, καὶ πλεῖστα νομίζοντας ὠφελεῖσθαι τὸν ἐλάχιστα τῷ δικαίῳ χρώμενον.", "st": "Pyrrh. 12.6"}, {"sp": "N", "t": "τότε δ’ οὖν εἷς Ἤπειρον ἐκπεσόντι τῷ Πύρρῳ καὶ προεμένῳ Μακεδονίαν ἡ μὲν τύχη παρεῖχε χρῆσθαι τοῖς παροῦσιν ἀπραγμόνως καὶ ζῆν ἐν εἰρήνῃ βασιλεύοντα τῶν οἰκείων· ὁ δὲ τὸ μὴ παρέχειν ἑτέροις κακὰ μηδὲ ἔχειν ὑφ’ ἑτέρων ἄλυν τινὰ ναυτιώδη νομίζων, ὥσπερ ὁ Ἀχιλλεὺς οὐκ ἔφερε τὴν σχολήν,", "st": "Pyrrh. 13.1"}, {"sp": "N", "t": "ἀλλὰ φθινύθεσκε φίλον κῆρ<br>αὖθι μένων, ποθέεσκε δ’ ἀυτήν τε πτόλεμόν τε.", "st": "Pyrrh. 13.1b"}, {"sp": "N", "t": "δεόμενος δ’ οὖν ἔλαβε πραγμάτων καινῶν τοιαύτην ὑπόθεσιν. Ῥωμαῖοι Ταραντίνοις ἐπολέμουν· οἱ δὲ μήτε φέρειν τὸν πόλεμον δυνάμενοι μήτε θέσθαι θρασύτητι καὶ μοχθηρίᾳ δημαγωγῶν, ἐβουλεύοντο ποιεῖσθαι Πύρρον ἡγεμόνα καὶ καλεῖν ἐπὶ τὸν πόλεμον ὡς σχολὴν ἄγοντα πλείστην τῶν βασιλέων καὶ στρατηγὸν ὄντα δεινότατον. τῶν δὲ πρεσβυτέρων καὶ νοῦν ἐχόντων πολιτῶν οἱ μὲν ἄντικρυς ἐνιστάμενοι πρὸς τὴν γνώμην ἐξέπιπτον ὑπὸ κραυγῆς καὶ βίας τῶν πολεμοποιῶν, οἱ δὲ ταῦτα ὁρῶντες ἀπέλειπον τὰς ἐκκλησίας. εἷς δέ τις ἀνήρ ἐπιεικὴς, Μέτων ὄνομα, τῆς ἡμέρας ἐκείνης ἐν ᾗ τὸ δόγμα κυροῦν ἔμελλον ἐνστάσης καὶ τοῦ δήμου καθεζομένου, λαβὼν στέφανον τῶν ἑώλων καὶ λαμπάδιον, ὥσπερ οἱ μεθύοντες, αὐλητρίδος ὑφηγουμένης αὐτῷ πρὸς τὴν ἐκκλησίαν ἐκώμαζεν. οἷα δὲ ἐν ὄχλῳ δημοκρατίας κόσμον οὐκ ἐχούσης οἱ μὲν ἐκρότουν ἰδόντες, οἱ δὲ ἐγέλων, ἐκώλυε δὲ οὐδείς, ἀλλὰ καὶ τὸ γύναιον αὐλεῖν κἀκεῖνον ᾅδειν ἐκέλευον εἷς μέσον προελθόντα· καὶ τοῦτο ποιήσων ἐπίδοξος ἦν. γενομένης δὲ σιωπῆς ἄνδρες, ἔφη, Ταραντῖνοι, καλῶς ποιεῖτε παίζειν καὶ κωμάζειν, ἕως ἔξεστι, τοῖς βουλομένοις μὴ φθονοῦντες. ἐὰν δὲ σωφρονῆτε, καὶ πάντες ἀπολαύσετε ἔτι τῆς ἐλευθερίας, ὡς ἕτερα πράγματα καὶ βίον καὶ δίαιταν ἕξοντες ὅταν Πύρρος εἷς τὴν πόλιν παραγένηται. ταῦτα ῥηθέντα τοὺς πολλοὺς ἔπεισε τῶν Ταραντίνων, καὶ θροῦς διέδραμε τῆς ἐκκλησίας ὡς εὖ λεγομένων. οἱ δὲ τοὺς Ῥωμαίους δεδιότες, μὴ γενομένης εἰρήνης ἐκδοθῶσι, τόν τε δῆμον ἐλοιδόρουν εἰ φέρει πράως ἐπικωμαζόμενος οὕτως ἀσελγῶς καὶ παροινούμενος, τόν τε Μέτωνα συστραφέντες ἐξέβαλον.", "st": "Pyrrh. 13.2"}, {"sp": "N", "t": "οὕτω δὲ τοῦ δόγματος κυρίου γενομένου πρέσβεις ἔπεμψαν εἷς Ἤπειρον, οὐχ αὑτῶν μόνον, ἀλλὰ καὶ τῶν Ἰταλιωτῶν, δῶρα τῷ Πύρρῳ κομίζοντας καὶ λέγοντας ὡς ἡγεμόνος ἔμφρονος δέονται καὶ δόξαν ἔχοντος, δυνάμεις δὲ αὐτόθεν ὑπάρξουσι μεγάλαι παρά τε Λευκανῶν καὶ Μεσσαπίων καὶ Σαυνιτῶν καὶ Ταραντίνων εἷς δισμυρίους ἱππεῖς, πεζῶν δὲ ὁμοῦ πέντε καὶ τριάκοντα μυριάδας. ταῦτα οὐ μόνον αὐτὸν ἐπῆρε τὸν Πύρρον, ἀλλὰ καὶ τοῖς Ἠπειρώταις προθυμίαν ἐνέβαλε καὶ ὁρμὴν τῆς στρατείας.", "st": "Pyrrh. 13.6"}, {"sp": "N", "t": "ἦν δέ τις Κινέας, Θεσσαλὸς ἀνήρ, τῷ μὲν φρονεῖν δοκῶν ἱκανὸς εἶναι, Δημοσθένους δὲ τοῦ ῥήτορος ἀκηκοὼς ἐδόκει μόνος ἐν μάλιστα τῶν τότε λεγόντων οἷον ἐν εἰκόνι τῆς ἐκείνου δυνάμεως καὶ δεινότητος ἀναμιμνήσκειν τοὺς ἀκούοντας. συνὼν δὲ τῷ Πύρρῳ καὶ πεμπόμενος ἐπὶ τὰς πόλεις ἐβεβαίου τὸ Εὐριπίδειον, ὅτι πᾶν ἐξαιρεῖ λόγος", "st": "Pyrrh. 14.1"}, {"sp": "N", "t": "ὃ καὶ σίδηρος πολεμίων δράσειεν ἄν.", "st": "Pyrrh. 14.1b"}, {"sp": "N", "t": "ὁ γοῦν Πύρρος ἔλεγε πλείονας πόλεις ὑπὸ Κινέου τοῖς λόγοις ἢ τοῖς ὅπλοις ὑφ’ ἑαυτοῦ προσῆχθαι· καὶ διετέλει τὸν ἄνδρα τιμῶν ἐν τοῖς μάλιστα καὶ χρώμενος. οὗτος οὖν τὸν Πύρρον ὡρμημένον τότε ὁρῶν ἐπὶ τὴν Ἰταλίαν εἰς λόγους ἐπηγάγετο τοιούτους, ἰδὼν σχολάζοντα. πολεμισταὶ μέν, ὦ Πύρρε, Ῥωμαῖοι λέγονται καὶ πολλῶν ἐθνῶν μαχίμων ἄρχοντες· εἰ δὲ δοίη θεὸς περιγενέσθαι τῶν ἀνδρῶν, τί χρησόμεθα τῇ νίκῃ; καὶ ὁ Πύρρος, ἐρωτᾷς, εἶπεν, ὦ Κινέα, πρᾶγμα φαινόμενον· οὔτε βάρβαρος ἡμῖν ἐκεῖ πόλις οὔτε Ἑλληνὶς ἀξιόμαχος Ῥωμαίων κρατηθέντων, ἀλλ’ ἕξομεν εὐθὺς Ἰταλίαν ἅπασαν, ἧς μέγεθος καὶ ἀρετὴν καὶ δύναμιν ἄλλῳ πού τινι μᾶλλον ἀγνοεῖν ἢ σοὶ προσήκει. μικρὸν οὖν ἐπισχὼν ὁ Κινέας, Ἰταλίαν δέ, εἶπεν, ὦ βασιλεῦ, λαβόντες, τί ποιήσομεν; καὶ ὁ Πύρρος οὔπω τὴν διάνοιαν αὐτοῦ καθορῶν, ἐγγύς, εἶπεν, ἡ Σικελία χεῖρας ὀρέγει, νῆσος εὐδαίμων καὶ πολυάνθρωπος, ἁλῶναι δὲ ῥᾴστη· στάσις γάρ, ὦ Κινέα, πάντα νῦν ἐκεῖνα καὶ ἀναρχία πόλεων καὶ δημαγωγῶν ὀξύτης Ἀγαθοκλέους ἐκλελοιπότος εἰκότα, ἔφη, λέγεις, ὁ Κινέας· ἀλλ’ ἦ τοῦτο πέρας ἡμῖν τῆς στρατείας, λαβεῖν Σικελίαν; θεός, ἔφη ὁ Πύρρος, νικᾶν διδῴη καὶ κατορθοῦν· τούτοις δὲ προάγωσι χρησόμεθα πραγμάτων μεγάλων. τίς γὰρ ἂν ἀπόσχοιτο Λιβύης καὶ Καρχηδόνος ἐν ἐφικτῷ γενομένης, ἣν Ἀγαθοκλῆς ἀποδρὰς ἐκ Συρακουσῶν κρύφα καὶ περάσας ναυσὶν ὀλίγαις λαβεῖν παρ’ οὐδὲν ἦλθεν; ὅτι δὲ τούτων κρατήσασιν ἡμῖν οὐδεὶς ἀντιστήσεται τῶν νῦν ὑβριζόντων πολεμίων, τί ἂν λέγοι τις; οὐδέν, ὁ Κινέας εἶπε· δῆλον γὰρ ὅτι καὶ Μακεδονίαν ἀναλαβεῖν καὶ τῆς Ἑλλάδος ἄρχειν ὑπάρξει βεβαίως ἀπὸ τηλικαύτης δυνάμεως, γενομένων δὲ πάντων ὑφ’ ἡμῖν, τί ποιήσομεν; καὶ ὁ Πύρρος ἐπιγελάσας, σχολήν, ἔφη, ἄξομεν πολλήν, καὶ κώθων, ὦ μακάριε, καθημερινὸς ἔσται, καὶ διὰ λόγων συνόντες ἀλλήλους εὐφρανοῦμεν. ἐνταῦθα δὴ τῶν λόγων καταστήσας τὸν Πύρρον ὁ Κινέας, εἶτα, ἔφη, τί νῦν ἐμποδών ἐστιν ἡμῖν βουλομένοις κώθωνι χρῆσθαι καὶ σχολάζειν μετ’ ἀλλήλων, εἰ ταῦτα ἔχομεν ἤδη καὶ πάρεστιν ἀπραγμόνως ἐφ’ ἃ δι’ αἵματος καὶ πόνων μεγάλων καὶ κινδύνων μέλλομεν ἀφίξεσθαι, πολλὰ καὶ δράσαντες ἑτέρους κακὰ καὶ παθόντες;", "st": "Pyrrh. 14.2"}, {"sp": "N", "t": "τούτοις τοῖς λόγοις ἠνίασε μᾶλλον ἢ μετέθηκε τὸν Πύρρον ὁ Κινέας, νοήσαντα μὲν ὅσην ἀπέλειπεν εὐδαιμονίαν, ὧν δὲ ὠρέγετο τὰς ἐλπίδας ἀφεῖναι μὴ δυνάμενον.", "st": "Pyrrh. 14.8"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἀπέστειλε τὸν Κινέαν τοῖς Ταραντίνοις στρατιώτας ἄγοντα τρισχιλίους· ἔπειτα πολλῶν ἱππηγῶν καὶ καταφράκτων καὶ πορθμείων παντοδαπῶν ἐκ Τάραντος κομισθέντων ἐνεβίβαζεν ἐλέφαντας εἴκοσι καὶ τρισχιλίους ἱππεῖς, πεζοὺς δὲ δισμυρίους καὶ δισχιλίους τοξότας καὶ σφενδονήτας πεντακοσίους, γενομένων δὲ πάντων ἑτοίμων ἀναχθεὶς ἔπλει· καὶ μέσον ἔχων τὸν Ἰόνιον ἁρπάζεται βορέᾳ ἀνέμῳ παρ’ ὥραν ἐκραγέντι. καὶ βιασθεὶς αὐτὸς μὲν ἀρετῇ καὶ προθυμίᾳ ναυτῶν καὶ κυβερνητῶν ἐξανέφερε καὶ προσανῆγε τῇ γῇ πολυπόνως καὶ παραβόλως, τοῦ δὲ ἄλλου στόλου συγχυθέντος καὶ τῶν νεῶν σκεδασθεισῶν αἱ μὲν ἀποσφαλεῖσαι τῆς Ἰταλίας ἐξεώσθησαν εἰς τὸ Λιβυκὸν καὶ Σικελικὸν πέλαγος, τὰς δὲ ὑπερβαλεῖν μὴ δυνηθείσας ἄκραν Ἰαπυγίαν νύξ τε κατελάμβανε, καὶ πολλὴ καὶ χαλεπὴ θάλασσα παίουσα πρὸς χωρία δύσορμα καὶ τυφλὰ πάσας διέφθειρε πλὴν τῆς βασιλικῆς. αὕτη δὲ πλαγίου μὲν ἔτι ὄντος τοῦ κύματος ἠμύνετο καὶ διέφευγε μεγέθει καὶ ῥώμῃ τὰς ἐπιβολὰς τῆς θαλάσσης· ἐπεὶ δὲ περιελθὸν ἀπὸ γῆς ἀπήντα τὸ πνεῦμα καὶ κίνδυνον εἶχεν ἡ ναῦς ἀντίπρῳρος ἱσταμένη πρὸς κλύδωνα πολὺν διαρραγῆναι, τὸ δὲ ἐφέντας αὖθις ἠγριωμένῳ πελάγει καὶ πνεύματι τροπὰς λαμβάνοντι παντοδαπὰς φέρεσθαι φοβερώτερον ἐφαίνετο τῶν παρόντων κακῶν, ἄρας ὁ Πύρρος αὑτὸν ἀφῆκεν εἰς θάλασσαν, καὶ τῶν φίλων καὶ τῶν δορυφόρων εὐθὺς ἦν ἅμιλλα καὶ προθυμίᾳ περὶ αὐτόν. ἡ δὲ νύξ καὶ τὸ κῦμα μετὰ ψόφου μεγάλου καὶ τραχείας ἀνακοπῆς χαλεπὴν ἐποίει τὴν βοήθειαν, ὥστε μόλις ἡμέρας ἤδη μαραινομένου τοῦ πνεύματος ἐκπεσεῖν αὑτὸν ἐπὶ τὴν γῆν, τῷ μὲν σώματι παντάπασιν ἀδυνάτως ἔχοντα, τόλμῃ δὲ καὶ ῥώμῃ τῆς ψυχῆς ἀνταίροντα πρὸς τὴν ἀπορίαν. ἅμα δὲ οἵ τε Μεσσάπιοι, καθ’ οὓς ἐξεβράσθη, συνέθεον βοηθοῦντες ἐκ τῶν παρόντων προθύμως, καὶ προσεφέροντο τῶν σῳζομένων ἔνιαι νεῶν, ἐν αἷς ἦσαν ἱππεῖς μὲν ὀλίγοι παντάπασι πεζοὶ δὲ δισχιλίων ἐλάττους, ἐλέφαντες δὲ δύο.", "st": "Pyrrh. 15.1"}, {"sp": "N", "t": "τούτους ἀναλαβὼν ὁ Πύρρος ἐβάδιζεν εἰς Τάραντα. καὶ τοῦ Κινέου προαγαγόντος εἰς ἀπάντησιν, ὡς ᾔσθετο, τοὺς στρατιώτας, παρελθὼν οὐδὲν ἀκόντων οὐδὲ πρὸς βίαν ἔπραττε τῶν Ταραντίνων, ἕως ἀνεσώθησαν αἱ νῆες ἐκ τῆς θαλάττης καὶ συνῆλθεν ἡ πλείστη τῆς δυνάμεως. τηνικαῦτα δὲ ὁρῶν τὸ πλῆθος ἄνευ μεγάλης ἀνάγκης μήτε σώζεσθαι δυνάμενον μήτε σῴζειν, ἀλλ’ οἷον ἐκείνου προπολεμοῦντος οἴκοι καθῆσθαι περὶ λουτρὰ καὶ συνουσίας γενόμενον, ἀπέκλεισε μὲν τὰ γυμνάσια καὶ τοὺς περιπάτους, ἐν οἷς ἀλύοντες ὑπὲρ τῶν πραγμάτων λόγῳ διεστρατήγουν, πότους δὲ καὶ κώμους καὶ θαλίας ἀκαίρους ἀνεῖλεν, ἐκάλει δὲ πρὸς τὰ ὅπλα, καὶ περὶ τοὺς καταλόγους τῶν στρατευομένων ἀπαραίτητος ἦν καὶ λυπηρός, ὥστε πολλοὺς ἐκ τῆς πόλεως ἀπελθεῖν ἀηθείᾳ τοῦ ἄρχεσθαι δουλείαν τὸ μὴ πρὸς ἡδονὴν ζῆν καλοῦντας.", "st": "Pyrrh. 16.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Λαιβῖνος ὁ τῶν Ῥωμαίων ὕπατος ἠγγέλλετο πολλῇ στρατιᾷ χωρεῖν ἐπ’ αὑτὸν ἅμα τὴν Λευκανίαν διαπορθῶν, οὐδέπω μὲν οἱ σύμμαχοι παρῆσαν αὐτῷ, δεινὸν δὲ ποιούμενος κήρυκα πρὸς τοὺς Ῥωμαίους, εἰ φίλον ἀνασχέσθαι καὶ περιιδεῖν τοὺς πολεμίους ἐγγυτέρω προϊόντας ἐξῆλθε μετὰ τῆς δυνάμεως, προπέμψας ἐστὶν αὐτοῖς πρὸ πολέμου δίκας λαβεῖν παρὰ τῶν Ἰταλιωτῶν, αὐτῷ δικαστῇ καὶ διαλλακτῇ χρησαμένους. ἀποκριναμένου δὲ τοῦ Λαιβίνου μήτε διαλλακτὴν Πύρρον αἱρεῖσθαι Ῥωμαίους μήτε δεδοικέναι πολέμιον, προελθὼν κατεστρατοπέδευσεν ἐν τῷ μεταξὺ πεδίῳ Πανδοσίας πόλεως καὶ Ἡρακλείας. πυθόμενος δὲ τοὺς Ῥωμαίους ἐγγὺς εἶναι καὶ πέραν τοῦ Σίριος ποταμοῦ κατεστρατοπέδευσεν, προσίππευσε τῷ ποταμῷ θέας ἕνεκα· καὶ κατιδὼν τάξιν τε καὶ φυλακὰς καὶ κόσμον αὐτῶν καὶ τὸ σχῆμα τῆς στρατοπεδείας ἐθαύμασε, καὶ τῶν φίλων προσαγορεύσας τὸν ἐγγυτάτω, τάξις μέν, εἶπεν, ὦ Μεγάκλεις, αὕτη τῶν βαρβάρων οὐ βάρβαρος, τὸ δὲ ἔργον εἰσόμεθα. καὶ διὰ φροντίδος ἔχων ἤδη τὸ μέλλον ἔγνω τοὺς συμμάχους ἀναμένειν, τοῖς δὲ Ῥωμαίοις, ἂν πρότερον ἐπιχειρῶσι διαβαίνειν, ἐπέστησε φυλακὴν ὑπὲρ τοῦ ποταμοῦ τὴν εἴρξουσαν. οἱ δέ, ἅπερ ἐκεῖνος ἔγνω περιμένειν, φθῆναι σπεύδοντες, ἐνεχείρουν τῇ διαβάσει, κατὰ πόρον μὲν οἱ πεζοί, πολλαχόθεν δὲ οἱ ἱππεῖς διεξελαύνοντες τὸν ποταμόν, ὥστε δείσαντας τὴν κύκλωσιν ἀναχωρεῖν τοὺς Ἕλληνας, αἰσθόμενον δὲ τὸν Πύρρον καὶ διαταραχθέντα τοῖς μὲν ἡγεμόσι τοῦ πεζοῦ παρεγγυᾶν εὐθὺς εἰς τάξιν καθίστασθαι καὶ περιμένειν ἐν τοῖς ὅπλοις, αὑτὸν δὲ τοῖς ἱππεῦσι παρεξελάσαι τρισχιλίοις οὖσιν, ἐλπίζοντα διαβαίνοντας ἔτι καὶ διεσπασμένους ἀτάκτους λήψεσθαι τοὺς Ῥωμαίους. ἐπεὶ δ’ ἑώρα θυρεούς τε πολλοὺς ὑπερφαινομένους τοῦ ποταμοῦ καὶ τοὺς ἱππεῖς ἐπελαύνοντας ἐν τάξει, συστρέψας ἐνέβαλε πρῶτος, αὐτόθεν τε περίοπτος ὢν ὅπλων κάλλει καὶ λαμπρότητι κεκοσμημένων περιττῶς, καὶ τὴν δόξαν ἐπιδεικνύμενος ἔργοις οὐκ ἀποδέουσαν αὐτοῦ τῆς ἀρετῆς· μάλιστα δὲ ὅτι τὰς χεῖρας καὶ τὸ σῶμα παρέχων τῷ ἀγῶνι καὶ τοὺς καθ’ αὑτὸν ἀμυνόμενος ἐρρωμένως οὐ συνεχεῖτο τὸν λογισμὸν οὐδὲ τοῦ φρονεῖν ἐξέπιπτεν, ἀλλ’ ὥσπερ ἔξωθεν ἐφορῶν διεκυβέρνα τὸν πόλεμον, αὐτὸς μεταθέων ἑκασταχόσε καὶ παραβοηθῶν τοῖς ἐκβιάζεσθαι δοκοῦσιν.", "st": "Pyrrh. 16.3"}, {"sp": "N", "t": "ἔνθα δὴ Λεοννάτος ὁ Μακεδὼν ἄνδρα κατιδὼν Ἰταλὸν ἐπέχοντα τῷ Πύρρῳ καὶ τὸν ἵππον ἀντιπαρεξάγοντα καὶ συμμεθιστάμενον ἀεὶ καὶ συγκινούμενον, ὁρᾷς, εἶπεν, ὦ βασιλεῦ, τὸν βάρβαρον ἐκεῖνον, ὃν ὁ μέλας ἵππος ὁ λευκόπους φέρει; μέγα τι βουλευομένῳ καὶ δεινὸν ὅμοιός ἐστι. σοὶ γὰρ ἐνορᾷ καὶ πρὸς σὲ τέταται πνεύματος μεστὸς ὢν καὶ θυμοῦ, τοὺς δὲ ἄλλους ἐᾷ χαίρειν. ἀλλὰ σὺ φυλάττου τὸν ἄνδρα καὶ ὁ Πύρρος ἀπεκρίνατο, τὸ μὲν εἱμαρμένον, ὦ Λεοννάτε, διαφυγεῖν ἀδύνατον· χαίρων δὲ οὔτε οὗτος οὔτ’ ἄλλος τις Ἰταλῶν εἰς χεῖρας ἡμῖν σύνεισιν. ἔτι ταῦτα προσδιαλεγομένων ὁ Ἰταλὸς διαλαβὼν τὸ δόρυ καὶ συστρέψας τὸν ἵππον ὥρμησεν ἐπὶ τὸν Πύρρον. εἶτα ἅμα παίει μὲν αὐτὸς τῷ δόρατι τοῦ βασιλέως τὸν ἵππον, παίει δὲ τὸν ἐκείνου παραβαλὼν ὁ Λεοννάτος. ἀμφοτέρων δὲ τῶν ἵππων πεσόντων τὸν μὲν Πύρρον οἱ φίλοι περισχόντες ἀνήρπασαν, τὸν δὲ Ἰταλὸν μαχόμενον διέφθειραν. ἦν δὲ τῷ γένει Φρεντανός, ἴλης ἡγεμών, Ὄπλακος ὄνομα.", "st": "Pyrrh. 16.9"}, {"sp": "N", "t": "τοῦτο δὲ ἐδίδαξε τὸν Πύρρον μᾶλλον φυλάττεσθαι· καὶ τοὺς ἱππεῖς ὁρῶν ἐνδιδόντας μετεπέμπετο τὴν φάλαγγα καὶ παρέταττεν, αὐτὸς δὲ τὴν χλαμύδα καὶ τὰ ὅπλα παραδοὺς ἑνὶ τῶν ἑταίρων Μεγακλεῖ, τοῖς δὲ ἐκείνου τρόπον τινὰ κατακρύψας ἑαυτόν ἐπῆγε τοῖς Ῥωμαίοις. δεξαμένων δὲ ἐκείνων καὶ συμβαλόντων χρόνον τε πολὺν εἱστήκει τὰ τῆς μάχης ἄκριτα, καὶ τροπὰς ἑπτὰ λέγεται φευγόντων ἀνάπαλιν καὶ διωκόντων γενέσθαι. καὶ γὰρ ἡ διάμειψις τῶν ὅπλων ἐν καιρῷ πρὸς σωτηρίαν αὐτοῦ γεγονυῖα τοῦ βασιλέως ὀλίγον ἐδέησεν ἀνατρέψαι τὰ πράγματα καὶ διαφθεῖραι τὴν νίκην. πολλῶν γάρ ἐφιεμένων τοῦ Μεγακλέους, ὁ πρῶτος πατάξας καὶ καταβαλὼν αὐτόν, ὄνομα Δεξόος, ἀφαρπάσας τὸ κράνος καὶ τὴν χλαμύδα τῷ Λαιβίνῳ προσίππευσεν ἀναδεικνύων ἅμα καὶ βοῶν ἀνῃρηκέναι τὸν Πύρρον. ἦν οὖν παρὰ τὰς τάξεις τῶν λαφύρων παραφερομένων καὶ ἀναδεικνυμένων τοῖς τε Ῥωμαίοις χαρὰ μετ’ ἀλαλαγμοῦ καὶ τοῖς Ἕλλησιν ἀθυμία καὶ κατάπληξις, ἄχρι οὗ μαθὼν ὁ Πύρρος τὸ γινόμενον παρήλαυνε γυμνῷ τῷ προσώπῳ τήν τε δεξιὰν ὀρέγων τοῖς μαχομένοις καὶ τῇ φωνῇ σημαίνων ἑαυτόν, τέλος δὲ τῶν θηρίων ἐκβιαζομένων μάλιστα τοὺς Ῥωμαίους, καὶ τῶν ἵππων, πρὶν ἐγγὺς γενέσθαι, δυσανασχετούντων καὶ παραφερόντων τοὺς ἐπιβάτας, ἐπαγαγὼν τὴν Θετταλικὴν ἵππον αὐτοῖς ταρασσομένοις ἐτρέψατο πολλῷ φόνῳ.", "st": "Pyrrh. 17.1"}, {"sp": "N", "t": "Διονύσιος μὲν οὖν ὀλίγῳ τῶν πεντακισχιλίων καὶ μυρίων ἐλάσσονας πεσεῖν ἱστορεῖ Ῥωμαίων, Ἱερώνυμος δὲ μόνους ἑπτακισχιλίους, τῶν δὲ περὶ Πύρρον ὁ μὲν Διονύσιος μυρίους καὶ τρισχιλίους, ὁ δὲ Ἱερώνυμος ἐλάττονας τῶν τετρακισχιλίων· κράτιστοι δὲ ἦσαν οὗτοι· καὶ τῶν φίλων ὁ Πύρρος καὶ τῶν στρατηγῶν οἷς μάλιστα χρώμενος διετέλει καὶ πιστεύων ἀπέβαλεν. οὐ μὴν ἀλλὰ καὶ τὸ στρατόπεδον ἔλαβε τῶν Ῥωμαίων ἐκλιπόντων, καὶ πόλεις συμμαχίδας αὐτῶν προσηγάγετο, καὶ χώραν πολλὴν διεπόρθησε, καὶ προῆλθεν ὅσον μὴ πλέον σταδίων τριακοσίων ἀποσχεῖν τῆς Ῥώμης. ἀφίκοντο δὲ αὐτῷ Λευκανῶν τε πολλοὶ καὶ Σαυνιτῶν μετὰ τὴν μάχην, οὓς ἐμέμψατο μὲν ὑστερήσαντας, ἦν δὲ δῆλος ἡδόμενος καὶ μέγα φρονῶν ὅτι μόνοις τοῖς μετ’ αὐτοῦ καὶ Ταραντίνοις ἐκράτησε τῆς μεγάλης Ῥωμαίων δυνάμεως.", "st": "Pyrrh. 17.4"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ Λαιβῖνον μὲν οὐκ ἀπήλλαξαν τῆς ἀρχῆς, καίτοι λέγεται Γάιον Φαβρίκιον εἰπεῖν ὡς οὐκ Ἠπειρῶται Ῥωμαίους, ἀλλὰ Πύρρος νενικήκοι Λαιβῖνον, οἰόμενον οὐ τῆς δυνάμεως, ἀλλὰ τῆς στρατηγίας γεγονέναι τὴν ἧτταν ἀναπληροῦντες δὲ τὰς τάξεις καὶ συντάττοντες ἑτέρας προθύμως, καὶ λόγους ἀδεεῖς καὶ σοβαροὺς περὶ τοῦ πολέμου λέγοντες, ἔκπληξιν τῷ Πύρρῳ παρεῖχον. ἔδοξεν οὖν αὐτῷ πέμψαντι πρότερον διάπειραν λαβεῖν τῶν ἀνδρῶν, εἰ συμβατικῶς ἔχοιεν, ἡγουμένῳ τὸ μὲν ἑλεῖν τὴν πόλιν καὶ κρατῆσαι παντάπασιν οὐ μικρὸν ἔργον οὐδὲ τῆς παρούσης δυνάμεως εἶναι, τὴν δὲ φιλίαν καὶ τὰς διαλύσεις κάλλιστα ἔχειν πρὸς δόξαν αὐτῷ μετὰ νίκην. πεμφθεὶς οὖν ὁ Κινέας ἐνετύγχανε τοῖς δυνατοῖς, καὶ δῶρα παισὶν αὐτῶν καὶ γυναιξὶν ἔπεμψε παρὰ τοῦ βασιλέως. ἔλαβε δὲ οὐδείς, ἀλλ’ ἀπεκρίναντο πάντες καὶ πᾶσαι ὅτι δημοσίᾳ σπονδῶν γενομένων καὶ τὰ παρ’ αὐτῶν ὑπάρξει πρόθυμα τῷ βασιλεῖ καὶ κεχαρισμένα. πρὸς δὲ τὴν σύγκλητον ἐπαγωγὰ τοῦ Κινέου πολλὰ καὶ φιλάνθρωπα διαλεχθέντος, ἄσμενοι μὲν οὐδὲν οὐδὲ ἑτοίμως ἐδέχοντο, καίπερ ἄνδρας τε τοὺς ἡλωκότας ἐν τῇ μάχῃ δίχα λύτρων ἀφιέντος αὐτοῖς τοῦ Πύρρου καὶ συγκατεργάσασθαι τὴν Ἰταλίαν ἐπαγγελλομένου, φιλίαν δὲ ἀντὶ τούτων ἑαυτῷ καὶ τοῖς Ταραντίνοις ἄδειαν, ἕτερον δὲ μηδὲν αἰτουμένου. δῆλοί γε μὴν ἦσαν ἐνδιδόντες οἱ πολλοὶ πρὸς τὴν εἰρήνην, ἡττημένοι τε μεγάλῃ μάχῃ καὶ προσδοκῶντες ἑτέραν ἀπὸ μείζονος δυνάμεως, τῶν Ἰταλικῶν τῷ Πύρρῳ προσγεγονότων. ἔνθα δὴ Κλαύδιος Ἄππιος, ἀνὴρ ἐπιφανής, ὑπὸ δὲ γήρως ἅμα καὶ πηρώσεως ὀμμάτων ἀπειρηκὼς πρὸς τὴν πολιτείαν καὶ πεπαυμένος, ἀπαγγελλομένων τότε τῶν παρὰ τοῦ βασιλέως καὶ λόγου κατασχόντος ὡς μέλλει ψηφίζεσθαι τὰς διαλύσεις ἡ σύγκλητος, οὐκ ἐκαρτέρησεν, ἀλλὰ τοὺς θεράποντας ἄρασθαι κελεύσας αὑτόν ἐκομίζετο πρὸς τὸ βουλευτήριον ἐν φορείῳ δι’ ἀγορᾶς. γενόμενον δὲ πρὸς ταῖς θύραις οἱ μὲν παῖδες ἅμα τοῖς γαμβροῖς ὑπολαβόντες καὶ περισχόντες εἰσῆγον, ἡ δὲ βουλὴ σιωπὴν αἰδουμένη τὸν ἄνδρα μετὰ τιμῆς ἔσχεν.", "st": "Pyrrh. 18.1"}, {"sp": "N", "t": "ὁ δὲ αὐτόθεν καταστάς, πρότερον μέν, ἔφη, τὴν περὶ τὰ ὄμματα τύχην ἀνιαρῶς ἔφερον, ὦ Ῥωμαῖοι, νῦν δὲ ἄχθομαι πρὸς τῷ τυφλὸς εἶναι μὴ καὶ κωφὸς ὤν, ἀλλ’ ἀκούων αἰσχρὰ βουλεύματα καὶ δόγματα ὑμῶν ἀνατρέποντα τῆς Ῥώμης τὸ κλέος, ποῦ γὰρ ὑμῶν ὁ πρός ἅπαντας ἀνθρώπους θρυλούμενος ἀεὶ λόγος, ὡς, εἰ παρῆν ἐκεῖνος εἰς Ἰταλίαν ὁ μέγας Ἀλέξανδρος καὶ συνηνέχθη νέοις ἡμῖν καὶ τοῖς πατράσιν ἡμῶν ἀκμάζουσιν, οὐκ ἂν ὑμνεῖτο νῦν ἀνίκητος, ἀλλ’ ἢ φυγὼν ἂν ἤ ποῦ πεσὼν ἐνταῦθα τὴν Ῥώμην ἐνδοξοτέραν ἀπέλιπε; ταῦτα μέντοι κενὴν ἀλαζονείαν καὶ κόμπον ἀποδείκνυτε, Χάονας καὶ Μολοσσούς, τὴν ἀεὶ Μακεδόνων λείαν, δεδιότες, καὶ τρέμοντες Πύρρον, ὃς τῶν Ἀλεξάνδρου δορυφόρων ἕνα γοῦν ἀεὶ περιέπων καὶ θεραπεύων διατετέλεκε, καὶ νῦν οὐ βοηθῶν τοῖς ἐνταῦθα μᾶλλον Ἕλλησιν ἢ φεύγων τοὺς ἐκεῖ πολεμίους πλανᾶται περὶ τὴν Ἰταλίαν, ἐπαγγελλόμενος ἡμῖν τὴν ἡγεμονίαν ἀπὸ ταύτης τῆς δυνάμεως ἣ μέρος μικρὸν αὐτῷ Μακεδονίας οὐκ ἤρκεσε διαφυλάξαι. μὴ τοῦτον οὖν ἀπαλλάξειν νομίζετε ποιησάμενοι φίλον, ἀλλὰ ἐκείνους ἐπάξεσθαι καταφρονήσαντας ὑμῶν ὡς πᾶσιν εὐκατεργάστων, εἰ Πύρρος ἄπεισι μὴ δοὺς δίκην ὧν ὕβρισεν, ἀλλὰ καὶ προσλαβὼν μισθὸν τό ἐπεγγελάσαι Ῥωμαίοις Ταραντίνους καὶ Σαυνίτας.", "st": "Pyrrh. 19.1"}, {"sp": "N", "t": "τοιαῦτα τοῦ Ἀππίου διαλεχθέντος ὁρμὴ παρέστη πρὸς τὸν πόλεμον αὐτοῖς, καὶ τὸν Κινέαν ἀποπέμπουσιν ἀποκρινάμενοι Πύρρον ἐξελθόντα τῆς Ἰταλίας, οὕτως, εἰ δέοιτο, περὶ φιλίας καὶ συμμαχίας διαλέγεσθαι, μέχρι δὲ οὗ πάρεστιν ἐν ὅπλοις, πολεμήσειν αὐτῷ Ῥωμαίους κατὰ κράτος κἂν μυρίους ἔτι Λαιβίνους τρέψηται μαχόμενος, λέγεται δὲ Κινέαν, ἐν ᾧ ταῦτα ἔπραττεν, ἅμα ποιησάμενον ἔργον καὶ σπουδάσαντα τῶν τε βίων γενέσθαι θεατὴν καὶ τῆς πολιτείας τὴν ἀρετὴν κατανοῆσαι, καὶ διὰ λόγων ἐλθόντα τοῖς ἀρίστοις τά τε ἄλλα τῷ Πύρρῳ φράσαι, καὶ εἰπεῖν ὡς ἡ σύγκλητος αὐτῷ βασιλέων πολλῶν συνέδριον φανείη, περὶ δὲ τοῦ πλήθους δεδιέναι, μὴ πρός τινα φανῶσι Λερναίαν ὕδραν μαχόμενοι· διπλασίους γάρ ἤδη τῷ ὑπάτῳ τῶν παρατεταγμένων πρότερον ἠθροῖσθαι, καὶ πολλάκις εἶναι τοσούτους ἔτι τῶν Ῥωμαίων ὅπλα φέρειν δυναμένους.", "st": "Pyrrh. 19.4"}, {"sp": "N", "t": "ἐκ τούτου πρέσβεις ἀφίκοντο περὶ τῶν αἰχμαλώτων οἱ περὶ Γάιον Φαβρίκιον, οὗ πλεῖστον ἔφη Ῥωμαίους λόγον ἔχειν ὁ Κινέας ὡς ἀνδρὸς ἀγαθοῦ καὶ πολεμικοῦ, πένητος δὲ ἰσχυρῶς τοῦτον οὖν ὁ Πύρρος ἰδίᾳ φιλοφρονούμενος ἔπειθε λαβεῖν χρυσίον, ἐπ’ οὐδενὶ δῆθεν αἰσχρῷ, φιλίας δέ τι καὶ ξενίας ἐπονομάζων τοῦτο σύμβολον. ἀπωσαμένου δὲ τοῦ Φαβρικίου τότε μὲν ἡσύχασε, τῇ δ’ ὑστεραίᾳ βουλόμενος αὐτὸν ἐκπλῆξαι μήπω θεατὴν ἐλέφαντος γεγενημένον, ἐκέλευσε τῶν θηρίων τὸ μέγιστον ἐξόπισθεν αὐτοῖς παραστῆσαι κοινολογουμένοις, αὐλαίαν παρατείναντας. ἐγένετο δὴ ταῦτα· καὶ σημείου δοθέντος ἡ μὲν αὐλαία παρήχθη, τὸ δὲ θηρίον ἄφνω τήν τε προνομαίαν ἀράμενον ὑπερέσχε τῆς κεφαλῆς τοῦ Φαβρικίου καὶ φωνὴν ἀφῆκε φοβερὰν καὶ τραχεῖαν. ὁ δὲ ἠρέμα μεταστραφεὶς καὶ διαμειδιάσας πρὸς τὸν Πύρρον εἶπεν· οὔτε χθὲς με τὸ χρυσίον ἐκίνησεν οὔτε σήμερον τὸ θηρίον ἐν δὲ τῷ δείπνῳ λόγων παντοδαπῶν γενομένων, πλείστων δὲ περὶ τῆς Ἑλλάδος καὶ τῶν φιλοσοφούντων, ἔτυχέ πως ὁ Κινέας ἐπιμνησθεὶς τοῦ Ἐπικούρου, καὶ διῆλθεν ἃ λέγουσι περὶ θεῶν καὶ πολιτείας καὶ τέλους, τὸ μὲν ἐν ἡδονῇ τιθέμενοι, πολιτείαν δὲ φεύγοντες ὡς βλάβην καὶ σύγχυσιν τοῦ μακαρίου, τὸ δὲ θεῖον ἀπωτάτω χάριτος καὶ ὀργῆς καὶ τοῦ μέλειν ἡμῶν εἰς ἀπράγμονα βίον καὶ μεστὸν εὐπαθειῶν ἀποικίζοντες. ἔτι δὲ αὐτοῦ λέγοντος ἀνακραγὼν ὁ Φαβρίκιος, ὦ Ἡράκλεις, εἶπε, Πύρρῳ τὰ δόγματα μέλοι ταῦτα καὶ Σαυνίταις, ἕως πολεμοῦσι πρὸς ἡμᾶς.", "st": "Pyrrh. 20.1"}, {"sp": "N", "t": "οὕτω δὴ θαυμάσας τὸ φρόνημα τοῦ ἀνδρὸς καὶ τὸ ἦθος ὁ Πύρρος ἔτι μᾶλλον ὠρέγετο φιλίαν ἀντὶ πολέμου πρὸς τὴν πόλιν αὐτῷ γενέσθαι· κἀκεῖνον ἰδίᾳ παρεκάλει ποιησάμενον τὰς διαλύσεις ἕπεσθαι καὶ συζῆν μετ’ αὐτοῦ, πρῶτον ὄντα πάντων τῶν ἑταίρων καὶ τῶν στρατηγῶν, ὁ δὲ ἡσυχῇ λέγεται πρὸς αὐτὸν εἰπεῖν, ἀλλ’ οὐδὲ σοὶ τοῦτο, βασιλεῦ, λυσιτελές ἐστιν αὐτοὶ γὰρ οἱ νῦν σε τιμῶντες καὶ θαυμάζοντες, ἂν ἐμοῦ πεῖραν λάβωσιν, ὑπ’ ἐμοῦ μᾶλλον ἐθελήσουσιν ἢ σοῦ βασιλεύεσθαι. τοιοῦτος μὲν ὁ Φαβρίκιος. ὁ δὲ Πύρρος οὐ πρὸς ὀργὴν οὐδὲ τυραννικῶς ἐδέξατο τὸν λόγον, ἀλλὰ καὶ τοῖς φίλοις ἀπήγγειλε τοῦ Φαβρικίου τὴν μεγαλοφροσύνην, καὶ τοὺς αἰχμαλώτους ἐκείνῳ μόνῳ διεπίστευσεν, ὅπως, εἰ μὴ ψηφίσαιτο τὴν εἰρήνην ἡ σύγκλητος, ἀσπασάμενοι τοὺς προσήκοντας καὶ τὰ Κρόνια διεορτάσαντες ἀποπεμφθεῖεν πάλιν πρὸς αὐτόν, καὶ ἀπεπέμφθησαν μετὰ τὴν ἑορτήν, τῷ ὑπολειφθέντι τῆς βουλῆς ζημίαν θάνατον ψηφισαμένης.", "st": "Pyrrh. 20.5"}, {"sp": "N", "t": "μετὰ ταῦτα τὸν Φαβρικίου τὴν ἀρχὴν παραλαβόντος ἧκεν ἀνήρ εἰς τὸ στρατόπεδον πρὸς αὐτὸν ἐπιστολὴν κομίζων, ἣν ἔγραψεν ὁ τοῦ βασιλέως ἰατρός ἐπαγγελλόμενος φαρμάκοις ἀναιρήσειν τὸν Πύρρον, εἰ χάρις αὐτῷ παρ’ ἐκείνων ὁμολογηθείη λύσαντι τὸν πόλεμον ἀκινδύνως, ὁ δὲ Φαβρίκιος δυσχεράνας πρὸς τὴν ἀδικίαν τοῦ ἀνθρώπου, καὶ τὸν συνάρχοντα διαθεὶς ὁμοίως, ἔπεμψε γράμματα πρὸς τὸν Πύρρον κατὰ τάχος φυλάττεσθαι τὴν ἐπιβουλὴν κελεύων. εἶχε δὲ οὕτως τὰ γεγραμμένα· Γάιος Φαβρίκιος καὶ Κόιντος Αἰμίλιος ὕπατοι Ῥωμαίων Πύρρῳ βασιλεῖ χαίρειν. οὔτε φίλων εὐτυχὴς ἔοικας εἶναι κριτὴς οὔτε πολεμίων, γνώσῃ δὲ τὴν πεμφθεῖσαν ἡμῖν ἐπιστολὴν ἀναγνούς, ὅτι χρηστοῖς καὶ δικαίοις ἀνδράσι πολεμεῖς, ἀδίκοις δὲ καὶ κακοῖς πιστεύεις. οὐδὲ γὰρ ταῦτα σῇ χάριτι μηνύομεν, ἀλλ’ ὅπως μὴ τὸ σὸν πάθος ἡμῖν διαβολὴν ἐνέγκῃ καὶ δόλῳ δόξωμεν, ὡς ἀρετῇ μὴ δυνάμενοι, κατεργάσασθαι τὸν πόλεμον. ἐντυχὼν τούτοις τοῖς γράμμασιν ὁ Πύρρος καὶ τὴν ἐπιβουλὴν ἐξελέγξας τὸν μὲν ἰατρὸν ἐκόλασε, Φαβρικίῳ δὲ καὶ Ῥωμαίοις ἀμοιβὴν ἐδωρεῖτο προῖκα τοὺς αἰχμαλώτους, καὶ πάλιν ἔπεμψε τὸν Κινέαν διαπραξόμενον αὐτῷ τὴν εἰρήνην. οἱ δὲ Ῥωμαῖοι, μήτε εἰ χάρις ἐστὶ παρὰ πολεμίου, μήτε εἰ μισθὸς τοῦ μὴ ἀδικηθῆναι, λαβεῖν προῖκα τοὺς ἄνδρας ἀξιώσαντες ἴσους ἀπέλυσαν αὐτῷ Ταραντίνων καὶ Σαυνιτῶν, περὶ δὲ φιλίας καὶ εἰρήνης οὐδὲν εἴων διαλέγεσθαι πρὶν ἀράμενος τὰ ὅπλα καὶ τὸν στρατὸν ἐξ Ἰταλίας αἷς ἦλθε ναυσὶν ἀποπλεύσῃ πάλιν εἰς Ἤπειρον.", "st": "Pyrrh. 21.1"}, {"sp": "N", "t": "ἐκ τούτου μάχης ἄλλης τῶν πραγμάτων αὐτῷ δεομένων ἀναλαβὼν τὴν στρατιὰν ἐχώρει, καὶ περὶ Ἄσκλον πόλιν τοῖς Ῥωμαίοις συνάψας καὶ βιαζόμενος πρὸς χωρία δύσιππα καὶ ποταμὸν ὑλώδη καὶ τραχύν, ἔφοδον τῶν θηρίων οὐ λαβόντων ὥστε προσμῖξαι τῇ φάλαγγι, τραυμάτων πολλῶν γενομένων καὶ νεκρῶν πεσόντων, τότε μὲν διεκρίθη μέχρι νυκτὸς ἀγωνισάμενος. τῇ δ’ ὑστεραίᾳ στρατηγῶν δι’ ὁμαλοῦ τὴν μάχην θέσθαι καὶ τοὺς ἐλέφαντας ἐν τοῖς ὅπλοις γενέσθαι τῶν πολεμίων, προέλαβε τὰς δυσχωρίας φυλακῇ, καὶ πολλὰ καταμίξας ἀκοντίσματα καὶ τοξεύματα τοῖς θηρίοις ἐπῆγε μετὰ ῥώμης καὶ βίας πυκνὴν καὶ συντεταγμένην τὴν δύναμιν. οἱ δὲ Ῥωμαῖοι τὰς διακλίσεις καὶ τὰς ἀντιπαραγωγὰς τὰς πρότερον οὐκ ἔχοντες, ἐξ ἐπιπέδου συνεφέροντο κατὰ στόμα· καὶ σπεύδοντες ὤσασθαι τοὺς ὁπλίτας πρὶν ἐπιβῆναι τὰ θηρία, δεινοὺς περὶ τὰς σαρίσας τῶν ξιφῶν ἀγῶνας εἶχον, ἀφειδοῦντες ἑαυτῶν καὶ τὸ τρῶσαι καὶ καταβαλεῖν ὁρῶντες, τὸ δὲ παθεῖν εἰς οὐδὲν τιθέμενοι. χρόνῳ δὲ πολλῷ λέγεται μὲν ἀρχὴ τροπῆς κατ’ αὐτὸν γενέσθαι τὸν Πύρρον ἐπερείσαντα τοῖς ἀντιτεταγμένοις, τὸ δὲ πλεῖστον ἀλκῇ καὶ βίᾳ τῶν ἐλεφάντων κατειργάσατο, χρήσασθαι τῇ ἀρετῇ πρὸς τὴν μάχην τῶν Ῥωμαίων μὴ δυναμένων, ἀλλ’ οἷον ἐφόδῳ κύματος ἢ σεισμοῦ κατερείποντος οἰομένων δεῖν ἐξίστασθαι, μηδὲ ὑπομένειν ἀπράκτους ἀποθνῄσκειν, ἐν τῷ μηδὲν ὠφελεῖν πάντα πάσχοντας τὰ χαλεπώτατα.", "st": "Pyrrh. 21.5"}, {"sp": "N", "t": "τῆς δὲ φυγῆς οὐ μακρᾶς εἰς τὸ στρατόπεδον γενομένης ἑξακισχιλίους ἀποθανεῖν φησι τῶν Ῥωμαίων Ἱερώνυμος, τῶν δὲ περὶ Πύρρον ἐν τοῖς βασιλικοῖς ὑπομνήμασιν ἀνενεχθῆναι τρισχιλίους πεντακοσίους καὶ πέντε τεθνηκότας. ὁ μέντοι Διονύσιος οὔτε δύο περὶ Ἄσκλον μάχας οὔτε ὁμολογουμένην ἧτταν ἱστορεῖ γενέσθαι Ῥωμαίων, ἅπαξ δὲ μέχρι δυσμῶν ἡλίου μαχεσαμένους μόλις ἀπαλλαγῆναι, τοῦ Πύρρου τρωθέντος ὑσσῷ τὸν βραχίονα καὶ τὴν ἀποσκευὴν ἅμα Δαυνίων διαρπασάντων, ἀποθανεῖν δὲ καὶ Πύρρου καὶ Ῥωμαίων ἄνδρας ὑπὲρ μυρίους πεντακισχιλίους ἑκατέρων.", "st": "Pyrrh. 21.8"}, {"sp": "N", "t": "διελύθησαν δὲ ἀμφότεροι· καὶ λέγεται τὸν Πύρρον εἰπεῖν πρός τινα τῶν συνηδομένων αὐτῷ, ἂν ἔτι μίαν μάχην Ῥωμαίους νικήσωμεν, ἀπολούμεθα παντελῶς. πολὺ μὲν γὰρ ἀπωλώλει μέρος ἧς ἄγων ἧκε δυνάμεως, φίλοι δὲ καὶ στρατηγοὶ πλὴν ὀλίγων ἅπαντες, μεταπέμπεσθαι δὲ οὐκ ἦσαν ἕτεροι, καὶ τοὺς αὐτόθι συμμάχους ἀμβλυτέρους ἑώρα, τοῖς δὲ Ῥωμαίοις ὥσπερ ἐκ πηγῆς οἴκοθεν ἐπιρρεούσης ἀναπληρούμενον εὐπόρως καὶ ταχὺ τὸ στρατόπεδον, καὶ ταῖς ἥτταις οὐκ ἀποβάλλοντας τὸ θαρρεῖν, ἀλλὰ καὶ ῥώμην καὶ φιλονεικίαν ὑπ’ ὀργῆς ἐπὶ τὸν πόλεμον προσλαμβάνοντας.", "st": "Pyrrh. 21.10"}, {"sp": "N", "t": "ἐν τοιαύταις δὲ ὢν ἀπορίαις εἰς ἐλπίδας αὖ πάλιν καινὰς ἐνέπεσε καὶ πράγματα διχοστασίαν ἔχοντα τῆς γνώμης, ἅμα γάρ ἧκον ἐκ μὲν Σικελίας ἄνδρες Ἀκράγαντα καὶ Συρακούσας καὶ Λεοντίνους ἐγχειρίζοντες αὐτῷ, καὶ δεόμενοι Καρχηδονίους τε συνεκβαλεῖν καὶ τῶν τυράννων ἀπαλλάξαι τὴν νῆσον, ἐκ δὲ τῆς Ἑλλάδος ἀγγέλλοντες ὡς Πτολεμαῖος ὁ Κεραυνὸς ἀπόλωλε συμπεσὼν Γαλάταις μετὰ τῆς δυνάμεως, καὶ νῦν ἂν ἐν καιρῷ μάλιστα δεομένοις βασιλέως Μακεδόσι παραγένοιτο. πολλὰ δὴ τὴν τύχην μεμψάμενος ὅτι πράξεων μεγάλων ὑποθέσεις εἰς ἕνα καιρὸν αὐτῷ συνήνεγκε, καὶ νομίζων ὡς ἀμφοτέρων ὑπαρχόντων ἀπολλύναι θάτερον, διηνέχθη τοῖς λογισμοῖς πολὺν χρόνον. εἶτα τοῖς Σικελικοῖς μειζόνων ὑποκεῖσθαι πραγμάτων δοκούντων, Λιβύης ἐγγὺς εἶναι δοκούσης, ἐπὶ ταῦτα τρέψας Κινέαν μὲν εὐθὺς ἐξέπεμψε προδιαλεξόμενον, ὥσπερ εἰώθει, ταῖς πόλεσιν, αὐτὸς δὲ τοῖς Ταραντίνοις δυσανασχετοῦσιν ἐμβαλὼν φρουράν, καὶ ἀξιοῦσιν ἢ παρέχειν ἐφ’· οἷς ἧκε, συμπολεμοῦντα Ῥωμαίοις, ἢ τὴν χώραν προέμενον αὐτῶν ἀπολιπεῖν τὴν πόλιν οἵαν παρέλαβε, μηδὲν ἐπιεικὲς ἀποκρινάμενος, ἀλλὰ προστάξας ἡσυχίαν ἄγειν καὶ περιμένειν τὸν ἑαυτοῦ καιρόν, ἐξέπλευσεν.", "st": "Pyrrh. 22.1"}, {"sp": "N", "t": "ἁψαμένῳ δὲ αὐτῷ Σικελίας ἃ μὲν ἤλπισεν εὐθὺς ἀπήντα βέβαια, καὶ παρεῖχον αἱ πόλεις ἑαυτὰς προθύμως, τῶν δὲ ἀγῶνος καὶ βίας δεηθέντων οὐδὲν ἀντεῖχε τὸ πρῶτον, ἀλλὰ τρισμυρίοις πεζοῖς καὶ δισχιλίοις πεντακοσίοις ἱππεῦσι καὶ διακοσίαις ναυσὶν ἐπιών τούς τε Φοίνικας ἐξῄρει καὶ κατεστρέφετο τὴν ἐπικράτειαν αὐτῶν, τοῦ δ’ Ἔρυκος ἐχυρωτάτου τῶν χωρίων ὄντος καὶ πολλοὺς ἀμυνομένους ἔχοντος ἔγνω βιάζεσθαι πρὸς τὰ τείχη. καὶ τῆς στρατιᾶς γενομένης ἑτοίμης ἐνεδύσατο τὴν πανοπλίαν, καὶ προελθὼν εὔξατο τῷ Ἡρακλεῖ ποιήσειν ἀγῶνα καὶ θυσίαν ἀριστεῖον, ἂν τοῦ γένους καὶ τῶν ὑπαρχόντων ἄξιον ἀγωνιστὴν αὑτὸν ἀποδείξῃ τοῖς Σικελίαν οἰκοῦσιν Ἕλλησι· τῇ δὲ σάλπιγγι σημήνας καὶ τοῖς βέλεσι τοὺς βαρβάρους ἀνασκεδάσας καὶ τὰς κλίμακας προσαγαγών πρῶτος ἐπέβη τοῦ τείχους. ἀντιστάντων δὲ πολλῶν ἀμυνόμενος τοὺς μὲν ἐξέωσε τοῦ τείχους ἐπ’ ἀμφότερα καὶ κατέβαλε, πλείστους δὲ περὶ αὑτὸν τῷ ξίφει χρώμενος ἐσώρευσε νεκρούς, ἔπαθε δὲ αὐτὸς οὐδέν, ἀλλὰ καὶ προσιδεῖν δεινὸς ἐφάνη τοῖς πολεμίοις, καὶ τὸν Ὅμηρον ἔδειξεν ὀρθῶς καὶ μετὰ ἐμπειρίας ἀποφαίνοντα τῶν ἀρετῶν μόνην τὴν ἀνδρείαν φορὰς πολλάκις ἐνθουσιώδεις καὶ μανικὰς φερομένην. ἁλούσης δὲ τῆς πόλεως ἔθυσέ τε τῷ θεῷ μεγαλοπρεπῶς καὶ θέας ἀγώνων παντοδαπῶν παρέσχε.", "st": "Pyrrh. 22.4"}, {"sp": "N", "t": "τῶν δὲ περὶ Μεσσήνην βαρβάρων, Μαμερτίνων δὲ καλουμένων, πολλὰ τοῖς Ἕλλησιν ἐνοχλούντων, ἐνίους δὲ καὶ φόρου πεποιημένων ὑποτελεῖς, πολλῶν δὲ καὶ μαχίμων ὄντων, διὸ καὶ προσηγορεύθησαν Ἀρήιοι γλώσσῃ τῇ Λατίνων, τοὺς μὲν φορολόγους συλλαβὼν ἀπέκτεινεν, αὐτοὺς δὲ νικήσας μάχῃ πολλὰ τῶν φρουρίων ἐξέκοψε. Καρχηδονίοις δὲ συμβατικῶς ἔχουσι, καὶ χρήματα βουλομένοις τελεῖν, εἰ γένοιτο φιλία, καὶ ναῦς ἀποστέλλειν, ἀπεκρίνατο πλειόνων ἐφιέμενος μίαν εἶναι διάλυσιν καὶ φιλίαν πρὸς αὐτούς, εἰ πᾶσαν ἐκλιπόντες Σικελίαν ὅρῳ χρῷντο τῇ Λιβυκῇ θαλάσσῃ πρὸς τοὺς Ἕλληνας. εὐτυχίᾳ δὲ καὶ ῥώμῃ τῶν παρόντων ἐπαιρόμενος, καὶ διώκων τὰς ἐλπίδας ἐφ’ αἷς ἀπ’ ἀρχῆς ἔπλευσε, πρώτης δὲ Λιβύης ἐφιέμενος καὶ ναῦς ἔχων πολλὰς πληρωμάτων ἐπιδεεῖς ἤγειρεν ἐρέτας, οὐκ ἐπιεικῶς ἐντυγχάνων οὐδὲ πράως ταῖς πόλεσιν, ἀλλὰ δεσποτικῶς καὶ πρὸς ὀργὴν βιαζόμενος καὶ κολάζων, οὐκ εὐθὺς ὢν οὐδὲ ἐν ἀρχῇ τοιοῦτος, ἀλλὰ καὶ μᾶλλον ἑτέρων τῷ πρὸς χάριν ὁμιλεῖν καὶ πάντα πιστεύειν καὶ μηδὲν ἐνοχλεῖν ὑπαγόμενος, εἶτα γινόμενος ἐκ δημαγωγοῦ τύραννος ἀχαριστίας τῇ χαλεπότητι καὶ ἀπιστίας προσωφλίσκανε δόξαν.", "st": "Pyrrh. 23.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ ταῦτα μὲν ὡς ἀναγκαῖα συνεχώρουν, καίπερ δυσφοροῦντες· ἐπεὶ δὲ Θοίνωνα καὶ Σωσίστρατον, ἄνδρας ἡγεμονικοὺς ἐν Συρακούσαις, οἳ πρῶτοι μὲν αὐτὸν ἐλθεῖν ἔπεισαν εἰς Σικελίαν, ἐλθόντι δὲ τὴν πόλιν εὐθὺς ἐνεχείρισαν καὶ πλεῖστα συγκατειργάσαντο τῶν Σικελικῶν, μήτε ἄγειν σὺν αὑτῷ μήτε ἀπολείπειν βουλόμενος ἐν ὑποψίαις εἶχε, καὶ Σωσίστρατος μὲν ἀπέστη φοβηθείς, Θοίνωνα δὲ τὰ αὐτὰ φρονεῖν αἰτιασάμενος ἀπέκτεινεν, οὐ κατὰ μικρὸν οὐδὲ καθ’ ἓν αὐτῷ μεθίστατο τῶν πραγμάτων, ἀλλὰ δεινοῦ τινος μίσους ἐγγενομένου ταῖς πόλεσι πρὸς αὐτὸν αἱ μὲν προσετίθεντο Καρχηδονίοις, αἱ δὲ ἐπήγοντο Μαμερτίνους. ἀποστάσεις δὲ ὁρῶν ἅπαντα καὶ νεωτερισμοὺς καὶ σύστασιν ἰσχυρὰν ἐφ’ αὑτόν, ἐδέξατο γράμματα Σαυνιτῶν καὶ Ταραντίνων μόλις ἀντεχόντων ταῖς πόλεσιν αὐταῖς πρὸς τὸν πόλεμον, εἰργομένων δὲ τῆς χώρας ἁπάσης καὶ δεομένων βοηθεῖν. τοῦτο δὲ ἦν εὐπρέπεια μὴ φυγὴν εἶναι μηδὲ ἀπόγνωσιν τὸν ἀπόπλουν τῶν αὐτόθι πραγμάτων τὸ δὲ ἀληθὲς οὐ δυνάμενος κρατεῖν Σικελίας ὥσπερ νεὼς ταραχθείσης, ἀλλ’ ἔκβασιν ζητῶν, αὖθις ἔρριψεν ἑαυτὸν εἰς Ἰταλίαν. λέγεται δ’ ἀπαλλαττόμενος ἤδη πρὸς τὴν νῆσον ἀπιδὼν εἰπεῖν τοῖς περὶ αὐτὸν οἵαν ἀπολείπομεν, ὦ φίλοι, Καρχηδονίοις καὶ Ῥωμαίοις παλαίστραν. καὶ τοῦτο μέν, ὥσπερ εἰκάσθη, μετ’ οὐ πολὺν χρόνον ἐγένετο.", "st": "Pyrrh. 23.4"}, {"sp": "N", "t": "τῶν δὲ βαρβάρων συστάντων ἐπ’ αὐτὸν ἀποπλέοντα, Καρχηδονίοις μὲν ἐν τῷ πορθμῷ ναυμαχήσας ἀπέβαλε τῶν νεῶν πολλάς, ταῖς δ’ ἄλλαις κατέφυγε πρὸς τὴν Ἰταλίαν, Μαμερτῖνοι δὲ μυρίων οὐκ ἐλάττους προδιαβάντες ἀντιτάξασθαι μὲν ἐφοβήθησαν, ἐν δὲ ταῖς δυσχωρίαις ἐπιτιθέμενοι καὶ προσπίπτοντες ἅπαν τὸ στράτευμα συνετάραξαν. ἔπεσε δὲ δύο θηρία καὶ συχνοὶ τῶν ὀπισθοφυλακούντων ἀπέθνῃσκον. αὐτὸς οὖν ἀπὸ τοῦ στόματος παρελάσας ἠμύνετο καὶ διεκινδύνευε πρὸς ἄνδρας ἠσκημένους μάχεσθαι καὶ θυμοειδεῖς. πληγεὶς δὲ τὴν κεφαλὴν ξίφει καὶ μικρὸν ἐκ τῶν μαχομένων ἀποστὰς ἔτι μᾶλλον ἐπῆρε τοὺς πολεμίους. εἷς δὲ καὶ πολὺ πρὸ τῶν ἄλλων ἐπιδραμών, ἀνήρ τῷ τε σώματι μέγας καὶ τοῖς ὅπλοις λαμπρός, ἐχρῆτο τῇ φωνῇ θρασυτέρᾳ καὶ προελθεῖν ἐκέλευεν αὐτόν, εἰ ζῇ. παροξυνθεὶς δὲ ὁ Πύρρος ἐπέστρεψε βίᾳ τῶν ὑπασπιστῶν, καὶ μετ’ ὀργῆς αἵματι πεφυρμένος καὶ δεινὸς ὀφθῆναι τὸ πρόσωπον ὠσάμενος δι’ αὐτῶν καὶ φθάσας τὸν βάρβαρον ἔπληξε κατὰ τῆς κεφαλῆς τῷ ξίφει πληγὴν ῥώμῃ τε τῆς χειρὸς ἅμα καὶ βαφῆς ἀρετῇ τοῦ σιδήρου μέχρι τῶν κάτω διαδραμοῦσαν, ὥστε ἑνὶ χρόνῳ περιπεσεῖν ἑκατέρωσε τὰ μέρη τοῦ σώματος διχοτομηθέντος. τοῦτο τοὺς βαρβάρους ἐπέσχε τοῦ πρόσω χωρεῖν, ὥς τινα τῶν κρειττόνων θαυμάσαντας καὶ καταπλαγέντας τὸν Πύρρον. ὁ δὲ τὴν ἄλλην ὁδὸν ἀδεῶς διεξελθὼν ἧκεν εἷς Τάραντα, δισμυρίους πεζοὺς καὶ τρισχιλίους ἱππεῖς κομίζων. ἀναλαβὼν δὲ τῶν Ταραντίνων τοὺς κρατίστους, εὐθὺς ἐπὶ Ῥωμαίους ἦγεν ἐν τῇ Σαυνίτιδι στρατοπεδεύοντας.", "st": "Pyrrh. 24.1"}, {"sp": "N", "t": "τῶν δὲ Σαυνιτῶν τά τε πράγματα διέφθαρτο, καὶ τοῦ φρονήματος ὑφεῖντο, κεκρατημένοι μάχαις πολλαῖς ὑπὸ τῶν Ῥωμαίων. ἐνῆν δέ τι καὶ πρὸς τὸν Πύρρον ὀργῆς διὰ τὸν εἰς Σικελίαν πλοῦν· ὅθεν οὐ πολλοὶ τούτων αὐτῷ συνῆλθον. πάντας δὲ νείμας δίχα τοὺς μὲν εἰς τὴν Λευκανίαν ἔπεμψεν ἀντιληψομένους τοῦ ἑτέρου τῶν ὑπάτων, ὡς μὴ βοηθοίη, τοὺς δὲ ἦγεν αὐτὸς ἐπὶ Μάνιον Κούριον περὶ πόλιν Βενεουεντὸν ἱδρυμένον ἐν ἀσφαλεῖ καὶ περιμένοντα τὴν ἐκ τῆς Λευκανίας βοήθειαν· ἔστι δ’ ὅτε καὶ μάντεων αὐτὸν οἰωνοῖς καὶ ἱεροῖς ἀποτρεπόντων ἡσύχαζε, σπεύδων οὖν ὁ Πύρρος ἐπιθέσθαι τούτοις, πρὶν ἐκείνους ἐπελθεῖν, ἄνδρας τε τοὺς κρατίστους καὶ τῶν θηρίων τὰ μαχιμώτατα λαβὼν νυκτὸς ὥρμησεν ἐπὶ τὸ στρατόπεδον. περιιόντι δὲ αὐτῷ μακρὰν καὶ δασεῖαν ὕλαις ὁδὸν οὐκ ἀντέσχε τὰ φῶτα, καὶ πλάναι τοῖς στρατιώταις συνέτυχον· καὶ περὶ ταῦτα γινομένης διατριβῆς ἥ τε νὺξ ἐπέλιπε καὶ καταφανὴς ἦν ἅμ’ ἡμέρᾳ τοῖς πολεμίοις ἐπερχόμενος ἀπὸ τῶν ἄκρων, ὥστε θόρυβον πολὺν καὶ κίνησιν παρασχεῖν.", "st": "Pyrrh. 25.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῶν ἱερῶν τῷ Μανίῳ γενομένων, καὶ τοῦ καιροῦ βοηθεῖν ἀναγκάζοντος, ἐξελθὼν ἐνέβαλε τοῖς πρώτοις καὶ τρεψάμενος ἐφόβησε πάντας, ὥστε καὶ πεσεῖν οὐκ ὀλίγους καὶ τῶν ἐλεφάντων τινὰς ἁλῶναι καταλειφθέντας. αὕτη τὸν Μάνιον ἡ νίκη κατήγαγε μαχούμενον εἰς τὸ πεδίον· καὶ συμβαλὼν ἐκ προδήλου τὸ μὲν ἐτρέψατο τῶν πολεμίων, ἔστι δ’ ᾗ βιασθεὶς ὑπὸ τῶν θηρίων καὶ συσταλεὶς πρὸς τὸ στρατόπεδον τοὺς φύλακας ἐκάλει συχνοὺς ἐφεστῶτας τῷ χάρακι μετὰ τῶν ὅπλων καὶ ἀκμῆτας. οἱ δὲ ἐπιφανέντες ἐκ τόπων ὀχυρῶν καὶ τὰ θηρία βάλλοντες ἠνάγκασαν ἀποστρέφεσθαι καὶ φυγῇ χωροῦντα διὰ τῶν συμμάχων ὀπίσω ταραχὴν ἀπεργάσασθαι καὶ σύγχυσιν, ἣ τὸ νίκημα παρέδωκε τοῖς Ῥωμαίοις, ἅμα δὲ καὶ τὸ κράτος τῆς ἡγεμονίας, καὶ γάρ φρόνημα καὶ δύναμιν καὶ δόξαν ὡς ἄμαχοι προσλαβόντες ἐκ τῆς ἀρετῆς ἐκείνης καὶ τῶν ἀγώνων Ἰταλίαν μὲν εὐθύς, ὀλίγῳ δὲ ὕστερον Σικελίαν κατέσχον.", "st": "Pyrrh. 25.4"}, {"sp": "N", "t": "οὕτω μὲν ἐξέπεσε τῶν Ἰταλικῶν καὶ Σικελικῶν ὁ Πύρρος ἐλπίδων, ἑξαετῆ χρόνον ἀναλώσας περὶ τοὺς ἐκεῖ πολέμους, καὶ τοῖς πράγμασιν ἐλαττωθείς, τὸ δὲ ἀνδρεῖον ἀνίκητον ἐν ταῖς ἥτταις διαφυλάξας· καὶ νομισθεὶς ἐμπειρίᾳ μὲν πολεμικῇ καὶ χειρὶ καὶ τόλμῃ πολὺ πρῶτος εἶναι τῶν καθ’ αὑτὸν βασιλέων, ἃ δὲ ταῖς πράξεσιν ἐκτᾶτο ταῖς ἐλπίσιν ἀπολλύναι, δι’ ἔρωτα τῶν ἀπόντων οὐδὲν εἷς ὃ δεῖ θέσθαι τῶν ὑπαρχόντων φθάσας.", "st": "Pyrrh. 26.1"}, {"sp": "N", "t": "ὅθεν ἀπείκαζεν αὑτὸν ὁ Ἀντίγονος κυβευτῇ πολλὰ βάλλοντι καὶ καλά, χρῆσθαι δὲ οὐκ ἐπισταμένῳ τοῖς πεσοῦσι, κομίσας δὲ εἷς Ἤπειρον ὀκτακισχιλίους πεζοὺς καὶ πεντακοσίους ἱππεῖς, χρήματα δὴ οὐκ ἔχων ἐζήτει πόλεμον ᾧ θρέψει τὸ στράτευμα, καὶ τινων Γαλατῶν αὐτῷ προσγενομένων ἐνέβαλεν εἷς Μακεδονίαν Ἀντιγόνου τοῦ Δημητρίου βασιλεύοντος ὡς ἁρπαγῇ καὶ λεηλασίᾳ χρησόμενος. ἐπεὶ δὲ καὶ πόλεις ἐλάμβανε συχνὰς καὶ στρατιῶται δισχίλιοι μετέστησαν ὡς αὐτόν, ἐλπίσας τι πλέον ὥρμησεν ἐπὶ τὸν Ἀντίγονον καὶ περὶ τὰ Στενὰ προσπεσὼν συνετάραξε τὴν στρατιὰν ἅπασαν, οἱ δὲ ἐπὶ τῆς οὐραγίας τοῦ Ἀντιγόνου τεταγμένοι Γαλάται, συχνοὶ τὸ πλῆθος ὄντες, ὑπέστησαν εὐρώστως· καὶ καρτερᾶς μάχης γενομένης τούτων μὲν οἱ πλεῖστοι κατεκόπησαν, οἱ δὲ τῶν ἐλεφάντων ἡγεμόνες ἐγκαταλαμβανόμενοι παρέδωκαν ἑαυτοὺς καὶ τὰ θηρία πάντα. προσλαβὼν δὲ ὁ Πύρρος τηλικαῦτα, καὶ τῇ τύχῃ μᾶλλον ἢ τοῖς λογισμοῖς χρώμενος, ἐπῆγε τῇ φάλαγγι τῶν Μακεδόνων ἀναπεπλησμένῃ ταραχῆς καὶ φόβου διὰ τὴν ἧτταν. ὅθεν ἐμβολῆς μὲν ἔσχοντο καὶ μάχης πρὸς αὐτόν, τὴν δὲ δεξιὰν προτείνων καὶ στρατηγοὺς καὶ ταξιάρχους ἀνακαλούμενος, ἅπαντας ὁμαλῶς ἀπέστησε τοὺς πεζοὺς τὸν Ἀντιγόνου. κἀκεῖνος μὲν ὑποφεύγων ἅμα τῶν ἱππέων ὀλίγοις τῶν παραλίων τινὰς πόλεων κατέσχεν, ὁ δὲ Πύρρος ἐν εὐτυχήμασι τοσούτοις μέγιστον αὐτῷ πρὸς δόξαν οἰόμενος διαπεπρᾶχθαι τὸ περὶ τοὺς Γαλάτας, τὰ κάλλιστα καὶ λαμπρότατα τῶν λαφύρων ἀνέθηκεν εἷς τὸ ἱερὸν τῆς Ἰτωνίδος ’ Ἀθηνᾶς, τόδε τὸ ἐλεγεῖον ἐπιγράψας", "st": "Pyrrh. 26.2"}, {"sp": "N", "t": "τοὺς θυρεοὺς ὁ Μολοσσὸς Ἰτωνίδι δῶρον Ἀθάνᾳ<br>Πύρρος ἀπὸ θρασέων ἐκρέμασεν Γαλατᾶν,<br>πάντα τὸν Ἀντιγόνου καθελὼν στρατὸν οὐ μέγα<br>θαῦμα·<br>αἰχμηταὶ καὶ νῦν καὶ πάρος Αἰακίδαι.", "st": "Pyrrh. 26.2b"}, {"sp": "N", "t": "μετὰ τὴν μάχην δὲ εὐθὺς ἀνελάμβανε τὰς πόλεις, τῶν δὲ Αἰγαίων κρατήσας τά τε ἄλλα χαλεπῶς ἐχρήσατο τοῖς ἀνθρώποις, καὶ φρουρὰν Γαλατικὴν ἐν τῇ πόλει κατέλιπε τῶν μετ’ αὐτοῦ στρατευομένων, οἱ δὲ Γαλάται γένος ἀπληστότατον χρημάτων ὄντες ἐπέθεντο τῶν βασιλέων αὐτόθι κεκηδευμένων τοὺς τάφους ὀρύττειν, καὶ τὰ μὲν χρήματα διήρπασαν, τὰ δὲ ὀστᾶ πρὸς ὕβριν διέρριψαν. τοῦτο κούφως ἔδοξε καὶ ὀλιγώρως ἐνεγκεῖν ὁ Πύρρος, ἢ δι’ ἀσχολίας τινὰς ὑπερθέμενος ἢ παρεὶς ὅλως διὰ φόβον τὸ κολάσαι τοὺς βαρβάρους· ὅθεν ἤκουσε κακῶς ὑπὸ τῶν Μακεδόνων. οὔπω δὲ τῶν πραγμάτων αὐτῷ βεβαιότητα καὶ σύστασιν ἐχόντων μόνιμον, ᾐωρεῖτο τῇ γνώμῃ πάλιν πρὸς ἑτέρας ἐλπίδας, καὶ τὸν μὲν Ἀντίγονον ἐφυβρίζων ἀναίσχυντον ἐκάλει μὴ λαμβάνοντα θοἱμάτιον, ἀλλ’ ἔτι τὴν πορφύραν φοροῦντα. Κλεωνύμου δὲ τοῦ Σπαρτιάτου παραγενομένου καὶ καλοῦντος αὑτὸν ἐπὶ τὴν Λακεδαίμονα προθύμως ὑπήκουσεν.", "st": "Pyrrh. 26.6"}, {"sp": "N", "t": "ὁ δὲ Κλεώνυμος ἦν μὲν γένους βασιλικοῦ, δοκῶν δὲ βίαιος εἶναι καὶ μοναρχικὸς οὔτ’ εὔνοιαν οὔτε πίστιν εἶχεν, ἀλλ’ Ἄρευς ἐβασίλευε. καὶ τοῦτο μὲν ἓν ἦν κοινὸν ἔγκλημα καὶ πρεσβύτερον αὐτῷ πρὸς τοὺς πολίτας· γυναῖκα δὲ καλὴν καὶ γένους βασιλικοῦ Χιλωνίδα τὴν Λεωτυχίδου πρεσβύτερος ὢν ἔγημεν ὁ Κλεώνυμος. ἢ δὲ Ἀκροτάτῳ τῷ Ἄρεως ἐπιμανεῖσα, μειρακίῳ καθ’ ὥραν ἀκμάζοντι, λυπηρὸν ἐρῶντι τῷ Κλεωνύμῳ καὶ ἄδοξον ὁμοῦ παρεῖχε τὸν γάμον οὐδένα γὰρ ἐλάνθανε Σπαρτιατῶν καταφρονούμενος ὑπὸ τῆς γυναικός. οὕτω δὲ τῶν κατ’ οἶκον ἀνιαρῶν τοῖς πολιτικοῖς προσγενομένων ὑπ’ ὀργῆς καὶ βαρυθυμίας ἐπῆγε τῇ Σπάρτῃ τὸν Πύρρον, ἔχοντα δισμυρίους καὶ πεντακισχιλίους πεζούς, δισχιλίους δ’ ἱππεῖς, ἐλέφαντας δὲ εἰκοσιτέσσαρας, ὥστε τῷ μεγέθει τῆς παρασκευῆς εὐθὺς εἶναι κατάδηλον οὐ Κλεωνύμῳ τὴν Σπάρτην, ἀλλὰ τὴν Πελοπόννησον ἑαυτῷ κτώμενον, ἐπεὶ τῷ γε λόγῳ καὶ πρὸς αὐτοὺς ἔξαρνος ἦν τοὺς Λακεδαιμονίους πρεσβεύσαντας εἷς Μεγάλην πόλιν. ἔφη γάρ ἐλευθερώσων τὰς ὑπ’ Ἀντιγόνῳ πόλεις ἀφῖχθαι, καὶ νὴ Δία τοὺς νεωτέρους παῖδας εἷς Σπάρτην, εἰ μή τι κωλύει, πέμψων ἐντραφησομένους τοῖς Λακωνικοῖς ἔθεσιν, ὡς τούτῳ πλέον ἔχοιεν ἤδη τῶν πάντων βασιλέων, ταῦτα πλαττόμενος καὶ παράγων τοὺς ἐντυγχάνοντας αὐτῷ καθ’ ὁδόν, ὡς πρῶτον ἥψατο τῆς Λακωνικῆς ἁρπαγὴν ἐποιεῖτο καὶ λεηλασίαν· ἐγκαλούντων δὲ τῶν πρέσβεων, ὅτι μὴ καταγγείλας πόλεμον ἐξενήνοχε πρὸς αὐτούς, ἀλλ’ οὐδ’ ὑμᾶς, ἔφη· τοὺς Σπαρτιάτας ἴσμεν ὅ τι ἂν μέλλητε ποιεῖν ἑτέροις προλέγοντας εἷς δὲ τῶν παρόντων, ὄνομα Μανδροκλείδας, εἶπε τῇ φωνῇ λακωνίζων αἰ μὲν ἐσσὶ τύ γε θεός, οὐδὲν μὴ πάθωμεν οὐ γὰρ ἀδικεῦμεν αἰ δ’ ἄνθρωπος, ἔσσεται καὶ τεῦ κάρρων ἄλλος.", "st": "Pyrrh. 26.8"}, {"sp": "N", "t": "ἐκ τούτου κατέβαινεν ἐπὶ τὴν Λακεδαίμονα· καὶ τοῦ Κλεωνύμου κελεύοντος ἕξ ἐφόδου προσβαλεῖν φοβηθεὶς ὁ Πύρρος, ὡς λέγεται, μὴ διαρπάσωσιν οἱ στρατιῶται τὴν πόλιν ἐν νυκτὶ προσπεσόντες, ἐπέσχεν, εἰπὼν ὅτι ταὐτὸ ποιήσουσι μεθ’ ἡμέραν. αὐτοί τε γάρ ἦσαν ὀλίγοι καὶ ἀπαράσκευοι διὰ τὸ αἰφνίδιον, ὅ τε Ἄρευς οὐκ ἐτύγχανε παρών, ἀλλ’ ἐν Κρήτῃ Γορτυνίοις πολεμουμένοις βοηθῶν· καὶ τοῦτο δὴ μάλιστα τὴν πόλιν ἔσωσε δι’ ἐρημίαν καὶ ἀσθένειαν καταφρονηθεῖσαν. ὁ μὲν γάρ Πύρρος οὐδένα μαχεῖσθαι νομίζων κατηυλίσατο, τοῦ δὲ Κλεωνύμου τὴν οἰκίαν οἵ τε φίλοι καὶ εἵλωτες οὕτως ἐκόσμησαν καὶ παρεσκεύασαν ὡς δειπνήσοντος τοῦ Πύρρου παρ’ αὐτῷ.", "st": "Pyrrh. 27.1"}, {"sp": "N", "t": "γενομένης δὲ νυκτὸς οἱ Λακεδαιμόνιοι πρῶτον μὲν ἐβουλεύσαντο τὰς γυναῖκας εἰς Κρήτην ἀποστέλλειν, αἱ δὲ ἀντέστησαν. Ἀρχιδαμία δὲ καὶ ξίφος ἔχουσα πρὸς τὴν γερουσίαν ἦλθεν ἐγκαλοῦσα τοῖς ἀνδράσιν ὑπὲρ τῶν γυναικῶν, εἰ ζῆν αὑτὰς ἀξιοῦσι τῆς Σπάρτης ἀπολομένης. ἔπειτα τῷ στρατοπέδῳ τῶν πολεμίων παράλληλον ἔγνωσαν ἐμβαλόντες τάφρον ἔνθεν καὶ ἔνθεν αὐτῆς στῆσαι τὰς ἁμάξας, μέχρι τοῦ μέσου τῶν τροχῶν καταχώσαντες, ὅπως ἕδραν ἔχουσαι δυσεκβίαστον ἐμποδὼν ὦσι τοῖς θηρίοις. ἀρχομένοις δὲ ταῦτα πράττειν ἧκον αὐτοῖς τῶν παρθένων καὶ γυναικῶν αἱ μὲν ἐν ἱματίοις, καταζωσάμεναι τοὺς χιτωνίσκους, αἱ δὲ μονοχίτωνες, συνεργασόμεναι τοῖς πρεσβυτέροις. τοὺς δὲ μάχεσθαι μέλλοντας ἐκέλευον ἡσυχάζειν, καὶ λαβοῦσαι μέτρον αὐταὶ καθ’ αὑτὰς ἐξειργάσαντο τῆς τάφρου τὸ τρίτον μέρος, ἦν δὲ τὸ μὲν πλάτος αὐτῆς πήχεων ἕξ, τὸ δὲ βάθος τεττάρων, τὸ δὲ μῆκος ὀκτάπλεθρον, ὡς ἱστορεῖ Φύλαρχος, ὡς δ’ Ἱερώνυμος, ἔλαττον. ἅμα δ’ ἡμέρᾳ κινουμένων τῶν πολεμίων τὰ ὅπλα τοῖς νέοις ὀρέγουσαι καὶ παραδιδοῦσαι τὴν τάφρον ἀμύνειν καὶ φυλάττειν ἐκέλευον, ὡς ἡδὺ μὲν νικᾶν ἐν ὀφθαλμοῖς τῆς πατρίδος, εὐκλεὲς δὲ θνῄσκειν ἐν χερσὶ μητέρων καὶ γυναικῶν ἀξίως τῆς Σπάρτης πεσόντας. ἡ δὲ Χιλωνίς, ἐκποδὼν οὖσα καθ’ ἑαυτὴν, βρόχον εἶχεν ἐνημμένον, ὅπως ἐπὶ τῷ Κλεωνύμῳ μὴ γένοιτο τῆς πόλεως ἁλούσης.", "st": "Pyrrh. 27.3"}, {"sp": "N", "t": "αὐτὸς μὲν οὖν ὁ Πύρρος ἐβιάζετο κατὰ στόμα τοῖς ὁπλίταις πρὸς ἀσπίδας πολλὰς τῶν Σπαρτιατῶν ἀντιπαρατεταγμένας, καὶ τάφρον οὐ περατὴν οὐδὲ βάσιν ἀσφαλῆ τοῖς μαχομένοις παρέχουσαν ὑπὸ χαυνότητος. ὁ δὲ παῖς Πτολεμαῖος, ἔχων δισχιλίους Γαλάτας καὶ Χαόνων λογάδας, ἐξελίξας τὴν τάφρον ἐπειρᾶτο κατὰ τὰς ἁμάξας ὑπερβαίνειν. αἱ δὲ ὑπὸ βάθους καὶ πυκνότητος οὐ μόνον τούτοις τὴν ἔφοδον, ἀλλὰ καὶ τοῖς Λακεδαιμονίοις δύσεργον ἐποίουν τὴν βοήθειαν. ἀνασπώντων δὲ τῶν Γαλατῶν τοὺς τροχοὺς καὶ ὑποσυρόντων τὰς ἁμάξας εἰς τὸν ποταμόν, κατιδὼν τὸν κίνδυνον ὁ νεανίας Ἀκρότατος καὶ τὴν πόλιν διαδραμὼν μετὰ τριακοσίων περιῆλθε τὸν Πτολεμαῖον, οὐ συνορώμενος ὑπ’· αὑτοῦ διά τινας συγκλινίας, ἕως προσέβαλε τοῖς ἐσχάτοις καὶ μεταβαλόντας ἠνάγκασε μάχεσθαι πρὸς ἑαυτόν, ὠθουμένους ὑπ’ ἀλλήλων εἴς τε τὴν τάφρον καὶ περὶ ταῖς ἁμάξαις πίπτοντας, ἄχρι οὗ φόνῳ πολλῷ μόλις ἀνεκόπησαν. ἐθεῶντο δὲ οἵ τε πρεσβύτεροι καὶ τῶν γυναικῶν τὸ πλῆθος ἀριστεύοντα τὸν Ἀκρότατον. ἐπεὶ δὲ ἀπῄει πάλιν διὰ τῆς πόλεως ἐπὶ τὴν αὑτοῦ τάξιν αἵματος κατάπλεως καὶ γαῦρος, ὑπὸ τῆς νίκης ἐπηρμένος, καὶ μείζων ἔδοξε γεγονέναι καὶ καλλίων ταῖς Λακαίναις, καὶ τὴν Χιλωνίδα τοῦ ἔρωτος ἐζήλουν. τῶν δὲ πρεσβυτέρων τινὲς ἐπηκολούθουν βοῶντες· οἶχε, Ἀκρότατε, καὶ οἶφε τὰν Χιλωνίδα· μόνον παῖδας ἀγαθοὺς τᾷ Σπάρτᾳ ποίει.", "st": "Pyrrh. 28.1"}, {"sp": "N", "t": "κατὰ δὲ τὸν Πύρρον αὐτὸν ἰσχυρᾶς μάχης συνεστώσης ἄλλοι τε λαμπρῶς ἠγωνίζοντο, κία Φύλλιος ἐπὶ πλεῖστον ἀντισχὼν καὶ πλείστους ἀποκτείνας τῶν βιαζομένων, ὡς ᾔσθετο τραυμάτων πλήθει παραλυόμενον ἑαυτόν, ἐκστάς τινι τῶν ἐπιτεταγμένων τῆς χώρας ἔπεσεν ἐντὸς τῶν ὅπλων, ὥστε μὴ γενέσθαι τὸν νεκρὸν ὑπὸ τοῖς πολεμίοις.", "st": "Pyrrh. 28.4"}, {"sp": "N", "t": "νυκτὸς δὲ ἡ μάχη διεκρίθη· καὶ κοιμώμενος ὁ Πύρρος ὄψιν εἶδε τοιαύτην. ἐδόκει βάλλεσθαι κεραυνοῖς ὑπ’ αὐτοῦ τὴν Λακεδαίμονα καὶ φλέγεσθαι πᾶσαν, αὐτὸν δὲ χαίρειν. ὑπὸ δὲ τῆς χαρᾶς ἐξεγρόμενος τούς τε ἡγεμόνας ἐκέλευεν ἐν παρασκευῇ τὸν στρατὸν ἔχειν, καὶ τοῖς φίλοις διηγεῖτο τὸν ὄνειρον ὡς ληψόμενος κατὰ κράτος τὴν πόλιν. οἱ μὲν οὖν ἄλλοι θαυμασίως ἐπείθοντο, Λυσιμάχῳ δὲ οὐκ ἤρεσκεν ἡ ὄψις, ἀλλ’ ἔφη δεδιέναι μή, καθάπερ τὰ βαλλόμενα τοῖς κεραυνοῖς ἀνέμβατα μένει χωρία, καὶ τῷ Πύρρῳ προσημαίνῃ τὸ θεῖον ἀνείσοδον ἔσεσθαι τὴν πόλιν. ὁ δὲ Πύρρος εἰπὼν ὅτι ταῦτα μέν ἐστι πυλαϊκῆς ὀχλαγωγίας καὶ ἀσοφίαν ἔχοντα πολλήν, ἐκεῖνο δὲ δεῖ τὰ ὅπλα διὰ χειρῶν ἔχοντας ὑποβάλλειν ἑαυτοῖς,", "st": "Pyrrh. 29.1"}, {"sp": "N", "t": "εἷς οἰωνὸς ἄριστος ἀμύνεσθαι περὶ Πύρρου,<br>ἐξανέστη καὶ προσῆγεν ἅμ’ ἡμέρᾳ τὸν στρατόν.", "st": "Pyrrh. 29.1b"}, {"sp": "N", "t": "ἠμύνοντο δὲ προθυμίᾳ καὶ ἀρετῇ παρὰ δύναμιν οἱ Λακεδαιμόνιοι· καὶ παρῆσαν αἱ γυναῖκες ὀρέγουσαι βέλη, καὶ σιτία καὶ ποτὸν τοῖς δεομένοις προσφέρουσαι, καὶ ἀναλαμβάνουσαι τούς τιτρωσκομένους. τήν τε τάφρον οἱ Μακεδόνες χοῦν ἐπειρῶντο, πολλὴν συμφοροῦντες ὕλην, ὑφ’ ἧς ὅπλα καὶ σώματα νεκρῶν ἐπιχεομένης ἀπεκρύπτετο. καὶ πρὸς τοῦτο τῶν Λακεδαιμονίων βοηθούντων ὤφθη παρὰ τὴν τάφρον καὶ τὰς ἁμάξας ὁ Πύρρος ἵππῳ βιαζόμενος εἰς τὴν πόλιν. κραυγῆς δὲ τῶν κατὰ τοῦτο τεταγμένων γενομένης καὶ δρόμου καὶ ὀλολυγμοῦ τῶν γυναικῶν, ἤδη διεξελαύνοντι τῷ Πύρρῳ καὶ προσκειμένῳ τοῖς κατὰ πρόσωπον ἐξήλατο Κρητικῷ βέλει πληγεὶς ὁ ἵππος ὑπὸ τὴν γαστέρα, καὶ κατέβαλε δυσθανατῶν τὸν Πύρρον εἰς τόπους ὀλισθηροὺς καὶ κατάντεις. θορυβουμένων δὲ περὶ τοῦτον τῶν ἑταίρων ἐπέδραμον οἱ Σπαρτιᾶται, καὶ χρώμενοι τοῖς βέλεσιν ἐξέωσαν ἅπαντας· ἐκ δὲ τούτου καὶ τὴν ἄλλην μάχην ἔπαυεν, οἰόμενος ἐνδώσειν τι τοὺς Λακεδαιμονίους σχεδὸν ἁπάντων κατατετρωμένων αὐτοῖς, πεπτωκότων δὲ πολλῶν, ἡ δ’· ἀγαθὴ τύχη τῆς πόλεως, εἴτε πεῖραν ἀρετῆς λαμβάνουσα τῶν ἀνδρῶν, εἴθ’ ἑαυτῆς, ὅσην ἐν ἀπόροις ἔχει δύναμιν, ἀπόδειξιν διδοῦσα, μοχθηρὰς ἤδη τῶν Λακεδαιμονίων ἐχόντων τὰς ἐλπίδας Ἀμεινίαν τε Φωκέα, τῶν Ἀντιγόνου στρατηγῶν, ἐκ Κορίνθου βοηθήσοντα παρεισήγαγε μετὰ ξένων, καὶ τοῦτον ἄρτι δεδεγμένων ὁ βασιλεὺς αὐτοῖς Ἄρευς ἧκεν ἐκ Κρήτης δισχιλίους στρατιώτας κομίζων, αἵ τε δὴ γυναῖκες εὐθὺς ἐπὶ τὰς οἰκίας ἐσκεδάσθησαν, οὐδὲν ἔτι πολυπραγμονεῖν ἀξιοῦσαι τῶν πολεμικῶν, καὶ τοὺς παρ’ ἡλικίαν ἐν τοῖς ὅπλοις ὑπ’ ἀνάγκης γενομένους ἀφέντες αὑτοὺς ἐπὶ τὴν μάχην ἔταξαν.", "st": "Pyrrh. 29.3"}, {"sp": "N", "t": "τὸν δὲ Πύρρον ἔσχε μέν τις ἀλκὴ καὶ φιλοτιμία μᾶλλον διὰ τοὺς προσγεγονότας κρατῆσαι τῆς πόλεως· ὡς δὲ οὐδὲν ἐπέραινε, πληγὰς λαβὼν ἀπέστη καὶ τὴν χώραν ἐπόρθει διανοούμενος αὐτόθι χειμάσαι. τὸ δὲ χρεὼν ἦν ἄφυκτον. ἐν γὰρ Ἄργει στάσις ἦν Ἀριστέου πρὸς Ἀρίστιππον. ἐπεὶ δὲ ὁ Ἀρίστιππος ἐδόκει χρῆσθαι φίλῳ τῷ Ἀντιγόνῳ, φθάσας ὁ Ἀριστέας ἐκάλει τὸν Πύρρον εἰς τὸ Ἄργος. ὁ δὲ ἐλπίδας ἐξ ἐλπίδων ἀεὶ κυλίνδων, καὶ ταῖς μὲν εὐτυχίαις ἐπ’ ἄλλας χρώμενος ἀφορμαῖς, ἃ δὲ ἔπταιεν ἑτέροις βουλόμενος ἀναπληροῦν πράγμασιν, οὔτε ἧτταν οὔτε νίκην ὅρον ἐποιεῖτο τοῦ ταράττεσθαι καὶ ταράττειν. εὐθὺς οὖν ἀνεζεύγνυεν ἐπὶ τὸ Ἄργος· ὁ δὲ Ἄρευς ἐνέδρας τε πολλὰς ὑφεὶς καὶ καταλαβὼν τὰ χαλεπώτατα τῆς ὁδοῦ περιέκοπτε τοὺς Γαλάτας καὶ τοὺς Μολοσσοὺς ὀπισθοφυλακοῦντας.", "st": "Pyrrh. 30.1"}, {"sp": "N", "t": "τῷ δὲ Πύρρῳ προείρητο μὲν ἐκ τῶν ἱερῶν ἀλόβων γενομένων ὑπὸ τοῦ μάντεως ἀποβολή τινος τῶν ἀναγκαίων, παρὰ δὲ τὸν καιρὸν τότε τῷ θορύβῳ καὶ τῷ κινήματι τὸν λογισμὸν ἐκκρουσθεὶς ἐκέλευσε τὸν υἱὸν Πτολεμαῖον λαβόντα τοὺς ἑταίρους παραβοηθεῖν, αὐτὸς δὲ θᾶττον ἐκ τῶν στενῶν ἐφελκόμενος τὴν στρατιὰν ὑπῆγεν. ὀξείας δὲ περὶ τὸν Πτολεμαῖον μάχης γενομένης, καὶ τῶν ἐπιλέκτων Λακεδαιμονίων, ὧν Εὔαλκος ἡγεῖτο, τοῖς μαχομένοις πρὸ αὐτοῦ συμπλεκομένων, ἀνὴρ πλήκτης καὶ δραμεῖν ὀξύς, Ὄρυσσος ὄνομα, Κρὴς Ἀπτεραῖος· ἐκ πλαγίου παραδραμὼν ἀγωνιζόμενον ἐκθύμως τὸν νεανίσκον ἐπάταξε καὶ κατέβαλε. πεσόντος δὲ ἐκείνου καὶ τροπῆς γενομένης τῶν περὶ αὐτόν, οἱ Λακεδαιμόνιοι διώκοντες καὶ κρατοῦντες ἔλαθον εἰς τὸ πεδίον συνεμβαλόντες καὶ ἀποληφθέντες ὑπὸ τῶν ὁπλιτῶν, ἐφ’ οὓς ὁ Πύρρος ἄρτι τὸν θάνατον τοῦ παιδὸς ἀκηκοὼς καὶ περιπαθῶν ἐπέστρεψε τοὺς ἱππεῖς τῶν Μολοσσῶν, καὶ πρῶτος εἰσελάσας ἐνεπίμπλατο φόνου τῶν Λακεδαιμονίων, ἀεὶ μέν τις ἄμαχος καὶ δεινὸς ἐν τοῖς ὅπλοις φαινόμενος, τότε δὲ ὑπερβάλλων τόλμῃ καὶ βίᾳ τοὺς προτέρους ἀγῶνας. ἐπεὶ δὲ ἐπέβαλε τῷ Εὐάλκῳ τὸν ἵππον, ὁ μὲν ἐκ πλαγίου παραστὰς μικρὸν ἐδέησε τῷ ξίφει τὴν ἐπὶ τῆς ἡνίας χεῖρα διακόψαι τοῦ Πύρρου, τὴν δὲ ἡνίαν πατάξας ἀπέκοψεν. ὁ δὲ Πύρρος ἅμα τῇ πληγῇ τοῦ δόρατος διελάσας ἐκεῖνον ἀπερρύη τοῦ ἵππου, καὶ πεζὸς ἤδη πάντας ἐπὶ τῷ Εὐάλκῳ μαχομένους ἀπέκτεινε τοὺς λογάδας. καὶ μέγα τοῦτο τῇ Σπάρτῃ παρανάλωμα τοῦ πολέμου πέρας ἔχοντος ἐποίησεν ἡ φιλοτιμία τῶν ἀρχόντων.", "st": "Pyrrh. 30.3"}, {"sp": "N", "t": "ὁ δὲ Πύρρος ὥσπερ ἐναγισμόν τινα τῷ παιδὶ τελέσας καὶ λαμπρὸν ἐπιτάφιον ἀγωνισάμενος, καὶ πολὺ τῆς λύπης ἐν τῷ πρὸς τοὺς πολεμίους ἀφεὶς θυμῷ, προῆγεν ἐπὶ τὸ Ἄργος, καὶ τὸν Ἀντίγονον ἤδη πυνθανόμενος ἐπὶ τῶν ἄκρων ὑπὲρ τοῦ πεδίου καθῆσθαι, περὶ τὴν Ναυπλίαν ἐστρατοπέδευσε. τῇ δ’ ὑστεραίᾳ κήρυκα πρὸς τὸν Ἀντίγονον ἔπεμψε, λυμεῶνά τε καλῶν καὶ προκαλούμενος εἰς τὸ πεδίον καταβάντα διαγωνίσασθαι περὶ τῆς βασιλείας. ὁ δὲ ἀπεκρίνατο τὴν μὲν αὑτοῦ στρατηγίαν οὐχ ὅπλων μᾶλλον ἢ καιρῶν εἶναι, τῷ δὲ Πύρρῳ πολλὰς ὁδοὺς ἀνεῳγέναι πρὸς θάνατον, εἰ ζῆν μὴ σχολάζει, πρὸς δὲ ἀμφοτέρους πρέσβεις ἧκον ἐξ Ἄργους, ἀπαλλάττεσθαι δεόμενοι καὶ τὴν πόλιν ἐᾶν μηδετέρου γενομένην, εὔνουν δὲ οὖσαν ἀμφοτέροις. ὁ μὲν οὖν Ἀντίγονος ἐπείθετο καὶ τὸν υἱὸν ἐδίδου τοῖς Ἀργείοις ὅμηρον, ὁ δὲ Πύρρος ὡμολόγει μὲν ἀπαλλαγήσεσθαι, μὴ παρέχων δὲ πίστιν ὑποπτότερος ἦν.", "st": "Pyrrh. 31.1"}, {"sp": "N", "t": "γίνεται δὲ σημεῖον αὐτῷ τε τῷ Πύρρῳ μέγα, τῶν γὰρ βοῶν τεθυμένων αἱ κεφαλαὶ κείμεναι χωρὶς ἤδη τάς τε γλώττας ὤφθησαν προβάλλουσαι καὶ περιλιχμώμεναι τὸν ἑαυτῶν φόνον, ἔν τε τῇ πόλει τῶν Ἀργείων ἡ τοῦ Λυκείου προφῆτις Ἀπόλλωνος ἐξέδραμε βοῶσα νεκρῶν ὁρᾶν καὶ φόνου κατάπλεω τὴν πόλιν, τὸν δ’ ἀετὸν ἐπὶ τὸν ἀγῶνα χωροῦντα, εἶτα φροῦδον εἶναι.", "st": "Pyrrh. 31.3"}, {"sp": "N", "t": "σκότους δὲ πολλοῦ προσμίξας ὁ Πύρρος τοῖς τείχεσι, καὶ πύλην εὑρών ἣν Διαμπερὲς καλοῦσιν ἀνεῳγμένην ὑπὸ τοῦ Ἀριστέου αὐτοῖς, ἄχρι μὲν τοῦ παρεισπεσεῖν τοὺς Γαλάτας τοὺς παρ’ αὐτοῦ καὶ τὴν ἀγορὰν καταλαβεῖν ἐλάνθανε· τῆς δὲ πύλης τοὺς ἐλέφαντας οὐ δεχομένης καὶ διὰ τοῦτο τοὺς πύργους αὐτῶν ἀφαιρούντων, εἶτα πάλιν ἐν σκότε καὶ θορύβῳ περιτιθέντων καὶ γενομένης διατριβῆς, οἱ Ἀργεῖοι συναισθόμενοι πρὸς τὴν Ἀσπίδα καὶ τοὺς ὀχυροὺς τόπους ἀνέθεον, καὶ τὸν Ἀντίγονον ἐκάλουν πέμποντες. ὁ δὲ αὐτὸς μὲν ἐγγὺς προσελάσας ἐφήδρευε, τοὺς δὲ στρατηγοὺς καὶ τὸν υἱὸν εἰσέπεμψε συχνὴν βοήθειαν ἄγοντας. ἧκε δὲ καὶ Ἄρευς ἔχων χιλίους Κρῆτας καὶ Σπαρτιάτας τοὺς ἐλαφροτάτους, καὶ πάντες ἅμα τοῖς Γαλάταις προσβαλόντες εἰς πολὺν θόρυβον κατέστησαν αὐτούς, ὁ δὲ Πύρρος εἰσιὼν μετ’ ἀλαλαγμοῦ καὶ βοῆς παρὰ τὴν Κυλάραβιν, ὡς οἱ Γαλάται τοῖς περὶ αὐτὸν ἀντηλάλαξαν οὐκ ἰταμὸν οὐδὲ θαρραλέον, εἴκασε ταραττομένων εἶναι τὴν φωνὴν καὶ πονούντων. ἐπῆγεν οὖν θᾶττον, ὠθῶν τοὺς πρὸ αὐτοῦ τῶν ἱππέων δυσοδοῦντας ἐν τοῖς ὀχετοῖς, ὧν ἡ πόλις ἐστὶ μεστή, καὶ κινδυνεύοντας, ἦν δὲ καὶ ἀσάφεια πολλὴ τῶν δρωμένων καὶ παραγγελλομένων ἐν νυκτομαχίᾳ, καὶ πλάναι καὶ διασπασμοὶ περὶ τοὺς στενωπούς, καὶ στρατηγίας οὐδὲν ἔργον ὑπὸ σκότους καὶ βοῆς ἀκρίτου καὶ στενότητος, ἀλλὰ διέτριβον ἄλλως περιμένοντες ἀμφότεροι τὴν ἡμέραν.", "st": "Pyrrh. 32.1"}, {"sp": "N", "t": "ἤδη δὲ διαλάμποντος ἥ τε Ἀσπὶς ὅπλων περίπλεως πολεμίων ὀφθεῖσα τὸν Πύρρον διετάραξε, καὶ τῆς ἀγορᾶς ἐν πολλοῖς ἀναθήμασι κατιδὼν λύκον χαλκοῦν καὶ ταῦρον οἷον εἰς μάχην ἀλλήλοις συνιόντας ἐξεπλάγη, χρησμόν τινα πρὸς ἑαυτὸν ἀνενεγκὼν παλαιόν, ὡς ἀποθανεῖν αὐτῷ πεπρωμένον ὅταν λύκον ἴδῃ ταύρῳ μαχόμενον. ταῦτα δὲ Ἀργεῖοι πάθους ὑπομνήματα παλαιοῦ γεγενῆσθαι παρ’ αὐτοῖς λέγουσι. Δαναῷ γάρ, ὅτε πρῶτον ἐπέβη τῆς χώρας κατὰ τὰ Πυράμια τῆς Θυρεάτιδος, εἰς Ἄργος πορευομένῳ λύκον φανῆναι ταύρῳ μαχόμενον· θέμενον δὲ τὸν Δαναὸν ὡς ὁ λύκος εἴη πρὸς αὐτοῦ ξένον γὰρ ὄντα τοῖς ἐγχωρίοις ἐπιτίθεσθαι καθάπερ αὐτόν, ἐφορᾶν τὴν μάχην, καὶ τοῦ λύκου κρατήσαντος Ἀπόλλωνι Λυκείῳ προσευξάμενον ἐπιχειρῆσαι καὶ περιγενέσθαι, στάσει Γελάνορος, ὃς τότε τῶν Ἀργείων ἐβασίλευεν, ἐκπεσόντος. τὸ μὲν οὖν ἀνάθημα τοῦτον εἶχε τὸν λόγον.", "st": "Pyrrh. 32.4"}, {"sp": "N", "t": "πρὸς δὲ τὴν ὄψιν ὁ Πύρρος ἅμα καὶ τῷ μηδὲν ὧν ἤλπιζε προχωρεῖν ἀθυμῶν ἀναστρέφειν διενοεῖτο· τὰς δὲ πύλας στενὰς οὔσας φοβούμενος ἔπεμψε πρὸς τὸν υἱὸν Ἕλενον μετὰ τῆς πολλῆς δυνάμεως ἔξω καταλελειμμένον, κελεύων τοῦ τείχους διασκάπτειν καὶ δέχεσθαι τοὺς ἐκπίπτοντας, ἂν ἐνοχλῶσιν οἱ πολέμιοι. σπουδῇ δὲ καὶ θορύβῳ τοῦ πεμφθέντος οὐδὲν σαφὲς ἀπαγγέλλοντος, ἀλλὰ καὶ διαμαρτίας γενομένης, τῶν θηρίων τὰ λοιπὰ καὶ στρατιώτας ἀναλαβὼν τοὺς κρατίστους ὁ νεανίσκος εἴσω διὰ τῶν πυλῶν ἐχώρει τῷ πατρὶ βοηθήσων, ἔτυχε δὲ ὁ Πύρρος ἀναστρέφων ἤδη. καὶ μέχρι μὲν ἡ ἀγορὰ παρεῖχεν ὑπεξάγοντι χώραν καὶ μαχομένῳ, ἐκ μεταβολῆς ἠμύνετο τοὺς ἐπιφερομένους· ἐπεὶ δὲ τῆς ἀγορᾶς εἰς τὸν στενωπὸν ἐξωσθεὶς τὸν ἐπὶ τὴν πύλην ἀνήκοντα συνέπιπτε τοῖς ἐπιβοηθοῦσιν ἐξ ἐναντίας προσφερομένοις, οἱ μὲν οὐχ ὑπήκουον ὑποχωρεῖν βοῶντος αὐτοῦ, τοὺς δὲ καὶ πάνυ προθύμους ὄντας εἶργον οἱ κατόπιν ἀπὸ τῆς πύλης ἐπιχεόμενοι. καὶ γὰρ ὁ μέγιστος ἐλέφας ἐν τῇ πύλῃ πλάγιος παραπεσὼν καὶ βρυχώμενος ἐμποδὼν ἔκειτο τοῖς ἀποτρεπομένοις, καὶ τῶν προεισεληλυθότων ἕτερος, ᾧ Νίκων ὄνομα ἦν, ἀπορρυέντα τὸν ἐπιστάτην ὑπὸ τραυμάτων ζητῶν ἀναλαβεῖν καὶ φερόμενος πρὸς τοὐναντίον τοῖς ὑπεξάγουσιν, ἀνέμιξε φίλους ὁμοῦ καὶ πολεμίους ὠθουμένους ὑπ’ αὐτοῦ· καὶ περιέπιπτον ἀλλήλοις, ἕως εὑρὼν νεκρὸν ἀνείλετο τῇ προβοσκίδι, καὶ τοῖς ὀδοῦσιν ἀμφοτέροις ὑπολαβὼν ἀνέστρεφε πάλιν ὥσπερ ἐμμανὴς, ἀνατρέπων καὶ διαφθείρων τοὺς ἐντυγχάνοντας. οὕτω δὲ θλιβομένων καὶ συμπιλουμένων πρὸς ἀλλήλους οὐδεὶς οὐδὲν ἑαυτῷ καθ’ ἕνα χρῆσθαι δυνατὸς ἦν, ἀλλ’ ὥσπερ ἓν σῶμα συγγεγομφωμένον ἑαυτῷ τὸ πᾶν πλῆθος ἐλάμβανε πολλὰς ἀποκλίσεις καὶ μεταβολὰς ἐπ’ ἀμφότερα. καὶ μάχαι μὲν ἦσαν ὀλίγαι πρὸς τοὺς ἐναπολαμβανομένους ἀεὶ τῶν πολεμίων ἢ προσκειμένους ὄπισθεν, πλεῖστα δὲ ἑαυτοὺς εἰργάζοντο κακά. σπασάμενον γάρ τὸ ξίφος ἢ κλίναντα λόγχην οὐκ ἦν ἀναλαβεῖν οὐδὲ καταθέσθαι πάλιν, ἀλλ’ ἐχώρει δι’ ὧν ἔτυχε τὰ τοιαῦτα πάντα, καὶ περιπίπτοντες ἀλλήλοις ἔθνῃσκον.", "st": "Pyrrh. 33.1"}, {"sp": "N", "t": "ὁ δὲ Πύρρος ἐφορῶν τὸν περιέχοντα χειμῶνα καὶ κλύδωνα, τὴν μὲν στεφάνην, ᾗ διάσημον ἦν τὸ κράνος, ἀφελὼν ἔδωκέ τινι τῶν ἑταίρων, αὐτὸς δὲ τῷ ἵππῳ πεποιθὼς εἴς τοὺς ἑπομένους τῶν πολεμίων ἐνέβαλε, καὶ δόρατι πληγεὶς διὰ τοῦ θώρακος οὐ καιρίαν πληγὴν οὐδὲ μεγάλην ἐπέστρεψε κατὰ τοῦ πατάξαντος, ὃς ἦν Ἀργεῖος, οὐ τῶν ἐπιφανῶν, ἀλλὰ πενιχρᾶς καὶ πρεσβυτέρας υἱὸς γυναικός αὕτη τότε θεωμένη τὴν μάχην ὥσπερ αἱ λοιπαὶ γυναῖκες ἀπὸ τοῦ τέγους, ὡς ἐπέγνω συνεστῶτα τῷ Πύρρῳ τὸν υἱόν, ἐκπαθὴς γενομένη πρὸς τὸν κίνδυνον, ἄρασα κεραμίδα ταῖς χερσὶν ἀμφοτέραις ἀφῆκεν ἐπὶ τὸν Πύρρον. ἐμπεσούσης δὲ τῇ κεφαλῇ κατὰ τοῦ κράνους, καὶ τῶν σφονδύλων πρὸς τὴν βάσιν τοῦ τραχήλου συντριβέντων, αἵ τε ὄψεις συνεχύθησαν αὐτοῦ καὶ προήκαντο τὰς ἡνίας αἱ χεῖρες, αὐτὸς δὲ κατενεχθεὶς παρὰ τὸν τοῦ Λικυμνίου σηκὸν ἔπεσεν ὑπὸ τῶν πολλῶν ἀγνοούμενος. Ζώπυρος δέ τις τῶν παρὰ Ἀντιγόνῳ στρατευομένων καὶ δύο ἢ τρεῖς ἕτεροι προσδραμόντες καὶ κατανοήσαντες εἴς τινα θυρῶνα παρείλκυσαν αὐτὸν ἀρχόμενον ἐκ τῆς πληγῆς ἀναφέρεσθαι, σπασαμένου δὲ τοῦ Ζωπύρου μάχαιραν Ἰλλυρικὴν ὡς τὴν κεφαλὴν ἀποτεμοῦντος ἐνέβλεψε δεινόν, ὥστε τὸν Ζώπυρον περίφοβον γενόμενον, καὶ τὰ μὲν τρέμοντα ταῖς χερσί, τὰ δὲ ἐπιχειροῦντα, θορύβου δὲ καὶ ταραχῆς μεστὸν ὄντα, μὴ κατ’ ὀρθόν, ἀλλὰ παρὰ τὸ στόμα καὶ τὸ γένειον ἀποτέμνοντα βραδέως καὶ μόλις ἀποσπάσαι τὴν κεφαλήν. ἤδη δὲ σύνδηλον ἦν τὸ γεγονὸς πλείοσι, καὶ προσδραμὼν ὁ Ἀλκυονεὺς ᾔτησε τὴν κεφαλὴν ὡς ἂν κατανοήσων λαβὼν δὲ ἀφίππευσε πρὸς τὸν πατέρα, καὶ καθεζομένῳ μετὰ τῶν φίλων προσέβαλε, θεασάμενος δὲ καὶ γνοὺς ὁ Ἀντίγονος τὸν μὲν υἱὸν ἀπήλασε τῇ βακτηρίᾳ παίων καὶ καλῶν ἐναγῆ καὶ βάρβαρον, αὐτὸς δὲ τὴν χλαμύδα προθέμενος τοῖς ὄμμασιν ἐδάκρυσεν, Ἀντιγόνου τοῦ πάππου μνησθεὶς καὶ Δημητρίου τοῦ πατρός, οἰκείων παραδειγμάτων εἴς τύχης μεταβολήν.", "st": "Pyrrh. 34.1"}, {"sp": "N", "t": "τὴν μὲν οὖν κεφαλὴν καὶ τὸ σῶμα τοῦ Πύρρου κοσμήσας ἔκαυσεν· ἐπεὶ δὲ ὁ Ἀλκυονεὺς τῷ Ἑλένῳ περιτυχὼν ταπεινῷ καὶ χλαμύδιον λιτὸν ἀμπεχομένῳ φιλανθρώπως ἐνέτυχε καὶ τῷ πατρὶ προσήγαγεν, ἰδὼν ὁ Ἀντίγονος βελτίονα μὲν, εἶπεν, ὦ παῖ, ταῦτα τῶν προτέρων, ἀλλ’ οὐδὲ νῦν ὀρθῶς τῷ μὴ περιελεῖν τὴν ἐσθῆτα ταύτην, ἣ μᾶλλον ἡμᾶς καταισχύνει τοὺς κρατεῖν δοκοῦντας. ἐκ τούτου φιλοφρονησάμενος καὶ κοσμήσας τὸν Ἕλενον ἀπέστειλεν εἴς Ἤπειρον, καὶ τοῖς φίλοις τοῦ Πύρρου πράως ἐνετύγχανε τοῦ στρατοπέδου καὶ τῆς δυνάμεως πάσης κύριος γενόμενος.", "st": "Pyrrh. 34.5"}, {"sp": "HDR", "t": "Γάϊος Μάριος"}, {"sp": "N", "t": "Γαΐου Μαρίου τρίτον οὐκ ἔχομεν εἰπεῖν ὄνομα, καθάπερ οὐδὲ Κοΐντου Σερτωρίου τοῦ κατασχόντος Ἰβηρίαν, οὐδὲ Λευκίου Μομμίου τοῦ Κόρινθον ἑλόντος· ὁ γὰρ Ἀχαϊκὸς τούτῳ γε τῆς πράξεως ἐπώνυμον γέγονεν, ὡς ὁ Ἀφρικανὸς Σκηπίωνι καὶ ὁ Μακεδονικὸς Μετέλλῳ. ἐξ οὗ καὶ μάλιστα Ποσειδώνιος ἐλέγχειν οἴεται τοὺς τὸ τρίτον ὄνομα Ῥωμαίοις κύριον εἶναι νομίζοντας, οἷον τὸν Κάμιλλον καὶ τὸν Μάρκελλον καὶ τὸν Κάτωνα· γίνεσθαι γὰρ ἂν ἀνωνύμους τοὺς ἀπὸ μόνων τῶν δυεῖν προσαγορευομένους. λανθάνει δὲ ἑαυτὸν ὅτι τούτῳ τῷ λόγῳ πάλιν αὐτὸς ἀνωνύμους ποιεῖ τὰς γυναῖκας· οὐδεμιᾷ γάρ γυναικὶ τίθεται τῶν ὀνομάτων τὸ πρῶτον, ὅπερ οἴεται κύριον ὄνομα Ῥωμαίοις ὑπάρχειν ὁ Ποσειδώνιος. τῶν δὲ ἄλλων τὸ μὲν κοινὸν ἀπὸ συγγενείας, τοὺς Πομπηΐους καὶ τοὺς Μαλλίους καὶ τοὺς Κορνηλίους ὥσπερ ἂν Ἡρακλείδας τις εἴποι καὶ Πελοπίδας, τοῦτο δὲ προσηγορικὸν ἐξ ἐπιθέτου πρὸς τὰς φύσεις ἢ τὰς πράξεις ἢ τὰ τοῦ σώματος εἴδη καὶ πάθη τίθεσθαι, τὸν Μακρῖνον καὶ τὸν Τουρκουᾶτον καὶ τὸν Σύλλαν οἶόν ἐστιν ὁ Μνήμων ἢ ὁ Γρυπὸς ἢ ὁ Καλλίνικος, εἰς μὲν οὖν ταῦτα πολλὰς δίδωσιν ἐπιχειρήσεις ἡ τῆς συνηθείας ἀνωμαλία.", "st": "Mar. 1.1"}, {"sp": "N", "t": "τῆς δὲ ὄψεως τῆς Μαρίου λιθίνην εἰκόνα κειμένην ἐν Ῥαβέννῃ τῆς Γαλατίας ἐθεώμεθα πάνυ τῇ λεγομένῃ περὶ τὸ ἦθος στρυφνότητι καὶ πικρίᾳ πρέπουσαν. ἀνδρώδης γὰρ φύσει καὶ πολεμικὸς γενόμενος, καὶ στρατιωτικῆς μᾶλλον ἢ πολιτικῆς παιδείας μεταλαβών, ἄκρατον ἐν ταῖς ἐξουσίαις τὸν θυμὸν ἔσχε. λέγεται δὲ μήτε γράμματα μαθεῖν Ἑλληνικὰ μήτε γλώττῃ πρὸς μηδὲν Ἑλληνίδι χρῆσθαι τῶν σπουδῆς ἐχομένων, ὡς γελοῖον γράμματα μανθάνειν ὧν οἱ διδάσκαλοι δουλεύοιεν ἑτέροις μετὰ δὲ τὸν δεύτερον θρίαμβον ἐπὶ ναοῦ τινος καθιερώσει θέας Ἐλληνικὰς παρέχων, εἰς τὸ θέατρον ἐλθὼν καὶ μόνον καθίσας εὐθὺς ἀπαλλαγῆναι. ὥσπερ οὖν Ξενοκράτει τῷ φιλοσόφῳ σκυθρωποτέρῳ δοκοῦντι τὸ ἦθος εἶναι πολλάκις εἰώθει λέγειν ὁ Πλάτων, Ὦ μακάριε Ξενόκρατες, θῦε ταῖς Χάρισιν, οὕτως εἴ τις ἔπεισε Μάριον θύειν ταῖς Ἑλληνικαῖς Μούσαις καὶ Χάρισιν, οὐκ ἂν ἐκπρεπεστάταις στρατηγίαις καὶ πολιτείαις ἀμορφοτάτην ἐπέθηκε κορωνίδα, ὑπὸ θυμοῦ καὶ φιλαρχίας ἀώρου καὶ πλεονεξιῶν ἀπαρηγορήτων εἰς ὠμότατον καὶ ἀγριώτατον γῆρας ἐξοκείλας. ταῦτα μὲν οὖν ἐπὶ τῶν πράξεων αὐτῶν εὐθὺς θεωρείσθω.", "st": "Mar. 2.1"}, {"sp": "N", "t": "γενόμενος δὲ γονέων παντάπασιν ἀδόξων, αὐτουργῶν δὲ καὶ πενήτων, πατρὸς μὲν ὁμωνύμου, μητρὸς δὲ Φουλκινίας, ὀψέ ποτε πόλιν εἶδε καὶ τῶν ἐν πόλει διατριβῶν ἐγεύσατο, τὸν δὲ ἄλλον χρόνον ἐν κώμῃ Κιρραιάτωνι τῆς Ἀρπίνης δίαιταν εἶχε, πρὸς μὲν ἀστεῖον καὶ γλαφυρὸν βίον ἀγροικοτέραν, σώφρονα δὲ καὶ ταῖς πάλαι Ῥωμαίων τροφαῖς ἐοικυῖαν. πρώτην δὲ στρατείαν στρατευσάμενος ἐπὶ Κελτίβηρας, ὅτε Σκηπίων Ἀφρικανὸς Νομαντίαν ἐπολιόρκει, τὸν στρατηγὸν οὐκ ἐλάνθανεν ἀνδρείᾳ τῶν ἄλλων νέων διαφέρων καὶ τὴν μεταβολὴν τῆς διαίτης, ἣν ὑπὸ τρυφῆς καὶ πολυτελείας διεφθαρμένοις ἐπῆγε τοῖς στρατεύμασιν ὁ Σκηπίων, εὐκολώτατα προσδεχόμενος. λέγεται δὲ καὶ πολέμιον ἄνδρα συστὰς καταβαλεῖν ἐν ὄψει τοῦ στρατηγοῦ. διὸ ταῖς τε ἄλλαις προήγετο τιμαῖς ὑπ’ αὐτοῦ, καί ποτε λόγου μετὰ δεῖπνον ἐμπεσόντος ὑπὲρ στρατηγῶν, καὶ τῶν παρόντων ἑνὸς εἴτε ἀληθῶς διαπορήσαντος εἴτε πρὸς ἡδονὴν ἐρομένου τὸν Σκηπίωνα τίνα δὴ τοιοῦτον ἕξει μετ’ ἐκεῖνον ἡγεμόνα καὶ προστάτην ὁ Ῥωμαίων δῆμος, ὑπερκατακειμένου τοῦ Μαρίου τῇ χειρὶ τὸν ὦμον ἠρέμα πατάξας ὁ Σκηπίων, τάχα δὲ τοῦτον, εἶπεν. οὕτως εὐφυὴς ἦν ὁ μὲν ἐκ μειρακίου φανῆναι μέγας, ὁ δὲ ἀπὸ τῆς ἀρχῆς τὸ τέλος νοῆσαι.", "st": "Mar. 3.1"}, {"sp": "N", "t": "τὸν δ’ οὖν Μάριον ὑπὸ ταύτης λέγεται μάλιστα τῆς φωνῆς, ὥσπερ ὑπὸ θείας κληδόνος, ἐπαρθέντα ταῖς ἐλπίσιν ὁρμῆσαι πρὸς τὴν πολιτείαν, καὶ τυχεῖν δημαρχίας Κεκιλίου Μετέλλου σπουδάσαντος, οὗ τὸν οἶκον ἐξ ἀρχῆς καὶ πατρόθεν ἐθεράπευεν. ἐν δὲ τῇ δημαρχίᾳ νόμον τινὰ περὶ ψηφοφορίας γράφοντος αὐτοῦ δοκοῦντα τῶν δυνατῶν ἀφαιρεῖσθαι τὴν περὶ τὰς κρίσεις ἰσχύν, ἐνιστάμενος Κόττας ὁ ὕπατος συνέπεισε τὴν βουλὴν τῷ μὲν νόμῳ μάχεσθαι, τὸν δὲ Μάριον καλεῖν λόγον ὑφέξοντα. καὶ τοῦ δόγματος τούτου γραφέντος εἰσελθὼν ἐκεῖνος οὐκ ἔπαθε νέου πάθος ἀπὸ μηδενὸς λαμπροῦ προεληλυθότος ἄρτι πρὸς τὴν πολιτείαν, ἀλλ’ ἑαυτῷ διδοὺς ἤδη φρονεῖν ἡλίκον αἱ μετέπειτα πράξεις ἔδωκαν, ἠπείλησε τὸν Κότταν ἀπάξειν εἰς τὸ δεσμωτήριον, εἰ μὴ διαγράψειε τὸ δόγμα. τοῦ δὲ πρὸς Μέτελλον τραπομένου καὶ γνώμην ἐρωτῶντος, Μέτελλος μὲν ἀναστὰς συνηγόρει τῷ ὑπάτῳ, Μάριος δὲ τὸν ὑπηρέτην μεταπεμψάμενος ἔξωθεν ἐκέλευεν ἀπάγειν αὐτὸν τὸν Μέτελλον εἰς τὸ δεσμωτήριον. ἐκείνου δὲ τοὺς ἄλλους ἐπικαλουμένου δημάρχους ἐβοήθει μὲν οὐδείς, ἡ δὲ σύγκλητος εἴξασα προήκατο τὸ δόγμα, καὶ λαμπρὸς ἐξελάσας ὁ Μάριος εἰς τὸ πλῆθος ἐκύρωσε τὸν νόμον, δόξας ἄκαμπτος μὲν εἶναι πρὸς φόβον, ἄτρεπτος δὲ ὑπ’· αἰδοῦς, δεινὸς δὲ κατὰ τῆς βουλῆς ἀνίστασθαι χάριτι τῶν πολλῶν δημαγωγῶν. οὐ μὴν ἀλλὰ ταύτην μὲν ταχέως μετέστησεν ἑτέρῳ πολιτεύματι τὴν δόξαν. νόμου γάρ εἰσφερομένου περὶ σίτου διανομῆς τοῖς πολίταις ἐναντιωθεὶς ἐρρωμενέστατα καὶ κρατήσας, εἰς τὸ ἴσον ἑαυτὸν κατέστησε τῇ τιμῇ πρὸς ἀμφοτέρους ὡς μηδετέροις παρὰ τὸ συμφέρον χαριζόμενος.", "st": "Mar. 4.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν δημαρχίαν ἀγορανομίαν τὴν μείζονα παρήγγειλε, δύο γάρ εἰσι τάξεις ἀγορανομιῶν, ἡ μὲν ἀπὸ τῶν δίφρων τῶν ἀγκυλοπόδων, ἐφ’ ὧν καθεζόμενοι χρηματίζουσιν, ἔχουσα τοὔνομα τῆς ἀρχῆς, τὴν δ’ ὑποδεεστέραν δημοτικὴν καλοῦσιν. ὅταν δὲ τοὺς ἐντιμοτέρους ἕλωνται περὶ τῶν ἑτέρων πάλιν τὴν ψῆφον λαμβάνουσιν. ὡς οὖν ὁ Μάριος φανερὸς ἦν λειπόμενος ἐν ἐκείνῃ, ταχὺ μεταστὰς αὖθις ᾔτει τὴν ἑτέραν. δόξας δὲ θρασὺς εἶναι καὶ αὐθάδης ἀπέτυχε· καὶ δυσὶν ἐν ἡμέρᾳ μιᾷ περιπεσὼν ἀποτεύξεσιν, ὃ μηδεὶς ἔπαθεν ἄλλος, οὐδὲ μικρὸν ὑφήκατο τοῦ φρονήματος, ὕστερον δὲ οὐ πολλῷ στρατηγίαν μετελθὼν ὀλίγον ἐδέησεν ἐκπεσεῖν, ἔσχατος δὲ πάντων ἀναγορευθεὶς δίκην ἔσχε δεκασμοῦ.", "st": "Mar. 5.1"}, {"sp": "N", "t": "μάλιστα δὲ ὑποψίαν παρέσχε Κασσίου Σαβάκωνος οἰκέτης ὀφθεὶς ἐντὸς τῶν δρυφάκτων ἀναμεμειγμένος τοῖς φέρουσι τὰς ψήφους· ὁ γὰρ Σαβάκων ἦν ἑταῖρος ἐν τοῖς μάλιστα Μαρίον. κληθεὶς οὖν οὗτος ὑπὸ τῶν δικαστῶν ἔφη διὰ τὸ καῦμα διψήσας ὕδωρ ψυχρὸν αἰτῆσαι καὶ τὸν οἰκέτην ἔχοντα ποτήριον εἰσελθεῖν πρὸς αὐτόν, εἶτ’ εὐθὺς οἴχεσθαι πιόντος. οὗτος μὲν οὖν ὑπὸ τῶν μετὰ ταῦτα τιμητῶν ἐξέπεσε τῆς βουλῆς, ἐπιτήδειος εἶναι παθεῖν τοῦτο δόξας ἢ διὰ τὴν ψευδομαρτυρίαν ἢ διὰ τὴν ἀκρασίαν ἐπὶ δὲ τὸν Μάριον καὶ Γάϊος Ἑρέννιος μάρτυς εἰσαχθεὶς οὐκ ἔφη ἡ πάτριον εἶναι καταμαρτυρεῖν πελατῶν, ἀλλὰ τὸν νόμον ἀφιέναι ταύτης τῆς ἀνάγκης τοὺς πάτρωνας οὕτως γάρ οἱ Ῥωμαῖοι τοὺς προστάτας καλοῦσι, τοῦ δ’ Ἑρεννίων οἴκου τοὺς Μαρίου γονεῖς καὶ Μάριον αὐτὸν ἐξ ἀρχῆς γεγονέναι πελάτας. ἀποδεξαμένων δὲ τὴν ἀπόρρησιν τῆς μαρτυρίας τῶν δικαστῶν αὐτὸς ἀντεῖπεν ὁ Μάριος πρὸς τὸν Ἑρέννιον ὡς, ὅτε πρῶτον ἄρχων ἀνηγορεύθη, τὸν πελάτην ἐκβεβηκώς· ὅπερ ἦν οὐ παντάπασιν ἀληθές, ἀρχὴ γὰρ οὐ πᾶσα τοῦ νέμειν προστάτην ἀπαλλάσσει τοὺς τυχόντας αὐτοὺς καὶ γένος, ἀλλ’ ᾗ τὸν ἀγκυλόποδα δίφρον ὁ νόμος δίδωσιν. οὐ μὴν ἀλλὰ ταῖς πρώταις ἡμέραις ἐν τῇ δίκῃ κακῶς πράττων ὁ Μάριος καὶ χαλεποῖς χρώμενος τοῖς δικασταῖς, τῇ τελευταίᾳ παραλόγως ἀπέφυγεν ἴσων τῶν ψήφων γενομένων.", "st": "Mar. 5.3"}, {"sp": "N", "t": "ἐν μὲν οὖν τῇ στρατηγίᾳ μετρίως ἐπαινούμενον ἑαυτὸν παρέσχε, μετὰ δὲ τὴν στρατηγίαν κλήρῳ λαβὼν τὴν ἐκτὸς Ἰβηρίαν λέγεται καθᾶραι λῃστηρίων τὴν ἐπαρχίαν ἀνήμερον οὖσαν ἔτι τοῖς ἐθισμοῖς καὶ θηριώδη, καὶ τὸ λῃστεύειν οὔπω τότε τῶν Ἰβήρων οὐχὶ κάλλιστον ἡγουμένων, ἐν δὲ τῇ πολιτείᾳ γενόμενος οὐκ εἶχεν οὔτε πλοῦτον οὔτε λόγον, οἷς ἦγον οἱ τότε μάλιστα τιμώμενοι τὸν δῆμον. αὐτὴν δὲ τὴν ἀνάτασιν τοῦ φρονήματος καὶ τὸ περὶ τοὺς πόνους ἐνδελεχὲς αὐτοῦ καὶ τὸ δημοτικὸν τῆς διαίτης ἔν τινι σπουδῇ τιθεμένων τῶν πολιτῶν ηὐξάνετο τῇ τιμῇ πρὸς δύναμιν, ὥστε καὶ γάμον γῆμαι λαμπρὸν οἰκίας ἐπιφανοῦς τῆς Καισάρων Ἰουλίαν, ἧς ἦν ἀδελφιδοῦς Καῖσαρ ὁ χρόνοις ὕστερον Ῥωμαίων μέγιστος γενόμενος καί τι κατ’ οἰκειότητα ζηλώσας Μάριον, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται.", "st": "Mar. 6.1"}, {"sp": "N", "t": "τῷ δὲ Μαρίῳ καὶ σωφροσύνην μαρτυροῦσι καὶ καρτερίαν, ἧς δεῖγμα καὶ τὸ περὶ τὴν χειρουργίαν ἐστίν, ἰξιῶν γάρ, ὡς ἔοικε, μεγάλων ἀνάπλεως ἄμφω τὰ σκέλη γεγονὼς καὶ τὴν ἀμορφίαν δυσχεραίνων ἔγνω παρασχεῖν ἑαυτὸν τῷ ἰατρῷ· καὶ παρέσχεν ἄδετος θάτερον σκέλος, οὐδὲν κινηθεὶς οὐδὲ στενάξας, ἀλλὰ καθεστῶτι τῷ προσώπῳ καὶ μετὰ σιωπῆς ὑπερβολάς τινας ἀλγηδόνων ἐν ταῖς τομαῖς ἀνασχόμενος· τοῦ δ’ ἰατροῦ μετιόντος ἐπὶ θάτερον οὐκέτι παρέσχε, φήσας ὁρᾶν τὸ ἐπανόρθωμα τῆς ἀλγηδόνος οὐκ ἄξιον.", "st": "Mar. 6.3"}, {"sp": "N", "t": "ἐπεὶ δὲ Καικίλιος Μέτελλος ἀποδειχθεὶς ἐπὶ τὸν κατὰ Ἰουγούρθα πόλεμον ὕπατος στρατηγὸς εἰς Λιβύην ἐπηγάγετο πρεσβευτὴν Μάριον, ἐνταῦθα πράξεων μεγάλων καὶ λαμπρῶν ἀγώνων ἐπιλαβόμενος τὸ μὲν αὔξειν τὸν Μέτελλον, ὥσπερ οἱ λοιποί, καὶ πολιτεύεσθαι πρὸς ἐκεῖνον εἴασε χαίρειν· ἀξιῶν δὲ οὐχ ὑπὸ Μετέλλου κεκλῆσθαι πρεσβευτής, ὑπὸ δὲ τῆς τύχης εἰς εὐφυέστατον καιρὸν ὁμοῦ καὶ μέγιστον εἰσάγεσθαι πράξεων θέατρον, ἐπεδείκνυτο πᾶσαν ἀνδραγαθίαν. καὶ πολλὰ τοῦ πολέμου δυσχερῆ φέροντος οὔτε τῶν μεγάλων τινὰ πόνων ὑποτρέσας οὔτε τῶν μικρῶν ἀπαξιώσας, ἀλλὰ τοὺς μὲν ὁμοτίμους εὐβουλίᾳ καὶ προνοίᾳ τοῦ συμφέροντος ὑπερβαλλόμενος, πρὸς δ’ τοὺς στρατιώτας ὑπὲρ εὐτελείας καὶ καρτερίας διαμιλλώμενος εὔνοιαν ἔσχε πολλὴν παρ’ αὐτοῖς. ὅλως μὲν γάρ ἔοικε τοῦ κάμνειν ἑκάστῳ παραμυθία τὸ συγκάμνον ἑκουσίως εἶναι· δοκεῖ γὰρ ἀφαιρεῖν τὴν ἀνάγκην· ἥδιστον δὲ Ῥωμαίῳ θέαμα στρατιώτῃ στρατηγὸς ἐσθίων ἐν ὄψει κοινὸν ἄρτον ἢ κατακείμενος ἐπὶ στιβάδος εὐτελοῦς ἢ περὶ ταφρείαν τινὰ καὶ χαράκωσιν ἔργου συνεφαπτόμενος, οὐ γάρ οὕτως τοὺς τιμῆς καὶ χρημάτων μεταδιδόντας ὡς τοὺς πόνου καὶ κινδύνου μεταλαμβάνοντας ἡγεμόνας θαυμάζουσιν, ἀλλὰ μᾶλλον ἀγαπῶσι τῶν ῥᾳθυμεῖν ἐπιτρεπόντων τοὺς συμπονεῖν ἐθέλοντας,", "st": "Mar. 7.1"}, {"sp": "N", "t": "ταῦτα πάντα ποιῶν ὁ Μάριος καὶ διὰ τούτων τοὺς στρατιώτας δημαγωγῶν ταχὺ μὲν ἐνέπλησε τὴν Λιβύην, ταχὺ δὲ τὴν Ῥώμην, ὀνόματος καὶ δόξης, τῶν ἀπὸ στρατοπέδου τοῖς οἴκοι γραφόντων ὡς οὐκ ἔστι πέρας οὐδὲ ἀπαλλαγὴ τοῦ πρὸς τὸν βάρβαρον πολέμου μὴ Γάϊον Μάριον ἑλομένοις ὕπατον.", "st": "Mar. 7.4"}, {"sp": "N", "t": "ἐφ’ οἷς δῆλος ἦν ὁ Μέτελλος ἀχθόμενος. μάλιστα δ’ αὐτὸν ἠνίασε τὸ περὶ Τουρπίλλιον. οὗτος γὰρ ὁ ἀνὴρ ἦν μὲν ἐκ πατέρων ξένος τῷ Μετέλλῳ καὶ τότε τὴν ἐπὶ τῶν τεκτόνων ἔχων ἀρχὴν συνεστράτευε· φρουρῶν δὲ Βάγαν, πόλιν μεγάλην, καὶ τῷ μηδὲν ἀδικεῖν τοὺς ἐνοικοῦντας, ἀλλὰ πράως καὶ φιλανθρώπως αὐτοῖς προσφέρεσθαι πιστεύων, ἔλαθεν ὑποχείριος τοῖς πολεμίοις γενόμενος. παρεδέξαντο γάρ τὸν Ἰουγούρθαν, τὸν δὲ Τουρπίλλιον οὐδὲν ἠδίκησαν, ἀλλὰ σῷον ἐξαιτησάμενοι διῆκαν. ἔσχεν οὖν αἰτίαν προδοσίας· καὶ παρὼν ὁ Μάριος τῇ κρίσει σύμβουλος αὐτὸς τέ οἱ πικρὸς ἦν καὶ τῶν ἄλλων παρώξυνε τοὺς πλείστους, ὥστε ἄκοντα τὸν Μέτελλον ἐκβιασθῆναι καὶ καταψηφίσασθαι θάνατον τοῦ ἀνθρώπου. μετ’ ὀλίγον δὲ τῆς αἰτίας ψευδοῦς φανείσης, οἱ μὲν ἄλλοι συνήχθοντο τῷ Μετέλλῳ βαρέως φέροντι, Μάριος δὲ χαίρων καὶ ποιούμενος ἴδιον τὸ ἔργον οὐκ ᾐσχύνετο λέγειν περιιών ὡς αὐτὸς εἴη προστετριμμένος ἀλάστορα τῷ Μετέλλῳ ξενοκτόνον.", "st": "Mar. 8.1"}, {"sp": "N", "t": "ἐκ τούτου φανερῶς ἀπηχθάνοντο· καὶ λέγεταί ποτε τοῦ Μαρίου παρόντος οἷον ἐφυβρίζων ὁ Μέτελλος εἰπεῖν, σὺ δὴ καταλιπὼν ἡμᾶς, ὦ γενναῖε, πλεῖν ἐπ’ οἴκου διανοῇ καὶ παραγγέλλειν ὑπατείαν; οὐ γάρ ἀγαπήσεις, ἂν τᾠμῷ παιδὶ τούτῳ συνυπατεύσῃς; ἦν δ’ ὁ παῖς τότε τοῦ Μετέλλου παντάπασι μειράκιον. οὐ μὴν ἀλλὰ τοῦ Μαρίου σπουδάζοντος ἀφεθῆναι, πολλὰς ἀναβολὰς ποιησάμενος, ἔτι δώδεκα λειπομένων ἡμερῶν ἐπὶ τὴν τῶν ὑπάτων ἀνάδειξιν, ἀφῆκεν αὐτόν, ὁ δὲ πολλὴν ἀπὸ στρατοπέδου τὴν ἐπὶ θάλασσαν εἰς Ἰτύκην ὁδὸν ἡμέραις δυσὶ καὶ μιᾷ νυκτὶ συνελών ἔθυε πρὸ τοῦ πλοῦ. καὶ λέγεται τὸν μάντιν εἰπεῖν ὡς ἀπίστους τινὰς τὸ μέγεθος καὶ κρείττονας ἐλπίδος ἁπάσης εὐπραξίας προφαίνοι τῷ Μαρίῳ τὸ δαιμόνιον. ὁ δὲ τούτοις ἐπαρθεὶς ἀνήχθη. καὶ τὸ πέλαγος τεταρταῖος οὐρίῳ πνεύματι περάσας αὐτίκα τε τῷ δήμῳ ποθεινὸς ὤφθη, καὶ προαχθεὶς ὑπό τινος τῶν δημάρχων εἰς τὸ πλῆθος ἐπὶ πολλαῖς κατὰ τοῦ Μετέλλου διαβολαῖς ᾐτεῖτο τὴν ἀρχήν, ὑπισχνούμενος ἢ κτενεῖν ἢ ζῶντα λήψεσθαι τὸν Ἰουγούρθαν.", "st": "Mar. 8.3"}, {"sp": "N", "t": "ἀναγορευθεὶς δὲ λαμπρῶς εὐθὺς ἐστρατολόγει, παρὰ τὸν νόμον καὶ τὴν συνήθειαν πολὺν τὸν ἄπορον καὶ φαῦλον καταγράφων, τῶν πρόσθεν ἡγεμόνων οὐ προσδεχομένων τοὺς τοιούτους, ἀλλ’, ὥσπερ ἄλλο τι τῶν καλῶν, τὰ ὅπλα μετὰ τιμῆς τοῖς ἀξίοις νεμόντων, ἐνέχυρον τὴν οὐσίαν ἑκάστου τιθέναι δοκοῦντος. οὐ μὴν ταῦτά γε μάλιστα διέβαλλε τὸν Μάριον, ἀλλ’ οἱ λόγοι θρασεῖς ὄντες ὑπεροψίᾳ καὶ ὕβρει τοὺς πρώτους ἐλύπουν, σκῦλόν τε βοῶντος αὐτοῦ τὴν ὑπατείαν φέρεσθαι τῆς τῶν εὐγενῶν καὶ πλουσίων μαλακίας, καὶ τραύμασιν οἰκείοις πρὸς τὸν δῆμον, οὐ μνήμασι νεκρῶν οὐδὲ ἀλλοτρίαις εἰκόσι νεανιεύεσθαι. πολλάκις δὲ καὶ τοὺς ἀτυχήσαντας ἐν Λιβύῃ στρατηγούς, τοῦτο μὲν Βηστίαν, τοῦτο δὲ Ἀλβῖνον, ἀνθρώπους οἴκων μὲν ἐπιφανῶν, αὐτοὺς δὲ τύχῃ σφαλέντας, ἀπολέμους καὶ δι’ ἀπειρίαν πταίσαντας ὀνομάζων, ἐπυνθάνετο τῶν παρόντων εἰ μὴ καὶ τοὺς ἐκείνων οἴονται προγόνους αὐτῷ μᾶλλον ἂν εὔξασθαι παραπλησίους ἐκγόνους ἀπολιπεῖν, ἅτε δὴ μηδὲ αὐτοὺς δι’ εὐγένειαν, ἀλλ’ ὑπ’ ἀρετῆς καὶ καλῶν ἔργων ἐνδόξους γενομένους. ταῦτα δὲ οὐ κενῶς οὐδὲ ἀλαζονικῶς ἔλεγεν οὐδὲ μάτην ἀπεχθάνεσθαι τοῖς δυνατοῖς βουλόμενος, ἀλλ’ ὁ δῆμος αὐτόν, ἡδόμενός τε τῇ βουλῇ προπηλακιζομένῃ καὶ λόγου κόμπῳ μετρῶν ἀεὶ φρονήματος μέγεθος, ἐξεκούφιζε, καὶ συνεξώρμα μὴ φείδεσθαι τῶν ἀξιολόγων, χαριζόμενον τοῖς πολλοῖς.", "st": "Mar. 9.1"}, {"sp": "N", "t": "ὡς δὲ διέπλευσεν εἰς Λιβύην, Μέτελλος μὲν ἥττων τοῦ φθόνου γενόμενος, καὶ περιπαθῶν ὅτι, κατειργασμένου τὸν πόλεμον αὐτοῦ καὶ μηδὲν ὑπόλοιπον ἣ τὸ σῶμα τοῦ Ἰουγούρθα λαβεῖν ἔχοντος, ἥκει Μάριος ἐπὶ τὸν στέφανον καὶ τὸν θρίαμβον, ἐκ τῆς πρὸς ἐκεῖνον ἀχαριστίας ηὐξημένος, οὐχ ὑπέμεινεν εἰς τὸ αὐτὸ συνελθεῖν, ἀλλ’ αὐτὸς μὲν ὑπεξεχώρησε, Ῥουτίλιος δὲ τὸ στράτευμα τῷ Μαρίῳ παρέδωκε, πρεσβευτὴς γεγονὼς τοῦ Μετέλλου. καὶ περιῆλθέ τις νέμεσις ἐν τῷ τέλει τῶν πράξεων Μάριον ἀφῃρέθη γάρ ὑπὸ Σύλλα τὴν τοῦ κατορθώματος δόξαν, ὡς ὑπ’ ἐκείνου Μέτελλος· ὃν τρόπον δέ, ἀφηγήσομαι βραχέως, ἐπεὶ τὰ καθ’ ἕκαστον μᾶλλον ἐν τοῖς περὶ Σύλλα γέγραπται.", "st": "Mar. 10.1"}, {"sp": "N", "t": "Βόκχος ὁ τῶν ἄνω βαρβάρων βασιλεὺς ἦν πενθερὸς Ἰουγούρθα, καὶ πολεμοῦντι μὲν οὐ πάνυ τι συλλαμβάνειν ἐδόκει, προβαλλόμενος αὐτοῦ τὴν ἀπιστίαν, καὶ τὴν αὔξησιν δεδοικώς· ἐπεὶ δὲ φεύγων καὶ πλανώμενος ἐκεῖνον ὑπ’ ἀνάγκης ἔθετο τῶν ἐλπίδων τελευταῖαν καὶ κατῆρε πρὸς αὐτόν, αἰσχύνῃ μᾶλλον ὡς ἱκέτην ἣ δι’ εὔνοιαν ὑποδεξάμενος διὰ χειρὸς εἶχε, φανερῶς μὲν ὑπὲρ αὐτοῦ παραιτούμενος Μάριον καὶ γράφων ὡς οὐκ ἂν ἐκδῴη καὶ παρρησιαζόμενος, κρύφα δὲ βουλεύων προδοσίαν ἐπ’ αὐτῷ, καὶ μεταπεμπόμενος Λεύκιον Σύλλαν, ταμίαν μὲν ὄντα Μαρίου, χρήσιμον δὲ τῷ Βόκχῳ γεγενημένον ἐπὶ στρατείας. ὡς δὲ πιστεύσας ἀνέβη πρὸς αὐτὸν ὁ Σύλλας, ἔσχε μέν τις τροπὴ γνώμης καὶ μετάνοια τὸν βάρβαρον, ἡ μέρας τε συχνὰς διηνέχθη τῷ λογισμῷ, βουλευόμενος ἣ παραδοῦναι τὸν Ἰουγούρθαν ἣ μηδὲ τὸν Σύλλαν ἀφεῖναι· τέλος δὲ τὴν προτέραν κυρώσας προδοσίαν, ἐνεχείρισε τῷ Σύλλᾳ ζῶντα τὸν Ἰουγούρθαν.", "st": "Mar. 10.3"}, {"sp": "N", "t": "καὶ τοῦτο πρῶτον ὑπῆρξεν αὐτοῖς σπέρμα τῆς ἀνηκέστου καὶ χαλεπῆς ἐκείνης στάσεως, ἣ μικρὸν ἐδέησεν ἀνατρέψαι τὴν Ῥώμην. πολλοὶ γάρ ἐβούλοντο τοῦ Σύλλα τὸ ἔργον εἶναι τῷ Μαρίῳ φθονοῦντες, αὐτός τε Σύλλας σφραγῖδα ποιησάμενος ἐφόρει γλυφὴν ἔχουσαν ἐγχειριζόμενον ὑπὸ τοῦ Βόκχου τὸν Ἰουγούρθαν ἑαυτῷ. καὶ ταύτῃ χρώμενος ἀεὶ διετέλει φιλότιμον ἄνδρα καὶ πρὸς κοινωνίαν δόξης ἀγνώμονα, καὶ δύσεριν ἐρεθίζων τὸν Μάριον, ἐναγόντων μάλιστα τῶν ἐχθρῶν τῶν ἐκείνου, καὶ τὰ μὲν πρῶτα τοῦ πολέμου καὶ μέγιστα τῷ Μετέλλῳ, τὰ δ’ ἔσχατα καὶ τὸ πέρας αὐτοῦ Σύλλᾳ προστιθέντων, ὡς παύσαιτο θαυμάζων καὶ προσέχων ἐκείνῳ μάλιστα πάντων ὁ δῆμος.", "st": "Mar. 10.5"}, {"sp": "N", "t": "ταχὺ μέντοι τὸν φθόνον τοῦτον καὶ τὰ μίση καὶ τὰς διαβολὰς ἀπεσκέδασε τοῦ Μαρίου καὶ μετέστησεν ὁ κατασχὼν τὴν Ἰταλίαν ἀπὸ τῆς ἑσπέρας κίνδυνος, ἅμα τῷ πρῶτον ἐν χρείᾳ μεγάλου στρατηγοῦ γενέσθαι καὶ περισκέψασθαι τὴν πόλιν ᾧ χρωμένη κυβερνήτῃ διαφεύξεται κλύδωνα πολέμου τοσοῦτον, οὐδενὸς ἀνασχομένου τῶν ἀπὸ γένους μεγάλων ἢ πλουσίων οἴκων ἐπὶ τὰς ὑπατικὰς κατιόντων ἀρχαιρεσίας, ἀλλ’ ἀπόντα τὸν Μάριον ἀναγορευσάντων. ἄρτι γάρ ἀπηγγελμένης αὐτοῖς τῆς Ἰουγούρθα συλλήψεως αἵ περὶ Τευτόνων καὶ Κίμβρων φῆμαι προσέπιπτον, ἀπιστίαν μὲν ἐν ἀρχῇ παρασχοῦσαι πλήθους τε καὶ ῥώμης τῶν ἐπερχομένων στρατῶν, ὕστερον δὲ τῆς ἀληθείας ὑποδεέστεραι φανεῖσαι. μυριάδες μὲν γὰρ αἱ μάχιμοι τριάκοντα σὺν ὅπλοις ἐχώρουν, ὄχλοι δὲ παίδων καὶ γυναικῶν ἐλέγοντο πολλῷ πλείους συμπεριάγεσθαι, γῆς χρῄζοντες θρέψει τοσοῦτον πλῆθος, καὶ πόλεων ἐν αἷς ἱδρυθέντες βιώσονται, καθάπερ πρὸ αὐτῶν ἐπυνθάνοντο Κελτοὺς τῆς Ἰταλίας τὴν ἀρίστην κατασχεῖν Τυρρηνῶν ἀφελομένους. αὐτοὶ μὲν γάρ ἀμειξίᾳ, τῇ πρὸς ἑτέρους, μήκει τε χώρας ἣν ἐπῆλθον, ἠγνοοῦντο, τίνες ὄντες ἀνθρώπων ἢ πόθεν ὁρμηθέντες ὥσπερ νέφος ἐμπέσοιεν Γαλατίᾳ καὶ Ἰταλίᾳ. καὶ μάλιστα μὲν εἰκάζοντο Γερμανικὰ γένη τῶν καθηκόντων ἐπὶ τὸν βόρειον ὠκεανὸν εἶναι τοῖς μεγέθεσι τῶν σωμάτων καὶ τῇ χαροπότητι τῶν ὀμμάτων, καὶ ὅτι Κίμβρους ἐπονομάζουσι Γερμανοὶ τοὺς λῃστάς.", "st": "Mar. 11.1"}, {"sp": "N", "t": "εἰσὶ δὲ οἳ τὴν Κελτικὴν διὰ βάθος χώρας καὶ μέγεθος ἀπὸ τῆς ἔξω θαλάσσης καὶ τῶν ὑπαρκτίων κλιμάτων πρὸς ἥλιον ἀνίσχοντα κατὰ τὴν Μαιῶτιν ἐπιστρέφουσαν ἅπτεσθαι τῆς Ποντικῆς Σκυθίας λέγουσι, κἀκεῖθεν τὰ γένη μεμεῖχθαι. τούτους ἐξαναστάντας οὐκ ἐκ μιᾶς ὁρμῆς οὐδὲ συνεχῶς, ἀλλὰ ἔτους ὥρᾳ καθ’ ἕκαστον ἐνιαυτὸν εἰς τοὔμπροσθεν ἀεὶ χωροῦντας πολέμῳ χρόνοις πολλοῖς ἐπελθεῖν τὴν ἤπειρον. διὸ καὶ πολλὰς κατὰ μέρος ἐπικλήσεις ἐχόντων κοινῇ Κελτοσκύθας τὸν στρατὸν ὠνόμαζον.", "st": "Mar. 11.4"}, {"sp": "N", "t": "ἄλλοι δέ φασι Κιμμερίων τὸ μὲν πρῶτον ὑφ’ Ἑλλήνων τῶν πάλαι γνωσθὲν οὐ μέγα γενέσθαι τοῦ παντὸς μόριον, ἀλλὰ φυγὴν ἢ στάσιν τινὰ βιασθεῖσαν ὑπὸ Σκυθῶν εἰς Ἀσίαν ἀπὸ τῆς Μαιώτιδος διαπερᾶσαι Λυγδάμιος ἡγουμένου, τὸ δὲ πλεῖστον αὐτῶν καὶ μαχιμώτατον ἐπ’ ἐσχάτοις οἰκοῦν παρὰ τὴν ἔξω θάλασσαν γῆν μὲν νέμεσθαι σύσκιον καὶ ὑλώδη καὶ δυσήλιον πάντῃ διὰ βάθος καὶ πυκνότητα δρυμῶν, οὓς μέχρι τῶν Ἑρκυνίων εἴσω διήκειν, οὐρανοῦ δὲ εἰληχέναι καθ’ ὃ δοκεῖ μέγα λαμβάνων ὁ πόλος ἔξαρμα διὰ τὴν ἔγκλισιν τῶν παραλλήλων ὀλίγον ἀπολείπειν τοῦ κατὰ κορυφὴν ἱσταμένου σημείου πρὸς τὴν οἴκησιν, αἵ τε ἡμέραι βραχύτητι καὶ μήκει πρὸς τὰς νύκτας ἴσαι κατανέμεσθαι τὸν χρόνον· διὸ καὶ τὴν εὐπορίαν τοῦ μυθεύματος Ὁμήρῳ γενέσθαι πρὸς τὴν νεκυίαν. ἔνθεν οὖν τὴν ἔφοδον εἶναι τῶν βαρβάρων τούτων ἐπὶ τὴν Ἰταλίαν, Κιμμερίων μὲν ἐξ ἀρχῆς, τότε δὲ Κίμβρων οὐκ ἀπὸ τρόπου προσαγορευομένων. ἀλλὰ ταῦτα μὲν εἰκασμῷ μᾶλλον ἢ κατὰ βέβαιον ἱστορίαν λέγεται.", "st": "Mar. 11.6"}, {"sp": "N", "t": "τὸ δὲ πλῆθος οὐκ ἔλαττον, ἀλλὰ πλέον εἶναι τοῦ λεχθέντος ὑπὸ πολλῶν ἱστόρηται. θυμὸν δὲ καὶ τόλμαν ἀνυπόστατοι καὶ χειρῶν ἔργα παοὰ τὰς μάχας ὀξύτητι καὶ βίᾳ πυρὸς ἐοικότες ἐπῄεσαν, οὐδενὸς ἀντέχοντος αὐτῶν πρὸς τὴν ἔφοδον, ἀλλὰ πάντων μέν, ὅσους ἐπῆλθον, ἐν λόγῳ λείας ἀγομένων καὶ φερομένων, πολλῶν δὲ καὶ μεγάλων Ῥωμαϊκῶν στρατοπέδων καὶ στρατηγῶν, ὅσοι προεκάθηντο τῆς ἐκτὸς Ἄλπεων Γαλατίας, ἀνηρπασμένων ἀκλεῶς· οἳ καὶ μάλιστα τὴν φορὰν αὐτῶν κακῶς ἀγωνισάμενοι κατὰ τῆς Ῥώμης ἐπεσπάσαντο. νικήσαντες γὰρ οἷς ἐνέτυχον, καὶ χρημάτων πολλῶν κρατήσαντες; ἔγνωσαν μηδαμοῦ γῆς ἑαυτοὺς ἱδρύειν, πρὶν ἀνατρέψωσι τὴν Ῥώμην καὶ διαπορθήσωσι τὴν Ἰταλίαν.", "st": "Mar. 11.8"}, {"sp": "N", "t": "ταῦτα Ῥωμαῖοι πυνθανόμενοι πολλαχόθεν, ἐκάλουν Μάριον ἐπὶ τὴν στρατηγίαν. καὶ τὸ δεύτερον ὕπατος ἀπεδείχθη, τοῦ μὲν νόμου κωλύοντος ἀπόντα καὶ μὴ διαλιπόντα χρόνον ὡρισμένον αὖθις αἱρεῖσθαι, τοῦ δὲ δήμου τοὺς ἀντιλέγοντας ἐκβαλόντος. ἡγοῦντο γὰρ οὔτε νῦν πρῶτον εἴξειν τῷ συμφέροντι τὸν νόμον, οὔτε ἀλογωτέραν εἶναι τὴν παροῦσαν αἰτίαν ἐκείνης δι’ ἣν τὸν Σκιπίωνα παρὰ τοὺς νόμους ὕπατον ἀπέδειξαν, οὐ φοβούμενοι τὴν ἑαυτῶν ἀποβαλεῖν, ἀλλὰ τὴν Καρχηδονίων ἐπιθυμοῦντες ἀνελεῖν. ταῦτα ἔδοξε· καὶ Μάριος ἐκ Λιβύης μετὰ τοῦ στρατεύματος διακομισθεὶς αὐταῖς Καλάνδαις Ἰανουαρίαις, ἣν ἔτους ἀρχὴν ἄγουσι Ῥωμαῖοι, τήν τε ὑπατείαν ἀνέλαβε καὶ τὸν θρίαμβον εἰσήλασεν, ἄπιστον ἐπιδειξάμενος θέαμα Ῥωμαίοις Ἰουγούρθαν αἰχμάλωτον, οὗ ζῶντος οὐδ’ ἂν εἷς ἤλπισε πολεμίων κρατῆσαι οὕτω τις ἦν ποικίλος ἀνήρ τύχαις ὁμιλῆσαι καὶ πανουργίᾳ πολλῇ μεμειγμένον ἔχων τὸ θυμοειδές. ἀλλ’ ἐξέστη γε πομπευθεὶς, ὡς λέγουσι, τότε τοῦ φρονεῖν· καὶ μετὰ τὸν θρίαμβον εἷς τὸ δεσμωτήριον ἐμπεσών, ὡς οἱ μὲν αὐτοῦ βίᾳ περιέρρηξαν τὸν χιτωνίσκον, οἱ δὲ σπεύδοντες ἀφελέσθαι βίᾳ τὸ χρυσοῦν ἐλλόβιον ἅμα τὸν λοβὸν συναπέρρηξαν, ὠσθεὶς δὲ γυμνὸς εἷς τὸ βάραθρον κατεβλήθη, μεστὸς ὢν ταραχῆς καὶ διασεσηρώς, Ἡράκλεις, εἶπεν, ὡς ψυχρὸν ὑμῶν τὸ βαλανεῖον. ἀλλὰ τοῦτον μὲν ἓξ ἡμέραις ζυγομαχήσαντα τῷ λιμῷ καὶ μέχρι τῆς ἐσχάτης ὥρας ἐκκρεμασθέντα τῆς τοῦ ζῆν ἐπιθυμίας εἶχεν ἀξία δίκη τῶν ἀσεβημάτων.", "st": "Mar. 12.1"}, {"sp": "N", "t": "ἐν δὲ τῷ θριάμβῳ κομισθῆναι λέγουσι χρυσοῦ μὲν ἑπτὰ καὶ τρισχιλίας λίτρας, ἀργύρου δὲ ἀσήμου πεντακισχιλίας ἑπτακοσίας ἑβδομήκοντα πέντε, νομίσματος δὲ δραχμὰς ἑπτακισχιλίας ἐπὶ μυριάσιν ὀκτὼ καὶ εἴκοσι.", "st": "Mar. 12.1b"}, {"sp": "N", "t": "μετὰ δὲ τὴν πομπὴν ὁ Μάριος σύγκλητον ἤθροισεν ἐν Καπετωλίῳ· καὶ παρῆλθε μὲν εἴτε λαθὼν αὑτὸν εἴτε τῇ τύχῃ χρώμενος ἀγροικότερον ἐν τῇ θριαμβικῇ κατασκευῇ, ταχὺ δὲ τὴν βουλὴν ἀχθεσθεῖσαν αἰσθόμενος ἐξανέστη καὶ μεταλαβὼν τὴν περιπόρφυρον αὖθις ἦλθεν.", "st": "Mar. 12.5"}, {"sp": "N", "t": "ἐν δὲ τῇ στρατείᾳ τὴν δύναμιν διεπόνει καθ’ ὁδὸν ἐξασκῶν δρόμοις τε παντοδαποῖς καὶ μακραῖς ὁδοιπορίαις, ἑαυτῷ δὲ ἀχθοφορεῖν ἀναγκάζων καὶ αὐτουργεῖν τὰ πρὸς τὴν δίαιταν, ὥστε καὶ μετὰ ταῦτα τοὺς φιλοπόνους καὶ σιωπῇ μετ’ εὐκολίας τὰ προστασσόμενα ποιοῦντας ἡμιόνους Μαριανοὺς καλεῖσθαι. καίτοι τινὲς αἰτίαν ἑτέραν τὸν λόγου τούτου νομίζουσι. Σκηπίωνος γάρ, ὅτε Νομαντίαν ἐπολιόρκει, βουληθέντος ἐπιδεῖν μὴ μόνον τὰ ὅπλα μηδὲ τοὺς ἵππους, ἀλλὰ καὶ τοὺς ὀρεῖς καὶ τὰς ἁμάξας, ὅπως ἑκάστοις ἐξησκημένα καὶ παρεσκευασμένα τυγχάνοι, προαγαγεῖν τὸν Μάριον ἵππον τε κάλλιστα τεθραμμένον ὑπ’ αὐτοῦ καὶ ἡμίονον εὐεξίᾳ καὶ πρᾳότητι καὶ ῥώμῃ διαφέροντα πολὺ τῶν ἄλλων ἡσθέντος οὖν τοῦ στρατηγοῦ τοῖς τοῦ Μαρίου θρέμμασι καὶ πολλάκις αὐτῶν μνησθέντος, οὕτως ἄρα τοὺς σκώπτοντας ἐν ἐπαίνῳ τὸν ἐνδελεχῆ καὶ τλήμονα καὶ φιλόπονον Μαριανὸν ἡμίονον προσαγορεύειν.", "st": "Mar. 13.1"}, {"sp": "N", "t": "εὐτύχημα δὲ δοκεῖ τῷ Μαρίῳ μέγα γενέσθαι, τῶν γάρ βαρβάρων ὥσπερ τινὰ παλίρροιαν τῆς ὁρμῆς λαβόντων καὶ ῥυέντων πρότερον ἐπὶ τὴν Ἰβηρίαν, χρόνον ἔσχε καὶ τὰ σώματα γυμνάσαι τῶν ἀνδρῶν καὶ τὰ φρονήματα πρὸς τὸ θαρρεῖν ἀναρρῶσαι, τὸ δὲ μέγιστον, αὐτὸς οἷος ἦν κατανοηθῆναι. τὸ γὰρ ἐν ἀρχῇ σκυθρωπὸν αὐτοῦ καὶ περὶ τὰς τιμωρίας δυσμείλικτον ἐθισθεῖσι μηδὲν ἁμαρτάνειν μηδὲ ἀπειθεῖν ἅμα τῷ δικαίῳ σωτήριον ἐφαίνετο, τήν τε τοῦ θυμοῦ σφοδρότητα καὶ τὸ τραχὺ τῆς φωνῆς καὶ ἀγριωπὸν τοῦ προσώπου συντρεφόμενον κατὰ μικρὸν οὐχ αὑτοῖς ἐνόμιζον εἶναι φοβερόν, ἀλλὰ τοῖς πολεμίοις. μάλιστα δὲ ἡ περὶ τὰς κρίσεις ὀρθότης αὐτοῦ τοῖς στρατιώταις ἤρεσκεν ἧς καὶ τοιόνδε τι δεῖγμα λέγεται.", "st": "Mar. 14.1"}, {"sp": "N", "t": "Γάϊος Λούσιος ἀδελφιδοῦς αὐτοῦ τεταγμένος ἐφ’ ἡγεμονίας ἐστρατεύετο, τάχα μὲν ἀνήρ οὐ δοκῶν εἶναι πονηρός, ἥττων δὲ μειρακίων καλῶν. οὗτος ἤρα νεανίσκου τῶν ὐφ’ αὑτῷ στρατευομένων, ὄνομα Τρεβωνίου, καὶ πολλάκις πειρῶν οὐκ ἐτύγχανε· τέλος δὲ νύκτωρ ὑπηρέτην ἀποστείλας μετεπέμπετο τὸν Τρεβώνιον· ὁ δὲ νεανίας ἧκε μέν, ἀντειπεῖν γὰρ οὐκ ἐξῆν καλούμενον, εἰσαχθεὶς δὲ ὑπὸ τὴν σκηνὴν πρὸς αὐτὸν ἐπιχειροῦντα βιάζεσθαι σπασάμενος τὸ ξίφος ἀπέκτεινε. ταῦτα ἐπράχθη τοῦ Μαρίου μὴ παρόντος· ἐπανελθὼν δὲ προὔθηκε τῷ Τρεβωνίῳ κρίσιν· ἐπεὶ δὲ πολλῶν κατηγορούντων, οὐδενὸς δὲ συνηγοροῦντος, αὐτὸς εὐθαρσῶς καταστὰς διηγήσατο τὸ πρᾶγμα καὶ μάρτυρας ἔσχεν ὅτι πειρῶντι πολλάκις ἀντεῖπε τῷ Λουσίῳ καὶ μεγάλων διδομένων ἐπ’ οὐδενὶ προήκατο τὸ σῶμα, θαυμάσας ὁ Μάριος καὶ ἡσθεὶς ἐκέλευσε τὸν πάτριον ἐπὶ ταῖς ἀριστείαις στέφανον κομισθῆναι, καὶ λαβὼν αὐτὸς ἐστεφάνωσε τὸν Τρεβώνιον ὡς κάλλιστον ἔργον ἐν καιρῷ παραδειγμάτων δεομένῳ καλῶν ἀποδεδειγμένον·", "st": "Mar. 14.4"}, {"sp": "N", "t": "τοῦτο εἰς τὴν Ῥώμην ἀπαγγελθὲν οὐχ ἥκιστα τῷ Μαρίῳ συνέπραξε τὴν τρίτην ὑπατείαν ἅμα δὲ καὶ τῶν βαρβάρων ἔτους ὥρᾳ προσδοκίμων ὄντων ἐβούλοντο μετὰ μηδενὸς ἄλλου στρατηγοῦ κινδυνεῦσαι πρὸς αὐτούς, οὐ μὴν ἧκον ὡς προσεδοκῶντο ταχέως, ἀλλὰ πάλιν διῆλθε τῷ Μαρίῳ ὁ τῆς ὑπατείας χρόνος. ἐνισταμένων δὲ τῶν ἀρχαιρεσιῶν καὶ τοῦ συνάρχοντος αὐτοῦ τελευτήσαντος, ἀπολιπὼν ἐπὶ τῶν δυνάμεων Μάνιον Ἀκύλλιον αὐτὸς ἧκεν εἰς Ῥώμην. μετιόντων δὲ πολλῶν καὶ ἀγαθῶν τὴν ὑπατείαν, Λούκιος Σατορνῖνος ὁ μάλιστα τῶν δημάρχων ἄγων τὸ πλῆθος, ὑπὸ τοῦ Μαρίου τεθεραπευμένος ἐδημηγόρει, κελεύων ἐκεῖνον ὕπατον αἱρεῖσθαι. θρυπτομένου δὲ τοῦ Μαρίου καὶ παραιτεῖσθαι τὴν ἀρχὴν φάσκοντος ὡς δὴ μὴ δεομένου, προδότην αὐτὸν ὁ Σατορνῖνος ἀπεκάλει τῆς πατρίδος ἐν κινδύνῳ τοσούτῳ φεύγοντα τὸ στρατηγεῖν. καὶ φανερὸς μὲν ἦν ἀπιθάνως συνυποκρινόμενος τὸ προσποίημα τῷ Μαρίῳ, τὸν δὲ καιρὸν ὁρῶντες οἱ πολλοὶ τῆς ἐκείνου δεινότητος ἅμα καὶ τύχης δεόμενον ἐψηφίσαντο τὴν τετάρτην ὑπατείαν, καὶ συνάρχοντα Κάτλον αὐτῷ Λουτάτιον κατέστησαν, ἄνδρα καὶ τιμώμενον ὑπὸ τῶν ἀρίστων καὶ τοῖς πολλοῖς οὐκ ἐπαχθῆ.", "st": "Mar. 14.6"}, {"sp": "N", "t": "πυνθανόμενος δὲ τοὺς πολεμίους ὁ Μάριος ἐγγὺς εἶναι διὰ ταχέων ὐπερέβαλε τὰς Ἄλπεις· καὶ τειχίσας στρατόπεδον παρὰ τῷ Ῥοδανῷ ποταμῷ συνῆγεν εἰς αὐτὸ χορηγίαν ἄφθονον, ὡς μηδέποτε παρὰ τὸν τοῦ συμφέροντος λογισμὸν ἐκβιασθείη δι’ ἔνδειαν τῶν ἀναγκαίων εἰς μάχην καταστῆναι. τὴν δὲ κομιδὴν ὧν ἔδει τῷ στρατεύματι μακρὰν καὶ πολυτελῆ πρότερον οὖσαν πρὸς τὴν θάλασσαν, αὐτὸς εἰργάσατο ῥᾳδίαν καὶ ταχεῖαν. τὰ γάρ στόματα τοῦ Ῥοδανοῦ, πρὸς τὰς ἀνακοπὰς τῆς θαλάττης, ἰλύν τε πολλὴν λαμβάνοντα καὶ θῖνα πηλῷ βαθεῖ συμπεπιλημένην ὑπὸ τοῦ κλύδωνος, χαλεπὸν καὶ ἐπίπονον καὶ βραδύπορον τοῖς σιταγωγοῖς ἐποίει τὸν εἴσπλουν. ὁ δὲ τρέψας ἐνταῦθα τὸν στρατὸν σχολάζοντα τάφρον μεγάλην ἐνέβαλε, καὶ ταύτῃ πολύ μέρος τοῦ ποταμοῦ μεταστήσας περιήγαγεν εἰς ἐπιτήδειον αἰγιαλόν, βαθὺ μὲν καὶ ναυσὶ μεγάλαις ἔποχον, λεῖον δὲ καὶ ἄκλυστον στόμα λαβοῦσαν πρὸς τὴν θάλασσαν. αὕτη μὲν οὖν ἔτι ἀπ’ ἐκείνου τὴν ἐπωνυμίαν φυλάττει.", "st": "Mar. 15.1"}, {"sp": "N", "t": "τῶν δὲ βαρβάρων διελόντων σφᾶς αὐτοὺς δίχα Κίμβροι μὲν ἔλαχον διὰ Νωρικῶν ἄνωθεν ἐπὶ Κάτλον χωρεῖν καὶ τὴν πάροδον ἐκείνην βιάζεσθαι, Τεύτονες δὲ καὶ Ἄμβρωνες διὰ Λιγύων ἐπὶ Μάριον παρὰ θάλατταν. καὶ Κίμβροις μέν ἐγίνετο πλείων ἡ διατριβὴ καὶ μέλλησις, Τεύτονες δὲ καὶ Ἄμβρωνες ἄραντες εὐθὺς καὶ διελθόντες τὴν ἐν μέσῳ χώραν ἐφαίνοντο πλήθει τε ἄπειροι καὶ δυσπρόσοπτοι τὰ εἴδη, φθόγγον τε καὶ θόρυβον οὐχ ἑτέροις ὅμοιοι. περιβαλόμενοι δὲ τοῦ πεδίου μέγα μέρος καὶ στρατοπεδεύσαντες προὐκαλοῦντο τὸν Μάριον εἰς μάχην.", "st": "Mar. 15.4"}, {"sp": "N", "t": "ὁ δὲ τούτων μὲν οὐκ ἐφρόντιζεν, ἐν δὲ τῷ χάρακι τοὺς στρατιώτας συνεῖχε, καὶ καθήπτετο πικρῶς τῶν θρασυνομένων, καὶ τοὺς προπίπτοντας ὑπὸ θυμοῦ καὶ μάχεσθαι βουλομένους προδότας ἀπεκάλει τῆς πατρίδος, οὐ γάρ ὑπὲρ θριάμβων τὴν φιλοτιμίαν εἶναι καὶ τροπαίων, ἀλλ’ ὅπως νέφος τοσοῦτον πολέμου καὶ σκηπτὸν ὠσάμενοι διασώσουσι τὴν Ἰταλίαν. ταῦτα μὲν ἰδίᾳ πρὸς τοὺς ἡγεμόνας καὶ τοὺς ὁμοτίμους ἔλεγε, τοὺς δὲ στρατιώτας ὑπὲρ τοῦ χάρακος ἱστὰς ἀνὰ μέρος καὶ θεᾶσθαι κελεύων εἴθιζε τὴν μορφὴν ἀνέχεσθαι τῶν πολεμίων καὶ τήν φωνὴν ὑπομένειν ὅλως οὖσαν ἀλλόκοτον καὶ θηριώδη, σκευήν τε καὶ κίνησιν αὐτῶν καταμανθάνειν, ἅμα τῷ χρόνῳ τὰ φαινόμενα δεινὰ ποιουμένους τῇ διανοίᾳ χειροήθη διὰ τῆς ὄψεως· ἡγεῖτο γὰρ πολλὰ μὲν ἐπιψεύδεσθαι τῶν οὐ προσόντων τὴν καινότητα τοῖς φοβεροῖς, ἐν δὲ τῇ συνηθείᾳ καὶ τὰ τῇ φύσει δεινὰ τὴν ἔκπληξιν ἀποβάλλειν. τῶν δὲ οὐ μόνον ἡ καθ’ ἡμέραν ὄψις ἀφῄρει τι τοῦ θάμβους, ἀλλὰ καὶ πρὸς τὰς ἀπειλὰς τῶν βαρβάρων καὶ τὸν κόμπον οὐκ ἀνεκτὸν ὄντα θυμὸς αὐτοῖς παριστάμενος ἐξεθέρμαινε καὶ διέφλεγε τὰς ψυχάς, οὐ μόνον ἀγόντων καὶ φερόντων τὰ πέριξ ἅπαντα τῶν πολεμίων, ἀλλὰ καὶ τῷ χάρακι ποιουμένων προσβολὰς μετὰ πολλῆς ἀσελγείας καὶ θρασύτητος, ὥστε φωνὰς καὶ διαγανακτήσεις τῶν στρατιωτῶν πρὸς τὸν Μάριον ἐκφέρεσθαι. τίνα δὴ καταγνοὺς ἀνανδρίαν ἡμῶν Μάριος εἴργει μάχης ὥσπερ γυναῖκας ὑπὸ κλεισὶ καὶ θυρωροῖς; φέρε, παθόντες ἀνδρῶν πάθος ἐλευθέρων ἐρώμεθα πότερον ἄλλους ἀναμένει μαχουμένους ὑπὲρ τῆς Ἰταλίας, ἡμῖν δὲ λειτουργοῖς χρήσεται διὰ παντός, ὅταν δέῃται τάφρους ὀρύσσειν καὶ πηλὸν ἐκκαθαίρειν καὶ ποταμούς τινας παρατρέπειν; ἐπὶ ταῦτα γάρ, ὡς ἔοικεν, ἤσκει τοῖς πολλοῖς πόνοις ἡμᾶς, καὶ ταῦτα τῶν ὑπατειῶν ἀποδειξάμενος ἔργα τοῖς πολίταις ἐπάνεισιν. ἢ τὰ Κάρβωνος αὐτὸν φοβεῖ καὶ Καιπίωνος, οὓς ἐνίκησαν οἱ πολέμιοι, πολὺ μὲν αὐτοὺς τῆς Μαρίου δόξης καὶ ἀρετῆς ἀποδέοντας, πολὺ δὲ χείρονα στρατὸν ἄγοντας; ἀλλὰ καὶ παθεῖν τι δρῶντας, ὡς ἐκεῖνοι, κάλλιον ἢ καθῆσθαι πορθουμένων τῶν συμμάχων θεατάς.", "st": "Mar. 16.1"}, {"sp": "N", "t": "ταῦτ’ ἀκούων ὁ Μάριος ἥδετο, καὶ κατεπράυνεν αὐτούς ὡς οὐκ ἐκείνοις ἀπιστῶν, ἀλλ’ ἔκ τινων λογίων τὸν τῆς νίκης ἅμα καιρὸν καὶ τόπον ἐκδεχόμενος. καὶ γάρ τινα Σύραν γυναῖκα, Μάρθαν ὄνομα, μαντεύεσθαι λεγομένην ἐν φορείῳ κατακειμένην σεμνῶς περιήγετο, καὶ θυσίας ἔθυεν ἐκείνης κελευούσης. ἣν πρότερον μὲν ἀπήλασεν ἡ σύγκλητος ἐντυχεῖν ὑπὲρ τούτων βουλομένην καὶ τὰ μέλλοντα προθεσπίζουσαν, ἐπεὶ δὲ πρὸς τὰς γυναῖκας εἰσιοῦσα διάπειραν ἐδίδου καὶ μάλιστα τῇ Μαρίου παρακαθίζουσα παρὰ τοὺς πόδας τῶν μονομάχων ἐπιτυχῶς προηγόρευε τὸν μέλλοντα νικᾶν, ἀναπεμφθεῖσα πρὸς Μάριον ὑπ’· ἐκείνης ἐθαυμάζετο. καὶ τὰ πολλὰ μὲν ἐν φορείῳ παρεκομίζετο, πρὸς δὲ τὰς θυσίας κατῄει φοινικίδα διπλῆν ἐμπεπορπημένη καὶ λόγχην ἀναδεδεμένην ταινίαις καὶ στεφανώμασι φέρουσα. τοῦτο μὲν οὖν τὸ δρᾶμα πολλοῖς ἀμφισβήτησιν παρεῖχεν, εἴτε πεπεισμένος ὡς ἀληθῶς εἴτε πλαττόμενος καὶ συνυποκρινόμενος ἐπιδείκνυται τὴν ἄνθρωπον.", "st": "Mar. 17.1"}, {"sp": "N", "t": "τὸ δὲ περὶ τοὺς γῦπας θαύματος ἄξιον Ἀλέξανδρος ὁ Μύνδιος ἱστόρηκε. δύο γὰρ ἐφαίνοντο πρὸ τῶν κατορθωμάτων ἀεὶ περὶ τὰς στρατιὰς καὶ παρηκολούθουν γνωριζόμενοι χαλκοῖς περιδεραίοις· ταὐτὰ δὲ οἱ στρατιῶται συλλαβόντες αὐτούς περιῆψαν, εἶτα ἀφῆκαν· ἐκ δὲ τούτου γνωρίζοντες ἠσπάζοντο αὐτούς οἱ στρατιῶται καὶ φανέντων ἐπὶ ταῖς ἐξόδοις ἔχαιρον ὡς ἀγαθὸν τι πράξοντες.", "st": "Mar. 17.1b"}, {"sp": "N", "t": "πολλῶν δὲ σημείων πρὸ φαινομένων τὰ μὲν ἄλλα χαρακτῆρα κοινὸν εἶχεν, ἐκ δὲ Ἀμερίας καὶ Τουδέρτου, πόλεων Ἰταλικῶν, ἀπηγγέλθη νυκτὸς ὦφθαι κατὰ τὸν οὐρανὸν αἰχμάς τε φλογοειδεῖς καὶ θυρεοὺς διαφερομένους τὸ πρῶτον, εἶτα συμπίπτοντας ἀλλήλοις καὶ σχήματα καὶ κινήματα λαμβάνοντας οἷα γίνεται μαχομένων ἀνδρῶν, τέλος δὲ τῶν μὲν ἐνδιδόντων, τῶν δὲ ἐπιφερομένων, πάντας ἐπὶ δυσμὰς ῥυῆναι. περὶ τοῦτον δέ πως τὸν χρόνον ἀφίκετο καὶ Βατάκης ἐκ Πεσσινοῦντος ὁ τῆς Μεγάλης Μητρὸς ἱερεύς, ἀπαγγέλλων ὡς ἡ θεὸς ἐκ τῶν ἀνακτόρων ἐφθέγξατο αὐτῷ νίκην καὶ κράτος πολέμου Ῥωμαίοις ὑπάρχειν. τῆς δὲ συγκλήτου προσεμένης καὶ τῇ θεῷ ναὸν ἐπινίκιον ἱδρύσασθαι ψηφισαμένης, τὸν Βατάκην εἰς τὸν δῆμον προελθόντα καὶ ταὐτὰ βουλόμενον εἰπεῖν ἐκώλυσε δημαρχῶν Αὖλος Πομπήϊος, ἀγύρτην ἀποκαλῶν καὶ πρὸς ὕβριν ἀπελαύνων τοῦ βήματος δὲ δὴ καὶ μάλιστα τῷ λόγῳ τοῦ ἀνθρώπου πίστιν παρέσχεν. οὐ γάρ ἔφθη τῆς ἐκκλησίας λυθείσης ὁ Αὖλος εἰς οἶκον ἐπανελθεῖν, καὶ πυρετὸς ἐξήνθησεν αὐτῷ τοσοῦτος ὥστε πᾶσι καταφανῆ γενόμενον καὶ περιβόητον ἐντὸς ἑβδόμης ἡμέρας ἀποθανεῖν.", "st": "Mar. 17.4"}, {"sp": "N", "t": "οἱ δὲ Τεύτονες ἐπεχείρησαν μὲν ἡσυχάζοντος τοῦ Μαρίου πολιορκεῖν τὸ στρατόπεδον, βέλεσι δὲ πολλοῖς ἐντυχόντες ἀπὸ τοῦ χάρακος φερομένοις καί τινας ἓξ αὑτῶν ἀποβαλόντες ἔγνωσαν εἰς τοὔμπροσθεν χωρεῖν ὡς ὑπερβαλοῦντες ἀδεῶς τὰς Ἄλπεις· καὶ συσκευασάμενοι παρήμειβον τὸ στρατόπεδον τῶν Ῥωμαίων, τότε δὴ μάλιστα παμπληθεῖς μήκει καὶ χρόνῳ τῆς παρόδου φανέντες· ἡμέραις γὰρ ἓξ λέγονται τὸν χάρακα τοῦ Μαρίου παραμείψασθαι συνεχῶς ὁδεύοντες. ἐπορεύοντο δὲ ἐγγύς, πυνθανόμενοι τῶν Ῥωμαίων μετὰ γέλωτος εἴ τι πρὸς τὰς γυναῖκας ἐπιστέλλοιεν αὐτοὶ γάρ ἔσεσθαι ταχέως παρ’ αὐταῖς. ἐπεὶ δὲ παρήλλαξαν οἱ βάρβαροι καὶ προῄεσαν, ἄρας καὶ αὐτὸς ἐπηκολούθει σχέδην, ἐγγὺς μὲν ἀεὶ καὶ παρ’ αὐτοὺς ἐκείνους ἱδρυόμενος, ὀχυραῖς δὲ χρώμενος στρατοπεδείαις καὶ χωρία καρτερὰ προβαλλόμενος, ὥστε ἐν ἀσφαλεῖ νυκτερεύειν. οὕτω δὴ προϊόντες ἐγένοντο πρὸς τοῖς καλουμένοις ὕδασι Σεξτίοις, ὅθεν ἔδει πορευθέντας οὐ πολλὴν ὁδὸν ἐν ταῖς Ἄλπεσιν εἶναι. διὸ δὴ καὶ Μάριος ἐνταῦθα παρεσκευάζετο μάχεσθαι, καὶ κατέλαβε τῷ στρατοπέδῳ τόπον ἰσχυρὸν μέν, ὕδωρ δὲ ἄφθονον οὐκ ἔχοντα, βουλόμενος, ὥς φασι, καὶ τούτῳ παροξῦναι τοὺς στρατιώτας. πολλῶν γέ τοι δυσχεραινόντων καὶ διψήσειν λεγόντων, δείξας τῇ χειρὶ ποταμόν τινα ῥέοντα πλησίον τοῦ βαρβαρικοῦ χάρακος, ἐκεῖθεν αὐτοῖς ἔφησεν εἶναι ποτὸν ὤνιον αἵματος. τί οὖν, ἔφασαν, οὐκ εὐθὺς ἡμᾶς ἄγεις ἐπ’ αὐτούς, ἕως ὑγρὸν τὸ αἷμα ἔχομεν; κἀκεῖνος ἠρέμα τῇ φωνῇ, πρότερον, εἶπεν, ὀχυρωτέον ἡμῖν τὸ στρατόπεδον.", "st": "Mar. 18.1"}, {"sp": "N", "t": "οἱ μὲν οὖν στρατιῶται καίπερ ἀσχάλλοντες ἐπείθοντο· τῆς δὲ θεραπείας τὸ πλῆθος οὔτ’ αὐτοὶ ποτὸν οὔτε ὑποζυγίοις ἔχοντες ἀθρόοι κατέβαινον ἐπὶ τὸν ποταμόν, οἱ μὲν ἀξίνας, οἱ δὲ πελέκεις, ἔνιοι δὲ καὶ ξίφη καὶ λόγχας ἅμα τοῖς ὑδρίοις ἀναλαβόντες, ὡς καὶ διὰ μάχης ὑδρευσόμενοι. τούτοις τὸ πρῶτον ὀλίγοι προσεμάχοντο τῶν πολεμίων ἔτυχον γὰρ ἀριστῶντες οἱ πολλοὶ μετὰ λουτρόν, οἱ δὲ ἐλούοντο. ῥήγνυσι γὰρ αὐτόθι ναμάτων θερμῶν πηγὰς ὁ χῶρος· καὶ μέρος τι περὶ ταῦτα τοὺς βαρβάρους εὐπαθοῦντας καὶ πανηγυρίζοντας ἡδονῇ καὶ θαύματι τοῦ τόπου κατέλαβον οἱ Ῥωμαῖοι. πρὸς δὲ τὴν κραυγὴν πλειόνων συντρεχόντων τῷ τε Μαρίῳ χαλεπὸν ἦν ἔτι τοὺς στρατιώτας ἐπισχεῖν περὶ τῶν οἰκετῶν δεδιότας, καὶ τῶν πολεμίων τὸ μαχιμώτατον μέρος, ὑφ’ οὗ προήττηντο Ῥωμαῖοι μετὰ Μαλλίου καὶ Καιπίωνος πρότερον Ἄμβρωνες ὠνομάζοντο καὶ πλῆθος ὑπὲρ τρισμυρίους αὐτοὶ καθ’ ἑαυτοὺς ἦσαν, ἀναΐξαντες ἐπὶ τὰς πανοπλίας ἐχώρουν. τὰ μὲν οὖν σώματα πλησμονῇ βεβαρημένοι, τοῖς δὲ φρονήμασι γαῦροι καὶ διακεχυμένοι πρὸς τὸν ἄκρατον, οὐκ ἀτάκτοις οὐδὲ μανιώδεσι φερόμενοι δρόμοις οὐδὲ ἄναρθρον ἀλαλαγμὸν ἱέντες, ἀλλὰ κρούοντες ῥυθμῷ τὰ ὅπλα καὶ συναλλόμενοι πάντες ἅμα τὴν αὑτῶν ἐφθέγγοντο πολλάκις προσηγορίαν Ἄμβρωνες, εἴτε ἀνακαλούμενοι σφᾶς αὐτούς, εἴτε τοὺς πολεμίους τῇ προδηλώσει προεκφοβοῦντες. τῶν δὲ Ἰταλικῶν πρῶτοι καταβαίνοντες ἐπ’ αὐτοὺς Λίγυες, ὡς ἤκουσαν βοώντων καὶ συνῆκαν, ἀντεφώνουν καὶ αὐτοὶ τὴν πάτριον ἐπίκλησιν αὑτῶν εἶναι σφᾶς γὰρ αὐτοὺς οὕτως κατὰ γένος ὀνομάζουσι Λίγυες. πυκνὸν οὖν καὶ παράλληλον ἀντήχει πρὶν εἰς χεῖρας συνελθεῖν τὸ ἀναφώνημα· καὶ τῶν στρατῶν ἑκατέροις ἀνὰ μέρος συναναφθεγγομένων καὶ φιλοτιμουμένων πρῶτον ἀλλήλους τῷ μεγέθει τῆς βοῆς ὑπερβαλέσθαι, παρώξυνε καὶ διηρέθιζε τὸν θυμὸν ἡ κραυγή.", "st": "Mar. 19.1"}, {"sp": "N", "t": "τοὺς μὲν οὖν Ἄμβρωνας διέσπασε τὸ ῥεῖθρον οὐ γάρ ἔφθασαν εἰς τάξιν καταστῆναι διαβάντες, ἀλλὰ τοῖς πρώτοις εὐθὺς μετὰ δρόμου τῶν Λιγύων προσπεσόντων ἐν χερσὶν ἦν ἢ μάχη· τοῖς δὲ Λίγυσι τῶν Ῥωμαίων ἐπιβοηθούντων καὶ φερομένων ἄνωθεν ἐπὶ τοὺς βαρβάρους βιασθέντες ἐτράποντο. καὶ πλεῖστοι μὲν αὐτοῦ περὶ τὸ ῥεῖθρον ὠθούμενοι κατ’ ἀλλήλων ἐπαίοντο καὶ κατεπίμπλασαν φόνου καὶ νεκρῶν τὸν ποταμόν, τοὺς δὲ διαβάντες οἱ Ῥωμαῖοι μὴ τολμῶντας ἀναστρέφειν ἔκτεινον ἄχρι τοῦ στρατοπέδου καὶ τῶν ἁμαξῶν φεύγοντας. ἐνταῦθα δὲ αἱ γυναῖκες ἀπαντῶσαι μετὰ ξιφῶν καὶ πελέκεων δεινὸν τετριγυῖαι καὶ περίθυμον ἠμύνοντο τοὺς φεύγοντας ὁμοίως καὶ τοὺς διώκοντας, τοὺς μὲν ὡς προδότας, τοὺς δὲ ὡς πολεμίους, ἀναπεφυρμέναι μαχομένοις καὶ χερσὶ γυμναῖς τούς τε θυρεοὺς τῶν Ῥωμαίων ἀποσπῶσαι καὶ τῶν ξιφῶν ἐπιλαμβανόμεναι, καὶ τραύματα καὶ διακοπὰς σωμάτων ὑπομένουσαι, μέχρι τελευτῆς ἀήττητοι τοῖς θυμοῖς. τὴν μὲν οὖν παραποτάμιον μάχην οὕτω κατὰ τύχην μᾶλλον ἢ γνώμῃ τοῦ στρατηγοῦ γενέσθαι λέγουσιν.", "st": "Mar. 19.5"}, {"sp": "N", "t": "ἐπεὶ δὲ πολλοὺς τῶν Ἀμβρώνων οἱ Ῥωμαῖοι διαφθείραντες ἀνεχώρησαν ὀπίσω καὶ σκότος ἐπέσχεν, οὐχ ὥσπερ ἐπ’ εὐτυχήματι τοσούτῳ τὸν στρατὸν ἐδέξαντο παιᾶνες ἐπινίκιοι καὶ πότοι κατὰ σκηνὰς καὶ φιλοφροσύναι περὶ δεῖπνα καὶ τὸ πάντων ἥδιστον ἀνδράσιν εὐτυχῶς μεμαχημένοις, ὕπνος ἤπιος, ἀλλ’ ἐκείνην μάλιστα τὴν νύκτα φοβερὰν καὶ ταραχώδη διήγαγον. ἦν μὲν γάρ αὐτοῖς ἀχαράκωτον τὸ στρατόπεδον καὶ ἀτείχιστον, ἀπελείποντο δὲ τῶν βαρβάρων ἔτι πολλαὶ μυριάδες ἀήττητοι, καὶ συμμεμιγμένων τούτοις ὅσοι διαπεφεύγεσαν τῶν Ἀμβρώνων, ὀδυρμὸς ἦν διὰ νυκτός, οὐ κλαυθμοῖς οὐδὲ στεναγμοῖς ἀνθρώπων ἐοικώς, ἀλλὰ θηρομιγής τις ὠρυγὴ καὶ βρύχημα μεμιγμένον ἀπειλαῖς καὶ θρήνοις ἀναπεμπόμενον ἐκ πλήθους τοσούτου τά τε πέριξ ὄρη καὶ τὰ κοῖλα τοῦ ποταμοῦ περιεφώνει. καὶ κατεῖχε φρικώδης ἦχος τὸ πεδίον, τοὺς δὲ Ῥωμαίους δέος, αὐτόν τε τὸν Μάριον ἔκπληξις ἄκοσμόν τινα καὶ ταραχώδη νυκτομαχίαν προσδεχόμενον. οὐ μὴν ἐπῆλθον οὔτε νυκτὸς οὔτε τῆς ἐπιούσης ἡμέρας, ἀλλὰ συντάττοντες ἑαυτοὺς καὶ παρασκευαζόμενοι διετέλουν.", "st": "Mar. 20.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Μάριος, ἦσαν γάρ ἐκ κεφαλῆς τῶν βαρβάρων νάπαι περικλινεῖς καὶ κατάσκιοι δρυμοῖς αὐλῶνες, ἐνταῦθα Κλαύδιον Μάρκελλον ἐκπέμπει μετὰ τρισχιλίων ὁπλιτῶν, ἐνεδρεῦσαι κελεύσας κρύφα καὶ μαχομένοις ἐξόπισθεν ἐπιφανῆναι. τοὺς δὲ ἄλλους δειπνήσαντας ἐν ὥρᾳ καὶ κοιμηθέντας ἅμ’ ἡμέρᾳ συνέταττε πρὸ τοῦ χάρακος ἀγαγών, καὶ προεξέπεμπε τοὺς ἱππέας εἰς τὸ πεδίον. θεασάμενοι δὲ οἱ Τεύτονες οὐκ ἠνέσχοντο καταβαίνοντας αὐτοῖς ἐξ ἴσου διαγωνίζεσθαι τοὺς Ῥωμαίους, ἀλλὰ σὺν τάχει καὶ δι’ ὀργῆς ὁπλισάμενοι τῷ λόφῳ προσέβαλον. ὁ δὲ Μάριος ἑκασταχοῦ διαπέμπων τοὺς ἡγεμόνας ἑστάναι καὶ καρτερεῖν παρεκάλει, πελασάντων δὲ εἰς ἐφικτὸν ἐξακοντίσαι τοὺς ὑσσούς, εἶτα χρῆσθαι ταῖς μαχαίραις καὶ τοῖς θυρεοῖς ἀντερείσαντας βιάζεσθαι· τῶν γάρ τόπων ἐπισφαλῶν ὄντων ἐκείνοις οὔτε τόνον ἕξειν τὰς πληγὰς οὔτε ῥώμην τὸν συνασπισμόν, ἐν περιτροπῇ καὶ σάλῳ τῶν σωμάτων ὄντων διὰ τὴν ἀνωμαλίαν. ταῦτα ἅμα παρῄνει καὶ δρῶν ἑωρᾶτο πρῶτος· οὐδενὸς γάρ ἤσκητο χεῖρον τὸ σῶμα, καὶ πάντας πολὺ τῇ τόλμῃ παρήλλαττεν.", "st": "Mar. 20.4"}, {"sp": "N", "t": "ὡς οὖν ἀντιστάντες αὐτοῖς οἱ Ῥωμαῖοι καὶ συμπεσόντες ἔσχον ἄνω φερομένους, ἐκθλιβόμενοι κατὰ μικρὸν ὑπεχώρουν εἰς τὸ πεδίον καὶ τῶν πρώτων ἤδη καθισταμένων εἰς τάξιν ἐν τοῖς ἐπιπέδοις βοὴ καὶ διασπασμὸς ἦν περὶ τοὺς ὄπισθεν, ὁ γάρ καιρὸς οὐκ ἔλαθε τὸν Μάρκελλον, ἀλλὰ τῆς κραυγῆς ὑπὲρ τοὺς λόφους ἄνω φερομένης ἀναστήσας τοὺς μετ’ αὐτοῦ δρόμῳ καὶ ἀλαλαγμῷ προσέπιπτε κατὰ νώτου, κτείνων τοὺς ἐσχάτους. οἱ δὲ τοὺς πρὸ αὑτῶν ἐπισπώμενοι ταχὺ πᾶν τὸ στράτευμα ταραχῆς ἐνέπλησαν, οὐ πολύν τε χρόνον ἠνέσχοντο παιόμενοι διχόθεν, ἀλλὰ τὴν τάξιν λύσαντες ἔφευγον. οἱ δὲ Ῥωμαῖοι διώκοντες αὑτῶν μὲν ὑπὲρ δέκα μυριάδας ἣ ζῶντας εἷλον ἢ κατέβαλον, σκηνῶν δὲ καὶ ἁμαξῶν καὶ χρημάτων κρατήσαντες, ὅσα μὴ διεκλάπη, Μάριον λαβεῖν ἐψηφίσαντο. καὶ δωρεᾶς ταύτης λαμπροτάτης τυχὼν οὐδὲν ἄξιον ἔχειν ὧν ἐστρατήγησεν ἐνομίσθη διὰ τὸ τοῦ κινδύνου μέγεθος.", "st": "Mar. 21.1"}, {"sp": "N", "t": "ἕτεροι δὲ περὶ τῆς δωρεᾶς τῶν λαφύρων οὐχ ὁμολογοῦσιν, οὐδὲ περὶ τοῦ πλήθους τῶν πεσόντων. Μασσαλιήτας μέντοι λέγουσι τοῖς ὀστέοις περιθριγκῶσαι τοὺς ἀμπελῶνας, τὴν δὲ γῆν, τῶν νεκρῶν καταναλωθέντων ἐν αὐτῇ καὶ διὰ χειμῶνος ὄμβρων ἐπιπεσόντων, οὕτως ἐκλιπανθῆναι καὶ γενέσθαι διὰ βάθους περίπλεω τῆς σηπεδόνος ἐνδύσης ὥστε καρπῶν ὑπερβάλλον εἰς ὥρας πλῆθος ἐξενεγκεῖν καὶ μαρτυρῆσαι τῷ Ἀρχιλόχῳ λέγοντι πιαίνεσθαι πρὸς τοῦ τοιούτου τὰς ἀρούρας. ἐπιεικῶς δὲ ταῖς μεγάλαις μάχαις ἐξαισίους ὑετοὺς ἐπικαταρρήγνυσθαι λέγουσιν, εἴτε δαιμονίου τινὸς τὴν γῆν καθαροῖς καὶ διιπετέσιν ἁγνίζοντος ὕδασι καὶ κατακλύζοντος, εἴτε τοῦ φόνου καὶ τῆς σηπεδόνος ἐξανιείσης ὑγρὰν καὶ βαρεῖαν ἀναθυμίασιν, ἣ τὸν ἀέρα συνίστησιν εὔτρεπτον ὄντα καὶ ῥᾴδιον μεταβάλλειν ἀπὸ σμικροτάτης ἐπὶ πλεῖστον ἀρχῆς.", "st": "Mar. 21.3"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην ὁ Μάριος τῶν βαρβαρικῶν ὅπλων καὶ λαφύρων τὰ μὲν ἐκπρεπῆ καὶ ὁλόκληρα καὶ πομπικὴν ὄψιν τῷ θριάμβῳ δυνάμενα παρασχεῖν ἐπέλεξε, τῶν δὲ ἄλλων ἐπὶ πυρᾶς μεγάλης κατασωρεύσας τὸ πλῆθος ἔθυσε θυσίαν μεγαλοπρεπῆ. καὶ τοῦ στρατοῦ παρεστῶτος ἐν ὅπλοις ἐστεφανωμένου περιζωσάμενος αὐτός, ὥσπερ ἔθος ἐστίν, ἀναβαλὼν τὴν περιπόρφυρον καὶ λαβὼν δᾷδα καιομένην καὶ δι’ ἀμφοτέρων τῶν χειρῶν ἀνασχὼν πρὸς τὸν οὐρανὸν ἔμελλεν ὑφήσειν τῇ πυρᾷ· καὶ προσελαύνοντες ἵπποις ἑωρῶντο φίλοι σὺν τάχει πρὸς αὐτόν, ὥστε πολλὴν γενέσθαι σιωπὴν καὶ προσδοκίαν ἁπάντων. ἐπεὶ δὲ ἐγγὺς ἦσαν, ἀποπηδήσαντες ἐδεξιοῦντο τὸν Μάριον, εὐαγγελιζόμενοι τὸ πέμπτον αὐτὸν ὕπατον ᾑρῆσθαι, καὶ γράμματα περὶ τούτων ἀπέδοσαν. μεγάλης οὖν χαρᾶς τοῖς ἐπινικίοις προσγενομένης ὅ τε στρατὸς ὑφ’ ἡδονῆς ἐνοπλίῳ τινὶ κρότῳ καὶ πατάγῳ συνηλάλαξαν, καὶ τῶν ἡγεμόνων τὸν Μάριον αὖθις ἀναδούντων δάφνης στεφάνοις ἐνῆψε τὴν πυρὰν καὶ τὴν θυσίαν ἐπετελείωσεν.", "st": "Mar. 22.1"}, {"sp": "N", "t": "ἡ δὲ μηθὲν ἐῶσα τῶν μεγάλων εὐτυχημάτων ἄκρατον εἰς ἡδονὴν καὶ καθαρόν, ἀλλὰ μείξει κακῶν καὶ ἀγαθῶν ποικίλλουσα τὸν ἀνθρώπινον βίον ἢ τύχη τις ἢ νέμεσις ἢ πραγμάτων ἀναγκαία φύσις οὐ πολλαῖς ὕστερον ἡμέραις ἐπήγαγε τῷ Μαρίῳ τὴν περὶ Κάτλου τοῦ συνάρχοντος ἀγγελίαν, ὥσπερ ἐν εὐδίᾳ καὶ γαλήνῃ νέφος, αὖθις ἕτερον φόβον καὶ χειμῶνα τῇ Ῥώμῃ περιστήσασα. ὁ γάρ δὴ Κάτλος ἀντικαθήμενος τοῖς Κίμβροις τὰς μὲν ὑπερβολὰς τῶν Ἄλπεων ἀπέγνω φυλάσσειν, μὴ κατὰ πολλὰ τὴν δύναμιν μέρη διαιρεῖν ἀναγκαζόμενος ἀσθενὴς γένοιτο, καταβὰς δ’ εὐθὺς εἰς τὴν Ἰταλίαν καὶ τὸν Ἀτισῶνα ποταμὸν λαβὼν πρὸ αὑτοῦ καὶ φραξάμενος πρὸς τὰς διαβάσεις ἑκατέρωθεν ἰσχυροῖς χαρακώμασιν, ἔζευξε τὸν πόρον, ὡς ἐπιβοηθεῖν εἴη τοῖς πέραν, εἰ πρὸς τὰ φρούρια βιάζοιντο διὰ τῶν στενῶν οἱ βάρβαροι. τοῖς δὲ τοσοῦτον περιῆν ὑπεροψίας καὶ θράσους κατὰ τῶν πολεμίων ὥστε ῥώμην καὶ τόλμαν ἐπιδεικνύμενοι μᾶλλον ἢ πράττοντές τι τῶν ἀναγκαίων γυμνοὶ μὲν ἠνείχοντο νιφόμενοι καὶ διὰ πάγων καὶ χιόνος βαθείας τοῖς ἄκροις προσέβαινον, ἄνωθεν δὲ τοὺς θυρεοὺς πλατεῖς ὑποτιθέντες τοῖς σώμασιν, εἶτα ἀφιέντες αὑτούς ὑπεφέροντο κατὰ κρημνῶν ὀλισθήματα καὶ λισσάδας ἀχανεῖς ἐχόντων. ὡς δὲ παραστρατοπεδεύσαντες ἐγγὺς καὶ κατασκεψάμενοι τὸν πόρον ἤρξαντο χοῦν, καὶ τοὺς πέριξ λόφους ἀναρρηγνύντες, ὥσπερ οἱ γίγαντες, ἅμα δένδρα πρόρριζα καὶ κρημνῶν σπαράγματα καὶ γῆς κολωνοὺς ἐφόρουν εἰς τὸν ποταμόν, ἐκθλίβοντες τὸ ῥεῦμα καὶ τοῖς ἐρείδουσι τὰ ζεύγματα βάθροις ἐφιέντες βάρη μεγάλα συρόμενα κατὰ ῥοῦν καὶ τινάττοντα ταῖς πληγαῖς τὴν γέφυραν, ἀποδειλιάσαντες οἱ πλεῖστοι τῶν στρατιωτῶν ἐξέλειπον τὸ μέγα στρατόπεδον καὶ ἀνεχώρουν.", "st": "Mar. 23.1"}, {"sp": "N", "t": "ἔνθα δὴ Κάτλος ἔδειξεν ἑαυτόν, ὥσπερ χρὴ τὸν ἀγαθὸν καὶ τέλειον ἄρχοντα, τὴν αὑτοῦ δόξαν ἐν ὑστέρῳ τῶν πολιτῶν τιθέμενον. ἐπεὶ γάρ οὐκ ἔπειθε τοὺς στρατιώτας μένειν, ἀλλ’ ἑώρα περιδεῶς ἀναζευγνύντας, ἄρασθαι κελεύσας τὸν ἀετὸν εἰς τοὺς πρώτους τῶν ἀπερχομένων ὥρμησε δρόμῳ καὶ πρῶτος ἡγεῖτο, βουλόμενος αὑτοῦ τὸ αἰσχρόν, ἀλλὰ μὴ τῆς πατρίδος γενέσθαι, καὶ δοκεῖν μὴ φεύγοντας, ἀλλ’ ἑπομένους τῷ στρατηγῷ ποιεῖσθαι τὴν ἀποχώρησιν. οἱ δὲ βάρβαροι τὸ μὲν πέραν τοῦ Ἀτισῶνος φρούριον ἐπελθόντες ἔλαβον, καὶ τοὺς αὐτόθι Ῥωμαίους ἀνδρῶν κρατίστους γενομένους καὶ προκινδυνεύσαντας ἀξίως τῆς πατρίδος θαυμάσαντες ὑποσπόνδους ἀφῆκαν. ὀμόσαντες τὸν χαλκοῦν ταῦρον, ὃν ὕστερον ἁλόντα μετὰ τὴν μάχην εἰς τὴν Κάτλου φασὶν οἰκίαν ὥσπερ ἀκροθίνιον τῆς νίκης κομισθῆναι· τὴν δὲ χώραν ἔρημον βοηθείας ἐπιχυθέντες ἐπόρθουν.", "st": "Mar. 23.5"}, {"sp": "N", "t": "ἐπὶ τούτοις ἐκαλεῖτο Μάριος εἰς τὴν Ῥώμην καὶ παραγενόμενος, πάντων αὐτὸν οἰομένων θριαμβεύσειν καὶ τῆς βουλῆς προθύμως ψηφισαμένης, οὐκ ἠξίωσεν, εἴτε τοὺς στρατιώτας καὶ συναγωνιστὰς ἀποστερῆσαι τῆς φιλοτιμίας μὴ βουλόμενος, εἴτε πρὸς τὰ παρόντα θαρρύνων τὸ πλῆθος, ὡς τῇ τύχῃ τῆς πόλεως παρακατατιθέμενος τὴν τῶν πρώτων κατορθωμάτων, δόξαν ἐν τοῖς δευτέροις λαμπροτέραν ἀποδοθησομένην. διαλεχθεὶς δὲ τὰ πρέποντα τῷ καιρῷ καὶ πρὸς τὸν Κάτλον ἐξορμήσας, τοῦτόν τε παρεθάρρυνε καὶ τοὺς αὑτοῦ μετεπέμπετο στρατιώτας ἐκ Γαλατίας, ὡς δὲ ἀφίκοντο, διαβὰς τὸν Ἠριδανὸν εἴργειν ἐπειρᾶτο τῆς ἐντὸς Ἰταλίας τοὺς βαρβάρους, οἱ δὲ τοὺς Τεύτονας ἐκδέχεσθαι καὶ θαυμάζειν ὡς βραδυνόντων φάσκοντες ἀνεβάλλοντο τὴν μάχην, εἴτε ἀγνοοῦντες ὄντως τὴν ἐκείνων φθοράν, εἴτε βουλόμενοι δοκεῖν ἀπιστεῖν. καὶ γὰρ τοὺς ἀγγέλλοντας ᾐκίζοντο δεινῶς, καὶ τὸν Μάριον ᾔτουν πέμψαντες ἑαυτοῖς καὶ τοῖς ἀδελφοῖς χώραν καὶ πόλεις ἱκανὰς ἐνοικεῖν. ἐρομένου δὲ τοῦ Μαρίου τοὺς πρέσβεις περὶ τῶν ἀδελφῶν, κἀκείνων ὀνομασάντων τοὺς Τεύτονας, οἱ μὲν ἄλλοι πάντες ἐγέλασαν, ὁ δὲ Μάριος ἔσκωψεν εἰπὼν ἐᾶτε τοίνυν τοὺς ἀδελφούς· ἔχουσι γὰρ γῆν ἐκεῖνοι καὶ διὰ παντὸς ἕξουσι παρ’ ἡμῶν λαβόντες. οἱ δὲ πρέσβεις τὴν εἰρωνείαν συνέντες ἐλοιδόρουν αὐτὸν ὡς δίκην ὑφέξοντα, Κίμβροις μὲν αὐτίκα, Τεύτοσι δὲ ὅταν παραγένωνται. καὶ μὴν πάρεισιν, ἔφη ὁ Μάριος, καὶ οὐχ ἕξει καλῶς ὑμῖν ἀπαλλαγῆναι πρότερον ἢ τοὺς ἀδελφοὺς ἀσπάσασθαι. καὶ ταῦτα εἰπὼν ἐκέλευσε τοὺς βασιλεῖς τῶν Τευτόνων προσαχθῆναι δεδεμένους· ἑάλωσαν γὰρ ἐν ταῖς Ἄλπεσι φεύγοντες ὑπὸ Σηκουανῶν.", "st": "Mar. 24.1"}, {"sp": "N", "t": "ὡς δὲ ἀπηγγέλθη ταῦτα τοῖς Κίμβροις, αὖθις ἐξ ἀρχῆς ἐχώρουν ἐπὶ τὸν Μάριον ἡσυχάζοντα καὶ διαφυλάττοντα τὸ στρατόπεδον. λέγεται δὲ εἰς ἐκείνην τὴν μάχην πρῶτον ὑπὸ Μαρίου καινοτομηθῆναι τὸ περὶ τοὺς ὑσσούς. τὸ γάρ εἰς τὸν σίδηρον ἔμβλημα τοῦ ξύλου πρότερον μὲν ἦν δυσὶ περόναις κατειλημμένον σιδηραῖς, τότε δὲ ὁ Μάριος τὴν μέν, ὥσπερ εἶχεν, εἴασε, τὴν δὲ ἑτέραν ἐξελὼν ξύλινον ἧλον εὔθραυστον ἀντ’ αὐτῆς ἐνέβαλε, τεχνάζων προσπεσόντα τὸν ὑσσὸν τῷ θυρεῷ τοῦ πολεμίου μὴ μένειν ὀρθόν, ἀλλὰ τοῦ ξυλίνου κλασθέντος ἥλου καμπὴν γίνεσθαι περὶ τὸν σίδηρον καὶ παρέλκεσθαι τὸ δόρυ, διὰ τὴν στρεβλότητα τῆς αἰχμῆς ἐνεχόμενον.", "st": "Mar. 25.1"}, {"sp": "N", "t": "Βοιῶριξ δὲ ὁ τῶν Κίμβρων βασιλεὺς ὀλιγοστὸς προσιππεύσας τῷ στρατοπέδῳ προὐκαλεῖτο τὸν Μάριον, ἡμέραν ὁρίσαντα καὶ τόπον, προελθεῖν καὶ διαγωνίσασθαι περὶ τῆς χώρας. τοῦ δὲ Μαρίου φήσαντος οὐδέποτε Ῥωμαίους συμβούλοις κεχρῆσθαι περὶ μάχης τοῖς πολεμίοις, οὐ μὴν ἀλλὰ καὶ χαριεῖσθαι τοῦτο Κίμβροις, ἡ μέραν μὲν ἔθεντο τὴν ἀπ’· ἐκείνης τρίτην, χώραν δὲ τὸ πεδίον τὸ περὶ Βερκέλλας, Ῥωμαίοις μὲν ἐπιτήδειον ἐνιππάσασθαι, τῶν δὲ ἀνάχυσιν τῷ πλήθει παρασχεῖν.", "st": "Mar. 25.3"}, {"sp": "N", "t": "τηρήσαντες οὖν τὸν ὡρισμένον χρόνον ἀντιπαρετάσσοντο, Κάτλος μὲν ἔχων δισμυρίους καὶ τριακοσίους στρατιώτας, οἱ δὲ Μαρίου δισχίλιοι μὲν ἐπὶ τρισμυρίοις ἐγένοντο, περιέσχον δὲ τὸν Κάτλον ἐν μέσῳ νεμηθέντες εἰς ἑκάτερον κέρας, ὡς Σύλλας, ἠγωνισμένος ἐκείνην τὴν μάχην, γέγραφε. καί φησι τὸν Μάριον ἐλπίσαντα τοῖς ἄκροις μάλιστα καὶ κατὰ κέρας συμπεσεῖν τὰς φάλαγγας, ὅπως ἴδιος ἡ νίκη τῶν ἐκείνου στρατιωτῶν γένοιτο καὶ μὴ μετάσχοι τοῦ ἀγῶνος ὁ Κάτλος μηδὲ προσμίξειε τοῖς πολεμίοις, κόλπωμα τῶν μέσων, ὥσπερ εἴωθεν ἐν μεγάλοις μετώποις, λαμβανόντων, οὕτω διαστῆσαι τὰς δυνάμεις. ὅμοια δὲ καὶ τὸν Κάτλον αὐτὸν ἀπολογεῖσθαι περὶ τούτων ἱστοροῦσι, πολλὴν κατηγοροῦντα τοῦ Μαρίου κακοήθειαν πρὸς αὐτόν.", "st": "Mar. 25.4"}, {"sp": "N", "t": "τοῖς δὲ Κίμβροις τὸ μὲν πεζὸν ἐκ τῶν ἐρυμάτων καθ’ ἡσυχίαν προῄει, βάθος ἴσον τῷ μετώπῳ ποιούμενον. ἑκάστη γὰρ ἐπέσχε πλευρὰ σταδίους τριάκοντα τῆς παρατάξεως· οἱ δὲ ἱππεῖς μύριοι καὶ πεντακισχίλιοι τὸ πλῆθος ὄντες ἐξήλασαν λαμπροί, κράνη μὲν εἰκασμένα θηρίων φοβερῶν χάσμασι καὶ προτομαῖς ἰδιομόρφοις ἔχοντες, ἃς ἐπαιρόμενοι λόφοις πτερωτοῖς εἰς ὕψος ἐφαίνοντο μείζους, θώραξι δὲ κεκοσμημένοι σιδηροῖς, θυρεοῖς δὲ λευκοῖς στίλβοντες. ἀκόντισμα δὲ ἦν ἑκάστῳ διβολία· συμπεσόντες δὲ μεγάλαις ἐχρῶντο καὶ βαρείαις μαχαίραις.", "st": "Mar. 25.7"}, {"sp": "N", "t": "τότε δὲ οὐχὶ κατὰ στόμα προσεφέροντο τοῖς Ῥωμαίοις, ἀλλ’ ἐκκλίνοντες ἐπὶ δεξιὰ ὑπῆγον αὑτοὺς κατὰ μικρόν, ἐμβάλλοντες εἰς τὸ μέσον αὐτῶν τε καὶ τῶν πεζῶν ἐξ ἀριστερᾶς παρατεταγμένων, καὶ συνεῖδον μὲν οἱ τῶν Ῥωμαίων στρατηγοὶ τὸν δόλον, ἐπισχεῖν δὲ τοὺς στρατιώτας οὐκ ἔφθησαν, ἀλλ’ ἑνὸς ἐκβοήσαντος ὅτι φεύγουσιν οἱ πολέμιοι, πάντες ὥρμησαν διώκειν. καὶ τὸ πεζὸν ἐν τούτῳ τῶν βαρβάρων ἐπῄει καθάπερ πέλαγος ἀχανὲς κινούμενον. ἐνταῦθα νιψάμενος ὁ Μάριος τὰς χεῖρας καὶ πρὸς τὸν οὐρανὸν ἀνασχὼν εὔξατο τοῖς θεοῖς κατὰ ἑκατόμβης, εὔξατο δὲ καὶ Κάτλος ὁμοίως ἀνασχὼν τὰς χεῖρας καθιερώσειν τὴν τύχην τῆς ἡμέρας ἐκείνης, τὸν δὲ Μάριον καὶ θύσαντα λέγεται τῶν ἱερῶν αὐτῷ δειχθέντων μέγα φθεγξάμενον εἰπεῖν ἐμὴ ἡ νίκη.", "st": "Mar. 26.1"}, {"sp": "N", "t": "γενομένης δὲ τῆς ἐφόδου πρᾶγμα νεμεσητὸν παθεῖν τὸν Μάριον οἱ περὶ Σύλλαν ἱστοροῦσι. κονιορτοῦ γὰρ ἀρθέντος, οἷον εἰκός, ἀπλέτου καὶ τῶν στρατοπέδων ἀποκεκρυμμένων, ἐκεῖνον μέν, ὡς τὸ πρῶτον ὥρμησε πρὸς τὴν δίωξιν, ἐπισπασάμενον τὴν δύναμιν ἀστοχῆσαι τῶν πολεμίων καὶ παρενεχθέντα τῆς φάλαγγος ἐν τῷ πεδίῳ διαφέρεσθαι πολὺν χρόνον, τῷ δὲ Κάτλῳ τοὺς βαρβάρους ἀπὸ τύχης συρραγῆναι, καὶ γενέσθαι τὸν ἀγῶνα κατ’ ἐκεῖνον καὶ τοὺς ἐκείνου μάλιστα στρατιώτας, ἐν οἷς αὐτὸς ὁ Σύλλας τετάχθαι φησί· συναγωνίσασθαι δὲ τοῖς Ῥωμαίοις τὸ καῦμα καὶ τὸν ἥλιον ἀντιλάμποντα τοῖς Κίμβροις. δεινοὶ γὰρ ὄντες ὑπομεῖναι κρύη, καὶ τόποις ἐντεθραμμένοι σκιεροῖς, ὡς λέλεκται, καὶ ψυχροῖς, ἀνετρέποντο πρὸς τὸ θάλπος, ἱδρῶτά τε μετὰ ἄσθματος πολὺν ἐκ τῶν σωμάτων ἀφιέντες καὶ τοὺς θυρεοὺς προβαλλόμενοι πρὸ τῶν προσώπων, ἅτε δὴ καὶ μετὰ τροπὰς θέρους τῆς μάχης γενομένης, ἃς ἄγουσι Ῥωμαῖοι πρὸ τριῶν ἡμερῶν τῆς νουμηνίας τοῦ νῦν μὲν Αὐγούστου, τότε δὲ Σεξτιλίου μηνός. ὤνησε δὲ καὶ πρὸς τὸ θαρρεῖν ὁ κονιορτὸς ἀποκρύψας τοὺς πολεμίους, οὐ γάρ κατεῖδον ἐκ πολλοῦ τὸ πλῆθος, ἀλλὰ δρόμῳ τοῖς κατ’ αὑτοὺς ἕκαστοι προσμείξαντες ἐν χερσὶν ἦσαν, ὑπὸ τῆς ὄψεως μὴ προεκφοβηθέντες. οὕτω δ’ ἦσαν διάπονοι τὰ σώματα καὶ κατηθληκότες ὡς μήτε ἱδροῦντά τινα μήτε ἀσθμαίνοντα Ῥωμαίων ὀφθῆναι διὰ πνίγους τοσούτου καὶ μετὰ δρόμου τῆς συρράξεως γενομένης, ὡς τὸν Κάτλον αὐτὸν ἱστορεῖν λέγουσι μεγαλύνοντα τοὺς στρατιώτας.", "st": "Mar. 26.3"}, {"sp": "N", "t": "τὸ μὲν οὖν πλεῖστον μέρος καὶ μαχιμώτατον τῶν πολεμίων αὐτοῦ κατεκόπη· καὶ γὰρ ἦσαν ὑπὲρ τοῦ μὴ διασπᾶσθαι τὴν τάξιν οἱ πρόμαχοι μακραῖς ἁλύσεσι πρὸς ἀλλήλους συνεχόμενοι διὰ τῶν ζωστήρων ἀναδεδεμέναις· τοὺς δὲ φεύγοντας ὤσαντες πρὸς τὸ χαράκωμα τραγικωτάτοις ἐνετύγχανον πάθεσιν. αἱ γὰρ γυναῖκες ἐπὶ τῶν ἁμαξῶν μελανείμονες ἐφεστῶσαι τούς τε φεύγοντας ἔκτεινον, αἱ μὲν ἄνδρας, αἱ δὲ ἀδελφούς, αἱ δὲ πατέρας, καὶ τὰ νήπια τῶν τέκνων ἀπάγχουσαι ταῖς χερσὶν ἐρρίπτουν ὑπὸ τοὺς τροχοὺς καὶ τοὺς πόδας τῶν ὑποζυγίων, αὑτὰς δὲ ἀπέσφαττον. μίαν δέ φασιν ἓξ ἄκρου ῥυμοῦ κρεμαμένην τὰ παιδία τῶν αὑτῆς σφυρῶν ἀφημμένα βρόχοις ἐκατέρωθεν ἠρτῆσθαι· τοὺς δὲ ἄνδρας ἀπορίᾳ δένδρων τοῖς κέρασι τῶν βοῶν, τοὺς δὲ τοῖς σκέλεσι προσδεῖν τοὺς αὑτῶν τραχήλους, εἶτα κέντρα προσφέροντας ἐξαλλομένων τῶν βοῶν ἐφελκομένους καὶ πατουμένους ἀπόλλυσθαι. πλὴν καίπερ οὕτως αὑτῶν διαφθαρέντων, ἑάλωσαν ὑπὲρ ἓξ μυριάδας· αἱ δὲ τῶν πεσόντων ἐλέγοντο δὶς τοσαῦται γενέσθαι.", "st": "Mar. 27.1"}, {"sp": "N", "t": "τὰ μὲν οὖν χρήματα διήρπασαν οἱ Μαρίου στρατιῶται, τὰ δὲ λάφυρα καὶ τὰς σημαίας καὶ τὰς σάλπιγγας εἰς τὸ Κάτλου στρατόπεδον ἀνενεχθῆναι λέγουσιν· ᾧ καὶ μάλιστα τεκμηρίῳ χρῆσθαι τὸν Κάτλον ὡς κατ’ αὐτὸν ἡ νίκη γένοιτο, καὶ μέντοι καὶ τοῖς στρατιώταις, ὡς ἔοικεν, ἐμπεσούσης ἔριδος, ᾑρέθησαν οἷον διαιτηταὶ πρέσβεις Παρμητῶν παρόντες, οὓς οἱ Κάτλου διὰ τῶν πολεμίων νεκρῶν ἄγοντες ἐπεδείκνυντο τοῖς ἑαυτῶν ὑσσοῖς διαπεπαρμένους· γνώριμοι δ’ ἦσαν ὑπὸ γραμμάτων, τοὔνομα τοῦ Κάτλου παρὰ τὸ ξύλον αὑτῶν ἐγχαράξαντος. οὐ μὴν ἀλλὰ τῷ Μαρίῳ προσετίθετο σύμπαν τὸ ἔργον ἥ τε προτέρα νίκη καὶ τὸ πρόσχημα τῆς ἀρχῆς, μάλιστα δὲ οἱ πολλοὶ κτίστην τε Ῥώμης τρίτον ἐκεῖνον ἀνηγόρευον, ὡς οὐχ ἥττονα τοῦ Κελτικοῦ τοῦτον ἀπεωσμένον τὸν κίνδυνον, εὐθυμούμενοί τε μετὰ παίδων καὶ γυναικῶν ἕκαστοι κατ’ οἶκον ἅμα τοῖς θεοῖς καὶ Μαρίῳ δείπνου καὶ λοιβῆς ἀπήρχοντο, καὶ θριαμβεύειν μόνον ἠξίουν ἀμφοτέρους τοὺς θριάμβους. οὐ μὴν ἐθριάμβευσεν οὕτως, ἀλλὰ μετὰ τοῦ Κάτλου, μέτριον ἐπὶ τηλικαύταις εὐτυχίαις βουλόμενος παρέχειν ἑαυτόν· ἔστι δὲ ὅ τι καὶ τοὺς στρατιώτας φοβηθείς παρατεταγμένους, εἰ Κάτλος ἀπείργοιτο τῆς τιμῆς, μηδὲ ἐκεῖνον ἐᾶν θριαμβεύειν.", "st": "Mar. 27.4"}, {"sp": "N", "t": "πέμπτην μὲν οὖν ὑπατείαν διεῖπε· τῆς δὲ ἕκτης ὡς οὐδὲ εἷς πρώτης ὠρέγετο, θεραπείαις τὸν δῆμον ἀναλαμβάνων καὶ πρὸς χάριν ἐνδιδοὺς τοῖς πολλοῖς, οὐ μόνον παρὰ τὸν ὄγκον καὶ τὸ κοινὸν ἀξίωμα τῆς ἀρχῆς, ἀλλὰ καὶ παρὰ τὴν αὐτοῦ φύσιν ὑγρός τις εἶναι βουλόμενος καὶ δημοτικός, ἥκιστα τοιοῦτος πεφυκώς. ἀλλ’ ἦν, ὡς λέγουσι, πρὸς πολιτείαν καὶ τοὺς ἐν ὄχλοις θορύβους ὑπὸ φιλοδοξίας ἀτολμότατος, καὶ τὸ παρὰ τὰς μάχας ἀνέκπληκτον καὶ στάσιμον ἐν ταῖς ἐκκλησίαις ἀπέλειπεν αὐτὸν ὑπὸ τῶν τυχόντων ἐπαίνων καὶ ψόγων ἐξιστάμενον. καίτοι λέγεται Καμερίνων ἄνδρας ὁμοῦ χιλίους διαπρεπῶς ἀγωνισαμένους ἐν τῷ πολέμῳ δωρησάμενος πολιτείᾳ, δοκοῦντος εἶναι τούτου παρανόμου καί τινων ἐγκαλούντων, εἰπεῖν ὅτι τοῦ νόμου διὰ τὸν τῶν ὅπλων ψόφον οὐ κατακούσειεν. οὐ μὴν ἀλλὰ μᾶλλον ἔοικεν ἐκπλήσσεσθαι καὶ δεδιέναι τὴν ἐν ταῖς ἐκκλησίαις κραυγήν. ἐν μὲν γε τοῖς ὅπλοις ἀξίωμα καὶ δύναμιν εἶχε διὰ τὴν χρείαν, ἐν δὲ τῇ πολιτείᾳ περικοπτόμενος τὰ πρωτεῖα κατέφευγεν ἐπὶ τὴν τῶν πολλῶν εὔνοιαν καὶ χάριν, ὑπὲρ τοῦ μέγιστος γενέσθαι τὸ βέλτιστος εἶναι προϊέμενος. πᾶσι μὲν οὖν προσέκρουε τοῖς ἀριστοκρατικοῖς, μάλιστα δὲ ὀρρωδῶν τὸν Μέτελλον ἠχαριστημένον ὑπ’ αὐτοῦ καὶ φύσει δι’ ἀρετὴν ἀληθῆ πολεμοῦντα τοῖς οὐ κατὰ τὸ βέλτιστον ὑποδυομένοις τὰ πλήθη καὶ πρὸς ἡδονὴν δημαγωγοῦσιν, ἐπεβούλευε τῆς πόλεως ἐκβαλεῖν τὸν ἄνδρα. καὶ πρὸς τοῦτο Γλαυκίαν καὶ Σατορνῖνον, ἀνθρώπους θρασυτάτους καὶ πλῆθος ἄπορον καὶ θορυβοποιὸν ὑπ’ αὑτοῖς ἔχοντας, σἰκειωσάμενος εἰσέφερε νόμους δι’ αὐτῶν καὶ τὸ στρατιωτικὸν ἐπάρας κατεμίγνυε ταῖς ἐκκλησίαις καὶ κατεστασίαζε τὸν Μέτελλον. ὡς δὲ Ῥουτίλιος ἱστορεῖ, τὰ μὲν ἄλλα φιλαλήθης ἀνήρ καὶ χρηστός, ἰδίᾳ δὲ τῷ Μαρίῳ προσκεκρουκώς, καὶ τῆς ἕκτης ἔτυχεν ὑπατείας ἀργύριον εἷς τὰς φυλὰς καταβαλὼν πολὺ καὶ πριάμενος τὸ Μέτελλον ἐκκροῦσαι τῆς ἀρχῆς, Οὐαλλέριον δὲ Φλάκκον ὑπηρέτην μᾶλλον ἢ συνάρχοντα τῆς ὑπατείας λαβεῖν. οὐδενὶ μέντοι τῶν πρὸ αὐτοῦ πλὴν μόνῳ Κορβίνῳ Οὐαλλερίῳ τοσαύτας ὑπατείας ἔδωκεν ὁ δῆμος, ἀλλ’ ἐκείνῳ μὲν ἀπὸ τῆς πρώτης εἷς τὴν τελευταίαν ἔτη πέντε καὶ τεσσαράκοντα γενέσθαι λέγουσι, Μάριος δὲ μετὰ τὴν πρώτην τὰς πέντε ῥύμῃ μιᾷ τύχης διέδραμε.", "st": "Mar. 28.1"}, {"sp": "N", "t": "καὶ μάλιστα περὶ τὴν τελευταίαν ἐφθονεῖτο, πολλὰ συνεξαμαρτάνων τοῖς περὶ τὸν Σατορνῖνον. ὧν ἦν καὶ ὁ Νωνίου φόνος, ὃν ἀντιπαραγγέλλοντα δημαρχίαν ἀπέσφαξεν ὁ Σατορνῖνος. εἶτα δημαρχῶν ἐπῆγε τὸν περὶ τῆς χώρας νόμον, ᾧ προσεγέγραπτο τὴν σύγκλητον ὀμόσαι προσελθοῦσαν, ἦ μὴν ἐμμενεῖν οἷς ἂν ὁ δῆμος ψηφίσαιτο καὶ πρὸς μηδὲν ὑπεναντιώσεσθαι. τοῦτο τοῦ νόμου τό μέρος προσποιούμενος ἐν τῇ βουλῇ διώκειν ὁ Μάριος οὐκ ἔφη δέξεσθαι τὸν ὅρκον, οὐδὲ ἄλλον οἴεσθαι σωφρονοῦντα· καὶ γάρ εἰ μὴ μοχθηρὸς ἦν ὁ νόμος, ὕβριν εἶναι τὰ τοιαῦτα τὴν βουλὴν διδόναι βιαζομένην, ἀλλὰ μὴ πειθοῖ μηδὲ ἐκοῦσαν. ταῦτα δὲ οὐχ οὕτως φρονῶν ἔλεγεν, ἀλλὰ τῷ Μετέλλῳ ἀπάτην περιτιθεὶς ἄφυκτον. αὐτὸς μὲν γὰρ εἰς ἀρετῆς καὶ δεινότητος μερίδα τὸ ψεύσασθαι τιθέμενος λόγον οὐδένα τῶν πρὸς τὴν σύγκλητον ὡμολογημένων ἕξειν ἔμελλε, τὸν δὲ Μέτελλον εἰδὼς βέβαιον ἄνδρα καὶ τὴν αλήθειαν ἀρχὴν μεγάλης ἀρετῆς κατὰ Πίνδαρον ἡγούμενον ἐβούλετο τῇ πρὸς τὴν σύγκλητον ἀρνήσει προληφθέντα καὶ μὴ δεξάμενον τὸν ὅρκον εἰς ἀνήκεστον ἐμβαλεῖν πρὸς τὸν δῆμου ἔχθραν. ὃ καὶ συνέβη.", "st": "Mar. 29.1"}, {"sp": "N", "t": "τοῦ γὰρ Μετέλλου φήσαντος μὴ ὀμόσειν, τότε μὲν ἡ βουλῇ διελύθη, μετὰ δὲ ἡμέρας ὀλίγας τοῦ Σατορνίνου πρὸς τὸ βῆμα τοὺς συγκλητικοὺς ἀνακαλουμένου καὶ τὸν ὅρκον ὀμνύειν ἀναγκάζοντος ὁ Μάριος παρελθών, γενομένης σιωπῆς καὶ πάντων εἰς ἐκεῖνον ἀνηρτημένων, μακρὰ χαίρειν φράσας τοῖς ἐν τῇ βουλῇ νεανιευθεῖσιν ἀπὸ φωνῆς, οὐχ οὕτω πλατὺν ἔφη φορεῖν τὸν τράχηλον ὡς προαποφαίνεσθαι καθάπαξ εἰς πρᾶγμα τηλικοῦτον, ἀλλ’ ὀμεῖσθαι καὶ τῷ νόμῳ πειθαρχήσειν, εἴπερ ἔστι νόμος· καὶ γάρ τοῦτο προσέθηκε τὸ σοφὸν ὥσπερ παρακάλυμμα τῆς αἰσχύνης. ὁ μὲν οὖν δῆμος ἡσθεὶς ὀμόσαντος ἀνεκρότησε καὶ κατευφήμησε, τοὺς δὲ ἀρίστους κατήφεια δεινὴ καὶ μῖσος ἔσχε τοῦ Μαρίου τῆς μεταβολῆς, ὤμνυσαν οὖν ἅπαντες ἐφεξῆς δεδιότες τὸν δῆμον ἄχρι Μετέλλου· Μέτελλος δέ, καίπερ ἀντιβολούντων καὶ δεομένων τῶν φίλων ὀμόσαι καὶ μὴ περιβαλεῖν ἑαυτὸν ἐπιτιμίοις ἀνηκέστοις, ἃ κατὰ τῶν μὴ ὀμνυόντων ὁ Σατορνῖνος εἰσέφερεν, οὐχ ὐφήκατο τοῦ φρονήματος οὐδὲ ὤμοσεν, ἀλλ’ ἐμμένων τῷ ἤθει καὶ πᾶν παθεῖν δεινὸν ἐπὶ τῷ μηθὲν αἰσχρὸν ἐργάσασθαι παρεσκευασμένος ἀπῆλθεν ἐκ τῆς ἀγορᾶς, διαλεγόμενος τοῖς περὶ αὐτὸν ὡς τὸ κακόν τι πρᾶξαι φαῦλον εἴη, τὸ δὲ καλὸν μέν, ἀκινδύνως δέ, κοινόν, ἴδιον δὲ ἀνδρὸς ἀγαθοῦ τὸ μετὰ κινδύνων τὰ καλὰ πράσσειν. ἐκ τούτου ψηφίζεται Σατορνῖνος ἐπικηρύξαι τοὺς ὑπάτους ὅπως πυρὸς καὶ ὕδατος καὶ στέγης εἴργηται Μέτελλος· καὶ τὸ φαυλότατον αὐτοῖς τοῦ πλήθους παρῆν ἕτοιμον ἀποκτιννύναι τὸν ἄνδρα, τῶν δὲ βελτίστων περιπαθούντων καὶ συντρεχόντων πρὸς τὸν Μέτελλον οὐκ εἴα στασιάζειν δι’ αὐτόν, ἀλλὰ ἀπῆλθεν ἐκ τῆς πόλεως ἔμφρονι λογισμῷ χρησάμενος. ἢ γὰρ ἀμεινόνων, ἔφη, τῶν πραγμάτων γενομένων καὶ τοῦ δήμου μετανοήσαντος ἀφίξομαι παρακαλούμενος· ἢ μενόντων ὁμοίων ἀπηλλάχθαι κράτιστον. ἀλλὰ γὰρ ὅσης μὲν ἀπέλαυσεν εὐνοίας παρὰ τὴν φυγὴν καὶ τιμῆς Μέτελλος, ὃν δὲ τρόπον ἐν Ῥόδῳ φιλοσοφῶν διῃτήθη, βέλτιον ἐν τοῖς περὶ ἐκείνου γραφομένοις εἰρήσεται.", "st": "Mar. 29.4"}, {"sp": "N", "t": "Μάριος δὲ τὸν Σατορνῖνον ἀντὶ τῆς ὑπουργίας ταύτης ἐπὶ πᾶν προϊόντα τόλμης καὶ δυνάμεως περιορᾶν ἀναγκαζόμενος, ἔλαθεν οὐκ ἀνεκτὸν ἀπεργασάμενος κακόν, ἀλλ’ ἄντικρυς ὅπλοις καὶ σφαγαῖς ἐπὶ τυραννίδα καὶ πολιτείας ἀνατροπὴν πορευόμενον. αἰδούμενος δὲ τοὺς κρατίστους, θεραπεύων δὲ τοὺς πολλούς, ἔργον ἀνελεύθερον ἐσχάτως ὑπέμεινε καὶ παλίμβολον. ἐλθόντων γάρ ὡς αὐτὸν ὑπὸ νύκτα τῶν πρώτων ἀνδρῶν καὶ παρακαλούντων ἐπὶ τὸν Σατορνῖνον, ἑτέραις θύραις ἐκεῖνον ὑπεδέξατο τούτων ἀγνοούντων. εἶτα πρόφασιν λέγων πρὸς ἀμφοτέρους κοιλίας διάρροιαν, νῦν μὲν ὡς τούτους, νῦν δὲ ὡς ἐκεῖνον ἐπὶ τῆς οἰκίας ἀνά μέρος διατρέχων συνέκρουε καὶ παρώξυνεν. οὐ μὴν ἀλλὰ καὶ τῆς βουλῆς καὶ τῶν ἱππέων συνισταμένων καὶ ἀγανακτούντων ἐξήνεγκεν εἰς ἀγορὰν τὰ ὅπλα, καὶ καταδιωχθέντας αὐτοὺς εἰς τὸ Καπετώλιον εἷλε δίψει· τοὺς γὰρ ὀχετοὺς ἀπέκοψεν, οἱ δ’ ἀπειπόντες ἐκεῖνον ἐκάλουν καὶ παρέδωκαν σφᾶς αὐτοὺς διὰ τῆς λεγομένης δημοσίας πίστεως. ἐπεὶ δὲ παντοῖος γενόμενος ὑπὲρ τοῦ σῶσαι τοὺς ἄνδρας οὐδὲν ὤνησεν, ἀλλὰ κατιόντες εἰς ἀγορὰν ἀνῃρέθησαν, ἐκ τούτου τοῖς τε δυνατοῖς ἅμα καὶ τῷ δήμῳ προσκεκρουκώς, τιμητείας παραπεσούσης ἐπίδοξος ὢν οὐ μετῆλθεν, ἀλλ’ εἴασεν ἑτέρους ὑποδεεστέρους αἱρεθῆναι, δεδιὼς ἀποτυχεῖν. ἄλλως δὲ αὐτὸς ἐκαλλωπίζετο πολλοῖς μὴ θέλειν ἀπεχθάνεσθαι τοὺς βίους αὐτῶν καὶ τὰ ἤθη πικρῶς ἐξετάζων.", "st": "Mar. 30.1"}, {"sp": "N", "t": "δόγματος δὲ εἰσφερομένου Μέτελλον ἀπὸ τῆς φυγῆς ἀνακαλεῖσθαι, πολλὰ καὶ διὰ λόγων καὶ δι’ ἔργων μάτην ἐναντιωθεὶς τέλος ἀπεῖπε· καὶ δεξαμένου τὴν γνώμην τοῦ δήμου προθύμως, οὐχ ὑπομένων κατερχόμενον ἐπιδεῖν τὸν Μέτελλον ἐξέπλευσεν εἰς Καππαδοκίαν καὶ Γαλατίαν, λόγῳ μὲν ἀποδώσων ἃς εὔξατο τῇ Μητρὶ τῶν θεῶν θυσίας, ἑτέραν δὲ τῆς ἀποδημίας ἔχων ὑπόθεσιν λανθάνουσαν τοὺς πολλούς. ἀφυὴς γὰρ ὢν πρὸς εἰρήνην καὶ ἀπολίτευτος, ηὐξημένος δὲ τοῖς πολέμοις, εἶτα κατὰ μικρὸν αὖθις ὑπὸ ἀργίας καὶ ἡσυχίας ἀπὸ ἀπομαραίνεσθαι τὴν δύναμιν αὐτόν καὶ τὴν δόξαν οἰόμενος, ἐζήτει καινῶν πραγμάτων ἀρχάς, ἤλπιζε γὰρ τοὺς βασιλεῖς συνταράξας καὶ Μιθριδάτην ἐπίδοξον ὄντα πολεμήσειν ἀναστήσας καὶ παροξύνας, εὐθὺς ἐπ’ αὐτὸν ἡγεμὼν αἱρεθήσεσθαι καὶ νέων μὲν τὴν πόλιν θριάμβων, σκύλων δὲ Ποντικῶν καὶ πλούτου βασιλικοῦ τὸν οἶκον ἐμπλήσειν. διὸ καὶ Μιθριδάτου πάσῃ χρησαμένου θεραπείᾳ καὶ τιμῇ πρὸς αὐτόν οὐ καμφθεὶς οὐδὲ ὑπείξας, ἀλλ’ εἰπών, ἢ μεῖζον, ὦ βασιλεῦ, πειρῶ δύνασθαι Ῥωμαίων, ἢ ποίει σιωπῇ τὸ προστασσόμενον, ἐξέπληξεν αὐτόν, ὡς φωνῆς μὲν πολλάκις, παρρησίας δὲ τότε πρῶτον ἀκούσαντα Ῥωμαϊκῆς.", "st": "Mar. 31.1"}, {"sp": "N", "t": "ἐπανελθὼν δὲ εἰς Ῥώμην οἰκίαν ἐδείματο τῆς ἀγορᾶς πλησίον, εἴτε, ὡς αὐτὸς ἔλεγε, τοὺς θεραπεύοντας αὐτὸν ἐνοχλεῖσθαι μὴ βουλόμενος μακρὰν βαδίζοντας, εἴτε τοῦτο αἴτιον οἰόμενος εἶναι τοῦ μὴ πλείονας ἄλλων ἐπὶ θύρας αὐτοῦ φοιτᾶν. τὸ δ’ οὐκ ἦν ἄρα τοιοῦτον ἀλλ’ ὁμιλίας χάριτι καὶ πολιτικαῖς χρείαις ἑτέρων λειπόμενος ὥσπερ ὄργανον πολεμικὸν ἐπ’ εἰρήνης παρημεχεῖτο. καὶ τοῖς μὲν ἄλλοις ἧττον ἤχθετο παρευδοκιμούμενος, σφόδρα δὲ αὐτὸν ἠνία Σύλλας ἐκ τοῦ πρὸς ἐκεῖνον αὐξανόμενος φθόνου τῶν δυνατῶν καὶ τὰς πρὸς ἐκεῖνον διαφορὰς ἀρχὴν πολιτείας ποιούμενος, ἐπεὶ δὲ καὶ Βόκχος ὁ Νομὰς σύμμαχος Ῥωμαίων ἀναγεγραμμένος ἔστησεν ἐν Καπετωλίῳ Νίκας τροπαιοφόρους καὶ παρ’ αὐταῖς ἐν εἰκόσι χρυσαῖς Ἰουγούρθαν ἐγχειριζόμενον ὑπὸ αὐτοῦ Σύλλᾳ, τοῦτο ἐξέστησεν ὀργῇ καὶ φιλονεικίᾳ Μάριον, ὡς Σύλλα περισπῶντος εἰς ἑαυτὸν τὰ ἔργα, καὶ παρεσκευάζετο βίᾳ τὰ ἀναθήματα καταβάλλειν. ἀντεφιλονίκει δὲ Σύλλας, καὶ τὴν στάσιν ὅσον οὔπω φερομένην εἰς μέσον ἐπέσχεν ὁ συμμαχικὸς πόλεμος ἐξαίφνης ἐπὶ τὴν πόλιν ἀναρραγείς. τὰ γὰρ μαχιμώτατα τῶν Ἰταλικῶν ἐθνῶν καὶ πολυανθρωπότατα κατὰ τῆς Ῥώμης συνέστησαν καὶ μικρὸν ἐδέησαν συγχέαι τὴν ἡγεμονίαν, οὐ μόνον ὅπλοις ἐρρωμένα καὶ σώμασιν, ἀλλὰ καὶ τόλμαις στρατηγῶν καὶ δεινότησι χρησάμενα θαυμασταῖς καὶ ἀντιπάλοις.", "st": "Mar. 32.1"}, {"sp": "N", "t": "οὗτος ὁ πόλεμος τοῖς πάθεσι ποικίλος γενόμενος καὶ ταῖς τύχαις πολυτροπώτατος ὅσον Σύλλᾳ προσέθηκε δόξης καὶ δυνάμεως, τοσοῦτον ἀφεῖλε Μαρίου, βραδὺς γάρ ἐφάνη ταῖς ἐπιβολαῖς, ὄκνου τε περὶ πάντα καὶ μελλήσεως ὑπερέβαλλεν’,, εἴτε τοῦ γήρως τὸ δραστήριον ἐκεῖνο καὶ θερμὸν ἐν αὐτῷ κατασβεννύντος ἑξηκοστὸν γάρ ἤδη καὶ πέμπτον ἔτος ὑπερέβαλλεν, εἴτε, ὡς αὐτὸς ἔλεγε, περὶ νεῦρα γεγονὼς νοσώδης καὶ σώματι δύσεργος ὢν ὑπέμενε παρὰ δύναμιν αἰσχύνῃ τὰς στρατείας. οὐ μὴν ἀλλὰ καὶ τότε μάχῃ τε μεγάλῃ νικήσας ἑξακισχιλίους ἀνεῖλε τῶν πολεμίων, καὶ λαβὴν οὐδαμῇ παρέσχεν αὐτοῖς, ἀλλὰ καὶ περιταφρευόμενος ἠνέσχετο καὶ χλευαζόμενος καὶ καλούμενος οὐ παρωξύνθη. λέγεται δὲ Ποπλίου Σίλωνος, ὃς μέγιστον εἶχε τῶν πολεμίων ἀξίωμα καὶ δύναμιν, εἰπόντος πρὸς αὐτόν, εἰ μέγας εἶ στρατηγός, ὦ Μάριε, διαγώνισαι καταβάς, ἀποκρίνασθαι, Σὺ μὲν οὖν, εἰ μέγας εἶ στρατηγός, ἀνάγκασόν με διαγωνίσασθαι μὴ βουλόμενον. πάλιν δέ ποτε τῶν μὲν πολεμίων καιρὸν ἐπιχειρήσεως παραδιδόντων, τῶν δὲ Ῥωμαίων ἀποδειλιασάντων, ὡς ἀνεχώρησαν ἀμφότεροι, συναγαγὼν εἰς ἐκκλησίαν τοὺς στρατιώτας, ἀπορῶ, φησί, πότερον εἴπω τοὺς πολεμίους ἀνανδροτέρους ἢ ὑμᾶς· οὔτε γάρ ἐκεῖνοι τὸν νῶτον ὑμῶν οὔτε ὑμεῖς ἐκείνων τὸ ἰνίον ἰδεῖν ἐδυνήθητε. τέλος δὲ ἀφῆκε τὴν στρατηγίαν ὡς ἐξαδυνατῶν τῷ σώματι διὰ τὴν ἀσθένειαν.", "st": "Mar. 33.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἤδη τῶν Ἰταλῶν ἐγκεκλικότων ἐμνηστεύοντο πολλοὶ τὸν Μιθριδατικὸν πόλεμον ἐν Ῥώμῃ διὰ τῶν δημαγωγῶν, παρὰ πᾶσαν ἐλπίδα Σουλπίκιος δήμαρχος, ἀνήρ θρασύτατος, παραγαγὼν Μάριον ἀπεδείκνυεν ἀνθύπατον στρατηγὸν ἐπὶ Μιθριδάτην. καὶ ὁ δῆμος διέστη, τῶν μὲν αἱρουμένων τὰ Μαρίου, τῶν δὲ Σύλλαν καλούντων καὶ τὸν Μάριον ἐπὶ θερμὰ κελευόντων εἰς Βαΐας βαδίζειν καὶ τὸ σῶμα θεραπεύειν ὑπό τε γήρως καὶ ῥευμάτων ἀπειρηκός, ὡς αὐτὸς ἔλεγε. καὶ γάρ ἦν ἐκεῖ περὶ Μισηνοὺς τῷ Μαρίῳ πολυτελὴς οἰκία, τρυφὰς ἔχουσα καὶ διαίτας θηλυτέρας ἢ κατ’ ἄνδρα πολέμων τοσούτων καὶ στρατειῶν αὐτουργόν. ταύτην λέγεται μυριάδων ἑπτὰ ἡμίσους Κορνηλία πρίασθαι χρόνου δ’ οὐ πάνυ πολλοῦ γενομένου Λεύκιος Λεύκολλος ὠνεῖται μυριάδων πεντήκοντα καὶ διακοσίων οὕτως ταχέως ἀνέδραμεν ἡ πολυτέλεια καὶ τοσαύτην ἐπίδοσιν τὰ πράγματα πρὸς τρυφὴν ἔλαβεν. οὐ μὴν ἀλλὰ Μάριος φιλοτίμως πάνυ καὶ μειρακιωδῶς ἀποτριβόμενος τὸ γῆρας καὶ τὴν ἀσθένειαν ὁσημέραι κατέβαινεν εἰς τὸ πεδίον, καὶ μετὰ τῶν νεανίσκων γυμναζόμενος ἐπεδείκνυε τὸ σῶμα κοῦφον μὲν ὅπλοις, ἔποχον δὲ ταῖς ἱππασίαις, καίπερ οὐκ εὐσταλὴς γεγονώς ἐν γήρᾳ τὸν ὄγκον, ἀλλ’ εἰς σάρκα περιπληθῆ καὶ βαρεῖαν ἐνδεδωκώς.", "st": "Mar. 34.1"}, {"sp": "N", "t": "ἐνίοις μὲν οὖν ἤρεσκε ταῦτα πράττων, καὶ κατιόντες ἐθεῶντο τὴν φιλοτιμίαν αὐτοῦ καὶ τὰς ἁμίλλας, τοῖς δὲ βελτίστοις ὁρῶσιν οἰκτείρειν ἐπῄει τὴν πλεονεξίαν καὶ τὴν φιλοδοξίαν, ὅτι πλουσιώτατος ἐκ πένητος καὶ μέγιστος ἐκ μικροῦ γεγονώς ὅρον οὐκ οἶδεν εὐτυχίας, οὐδὲ θαυμαζόμενος ἀγαπᾷ καὶ ἀπολαύων ἐν ἡσυχίᾳ τῶν παρόντων, ἀλλ’ ὥσπερ ἐνδεὴς ἁπάντων εἰς Καππαδοκίαν καὶ τὸν Εὔξεινον Πόντον ἄρας ἐκ θριάμβων καὶ δόξης ἐκφέρει τοσοῦτον γῆρας, Ἀρχελάῳ καὶ Νεοπτολέμῳ τοῖς Μιθριδάτου σατράπαις διαμαχούμενος. αἱ δὲ πρὸς ταῦτα τοῦ Μαρίου δικαιολογίαι παντάπασιν ἐφαίνοντο ληρώδεις· ἔφη γάρ ἐθέλειν τὸν υἱὸν ἀσκῆσαι παρὼν αὐτὸς ἐπὶ στρατείας.", "st": "Mar. 34.4"}, {"sp": "N", "t": "ταῦτα τὴν πόλιν ἐκ πολλῶν χρόνων ὕπουλον γεγενημένην καὶ νοσοῦσαν ἀνέρρηξεν, εὐφυέστατον εὑρόντος ὄργανον Μαρίου πρὸς τὸν κοινὸν ὄλεθρον τὸ Σουλπικίου θράσος, ὃς διὰ τἆλλα πάντα θαυμάζων καὶ ζηλῶν τὸν Σατορνῖνον ἀτολμίαν ἐπεκάλει τοῖς πολιτεύμασιν αὑτὸν καὶ μέλλησιν. αὐτὸς δὲ μὴ μέλλων ἑξακοσίους μὲν εἶχε περὶ αὑτὸν τῶν ἱππικῶν οἷον δορυφόρους, καὶ τούτους ἀντισύγκλητον ὠνόμαζεν, ἐπελθὼν δὲ μεθ’ ὅπλων ἐκκλησιάζουσι τοῖς ὑπάτοις τοῦ μὲν ἑτέρου φυγόντος ἐξ ἀγορᾶς τὸν υἱὸν ἐγκαταλαβὼν ἀπέσφαξε, Σύλλας δὲ παρὰ τὴν οἰκίαν τοῦ Μαρίου διωκόμενος, οὐδενὸς ἂν προσδοκήσαντος, εἰσέπεσε· καὶ τοὺς μὲν διώκοντας ἔλαθε δρόμῳ παρενεχθέντας, ὑπ’ αὐτοῦ δὲ Μαρίου λέγεται κατὰ θύρας ἑτέρας ἀσφαλῶς ἀποπεμφθεὶς διεκπεσεῖν εἴς τὸ στρατόπεδον. αὐτὸς δὲ Σύλλας ἐν τοῖς ὑπομνήμασιν οὔ φησι καταφυγεῖν πρὸς τὸν Μάριον, ἀλλ’ ἀπαλλαχθῆναι βουλευσόμενος ὑπὲρ ὧν Σουλπίκιος ἠνάγκαζεν αὑτὸν ἄκοντα ψηφίσασθαι, περισχὼν ἐν κύκλῳ ξίφεσι γυμνοῖς καὶ συνελάσας πρὸς τὸν Μάριον, ἄχρι οὗ προελθὼν ἐκεῖθεν εἴς ἀγοράν, ὡς ἠξίουν ἐκεῖνοι, τὰς ἀπραξίας ἔλυσε. γενομένων δὲ τούτων ὅ τε Σουλπίκιος ἤδη κρατῶν ἐπεχειροτόνησε τε Μαρίῳ τὴν στρατηγίαν, ὅ τε Μάριος ἐν παρασκευῇ τῆς ἐξόδου καθειστήκει, καὶ δύο χιλιάρχους ἐξέπεμψε παραληψομένους τὸ Σύλλα στράτευμα. Σύλλας δὲ τοὺς στρατιώτας παροξύνας ἦσαν δὲ τρισμυρίων καὶ πεντακισχιλίων οὐ μείους ὁπλῖται προήγαγεν ἐπὶ τὴν Ῥώμην. τοὺς δὲ χιλιάρχους, οὓς ἐπέπεμψε Μάριος, προσπεσόντες οἱ στρατιῶται διέφθειραν.", "st": "Mar. 35.1"}, {"sp": "N", "t": "πολλοὺς δὲ καὶ Μάριος ἐν Ῥώμῃ τῶν Σύλλα φίλων ἀνῃρήκει, καὶ δούλοις ἐλευθερίαν ἐκήρυττεν ἐπὶ συμμαχίᾳ· λέγονται δὲ τρεῖς μόνοι προσγενέσθαι. μικρὰ δ’· ἀντιστὰς εἰσελάσαντι τῷ Σύλλᾳ καὶ ταχέως ἐκβιασθεὶς ἔφυγε. τῶν δὲ περὶ αὐτόν, ὡς πρῶτον ἐξέπεσε τῆς πόλεως, διασπαρέντων, σκότους ὄντος εἴς τι τῶν ἐπαυλίων αὑτοῦ Σολώνιον κατέφυγε. καὶ τὸν μὲν υἱὸν ἔπεμψεν ἐκ τῶν Μουκίου τοῦ πενθεροῦ χωρίων οὐ μακρὰν ὄντων τὰ ἐπιτήδεια ληψόμενον, αὐτὸς δὲ καταβὰς εἴς Ὠστίαν, φίλου τινὸς Νουμερίου πλοῖον αὐτῷ παρασκευάσαντος, οὐκ ἀναμείνας τὸν υἱόν, ἀλλὰ Γράνιον ἔχων μεθ’ αὑτοῦ τὸν πρόγονον ἐξέπλευσεν. ὁ δὲ νεανίας, ὡς ἦλθεν εἴς τὰ χωρία τοῦ Μουκίου, λαμβάνων τι καὶ σκευαζόμενος ἡμέρας καταλαβούσης οὐ παντάπασι τοὺς πολεμίους ἔλαθεν, ἀλλ’ ἦλθον ἱππεῖς ἐλαύνοντες καθ’ ὑπόνοιαν ἐπὶ τὸν τόπον· οὓς ὁ τῶν ἀγρῶν ἐπιμελητὴς προϊδόμενος ἔκρυψε τὸν Μάριον ἐν ἁμάξῃ κυάμους ἀγούσῃ, καὶ βοῦς ὑποζεύξας ἀπήντα τοῖς ἱππεῦσιν εἴς πόλιν ἐλαύνων τὴν ἅμαξαν. οὕτω δὲ πρὸς τὴν οἰκίαν τῆς γυναικὸς ὁ Μάριος διακομισθεὶς καὶ λαβὼν ὅσων ἐδεῖτο νυκτὸς ἐπὶ θάλασσαν ἧκε καὶ νεὼς ἐπιβὰς εἴς Λιβύην πλεούσης ἀπεπέρασεν.", "st": "Mar. 35.5"}, {"sp": "N", "t": "ὁ δὲ πρεσβύτης Μάριος ὡς ἀνήχθη, πνεύματι φορῷ κομιζόμενος παρὰ τὴν Ἰταλίαν ἐφοβήθη Γεμίνιόν τινα τῶν ἐν Ταρρακίνῃ δυνατῶν ἐχθρὸν αὑτοῦ, καὶ ταῖς ναύταις προεῖπεν εἴργεσθαι Ταρρακίνης. οἱ δὲ ἐβούλοντο μὲν αὐτῷ χαρίζεσθαι, τοῦ δὲ πνεύματος εἰς πελάγιον μεθισταμένου καὶ κλύδωνα κατάγοντος πολὺν οὔτε τὸ πορθμεῖον ἐδόκει περικλυζόμενον ἀνθέξειν, τοῦ τε Μαρίου δυσφοροῦντος καὶ κακῶς ἔχοντος ὑπὸ ναυτίας μόλις ἀντιλαμβάνονται τῶν περὶ τὸ Κίρκαιον αἰγιαλῶν. τοῦ δὲ χειμῶνος αὐξανομένου καὶ τῶν σιτίων ἐπιλειπόντων ἐκβάντες ἐπλάζοντο πρὸς οὐδένα σκοπόν, ἀλλ’ οἷα συμβαίνει ταῖς μεγάλαις ἀπορίαις ἀεὶ φεύγειν ἐκ τοῦ παρόντος ὡς χαλεπωτάτου καὶ τὰς ἐλπίδας ἔχειν ἐν τοῖς ἀδήλοις. ἐπεὶ πολεμία μὲν ἐκείνοις ἡ γῆ, πολεμία δὲ ἡ θάλασσα, φοβερὸν δὲ ἦν ἀνθρώποις περιπεσεῖν, φοβερὸν δὲ μὴ περιπεσεῖν δι’ ἔνδειαν τῶν ἀναγκαίων. οὐ μὴν ἀλλ’ ὀψέ που βοτῆρσιν ὀλίγοις ἐντυγχάνουσιν, οἳ δοῦναι μὲν οὐδὲν ἔσχον αὐτοῖς δεομένοις, γνωρίσαντες δὲ τὸν Μάριον ἐκέλευον ἀπαλλάττεσθαι τὴν ταχίστην· ὀλίγον γάρ ἔμπροσθεν αὐτόθι κατὰ ζήτησιν αὐτοῦ συχνοὺς ἱππέας ὀφθῆναι διεξελαύνοντας. ἐν παντὶ δὴ γεγονὼς ἀπορίας, μάλιστα δὲ νηστείᾳ τῶν περὶ αὐτὸν ἀπαγορευόντων, τότε μὲν ἐκτραπόμενος τῆς ὁδοῦ καὶ καταβαλὼν ἑαυτὸν εἰς ὕλην βαθεῖαν ἐπιπόνως διενυκτέρευσε. τῇ δ’ ὑστεραίᾳ συνηγμένος ὑπ’ ἐνδείας καὶ τῷ σώματι πρὶν ἐκλελύσθαι παντάπασι χρήσασθαι βουλόμενος ἐχώρει παρὰ τὸν αἰγιαλόν, ἐπιθαρσύνων τοὺς ἑπομένους καὶ δεόμενος μὴ προαποκάμνειν τῆς τελευταίας ἐλπίδος, ἐφ’ ἣν ἑαυτὸν φυλάττει μαντεύμασι παλαιοῖς πιστεύων. νέος γὰρ ὢν ἔτι παντελῶς καὶ διατρίβων κατ’ ἀγρὸν ὑποδέξασθαι τῷ ἱματίῳ καταφερομένην ἀετοῦ νεοττιὰν ἑπτὰ νεοττοὺς ἔχουσαν· ἰδόντας δὲ τοὺς γονεῖς καὶ θαυμάσαντας διαπυνθάνεσθαι τῶν μάντεων τοὺς δὲ εἰπεῖν ὡς ἐπιφανέστατος ἀνθρώπων ἔσοιτο καὶ τὴν μεγίστην ἡγεμονίαν καὶ ἀρχὴν ἑπτάκις αὐτὸν λαβεῖν ἀναγκαῖον εἴη.", "st": "Mar. 36.1"}, {"sp": "N", "t": "ταῦτα οἱ μὲν ἀληθῶς τῷ Μαρίῳ συντυχεῖν οὕτω λέγουσιν οἱ δὲ τοὺς τότε καὶ παρὰ τὴν ἄλλην φυγὴν ἀκούσαντας αὐτοῦ καὶ πιστεύσαντας ἀναγράψαι πρᾶγμα κομιδῇ μυθῶδες. ἀετὸς γὰρ οὐ τίκτει πλεῖον τῶν δυεῖν, ἀλλὰ καὶ Μουσαῖον ἐψεῦσθαι λέγουσιν εἰπόντα περὶ τοῦ ἀετοῦ, ὡς", "st": "Mar. 36.6"}, {"sp": "N", "t": "τρία μὲν τίκτει, δύο δ’ ἐκλέπει, ἓν δ’ ἀλεγίζει.", "st": "Mar. 36.6b"}, {"sp": "N", "t": "τὸ μέντοι πολλάκις ἐν τῇ φυγῇ καὶ ταῖς ἐσχάταις ἀπορίαις Μάριον εἰπεῖν ὡς ἄχρις ἑβδόμης ὑπατείας πρόεισιν, ὁμολογούμενόν ἐστιν.", "st": "Mar. 36.6c"}, {"sp": "N", "t": "ἤδη δὲ Μιντούρνης, πόλεως Ἰταλικῆς, ὅσον εἴκοσι σταδίων ἀπέχοντες ὁρῶσιν ἱππέων ἴλην πρόσωθεν ἐλαύνοντας ἐπ’ αὐτοὺς καὶ κατὰ τύχην ὁλκάδας δύο φερομένας. ὡς οὖν ἕκαστος ποδῶν εἶχε καὶ ῥώμης καταδραμόντες ἐπὶ τὴν θάλασσαν καὶ καταβαλόντες ἑαυτοὺς προσενήχοντο ταῖς ναυσί. καὶ λαβόμενοι τῆς ἑτέρας οἱ περὶ τὸν Γράνιον ἀπεπέρασαν εἰς τὴν ἄντικρυς νῆσον Αἰναρία καλεῖται· αὐτὸν δὲ Μάριον βαρὺν ὄντα τῷ σώματι καὶ δυσμεταχείριστον οἰκέται δύο μόλις καὶ χαλεπῶς ὑπέρ τῆς θαλάττης ἐξάραντες εἰς τὴν ἑτέραν ἔθεντο ναῦν, ἤδη τῶν ἱππέων ἐφεστώτων καὶ διακελευομένων ἀπὸ γῆς τοῖς ναύταις κατάγειν τὸ πλοῖον ἢ τὸν Μάριον ἐκβαλόντας αὐτοὺς ἀποπλεῖν ὅπῃ χρῄζοιεν. ἱκετεύοντος δὲ τοῦ Μαρίου καὶ δακρύοντος, οἱ κύριοι τῆς ὁλκάδος ὡς ἐν ὀλίγῳ πολλὰς ἐπ’ ἀμφότερα τῆς γνώμης τροπὰς λαβόντες ὅμως ἀπεκρίναντο τοῖς ἱππεῦσι μὴ προέσθαι τὸν Μάριον. ἐκείνων δὲ πρὸς ὀργὴν ἀπελασάντων αὖθις ἑτέρων γενόμενοι λογισμῶν κατεφέροντο πρὸς τὴν γῆν· καὶ περὶ τὰς ἐκβολὰς τοῦ Λίριος ποταμοῦ διάχυσιν λιμνώδη λαμβάνοντος ἀγκύρας βαλόμενοι παρεκάλουν αὐτὸν ἐκβῆναι καὶ τροφὴν ἐπὶ γῆς λαβεῖν καὶ τὸ σῶμα θεραπεῦσαι κεκακωμένον, ἄχρι οὗ φορὰ γένηται· γίγνεσθαι δὲ τὴν εἰωθυῖαν ὥραν τοῦ πελαγίου μαραινομένου καὶ τῶν ἑλῶν αὔραν ἀναδιδόντων ἐπιεικῶς διαρκῆ. ταῦτα πεισθεὶς ὁ Μάριος ἔπραττε· καὶ τῶν ναυτῶν ἐξελομένων αὐτὸν ἐπὶ τὴν γῆν κατακλινεὶς ἔν τινι πόᾳ πορρωτάτω τοῦ μέλλοντος εἶχε τὴν διάνοιαν. οἱ δὲ εὐθὺς ἐπιβάντες ἐπὶ τὴν ναῦν καὶ τὰς ἀγκύρας ἀναλαβόντες ἔφευγον, ὡς οὔτε καλὸν ἐκδοῦναι τὸν Μάριον αὐτοῖς οὔτε σῴζειν ἀσφαλές, οὕτω δὴ πάντων ἔρημος ἀπολειφθείς πολὺν μὲν χρόνον ἄναυδος ἐπὶ τῆς ἀκτῆς ἔκειτο, μόλις δέ πως ἀναλαβὼν ἑαυτὸν ἐπορεύετο ταλαιπώρως ἀνοδίαις· καὶ διεξελθὼν ἕλη βαθέα καὶ τάφρους ὕδατος καὶ πηλοῦ γεμούσας ἐπιτυγχάνει καλύβῃ λιμνουργοῦ γέροντος, ὃν περιπεσὼν ἱκέτευε γενέσθαι σωτῆρα καὶ βοηθὸν ἀνδρός, εἰ διαφύγοι τὰ παρόντα, μείζονας ἐλπίδων ἀμοιβὰς ἀποδώσοντος. ὁ δὲ ἄνθρωπος, εἴτε πάλαι γινώσκων εἴτε πρὸς τὴν ὄψιν ὡς κρείττονα θαυμάσας, ἀναπαύσασθαι μὲν ἔφη δεομένῳ τὸ σκηνύδριον ἐξαρκεῖν, εἰ δέ τινας ὑποφεύγων πλάζοιτο κρύψειν αὐτὸν ἐν τόπῳ μᾶλλον ἡσυχίαν ἔχοντι. τοῦ δὲ Μαρίου δεηθέντος τοῦτο ποιεῖν, ἀγαγὼν αὐτὸν εἰς τὸ ἕλος καὶ πτῆξαι κελεύσας ἐν χωρίῳ κοίλῳ παρὰ τὸν ποταμὸν ἐπέβαλε τῶν τε καλάμων πολλοὺς καὶ τῆς ἄλλης ἐπιφέρων ὕλης ὅση κούφη καὶ περιπέσσειν ἀβλαβῶς δυναμένη.", "st": "Mar. 37.1"}, {"sp": "N", "t": "χρόνου δὲ οὐ πολλοῦ διαγενομένου ψόφος αὐτῷ καὶ θόρυβος ἀπὸ τῆς καλύβης προσέπεσεν. ὁ γὰρ Γεμίνιος· ἐκ Ταρρακίνης ἔπεμψε πολλοὺς ἐπὶ τὴν δίωξιν, ὧν ἔνιοι κατὰ τύχην ἐκεῖ προσελθόντες ἐξεφόβουν καὶ κατεβόων τοῦ γέροντος ὡς ὑποδεδεγμένου καὶ κατακρυβόντος πολέμιον Ῥωμαίων. ἐξαναστὰς οὖν ὁ Μάριος καὶ ἀποδυσάμενος καθῆκεν ἑαυτὸν εἰς τὴν λίμνην ὕδωρ παχὺ καὶ τελματῶδες ἔχουσαν. ὅθεν οὐ διέλαθε τοὺς ζητοῦντας, ἀλλ’ ἀνασπασθεὶς βορβόρου κατάπλεως γυμνὸς εἰς Μιντούρνας ἀνήχθη καὶ παρεδόθη τοῖς ἄρχουσιν. ἦν γάρ εἰς ἅπασαν ἤδη πόλιν ἐξενηνεγμένον παράγγελμα περὶ τοῦ Μαρίου δημοσίᾳ διώκειν καὶ κτείνειν τοὺς λαβόντας. ὅμως δὲ βουλεύσασθαι πρότερον ἐδόκει τοῖς ἄρχουσι καὶ κατατίθενται τὸν Μάριον εἰς οἰκίαν Φαννίας γυναικὸς οὐκ εὐμενῶς δοκούσης ἔχειν πρὸς αὑτὸν ἐξ αἰτίας παλαιᾶς.", "st": "Mar. 38.1"}, {"sp": "N", "t": "ἦν γὰρ ἀνήρ τῇ Φαννίᾳ Τιτίννιος· τούτου διαστᾶσα τὴν φερνὴν ἀπῄτει λαμπρὰν οὖσαν. ὁ δὲ μοιχείαν ἐνεκάλει· καὶ γίνεται Μάριος ὑπατεύων τὸ ἕκτον δικαστής. ἐπεὶ δὲ τῆς δίκης λεγομένης ἐφαίνετο καὶ τὴν Φαννίαν ἀκόλαστον γεγονέναι καὶ τὸν ἄνδρα τοιαύτην εἰδότα λαβεῖν καὶ συμβιῶσαι πολὺν χρόνον, ἀμφοτέρους δυσχεράνας τὸν μὲν ἄνδρα τὴν φερνὴν ἐκέλευσεν ἀποδοῦναι, τῆς δὲ γυναικὸς ἀτιμίας ἕνεκα τῇ καταδίκῃ χαλκοῦς τέσσαρας προσετίμησεν.", "st": "Mar. 38.4"}, {"sp": "N", "t": "οὐ μὴν ἥ γε Φαννίᾳ τότε πάθος γυναικὸς ἠδικημένης ἔλαβεν, ἀλλ’ ὡς εἶδε τὸν Μάριον, πορρωτάτω γενομένη τοῦ μνησικακεῖν, ἐκ τῶν παρόντων ἐπεμελεῖτο καὶ παρεθάρρυνεν αὐτόν, ὁ δὲ κἀκείνην ἐπῄνει καὶ θαρρεῖν ἔφασκε· σημεῖον γάρ αὐτῷ γεγονέναι χρηστόν.", "st": "Mar. 38.5"}, {"sp": "N", "t": "ἦν δὲ τοιοῦτον. ὡς ἀγόμενος πρὸς τῇ οἰκίᾳ τῆς Φαννίας ἐγεγόνει, τῶν θυρῶν ἀνοιχθεισῶν ὄνος ἔνδοθεν ἐχώρει δρόμῳ, πιόμενος ἀπὸ κρήνης ἐγγὺς ἀπορρεούσης· προσβλέψας δὲ τῷ Μαρίῳ λαμυρόν τι καὶ γεγηθὸς ἔστη πρῶτον ἐναντίον, εἶτα φωνὴν ἀφῆκε λαμπρὰν καὶ παρεσκίρτησε παρ’ αὑτὸν ὑπὸ γαυρότητος. ἐξ οὗ συμβαλὼν ὁ Μάριος ἔφασκεν ὡς διὰ θαλάσσης αὐτῷ μᾶλλον ἢ διὰ γῆς ὑποδείκνυσι σωτηρίαν τὸ δαιμόνιον τὸν γάρ ὄνον οὐ προσέχοντα τῇ ξηρᾷ τροφῇ πρὸς τὸ ὕδωρ ἀπ’ αὐτοῦ τραπέσθαι.", "st": "Mar. 38.6"}, {"sp": "N", "t": "ταῦτα διαλεχθεὶς τῇ Φαννίᾳ καθ’ αὑτὸν ἀνεπαύετο, τὴν θύραν τοῦ δωματίου προσθεῖναι κελεύσας.", "st": "Mar. 38.6b"}, {"sp": "N", "t": "βουλευομένοις δὲ τοῖς ἄρχουσι καὶ συνέδροις τῶν Μιντουρνησίων ἔδοξε μὴ μέλλειν, ἀλλὰ διαχρήσασθαι τὸν ἄνδρα. καὶ τῶν μὲν πολιτῶν οὐδεὶς ὑπέστη τὸ ἔργον, ἱππεὺς δὲ Γαλάτης τὸ γένος ἢ Κίμβρος ἀμφοτέρως γὰρ ἱστορεῖται λαβών ξίφος ἐπεισῆλθεν αὐτῷ. τοῦ δὲ οἰκήματος ἐν ᾧ ἔτυχε μέρει κατακείμενος οὐ πάνυ λαμπρὸν φῶς ἔχοντος, ἀλλ’ ὄντος ἐπισκίου, λέγεται τὰ μὲν ὄμματα τοῦ Μαρίου φλόγα πολλὴν ἐκβάλλοντα τῷ στρατιώτῃ φανῆναι, φωνὴν δὲ μεγάλην ἐκ τοῦ παλισκίου γενέσθαι, σὺ δὴ τολμᾷς, ἄνθρωπε, Γάϊον Μάριον ἀνελεῖν; ἐξῆλθεν οὖν εὐθὺς ὁ βάρβαρος φυγῇ, καὶ τὸ ξίφος ἐν μέσῳ καταβαλὼν ἐχώρει διὰ θυρῶν, τοῦτο μόνον βοῶν, οὐ δύναμαι Γάϊον Μάριον ἀποκτεῖναι. πάντας οὖν ἔκπληξις ἔσχεν, εἶτα οἶκτος καὶ μετάνοια τῆς γνώμης καὶ κατάμεμψις ἑαυτῶν ὡς βούλευμα βεβουλευκότων ἄνομον καὶ ἀχάριστον ἐπ’ ἀνδρὶ σωτῆρι τῆς Ἰταλίας, ᾧ μὴ βοηθῆσαι δεινὸν ἦν. ἴτω δ’οὖν ὅπῃ χρῄζει φυγάς ἀνατλησόμενος ἀλλαχόθι τὸ μεμορμένον. ἡμεῖς δὲ εὐχώμεθα μὴ νεμεσῆσαι θεοὺς Μάριον ἄπορον καὶ γυμνὸν ἐκ τῆς πόλεως ἐκβαλοῦσιν. ὑπὸ τοιούτων λογισμῶν εἰσπεσόντες ἀθρόοι καὶ περισχόντες αὐτὸν ἐξῆγον ἐπὶ τὴν θάλασσαν. ἄλλου δὲ ἄλλο τι προθύμως ὑπηρετοῦντος καὶ σπευδόντων ἁπάντων ἐγίνετο τριβὴ τοῦ χρόνου. τὸ γάρ τῆς λεγομένης Μαρίκας ἄλσος, ὃ σέβονται καὶ παραφυλάττουσι μηθὲν ἐκεῖθεν ἐκκομισθῆναι τῶν εἰσκομισθέντων, ἐμποδὼν ἦν τῆς ἐπὶ θάλασσαν ὁδοῦ, καὶ κύκλῳ περιιόντας ἔδει βραδύνειν, ἄχρι οὗ τῶν πρεσβυτέρων τις ἐκβοήσας ἔφη μηδεμίαν ἄβατον μηδ’· ἀπόρεντον ὁδὸν εἶναι δι’ ἧς σῴζεται Μάριος, καὶ πρῶτος αὐτὸς λαβών τι τῶν κομιζομένων ἐπὶ ναῦν διὰ τοῦ τόπου διεξῆλθε.", "st": "Mar. 39.1"}, {"sp": "N", "t": "τοιαύτῃ προθυμίᾳ ταχὺ πάντων συμπορισθέντων καὶ Βηλαίου τινὸς ναῦν τῷ Μαρίῳ παρασχόντος, ὃς ὕστερον πίνακα τῶν πράξεων ἐκείνων γραψάμενος ἀνέθηκεν εἰς τὸ ἱερὸν ὅθεν ἐμβὰς ὁ Μάριος ἀνήχθη, τῷ πνεύματι φέροντι χρώμενος ἐφέρετό πως κατὰ τύχην πρὸς Αἰναρίαν τὴν νῆσον, ὅπου τὸν Γράνιον καὶ τοὺς ἄλλους φίλους εὑρών ἔπλει μετ’ αὐτῶν ἐπὶ Λιβύης. ὕδατος δὲ ἐπιλιπόντος αὐτοὺς ἀναγκαίως Σικελίᾳ κατὰ τὴν Ἐρυκίνην προσέσχον. ἔτυχε δὲ περὶ τοὺς τόπους ἐκείνους ὁ Ῥωμαίων ταμίας παραφυλάσσων, καὶ μικροῦ μὲν αὐτὸν ἀποβάντα τὸν Μάριον εἷλεν, ἀπέκτεινε δὲ περὶ ἑκκαίδεκα τῶν ὑδρευομένων. Μάριος δὲ κατὰ σπουδὴν ἀναχθεὶς καὶ διαπεράσας τὸ πέλαγος πρὸς Μήνιγγα τὴν νῆσον, ἐνταῦθα διαπυνθάνεται πρῶτον ὡς ὁ παῖς αὐτοῦ διασέσῳσται μετὰ Κεθήγου καὶ πορεύονται πρὸς τὸν βασιλέα τῶν Νομάδων Ἰάμψαν, δεησόμενοι βοηθεῖν. ἐφ’ οἷς μικρὸν ἀναπνεύσας ἐθάρρησεν ἀπὸ τῆς νήσου πρὸς τὴν Καρχηδονίαν προσβαλεῖν·", "st": "Mar. 40.1"}, {"sp": "N", "t": "ἐστρατήγει δὲ τῆς Λιβύης τότε Σεξτίλιος, ἀνήρ Ῥωμαῖος, οὔτε φαῦλον οὐθὲν οὔτε χρηστὸν ἐκ Μαρίου προειληφώς, ἀλλ’ ὅσον ἀπ’ οἴκτου τι προσδοκώμενος ὠφελήσειν. ἄρτι δὲ αὐτοῦ μετ’ ὀλίγων ἀποβεβηκότος ὑπηρέτης ἀπαντήσας καὶ καταστὰς ἐναντίον εἶπεν, ἀπαγορεύει σοι Σεξτίλιος ὁ στρατηγός, ὦ Μάριε, Λιβύης ἐπιβαίνειν· εἰ δὲ μή, φησὶν ἀμυνεῖν τοῖς τῆς βουλῆς δόγμασιν, ὡς Ῥωμαίων πολεμίῳ χρώμενος. ταῦτα ἀκούσαντα τὸν Μάριον ὑπὸ λύπης καὶ βαρυθυμίας ἀπορία λόγων ἔσχε, καὶ πολὺν χρόνον ἡσυχίαν ἦγε δεινὸν εἰς τὸν ὑπηρέτην ἀποβλέπων, ἐρομένου δὲ ἐκείνου τί φράζει καὶ τί λέγει πρὸς τὸν στρατηγόν, ἀπεκρίνατο μέγα στενάξας, ἄγγελλε τοίνυν ὅτι Γάϊον Μάριον ἐν τοῖς Καρχηδόνος ἐρειπίοις φυγάδα καθεζόμενον εἶδες, οὐ κακῶς ἅμα τήν τε τῆς πόλεως ἐκείνης τύχην καὶ τὴν ἑαυτοῦ μεταβολὴν ἐν παραδείγματος λόγῳ θέμενος.", "st": "Mar. 40.4"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Ἰάμψας ὁ βασιλεὺς τῶν Νομάδων ἐπαμφοτερίζων τοῖς λογισμοῖς ἐν τιμῇ μὲν ἦγε τοὺς περὶ τὸν νέον Μάριον, ἀπιέναι δὲ βουλομένους ἔκ τινος ἀεὶ προφάσεως κατεῖχε, καὶ δῆλος ἦν ἐπ’ οὐδενὶ χρηστῷ ποιούμενος τὴν ἀναβολήν. οὐ μὴν ἀλλὰ συμβαίνει τι τῶν εἰκότων αὐτοῖς πρὸς σωτηρίαν. ὁ γάρ νέος Μάριος εὐπρεπὴς ὢν τὴν ὄψιν ἠνία τινὰ τῶν παλλακίδων τοῦ βασιλέως παρ’ ἀξίαν πράττων· ὁ δὲ οἶκτος οὗτος ἀρχὴ καὶ πρόφασις ἦν ἔρωτος. τὸ μὲν οὖν πρῶτον ἀπετρίβετο τὴν ἄνθρωπον· ὡς δὲ οὔτε φυγῆς ἑτέραν ὁδὸν ἑώρα καὶ τὰ παρ’ ἐκείνης σπουδαιότερον ἢ πρὸς ἡδονὴν ἀκόλαστον διεπράττετο, δεξάμενος τὴν φιλοφροσύνην καὶ συνεκπεμφθεὶς ὑπ’ αὐτῆς ἀπέδρα μετὰ τῶν φίλων καὶ διέφυγε πρὸς τὸν Μάριον. ἐπεὶ δὲ ἀλλήλους ἠσπάσαντο, πορευόμενοι παρὰ τὴν θάλασσαν ἐντυγχάνουσι σκορπίοις μαχομένοις· καὶ τὸ σημεῖον ἐφάνη τῷ Μαρίῳ πονηρόν. εὐθὺς οὖν ἁλιάδος ἐπιβάντες εἰς Κέρκιναν διεπέρων, νῆσον ἀπέχουσαν οὐ πολὺ τῆς ἠπείρου· καὶ τοσοῦτον ἔφθασαν ὅσον ἀνηγμένων αὐτῶν ἱππεῖς ὁρᾶσθαι παρὰ τοῦ βασιλέως ἐλαύνοντας ἐπὶ τὸν τόπον ὅθεν ἀνήχθησαν. τοῦτον οὐδενὸς ἐλάττονα κίνδυνον ἔδοξεν ἐκφυγεῖν ὁ Μάριος.", "st": "Mar. 40.5"}, {"sp": "N", "t": "ἐν δὲ Ῥώμῃ Σύλλας μὲν ἠκούετο τοῖς Μιθριδάτου πολεμεῖν στρατηγοῖς περὶ Βοιωτίαν, οἱ δὲ ὕπατοι στασιάσαντες ἐχώρουν εἰς ὅπλα. καὶ μάχης γενομένης Ὀκτάβιος μὲν κρατήσας ἐξέβαλε Κίνναν ἐπιχειροῦντα τυραννικώτερον ἄρχειν, καὶ κατέστησεν ἀντ’ αὐτοῦ Κορνήλιον Μερούλλαν ὕπατον, ὁ δὲ Κίννας ἐκ τῆς ἄλλης Ἰταλίας συναγαγὼν δύναμιν αὖθις διεπολέμει πρὸς αὐτούς. ταῦτα τῷ Μαρίῳ πυνθανομένῳ πλεῦσαι τὴν ταχίστην ἐφαίνετο· καὶ παραλαβὼν ἐκ τῆς Λιβύης Μαυρουσίων τινὰς ἱππότας καὶ τῶν ἀπὸ τῆς Ἰταλίας τινὰς καταφερομένων, συναμφοτέρους οὐ πλείονας χιλίων γενομένους, ἀνήχθη. προσβαλὼν δὲ Τελαμῶνι τῆς Τυρρηνίας καὶ ἀποβὰς ἐκήρυττε δούλοις ἐλευθερίαν· καὶ τῶν αὐτόθι γεωργούντων καὶ νεμόντων ἐλευθέρων κατὰ δόξαν αὐτοῦ συντρεχόντων ἐπὶ τὴν θάλασσαν ἀναπείθων τοὺς ἀκμαιοτάτους ἐν ἡμέραις ὀλίγαις χεῖρα μεγάλην ἤθροισε καὶ τεσσαράκοντα ναῦς ἐπλήρωσεν.", "st": "Mar. 41.1"}, {"sp": "N", "t": "εἰδὼς δὲ τὸν μὲν Ὀκτάβιον ἄριστον ἄνδρα καὶ τῷ δικαιοτάτῳ τρόπῳ βουλόμενον ἄρχειν, τὸν δὲ Κίνναν ὕποπτόν τε τῷ Σύλλᾳ καὶ πολεμοῦντα τῇ καθεστώσῃ πολιτείᾳ, τούτῳ προσνέμειν ἑαυτὸν ἔγνω μετὰ τῆς δυνάμεως, ἔπεμψεν οὖν ἐπαγγελλόμενος ὡς ὑπάτῳ πάντα ποιήσειν τὰ προστασσόμενα. δεξαμένου δὲ τοῦ Κίννα καὶ προσαγορεύσαντος αὐτὸν ἀνθύπατον, ῥάβδους δὲ καὶ τἆλλα παράσημα τῆς ἀρχῆς ἀποστείλαντος, οὐκ ἔφη πρέπειν αὐτοῦ ταῖς τύχαις τὸν κόσμον, ἀλλ’ ἐσθῆτι φαύλῃ κεχρημένος καὶ κομῶν ἀφ’ ἧς ἔφυγεν ἡμέρας, ὑπὲρ ἑβδομήκοντα γεγονὼς ἔτη βάδην προσῄει, βουλόμενος μὲν ἐλεεινὸς εἶναι, τῷ δὲ οἴκτῳ συμμέμικτο τὸ οἰκεῖον τῆς ὄψεως αὐτοῦ πλέον τὸ φοβερόν, καὶ διέφαινεν ἡ κατήφεια τὸν θυμὸν οὐ τεταπεινωμένον, ἀλλ’ ἐξηγριωμένον ὑπὸ τῆς μεταβολῆς.", "st": "Mar. 41.3"}, {"sp": "N", "t": "ἀσπασάμενος δὲ τὸν Κίνναν καὶ τοῖς στρατιώταις ἐντυχὼν εὐθὺς εἴχετο τοῦ ἔργου καὶ μεγάλην μεταβολὴν τῶν πραγμάτων ἐποίησε. πρῶτον μὲν γάρ ταῖς ναυσὶ τὰ σιτηγὰ περικόπτων καὶ τοὺς ἐμπόρους ληιζόμενος ἐκράτησε τῆς ἀγορᾶς, ἔπειτα τὰς παραλίους πόλεις ἐπιπλέων ᾕρει. τέλος δὲ τὴν Ὠστίαν αὐτὴν λαβὼν ἐκ προδοσίας τά τε χρήματα διήρπασε καὶ τῶν ἀνθρώπων τοὺς πολλοὺς ἀπέκτεινε, καὶ γεφυρώσας τὸν ποταμὸν ἀπέκοψε κομιδῇ τὰς ἐκ θαλάσσης εὐπορίας τῶν πολεμίων. ἄρας δὲ τῷ στρατῷ πρὸς τὴν πόλιν ἐχώρει καὶ τὸ καλούμενον Ἰανοῦκλον ὄρος κατέσχεν, οὐ τοσοῦτον ἀπειρίᾳ τοῦ Ὀκταβίου τὰ πράγματα βλάπτοντος, ὅσον ἀκριβείᾳ τῶν δικαίων προϊεμένου τὰ χρειώδη παρὰ τὸ συμφέρον, ὅς γε πολλῶν κελευόντων αὐτὸν ἐπ’ ἐλευθερίᾳ καλεῖν τοὺς οἰκέτας οὐκ ἔφη δούλοις μεταδώσειν τῆς πατρίδος, ἧς Γάϊον Μάριον εἴργει τοῖς νόμοις ἀμύνων. ἐπεὶ δὲ Μέτελλος υἱὸς Μετέλλου τοῦ στρατηγήσαντος ἐν Λιβύῃ καὶ διὰ Μάριον ἐκπεσόντος ἧκεν εἰς Ῥώμην καὶ πολὺ τοῦ Ὀκταβίου στρατηγικώτερος ἐφαίνετο, καταλιπόντες οἱ στρατιῶται τὸν Ὀκτάβιον ἧκον ὡς ἐκεῖνον ἄρχειν δεόμενοι καὶ σῴζειν τὴν πόλιν εὖ γὰρ ἀγωνιεῖσθαι καὶ κρατήσειν ἔμπειρον ἡγεμόνα καὶ δραστήριον λαβόντες. ἀγανακτήσαντος δὲ τοῦ Μετέλλου καὶ κελεύοντος ἀπιέναι πρὸς τὸν ὕπατον, ᾤχοντο πρὸς τοὺς πολεμίους, ὑπεξέστη δὲ καὶ Μέτελλος ἀπογνοὺς τὴν πόλιν.", "st": "Mar. 42.1"}, {"sp": "N", "t": "Ὀκτάβιον δὲ Χαλδαῖοι καὶ θύται τινὲς καὶ σιβυλλισταὶ πείσαντες ἐν Ῥώμῃ κατέσχον, ὡς εὖ γενησομένων. ὁ γὰρ ἀνήρ οὗτος δοκεῖ, τἆλλα Ῥωμαίων εὐγνωμονέστατος γενόμενος καὶ μάλιστα δὴ τὸ πρόσχημα τῆς ὑπατείας ἀκολάκευτον ἐπὶ τῶν πατρίων ἐθῶν καὶ νόμων ὥσπερ διαγραμμάτων ἀμεταβόλων διαφυλάξας, ἀρρωστίᾳ τῇ περὶ ταῦτα χρήσασθαι, πλείονα συνὼν χρόνον ἀγύρταις καὶ μάντεσιν ἢ πολιτικοῖς καὶ πολεμικοῖς ἀνδράσιν. οὗτος μὲν οὖν, πρὶν εἰσελθεῖν τὸν Μάριον, ὑπὸ τῶν προπεμφθέντων ἀπὸ τοῦ βήματος κατασπασθεὶς ἐσφάττετο καὶ λέγεται διάγραμμα Χαλδαϊκὸν ἐν τοῖς κόλποις αὐτοῦ φονευθέντος εὑρεθῆναι. καὶ τὸ πρᾶγμα πολλὴν ἀλογίαν εἶχε, τὸ δυεῖν ἡγεμόνων ἐπιφανεστάτων Μάριον μὲν ὀρθῶσαι τὸ μὴ καταφρονῆσαι μαντικῆς, Ὀκτάβιον δὲ ἀπολέσαι.", "st": "Mar. 42.4"}, {"sp": "N", "t": "οὕτω δὴ τῶν πραγμάτων ἐχόντων ἡ βουλὴ συνελθοῦσα πρέσβεις ἐξέπεμψε πρὸς Κίνναν καὶ Μάριον, εἰσιέναι καὶ φείδεσθαι δεομένη τῶν πολιτῶν. Κίννας μὲν οὖν ὡς ὕπατος ἐπὶ τοῦ δίφρου καθήμενος ἐχρημάτιζε καὶ φιλανθρώπους ἀποκρίσεις ἔδωκε τοῖς πρέσβεσι, Μάριος δὲ τῷ δίφρῳ παρειστήκει φθεγγόμενος μὲν οὐδέν, ὑποδηλῶν δὲ ἀεὶ τῇ βαρύτητι τοῦ προσώπου καὶ τῇ στυγνότητι τοῦ βλέμματος ὡς εὐθὺς ἐμπλήσων φόνων τὴν πόλιν. ἐπεὶ δὲ ἀναστάντες ἐβάδιζον, Κίννας μὲν εἰσῄει δορυφορούμενος, Μάριος δὲ παρὰ ταῖς πύλαις ὑποστὰς εἰρωνεύετο πρὸς ὀργήν, φυγὰς εἶναι λέγων καὶ τῆς πατρίδος εἴργεσθαι κατὰ τὸν νόμον, εἰ δὲ χρῄζοι τις αὐτοῦ παρόντος, ἑτέρᾳ ψήφῳ λυτέον εἶναι τὴν ἐκβάλλουσαν, ὡς δὴ νόμιμός τις ὢν ἀνήρ καὶ κατιὼν εἰς πόλιν ἐλευθέραν· ἐκάλει δὴ τὸ πλῆθος εἰς ἀγορὰν καὶ πρὸ τοῦ τρεῖς ἢ τέτταρας φυλὰς ἐνεγκεῖν τὴν ψῆφον ἀφεὶς τὸ πλάσμα καὶ τὴν φυγαδικὴν ἐκείνην δικαιολογίαν κατῄει, δορυφόρους ἔχων λογάδας ἐκ τῶν προσπεφοιτηκότων δούλων, οὓς Βαρδυαίους προσηγόρευσεν. οὗτοι πολλοὺς μὲν ἀπὸ φωνῆς, πολλοὺς δὲ ἀπὸ νεύματος ἀνῄρουν προστάσσοντος αὐτοῦ· καὶ τέλος Ἀγχάριον, ἄνδρα βουλευτὴν καὶ στρατηγικόν, ἐντυγχάνοντα τῷ Μαρίῳ καὶ μὴ προσαγορευθέντα καταβάλλουσιν ἔμπροσθεν αὐτοῦ ταῖς μαχαίραις τύπτοντες. ἐκ δὲ τούτου καὶ τῶν ἄλλων ὅσους ἀσπασαμένους μὴ προσαγορεύσειε μηδὲ ἀντασπάσαιτο, τοῦτο αὐτὸ σύμβολον ἦν ἀποσφάττειν εὐθὺς ἐν ταῖς ὁδοῖς, ὥστε καὶ τῶν φίλων ἕκαστον ἀγωνίας μεστὸν εἶναι καὶ φρίκης ὁσάκις ἀσπασόμενοι τῷ Μαρίῳ πελάζοιεν· κτεινομένων δὲ πολλῶν Κίννας μὲν ἀμβλὺς ἦν καὶ μεστὸς ἤδη τοῦ φονεύειν, Μάριος δὲ καθ’ ἑκάστην ἡμέραν ἀκμάζοντι τῷ θυμῷ καὶ διψῶντι διὰ πάντων ἐχώρει τῶν ὁπωσοῦν ἐν ὑποψίᾳ γεγονότων. καὶ πᾶσα μὲν ὁδός, πᾶσα δὲ πόλις τῶν διωκόντων καὶ κυνηγετούντων τοὺς ὑποφεύγοντας καὶ κεκρυμμένους ἔγεμεν. ἠλέγχετο δὲ καὶ ξενίας καὶ φιλίας πίστις οὐδὲν ἔχουσα παρὰ τὰς τύχας βέβαιον· ὀλίγοι γάρ ἐγένοντο παντάπασιν οἱ μὴ προδόντες αὐτοῖς τοὺς παρὰ σφᾶς καταφυγόντας. ἄξιον οὖν ἄγασθαι καὶ θαυμάσαι τοὺς τοῦ Κορνούτου θεράποντας οἳ, οἱ τὸν δεσπότην ἀποκρύψαντες οἴκοι, νεκρὸν δέ τινα τῶν πολλῶν ἀναρτήσαντες ἐκ τοῦ τραχήλου καὶ περιθέντες αὐτῷ χρυσοῦν δακτύλιον ἐπεδείκνυον τοῖς Μαρίου δορυφόροις καὶ κοσμήσαντες ὡς ἐκεῖνον αὐτὸν ἔθαπτον. ὑπενόησε δὲ οὐδείς, ἀλλ’ οὕτω λαθὼν ὁ Κορνοῦτος ὑπὸ τῶν οἰκετῶν εἰς Γαλατίαν διεκομίσθη.", "st": "Mar. 43.1"}, {"sp": "N", "t": "χρηστῷ δὲ καὶ Μᾶρκος Ἀντώνιος ὁ ῥήτωρ φίλῳ χρησάμενος ἠτύχησεν. ὁ γάρ ἄνθρωπος ἦν μὲν πένης καὶ δημοτικός, ὑποδεξάμενος δὲ πρῶτον ἄνδρα Ῥωμαίων καὶ φιλοφρονούμενος ἐκ τῶν παρόντων, οἰκέτην ἔπεμψε πρός τινα τῶν ἐγγὺς καπήλων ληψόμενον οἶνον. διαγευομένου δὲ ἐπιμελέστερον καὶ βελτίονα μετρῆσαι κελεύοντος ἠρώτησεν ὁ κάπηλος ὁ τι παθὼν οὐχὶ τὸν νέον, ὥσπερ εἴωθεν, ὠνεῖται καὶ δημοτικόν, ἀλλὰ τοῦ σπουδαίου καὶ πολυτελοῦς. ἁπλῶς δέ πως ἐκείνου φράσαντος ὡς πρὸς συνήθη καὶ γνώριμον, ὅτι Μᾶρκον Ἀντώνιον ὁ δεσπότης ἑστιᾷ παρ’ αὐτῷ κρυπτόμενον, ἀσεβὴς καὶ μιαρὸς ὢν ὁ κάπηλος ἅμα τῷ τὸν οἰκέτην ἀπελθεῖν αὐτὸς συνέτεινε πρὸς Μάριον ἤδη περὶ δεῖπνον ὄντα, καὶ προσαχθεὶς ὡμολόγησε παραδώσειν αὐτῷ τὸν Ἀντώνιον. ἀκούσας οὖν ἐκεῖνος ἐκκραγεῖν λέγεται μέγα καὶ ταῖς χερσὶν ὑφ’· ἡδονῆς ἀνακροτῆσαι· καὶ μικροῦ μὲν ἐδέησεν ἐξαναστὰς αὐτὸς ἐπὶ τὸν τόπον φέρεσθαι, τῶν δὲ φίλων κατασχόντων Ἄννιον ἔπεμπε καὶ στρατιώτας μετ’ αὐτοῦ κελεύσας κατὰ τάχος τὴν κεφαλὴν τοῦ Ἀντωνίου κομίζειν. ὡς οὖν ἧκον ἐπὶ τὴν οἰκίαν, ὁ μὲν Ἄννιος ὑπέστη παρὰ τὰς θύρας, οἱ δὲ στρατιῶται διὰ κλιμάκων ἀναβάντες εἰς τὸ δωμάτιον καὶ θεασάμενοι τὸν Ἀντώνιον ἄλλος ἄλλον ἐπὶ τὴν σφαγὴν ἀνθ’ ἑαυτοῦ παρεκάλει καὶ προὐβάλλετο. τοιαύτη δὲ τις ἦν, ὡς ἔοικε, τοῦ ἀνδρὸς ἡ τῶν λόγων σειρὴν καὶ χάρις, ὥστε ἀρξαμένου λέγειν καὶ παραιτεῖσθαι τὸν θάνατον ἅψασθαι μὲν οὐδεὶς ἐτόλμησεν οὐδὲ ἀντιβλέψαι, κάτω δὲ κύψαντες ἐδάκρυον ἅπαντες, διατριβῆς δὲ γενομένης ἀναβὰς ὁ Ἄννιος ὁρᾷ τὸν μὲν Ἀντώνιον διαλεγόμενον, τοὺς δὲ στρατιώτας ἐκπεπληγμένους καὶ κατακεκηλημένους ὑπ’ αὐτοῦ· κακίσας οὖν ἐκείνους καὶ προσδραμὼν αὐτὸς ἀποτέμνει τὴν κεφαλήν.", "st": "Mar. 44.1"}, {"sp": "N", "t": "Κάτλος δὲ Λουτάτιος Μαρίῳ συνάρξας καὶ συνθριαμβεύσας ἀπὸ Κίμβρων, ἐπεὶ πρὸς τοὺς δεομένους ὑπὲρ αὐτοῦ καὶ παραιτουμένους ὁ Μάριος τοσοῦτον μόνον εἶπεν, ἀποθανεῖν δεῖ, κατακλεισάμενος εἰς οἴκημα καὶ πολλοὺς ἄνθρακας ἐκζωπυρήσας ἀπεπνίγη.", "st": "Mar. 44.5"}, {"sp": "N", "t": "ῥιπτουμένων δὲ τῶν σωμάτων ἀκεφάλων καὶ πατουμένων ἐν ταῖς ὁδοῖς ἔλεος οὐκ ἦν, ἀλλὰ φρίκη καὶ τρόμος ἁπάντων πρὸς τὴν ὄψιν. ἠνία δὲ μάλιστα τὸν δῆμον ἡ τῶν καλουμένων Βαρδυαίων ἀσέλγεια, τοὺς γάρ δεσπότας ἐν ταῖς οἰκίαις σφάττοντες ᾔσχυνον μὲν αὐτῶν παῖδας, ἐμείγνυντο δὲ βίᾳ ταῖς δεσποίναις, ἀκατάσχετοι δὲ ἦσαν ἁρπάζοντες καὶ μιαιφονοῦντες, ἕως οἱ περὶ Κίνναν καὶ Σερτώριον συμφρονήσαντες ἐπέθεντο κοιμωμένοις αὐτοῖς ἐν τῷ στρατοπέδῳ καὶ κατηκόντισαν ἅπαντας.", "st": "Mar. 44.6"}, {"sp": "N", "t": "ἐν τούτῳ δὲ ὥσπερ τροπαίας τινος ἀμειβούσης ἐφοίτων ἄγγελοι πανταχόθεν ὡς Σύλλας συνῃρηκὼς τὸν Μιθριδατικὸν πόλεμον καὶ τὰς ἐπαρχίας ἀνειληφὼς ἐπιπλέοι μετὰ πολλῆς δυνάμεως, καὶ τοῦτο βραχεῖαν ἐπίσχεσιν ἐποίησε καὶ παῦλαν ὀλίγην ἀφάτων κακῶν, ὅσον οὔπω τὸν πόλεμον ἥκειν ἐπ’ αὐτοὺς οἰομένων. ὕπατος μὲν οὖν ἀπεδείχθη τὸ ἕβδομον Μάριος, καὶ προελθὼν αὐταῖς Καλάνδαις Ἰανουαρίαις, ἔτους ἀρχῇ, Σέξτον τινὰ Λουκῖνον κατεκρήμνισεν ὃ κἀκείνοις καὶ τῇ πόλει τῶν αὖθις ἐδόκει κακῶν γεγονέναι σημεῖον μέγιστον.", "st": "Mar. 45.1"}, {"sp": "N", "t": "αὐτὸς δὲ ἤδη τοῖς τε πόνοις ἀπειρηκὼς καὶ ταῖς φροντίσιν οἷον ὑπέραντλος ὢν καὶ κατάπονος, τὴν ψυχὴν πρὸς τοσαύτην αὖθις ἐπίνοιαν νέου πολέμου καὶ καινῶν ἀγώνων καὶ φόβων ὑπὸ ἐμπειρίας δεινῶν καὶ καμάτου τρέμουσαν οὐκ ἀνέφερε, λογιζόμενος ὡς οὐ πρὸς Ὀκτάβιον οὐδὲ Μερούλαν σύγκλυδος ὁμίλου καὶ στασιώδους ὄχλου στρατηγοὺς ὁ κίνδυνος ἔσοιτο, Σύλλας δὲ ἐκεῖνος ἔπεισιν ὁ τῆς πατρίδος αὐτὸν ἐξελάσας πάλαι, νῦν δὲ Μιθριδάτην συνεσταλκὼς εἰς τὸν Εὔξεινον Πόντον. ὑπὸ τοιούτων θραυόμενος λογισμῶν, καὶ τὴν μακρὰν ἄλην αὐτοῦ καὶ φυγὰς καὶ κινδύνους διὰ γῆς καὶ θαλάττης ἐλαυνομένου λαμβάνων πρὸ ὀφθαλμῶν, εἰς ἀπορίας ἐνέπιπτε δεινὰς καὶ νυκτερινὰ δείματα καὶ ταραχώδεις ὀνείρους, ἀεί τινος ἀκούειν φθεγγομένου δοκῶν", "st": "Mar. 45.2"}, {"sp": "N", "t": "δειναὶ γάρ κοῖται καὶ ἀποιχομένοιο λέοντος.", "st": "Mar. 45.2b"}, {"sp": "N", "t": "μάλιστα δὲ πάντων φοβούμενος τὰς ἀγρυπνίας ἐνέβαλεν εἰς πότους ἑαυτὸν καὶ μέθας ἀώρους καὶ παρ’ ἡλικίαν, ὥσπερ ἀπόδρασιν τῶν φροντίδων τὸν ὕπνον μηχανώμενος. τέλος δὲ ὡς ἧκέ τις ἀπαγγέλλων ἀπὸ θαλάσσης, νέοι προσπίπτοντες αὐτῷ φόβοι, τὰ μὲν δέει τοῦ μέλλοντος, τὰ δὲ ὥσπερ ἄχθει καὶ κόρῳ τῶν παρόντων, ῥοπῆς βραχείας ἐπιγενομένης εἰς νόσον κατηνέχθη πλευρῖτιν, ὡς ἱστορεῖ Ποσειδώνιος ὁ φιλόσοφος, αὐτὸς εἰσελθεῖν καὶ διαλεχθῆναι περὶ ὧν ἐπρέσβευεν ἤδη νοσοῦντι φάσκων αὐτῷ. Γάϊος δέ τις Πείσων, ἀνήρ ἱστορικὸς, ἱστορεῖ τὸν Μάριον ἀπὸ δείπνου περιπατοῦντα μετὰ τῶν φίλων ἐν λόγοις γενέσθαι περὶ τῶν καθ’ ἑαυτὸν πραγμάτων, ἄνωθεν ἀρξάμενον· καὶ τὰς ἐπ’ ἀμφότερα πολλάκις μεταβολὰς ἀφηγησάμενον εἰπεῖν ὡς οὐκ ἔστι νοῦν ἔχοντος ἀνδρὸς ἔτι τῇ τύχῃ πιστεύειν ἑαυτόν· ἐκ δὲ τούτου τοὺς παρόντας ἀσπασάμενον καὶ κατακλιθέντα συνεχῶς ἡμέρας ἑπτὰ τελευτῆσαι. τινὲς δὲ τὴν φιλοτιμίαν αὐτοῦ φασιν ἐν τῇ νόσῳ παντάπασιν ἀποκαλυφθεῖσαν εἰς ἄτοπον ἐξοκεῖλαι παρακοπήν, οἰομένου τὸν Μιθριδατικὸν στρατηγεῖν πόλεμον, εἶτα, ὥσπερ ἐπ’ αὐτῶν εἰώθει τῶν ἀγώνων, σχήματα παντοδαπὰ καὶ κινήματα σώματος μετὰ συντόνου κραυγῆς καὶ πυκνῶν ἀλαλαγμάτων ἀποδιδόντος. οὕτως δεινὸς αὐτῷ καὶ δυσπαραμύθητος ἐκ φιλαρχίας καὶ ζηλοτυπίας ἔρως ἐντετήκει τῶν πράξεων ἐκείνων. διὸ ἔτη μὲν ἑβδομήκοντα βεβιωκώς, ὕπατος δὲ πρῶτος ἀνθρώπων ἑπτάκις ἀνηγορευμένος, οἶκόν τε καὶ πλοῦτον ἀρκοῦντα βασιλείαις ὁμοῦ πολλαῖς κεκτημένος, ὠδύρετο τὴν ἑαυτοῦ τύχην ὡς ἐνδεὴς καὶ ἀτελὴς ὧν ἐπόθει προαποθνῄσκων.", "st": "Mar. 45.4"}, {"sp": "N", "t": "Πλάτων μὲν οὖν ἤδη πρὸς τῷ τελευτᾶν γενόμενος ὕμνει τὸν αὐτοῦ δαίμονα καὶ τὴν τύχην, ὅτι πρῶτον μὲν ἄνθρωπος, εἶτα Ἕλλην, οὐ βάρβαρος οὐδὲ ἄλογον τῇ φύσει θηρίον γένοιτο, πρὸς δὲ τούτοις, ὅτι τοῖς Σωκράτους χρόνοις ἀπήντησεν ἡ γένεσις αὐτοῦ. καὶ νὴ Δία τὸν Ταρσέα λέγουσιν Ἀντίπατρον ὡσαύτως ὑπὸ τὴν τελευτὴν ἀναλογιζόμενον ὧν τύχοι μακαρίων μηδὲ τῆς εἰς Ἀθήνας οἴκοθεν εὐπλοίας ἐπιλαθέσθαι, καθάπερ φιλοχρήστου τῆς τύχης ἅπασαν δόσιν εἰς μεγάλην χάριν τιθέμενον καὶ σῴζοντα τῇ μνήμῃ διὰ τέλους, ἧς οὐδέν ἐστιν ἀνθρώπῳ ταμιεῖον ἀγαθῶν βεβαιότερον. τοὺς δὲ ἀμνήμονας ς καὶ ἀνοήτους ὑπεκρεῖ τὰ γιγνόμενα μετὰ τοῦ χρόνου· διὸ μηθὲν στέγοντες μηδὲ διατηροῦντες ἀεὶ κενοὶ μὲν ἀγαθῶν, πλήρεις δὲ ἐλπίδων πρὸς τὸ μέλλον ἀποβλέπουσι, τὸ παρὸν προϊέμενοι. καίτοι τὸ μὲν ἂν ἡ τύχη κωλῦσαι δύναιτο, τὸ δὲ ἀναφαίρετόν ἐστιν· ἀλλ’ ὅμως τοῦτο τῆς τύχης ὡς ἀλλότριον ἐκβάλλοντες ἐκεῖνο τὸ ἄδηλον ὀνειρώττουσιν, εἰκότα πάσχοντες, πρὶν γὰρ ἐκ λόγου καὶ παιδείας ἕδραν ὑποβαλέσθαι καὶ κρηπῖδα τοῖς ἔξωθεν ἀγαθοῖς, συνάγοντες αὐτὰ καὶ συμφοροῦντες ἐμπλῆσαι τῆς ψυχῆς οὐ δύνανται τὸ ἀκόρεστον.", "st": "Mar. 46.1"}, {"sp": "N", "t": "ἀποθνῄσκει δ’ οὖν Μάριος ἡμέρας ἑπτακαίδεκα τῆς ἑβδόμης ὑπατείας ἐπιλαβών. καὶ μέγα ἔσχε παραυτίκα τὴν Ῥώμην χάρμα καὶ θάρσος ὡς χαλεπῆς τυραννίδος ἀπηλλαγμένην· ὀλίγαις δὲ ἡμέραις ᾔσθοντο νέον ἀντηλλαγμένοι καὶ ἀκμάζοντα ἀντὶ πρεσβύτου δεσπότην τοσαύτην ὁ υἱὸς αὐτοῦ Μάριος ὠμότητα καὶ πικρίαν ἀπεδείξατο, τοὺς ἀρίστους καὶ δοκιμωτάτους ἀναιρῶν. δόξας δὲ καὶ τολμητὴς καὶ φιλοκίνδυνος εἶναι πρὸς τοὺς πολεμίους ἐν ἀρχῇ παῖς Ἄρεος ὠνομάζετο, ταχὺ δὲ τοῖς ἔργοις ἐλεγχόμενος αὖθις Ἀφροδίτης υἱὸς ἐκαλεῖτο. τέλος δὲ κατακλεισθεὶς εἰς Πραινεστὸν ὑπὸ Σύλλα καὶ πολλὰ φιλοψυχήσας μάτην, ὡς ἦν ἄφυκτα τῆς πόλεως ἁλισκομένης, αὐτὸς αὑτὸν ἀπέκτεινεν.", "st": "Mar. 46.5"}, {"sp": "HDR", "t": "Λύσανδρος"}, {"sp": "N", "t": "ὁ Ἀκανθίων θησαυρὸς ἐν Δελφοῖς ἐπιγραφὴν ἔχει τοιαύτην· Βρασίδας καὶ Ἀκάνθιοι ἀπ’ Ἀθηναίων· διὸ καὶ πολλοὶ τὸν ἐντὸς ἑστῶτα τοῦ οἴκου παρὰ ταῖς θύραις λίθινον ἀνδριάντα Βρασίδου νομίζουσιν εἶναι. Λυσάνδρου δέ ἐστιν εἰκονικός, εὖ μάλα κομῶντος ἔθει τῷ παλαιῷ καὶ πώγωνα καθειμένου γενναῖον. οὐ γάρ, ὡς ἔνιοί φασιν, Ἀργείων μετὰ τὴν μεγάλην ἧτταν ἐπὶ πένθει καρέντων οἱ Σπαρτιᾶται πρὸς τὸ ἀντίπαλον αὐτοῖς τὰς κόμας ἀγαλλόμενοι τοῖς πεπραγμένοις ἀνῆκαν, οὐδὲ Βακχιαδῶν τῶν ἐκ Κορίνθου φυγόντων εἰς Λακεδαίμονα ταπεινῶν καὶ ἀμόρφων διὰ τὸ κείρασθαι τὰς κεφαλὰς φανέντων εἰς ζῆλον αὐτοὶ τοῦ κομᾶν ἦλθον, ἀλλὰ καὶ τοῦτο Λυκούργειόν ἐστι. καί φασιν αὐτὸν εἰπεῖν ὡς ἡ κόμη τοὺς μὲν καλοὺς εὐπρεπεστέρους ὁρᾶσθαι ποιεῖ, τοὺς δὲ αἰσχροὺς φοβερωτέρους.", "st": "Lys. 1.1"}, {"sp": "N", "t": "λέγεται δὲ ὁ Λυσάνδρου πατὴρ Ἀριστόκλειτος οἰκίας μὲν οὐ γενέσθαι βασιλικῆς, ἄλλως δὲ γένους εἶναι τοῦ τῶν Ἡρακλειδῶν. ἐτράφη δὲ ὁ Λύσανδρος ἐν πενίᾳ, καὶ παρέσχεν ἑαυτὸν εὔτακτον, ὡς εἴ τις ἄλλος, πρὸς τοὺς ἐθισμοὺς καὶ ἀνδρώδη καὶ κρείττονα πάσης ἡδονῆς, πλὴν εἴ τινα τιμωμένοις καὶ κατορθοῦσιν αἱ καλαὶ πράξεις ἐπιφέρουσι. ταύτης δὲ οὐκ αἰσχρόν ἐστιν ἡττᾶσθαι τοὺς νέους ἐν Σπάρτῃ. βούλονται γὰρ εὐθὺς ἐξ ἀρχῆς πάσχειν τι τοὺς παῖδας αὐτῶν πρὸς δόξαν, ἀλγυνομένους τε τοῖς ψόγοις καὶ μεγαλυνομένους ὑπὸ τῶν ἐπαίνων· ὁ δὲ ἀπαθὴς καὶ ἀκίνητος ἐν τούτοις ὡς ἀφιλότιμος πρὸς ἀρετὴν καὶ ἀργὸς καταφρονεῖται. τὸ μὲν οὖν φιλότιμον αὐτῷ καὶ φιλόνεικον ἐκ τῆς Λακωνικῆς παρέμεινε παιδείας ἐγγενόμενον, καὶ οὐδέν τι μέγα χρὴ τὴν φύσιν ἐν τούτοις αἰτιᾶσθαι· θεραπευτικὸς δὲ τῶν δυνατῶν μᾶλλον ἢ κατὰ Σπαρτιάτην φύσει δοκεῖ γενέσθαι, καὶ βάρος ἐξουσίας διὰ χρείαν ἐνεγκεῖν εὔκολος· ὃ πολιτικῆς δεινότητος οὐ μικρὸν ἔνιοι ποιοῦνται μέρος. Ἀριστοτέλης δὲ τὰς μεγάλας φύσεις ἀποφαίνων μελαγχολικάς, ὡς τὴν Σωκράτους καὶ Πλάτωνος καὶ Ἡρακλέους, ἱστορεῖ καὶ Λύσανδρον οὐκ εὐθύς, ἀλλὰ πρεσβύτερον ὄντα τῇ μελαγχολίᾳ περιπεσεῖν.", "st": "Lys. 2.1"}, {"sp": "N", "t": "ἴδιον δὲ αὐτοῦ μάλιστα τὸ καλῶς πενίαν φέροντα, καὶ μηδαμοῦ κρατηθέντα μηδὲ διαφθαρέντα χρήμασιν αὐτόν, ἐμπλῆσαι τὴν πατρίδα πλούτου καὶ φιλοπλουτίας καὶ παῦσαι θαυμαζομένην ἐπὶ τῷ μὴ θαυμάζειν πλοῦτον, εἰσάγοντα χρυσίου καὶ ἀργυρίου πλῆθος μετὰ τὸν Ἀττικὸν πόλεμον, ἑαυτῷ δὲ μηδεμίαν δραχμὴν ὑπολειπόμενον. Διονυσίου δὲ τοῦ τυράννου πέμψαντος αὐτοῦ ταῖς θυγατράσι πολυτελῆ χιτώνια τῶν Σικελῶν, οὐκ ἔλαβεν, εἰπὼν φοβεῖσθαι μὴ διὰ ταῦτα μᾶλλον αἰσχραὶ φανῶσιν. ἀλλ’ ὀλίγον ὕστερον πρὸς τὸν αὐτὸν τύραννον ἐκ τῆς αὐτῆς πόλεως ἀποσταλεὶς πρεσβευτής, προσπέμψαντος αὐτῷ δύο στολὰς ἐκείνου καὶ κελεύσαντος ἣν βούλεται τούτων ἑλόμενον τῇ θυγατρὶ κομίζειν, αὐτὴν ἐκείνην ἔφη βέλτιον αἱρήσεσθαι, καὶ λαβὼν ἀμφοτέρας ἀπῆλθεν.", "st": "Lys. 2.4"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῦ Πελοποννησιακοῦ πολέμου μῆκος λαμβάνοντος, καὶ μετὰ τὴν ἐν Σικελία τῶν Ἀθηναίων κακοπραγίαν αὐτίκα μὲν ἐπιδόξων ὄντων ἐκπεσεῖσθαι τῆς θαλάττης, οὐ πολλῷ δὲ ὕστερον ἀπαγορεύσειν παντάπασιν, Ἀλκιβιάδης ἀπὸ τῆς φυγῆς ἐπιστὰς τοῖς πράγμασι μεγάλην μεταβολὴν ἐποίησε καὶ κατέστησε τοὺς ναυτικοὺς ἀγῶνας εἰς ἀντίπαλον αὐτοῖς, δείσαντες οὖν οἱ Λακεδαιμόνιοι πάλιν καὶ γενόμενοι ταῖς προθυμίαις καινοὶ πρὸς τὸν πόλεμον, ὡς ἡγεμόνος τε δεινοῦ καὶ παρασκευῆς ἐρρωμενεστέρας δεόμενον, ἐκπέμπουσιν ἐπὶ τὴν τῆς θαλάττης ἡγεμονίαν Λύσανδρον. γενόμενος δ’ ἐν Ἐφέσῳ, καὶ τὴν πόλιν εὑρὼν εὔνουν μὲν αὑτῷ καὶ λακωνίζουσαν προθυμότατα, πράττουσαν δὲ τότε λυπρῶς καὶ κινδυνεύουσαν ἐκβαρβαρωθῆναι τοῖς Περσικοῖς ἔθεσι διὰ τὰς ἐπιμιξίας, ἅτε δὴ τῆς Λυδίας περικεχυμένης καὶ τῶν βασιλικῶν στρατηγῶν αὐτόθι τὰ πολλὰ διατριβόντων, στρατόπεδον βαλόμενος καὶ τὰ πλοῖα πανταχόθεν ἕλκεσθαι κελεύσας ἐκεῖ τὰ φορτηγά, καὶ ναυπηγίαν τριήρων ἐκεῖ κατασκευασάμενος, ταῖς μὲν ἐμπορίαις τοὺς λιμένας αὐτῶν ἀνέλαβεν, ἐργασίαις δὲ τὴν ἀγοράν, χρηματισμῶν δὲ τοὺς οἴκους καὶ τὰς τέχνας ἐνέπλησεν, ὥστε πρῶτον ἀπ’ ἐκείνου τοῦ χρόνου τὴν πόλιν ἐν ἐλπίδι τοῦ περὶ αὐτὴν νῦν ὄντος ὄγκου καὶ μεγέθους διὰ Λύσανδρον γενέσθαι.", "st": "Lys. 3.1"}, {"sp": "N", "t": "πυθόμενος δὲ Κῦρον εἰς Σάρδεις ἀφῖχθαι τὸν βασιλέως υἱόν, ἀνέβη διαλεξόμενος αὐτῷ καὶ Τισαφέρνου κατηγορήσων, ὃς ἔχων πρόσταγμα Λακεδαιμονίοις βοηθεῖν καὶ τῆς θαλάσσης ἐξελάσαι τοὺς Ἀθηναίους, ἐδόκει δι’ Ἀλκιβιάδην ὑφιέμενος ἀπρόθυμος εἶναι καὶ γλίσχρως χορηγῶν τὸ ναυτικὸν φθείρειν. ἦν δὲ καὶ Κύρῳ βουλομένῳ τὸν Τισαφέρνην ἐν αἰτίαις εἶναι καὶ κακῶς ἀκούειν, πονηρὸν ὄντα καὶ πρὸς αὐτὸν ἰδίᾳ διαφερόμενον. ἔκ τε δὴ τούτων καὶ τῆς ἄλλης συνδιαιτήσεως ὁ Λύσανδρος ἀγαπηθεὶς καὶ τῷ θεραπευτικῷ μάλιστα τῆς ὁμιλίας ἑλὼν τὸ μειράκιον ἐπέρρωσε πρὸς τὸν πόλεμον. ἐπεὶ δὲ ἀπαλλάττεσθαι βουλόμενον αὐτὸν ἑστιῶν ὁ Κῦρος ἠξίου μὴ διωθεῖσθαι τὰς παρ’ αὐτοῦ φιλοφροσύνας, ἀλλ’ αἰτεῖν ὃ βούλοιτο καὶ φράζειν ὡς οὐδενὸς ἁπλῶς ἀποτευξόμενον, ὑπολαβὼν ὁ Λύσανδρος, ἐπεὶ τοίνυν, εἶπεν, οὕτως ἔχεις, ὦ Κῦρε, προθυμίας, αἰτοῦμαί σε καὶ παρακαλῶ προσθεῖναι τῷ μισθῷ τῶν ναυτῶν ὀβολόν, ὅπως τετρώβολον ἀντὶ τριωβόλου λαμβάνωσιν. ἡσθεὶς οὖν ὁ Κῦρος ἐπὶ τῇ φιλοτιμίᾳ τοῦ ἀνδρὸς μυρίους αὐτῷ δαρεικοὺς ἔδωκεν, ἐξ ὧν ἐπιμετρήσας τὸν ὀβολὸν τοῖς ναύταις καὶ λαμπρυνάμενος ὀλίγῳ χρόνῳ τὰς ναῦς τῶν πολεμίων κενὰς ἐποίησεν. ἀπεφοίτων γὰρ οἱ πολλοὶ πρὸς τοὺς πλέον διδόντας, οἱ δὲ μένοντες ἀπρόθυμοι καὶ στασιώδεις ἐγίνοντο καὶ κακὰ παρεῖχον ὁσημέραι τοῖς στρατηγοῖς. οὐ μὴν ἀλλὰ καίπερ οὕτως περισπάσας καὶ κακώσας τοὺς πολεμίους ὁ Λύσανδρος ὠρρώδει ναυμαχεῖν, δραστήριον ὄντα τὸν Ἀλκιβιάδην καὶ νεῶν πλήθει περιόντα καὶ μάχας καὶ κατὰ γῆν καὶ κατὰ θάλατταν εἰς ἐκεῖνο χρόνου πάσας ἀήττητον ἠγωνισμένον δεδοικώς.", "st": "Lys. 4.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁ μὲν Ἀλκιβιάδης εἰς Φωκαίαν ἐκ Σάμου διέπλευσεν ἐπὶ τοῦ στόλου καταλιπὼν Ἀντίοχον τὸν κυβερνήτην, ὁ δὲ Ἀντίοχος οἷον ἐφυβρίζων τῷ Λυσάνδρῳ καὶ θρασυνόμενος ἐπέπλευσε δυσὶ τριήρεσιν εἰς τὸν λιμένα τῶν Ἐφεσίων καὶ παρὰ τὸν ναύσταθμον γέλωτι καὶ πατάγῳ χρώμενος σοβαρῶς παρήλαυνεν, ἀγανακτήσας ὁ Λύσανδρος καὶ κατασπάσας τὸ πρῶτον οὐ πολλὰς τῶν τριήρων ἐδίωκεν αὐτόν, ἰδὼν δὲ αὖ τοὺς Ἀθηναίους βοηθοῦντας ἄλλας ἐπλήρου, καὶ τέλος ἐναυμάχουν συμπεσόντες. ἐνίκα δὲ Λύσανδρος, καὶ πεντεκαίδεκα τριήρεις λαβὼν ἔστησε τρόπαιον. ἐπὶ τούτῳ τὸν Ἀλκιβιάδην ὁ μὲν ἐν ἄστει δῆμος ὀργισθεὶς ἀπεχειροτόνησεν, ὑπὸ δὲ τῶν ἐν Σάμῳ στρατιωτῶν ἀτιμαζόμενος καὶ κακῶς ἀκούων ἀπέπλευσεν εἰς Χερρόνησον ἐκ τοῦ στρατοπέδου. ταύτην μὲν οὖν τὴν μάχην, καίπερ οὐ μεγάλην τῇ πράξει γενομένην, ἡ τύχη δι’ Ἀλκιβιάδην ὀνομαστὴν ἐποίησεν.", "st": "Lys. 5.1"}, {"sp": "N", "t": "ὁ δὲ Λύσανδρος ἀπὸ τῶν πόλεων εἰς Ἔφεσον μεταπεμπόμενος οὓς ἑώρα μάλιστα ταῖς τε τόλμαις καὶ τοῖς φρονήμασιν ὑπὲρ τοὺς πολλοὺς ὄντας, ἀρχὰς ὑπέσπειρε τῶν ὕστερον ἐπ’ αὐτοῦ γενομένων δεκαδαρχιῶν καὶ νεωτερισμῶν, προτρέπων καὶ παροξύνων ἑταιρικὰ συνίστασθαι καὶ προσέχειν τὸν νοῦν τοῖς πράγμασιν, ὡς ἅμα τῷ καταλυθῆναι τοὺς Ἀθηναίους τῶν τε δήμων ἀπαλλαξομένους καὶ δυναστεύσοντας ἐν ταῖς πατρίσι. τούτων δὲ τὴν πίστιν ἑκάστῳ δι’ ἔργων παρεῖχε, τοὺς ἤδη γεγονότας φίλους αὐτῷ καὶ ξένους εἰς μεγάλα πράγματα καὶ τιμὰς καὶ στρατηγίας ἀνάγων, καὶ συναδικῶν καὶ συνεξαμαρτάνων αὐτὸς ὑπὲρ τῆς ἐκείνων πλεονεξίας, ὥστε προσέχειν ἅπαντας αὐτῷ καὶ χαρίζεσθαι καὶ ποθεῖν, ἐλπίζοντας οὐδενὸς ἀτυχήσειν τῶν μεγίστων ἐκείνου κρατοῦντος. διὸ καὶ Καλλικρατίδαν οὔτ’ εὐθὺς ἡδέως εἶδον ἐλθόντα τῷ Λυσάνδρῳ διάδοχον τῆς ναυαρχίας, οὔτε, ὡς ὕστερον διδοὺς πεῖραν ἀνὴρ ἐφαίνετο πάντων ἄριστος καὶ δικαιότατος, ἠρέσκοντο τῷ τρόπῳ τῆς ἡγεμονίας ἁπλοῦν τι καὶ Δώριον ἐχούσης καὶ ἀληθινόν. ἀλλὰ τούτου μὲν τὴν ἀρετὴν ὥσπερ ἀγάλματος ἡρωϊκοῦ κάλλος ἐθαύμαζον, ἐπόθουν δὲ τὴν ἐκείνου σπουδὴν καὶ τὸ φιλέταιρον καὶ χρειῶδες ἐζήτουν, ὥστε ἀθυμεῖν ἐκπλέοντος αὐτοῦ καὶ δακρύειν.", "st": "Lys. 5.3"}, {"sp": "N", "t": "ὁ δὲ τούτους τε τῷ Καλλικρατίδᾳ δυσμενεστέρους ἐποίει ἔτι μᾶλλον, καὶ τῶν ὑπὸ Κύρου χρημάτων αὐτῷ δεδομένων εἰς τὸ ναυτικὸν τὰ περιόντα πάλιν εἰς Σάρδεις ἀνέπεμψεν, αὐτὸν αἰτεῖν, εἰ βούλοιτο, τὸν Καλλικρατίδαν καὶ σκοπεῖν ὅπως θρέψοι τοὺς στρατιώτας κελεύσας. τέλος δὲ ἀποπλέων ἐμαρτύρατο πρὸς αὐτὸν ὅτι θαλασσοκρατοῦν τὸ ναυτικὸν παραδίδωσιν. ὁ δὲ βουλόμενος ἐλέγξαι τὴν φιλοτιμίαν ἀλαζονικὴν καὶ κενὴν οὖσαν, οὐκοῦν, ἔφη, λαβὼν ἐν ἀριστερᾷ Σάμον καὶ περιπλεύσας εἰς Μίλητον ἐκεῖ μοι παράδος τὰς τριήρεις· δεδιέναι γὰρ οὐ χρὴ παραπλέοντας ἡμᾶς τοὺς ἐν Σάμῳ πολεμίους, εἰ θαλασσοκρατοῦμεν. πρὸς ταῦτα εἰπὼν ὁ Λύσανδρος ὅτι οὐκ αὐτός, ἀλλ’ ἐκεῖνος ἄρχοι τῶν νεῶν, ἀπέπλευσεν εἰς Πελοπόννησον, ἐν πολλῇ τὸν Καλλικρατίδαν ἀπορία καταλιπών. οὔτε γὰρ οἴκοθεν ἀφῖκτο χρήματα κομίζων, οὔτε τὰς πόλεις ἀργυρολογεῖν καὶ βιάζεσθαι μοχθηρὰ πραττούσας ὑπέμεινε. λοιπὸν οὖν ἦν ἐπὶ θύρας ἰόντα τῶν βασιλέως στρατηγῶν, ὥσπερ Λύσανδρος, αἰτεῖν· πρὸς ὃ πάντων ἀφυέστατος ἐτύγχανεν, ἀνὴρ ἐλευθέριος καὶ μεγαλόφρων, καὶ πᾶσαν ὑφ’ Ἑλλήνων ἧτταν Ἕλλησιν ἡγούμενος εὐπρεπεστέραν εἶναι τοῦ κολακεύειν καὶ φοιτᾶν ἐπὶ θύρας ἀνθρώπων βαρβάρων, πολὺ χρυσίον, ἄλλο δ’ οὐδὲν καλὸν ἐχόντων.", "st": "Lys. 6.1"}, {"sp": "N", "t": "ἐκβιαζόμενος δὲ ὑπὸ τῆς ἀπορίας, ἀναβὰς εἰς Λυδίαν εὐθὺς ἐπορεύετο εἰς τὴν οἰκίαν τοῦ Κύρου, καὶ φράζειν προσέταξεν ὅτι Καλλικρατίδας ὁ ναύαρχος ἥκει διαλεχθῆναι βουλόμενος αὐτῷ. τῶν δ’ ἐπὶ θύραις τινὸς εἰπόντος, ἀλλ’ οὐ σχολὴ νῦν, ὦ ξένε, Κύρῳ· πίνει γάρ, ἀφελέστατά πως ὁ Καλλικρατίδας, οὐδέν, ἔφη, δεινόν· αὐτοῦ γὰρ ἑστὼς ἀναμενῶ, μέχρι πίῃ. τότε μὲν οὖν δόξας ἀγροῖκός τις εἶναι καὶ καταγελασθεὶς ὑπὸ τῶν βαρβάρων ἀπῆλθεν· ἐπεὶ δὲ καὶ δεύτερον ἐλθὼν ἐπὶ θύρας οὐ παρείθη, βαρέως ἐνεγκὼν εἰς Ἔφεσον ᾤχετο, πολλὰ μὲν ἐπαρώμενος κακὰ τοῖς πρώτοις ἐντρυφηθεῖσιν ὑπὸ βαρβάρων καὶ διδάξασιν αὐτοὺς ὑβρίζειν διὰ πλοῦτον, ὀμνύων δὲ πρὸς τοὺς παρόντας ἦ μήν, ὅταν πρῶτον εἰς Σπάρτην παραγένηται, πάντα ποιήσειν ὑπὲρ τοῦ διαλυθῆναι τοὺς Ἕλληνας, ὡς φοβεροὶ τοῖς βαρβάροις εἶεν αὐτοὶ καὶ παύσαιντο τῆς ἐκείνων ἐπ’ ἀλλήλους δεόμενοι δυνάμεως.", "st": "Lys. 6.5"}, {"sp": "N", "t": "ἀλλὰ Καλλικρατίδας μὲν ἄξια τῆς Λακεδαίμονος διανοηθείς, καὶ γενόμενος τοῖς ἄκροις ἐνάμιλλος τῶν Ἑλλήνων διὰ δικαιοσύνην καὶ μεγαλοψυχίαν καὶ ἀνδρείαν, μετ’ οὐ πολὺν χρόνον ἐν Ἀργινούσαις καταναυμαχηθεὶς ἠφανίσθη. τῶν δὲ πραγμάτων ὑποφερομένων οἱ σύμμαχοι πρεσβείαν πέμποντες εἰς Σπάρτην ᾐτοῦντο Λύσανδρον ἐπὶ τὴν ναυαρχίαν, ὡς πολὺ προθυμότερον ἀντιληψόμενοι τῶν πραγμάτων ἐκείνου στρατηγοῦντος. τὰ δὲ αὐτὰ καὶ Κῦρος ἀξιῶν ἐπέστελλεν. ἐπεὶ δὲ νόμος ἦν οὐκ ἐῶν δὶς τὸν αὐτὸν ναυαρχεῖν, ἐβούλοντό τε χαρίζεσθαι τοῖς συμμάχοις οἱ Λακεδαιμόνιοι, τὸ μὲν ὄνομα τῆς ναυαρχίας Ἀράκῳ τινὶ περιέθεσαν, τὸν δὲ Λύσανδρον ἐπιστολέα τῷ λόγῳ, τῷ δ’ ἔργῳ κύριον ἁπάντων ἐξέπεμψαν. τοῖς μὲν οὖν πλείστοις τῶν πολιτευομένων καὶ δυναμένων ἐν ταῖς πόλεσι πάλαι ποθούμενος ἧκεν· ἤλπιζον γὰρ ἔτι μᾶλλον ἰσχύσειν δι’ αὐτοῦ παντάπασι τῶν δήμων καταλυθέντων· τοῖς δὲ τὸν ἁπλοῦν καὶ γενναῖον ἀγαπῶσι τῶν ἡγεμόνων τρόπον, ὁ Λύσανδρος τῷ Καλλικρατίδᾳ παραβαλλόμενος ἐδόκει πανοῦργος εἶναι καὶ σοφιστής, ἀπάταις τὰ πολλὰ διαποικίλλων τοῦ πολέμου καὶ τὸ δίκαιον ἐπὶ τῷ λυσιτελοῦντι μεγαλύνων, εἰ δὲ μή, τῷ συμφέροντι χρώμενος ὡς καλῷ, καὶ τὸ ἀληθὲς οὐ φύσει τοῦ ψεύδους κρεῖττον ἡγούμενος, ἀλλ’ ἑκατέρου τῇ χρείᾳ τὴν τιμὴν ὁρίζων. τῶν δ’ ἀξιούντων μὴ πολεμεῖν μετὰ δόλου τοὺς ἀφ’ Ἡρακλέους γεγονότας καταγελᾶν ἐκέλευεν· ὅπου γὰρ ἡ λεοντῆ μὴ ἐφικνεῖται, προσραπτέον ἐκεῖ τὴν ἀλωπεκῆν.", "st": "Lys. 7.1"}, {"sp": "N", "t": "τοιαῦτα δὲ αὐτοῦ καὶ τὰ περὶ Μίλητον ἱστόρηται. τῶν γὰρ φίλων καὶ ξένων, οἷς ὑπέσχετο συγκαταλύσειν τε τὸν δῆμον καὶ συνεκβαλεῖν τοὺς διαφόρους, μεταβαλομένων καὶ διαλλαγέντων τοῖς ἐχθροῖς, φανερῶς μὲν ἥδεσθαι προσεποιεῖτο καὶ συνδιαλλάττειν, κρύφα δὲ λοιδορῶν αὐτοὺς καὶ κακίζων παρώξυνεν ἐπιθέσθαι τοῖς πολλοῖς. ὡς δὲ ᾔσθετο γινομένην τὴν ἐπανάστασιν, ὀξέως βοηθήσας καὶ παρεισελθὼν εἰς τὴν πόλιν οἷς πρώτοις ἐπιτύχοι τῶν νεωτεριζόντων ἐχαλέπαινε τῇ φωνῇ καὶ προσῆγε τραχυνόμενος ὡς ἐπιθήσων δίκην αὐτοῖς, τοὺς δὲ ἄλλους ἐκέλευε θαρρεῖν καὶ μηδὲν ἔτι προσδοκᾶν δεινὸν αὐτοῦ παρόντος. ὑπεκρίνετο δὲ ταῦτα καὶ διεποίκιλλε, τοὺς δημοτικωτάτους καὶ κρατίστους βουλόμενος μὴ φεύγειν, ἀλλ’ ἀποθανεῖν ἐν τῇ πόλει μείναντας.", "st": "Lys. 8.1"}, {"sp": "N", "t": "ὃ καὶ, συνέβη· πάντες γὰρ ἀπεσφάγησαν οἱ καταπιστεύσαντες.ἀπομνημονεύεται δὲ ὑπὸ Ἀνδροκλείδου λόγος πολλήν τινα κατηγορῶν τοῦ Λυσάνδρου περὶ τοὺς ὅρκους εὐχέρειαν. ἐκέλευε γάρ, ὥς φησι, τοὺς μὲν παῖδας ἀστραγάλοις, τοὺς δὲ ἄνδρας ὅρκοις ἐξαπατᾶν, ἀπομιμούμενος Πολυκράτη τὸν Σάμιον, οὐκ ὀρθῶς τύραννον στρατηγός, οὐδὲ Λακωνικὸν τὸ χρῆσθαι τοῖς θεοῖς ὥσπερ τοῖς πολεμίοις, μᾶλλον δὲ ὑβριστικώτερον. ὁ γὰρ ὅρκῳ παρακρουόμενος τὸν μὲν ἐχθρὸν ὁμολογεῖ δεδιέναι, τοῦ δὲ θεοῦ καταφρονεῖν.", "st": "Lys. 8.4"}, {"sp": "N", "t": "ὁ δ’ οὖν Κῦρος εἰς Σάρδεις μεταπεμψάμενος τὸν Λύσανδρον, τὰ μὲν ἔδωκε, τὰ δὲ ὑπέσχετο, νεανιευσάμενος εἰς τὴν ἐκείνου χάριν καὶ εἰ μηδὲν ὁ πατὴρ διδῴη καταχορηγήσειν τὰ οἰκεῖα· κἂν ἐπιλίπῃ πάντα, κατακόψειν ἔφη τὸν θρόνον ἐφ’ ᾧ καθήμενος ἐχρημάτιζε, χρυσοῦν καὶ ἀργυροῦν ὄντα. τέγος δὲ εἰς Μηδίαν ἀναβαίνων πρὸς τὸν πατέρα, τούς τε φόρους ἀπέδειξε τῶν πόλεων λαμβάνειν ἐκεῖνον, καὶ τὴν αὑτοῦ διεπίστευσεν ἀρχήν·", "st": "Lys. 9.1"}, {"sp": "N", "t": "ἀσπασάμενος δὲ καὶ δεηθεὶς μὴ ναυμαχεῖν Ἀθηναίοις, πρὶν αὐτὸν ἀφικέσθαι πάλιν, ἀφίξεσθαι δὲ ναῦς ἔχοντα πολλὰς ἔκ τε Φοινίκης καὶ Κιλικίας, ἀνέβαινεν ὡς βασιλέα.Λύσανδρος δὲ μήτε ναυμαχεῖν ἀγχωμάλῳ πλήθει δυνάμενος μήτε ἀργὸς καθέζεσθαι μετὰ νεῶν τοσούτων, ἀναχθεὶς ἐνίας προσηγάγετο τῶν νήσων, Αἴγινάν τε καὶ Σαλαμῖνα προσμίξας κατέδραμεν. εἰς δὲ τὴν Ἀττικὴν ἀποβὰς καὶ τὸν Ἆγιν ἀσπασάμενος, κατέβη γὰρ αὐτὸς ἐκ Δεκελείας πρὸς αὐτόν, ἐπέδειξε τῷ πεζῷ παρόντι τὴν τοῦ ναυτικοῦ ῥώμην, ὡς πλέων ᾗ βούλοιτο, κρατῶν τῆς θαλάττης. οὐ μὴν ἀλλὰ τοὺς Ἀθηναίους αἰσθόμενος διώκοντας αὐτὸν ἄλλῳ δρόμῳ διὰ νήσων ἔφευγεν εἰς τὴν Ἀσίαν.", "st": "Lys. 9.3"}, {"sp": "N", "t": "καὶ τὸν Ἑλλήσποντον ἔρημον καταλαβὼν ἐπεχείρει Λαμψακηνοῖς αὐτὸς ἐκ θαλάττης ταῖς ναυσί, Θώραξ δὲ τῷ πεζῷ στρατῷ συνανύσας εἰς τὸ αὐτὸ προσέβαλε τοῖς τείχεσιν. ἑλὼν δὲ τὴν πόλιν κατὰ κράτος διαρπάσαι τοῖς στρατιώταις ἔδωκεν. ὁ δὲ τῶν Ἀθηναίων στόλος ὀγδοήκοντα καὶ ἑκατὸν τριήρων ἐτύγχανε μὲν ἄρτι καθωρμισμένος εἰς Ἐλαιοῦντα τῆς Χερρονήσου, πυνθανόμενοι δὲ ἀπολωλέναι τὴν Λάμψακον εὐθὺς εἰς Σηστὸν καταίρουσι. κἀκεῖθεν ἐπισιτισάμενοι παρέπλευσαν εἰς Αἰγὸς ποταμούς, ἀντιπέρας τῶν πολεμίων ἔτι ναυλοχούντων περὶ τὴν Λάμψακον. ἐστρατήγουν δὲ τῶν Ἀθηναίων ἄλλοι τε πλείους καὶ Φιλοκλῆς ὁ πείσας ποτὲ ψηφίσασθαι τὸν δῆμον ἀποκόπτειν τὸν δεξιὸν ἀντίχειρα τῶν ἁλισκομένων κατὰ πόλεμον, ὅπως δόρυ μὲν φέρειν μὴ δύνωνται, κώπην δὲ ἐλαύνωσι.", "st": "Lys. 9.4"}, {"sp": "N", "t": "τότε μὲν οὖν ἀνεπαύοντο πάντες, ἐλπίζοντες εἰς τὴν ὑστεραίαν ναυμαχήσειν. ὁ δὲ Λύσανδρος ἄλλα μὲν διενοεῖτο, προσέταττε δὲ ναύταις καὶ κυβερνήταις, ὡς ἀγῶνος ἅμα ἡμέρᾳ γενησομένου, περὶ ὄρθρον ἐμβαίνειν εἰς τὰς τριήρεις καὶ καθέζεσθαι κόσμῳ καὶ σιωπῇ, δεχομένους τὸ παραγγελλόμενον, ὡς δ’ αὕτως καὶ τὸ πεζὸν ἐν τάξει παρὰ τὴν θάλατταν ἡσυχάζειν. ἀνίσχοντος δὲ τοῦ ἡλίου καὶ τῶν Ἀθηναίων μετωπηδὸν ἁπάσαις ἐπιπλεόντων καὶ προκαλουμένων, ἀντιπρῴρους ἔχων τὰς ναῦς καὶ πεπληρωμένας ἔτι νυκτὸς οὐκ ἀνήγετο, πέμπων δὲ ὑπηρετικὰ παρὰ τὰς πρώτας τῶν νεῶν ἀτρεμεῖν ἐκέλευε καὶ μένειν ἐν τάξει μὴ θορυβουμένους μηδ’ ἀντεκπλέοντας. οὕτω δὲ περὶ δείλην ἀποπλεόντων ὀπίσω τῶν Ἀθηναίων οὐ πρότερον ἐκ τῶν νεῶν τοὺς στρατιώτας ἀφῆκεν, εἰ μὴ δύο καὶ τρεῖς τριήρεις, ἃς ἔπεμψε κατασκόπους, ἐλθεῖν ἰδόντας ἀποβεβηκότας τοὺς πολεμίους. τῇ δ’ ὑστεραίᾳ πάλιν ἐγίνοντο ταῦτα καὶ τῇ τρίτῃ μέχρι τετάρτης, ὥστε πολὺ τοῖς Ἀθηναίοις θράσος ἐγγενέσθαι καὶ καταφρόνησιν ὡς δεδιότων καὶ συνεσταλμένων τῶν πολεμίων.", "st": "Lys. 10.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Ἀλκιβιάδης (ἐτύγχανε γὰρ περὶ Χερρόνησον ἐν τοῖς ἑαυτοῦ τείχεσι διαιτώμενος) ἵππῳ προσελάσας πρὸς τὸ στράτευμα τῶν Ἀθηναίων ᾐτιᾶτο τοὺς στρατηγοὺς πρῶτον μὲν οὐ καλῶς οὐδ’ ἀσφαλῶς στρατοπεδεύειν ἐν αἰγιαλοῖς δυσόρμοις καὶ ἀναπεπταμένοις· ἔπειτα πόρρωθεν ἐκ Σηστοῦ τὰ ἐπιτήδεια λαμβάνοντας ἁμαρτάνειν, δέον εἰς λιμένα καὶ πόλιν Σηστὸν δι’ ὀλίγου περιπλεύσαντας, ἀπωτέρω γενέσθαι τῶν πολεμίων ἐφορμούντων στρατεύματι μοναρχουμένῳ καὶ πάντα πρὸς φόβον ὀξέως ἀπὸ συνθήματος ὑπηρετοῦντι. ταῦτα δὲ αὐτοῦ διδάσκοντος οὐκ ἐπείθοντο, Τυδεὺς δὲ καὶ πρὸς ὕβριν ἀπεκρίνατο, φήσας οὐκ ἐκεῖνον, ἀλλ’ ἑτέρους στρατηγεῖν.", "st": "Lys. 10.4"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἀλκιβιάδης ὑποπτεύσας τι καὶ προδοσίας ἐν αὐτοῖς ἀπηλλάττετο. πέμπτῃ δὲ ἡμέρᾳ τῶν Ἀθηναίων ποιησαμένων τὸν ἐπίπλουν καὶ πάλιν ἀπερχομένων, ὥσπερ εἰώθεσαν, ὀλιγώρως πάνυ καὶ καταφρονητικῶς, ὁ Λύσανδρος ἐκπέμπων τὰς κατασκόπους ναῦς ἐκέλευσε τοὺς τριηράρχους, ὅταν ἴδωσι τοὺς Ἀθηναίους ἐκβεβηκότας, ἐλαύνειν ἀποστρέψαντας ὀπίσω τάχει παντί, καὶ γενομένους κατὰ μέσον τὸν πόρον ἀσπίδα χαλκῆν ἐπάρασθαι πρῴραθεν ἐπίπλου σύμβολον. αὐτὸς δὲ τοὺς κυβερνήτας καὶ τριηράρχους ἐπιπλέων ἀνεκαλεῖτο καὶ παρώρμα συνέχειν ἕκαστον ἐν τάξει τὸ πλήρωμα καὶ τοὺς ναύτας καὶ τοὺς ἐπιβάτας, ὅταν δὲ σημανθῇ, μετὰ προθυμίας καὶ ῥώμης ἐλαύνειν ἐπὶ τοὺς πολεμίους. ὡς δὲ ἥ τε ἀσπὶς ἀπὸ τῶν νεῶν ἤρθη καὶ τῇ σάλπιγγι τὴν ἀναγωγὴν ἐσήμαινεν ἀπὸ τῆς ναυαρχίδος, ἐπέπλεον μὲν αἱ νῆες, ἡμιλλῶντο δὲ οἱ πεζοὶ παρὰ τὸν αἰγιαλὸν ἐπὶ τὴν ἄκραν. τὸ δὲ μεταξὺ τῶν ἠπείρων διάστημα ταύτῃ πεντεκαίδεκα σταδίων ἐστί, καὶ ταχέως ὑπὸ σπουδῆς καὶ προθυμίας τῶν ἐλαυνόντων συνῄρητο.", "st": "Lys. 11.1"}, {"sp": "N", "t": "Κόνων δὲ πρῶτος ὁ τῶν Ἀθηναίων στρατηγὸς ἀπὸ τῆς γῆς ἰδὼν ἐπιπλέοντα τὸν στόλον ἐξαίφνης ἀνεβόησεν ἐμβαίνειν, καὶ περιπαθῶν τῷ κακῷ τοὺς μὲν ἐκάλει, τῶν δὲ ἐδεῖτο, τοὺς δὲ ἠνάγκαζε πληροῦν τὰς τριήρεις. ἦν δὲ οὐδὲν ἔργον αὐτοῦ τῆς σπουδῆς ἐσκεδασμένων τῶν ἀνθρώπων. ὡς γὰρ ἐξέβησαν, εὐθύς, ἅτε μηδὲν προσδοκῶντες, ἠγόραζον, ἐπλανῶντο περὶ τὴν χώραν, ἐκάθευδον ὑπὸ ταῖς σκηναῖς, ἠριστοποιοῦντο, πορρωτάτω τοῦ μέλλοντος ἀπειρίᾳ τῶν ἡγουμένων ὄντες. ἤδη δὲ κραυγῇ καὶ ῥοθίῳ προσφερομένων τῶν πολεμίων ὁ μὲν Κόνων ὀκτὼ ναυσὶν ὑπεξέπλευσε καὶ διαφυγὼν ἀπεπέρασεν εἰς Κύπρον πρὸς Εὐαγόραν, ταῖς δὲ ἄλλαις ἐπιπεσόντες οἱ Πελοποννήσιοι τὰς μὲν κενὰς παντάπασιν ᾕρουν, τὰς δ’ ἔτι πληρουμένας ἔκοπτον.", "st": "Lys. 11.4"}, {"sp": "N", "t": "οἱ δὲ ἄνθρωποι πρός τε ταῖς ναυσὶν ἀπέθνησκον ἄνοπλοι καὶ σποράδες ἐπιβοηθοῦντες, ἔν τε τῇ γῇ φεύγοντες ἀποβάντων τῶν πολεμίων ἐκτείνοντο. λαμβάνει δὲ ὁ Λύσανδρος τρισχιλίους ἄνδρας αἰχμαλώτους μετὰ τῶν στρατηγῶν, ἅπαν δὲ τὸ ναύσταθμον ἄνευ τῆς Παράλου καὶ τῶν μετὰ Κόνωνος ἐκφυγουσῶν. ἀναδησάμενος δὲ τὰς ναῦς καὶ διαπορθήσας τὸ στρατόπεδον μετὰ αὐλοῦ καὶ παιάνων ἀνέπλευσεν εἰς Λάμψακον, ἔργον ἐλαχίστῳ πόνῳ μέγιστον ἐξειργασμένος, καὶ συνῃρηκὼς ὥρᾳ μιᾷ χρόνου μήκιστον καὶ ποικιλώτατον πάθεσί τε καὶ τύχαις ἀπιστότατον τῶν πρὸ αὐτοῦ πολέμων, ὃς μυρίας μορφὰς ἀγώνων καὶ πραγμάτων μεταβολὰς ἀμείψας, καὶ στρατηγοὺς ὅσους οὐδὲ οἱ σύμπαντες οἱ πρὸ αὐτοῦ τῆς Ἑλλάδος ἀναλώσας, ἑνὸς ἀνδρὸς εὐβουλία καὶ δεινότητι συνῄρητο· διὸ καὶ θεῖόν τινες ἡγήσαντο τοῦτο τὸ ἔργον.", "st": "Lys. 11.6"}, {"sp": "N", "t": "ἦσαν δέ τινες οἱ τοὺς Διοσκούρους ἐπὶ τῆς Λυσάνδρου νεὼς ἑκατέρωθεν, ὅτε τοῦ λιμένος ἐξέπλει πρῶτον ἐπὶ τοὺς πολεμίους, ἄστρα τοῖς οἴαξιν ἐπιλάμψαι λέγοντες. οἱ δὲ καὶ τὴν τοῦ λίθου πτῶσιν ἐπὶ τῷ πάθει τούτῳ σημεῖόν φασι γενέσθαι· κατηνέχθη γάρ, ὡς ἡ δόξα τῶν πολλῶν, ἐξ οὐρανοῦ παμμεγέθης λίθος εἰς Αἰγὸς ποταμούς. καὶ δείκνυται μὲν ἔτι νῦν, σεβομένων αὐτὸν τῶν Χερρονησιτῶν· λέγεται δὲ Ἀναξαγόραν προειπεῖν ὡς τῶν κατὰ τὸν οὐρανὸν ἐνδεδεμένων σωμάτων, γενομένου τινὸς ὀλισθήματος ἢ σάλου, ῥῖψις ἔσται καὶ πτῶσις ἑνὸς ἀπορραγέντος· εἶναι δὲ καὶ τῶν ἄστρων ἕκαστον οὐκ ἐν ᾗ πέφυκε χώρᾳ· λιθώδη γὰρ ὄντα καὶ βαρέα λάμπειν μὲν ἀντερείσει καὶ περικλάσει τοῦ αἰθέρος, ἕλκεσθαι δὲ ὑπὸ βίας σφιγγόμενα δίνῃ καὶ τόνῳ τῆς περιφορᾶς, ὥς που καὶ τὸ πρῶτον ἐκρατήθη μὴ πεσεῖν δεῦρο, τῶν ψυχρῶν καὶ βαρέων ἀποκρινομένων τοῦ παντός.", "st": "Lys. 12.1"}, {"sp": "N", "t": "ἔστι δέ τις πιθανωτέρα δόξα ταύτης, εἰρηκότων ἐνίων ὡς οἱ διᾴττοντες ἀστέρες οὐ ῥύσις εἰσὶν οὐδ’ ἐπινέμησις αἰθερίου πυρὸς ἐν ἀέρι κατασβεννυμένου περὶ τὴν ἔξαψιν αὐτήν, οὐδὲ ἀέρος εἰς τὴν ἄνω χώραν πλήθει λυθέντος ἔκπρησις καὶ ἀνάφλεξις, ῥῖψις δὲ καὶ πτῶσις οὐρανίων σωμάτων οἷον ἐνδόσει τινὶ τόνου καὶ περιτρόπου κινήσεως ἐκπαλῶν φερομένων οὐ πρὸς τὸν οἰκούμενον τόπον τῆς γῆς, ἀλλὰ τῶν πλείστων ἐκτὸς εἰς τὴν μεγάλην ἐκπιπτόντων θάλατταν· διὸ καὶ λανθάνουσι.", "st": "Lys. 12.3"}, {"sp": "N", "t": "τῷ δ’ Ἀναξαγόρᾳ μαρτυρεῖ καὶ Δαΐμαχος ἐν τοῖς Περὶ εὐσεβείας, ἱστορῶν ὅτι πρὸ τοῦ πεσεῖν τὸν λίθον ἐφ’ ἡμέρας ἑβδομήκοντα καὶ πέντε συνεχῶς κατὰ τὸν οὐρανὸν ἑωρᾶτο πύρινον σῶμα παμμέγεθες, ὥσπερ νέφος φλογοειδές, οὐ σχολάζον, ἀλλὰ πολυπλόκους καὶ κεκλασμένας φορὰς φερόμενον, ὥστε ὑπὸ σάλου καὶ πλάνης ἀπορρηγνύμενα πυροειδῆ σπάσματα φέρεσθαι πολλαχοῦ καὶ ἀστράπτειν, ὥσπερ οἱ διᾴττοντες ἀστέρες. ἐπεὶ δὲ ἐνταῦθα τῆς γῆς ἔβρισε καὶ παυσάμενοι φόβου καὶ θάμβους οἱ ἐπιχώριοι συνῆλθον, ὤφθη πυρὸς μὲν οὐδὲν ἔργον οὐδ’ ἴχνος τοσοῦτο, λίθος δὲ κείμενος, ἄλλως μὲν μέγας, οὐθὲν δὲ μέρος, ὡς εἰπεῖν, ἐκείνης τῆς πυροειδοῦς περιοχῆς ἔχων. ὅτι μὲν οὖν εὐγνωμόνων ὁ Δαΐμαχος ἀκροατῶν δεῖται δῆλός ἐστιν· εἰ δὲ ἀληθὴς ὁ λόγος, ἐξελέγχει κατὰ κράτος τοὺς φάσκοντας ἔκ τινος, ἀκρωρείας ἀποκοπεῖσαν πνεύμασι καὶ ζάλαις πέτραν, ὑποληφθεῖσαν δ’ ὥσπερ οἱ στρόβιλοι, καὶ φερομένην, ᾗ πρῶτον ἐνέδωκε καὶ διελύθη τὸ περιδινῆσαν, ἐκριφῆναι καὶ πεσεῖν. εἰ μὴ νὴ Δία πῦρ μὲν ἦν ὄντως τὸ φαινόμενον ἐπὶ πολλὰς ἡμέρας, σβέσις δὲ καὶ φθορὰ μεταβολὴν ἀέρι παρέσχεν εἰς πνεύματα βιαιότερα καὶ κινήσεις, ὑφ’ ὧν συνέτυχε καὶ τὸν λίθον ἐκριφῆναι. ταῦτα μὲν οὖν ἑτέρῳ γένει γραφῆς διακριβωτέον.", "st": "Lys. 12.4"}, {"sp": "N", "t": "ὁ δὲ Λύσανδρος, ἐπεὶ τῶν τρισχιλίων Ἀθηναίων, οὓς ἔλαβεν αἰχμαλώτους, ὑπὸ τῶν συνέδρων θάνατος κατέγνωστο, καλέσας Φιλοκλέα τὸν στρατηγὸν αὐτῶν ἠρώτησεν τίνα τιμᾶται δίκην ἑαυτῷ τοιαῦτα περὶ Ἑλλήνων συμβεβουλευκὼς τοῖς πολίταις. ὁ δὲ οὐδέν τι πρὸς τὴν συμφορὰν ἐνδοὺς ἐκέλευσε μὴ κατηγορεῖν ὧν οὐδείς ἐστι δικαστής, ἀλλὰ νικῶντα πράττειν ἅπερ ἂν νικηθεὶς ἔπασχεν· εἶτα λουσάμενος καὶ λαβὼν χλανίδα λαμπρὰν πρῶτος ἐπὶ τὴν σφαγὴν ἡγεῖτο τοῖς πολίταις, ὡς ἱστορεῖ Θεόφραστος. ἐκ δὲ τούτου πλέων ὁ Λύσανδρος ἐπὶ τὰς πόλεις Ἀθηναίων μὲν οἷς ἐπιτύχοι ἐκέλευε πάντας εἰς Ἀθήνας ἀπιέναι· φείσεσθαι γὰρ οὐδενός, ἀλλ’ ἀποσφάξειν ὃν ἂν ἔξω λάβῃ τῆς πόλεως. ταῦτα δ’ ἔπραττε καὶ συνήλαυνεν ἅπαντας εἰς τὸ ἄστυ βουλόμενος ἐν τῇ πόλει ταχὺ λιμὸν ἰσχυρὸν γενέσθαι καὶ σπάνιν, ὅπως μὴ πράγματα παράσχοιεν αὐτῷ τὴν πολιορκίαν εὐπόρως ὑπομένοντες. καταλύων δὲ τοὺς δήμους καὶ τὰς ἄλλας πολιτείας, ἕνα μὲν ἁρμοστὴν ἑκάστῃ Λακεδαιμόνιον κατέλιπε, δέκα δὲ ἄρχοντας ἐκ τῶν ὑπ’ αὐτοῦ συγκεκροτημένων κατὰ πόλιν ἑταιρειῶν. καὶ ταῦτα πράττων ὁμοίως ἔν τε ταῖς πολεμίαις καὶ ταῖς συμμάχοις γεγενημέναις πόλεσι, παρέπλει σχολαίως, τρόπον τινὰ κατασκευαζόμενος ἑαυτῷ τὴν τῆς Ἑλλάδος ἡγεμονίαν. οὔτε γὰρ ἀριστίνδην οὔτε πλουτίνδην ἀπεδείκνυε τοὺς ἄρχοντας, ἀλλ’ ἑταιρείαις καὶ ξενίαις χαριζόμενος τὰ πράγματα καὶ κυρίους ποιῶν τιμῆς τε καὶ κολάσεως, πολλαῖς δὲ παραγινόμενος αὐτὸς σφαγαῖς καὶ συνεκβάλλων τοὺς τῶν φίλων ἐχθρούς, οὐκ ἐπιεικὲς ἐδίδου τοῖς Ἕλλησι δεῖγμα τῆς Λακεδαιμονίων ἀρχῆς, ἀλλὰ καὶ ὁ κωμικὸς Θεόπομπος ἔοικε ληρεῖν ἀπεικάζων τοὺς Λακεδαιμονίους ταῖς καπηλίσιν, ὅτι τοὺς Ἕλληνας ἥδιστον ποτὸν τῆς ἐλευθερίας γεύσαντες ὄξος ἐνέχεαν· εὐθὺς γὰρ ἦν τὸ γεῦμα δυσχερὲς καὶ πικρόν, οὔτε τοὺς δήμους κυρίους τῶν πραγμάτων ἐῶντος εἶναι τοῦ Λυσάνδρου, καὶ τῶν ὀλίγων τοῖς θρασυτάτοις καὶ φιλονεικοτάτοις τὰς πόλεις ἐγχειρίζοντος.", "st": "Lys. 13.1"}, {"sp": "N", "t": "διατρίψας δὲ περὶ ταῦτα χρόνον οὐ πολύν, καὶ προπέμψας εἰς Λακεδαίμονα τοὺς ἀπαγγελοῦντας ὅτι προσπλεῖ μετὰ νεῶν διακοσίων, συνέμιξε περὶ Ἀττικὴν Ἄγιδι καὶ Παυσανίᾳ τοῖς βασιλεῦσιν ὡς ταχὺ συναιρήσων τὴν πόλιν. ἐπεὶ δὲ ἀντεῖχον οἱ Ἀθηναῖοι, λαβὼν τὰς ναῦς πάλιν εἰς Ἀσίαν διεπέρασε· καὶ τῶν μὲν ἄλλων πόλεων ὁμαλῶς ἁπασῶν κατέλυε τὰς πολιτείας καὶ καθίστη δεκαδαρχίας, πολλῶν μὲν ἐν ἑκάστῃ σφαττομένων, πολλῶν δὲ φευγόντων, Σαμίους δὲ πάντας ἐκβαλὼν παρέδωκε τοῖς φυγάσι τὰς πόλεις. Σηστὸν δ’ Ἀθηναίων ἐχόντων ἀφελόμενος οὐκ εἴασεν οἰκεῖν Σηστίους, ἀλλὰ τοῖς γενομένοις ὑπ’ αὐτῷ κυβερνήταις καὶ κελευσταῖς ἔδωκε τὴν πόλιν καὶ τὴν χώραν νέμεσθαι. πρὸς ὃ καὶ πρῶτον ἀντέκρουσαν οἱ Λακεδαιμόνιοι καὶ τοὺς Σηστίους αὖθις ἐπὶ τὴν χώραν κατήγαγον. ἀλλ’ ἐκεῖνά γε τοῦ Λυσάνδρου πάντες ἡδέως ἑώρων οἱ Ἕλληνες, Αἰγινήτας τε διὰ πολλοῦ χρόνου τὴν αὑτῶν πόλιν ἀπολαμβάνοντας καὶ Μηλίους καὶ Σκιωναίους ὑπ’ αὐτοῦ συνοικιζομένους, ἐξελαυνομένων Ἀθηναίων καὶ τὰς πόλεις ἀποδιδόντων.ἤδη δὲ καὶ τοὺς ἐν ἄστει κακῶς ἔχειν ὑπὸ λιμοῦ πυνθανόμενος κατέπλευσεν εἰς τὸν Πειραιᾶ καὶ παρεστήσατο τὴν πόλιν, ἀναγκασθεῖσαν ἐφ’ οἷς ἐκεῖνος ἐκέλευε ποιήσασθαι τὰς διαλύσεις.", "st": "Lys. 14.1"}, {"sp": "N", "t": "καίτοι Λακεδαιμονίων ἐστὶν ἀκοῦσαι λεγόντων ὡς Λύσανδρος μὲν ἔγραψε τοῖς ἐφόροις τάδε· ἁλώκαντι ταὶ Ἀθᾶναι, Λυσάνδρῳ δ’ ἀντέγραψαν οἱ ἔφοροι· ἀρκεῖ τό γε ἑαλώκειν. ἀλλ’ εὐπρεπείας χάριν οὗτος ὁ λόγος πέπλασται. τὸ δ’ ἀληθινὸν δόγμα τῶν ἐφόρων οὕτως εἶχε· τάδε τὰ τέλη τῶν Λακεδαιμονίων ἔγνω· καββαλόντες τὸν Πειραιᾶ καὶ τὰ μακρὰ σκέλη, καὶ ἐκβάντες ἐκ πασῶν τῶν πόλεων τὰν αὑτῶν γᾶν ἔχοντες, ταῦτά κα δρῶντες τὰν εἰράναν ἔχοιτε, αἰ χρήδοιτε, καὶ τοὺς φυγάδας ἀνέντες. περὶ τᾶν ναῶν τῶ πλήθεος, ὁκοῖόν τί κα τηνεὶ δοκέῃ, ταῦτα ποιέετε. ταύτην δὲ προσεδέξαντο τὴν σκυτάλην οἱ Ἀθηναῖοι Θηραμένους τοῦ Ἅγνωνος συμβουλεύσαντος· ὅτε καί φασιν ὑπὸ τῶν νέων τινὸς δημαγωγῶν Κλεομένους ἐρωτώμενον εἰ τολμᾷ τἀναντία Θεμιστοκλεῖ πράττειν καὶ λέγειν, παραδιδοὺς τὰ τείχη τοῖς Λακεδαιμονίοις, ἃ Λακεδαιμονίων ἀκόντων ἐκεῖνος ἀνέστησεν, εἰπεῖν· ἀλλ’ οὐδέν, ὦ μειράκιον, ὑπεναντίον ἐγὼ πράττω Θεμιστοκλεῖ· τὰ γὰρ αὐτὰ τείχη κἀκεῖνος ἐπὶ σωτηρίᾳ τῶν πολιτῶν ἀνέστησε καὶ ἡμεῖς ἐπὶ σωτηρίᾳ καταβαλοῦμεν. εἰ δὲ τὰ τείχη τὰς πόλεις εὐδαίμονας ἐποίει, πασῶν ἔδει πράττειν κάκιστα τὴν Σπάρτην ἀτείχιστον οὖσαν.", "st": "Lys. 14.4"}, {"sp": "N", "t": "ὁ δ’ οὖν Λύσανδρος, ὡς παρέλαβε τάς τε ναῦς ἁπάσας πλὴν δώδεκα καὶ τὰ τείχη τῶν Ἀθηναίων, ἕκτῃ ἐπὶ δεκάτῃ Μουνυχιῶνος μηνός, ἐν ᾗ καὶ τὴν ἐν Σαλαμῖνι ναυμαχίαν ἐνίκων τὸν βάρβαρον, ἐβούλευσεν εὐθὺς καὶ τὴν πολιτείαν μεταστῆσαι. δυσπειθῶς δὲ καὶ τραχέως φερόντων, ἀποστείλας πρὸς τὸν δῆμον ἔφη τὴν πόλιν εἰληφέναι παρασπονδοῦσαν· ἑστάναι γὰρ τὰ τείχη τῶν ἡμερῶν ἐν αἷς ἔδει καθῃρῆσθαι παρῳχημένων. ἑτέραν οὖν ἐξ ἀρχῆς προθήσειν γνώμην περὶ αὐτῶν ὡς τὰς ὁμολογίας λελυκότων. ἔνιοι δὲ καὶ προτεθῆναί φασιν ὡς ἀληθῶς ὑπὲρ ἀνδραποδισμοῦ γνώμην ἐν τοῖς συμμάχοις, ὅτε καὶ τὸν Θηβαῖον Ἐρίανθον εἰσηγήσασθαι τὸ μὲν ἄστυ κατασκάψαι, τὴν δὲ χώραν ἀνεῖναι μηλόβοτον. εἶτα μέντοι συνουσίας γενομένης τῶν ἡγεμόνων παρὰ πότον, καί τινος Φωκέως ᾄσαντος ἐκ τῆς Εὐριπίδου Ἠλέκτρας τὴν πάροδον ἧς ἡ ἀρχή", "st": "Lys. 15.1"}, {"sp": "N", "t": "Ἀγαμέμνονος ὦ κόρα,<br>ἤλυθον, Ἠλέκτρα, ποτὶ σὰν ἀγρότειραν αὐλάν,", "st": "Lys. 15.1b"}, {"sp": "N", "t": "πάντας ἐπικλασθῆναι, καὶ φανῆναι σχέτλιον ἔργον τὴν οὕτως εὐκλεᾶ καὶ τοιούτους ἄνδρας φέρουσαν ἀνελεῖν καὶ διεργάσασθαι πόλιν.", "st": "Lys. 15.1c"}, {"sp": "N", "t": "ὁ δ’ οὖν Λύσανδρος ἐνδόντων τῶν Ἀθηναίων πρὸς ἅπαντα, πολλὰς μὲν ἐξ ἄστεος μεταπεμψάμενος αὐλητρίδας, πάσας δὲ τὰς ἐν τῷ στρατοπέδῳ συναγαγών, τὰ τείχη κατέσκαπτε καὶ τὰς τριήρεις κατέφλεγε πρὸς τὸν αὐλόν, ἐστεφανωμένων καὶ παιζόντων ἅμα τῶν συμμάχων, ὡς ἐκείνην τὴν ἡμέραν ἄρχουσαν τῆς ἐλευθερίας. εὐθὺς δὲ καὶ τὰ περὶ τὴν πολιτείαν ἐκίνησε, τριάκοντα μὲν ἐν ἄστει, δέκα δὲ ἐν Πειραιεῖ καταστήσας ἄρχοντας, ἐμβαλὼν δὲ φρουρὰν εἰς τὴν ἀκρόπολιν, καὶ Καλλίβιον ἁρμοστήν, ἄνδρα Σπαρτιάτην, ἐπιστήσας. ἐπεὶ δὲ οὗτος Αὐτόλυκον τὸν ἀθλητήν, ἐφ’ ᾧ τὸ συμπόσιον ὁ Ξενοφῶν πεποίηκε, τὴν βακτηρίαν διαράμενος παίσειν ἔμελλεν, ὁ δὲ τῶν σκελῶν συναράμενος ἀνέτρεψεν αὐτόν, οὐ συνηγανάκτησεν ὁ Λύσανδρος, ἀλλὰ καὶ συνεπετίμησε, φήσας αὐτὸν οὐκ ἐπίστασθαι ἐλευθέρων ἄρχειν. ἀλλὰ τὸν μὲν Αὐτόλυκον οἱ τριάκοντα τῷ Καλλιβίῳ χαριζόμενοι μικρὸν ὕστερον ἀνεῖλον.", "st": "Lys. 15.4"}, {"sp": "N", "t": "ὁ δὲ Λύσανδρος ἀπὸ τούτων γενόμενος, αὐτὸς μὲν ἐπὶ Θρᾴκης ἐξέπλευσε, τῶν δὲ χρημάτων τὰ περιόντα καὶ ὅσας δωρεὰς αὐτὸς ἢ στεφάνους ἐδέξατο, πολλῶν, ὡς εἰκός, διδόντων ἀνδρὶ δυνατωτάτῳ καὶ τρόπον τινὰ κυρίῳ τῆς Ἑλλάδος, ἀπέστειλεν εἰς Λακεδαίμονα διὰ Γυλίππου τοῦ στρατηγήσαντος περὶ Σικελίαν. ὁ δέ, ὡς λέγεται, τὰς ῥαφὰς τῶν ἀγγείων κάτωθεν ἀναλύσας καὶ ἀφελὼν συχνὸν ἀργύριον ἐξ ἑκάστου πάλιν συνέρραψεν, ἀγνοήσας ὅτι γραμματίδιον ἐνῆν ἑκάστῳ τὸν ἀριθμὸν σημαῖνον. ἐλθὼν δὲ εἰς Σπάρτην ἃ μὲν ὑφῄρητο κατέκρυψεν ὑπὸ τὸν κέραμον τῆς οἰκίας, τὰ δὲ ἀγγεῖα παρέδωκε τοῖς ἐφόροις καὶ τὰς σφραγῖδας ἐπέδειξεν. ἐπεὶ δὲ ἀνοιξάντων καὶ ἀριθμούντων διεφώνει πρὸς τὰ γράμματα τὸ πλῆθος τοῦ ἀργυρίου καὶ παρεῖχε τοῖς ἐφόροις ἀπορίαν τὸ πρᾶγμα, φράζει θεράπων τοῦ Γυλίππου πρὸς αὐτοὺς αἰνιξάμενος ὑπὸ τῷ κεραμικῷ κοιτάζεσθαι πολλὰς γλαῦκας. ἦν γάρ, ὡς ἔοικε, τὸ χάραγμα τοῦ πλείστου τότε νομίσματος διὰ τοὺς Ἀθηναίους γλαῦκες.", "st": "Lys. 16.1"}, {"sp": "N", "t": "ὁ μὲν οὖν Γύλιππος αἰσχρὸν οὕτω καὶ ἀγεννὲς ἔργον ἐπὶ λαμπροῖς τοῖς ἔμπροσθεν καὶ μεγάλοις ἐργασάμενος μετέστησεν ἑαυτὸν ἐκ Λακεδαίμονος. οἱ δὲ φρονιμώτατοι τῶν Σπαρτιατῶν οὐχ ἥκιστα καὶ διὰ τοῦτο τὴν τοῦ νομίσματος ἰσχὺν φοβηθέντες, ὡς οὐχὶ τῶν τυχόντων ἁπτομένην πολιτῶν, τόν τε Λύσανδρον ἐλοιδόρουν καὶ διεμαρτύραντο τοῖς ἐφόροις ἀποδιοπομπεῖσθαι πᾶν τὸ ἀργύριον καὶ τὸ χρυσίον ὥσπερ κῆρας ἐπαγωγίμους. οἱ δὲ προὔθεσαν γνώμην. καὶ Θεόπομπος μέν φησι Σκιραφίδαν, ἔφορος δὲ Φλογίδαν εἶναι τὸν ἀποφηνάμενον ὡς οὐ χρὴ προσδέχεσθαι νόμισμα χρυσοῦν καὶ ἀργυροῦν εἰς τὴν πόλιν, ἀλλὰ χρῆσθαι τῷ πατρίῳ. τοῦτο δὲ ἦν σιδηροῦν, πρῶτον μὲν ὄξει καταβαπτόμενον ἐκ πυρός, ὅπως μὴ καταχαλκεύοιτο, ἀλλὰ διὰ τὴν βαφὴν ἄστομον καὶ ἀδρανὲς γίνοιτο, ἔπειτα βαρύσταθμον καὶ δυσπαρακόμιστον καὶ ἀπὸ πολλοῦ τινος πλήθους καὶ ὄγκου μικράν τινα ἀξίαν δυνάμενον. κινδυνεύει δὲ καὶ τὸ πάμπαν ἀρχαῖον οὕτως ἔχειν, ὀβελίσκοις χρωμένων νομίσμασι σιδηροῖς, ἐνίων δὲ χαλκοῖς· ἀφ’ ὧν παραμένει πλῆθος ἔτι καὶ νῦν τῶν κερμάτων ὀβολοὺς καλεῖσθαι, δραχμὴν δὲ τοὺς ἓξ ὀβολούς· τοσούτων γὰρ ἡ χεὶρ περιεδράττετο.", "st": "Lys. 17.1"}, {"sp": "N", "t": "τῶν δὲ Λυσάνδρου φίλων ὑπεναντιουμένων καὶ σπουδασάντων ἐν τῇ πόλει καταμεῖναι τὰ χρήματα, δημοσίᾳ μὲν ἔδοξεν εἰσάγεσθαι νόμισμα τοιοῦτον, ἂν δέ τις ἁλῷ κεκτημένος ἰδίᾳ, ζημίαν ὥρισαν θάνατον, ὥσπερ τοῦ Λυκούργου τὸ νόμισμα φοβηθέντος, οὐ τὴν ἐπὶ τῷ νομίσματι φιλαργυρίαν, ἣν οὐκ ἀφῄρει τὸ μὴ κεκτῆσθαι τὸν ἰδιώτην, ὡς τὸ κεκτῆσθαι τὴν πόλιν εἰσεποιεῖτο, τῆς χρείας ἀξίαν προσλαμβανούσης καὶ ζῆλον. οὐ γὰρ ἦν δημοσίᾳ τιμώμενον ὁρῶντας ἰδίᾳ καταφρονεῖν ὡς ἀχρήστου, καὶ πρὸς τὰ οἰκεῖα νομίζειν ἑκάστῳ μηδενὸς ἄξιον πρᾶγμα τὸ κοινῇ οὕτως εὐδοκιμοῦν καὶ ἀγαπώμενον, ἀλλὰ καὶ πολλῷ τάχιον ἀπὸ τῶν κοινῶν ἐπιτηδευμάτων ἐπιρρέουσιν οἱ ἐθισμοὶ τοῖς ἰδιωτικοῖς βίοις ἢ τὰ καθ’ ἕκαστον ὀλισθήματα καὶ πάθη τὰς πόλεις ἀναπίμπλησι πραγμάτων πονηρῶν. τῷ γὰρ ὅλῳ συνδιαστρέφεσθαι τὰ μέρη μᾶλλον, ὅταν ἐνδῷ πρὸς τὸ χεῖρον, εἰκός, αἱ δὲ ἀπὸ μέρους εἰς ὅλον ἁμαρτίαι πολλὰς ἐνστάσεις καὶ βοηθείας ἀπὸ τῶν ὑγιαινόντων ἔχουσιν. οἱ δὲ ταῖς μὲν οἰκίαις τῶν πολιτῶν, ὅπως οὐ πάρεισιν εἰς αὐτὰς νόμισμα, τὸν φόβον ἐπέστησαν φύλακα καὶ τὸν νόμον, αὐτὰς δὲ τὰς ψυχὰς ἀνεκπλήκτους καὶ ἀπαθεῖς πρὸς ἀργύριον οὐ διετήρησαν, ἐμβαλόντες εἰς ζῆλον ὡς σεμνοῦ δή τινος καὶ μεγάλου τοῦ πλουτεῖν ἅπαντας. περὶ μὲν οὖν τούτων καὶ δι’ ἑτέρας που γραφῆς ἡψάμεθα Λακεδαιμονίων.", "st": "Lys. 17.4"}, {"sp": "N", "t": "ὁ δὲ Λύσανδρος ἔστησεν ἀπὸ τῶν λαφύρων ἐν Δελφοῖς αὑτοῦ χαλκῆν εἰκόνα καὶ τῶν ναυάρχων ἑκάστου καὶ χρυσοῦς ἀστέρας τῶν Διοσκούρων, οἳ πρὸ τῶν Λευκτρικῶν ἠφανίσθησαν. ἐν δὲ τῷ Βρασίδου καὶ Ἀκανθίων θησαυρῷ τριήρης ἔκειτο διὰ χρυσοῦ πεποιημένη καὶ ἐλέφαντος δυεῖν πηχῶν, ἣν Κῦρος αὐτῷ νικητήριον ἔπεμψεν. Ἀναξανδρίδης δὲ ὁ Δελφὸς ἱστορεῖ καὶ παρακαταθήκην ἐνταῦθα Λυσάνδρου κεῖσθαι τάλαντον ἀργυρίου καὶ μνᾶς πεντήκοντα δύο καὶ πρὸς τούτοις ἕνδεκα στατῆρας, οὐχ ὁμολογούμενα γράφων τοῖς περὶ τῆς πενίας τοῦ ἀνδρὸς ὁμολογουμένοις. τότε δ’ οὖν ὁ Λύσανδρος ὅσον οὐδεὶς τῶν πρόσθεν Ἑλλήνων δυνηθεὶς ἐδόκει φρονήματι καὶ ὄγκῳ μείζονι κεχρῆσθαι τῆς δυνάμεως. πρώτῳ μὲν γάρ, ὡς ἱστορεῖ Δοῦρις, Ἑλλήνων ἐκείνῳ βωμοὺς αἱ πόλεις ἀνέστησαν ὡς θεῷ καὶ θυσίας ἔθυσαν, εἰς πρῶτον δὲ παιᾶνες ᾔσθησαν, ὧν ἑνὸς ἀρχὴν ἀπομνημονεύουσι τοιάνδε·", "st": "Lys. 18.1"}, {"sp": "N", "t": "τὸν Ἑλλάδος ἀγαθέας<br>στραταγὸν ἀπ’ εὐρυχόρου<br>Σπάρτας ὑμνήσομεν, ὦ, ἰὴ Παιάν.", "st": "Lys. 18.1b"}, {"sp": "N", "t": "σάμιοι δὲ τὰ παρ’ αὐτοῖς Ἡραῖα Λυσάνδρεια καλεῖν ἐψηφίσαντο. τῶν δὲ ποιητῶν Χοιρίλον μὲν ἀεὶ περὶ αὑτὸν εἶχεν ὡς κοσμήσοντα τὰς πράξεις διὰ ποιητικῆς, Ἀντιλόχῳ δὲ ποιήσαντι μετρίους τινὰς εἰς αὐτὸν στίχους ἡσθεὶς ἔδωκε πλήσας ἀργυρίου τὸν πῖλον. Ἀντιμάχου δὲ τοῦ Κολοφωνίου καὶ Νικηράτου τινὸς Ἡρακλεώτου ποιήμασι Λυσάνδρεια διαγωνισαμένων ἐπ’ αὐτοῦ τὸν Νικήρατον ἐστεφάνωσεν, ὁ δὲ Ἀντίμαχος ἀχθεσθεὶς ἠφάνισε τὸ ποίημα. Πλάτων δὲ νέος ὢν τότε, καὶ θαυμάζων τὸν Ἀντίμαχον ἐπὶ τῇ ποιητικῇ, βαρέως φέροντα τὴν ἧτταν ἀνελάμβανε καὶ παρεμυθεῖτο, τοῖς ἀγνοοῦσι κακὸν εἶναι φάμενος τὴν ἄγνοιαν, ὥσπερ τὴν τυφλότητα τοῖς μὴ βλέπουσιν. ἐπεὶ μέντοι ὁ κιθαρῳδὸς Ἀριστόνους ἑξάκις Πύθια νενικηκὼς ἐπηγγέλλετο τῷ Λυσάνδρῳ φιλοφρονούμενος, ἂν νικήσῃ πάλιν, Λυσάνδρου κηρύξειν ἑαυτόν, ἦ δοῦλον; εἶπεν.", "st": "Lys. 18.4"}, {"sp": "N", "t": "ἀλλ’ ἡ μὲν φιλοτιμία τοῦ Λυσάνδρου τοῖς πρώτοις καὶ ἰσοτίμοις ἦν ἐπαχθὴς μόνον. ὑπεροψίας δὲ πολλῆς ἅμα τῇ φιλοτιμίᾳ διὰ τοὺς θεραπεύοντας ἐγγενομένης τῷ ἤθει καὶ βαρύτητος, οὔτε τιμῆς οὔτε τιμωρίας μέτρον ἦν παρ’ αὐτῷ δημοτικόν, ἀλλὰ φιλίας μὲν ἆθλα καὶ ξενίας ἀνυπεύθυνοι δυναστεῖαι πόλεων καὶ τυραννίδες ἀνεξέταστοι, θυμοῦ δὲ μία πλήρωσις ἀπολέσθαι τὸν ἀπεχθόμενον· οὐδὲ γὰρ φυγεῖν ἐξῆν. ἀλλὰ καὶ Μιλησίων ὕστερον τοὺς τοῦ δήμου προϊσταμένους δεδιὼς μὴ φύγωσι, καὶ προαγαγεῖν τοὺς κεκρυμμένους βουλόμενος, ὤμοσε μὴ ἀδικήσειν· πιστεύσαντας δὲ καὶ προελθόντας ἀποσφάξαι τοῖς ὀλιγαρχικοῖς παρέδωκεν, οὐκ ἐλάττονας ὀκτακοσίων συναμφοτέρους ὄντας. ἦν δὲ καὶ τῶν ἄλλων ἐν ταῖς πόλεσι δημοτικῶν φόνος οὐκ ἀριθμητός, ἅτε δὴ μὴ κατ’ ἰδίας μόνον αἰτίας αὐτοῦ κτείνοντος, ἀλλὰ πολλαῖς μὲν ἔχθραις, πολλαῖς δὲ πλεονεξίαις τῶν ἑκασταχόθι φίλων χαριζομένου τὰ τοιαῦτα καὶ συνεργοῦντος. ὅθεν εὐδοκίμησεν Ἐτεοκλῆς ὁ Λακεδαιμόνιος εἰπὼν ὡς οὐκ ἂν ἡ Ἑλλὰς δύο Λυσάνδρους ἤνεγκε. τὸ δὲ αὐτὸ τοῦτο καὶ περὶ Ἀλκιβιάδου φησὶ Θεόφραστος εἰπεῖν Ἀρχέστρατον. ἀλλ’ ἐκεῖ μὲν ὕβρις ἦν καὶ τρυφὴ σὺν αὐθαδείᾳ τὸ μάλιστα δυσχεραινόμενον· τὴν δὲ Λυσάνδρου δύναμιν ἡ τοῦ τρόπου χαλεπότης φοβερὰν ἐποίει καὶ βαρεῖαν.οἱ δὲ Λακεδαιμόνιοι τοῖς μὲν ἄλλοις οὐ πάνυ προσεῖχον ἐγκαλοῦσιν·", "st": "Lys. 19.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Φαρνάβαζος ἀδικούμενος ὑπ’ αὐτοῦ τὴν χώραν ἄγοντος καὶ φέροντος ἀπέστειλεν εἰς τὴν Σπάρτην κατηγόρους, ἀγανακτήσαντες οἱ ἔφοροι τῶν μὲν φίλων αὐτοῦ καὶ συστρατήγων ἕνα Θώρακα λαβόντες ἀργύριον ἰδίᾳ κεκτημένον ἀπέκτειναν, ἐκείνῳ δὲ σκυτάλην ἔπεμψαν ἥκειν κελεύοντες.", "st": "Lys. 19.1b"}, {"sp": "N", "t": "ἔστι δὲ ἡ σκυτάλη τοιοῦτον. ἐπὰν ἐκπέμπωσι ναύαρχον ἢ στρατηγὸν οἱ ἔφοροι, ξύλα δύο στρογγύλα μῆκος καὶ πάχος ἀκριβῶς ἀπισώσαντες, ὥστε ταῖς τομαῖς ἐφαρμόζειν πρὸς ἄλληλα, τὸ μὲν αὐτοὶ φυλάττουσι, θάτερον δὲ τῷ πεμπομένῳ διδόασι. ταῦτα δὲ τὰ ξύλα σκυτάλας καλοῦσιν. ὅταν οὖν ἀπόρρητόν τι καὶ μέγα φράσαι βουληθῶσι, βιβλίον ὥσπερ ἱμάντα μακρὸν καὶ στενὸν ποιοῦντες περιελίττουσι τὴν παρ’ αὐτοῖς σκυτάλην, οὐδὲν διάλειμμα ποιοῦντες, ἀλλὰ πανταχόθεν κύκλῳ τὴν ἐπιφάνειαν αὐτῆς τῷ βιβλίῳ καταλαμβάνοντες. τοῦτο δὲ ποιήσαντες ἃ βούλονται καταγράφουσιν εἰς τὸ βιβλίον, ὥσπερ ἐστὶ τῇ σκυτάλῃ περικείμενον· ὅταν δὲ γράψωσιν, ἀφελόντες τὸ βιβλίον ἄνευ τοῦ ξύλου πρὸς τὸν στρατηγὸν ἀποστέλλουσι. δεξάμενος δὲ ἐκεῖνος ἄλλως μὲν οὐδὲν ἀναλέξασθαι δύναται τῶν γραμμάτων συναφὴν οὐκ ἐχόντων, ἀλλὰ διεσπασμένων, τὴν δὲ παρ’ αὑτῷ σκυτάλην λαβὼν τὸ τμῆμα τοῦ βιβλίου περὶ αὐτὴν περιέτεινεν, ὥστε, τῆς ἕλικος εἰς τάξιν ὁμοίως ἀποκαθισταμένης, ἐπιβάλλοντα τοῖς πρώτοις τὰ δεύτερα, κύκλῳ τὴν ὄψιν ἐπάγειν τὸ συνεχὲς ἀνευρίσκουσαν. καλεῖται δὲ ὁμωνύμως τῷ ξύλῳ σκυτάλη τὸ βιβλίον, ὡς τῷ μετροῦντι τὸ μετρούμενον.", "st": "Lys. 19.5"}, {"sp": "N", "t": "ὁ δὲ Λύσανδρος, ἐλθούσης τῆς σκυτάλης πρὸς αὐτὸν εἰς τὸν Ἑλλήσποντον, διεταράχθη, καὶ μάλιστα τὰς τοῦ Φαρναβάζου δεδιὼς κατηγορίας, ἐσπούδασεν εἰς λόγους αὐτῷ συνελθεῖν, ὡς λύσων τὴν διαφοράν. καὶ συνελθὼν ἐδεῖτο γράψαι περὶ αὐτοῦ πρὸς τοὺς ἄρχοντας ἑτέραν ἐπιστολὴν ὡς οὐδὲν ἠδικημένον οὐδ’ ἐγκαλοῦντα. πρὸς Κρῆτα δὲ ἄρα, τὸ τοῦ λόγου, κρητίζων ἠγνόει τὸν Φαρνάβαζον. ὑποσχόμενος γὰρ ἅπαντα ποιήσειν, φανερῶς μὲν ἔγραψεν οἵαν ὁ Λύσανδρος ἠξίωσεν ἐπιστολήν, κρύφα δὲ εἶχεν ἑτέραν αὐτόθι γεγραμμένην. ἐν δὲ τῷ τὰς σφραγῖδας ἐπιβάλλειν ἐναλλάξας τὰ βιβλία μηδὲν διαφέροντα τῇ ὄψει, δίδωσιν ἐκείνην αὐτῷ τὴν κρύφα γεγραμμένην. ἀφικόμενος οὖν ὁ Λύσανδρος εἰς Λακεδαίμονα καὶ πορευθείς, ὥσπερ ἔθος ἐστίν, εἰς τὸ ἀρχεῖον, ἀπέδωκε τοῖς ἐφόροις τὰ γράμματα τοῦ Φαρναβάζου, πεπεισμένος ἀνῃρῆσθαι τὸ μέγιστον αὐτοῦ τῶν ἐγκλημάτων· ἠγαπᾶτο γὰρ ὁ Φαρνάβαζος ὑπὸ τῶν Λακεδαιμονίων, προθυμότατος ἐν τῷ πολέμῳ τῶν βασιλέως στρατηγῶν γεγενημένος. ἐπεὶ δὲ ἀναγνόντες οἱ ἔφοροι τὴν ἐπιστολὴν ἔδειξαν αὐτῷ, καὶ συνῆκεν ὡς", "st": "Lys. 20.1"}, {"sp": "N", "t": "οὐκ ἆρ’ Ὀδυσσεύς ἐστιν αἱμύλος μόνος,", "st": "Lys. 20.1b"}, {"sp": "N", "t": "τότε μὲν ἰσχυρῶς τεθορυβημένος ἀπῆλθεν· ἡμέραις δὲ ὀλίγαις ὕστερον ἐντυχὼν τοῖς ἄρχουσιν ἔφη δεῖν αὐτὸν εἰς Ἄμμωνος ἀναβῆναι καὶ τῷ θεῷ θῦσαι θυσίας ἃς εὔξατο πρὸ τῶν ἀγώνων. ἔνιοι μὲν οὖν ἀληθῶς φασιν αὐτῷ πολιορκοῦντι τὴν τῶν Ἀφυταίων πόλιν ἐν Θρᾴκῃ κατὰ τοὺς ὕπνους παραστῆναι τὸν Ἄμμωνα· διὸ καὶ τὴν πολιορκίαν ἀφείς, ὡς τοῦ θεοῦ προστάξαντος, ἐκέλευσε τοὺς Ἀφυταίους Ἄμμωνι θύειν καὶ τὸν θεὸν ἐσπούδασεν εἰς τὴν Λιβύην πορευθεὶς ἐξιλάσασθαι. τοῖς δὲ πλείστοις ἐδόκει πρόσχημα ποιεῖσθαι τὸν θεόν, ἄλλως δὲ τοὺς ἐφόρους δεδοικὼς καὶ τὸν οἴκοι ζυγὸν οὐ φέρων οὐδ’ ὑπομένων ἄρχεσθαι πλάνης ὀρέγεσθαι καὶ περιφοιτήσεως τινός, ὥσπερ ἵππος ἐκ νομῆς ἀφέτου καὶ λειμῶνος αὖθις ἥκων ἐπὶ φάτνην καὶ πρὸς τὸ σύνηθες ἔργον αὖθις ἀγόμενος. ἣν μὲν γὰρ Ἔφορος τῆς ἀποδημίας ταύτης αἰτίαν ἀναγράφει, μετὰ μικρὸν ἀφηγήσομαι.", "st": "Lys. 20.5"}, {"sp": "N", "t": "μόλις δὲ καὶ χαλεπῶς ἀφεθῆναι διαπραξάμενος ὑπὸ τῶν ἐφόρων ἐξέπλευσεν. οἱ δὲ βασιλεῖς ἀποδημήσαντος αὐτοῦ συμφρονήσαντες ὅτι ταῖς ἑταιρείαις τὰς πόλεις κατέχων διὰ παντὸς ἄρχει καὶ κύριός ἐστι τῆς Ἑλλάδος, ἔπρασσον ὅπως ἀποδώσουσι τοῖς δημόταις τὰ πράγματα τοὺς ἐκείνου φίλους ἐκβαλόντες. οὐ μὴν ἀλλὰ πάλιν πρὸς ταῦτα κινήματος γενομένου, καὶ πρώτων τῶν ἀπὸ Φυλῆς Ἀθηναίων ἐπιθεμένων τοῖς τριάκοντα καὶ κρατούντων, ἐπανελθὼν διὰ ταχέων ὁ Λύσανδρος ἔπεισε τοὺς Λακεδαιμονίους ταῖς ὀλιγαρχίαις βοηθεῖν καὶ τοὺς δήμους κολάζειν. καὶ πρώτοις τοῖς τριάκοντα πέμπουσιν ἑκατὸν τάλαντα πρὸς τὸν πόλεμον καὶ στρατηγὸν αὐτὸν Λύσανδρον. οἱ δὲ βασιλεῖς φθονοῦντες καὶ δεδιότες μὴ πάλιν ἕλῃ τὰς Ἀθήνας, ἔγνωσαν ἐξιέναι τὸν ἕτερον αὐτῶν. ἐξῆλθε δὲ ὁ Παυσανίας, λόγῳ μὲν ὑπὲρ τῶν τυράννων ἐπὶ τὸν δῆμον, ἔργῳ δὲ καταλύσων τὸν πόλεμον, ὡς μὴ πάλιν ὁ Λύσανδρος διὰ τῶν φίλων κύριος γένοιτο τῶν Ἀθηνῶν. τοῦτο μὲν οὖν διεπράξατο ῥᾳδίως· καὶ τοὺς Ἀθηναίους διαλλάξας καὶ καταπαύσας τὴν στάσιν ἀφείλετο τοῦ Λυσάνδρου τὴν φιλοτιμίαν. ὀλίγῳ δὲ ὕστερον ἀποστάντων πάλιν τῶν Ἀθηναίων αὐτὸς μὲν αἰτίαν ἔλαβεν, ὡς ἐγκεχαλινωμένον τῇ ὀλιγαρχίᾳ τὸν δῆμον ἀνεὶς αὖθις ἐξυβρίσαι καὶ θρασύνασθαι, τῷ δὲ Λυσάνδρῳ προσεθήκατο δόξαν ἀνδρὸς οὐ πρὸς ἑτέρων χάριν οὐδὲ θεατρικῶς, ἀλλὰ πρὸς τὸ τῇ Σπάρτῃ συμφέρον αὐθεκάστως στρατηγοῦντος.", "st": "Lys. 21.1"}, {"sp": "N", "t": "ἦν δὲ καὶ τῷ λόγῳ θρασὺς καὶ καταπληκτικὸς πρὸς τοὺς ἀντιτείνοντας. Ἀργείοις μὲν γὰρ ἀμφιλογουμένοις περὶ γῆς ὅρων καὶ δικαιότερα τῶν Λακεδαιμονίων οἰομένοις λέγειν δείξας τὴν μάχαιραν, ὁ ταύτης, ἔφη, κρατῶν βέλτιστα περὶ γῆς ὅρων διαλέγεται. Μεγαρέως δὲ ἀνδρὸς ἔν τινι συλλόγῳ παρρησίᾳ χρησαμένου πρὸς αὐτόν, οἱ λόγοι σου, εἶπεν, ὦ ξένε, πόλεως δέονται. τοὺς δὲ Βοιωτοὺς ἐπαμφοτερίζοντας ἠρώτα πότερον ὀρθοῖς τοῖς δόρασιν ἢ κεκλιμένοις διαπορεύηται τὴν χώραν αὐτῶν. ἐπεὶ δὲ τῶν Κορινθίων ἀφεστώτων παρερχόμενος πρὸς τὰ τείχη τοὺς Λακεδαιμονίους ἑώρα προσβάλλειν ὀκνοῦντας, καὶ λαγώς τις ὤφθη διαπηδῶν τὴν τάφρον, οὐκ αἰσχύνεσθε, ἔφη, τοιούτους φοβούμενοι πολεμίους, ὧν οἱ λαγωοὶ δι’ ἀργίαν τοῖς τείχεσιν ἐγκαθεύδουσιν;", "st": "Lys. 22.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Ἆγις ὁ βασιλεὺς ἐτελεύτησεν ἀδελφὸν μὲν Ἀγησίλαον καταλιπών, υἱὸν δὲ νομιζόμενον Λεωτυχίδαν, ἐραστὴς τοῦ Ἀγησιλάου γεγονὼς ὁ Λύσανδρος ἔπεισεν αὐτὸν ἀντιλαμβάνεσθαι τῆς βασιλείας ὡς Ἡρακλείδην ὄντα γνήσιον. ὁ γὰρ Λεωτυχίδας διαβολὴν εἶχεν ἐξ Ἀλκιβιάδου γεγονέναι, συνόντος κρύφα τῇ Ἄγιδος γυναικὶ Τιμαίᾳ καθ’ ὃν χρόνον φεύγων ἐν Σπάρτῃ διέτριβεν. ὁ δὲ Ἆγις, ὥς φασι, χρόνου λογισμῷ τὸ πρᾶγμα συνελών, ὡς οὐ κυήσειεν ἐξ αὐτοῦ, παρημέλει τοῦ Λεωτυχίδου καὶ φανερὸς ἦν ἀναινόμενος αὐτὸν παρά γε τὸν λοιπὸν χρόνον. ἐπεὶ δὲ νοσῶν εἰς Ἡραίαν ἐκομίσθη καὶ τελευτᾶν ἔμελλε, τὰ μὲν ὑπ’ αὐτοῦ τοῦ νεανίσκου, τὰ δὲ ὑπὸ τῶν φίλων ἐκλιπαρηθεὶς ἐναντίον πολλῶν ἀπέφηνεν υἱὸν αὑτοῦ τὸν Λεωτυχίδαν, καὶ δεηθεὶς τῶν παρόντων ἐπιμαρτυρῆσαι ταῦτα πρὸς τοὺς Λακεδαιμονίους ἀπέθανεν. οὗτοι μὲν οὖν ἐμαρτύρουν ταῦτα τῷ Λεωτυχίδᾳ· τὸν δ’ Ἀγησίλαον λαμπρὸν ὄντα τἆλλα καὶ συναγωνιστῇ τῷ Λυσάνδρῳ χρώμενον ἔβλαπτε Διοπείθης, ἀνὴρ εὐδόκιμος ἐπὶ χρησμολογίᾳ, τοιόνδε μάντευμα προφέρων εἰς τὴν χωλότητα τοῦ Ἀγησιλάου·", "st": "Lys. 22.3"}, {"sp": "N", "t": "φράζεο δή, Σπάρτη, καίπερ μεγάλαυχος ἐοῦσα,<br>μὴ σέθεν ἀρτίποδος βλάστῃ χωλὴ βασιλεία.<br>δηρὸν γὰρ μόχθοι σε κατασχήσουσιν ἄελπτοι<br>φθισιβρότου τ’ ἐπὶ κῦμα κυλινδόμενον πολέμοιο.", "st": "Lys. 22.3b"}, {"sp": "N", "t": "πολλῶν οὖν ὑποκατακλινομένων πρὸς τὸ λόγιον καὶ τρεπομένων πρὸς τὸν Λεωτυχίδαν, ὁ Λύσανδρος οὐκ ὀρθῶς ἔφη τὸν Διοπείθη τὴν μαντείαν ὑπολαμβάνειν· οὐ γὰρ ἂν προσπταίσας τις ἄρχῃ Λακεδαιμονίων, δυσχεραίνειν τὸν θεόν, ἀλλὰ χωλὴν εἶναι τὴν βασιλείαν εἰ νόθοι καὶ κακῶς γεγονότες βασιλεύσουσι σὺν Ἡρακλείδαις. τοιαῦτα λέγων καὶ δυνάμενος πλεῖστον ἔπεισε, καὶ γίνεται βασιλεὺς Ἀγησίλαος.", "st": "Lys. 22.6"}, {"sp": "N", "t": "εὐθὺς οὖν αὐτὸν ἐξώρμα καὶ προὔτρεπεν ὁ Λύσανδρος εἰς τὴν Ἀσίαν στρατεύειν, ὑποτιθεὶς ἐλπίδας ὡς καταλύσοντι Πέρσας καὶ μεγίστῳ γενησομένῳ, πρός τε τοὺς ἐν Ἀσίᾳ φίλους ἔγραψεν αἰτεῖσθαι κελεύων παρὰ Λακεδαιμονίων στρατηγὸν Ἀγησίλαον ἐπὶ τὸν πρὸς τοὺς βαρβάρους πόλεμον. οἱ δὲ ἐπείθοντο καὶ πρέσβεις ἔπεμπον εἰς Λακεδαίμονα δεομένους· ὃ δοκεῖ τῆς βασιλείας οὐκ ἔλαττον Ἀγησιλάῳ καλὸν ὑπάρξαι διὰ Λύσανδρον. ἀλλ’ αἱ φιλότιμοι φύσεις ἄλλως μὲν οὐ κακαὶ πρὸς τὰς ἡγεμονίας εἰσί, τὸ δὲ φθονεῖν τοῖς ὁμοίοις διὰ δόξαν οὐ μικρὸν ἐμπόδιον τῶν καλῶν πράξεων ἔχουσι· ποιοῦνται γὰρ ἀνταγωνιστὰς τῆς ἀρετῆς οἷς πάρεστι χρῆσθαι συνεργοῖς. Ἀγησίλαος μὲν οὖν ἐπηγάγετο Λύσανδρον ἐν τοῖς τριάκοντα συμβούλοις ὡς μάλιστα καὶ πρώτῳ τῶν φίλων χρησόμενος· ἐπεὶ δὲ εἰς τὴν Ἀσίαν παραγενομένων πρὸς ἐκεῖνον μὲν οὐκ ἔχοντες οἱ ἄνθρωποι συνήθως βραχέα καὶ σπανίως διελέγοντο, τὸν δὲ Λύσανδρον ἐκ πολλῆς τῆς πρόσθεν ὁμιλίας οἵ τε φίλοι θεραπεύοντες οἵ τε ὕποπτοι δεδοικότες ἐφοίτων ἐπὶ θύρας καὶ παρηκολούθουν, οἷον ἐν τραγῳδίαις ἐπιεικῶς συμβαίνει περὶ τοὺς ὑποκριτάς, τὸν μὲν ἀγγέλου τινὸς ἢ θεράποντος ἐπικείμενον πρόσωπον εὐδοκιμεῖν καὶ πρωταγωνιστεῖν, τὸν δὲ διάδημα καὶ σκῆπτρον φοροῦντα μηδὲ ἀκούεσθαι φθεγγόμενον, οὕτω περὶ τὸν σύμβουλον ἦν τὸ πᾶν ἀξίωμα τῆς ἀρχῆς, τῷ δὲ βασιλεῖ τοὔνομα τῆς δυνάμεως ἔρημον ἀπελείπετο. γενέσθαι μὲν οὖν ἴσως ἔδει τινὰ τῆς ἐκμελοῦς ταύτης φιλοτιμίας ἐπαφὴν καὶ συσταλῆναι τὸν Λύσανδρον ἄχρι τῶν δευτερείων· τὸ δὲ παντελῶς ἀπορρῖψαι καὶ προπηλακίσαι διὰ δόξαν εὐεργέτην ἄνδρα καὶ φίλον οὐκ ἦν ἄξιον Ἀγησιλάῳ προσεῖναι.πρῶτον μὲν οὖν οὐ παρεῖχεν αὐτῷ πράξεων ἀφορμάς, οὐδὲ ἔταττεν ἐφ’ ἡγεμονίας·", "st": "Lys. 23.1"}, {"sp": "N", "t": "ἔπειτα ὑπὲρ ὧν αἴσθοιτό τι πράττοντα καὶ σπουδάζοντα τὸν Λύσανδρον, ἀεὶ τούτους πάντων ἀπράκτους καὶ τῶν ἐπιτυχόντων ἔλαττον ἔχοντας ἀπέπεμπε, παραλύων ἡσυχῆ καὶ διαψύχων τὴν ἐκείνου δύναμιν. ἐπεὶ δὲ τῶν πάντων διαμαρτάνων ὁ Λύσανδρος ἔγνω τοῖς φίλοις τὴν παρ’ αὑτοῦ σπουδὴν ἐναντίωμα γινομένην, αὐτός τε τὸ βοηθεῖν ἐξέλιπε κἀκείνων ἐδεῖτο μὴ προσιέναι μηδὲ θεραπεύειν αὐτόν, ἀλλὰ τῷ βασιλεῖ διαλέγεσθαι καὶ τοῖς δυναμένοις ὠφελεῖν τοὺς τιμῶντας αὐτοὺς μᾶλλον ἐν τῷ παρόντι. ταῦτα ἀκούοντες οἱ πολλοὶ τοῦ μὲν ἐνοχλεῖν αὐτὸν περὶ πραγμάτων ἀπείχοντο, τὰς δὲ θεραπείας οὐ κατέλιπον, ἀλλὰ προσφοιτῶντες ἐν τοῖς περιπάτοις καὶ γυμνασίοις ἔτι μᾶλλον ἢ πρότερον ἠνίων τὸν Ἀγησίλαον ὑπὸ φθόνου τῆς τιμῆς, ὥστε τοῖς πολλοῖς Σπαρτιάταις ἡγεμονίας πραγμάτων καὶ διοικήσεις πόλεων ἀποδιδοὺς τὸν Λύσανδρον ἀπέδειξε κρεοδαίτην. εἶτα οἷον ἐφυβρίζων πρὸς τοὺς Ἴωνας, ἀπιόντες, ἔφη, νῦν τὸν ἐμὸν κρεοδαίτην θεραπευέτωσαν. ἔδοξεν οὖν τῷ Λυσάνδρῳ διὰ λόγων πρὸς αὐτὸν ἐλθεῖν· καὶ γίνεται βραχὺς καὶ Λακωνικὸς αὐτῶν διάλογος. ἦ καλῶς ᾔδεις, ὦ Ἀγησίλαε, φίλους ἐλαττοῦν. καὶ ὅς· ἄν γε ἐμοῦ βούλωνται μείζονες εἶναι· τοὺς δὲ αὔξοντας τὴν ἐμὴν δύναμιν καὶ μετέχειν αὐτῆς δίκαιον. ἀλλ’ ἴσως μέν, ὦ Ἀγησίλαε, σοὶ λέλεκται κάλλιον ἢ ἐμοὶ πέπρακται· δέομαι δέ σου καὶ διὰ τοὺς ἐκτὸς ἀνθρώπους, οἳ πρὸς ἡμᾶς ἀποβλέπουσιν, ἐνταῦθά με τῆς σεαυτοῦ στρατηγίας τάξον, ὅπου τεταγμένον ἥκιστα μὲν ἐπαχθῆ, μᾶλλον δὲ χρήσιμον ἔσεσθαι σεαυτῷ νομίζεις.", "st": "Lys. 23.6"}, {"sp": "N", "t": "ἐκ τούτου πρεσβευτὴς εἰς Ἑλλήσποντον ἐπέμπετο· καὶ τὸν μὲν Ἀγησίλαον δι’ ὀργῆς εἶχεν, οὐκ ἠμέλει δὲ τοῦ τὰ δέοντα πράττειν, Σπιθριδάτην δὲ τὸν Πέρσην προσκεκρουκότα Φαρναβάζῳ, γενναῖον ἄνδρα καὶ στρατιὰν ἔχοντα περὶ αὑτόν, ἀποστήσας ἤγαγε πρὸς τὸν Ἀγησίλαον. ἄλλο δὲ οὐδὲν ἐχρήσατο αὐτῷ πρὸς τὸν πόλεμον, ἀλλὰ τοῦ χρόνου διελθόντος ἀπέπλευσεν εἰς τὴν Σπάρτην ἀτίμως, ὀργιζόμενος μὲν τῷ Ἀγησιλάῳ, μισῶν δὲ καὶ τὴν ὅλην πολιτείαν ἔτι μᾶλλον ἢ πρότερον, καὶ τὰ πάλαι δοκοῦντα συγκεῖσθαι καὶ μεμηχανῆσθαι πρὸς μεταβολὴν καὶ νεωτερισμὸν ἐγνωκὼς ἐγχειρεῖν τότε καὶ μὴ διαμέλλειν.", "st": "Lys. 24.1"}, {"sp": "N", "t": "ἦν δὲ τοιάδε. τῶν ἀναμιχθέντων Δωριεῦσιν Ἡρακλειδῶν καὶ κατελθόντων εἰς Πελοπόννησον πολὺ μὲν ἐν Σπάρτῃ καὶ λαμπρὸν ἤνθησε γένος, οὐ παντὶ δὲ αὐτῶν τῆς βασιλικῆς μετῆν διαδοχῆς, ἀλλ’ ἐβασίλευον ἐκ δυεῖν οἴκων μόνον Εὐρυπωντίδαι καὶ Ἀγιάδαι προσαγορευόμενοι, τοῖς δὲ ἄλλοις οὐδὲν ἑτέρου πλέον ἔχειν ἐν τῇ πολιτείᾳ διὰ τὴν εὐγένειαν ὑπῆρχεν, αἱ δὲ ἀπ’ ἀρετῆς τιμαὶ πᾶσι προὔκειντο τοῖς δυναμένοις. τούτων οὖν γεγονὼς ὁ Λύσανδρος, ὡς εἰς δόξαν τῶν πράξεων ἤρθη μεγάλην καὶ φίλους ἐκέκτητο πολλοὺς καὶ δύναμιν, ἤχθετο τὴν πόλιν ὁρῶν ὑπ’ αὐτοῦ μὲν αὐξανομένην, ὑφ’ ἑτέρων δὲ βασιλευομένην οὐδὲν βέλτιον αὐτοῦ γεγονότων, καὶ διενοεῖτο τὴν ἀρχὴν ἐκ τῶν δυεῖν οἴκων μεταστήσας εἰς κοινὸν ἀποδοῦναι πᾶσιν Ἡρακλείδαις, ὡς δὲ ἔνιοί φασιν, οὐχ Ἡρακλείδαις, ἀλλὰ Σπαρτιάταις, ἵνα μὴ ᾖ τῶν ἀφ’ Ἡρακλέους, ἀλλὰ τῶν οἷος Ἡρακλῆς τὸ γέρας, ἀρετῇ κρινομένων, ἣ κἀκεῖνον εἰς θεῶν τιμὰς ἀνήγαγεν. ἤλπιζε δὲ τῆς βασιλείας οὕτω δικαζομένης οὐδένα πρὸ αὑτοῦ Σπαρτιάτην ἂν αἱρεθήσεσθαι.", "st": "Lys. 24.3"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἐπεχείρησε καὶ παρεσκευάσατο πείθειν δι’ ἑαυτοῦ τοὺς πολίτας, καὶ λόγον ἐξεμελέτα πρὸς τὴν ὑπόθεσιν γεγραμμένον ὑπὸ Κλέωνος τοῦ Ἁλικαρνασσέως. ἔπειτα τὴν ἀτοπίαν καὶ τὸ μέγεθος τοῦ καινοτομουμένου πράγματος ὁρῶν ἰταμωτέρας δεόμενον βοηθείας, ὥσπερ ἐν τραγῳδία μηχανὴν αἴρων ἐπὶ τοὺς πολίτας, λόγια πυθόχρηστα καὶ χρησμοὺς συνετίθει καὶ κατεσκεύαζεν, ὡς οὐδὲν ὠφελησόμενος ὑπὸ τῆς Κλέωνος δεινότητος, εἰ μὴ φόβῳ θεοῦ τινι καὶ δεισιδαιμονίᾳ προεκπλήξας καὶ χειρωσάμενος ὑπαγάγοι πρὸς τὸν λόγον τοὺς πολίτας. ἔφορος μὲν οὖν φησιν αὐτόν, ὡς τήν τε Πυθίαν ἐπιχειρήσας διαφθεῖραι καὶ τὰς Δωδωνίδας αὖθις ἀναπείθων διὰ Φερεκλέους ἀπέτυχεν, εἰς Ἄμμωνος ἀναβῆναι καὶ διαλέγεσθαι τοῖς προφήταις πολὺ χρυσίον διδόντα, τοὺς δὲ δυσχεραίνοντας εἰς Σπάρτην τινὰς ἀποστεῖλαι τοῦ Λυσάνδρου κατηγορήσοντας, ἐπεὶ δὲ ἀπελύθη, τοὺς Λίβυας ἀπιόντας εἰπεῖν· ἀλλ’ ἡμεῖς γε βέλτιον, ὦ Σπαρτιᾶται, κρινοῦμεν, ὅταν ἥκητε πρὸς ἡμᾶς εἰς Λιβύην οἰκήσοντες, ὡς δὴ χρησμοῦ τινος ὄντος παλαιοῦ Λακεδαιμονίους ἐν Λιβύῃ κατοικῆσαι. τὴν δὲ ὅλην ἐπιβουλὴν καὶ σκευωρίαν τοῦ πλάσματος οὐ φαύλην οὖσαν οὐδὲ ἀφ’ ὧν ἔτυχεν ἀρξαμένην, ἀλλὰ πολλὰς καὶ μεγάλας ὑποθέσεις, ὥσπερ ἐν διαγράμματι μαθηματικῷ, προσλαβοῦσαν καὶ διὰ λημμάτων χαλεπῶν καὶ δυσπορίστων ἐπὶ τὸ συμπέρασμα προϊοῦσαν, ἡμεῖς ἀναγράψομεν ἀνδρὸς ἱστορικοῦ καὶ φιλοσόφου λόγῳ κατακολουθήσαντες.", "st": "Lys. 25.1"}, {"sp": "N", "t": "ἦν γύναιον ἐν Πόντῳ κύειν ἐξ Ἀπόλλωνος φάμενον, ᾧ πολλοὶ μέν, ὡς εἰκὸς ἦν, ἠπίστουν, πολλοὶ δὲ καὶ προσεῖχον, ὥστε καὶ τεκούσης παιδάριον ἄρρεν ὑπὸ πολλῶν καὶ γνωρίμων σπουδάζεσθαι τὴν ἐκτροφὴν αὐτοῦ καὶ τὴν ἐπιμέλειαν. ὄνομα δὲ τῷ παιδὶ Σειληνὸς ἐκ δή τινος αἰτίας ἐτέθη. ταύτην λαβὼν ὁ Λύσανδρος ἀρχήν, τὰ λοιπὰ παρ’ ἑαυτοῦ προσετεκταίνετο καὶ συνύφαινεν, οὐκ ὀλίγοις χρώμενος οὐδὲ φαύλοις τοῦ μύθου συναγωνισταῖς, οἳ τήν τε φήμην τῆς γενέσεως τοῦ παιδὸς εἰς πίστιν ἀνυπόπτως προῆγον, ἄλλον τε λόγον ἐκ Δελφῶν ἀντικομίσαντες εἰς τὴν Σπάρτην κατέβαλον καὶ διέσπειραν, ὡς ἐν γράμμασιν ἀπορρήτοις ὑπὸ τῶν ἱερέων φυλάττοιντο παμπάλαιοι δή τινες χρησμοί, καὶ λαβεῖν οὐκ ἔξεστι τούτους οὐδ’ ἐντυχεῖν θεμιτόν, εἰ μή τις ἄρα γεγονὼς ἐξ Ἀπόλλωνος ἀφίκοιτο τῷ πολλῷ χρόνῳ καὶ σύνθημα τοῖς φυλάττουσι τῆς γενέσεως γνώριμον παρασχὼν κομίσαιτο τὰς δέλτους ἐν αἷς ἦσαν οἱ χρησμοί. τούτων δὲ προκατεσκευασμένων ἔδει τὸν Σειληνὸν ἐλθόντα τοὺς χρησμοὺς ἀπαιτεῖν ὡς Ἀπόλλωνος παῖδα, τοὺς δὲ συμπράττοντας τῶν ἱερέων ἐξακριβοῦν ἕκαστα καὶ διαπυνθάνεσθαι περὶ τῆς γενέσεως, τέλος δὲ πεπεισμένους δῆθεν ὡς Ἀπόλλωνος υἱῷ δεῖξαι τὰ γράμματα, τὸν δὲ ἀναγνῶναι πολλῶν παρόντων ἄλλας τε μαντείας καὶ ἧς ἕνεκα τἄλλα πέπλασται τὴν περὶ τῆς βασιλείας, ὡς ἄμεινον εἴη καὶ λώϊον Σπαρτιάταις ἐκ τῶν ἀρίστων πολιτῶν αἱρουμένοις τοὺς βασιλέας.", "st": "Lys. 26.1"}, {"sp": "N", "t": "ἤδη δὲ τοῦ Σειληνοῦ μειρακίου γεγονότος καὶ πρὸς τὴν πρᾶξιν ἥκοντος, ἐξέπεσε τοῦ δράματος ὁ Λύσανδρος ἀτολμία· τῶν ὑποκριτῶν καὶ συνεργῶν ἑνός, ὡς ἐπ’ αὐτὸ τὸ ἔργον ἦλθεν, ἀποδειλιάσαντος καὶ ἀναδύντος. οὐ μὴν ἐφωράθη γε τοῦ Λυσάνδρου ζῶντος οὐθέν, ἀλλὰ μετὰ τὴν τελευτήν.", "st": "Lys. 26.4"}, {"sp": "N", "t": "ἐτελεύτησε δὲ πρὶν ἐξ Ἀσίας ἐπανελθεῖν τὸν Ἀγησίλαον, ἐμπεσὼν εἰς τὸν Βοιωτικὸν πόλεμον, ἢ μᾶλλον ἐμβαλὼν τὴν Ἑλλάδα. λέγεται γὰρ ἀμφοτέρως· καὶ τὴν αἰτίαν οἱ μέν τινες ἐκείνου ποιοῦσιν, οἱ δὲ Θηβαίων, οἱ δὲ κοινήν, Θηβαίοις μὲν ἐγκαλοῦντες τὴν ἐν Αὐλίδι τῶν ἱερῶν διάρριψιν καὶ ὅτι τῶν περὶ Ἀνδροκλείδην καὶ Ἀμφίθεον χρήμασι βασιλικοῖς διαφθαρέντων ἐπὶ τῷ Λακεδαιμονίοις Ἑλληνικὸν περιστῆσαι πόλεμον ἐπέθεντο Φωκεῦσι καὶ τὴν χώραν αὐτῶν ἐπόρθησαν, Λύσανδρον δέ φασιν ὀργῇ φέρειν ὅτι τῆς δεκάτης ἀντεποιήσαντο τοῦ πολέμου Θηβαῖοι μόνοι, τῶν ἄλλων συμμάχων ἡσυχαζόντων, καὶ περὶ χρημάτων ἠγανάκτησαν ἃ Λύσανδρος εἰς Σπάρτην ἀπέστειλε, μάλιστα δὲ ἐπὶ τῷ παρασχεῖν ἀρχὴν Ἀθηναίοις ἐλευθερώσεως ἀπὸ τῶν τριάκοντα τυράννων, οὓς Λύσανδρος μὲν κατέστησε, Λακεδαιμόνιοι δὲ δύναμιν καὶ φόβον αὐτοῖς προστιθέντες ἐψηφίσαντο τοὺς φεύγοντας ἐξ Ἀθηνῶν ἀγωγίμους εἶναι πανταχόθεν, ἐκσπόνδους δὲ τοὺς ἐνισταμένους τοῖς ἄγουσι. πρὸς ταῦτα γὰρ ἀντεψηφίσαντο Θηβαῖοι ψηφίσματα πρέποντα καὶ ἀδελφὰ ταῖς Ἡρακλέους καὶ Διονύσου πράξεσιν, οἰκίαν μὲν ἀνεῷχθαι πᾶσαν καὶ πόλιν ἐν Βοιωτίᾳ τοῖς δεομένοις Ἀθηναίων, τὸν δὲ τῷ ἀγομένῳ φυγάδι μὴ βοηθήσαντα ζημίαν ὀφείλειν τάλαντον, ἂν δέ τις Ἀθήναζε διὰ τῆς Βοιωτίας ἐπὶ τοὺς τυράννους ὅπλα κομίζῃ, μήτε ὁρᾶν τινα Θηβαῖον μήτε ἀκούειν. καὶ οὐκ ἐψηφίσαντο μὲν οὕτως Ἑλληνικὰ καὶ φιλάνθρωπα, τὰς δὲ πράξεις τοῖς γράμμασιν ὁμοίας οὐ παρέσχον, ἀλλὰ Θρασύβουλος καὶ οἱ σὺν αὐτῷ Φυλὴν καταλαβόντες ἐκ Θηβῶν ὡρμήθησαν, ὅπλα καὶ χρήματα καὶ τὸ λαθεῖν καὶ τὸ ἄρξασθαι Θηβαίων αὐτοῖς συμπαρασκευασάντων. αἰτίας μὲν οὖν ταύτας ἔλαβε κατὰ τῶν Θηβαίων ὁ Λύσανδρος.", "st": "Lys. 27.1"}, {"sp": "N", "t": "ἤδη δὲ παντάπασι χαλεπὸς ὢν ὀργὴν διὰ τὴν μελαγχολίαν ἐπιτείνουσαν εἰς γῆρας, παρώξυνε τοὺς ἐφόρους καὶ συνέπεισε φῆναι φρουρὰν ἐπ’ αὐτούς, καὶ λαβὼν τὴν ἡγεμονίαν ἐξεστράτευσεν. ὕστερον δὲ καὶ Παυσανίαν τὸν βασιλέα μετὰ στρατιᾶς ἀπέστειλαν. ἀλλὰ Παυσανίας μὲν κύκλῳ περιελθὼν διὰ τοῦ Κιθαιρῶνος ἐμβάλλειν ἔμελλεν εἰς τὴν Βοιωτίαν, Λύσανδρος δὲ διὰ Φωκέων ἀπήντα στρατιώτας ἔχων πολλούς· καὶ τὴν μὲν Ὀρχομενίων πόλιν ἑκουσίως προσχωρήσασαν ἔλαβε, τὴν δὲ Λεβάδειαν ἐπελθὼν διεπόρθησεν. ἔπεμψε δὲ τῷ Παυσανίᾳ γράμματα κελεύων εἰς Ἁλίαρτον ἐκ Πλαταιῶν συνάπτειν, ὡς αὐτὸς ἅμ’ ἡμέρᾳ πρὸς τοῖς τείχεσι τῶν Ἁλιαρτίων γενησόμενος. ταῦτα τὰ γράμματα πρὸς τοὺς Θηβαίους ἀπηνέχθη, τοῦ κομίζοντος εἰς κατασκόπους τινὰς ἐμπεσόντος. οἱ δὲ προσβεβοηθηκότων αὐτοῖς Ἀθηναίων τὴν μὲν πόλιν ἐκείνοις διεπίστευσαν, αὐτοὶ δὲ περὶ πρῶτον ὕπνον ἐξορμήσαντες ἔφθασαν ὀλίγῳ τὸν Λύσανδρον ἐν Ἁλιάρτῳ γενόμενοι, καὶ μέρει τινὶ παρῆλθον εἰς τὴν πόλιν. ἐκεῖνος δὲ τὸ μὲν πρῶτον ἔγνω τὴν στρατιὰν ἱδρύσας ἐπὶ λόφου περιμένειν τὸν Παυσανίαν· ἔπειτα προϊούσης τῆς ἡμέρας ἀτρεμεῖν οὐ δυνάμενος, λαβὼν τὰ ὅπλα καὶ τοὺς συμμάχους παρορμήσας ὀρθίῳ τῇ φάλαγγι παρὰ τὴν ὁδὸν ἦγε πρὸς τὸ τεῖχος. τῶν δὲ Θηβαίων οἱ μὲν ἔξω μεμενηκότες ἐν ἀριστερᾷ τὴν πόλιν λαβόντες ἐβάδιζον ἐπὶ τοὺς ἐσχάτους τῶν πολεμίων ὑπὸ τὴν κρήνην τὴν Κισσοῦσαν προσαγορευομένην, ἔνθα μυθολογοῦσι τὰς τιθήνας νήπιον ἐκ τῆς λοχείας ἀπολοῦσαι τὸν Διόνυσον· καὶ γὰρ οἰνωπὸν ἐπιστίλβει τὸ χρῶμα καὶ διαυγὲς καὶ πιεῖν ἥδιστον. οἱ δὲ Κρήσιοι στύρακες οὐ πρόσω περιπεφύκασιν, ἃ τεκμήρια τῆς Ῥαδαμάνθυος αὐτόθι κατοικήσεως Ἁλιάρτιοι ποιοῦνται, καὶ τάφον αὐτοῦ δεικνύουσιν Ἀλεᾶ καλοῦντες. ἔστι δὲ καὶ τὸ τῆς Ἀλκμήνης μνημεῖον ἐγγύς·", "st": "Lys. 28.1"}, {"sp": "N", "t": "ἐνταῦθα γάρ, ὥς φασιν, ἐκηδεύθη συνοικήσασα Ῥαδαμάνθυϊ μετὰ τὴν Ἀμφιτρύωνος τελευτήν.οἱ δὲ ἐν τῇ πόλει Θηβαῖοι μετὰ τῶν Ἁλιαρτίων συντεταγμένοι τέως μὲν ἡσύχαζον, ἐπεὶ δὲ τὸν Λύσανδρον ἅμα τοῖς πρώτοις προσπελάζοντα τῷ τείχει κατεῖδον, ἐξαπίνης ἀνοίξαντες τὰς πύλας καὶ προσπεσόντες αὐτόν τε μετὰ τοῦ μάντεως κατέβαλον καὶ τῶν ἄλλων ὀλίγους τινάς· οἱ γὰρ πλεῖστοι ταχέως ἀνέφυγον πρὸς τὴν φάλαγγα. τῶν δὲ Θηβαίων οὐκ ἀνιέντων, ἀλλὰ προσκειμένων αὐτοῖς, ἐτράποντο πάντες ἀνὰ τοὺς λόφους φεύγειν, καὶ χίλιοι πίπτουσιν αὐτῶν. ἀπέθανον δὲ καὶ Θηβαίων τριακόσιοι πρὸς τὰ τραχέα καὶ καρτερὰ τοῖς πολεμίοις συνεκπεσόντες. οὗτοι δὲ ἦσαν ἐν αἰτίᾳ τοῦ λακωνίζειν, ἣν σπουδάζοντες ἀπολύσασθαι τοῖς πολίταις καὶ σφῶν αὐτῶν ἀφειδοῦντες ἐν τῇ διώξει παραναλώθησαν.", "st": "Lys. 28.6"}, {"sp": "N", "t": "τῷ δὲ Παυσανίᾳ τὸ πάθος ἀγγέλλεται καθ’ ὁδὸν ἐκ Πλαταιῶν εἰς Θεσπιὰς πορευομένῳ· καὶ συνταξάμενος ἧκε πρὸς τὸν Ἁλίαρτον. ἧκε δὲ καὶ Θρασύβουλος ἐκ Θηβῶν ἄγων τοὺς Ἀθηναίους. βουλευομένου δὲ τοῦ Παυσανίου τοὺς νεκροὺς ὑποσπόνδους ἀπαιτεῖν, δυσφοροῦντες οἱ πρεσβύτεροι τῶν Σπαρτιατῶν αὐτοί τε καθ’ ἑαυτοὺς ἠγανάκτουν, καὶ τῷ βασιλεῖ προσιόντες ἐμαρτύραντο μὴ διὰ σπονδῶν ἀναιρεῖσθαι Λύσανδρον, ἀλλὰ δι’ ὅπλων περὶ τοῦ σώματος ἀγωνισαμένους καὶ νικήσαντας οὕτω τὸν ἄνδρα θάπτειν, ἡττωμένοις δὲ καλὸν ἐνταῦθα κεῖσθαι μετὰ τοῦ στρατηγοῦ. ταῦτα τῶν πρεσβυτέρων λεγόντων ὁρῶν ὁ Παυσανίας μέγα μὲν ἔργον ὑπερβαλέσθαι μάχῃ τοὺς Θηβαίους ἄρτι κεκρατηκότας, ἐγγὺς δὲ τῶν τειχῶν τὸ σῶμα τοῦ Λυσάνδρου παραπεπτωκός, ὥστε χαλεπὴν ἄνευ σπονδῶν καὶ νικῶσιν εἶναι τὴν ἀναίρεσιν, ἔπεμψε κήρυκα καὶ σπεισάμενος ἀπήγαγε τὴν δύναμιν ὀπίσω.", "st": "Lys. 29.1"}, {"sp": "N", "t": "τὸν δὲ Λύσανδρον ᾗ πρῶτον κομίζοντες ὑπὲρ τοὺς ὅρους ἐγένοντο τῆς Βοιωτίας ἐν φίλῃ καὶ συμμαχίδι χώρᾳ τῇ Πανοπέων κατέθεσαν, οὗ νῦν τὸ μνημεῖόν ἐστι παρὰ τὴν ὁδὸν εἰς Χαιρώνειαν ἐκ Δελφῶν πορευομένοις.ἐνταῦθα δὴ τῆς στρατιᾶς καταυλισαμένης λέγεταί τινα τῶν Φωκέων ἑτέρῳ μὴ παρατυχόντι τὸν ἀγῶνα διηγούμενον, εἰπεῖν ὡς οἱ πολέμιοι προσπέσοιεν αὐτοῖς τοῦ Λυσάνδρου τὸν Ὁπλίτην ἤδη διαβεβηκότος. θαυμάσαντα δὲ Σπαρτιάτην ἄνδρα τοῦ Λυσάνδρου φίλον ἐρέσθαι τίνα λέγοι τὸν Ὁπλίτην· οὐ γὰρ εἰδέναι τοὔνομα· καὶ μὴν ἐκεῖ γε, φάναι, τοὺς πρώτους ἡμῶν οἱ πολέμιοι κατέβαλον. τὸ γὰρ παρὰ τὴν πόλιν ῥεῖθρον Ὁπλίτην καλοῦσιν. ἀκούσαντα δὲ τὸν Σπαρτιάτην ἐκδακρῦσαι καὶ εἰπεῖν ὡς ἄφευκτόν ἐστιν ἀνθρώπῳ τὸ πεπρωμένον. ἦν γάρ, ὡς ἔοικε, τῷ Λυσάνδρῳ δεδομένος χρησμὸς οὕτως ἔχων·", "st": "Lys. 29.3"}, {"sp": "N", "t": "ὁπλίτην κελάδοντα φυλάξασθαί σε κελεύω<br>γῆς τε δράκονθ’ υἱὸν δόλιον κατόπισθεν ἰόντα.", "st": "Lys. 29.3b"}, {"sp": "N", "t": "τινὲς δὲ τὸν Ὁπλίτην οὐ πρὸς Ἁλιάρτῳ ῥεῖν λέγουσιν, ἀλλὰ πρὸς Κορώνειαν χειμάρρουν εἶναι τῷ Φιλάρῳ ποταμῷ συμφερόμενον παρὰ τὴν πόλιν, ὃν πάλαι μὲν Ὁπλίαν, νῦν δὲ Ἰσόμαντον προσαγορεύουσιν. ὁ δὲ ἀποκτείνας τὸν Λύσανδρον Ἁλιάρτιος ἀνὴρ ὄνομα Νεόχωρος ἐπίσημον εἶχε τῆς ἀσπίδος δράκοντα· καὶ τοῦτο σημαίνειν ὁ χρησμὸς εἰκάζετο. λέγεται δὲ καὶ Θηβαίοις ὑπὸ τὸν Πελοποννησιακὸν πόλεμον ἐν Ἰσμηνίῳ γενέσθαι χρησμὸν ἅμα τήν τε πρὸς Δηλίῳ μάχην καὶ τὴν πρὸς Ἁλιάρτῳ ταύτην ἐκείνης ὕστερον ἔτει τριακοστῷ γενομένην προμηνύοντα. ἦν δὲ τοιοῦτος·", "st": "Lys. 29.6"}, {"sp": "N", "t": "ἐσχατιὰν πεφύλαξο λύκους καμάκεσσι δοκεύων<br>καὶ λόφον Ὀρχαλίδην, ὃν ἀλώπηξ οὔποτε λείπει.", "st": "Lys. 29.6b"}, {"sp": "N", "t": "τὸν μὲν οὖν περὶ Δήλιον τόπον ἐσχατιὰν προσεῖπε, καθ’ ὃν ἡ Βοιωτία τῇ Ἀττικῇ σύνορός ἐστιν, Ὀρχαλίδην δὲ λόφον, ὃν νῦν Ἀλώπεκον καλοῦσιν, ἐν τοῖς πρὸς τὸν Ἑλικῶνα μέρεσι τοῦ Ἁλιάρτου κείμενον.", "st": "Lys. 29.6c"}, {"sp": "N", "t": "τοιαύτης δὲ τῷ Λυσάνδρῳ τῆς τελευτῆς γενομένης παραχρῆμα μὲν οὕτως ἤνεγκαν οἱ Σπαρτιᾶται βαρέως, ὥστε τῷ βασιλεῖ κρίσιν προγράψαι θανατικήν· ἣν οὐχ ὑποστὰς ἐκεῖνος εἰς Τεγέαν ἔφυγε, κἀκεῖ κατεβίωσεν ἱκέτης ἐν τῷ τεμένει τῆς Ἀθηνᾶς. καὶ γὰρ ἡ πενία τοῦ Λυσάνδρου τελευτήσαντος ἐκκαλυφθεῖσα φανερωτέραν ἐποίησε τὴν ἀρετήν, ἀπὸ χρημάτων πολλῶν καὶ δυνάμεως θεραπείας τε πόλεων καὶ βασιλέως τοσαύτης μηδὲ μικρὸν ἐπιλαμπρύναντος τὸν οἶκον εἰς χρημάτων λόγον, ὡς ἱστορεῖ Θεόπομπος, ᾧ μᾶλλον ἐπαινοῦντι πιστεύσειεν ἄν τις ἢ ψέγοντι, ψέγει γὰρ ἥδιον ἢ ἐπαινεῖ. χρόνῳ δὲ ὕστερον Ἔφορός φησιν ἀντιλογίας τινὸς συμμαχικῆς ἐν Σπάρτῃ γενομένης, καὶ τὰ γράμματα διασκέψασθαι δεῆσαν ἃ παρ’ ἑαυτῷ κατέσχεν ὁ Λύσανδρος, ἐλθεῖν ἐπὶ τὴν οἰκίαν τὸν Ἀγησίλαον. εὑρόντα δὲ τὸ βιβλίον ἐν ᾧ γεγραμμένος ἦν ὁ περὶ τῆς πολιτείας λόγος, ὡς χρὴ τῶν Εὐρυπωντιδῶν καὶ Ἀγιαδῶν τὴν βασιλείαν ἀφελομένους εἰς μέσον θεῖναι καὶ ποιεῖσθαι τὴν αἵρεσιν ἐκ τῶν ἀρίστων, ὁρμῆσαι μὲν εἰς τοὺς πολίτας τὸν λόγον ἐξενεγκεῖν καὶ παραδεικνύναι τὸν Λύσανδρον, οἷος ὢν πολίτης διαλάθοι, Λακρατίδαν δέ, ἄνδρα φρόνιμον καὶ τότε προεστῶτα τῶν ἐφόρων, ἐπιλαβέσθαι τοῦ Ἀγησιλάου, καὶ εἰπεῖν ὡς δεῖ μὴ ἀνορύττειν τὸν Λύσανδρον, ἀλλὰ καὶ τὸν λόγον αὐτῷ συγκατορύττειν οὕτω συντεταγμένον πιθανῶς καὶ πανούργως.", "st": "Lys. 30.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τάς τε ἄλλας τιμὰς ἀπέδοσαν αὐτῷ τελευτήσαντι, καὶ τοὺς μνηστευσαμένους τὰς θυγατέρας, εἶτα μετὰ τὴν τελευτὴν τοῦ Λυσάνδρου πένητος εὑρεθέντος ἀπειπαμένους ἐζημίωσαν, ὅτι πλούσιον μὲν νομίζοντες ἐθεράπευον, δίκαιον δὲ καὶ χρηστὸν ἐκ τῆς πενίας ἐπιγνόντες ἐγκατέλιπον. ἦν γάρ, ὡς ἔοικεν, ἐν Σπάρτῃ καὶ ἀγαμίου δίκη καὶ ὀψιγαμίου καὶ κακογαμίου· ταύτῃ δὲ ὑπῆγον μάλιστα τοὺς ἀντὶ τῶν ἀγαθῶν καὶ οἰκείων τοῖς πλουσίοις κηδεύοντας. τὰ μὲν οὖν περὶ Λύσανδρον οὕτως ἱστορήσαμεν ἔχοντα.", "st": "Lys. 30.5"}, {"sp": "HDR", "t": "Σύλλας"}, {"sp": "N", "t": "Λεύκιος δὲ Κορνήλιος Σύλλας γένει μὲν ἦν ἐκ πατρικίων, οὓς εὐπατρίδας ἄν τις εἴποι, τῶν δὲ προγόνων αὐτοῦ λέγουσι Ῥουφῖνον ὑπατεῦσαι, καὶ τούτῳ δὲ τῆς τιμῆς ἐπιφανεστέραν γενέσθαι τὴν ἀτιμίαν. εὑρέθη γὰρ ἀργυρίου κοίλου κεκτημένος ὑπὲρ δέκα λίτρας, τοῦ νόμου μὴ διδόντος· ἐπὶ τούτῳ δὲ τῆς βουλῆς ἐξέπεσεν. οἱ δὲ μετ’ ἐκεῖνον ἤδη ταπεινὰ πράττοντες διετέλεσαν, αὐτός τε Σύλλας ἐν οὐκ ἀφθόνοις ἐτράφη τοῖς πατρῴοις. γενόμενος δὲ μειράκιον ᾤκει παρ’ ἑτέροις ἐνοίκιον οὐ πολὺ τελῶν, ὡς ὕστερον ὠνειδίζετο παρ’ ἀξίαν εὐτυχεῖν δοκῶν, σεμνυνομένῳ μὲν γὰρ αὐτῷ καὶ μεγαληγοροῦντι μετὰ τὴν ἐν Λιβύῃ στρατείαν λέγεταί τις εἰπεῖν τῶν καλῶν τε κἀγαθῶν ἀνδρῶν, καὶ πῶς ἂν εἴης σὺ χρηστός, ὃς τοῦ πατρός σοι μηδὲν καταλιπόντος τοσαῦτα κέκτησαι· καὶ γὰρ οὐκ ἔτι τῶν βίων ἐν ἤθεσιν ὀρθίοις καὶ καθαροῖς μενόντων, ἀλλ’ ἐγκεκλικότων καὶ παραδεδεγμένων τρυφῆς καὶ πολυτελείας ζῆλον, εἰς ἴσον ὅμως ὄνειδος ἐτίθεντο τοὺς ὑπάρχουσαν εὐπορίαν ἀπολέσαντας καὶ τοὺς πενίαν πατρῴαν μὴ διαφυλάξαντας. ὕστερον δὲ ἤδη κρατοῦντος αὐτοῦ καὶ πολλοὺς ἀποκτιννύντος, ἀπελευθερικὸς ἄνθρωπος, δοκῶν κρύπτειν ἕνα τῶν προγεγραμμένων καὶ κατακρημνίζεσθαι διὰ τοῦτο μέλλων, ὠνείδισε τὸν Σύλλαν ὅτι πολὺν χρόνον ἐν μιᾷ συνοικίᾳ διῃτῶντο, φέροντες ἐνοίκιον αὐτός μὲν τῶν ἄνω δισχιλίους νούμμους, ἐκεῖνος δὲ τῶν ὑποκάτω τρισχιλίους, ὥστε τῆς τύχης αὐτῶν τὸ μεταξὺ χιλίους εἶναι νούμμους, οἳ πεντήκοντα καὶ διακοσίας δραχμὰς Ἀττικὰς δύνανται, ταῦτα μὲν οὖν ἱστοροῦσι περὶ τῆς παλαιᾶς τοῦ Σύλλα τύχης.", "st": "Sull. 1.1"}, {"sp": "N", "t": "τοῦ δὲ σώματος αὐτοῦ τὸ μὲν ἄλλο εἶδος ἐπὶ τῶν ἀνδριάντων φαίνεται, τὴν δὲ τῶν ὀμμάτων γλαυκότητα δεινῶς πικρὰν καὶ ἄκρατον οὖσαν ἡ χρόα τοῦ προσώπου φοβερωτέραν ἐποίει προσιδεῖν. ἐξήνθει γὰρ τὸ ἐρύθημα τραχὺ καὶ σποράδην καταμεμιγμένον τῇ λευκότητι· πρὸς ὃ καὶ τοὔνομα λέγουσιν αὐτῷ γενέσθαι τῆς χρόας ἐπίθετον, καὶ τῶν Ἀθήνησι γεφυριστῶν ἐπέσκωψέ τις εἰς τοῦτο ποιήσας·", "st": "Sull. 2.1"}, {"sp": "N", "t": "συκάμινόν ἐσθ’ ὁ Σύλλας ἀλφίτῳ πεπασμένον.", "st": "Sull. 2.1b"}, {"sp": "N", "t": "τοῖς δὲ τοιούτοις τῶν τεκμηρίων οὐκ ἄτοπόν ἐστι χρῆσθαι περὶ ἀνδρός, ὃν οὕτω φιλοσκώμμονα φύσει γεγονέναι λέγουσιν, ὥστε νέον μὲν ὄντα καὶ ἄδοξον ἔτι μετὰ μίμων καὶ γελωτοποιῶν διαιτᾶσθαι καὶ συνακολασταίνειν, ἐπεὶ δὲ κύριος ἁπάντων κατέστη, συναγαγόντα τῶν ἀπὸ σκηνῆς καὶ θεάτρου τοὺς ἰταμωτάτους ὁσημέραι πίνειν καὶ διαπληκτίζεσθαι τοῖς σκώμμασι, τοῦ τε γήρως ἀωρότερα πράττειν δοκοῦντα καὶ πρὸς τῷ καταισχύνειν τὸ ἀξίωμα τῆς ἀρχῆς πολλὰ τῶν δεομένων ἐπιμελείας προϊέμενον. οὐ γὰρ ἦν τῷ Σύλλᾳ περὶ δεῖπνον ὄντι χρήσασθαι σπουδαῖον οὐδέν, ἀλλ’ ἐνεργὸς ὢν καὶ σκυθρωπότερος παρὰ τὸν ἄλλον χρόνον, ἀθρόαν ἐλάμβανε μεταβολὴν ὁπότε πρῶτον ἑαυτὸν εἰς συνουσίαν καταβάλοι καὶ πότον, ὥστε μιμῳδοῖς καὶ ὀρχησταῖς τιθασὸς εἶναι καὶ πρὸς πᾶσαν ἔντευξιν ὑποχείριος καὶ κατάντης. ταύτης δὲ τῆς ἀνέσεως ἔοικε γεγονέναι νόσημα καὶ ἡ πρὸς τοὺς ἔρωτας εὐχέρεια καὶ ῥύσις αὐτοῦ τῆς φιληδονίας, ἧς οὐδὲ γηράσας ἐπαύσατο, Μητροβίου δὲ τῶν ἀπὸ σκηνῆς τινος ἐρῶν διετέλεσεν ἔτι νέος ὤν. καὶ συνήντησεν αὐτῷ τὸ τοιοῦτον ἀρξάμενος γὰρ ἐρᾶν κοινῆς μέν, εὐπόρου δὲ γυναικός, ὄνομα Νικοπόλεως, καὶ διὰ συνήθειαν καὶ χάριν, ἣν ἀφ’ ὥρας εἶχεν, εἰς ἐρωμένου σχῆμα περιελθών, ἀπελείφθη κληρονόμος ὑπὸ τῆς ἀνθρώπου τελευτώσης. ἐκληρονόμησε δὲ καὶ τὴν μητρυιάν, ἀγαπηθεὶς ὥσπερ υἱὸς ὑπ’ αὐτῆς· καὶ μετρίως μὲν ἀπὸ τούτων εὐπόρησεν.", "st": "Sull. 2.2"}, {"sp": "N", "t": "ἀποδειχθεὶς δὲ ταμίας ὑπατεύοντι Μαρίῳ τὴν πρώτην ὑπατείαν, συνεξέπλευσεν εἰς Λιβύην πολεμήσων Ἰογόρθαν. γενόμενος δὲ ἐπὶ στρατοπέδου τά τε ἄλλα παρεῖχεν ἑαυτὸν εὐδόκιμον, καὶ καιρῷ παραπεσόντι χρησάμενος εὖ φίλον ἐποιήσατο τὸν τῶν Νομάδων βασιλέα Βόκχον. πρεσβευτὰς γὰρ αὐτοῦ λῃστήριον Νομαδικὸν ἐκφυγόντας ὑποδεξάμενος καὶ φιλοφρονηθείς, δῶρα καὶ πομπὴν ἀσφαλῆ παρασχὼν ἀπέστειλεν. ὁ δὲ Βόκχος ἐτύγχανε μὲν ἔτι γε πάλαι γαμβρὸν ὄντα μισῶν καὶ φοβούμενος τὸν Ἰογόρθαν, τότε δὲ ἡττημένῳ καὶ πεφευγότι πρὸς αὐτὸν ἐπιβουλεύων ἐκάλει τὸν Σύλλαν, δι’ ἐκείνου μάλιστα βουλόμενος τὴν σύλληψιν καὶ παράδοσιν τοῦ Ἰογόρθα γενέσθαι ἢ δι’ αὑτοῦ, κοινωσάμενος δὲ τῷ Μαρίῳ καὶ λαβὼν στρατιώτας ὀλίγους ὁ Σύλλας τὸν μέγιστον ὑπέδυ κίνδυνον, ὅτι βαρβάρῳ καὶ πρὸς τοὺς οἰκειοτάτους ἀπίστῳ πιστεύσας, ὑπὲρ τοῦ παραλαβεῖν ἕτερον ἑαυτὸν ἐνεχείρισεν. οὐ μὴν ἀλλὰ ὁ Βόκχος ἀμφοτέρων κύριος γενόμενος, καὶ καταστήσας ἑαυτὸν εἰς ἀνάγκην τοῦ παρασπονδῆσαι τὸν ἕτερον, καὶ πολλὰ διενεχθεὶς τῇ γνώμῃ, τέλος ἐκύρωσε τὴν πρώτην προδοσίαν καὶ παρέδωκε τῷ Σύλλᾳ τὸν Ἰογόρθαν. ὁ μὲν οὖν θριαμβεύων ἐπὶ τούτῳ Μάριος ἦν, ἡ δὲ δόξα τοῦ κατορθώματος, ἣν ὁ Μαρίου φθόνος Σύλλᾳ προσετίθει, παρελύπει τὸν Μάριον ἡσυχῇ. καὶ γὰρ αὐτὸς ὁ Σύλλας φύσει τε μεγάλαυχος ὢν καὶ τότε πρῶτον ἐκ βίου ταπεινοῦ καὶ ἀγνῶτος ἔν τινι λόγῳ γεγονὼς παρὰ τοῖς πολίταις, καὶ τοῦ τιμᾶσθαι γευόμενος, εἰς τοῦτο φιλοτιμίας προῆλθεν ὥστε γλυψάμενος ἐν δακτυλίῳ φορεῖν εἰκόνα τῆς πράξεως, καὶ ταύτῃ γε χρώμενος ἀεὶ διετέλεσεν. ἦν δὲ ἡ γραφὴ Βόκχος μὲν παραδιδούς, Σύλλας δὲ παραλαμβάνων τὸν Ἰογόρθαν.", "st": "Sull. 3.1"}, {"sp": "N", "t": "ἠνία μὲν οὖν ταῦτα τὸν Μάριον· ἔτι δὲ ἡγούμενος ἐλάττονα τοῦ φθονεῖσθαι τὸν Σύλλαν, ἐχρῆτο πρὸς τὰς στρατείας, τὸ μὲν δεύτερον ὑπατεύων πρεσβευτῇ, τὸ δὲ τρίτον χιλιάρχῳ, καὶ πολλὰ δι’ ἐκείνου τῶν χρησίμων κατωρθοῦτο. πρεσβεύων τε γὰρ ἡγεμόνα Τεκτοσάγων Κόπιλλον εἷλε, καὶ χιλιαρχῶν μέγα καὶ πολυάνθρωπον ἔθνος Μαρσοὺς ἔπεισε φίλους γενέσθαι καὶ συμμάχους Ῥωμαίων, ἐκ δὲ τούτων τὸν Μάριον αἰσθόμενος ἀχθόμενον αὐτῷ καὶ μηκέτι προϊέμενον ἡδέως πράξεων ἀφορμάς, ἀλλὰ ἐνιστάμενον τῇ αὐξήσει, Κάτλῳ, τῷ συνάρχοντι τοῦ Μαρίου, προσένειμεν ἑαυτόν, ἀνδρὶ χρηστῷ μέν, ἀμβλυτέρῳ δὲ πρὸς τοὺς ἀγῶνας, ὑφ’ οὗ τὰ πρῶτα καὶ μέγιστα πιστευόμενος εἰς δύναμιν ἅμα δόξῃ προῄει. καὶ πολέμῳ μὲν αἱρεῖ πολὺ μέρος τῶν ἐν ταῖς Ἄλπεσι βαρβάρων, ἐπιλιπούσης δὲ τῆς ἀγορᾶς ἀναδεξάμενος τὴν ἐπιμέλειαν τοσαύτην ἐποίησε περιουσίαν, ὥστε τῶν Κάτλου στρατιωτῶν ἐν ἀφθόνοις διαγόντων καὶ τοῖς Μαρίου προσπαρασχεῖν. ἐφ’ ᾧ φησιν αὐτὸς ἰσχυρῶς ἀνιᾶσαι τὸν Μάριον. ἡ μὲν οὖν ἔχθρα βραχεῖαν οὕτω καὶ μειρακιώδη λαβοῦσα τὴν πρώτην ὑπόθεσιν καὶ ἀρχήν, εἶτα χωροῦσα δι’ αἵματος ἐμφυλίου καὶ στάσεων ἀνηκέστων ἐπὶ τυραννίδα καὶ σύγχυσιν ἁπάντων πραγμάτων, ἀπέδειξε τὸν Εὐριπίδην σοφὸν ἄνδρα καὶ πολιτικῶν ἐπιστήμονα νοσημάτων, διακελευσάμενον φυλάττεσθαι τὴν φιλοτιμίαν ὡς ὀλεθριωτάτην καὶ κακίστην δαίμονα τοῖς χρωμένοις.", "st": "Sull. 4.1"}, {"sp": "N", "t": "ὁ δὲ Σύλλας οἰόμενος αὑτῷ τὴν ἀπὸ τῶν πολεμικῶν δόξαν ἐπὶ τὰς πολιτικὰς πράξεις διαρκεῖν, καὶ δοὺς ἑαυτὸν ἀπὸ τῆς στρατείας εὐθὺς ἐπὶ τὴν τοῦ δήμου πρᾶξιν, ἐπὶ στρατηγίαν πολιτικὴν ἀπεγράψατο καὶ διεψεύσθη· τὴν δ’ αἰτίαν τοῖς ὄχλοις ἀνατίθησι. φησὶ γὰρ αὐτοὺς τὴν πρὸς Βόκχον εἰδότας φιλίαν, καὶ προσδεχομένους, εἰ πρὸ τῆς στρατηγίας ἀγορανομοίη, κυνηγέσια λαμπρὰ καὶ Λιβυκῶν θηρίων ἀγῶνας, ἑτέρους ἀποδεῖξαι στρατηγοὺς ὡς αὐτὸν ἀγορανομεῖν ἀναγκάσοντας. ἔοικε δὲ τὴν ἀληθῆ τῆς ἀποτεύξεως αἰτίαν οὐχ ὁμολογῶν ὁ Σύλλας ἐλέγχεσθαι τοῖς πράγμασιν. ἐνιαυτῷ γὰρ κατόπιν ἔτυχε τῆς στρατηγίας, τοῦ δήμου τὸ μέν τι θεραπείᾳ, τὸ δὲ καὶ χρήμασι προσαγαγόμενος. διὸ δὴ καὶ στρατηγοῦντος αὐτοῦ, καὶ πρὸς Καίσαρα μετ’ ὀργῆς εἰπόντος ὡς χρήσεται τῇ ἰδίᾳ πρὸς αὐτὸν ἐξουσίᾳ, γελάσας ὁ Καῖσαρ, ὀρθῶς, ἔφη, τὴν ἀρχὴν ἰδίαν νομίζεις· ἔχεις γὰρ αὐτὴν πριάμενος.", "st": "Sull. 5.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν στρατηγίαν εἰς τὴν Καππαδοκίαν ἀποστέλλεται, τὸν μέν ἐμφανῆ λόγον ἔχων πρὸς τὴν στρατείαν Ἀριοβαρζάνην καταγαγεῖν, αἰτίαν δὲ ἀληθῆ Μιθριδάτην ἐπισχεῖν πολυπραγμονοῦντα καὶ περιβαλλόμενον ἀρχὴν καὶ δύναμιν οὐκ ἐλάττονα τῆς ὑπαρχούσης. ἰδίαν μέν οὖν δύναμιν οὐ πολλὴν ἐπήγετο, χρησάμενος δὲ τοῖς συμμάχοις προθύμοις, καὶ πολλοὺς μέν αὐτῶν Καππαδοκῶν, πλείονας δ’ αὖθις Ἀρμενίων προσβοηθοῦντας ἀποκτείνας, Γόρδιον μέν ἐξήλασεν, Ἀριοβαρζάνην δὲ ἀπέδειξε βασιλέα.", "st": "Sull. 5.3"}, {"sp": "N", "t": "διατρίβοντι δὲ αὐτῷ παρὰ τὸν Εὐφράτην ἐντυγχάνει Πάρθος Ὀρόβαζος, Ἀρσάκου βασιλέως πρεσβευτής, οὔπω πρότερον ἀλλήλοις ἐπιμεμιγμένων τῶν γενῶν· ἀλλὰ καὶ τοῦτο τῆς μεγάλης δοκεῖ Σύλλα τύχης γενέσθαι, τὸ πρώτῳ Ῥωμαίων ἐκείνῳ Πάρθους συμμαχίας καὶ φιλίας δεομένους διὰ λόγων ἐλθεῖν. ὅτε καὶ λέγεται τρεῖς δίφρους προθέμενος, τὸν μέν Ἀριοβαρζάνῃ, τὸν δὲ Ὀροβάζῳ, τὸν δὲ αὐτῷ, μέσος ἀμφοῖν καθεζόμενος χρηματίζειν. ἐφ’ ᾧ τὸν μέν Ὀρόβαζον ὕστερον ὁ τῶν Πάρθων βασιλεὺς ἀπέκτεινε, τὸν δὲ Σύλλαν οἱ μέν ἐπῄνεσαν ἐντρυφήσαντα τοῖς βαρβάροις, οἱ δὲ ὡς φορτικὸν ᾐτιάσαντο καὶ ἀκαίρως φιλότιμον. ἱστορεῖται δέ τις ἀνὴρ τῶν μετὰ Ὀροβάζου καταβεβηκότων, Χαλδαῖος, εἰς τὸ τοῦ Σύλλα πρόσωπον ἀπιδὼν καὶ ταῖς κινήσεσι τῆς τε διανοίας καὶ τοῦ σώματος οὐ παρέργως ἐπιστήσας, ἀλλὰ πρὸς τὰς τῆς τέχνης ὑποθέσεις τὴν φύσιν ἐπισκεψάμενος, εἰπεῖν ὡς ἀναγκαῖον εἴη τοῦτον τὸν ἄνδρα μέγιστον γενέσθαι, θαυμάζειν δὲ καὶ νῦν πῶς ἀνέχεται μὴ πρῶτος ὢν ἁπάντων, ἀναχωρήσαντι δὲ αὐτῷ δίκην ἔλαχε δώρων Κηνσωρῖνος, ὡς πολλὰ χρήματα συνειλοχότι παρὰ τὸν νόμον ἐκ φίλης καὶ συμμάχου βασιλείας, οὐ μὴν ἀπήντησεν ἐπὶ τὴν κρίσιν, ἀλλ’ ἀπέστη τῆς κατηγορίας.", "st": "Sull. 5.4"}, {"sp": "N", "t": "ἡ μέντοι πρὸς Μάριον αὐτῷ στάσις ἀνερριπίζετο καινὴν ὑπόθεσιν λαβοῦσα τὴν Βόκχου φιλοτιμίαν, ὃς τόν τε δῆμον ἅμα θεραπεύων ἐν Ῥώμῃ καὶ τῷ Σύλλᾳ χαριζόμενος ἀνέθηκε εἰκόνας ἐν Καπιτωλίῳ τροπαιοφόρους καὶ παρ’ αὐταῖς χρυσοῦν Ἰογόρθαν ὑφ’ ἑαυτοῦ Σύλλᾳ παραδιδόμενον. ἐφ’ ᾧ τοῦ Μαρίου βαρυθυμουμένου καὶ καθαιρεῖν ἐπιχειροῦντος, ἑτέρων δὲ ἀμύνειν τῷ Σύλλᾳ, καὶ τῆς πόλεως ὅσον οὔπω διακεκαυμένης ὑπ’ ἀμφοῖν, ὁ συμμαχικὸς πόλεμος πάλαι τυφόμενος ἐπὶ τὴν πόλιν ἀναλάμψας τότε τὴν στάσιν ἐπέσχεν. ἐν τούτῳ, μεγίστῳ καὶ ποικιλωτάτῳ γενομένῳ καὶ πλεῖστα κακὰ καὶ βαρυτάτους παρασχόντι κινδύνους Ῥωμαίοις, Μάριος μὲν οὐδὲν ἀποδεῖξαι μέγα δυνηθεὶς ἤλεγχε τὴν πολεμικὴν ἀρετὴν ἀκμῆς καὶ ῥώμης δεομένην, Σύλλας δὲ πολλὰ δράσας ἄξια λόγου δόξαν ἔσχεν ἡγεμόνος μεγάλου μὲν παρὰ τοῖς πολίταις, μεγίστου δὲ παρὰ τοῖς φίλοις, εὐτυχεστάτου δὲ καὶ παρὰ τοῖς ἐχθροῖς.", "st": "Sull. 6.1"}, {"sp": "N", "t": "ἀλλ’ οὐκ ἔπαθε ταὐτὸ Τιμοθέῳ τῷ τοῦ Κόνωνος, ὅς, εἰς τὴν τύχην αὐτοῦ τὰ κατορθώματα τῶν ἐχθρῶν τιθεμένων καὶ γραφόντων ἐν πίναξι; κοιμώμενον ἐκεῖνον, τὴν δὲ Τύχην δικτύῳ τὰς πόλεις περιβάλλουσαν, ἀγροικιζόμενος καὶ χαλεπαίνων πρὸς τοὺς ταῦτα ποιοῦντας ὡς ἀποστερούμενος ὑπ’ αὐτῶν τῆς ἐπὶ ταῖς πράξεσι δόξης, ἔφη ποτὲ πρὸς τόν δῆμον, ἐπανήκων ἐκ στρατείας εὖ κεχωρηκέναι δοκούσης, ἀλλὰ ταύτης γε τῆς στρατείας οὐδέν, ἄνδρες Ἀθηναῖοι, τῇ τύχῃ μέτεστι. πρὸς Τιμόθεον μὲν οὖν φασιν οὕτω φανέντα φιλότιμον ἀντιμειρακιεύεσθαι τὸ δαιμόνιον, ὥστε μηδὲν ἔτι πρᾶξαι λαμπρόν, ἀλλὰ ὅλως ἀποτυγχάνοντα ταῖς πράξεσι καὶ προσκρούοντα τῷ δήμῳ τέλος ἐκπεσεῖν τῆς πόλεως· Σύλλας δὲ οὐ μόνον ἡδέως προσιέμενος τόν τοιοῦτον εὐδαιμονισμὸν καὶ ζῆλον, ἀλλὰ καὶ συναύξων καὶ συνεπιθειάζων τὰ πραττόμενα, τῆς τύχης ἐξῆπτεν, εἴτε κόμπῳ χρώμενος εἴθ’ οὕτως ἔχων τῇ δόξῃ πρὸς τὸ θεῖον. καὶ γὰρ ἐν τοῖς ὑπομνήμασι γέγραφεν ὅτι τῶν καλῶς αὐτῷ βεβουλεῦσθαι δοκούντων αἱ μὴ κατὰ γνώμην, ἀλλὰ πρὸς καιρὸν ἀποτολμώμεναι πράξεις ἔπιπτον εἰς ἄμεινον.", "st": "Sull. 6.3"}, {"sp": "N", "t": "ἔτι δὲ καὶ δι’ ὧν φησι πρὸς τύχην εὖ πεφυκέναι μᾶλλον ἢ πρὸς πόλεμον, τῇ τύχῃ τῆς ἀρετῆς πλέον ἔοικε νέμειν καὶ ὅλως ἑαυτὸν τοῦ δαίμονος ποιεῖν, ὅς γε καὶ τῆς πρὸς Μέτελλον ὁμονοίας, ἰσότιμον ἄνδρα καὶ κηδεστήν, εὐτυχίαν τινὰ θείαν αἰτιᾶται· πολλὰ γὰρ αὐτῷ πράγματα παρέξειν ἐπίδοξον ὄντα πρᾳότατον ἐν τῇ κοινωνίᾳ γενέσθαι τῆς ἀρχῆς. ἔτι δὲ Λευκόλλῳ μὲν ἐν τοῖς ὑπομνήμασιν, ὧν ἐκείνῳ τὴν γραφὴν ἀνατέθεικε, παραινεῖ μηδὲν οὕτως ἡγεῖσθαι βέβαιον ὡς ὅ τι ἂν αὐτῷ προστάξῃ νύκτωρ τὸ δαιμόνιον, ἐκπεμπομένου δὲ αὐτοῦ μετὰ δυνάμεως εἰς τὸν συμμαχικὸν πόλεμον ἱστορεῖ χάσμα τῆς γῆς μέγα γενέσθαι περὶ Λαβέρνην· ἐκ δὲ τούτου πῦρ ἀναβλῦσαι πολὺ καὶ φλόγα λαμπρὰν στηρίσαι πρὸς τόν οὐρανόν. εἰπεῖν δὴ καὶ τοὺς μάντεις ὡς ἀνὴρ ἀγαθὸς ὄψει διάφορος καὶ περιττὸς ἄρξας ἀπαλλάξει τῇ πόλει ταραχὰς τὰς παρούσας, τοῦτον δὲ αὑτὸν εἶναι φησιν ὁ Σύλλας· τῆς μὲν γὰρ ὄψεως ἴδιον εἶναι τὸ περὶ τὴν κόμην χρυσωπόν, ἀρετὴν δὲ οὐκ αἰσχύνεσθαι μαρτυρῶν ἑαυτῷ μετὰ πράξεις καλὰς οὕτω καὶ μεγάλας. ταῦτα μὲν οὖν περὶ τῆς θειότητος.", "st": "Sull. 6.6"}, {"sp": "N", "t": "τὸν δὲ ἄλλον τρόπον ἀνώμαλός τις ἔοικε γεγονέναι καὶ διάφορος πρὸς ἑαυτόν, ἀφελέσθαι πολλά, χαρίσασθαι πλείονα, τιμῆσαι παραλόγως, παραλόγως ἐφυβρίσαι, θεραπεύειν ὧν δέοιτο, θρύπτεσθαι πρὸς τοὺς δεομένους, ὥστε ἀγνοεῖσθαι πότερον ὑπερόπτης φύσει μᾶλλον ἢ κόλαξ γέγονε. τὴν μὲν γὰρ ἐν ταῖς τιμωρίαις ἀνωμαλίαν, ἐξ ὧν ἔτυχεν αἰτιῶν ἀποτυμπανίζοντος αὐτοῦ καὶ πάλιν τὰ μέγιστα τῶν ἀδικημάτων πρᾴως φέροντος, καὶ διαλλαττομένου μὲν ἐπὶ τοῖς ἀνηκέστοις μετὰ εὐκολίας, τὰ δὲ μικρὰ καὶ φαῦλα προσκρούσματα σφαγαῖς καὶ δημεύσεσιν οὐσιῶν μετιόντος, οὕτως ἄν τις διαιτήσειεν ὡς φύσει μὲν ὀργὴν χαλεπὸν ὄντα καὶ τιμωρητικόν, ὑφιέμενον δὲ τῆς πικρίας λογισμῷ πρὸς τὸ συμφέρον. ἐν αὐτῷ γε τούτῳ τῷ συμμαχικῷ πολέμῳ τῶν στρατιωτῶν αὐτοῦ στρατηγικὸν ἄνδρα πρεσβευτήν, Ἀλβῖνον ὄνομα, ξύλοις καὶ λίθοις διαχρησαμένων, παρῆλθε καὶ οὐκ ἐπεξῆλθεν ἀδίκημα τοσοῦτον, ἀλλὰ καὶ σεμνυνόμενος διεδίδου λόγον ὡς προθυμοτέροις διὰ τοῦτο χρήσοιτο πρὸς τόν πόλεμον αὐτοῖς ἰωμένοις τὸ ἁμάρτημα δι’ ἀνδραγαθίας. τῶν δ’ ἐγκαλούντων οὐδὲν ἐφρόντιζεν, ἀλλὰ ἤδη καταλῦσαι Μάριον διανοούμενος καὶ τοῦ πρὸς τοὺς συμμάχους πολέμου τέλος ἔχειν δοκοῦντος ἀποδειχθῆναι στρατηγὸς ἐπὶ Μιθριδάτην, ἐθεράπευε τὴν ὑφ’ ἑαυτῷ στρατιάν.", "st": "Sull. 6.8"}, {"sp": "N", "t": "καὶ παρελθὼν εἰς τὴν πόλιν ὕπατος μὲν ἀποδείκνυται μετὰ Κοΐντου Πομπηΐου, πεντήκοντα ἔτη γεγονώς, γαμεῖ δὲ γάμον ἐνδοξότατον Καικιλίαν τὴν Μετέλλου θυγατέρα τοῦ ἀρχιερέως. ἐφ’ ᾧ πολλὰ μὲν εἰς αὑτὸν ᾖδον οἱ δημοτικοί, πολλοὶ δὲ τῶν πρώτων ἐν ἐνεμέσων, οὐκ ἄξιον ἡγούμενοι τῆς γυναικὸς ὃν ἄξιον ὑπατείας ἔκριναν, ὥς φησιν ὁ Τίτος, οὐ μόνην δὲ ταύτην ἔγημεν, ἀλλὰ πρώτην μὲν ἔτι μειράκιον ὢν Ἰλίαν ἔσχε τὴν καὶ θυγάτριον αὐτῷ τεκοῦσαν, εἶτα μετ’ ἐκείνην Αἰλίαν τρίτην δὲ Κλοιλίαν, ἣν ἀπεπέμψατο μὲν ὡς στεῖραν ἐντίμως καὶ μετ’ εὐφημίας καὶ δῶρα προσθείς, ὀλίγαις δὲ ὕστερον ἡμέραις ἀγαγόμενος τὴν Μετέλλαν ἔδοξε διὰ τοῦτο τὴν Κλοιλίαν οὐ καλῶς αἰτιάσασθαι. τὴν μέντοι Μετέλλαν ἐν πᾶσι θεραπεύων διετέλεσεν, ὥστε καὶ τόν Ῥωμαίων δῆμον, ὅτε τοὺς περὶ Μάριον φυγάδας ἐπεθύμει καταγαγεῖν, ἀρνουμένου τοῦ Σύλλᾳ, δεόμενον ἐπιβοήσασθαι τὴν Μετέλλαν. ἐδόκει δὲ καὶ τοῖς Ἀθηναίοις ἑλὼν τὸ ἄστυ προσενεχθῆναι τραχύτερον, ὅτι τὴν Μετέλλαν ἀπὸ τοῦ τείχους γεφυρίζοντες ἐλοιδόρησαν. ἀλλὰ ταῦτα μὲν ὕστερον.", "st": "Sull. 6.10"}, {"sp": "N", "t": "τότε δὲ τὴν ὑπατείαν πρὸς τὰ μέλλοντα μικρὸν ἡγούμενος, ἐπτόητο τῇ γνώμῃ πρὸς τὸν Μιθριδατικὸν πόλεμον. ἀντανίστατο δὲ αὐτῷ Μάριος ὑπὸ δοξομανίας καὶ φιλοτιμίας, ἀγηράτων παθῶν, ἀνὴρ τῷ τε σώματι βαρὺς καὶ ταῖς ἔναγχος ἀπειρηκὼς στρατείαις διὰ γῆρας ἐκδήμων καὶ διαποντίων πολέμων ἐφιέμενος. καὶ τοῦ Σύλλα πρὸς τὰς ἐπιλιπεῖς πράξεις ὁρμήσαντος εἰς τὸ στρατόπεδον, αὐτὸς οἰκουρῶν ἐτεκταίνετο τὴν ὀλεθριωτάτην ἐκείνην καὶ ὅσα σύμπαντες οἱ πόλεμοι τὴν Ῥώμην οὐκ ἔβλαψαν ἀπεργασαμένην στάσιν, ὡς καὶ τὸ δαιμόνιον αὐτοῖς προεσήμηνε. πῦρ μὲν γὰρ αὐτόματον ἐκ τῶν τὰ σημεῖα δοράτων ὑποφερόντων ἀνέλαμψε καὶ κατεσβέσθη μόλις, κόρακες δὲ τρεῖς τοὺς νεοσσοὺς εἰς τὴν ὁδὸν προαγαγόντες κατέφαγον, τὰ δὲ λείψανα πάλιν εἰς τὴν νεοσσιὰν ἀνήνεγκαν. καὶ μυῶν δὲ ἐν ἱερῷ χρυσὸν ἀνακείμενον διαφαγόντων μίαν οἱ ζάκοροι πάγῃ θήλειαν λαμβάνουσιν, ἡ δὲ ἐν αὐτῇ τῇ πάγῃ τεκοῦσα πέντε κατανάλωσε τὰ τρία.", "st": "Sull. 7.1"}, {"sp": "N", "t": "τὸ δὲ πάντων μέγιστον, ἐξ ἀνεφέλου καὶ διαίθρου τοῦ περιέχοντος ἤχησε φωνὴ σάλπιγγος ὀξὺν ἀποτείνουσα καὶ θρηνώδη φθόγγον, ὥστε πάντας ἔκφρονας γενέσθαι καὶ καταπτῆξαι διὰ τὸ μέγεθος. Τυρρηνῶν δὲ οἱ λόγιοι μεταβολὴν ἑτέρου γένους ἀπεφαίνοντο καὶ μετακόσμησιν ἀποσημαίνειν τὸ τέρας. εἶναι μὲν γὰρ ὀκτὼ τὰ σύμπαντα γένη, διαφέροντα τοῖς βίοις καὶ τοῖς ἤθεσιν ἀλλήλων, ἑκάστῳ δὲ ἀφωρίσθαι χρόνων ἀριθμὸν ὑπὸ τοῦ θεοῦ συμπεραινόμενον ἐνιαυτοῦ μεγάλου περιόδῳ. καὶ ὅταν αὕτη σχῇ τέλος, ἑτέρας ἐνισταμένης κινεῖσθαί τι σημεῖον ἐκ γῆς ἢ οὐρανοῦ θαυμάσιον, ὡς δῆλον εἶναι τοῖς πεφροντικόσι τὰ τοιαῦτα καὶ μεμαθηκόσιν εὐθὺς ὅτι καὶ τρόποις ἄλλοις καὶ βίοις ἄνθρωποι χρώμενοι γεγόνασι, καὶ θεοῖς ἧττον ἢ μᾶλλον τῶν προτέρων μέλοντες. τά τε γὰρ ἄλλα φασὶν ἐν τῇ τῶν γενῶν ἀμείψει λαμβάνειν μεγάλας καινοτομίας, καὶ τὴν μαντικὴν ποτὲ μὲν αὔξεσθαι τῇ τιμῇ καὶ κατατυγχάνειν ταῖς προαγορεύσεσι, καθαρὰ καὶ φανερὰ σημεῖα τοῦ δαιμονίου προπέμποντος, αὖθις δ’ ἐν ἑτέρῳ γένει ταπεινὰ πράττειν, αὐτοσχέδιον οὖσαν τὰ πολλὰ καὶ δι’ ἀμυδρῶν καὶ σκοτεινῶν ὀργάνων τοῦ μέλλοντος ἁπτομένην.", "st": "Sull. 7.4"}, {"sp": "N", "t": "ταῦτα μὲν οὖν οἱ λογιώτατοι Τυρρηνῶν καὶ πλέον τι τῶν ἄλλων εἰδέναι δοκοῦντες ἐμυθολόγουν. τῆς δὲ συγκλήτου τοῖς μάντεσι περὶ τούτων σχολαζούσης καὶ καθημένης ἐν τῷ ναῷ τῆς Ἐνυοῦς, στρουθὸς εἰσέπτη πάντων ὁρώντων τέττιγα φέρων τῷ στόματι, καὶ τὸ μὲν ἐκβαλὼν μέρος αὐτοῦ κατέλιπε, τὸ δὲ ἔχων ἀπῆλθεν. ὑφεωρῶντο δὴ στάσιν οἱ τερατοσκόποι καὶ διαφορὰν τῶν κτηματικῶν πρὸς τὸν ἀστικὸν ὄχλον καὶ ἀγοραῖον φωνάεντα γὰρ τοῦτον εἶναι καθάπερ τέττιγα, τοὺς δὲ χωρίτας ἀρουραίους.", "st": "Sull. 7.6"}, {"sp": "N", "t": "Μάριος δὴ προσλαμβάνει δημαρχοῦντα Σουλπίκιον, ἄνθρωπον οὐδενὸς δεύτερον ἐν ταῖς ἄκραις κακίαις, ὥστε μὴ ζητεῖν τίνος ἐστὶν ἑτέρου μοχθηρότερος, ἀλλὰ πρὸς τί μοχθηρότατος ἑαυτοῦ, καὶ γὰρ ὠμότης καὶ τόλμα καὶ πλεονεξία περὶ αὐτὸν ἦν ἀπερίσκεπτος αἰσχροῦ καὶ παντὸς κακοῦ, ὅς γε τὴν Ῥωμαίων πολιτείαν ἐξελευθερικοῖς καὶ μετοίκοις πωλῶν ἀναφανδὸν ἠρίθμει τιμὴν διὰ τραπέζης ἐν ἀγορᾷ κειμένης. ἔτρεφε δὲ τρισχιλίους μαχαιροφόρους, καὶ πλῆθος ἱππικῶν νεανίσκων πρὸς ἅπαν ἑτοίμων περὶ αὑτὸν εἶχεν, οὓς ἀντισύγκλητον ὠνόμαζε. νόμον δὲ κυρώσας μηδένα συγκλητικὸν ὑπὲρ δισχιλίας δραχμὰς ὀφείλειν, αὐτὸς ἀπέλιπε μετὰ τὴν τελευτὴν ὀφλήματος μυριάδας τριακοσίας. οὗτος εἰς τὸν δῆμον ἀφεθεὶς ὑπὸ τοῦ Μαρίου, καὶ συνταράξας πάντα τὰ πράγματα βίᾳ καὶ σιδήρῳ, νόμους ἔγραφεν ἄλλους τε μοχθηροὺς καὶ τὸν διδόντα Μαρίῳ τοῦ Μιθριδατικοῦ πολέμου τὴν ἡγεμονίαν. ἀπραξίας δὲ διὰ ταῦτα τῶν ὑπάτων ψηφισαμένων, ἐπαγαγὼν αὐτοῖς ἐκκλησιάζουσι περὶ τὸν νεὼν τῶν Διοσκούρων ὄχλον ἄλλους τε πολλοὺς καὶ τὸ Πομπηΐου τοῦ ὑπάτου μειράκιον ἐπὶ τῆς ἀγορᾶς ἀνεῖλεν· αὐτὸς δὲ Πομπήϊος λαθὼν ἐξέφυγε. Σύλλας δὲ εἰς τὴν οἰκίαν τοῦ Μαρίου συνδιωχθεὶς ἠναγκάσθη προελθὼν τὰς ἀπραξίας λῦσαι· καὶ διὰ τοῦτο τὸν Πομπήϊον ἐπάρχοντα παύσας ὁ Σουλπίκιος οὐκ ἀφείλετο τοῦ Σύλλα τὴν ὑπατείαν, ἀλλὰ τὴν ἐπὶ Μιθριδάτην στρατείαν μόνον εἰς Μάριον μετήνεγκε· καὶ πέμπει χιλιάρχους εὐθὺς εἰς Νῶλαν παραληψομένους τὸ στράτευμα καὶ πρὸς τὸν Μάριον ἄξοντας.", "st": "Sull. 8.1"}, {"sp": "N", "t": "φθάσαντος δὲ τοῦ Σύλλα διαφυγεῖν εἰς τὸ στρατόπεδον, καὶ τῶν στρατιωτῶν, ὡς ἐπύθοντο ταῦτα, καταλευσάντων τοὺς χιλιάρχους, οἱ περὶ τὸν Μάριον αὖθις ἐν τῇ πόλει τοὺς Σύλλα φίλους ἀνῄρουν καὶ χρήματα διήρπαζον αὐτῶν, ἦσαν δὲ μεταστάσεις καὶ φυγαί, τῶν μὲν εἰς πόλιν ἀπὸ στρατοπέδου, τῶν δ’ ἐκεῖσε διαφοιτώντων ἐκ τῆς πόλεως. ἡ δὲ σύγκλητος ἦν μὲν οὐχ αὑτῆς, ἀλλὰ τοῖς Μαρίου καὶ Σουλπικίου διῳκεῖτο προστάγμασι, πυθομένη δὲ τὸν Σύλλαν ἐπὶ τὴν πόλιν ἐλαύνειν ἔπεμψε δύο τῶν στρατηγῶν, Βροῦτον καὶ Σερουΐλιον, ἀπαγορεύσοντας αὐτῷ βαδίζειν. τούτους θρασύτερον Σύλλᾳ διαλεχθέντας ὥρμησαν μὲν ἀνελεῖν οἱ στρατιῶται, τὰς δὲ ῥάβδους κατέκλασαν καὶ τὰς περιπορφύρους ἀφείλοντο καὶ πολλὰ περιυβρισμένους ἀπέπεμψαν, αὐτόθεν τε δεινὴν κατήφειαν, ὁρωμένους τῶν στρατηγικῶν παρασήμων ἐρήμους, καὶ τὴν στάσιν οὐκέτι καθεκτήν, ἀλλ’ ἀνήκεστον ἀπαγγέλλοντας.", "st": "Sull. 9.1"}, {"sp": "N", "t": "οἱ μὲν οὖν περὶ τὸν Μάριον ἐν παρασκευαῖς ἦσαν· ὁ δὲ Σύλλας ἄγων ἓξ τάγματα τέλεια μετὰ τοῦ συνάρχοντος ἀπὸ Νώλης ἐκίνει, τὸν μὲν στρατὸν ὁρῶν πρόθυμον ὄντα χωρεῖν εὐθὺς ἐπὶ τὴν πόλιν, ἐνδοιάζων δὲ τῇ γνώμῃ παρ’ ἑαυτῷ καὶ δεδοικὼς τὸν κίνδυνον. ὁ δὲ μάντις Ποστούμιος θύσαντος αὐτοῦ καταμαθὼν τὰ σημεῖα, καὶ τὰς χεῖρας ἀμφοτέρας τῷ Σύλλᾳ προτείνας, ἠξίου δεθῆναι καὶ φυλάττεσθαι μέχρι τῆς μάχης, ὡς, εἰ μὴ πάντα ταχὺ καὶ καλῶς αὐτῷ συντελεσθείη, τὴν ἐσχάτην δίκην ὑποσχεῖν βουλόμενος. λέγεται δὲ καὶ κατὰ τοὺς ὕπνους αὑτῷ Σύλλᾳ φανῆναι θεὸν ἣν τιμῶσι Ῥωμαῖοι παρὰ Καππαδοκῶν μαθόντες, εἴτε δὴ Σελήνην οὖσαν εἴτε Ἀθηνᾶν εἴτε Ἐνυώ. ταύτην ὁ Σύλλας ἔδοξεν ἐπιστᾶσαν ἐγχειρίσαι κεραυνὸν αὑτῷ, καὶ τῶν ἐχθρῶν ἕκαστον ὀνομάζουσαν τῶν ἐκείνου βάλλειν κελεῦσαι, τοὺς δὲ πίπτειν βαλλομένους καὶ ἀφανίζεσθαι. θαρσήσας δὲ τῇ ὄψει καὶ φράσας τῷ συνάρχοντι μεθ’ ἡμέραν ἐπὶ τὴν Ῥώμην ἡγεῖτο.", "st": "Sull. 9.3"}, {"sp": "N", "t": "καὶ περὶ Πικτὰς αὐτῷ πρεσβείας ἐντυχούσης καὶ δεομένης μὴ βαδίζειν εὐθὺς ἐξ ἐφόδου, πάντα γὰρ ἔσεσθαι τὰ δίκαια τῆς βουλῆς ψηφισαμένης, ὡμολόγησε μὲν αὐτοῦ καταστρατοπεδεύσειν καὶ διαμετρεῖν ἐκέλευε χώρας, ὥσπερ εἰώθει, τῷ στρατοπέδῳ τοὺς ἡγεμόνας, ὥστε τοὺς πρέσβεις ἀπελθεῖν πιστεύσαντας· ἐκείνων δὲ ἀπελθόντων εὐθὺς ἐκπέμψας Λεύκιον Βάσιλλον καὶ Γάϊον Μόμμιον καταλαμβάνει τὴν πύλην δι’ αὐτῶν καὶ τὰ τείχη τὰ περὶ τὸν λόφον τὸν Αἰσκυλῖνον· εἶτ’ αὐτὸς ἁπάσῃ σπουδῇ συνῆπτε. τῶν δὲ περὶ τὸν Βάσιλλον εἰς τὴν πόλιν ἐμπεσόντων καὶ κρατούντων, ὁ πολὺς καὶ ἄνοπλος δῆμος ἀπὸ τῶν τεγῶν κεράμῳ καὶ λίθῳ βάλλοντες ἐπέσχον αὐτοὺς τοῦ πρόσω χωρεῖν καὶ συνέστειλαν εἰς τὸ τεῖχος, ἐν τούτῳ δὲ ὁ Σύλλας παρῆν ἤδη, καὶ συνιδὼν τὸ γινόμενον ἐβόα τὰς οἰκίας ὑφάπτειν, καὶ λαβὼν δᾷδα καιομένην ἐχώρει πρῶτος αὐτός, καὶ τοὺς τοξότας ἐκέλευε χρῆσθαι τοῖς πυροβόλοις ἄνω τῶν στεγασμάτων ἐφιεμένους, κατ’ οὐδένα λογισμόν, ἀλλ’ ἐμπαθὴς ὢν καὶ τῷ θυμῷ παραδεδωκὼς τὴν τῶν πρασσομένων ἡγεμονίαν, ὅς γε τοὺς ἐχθροὺς μόνον ἑώρα, φίλους δὲ καὶ συγγενεῖς καὶ οἰκείους εἰς οὐδένα λόγον θέμενος οὐδ’ οἶκτον κατῄει διὰ πυρός, ᾧ τῶν αἰτίων καὶ μὴ διάγνωσις οὐκ ἦν. τούτων δὲ γινομένων Μάριος ἐξωσθεὶς πρὸς τὸ τῆς Γῆς ἱερὸν ἐκάλει διὰ κηρύγματος ἐπ’ ἐλευθερίᾳ τὸ οἰκετικόν ἐπελθόντων δὲ τῶν πολεμίων κρατηθεὶς ἐξέπεσε τῆς πόλεως.", "st": "Sull. 9.5"}, {"sp": "N", "t": "Σύλλας δὲ τὴν βουλὴν συναγαγὼν καταψηφίζεται θάνατον αὐτοῦ τε Μαρίου καὶ ὀλίγων ἄλλων, ἐν οἷς Σουλπίκιος ἦν ὁ δήμαρχος, ἀλλὰ Σουλπίκιος μέν ἀπεσφάγη προδοθεὶς ὑπὸ θεράποντος, ὃν ὁ Σύλλας ἠλευθέρωσεν, εἶτα κατεκρήμνισε, Μαρίῳ δ’ ἐπεκήρυξεν ἀργύριον, οὐκ εὐγνωμόνως οὐδὲ πολιτικῶς, ᾧ γε μικρὸν ἔμπροσθεν ὑποχείριον εἰς τὴν οἰκίαν δοὺς ἑαυτὸν ἀσφαλῶς ἀφείθη. καίτοι Μαρίῳ τότε μὴ διέντι Σύλλαν, ἀλλ’ ἀποθανεῖν ὑπὸ Σουλπικίου προεμένῳ, πάντων κρατεῖν ὑπῆρχεν, ἀλλ’ ὅμως ἐφείσατο καὶ μεθ’ ἡμέρας ὀλίγας τὴν αὐτὴν λαβὴν παρασχὼν οὐκ ἔτυχε τῶν ὁμοίων. ἐφ’ οἷς ὁ Σύλλας τὴν μέν σύγκλητον ἀδήλως ἠνίασεν ἡ δὲ παρὰ τοῦ δήμου δυσμένεια καὶ νέμεσις αὐτῷ φανερὰ δι’ ἔργων ἀπήντα. Νώνιον μέν γε τὸν ἀδελφιδοῦν αὐτοῦ καὶ Σερουήϊον ἀρχὰς μετιόντας ἀποψηφισάμενοι καὶ καθυβρίσαντες ἑτέρους κατέστησαν ἄρχοντας, οὓς μάλιστα τιμῶντες ᾤοντο λυπεῖν ἐκεῖνον, ὁ δὲ τούτοις τε προσεποιεῖτο χαίρειν, ὡς τοῦ δήμου τῷ ποιεῖν ἃ βούλοιτο δι’ αὐτὸν ἀπολαύοντος τῆς ἐλευθερίας, καὶ θεραπεύων τὸ τῶν πολλῶν μῖσος ὕπατον κατέστησεν ἀπὸ τῆς ἐναντίας στάσεως Λεύκιον Κίνναν, ἀραῖς καὶ ὅρκοις καταλαβὼν εὐνοήσειν τοῖς ἑαυτοῦ πράγμασιν. ὁ δὲ ἀναβὰς εἰς τὸ Καπιτώλιον ἔχων ἐν τῇ χειρὶ λίθον ὤμνυεν, εἶτα ἐπαρασάμενος ἑαυτῷ μὴ φυλάττοντι τὴν πρὸς ἐκεῖνον εὔνοιαν ἐκπεσεῖν τῆς πόλεως, ὥσπερ ὁ λίθος διὰ τῆς χειρός, κατέβαλε χαμᾶζε τὸν λίθον οὐκ ὀλίγων παρόντων, παραλαβὼν δὲ τὴν ἀρχὴν εὐθὺς ἐπεχείρει τὰ καθεστῶτα κινεῖν, καὶ δίκην ἐπὶ τὸν Σύλλαν παρεσκεύασε καὶ κατηγορεῖν ἐπέστησεν Οὐεργίνιον, ἕνα τῶν δημάρχων, ὃν ἐκεῖνος ἅμα τῷ δικαστηρίῳ χαίρειν ἐάσας ἐπὶ Μιθριδάτην ἀπῆρε.", "st": "Sull. 10.1"}, {"sp": "N", "t": "λέγεται δὲ ὑπὸ τάς ἡμέρας ἐκείνας ἐν αἷς ὁ Σύλλας ἀπὸ τῆς Ἰταλίας ἐκίνει τὸν στόλον, ἄλλα τε πολλὰ Μιθριδάτῃ διατρίβοντι περὶ τὸ Πέργαμον ἐπισκῆψαι δαιμόνια, καὶ Νίκην στεφανηφόρον καθιεμένην ὑπὸ τῶν Περγαμηνῶν ἐπ’ αὐτὸν ἔκ τινων ὀργάνων ἄνωθεν ὅσον οὔπω τῆς κεφαλῆς ψαύουσαν συντριβῆναι, καὶ τὸν στέφανον ἐκπεσόντα κατὰ τοῦ θεάτρου φέρεσθαι χαμᾶζε διαθρυπτόμενον, ὥστε φρίκην μὲν τῷ δήμῳ, ἀθυμίαν δὲ πολλὴν Μιθριδάτῃ παρασχεῖν, καίπερ αὐτῷ τότε τῶν πραγμάτων ἐλπίδος πέρα προχωρούντων. αὐτὸς μὲν γὰρ Ἀσίαν τε Ῥωμαίων καὶ Βιθυνίαν καὶ Καππαδοκίαν τῶν βασιλέων ἀφῃρημένος ἐν Περγάμῳ καθῆστο, πλούτους καὶ δυναστείας καὶ τυραννίδας διανέμων τοῖς φίλοις, τῶν δὲ παίδων ὁ μὲν ἐν Πόντῳ καὶ Βοσπόρῳ τὴν παλαιὰν ἄχρι τῶν ὑπὲρ τὴν Μαιῶτιν ἀοικήτων ἀρχὴν κατεῖχεν οὐδενὸς παρενοχλοῦντος, Ἀριαράθης δὲ Θρᾴκην καὶ Μακεδονίαν ἐπῄει στρατῷ μεγάλῳ προσαγόμενος, ἄλλους δὲ οἱ στρατηγοὶ τόπους ἐχειροῦντο δυνάμεις ἔχοντες, ὧν ὁ μέγιστος Ἀρχέλαος ταῖς μὲν ναυσὶν ὁμοῦ τι συμπάσης ἐπικρατῶν τῆς θαλάττης τάς τε Κυκλάδας νήσους ἐδουλοῦτο καὶ τῶν ἄλλων ὅσαι Μαλέας ἐντὸς ἵδρυνται, καὶ τὴν Εὔβοιαν αὐτὴν εἶχεν, ἐκ δὲ Ἀθηνῶν ὁρμώμενος τὰ μέχρι Θετταλίας ἔθνη τῆς Ἑλλάδος ἀφίστη, μικρὰ προσκρούσας περὶ Χαιρώνειαν. ἐνταῦθα γὰρ αὐτῷ Βρέττιος Σούρρας ἀπήντησε, πρεσβευτὴς μὲν ὢν Σεντίου, τοῦ στρατηγοῦ τῆς Μακεδονίας, ἀνὴρ δὲ τόλμῃ καὶ φρονήσει διαφέρων, οὗτος Ἀρχελάῳ δίκην ῥεύματος φερομένῳ διὰ τῆς Βοιωτίας ἐπὶ πλεῖστον ἀντιστάς, καὶ τρισὶ μάχαις διαγωνισάμενος περὶ Χαιρώνειαν, ἐξέωσε καὶ συνέστειλε πάλιν ἐπὶ τὴν θάλατταν. Λευκίου δὲ Λευκόλλου κελεύσαντος αὐτὸν ὑποχωρεῖν ἐπιόντι Σύλλᾳ καὶ τὸν ἐψηφισμένον ἐκείνῳ ἐᾶν πόλεμον, εὐθὺς ἐκλιπὼν τὴν Βοιωτίαν ὀπίσω πρὸς Σέντιον ἀπήλαυνε, καίπερ αὐτῷ τῶν πραγμάτων ἐλπίδος πέρα προχωρούντων καὶ τῆς Ἑλλάδος οἰκείως ἐχούσης πρὸς μεταβολὴν διὰ τὴν ἐκείνου καλοκἀγαθίαν. ἀλλὰ γὰρ Βρεττίῳ μὲν ταῦτα λαμπρότατα τῶν πεπραγμένων.", "st": "Sull. 11.1"}, {"sp": "N", "t": "Σύλλας δὲ τὰς μὲν ἄλλας πόλεις εὐθὺς εἶχεν ἐπιπρεσβευομένας καὶ καλούσας, ταῖς δὲ Ἀθήναις διὰ τὸν τύραννον Ἀριστίωνα βασιλεύεσθαι ἠναγκασμέναις ἄθρους ἐπέστη καὶ τὸν Πειραιᾶ περιλαβὼν ἐπολιόρκει, μηχανήν τε πᾶσαν ἐφιστὰς καὶ μάχας παντοδαπὰς ποιούμενος. καίτοι χρόνον οὐ πολὺν ἀνασχομένῳ παρῆν ἀκινδύνως ἑλεῖν τὴν ἄνω πόλιν, ὑπὸ λιμοῦ συνηγμένην ἤδη τῇ χρείᾳ τῶν ἀναγκαίων εἰς τὸν ἔσχατον καιρόν ἀλλ’ ἐπειγόμενος εἰς Ῥώμην καὶ δεδιὼς τὸν ἐκεῖ νεωτερισμόν, πολλοῖς μὲν κινδύνοις, πολλαῖς δὲ μάχαις, μεγάλαις δὲ δαπάναις κατέσπευδε τὸν πόλεμον, ᾧ γε δίχα τῆς ἄλλης παρασκευῆς ἡ περὶ τὰ μηχανήματα πραγματεία ζεύγεσι μυρίοις ὀρικοῖς ἐχορηγεῖτο, καθ’ ἡμέραν ἐνεργοῖς οὖσι πρὸς τήν ὑπηρεσίαν. ἐπιλειπούσης δὲ τῆς ὕλης διὰ τὸ κόπτεσθαι πολλὰ τῶν ἔργων περικλώμενα τοῖς αὑτῶν βρίθεσι καὶ πυρπολεῖσθαι βαλλόμενα συνεχῶς ὑπὸ τῶν πολεμίων, ἐπεχείρησε τοῖς ἱεροῖς ἄλσεσι, καὶ τήν τε Ἀκαδήμειαν ἔκειρε δενδροφορωτάτην προαστείων οὖσαν καὶ τὸ Λύκειον. ἐπεὶ δὲ καὶ χρημάτων ἔδει πολλῶν πρὸς τὸν πόλεμον, ἐκίνει τὰ τῆς Ἑλλάδος ἄσυλα, τοῦτο μὲν ἐξ Ἐπιδαύρου, τοῦτο δὲ ἐξ Ὀλυμπίας, τὰ κάλλιστα καὶ πολυτελέστατα τῶν ἀναθημάτων μεταπεμπόμενος. ἔγραψε δὲ καὶ τοῖς Ἀμφικτύοσιν εἰς Δελφοὺς ὅτι τὰ χρήματα τοῦ θεοῦ βέλτιον εἴη κομισθῆναι πρὸς αὐτόν ἢ γὰρ φυλάξειν ἀσφαλέστερον ἢ καὶ ἀποχρησάμενος ἀποδώσειν οὐκ ἐλάττω· καὶ τῶν φίλων ἀπέστειλε Κάφιν τὸν Φωκέα κελεύσας σταθμῷ παραλαβεῖν ἕκαστον. ὁ δὲ Κάφις ἧκε μὲν εἰς Δελφούς, ὤκνει δὲ τῶν ἱερῶν θιγεῖν, καὶ πολλὰ τῶν Ἀμφικτυόνων παρόντων ἀπεδάκρυσε τήν ἀνάγκην. ἐνίων δὲ φασκόντων ἀκοῦσαι φθεγγομένης τῆς ἐν τοῖς ἀνακτόροις κιθάρας, εἴτε πιστεύσας εἴτε τὸν Σύλλαν βουλόμενος ἐμβαλεῖν εἰς δεισιδαιμονίαν, ἐπέστειλε πρὸς αὐτόν, ὁ δὲ σκώπτων ἀντέγραψε θαυμάζειν τὸν Κάφιν, εἰ μὴ συνίησιν ὅτι χαίροντος, οὐ χαλεπαίνοντος, εἴη τὸ ᾅδειν· ὥστε θαρροῦντα λαμβάνειν ἐκέλευσεν, ὡς ἡδομένου τοῦ θεοῦ καὶ διδόντος.", "st": "Sull. 12.1"}, {"sp": "N", "t": "τὰ μὲν οὖν ἄλλα διέλαθε τούς γε πολλοὺς Ἕλληνας ἐκπεμπόμενα, τὸν δὲ ἀργυροῦν πίθον, ὃς ἦν ὑπόλοιπος ἔτι τῶν βασιλικῶν, διὰ βάρος καὶ μέγεθος οὐ δυναμένων ἀναλαβεῖν τῶν ὑποζυγίων, ἀναγκαζόμενοι κατακόπτειν οἱ Ἀμφικτύονες εἰς μνήμην ἐβάλοντο τοῦτο μὲν Τίτον Φλαμινῖνον καὶ Μάνιον Ἀκύλιον, τοῦτο δὲ Αἰμίλιον Παῦλον, ὧν ὁ μὲν Ἀντίοχον ἐξελάσας τῆς Ἑλλάδος, οἱ δὲ τούς Μακεδόνων βασιλεῖς καταπολεμήσαντες οὐ μόνον ἀπέσχοντο τῶν ἱερῶν τῶν Ἑλληνικῶν, ἀλλὰ καὶ δῶρα καὶ τιμὴν αὐτοῖς καὶ σεμνότητα πολλὴν προσέθεσαν. ἀλλ’ ἐκεῖνοι μὲν ἀνδρῶν τε σωφρόνων καὶ μεμαθηκότων σιωπῇ τοῖς ἄρχουσι παρέχειν τὰς χεῖρας ἡγούμενοι κατὰ νόμον, αὐτοί τε ταῖς ψυχαῖς βασιλικοὶ καὶ ταῖς δαπάναις εὐτελεῖς ὄντες, μετρίοις ἐχρῶντο καὶ τεταγμένοις ἀναλώμασι, τὸ κολακεύειν τούς στρατιώτας αἴσχιον ἡγούμενοι τοῦ δεδιέναι τούς πολεμίους· οἱ δὲ τότε στρατηγοὶ βίᾳ τὸ πρωτεῖον, οὐκ ἀρετῇ, κτώμενοι, καὶ μᾶλλον ἐπ’ ἀλλήλους δεόμενοι τῶν ὅπλων ἢ τούς πολεμίους, ἠναγκάζοντο δημαγωγεῖν ἐν τῷ στρατηγεῖν, εἶθ’ ὧν εἰς τὰς ἡδυπαθείας τοῖς στρατευομένοις ἀνήλισκον ὠνούμενοι τούς πόνους αὑτῶν, ἔλαθον ὤνιον ὅλην τήν πατρίδα ποιήσαντες ἑαυτούς τε δούλους τῶν κακίστων ἐπὶ τῷ τῶν βελτιόνων ἄρχειν. ταῦτα ἐξήλαυνε Μάριον, εἶτ’ αὖθις ἐπὶ Σύλλαν κατῆγε, ταῦτα Ὀκταουΐου τούς περὶ Κίνναν, ταῦτα Φλάκκου τούς περὶ Φιμβρίαν αὐτόχειρας ἐποίησεν. ὧν οὐχ ἥκιστα Σύλλας ἐνέδωκεν ἀρχάς, ἐπὶ τῷ διαφθείρειν καὶ μετακαλεῖν τούς ὑπ’ ἄλλοις ταττομένους καταχορηγῶν εἰς τούς ὑφ’ αὑτῷ καὶ δαπανώμενος, ὥστε ἅμα τούς ἄλλους μὲν εἰς προδοσίαν, τούς δὲ ὑφ’ αὑτῷ εἰς ἀσωτίαν διαφθείρων χρημάτων δεῖσθαι πολλῶν, καὶ μάλιστα πρὸς τὴν πολιορκίαν ἐκείνην.", "st": "Sull. 12.6"}, {"sp": "N", "t": "δεινὸς γάρ τις ἄρα καὶ ἀπαραίτητος εἶχεν αὐτὸν ἔρως ἑλεῖν τὰς Ἀθήνας, εἴτε ζήλῳ τινὶ πρὸς τὴν πάλαι σκιαμαχοῦντα τῆς πόλεως δόξαν, εἴτε θυμῷ τὰ σκώμματα φέροντα καὶ τὰς βωμολοχίας, αἷς αὐτόν τε καὶ τὴν Μετέλλαν ἀπὸ τῶν τειχῶν ἑκάστοτε γεφυρίζων καὶ κατορχούμενος ἐξηρέθιζεν ὁ τύραννος Ἀριστίων, ἄνθρωπος ἐξ ἀσελγείας ὁμοῦ καὶ ὠμότητος ἔχων συγκειμένην τὴν ψυχήν, καὶ τὰ χείριστα τῶν Μιθριδατικῶν συνερρυηκότα νοσημάτων καὶ παθῶν εἰς ἑαυτὸν ἀνειληφώς, καὶ τῇ πόλει μυρίους μὲν πολέμους, πολλὰς δὲ τυραννίδας καὶ στάσεις διαπεφευγυίᾳ πρότερον ὥσπερ νόσημα θανατηφόρον εἰς τοὺς ἐσχάτους καιροὺς ἐπιτιθέμενος· ὅς, χιλίων δραχμῶν ὠνίου τοῦ μεδίμνου τῶν πυρῶν ὄντος ἐν ἄστει τότε, τῶν ἀνθρώπων σιτουμένων τὸ περὶ τὴν ἀκρόπολιν φυόμενον παρθένιον, ὑποδήματα δὲ καὶ ληκύθους ἑφθὰς ἐσθιόντων, αὐτὸς ἐνδελεχῶς πότοις μεθημερινοῖς καὶ κώμοις χρώμενος καὶ πυρριχίζων καὶ γελωτοποιῶν πρὸς τοὺς πολεμίους τὸν μὲν ἱερὸν τῆς θεοῦ λύχνον ἀπεσβηκότα διὰ σπάνιν ἐλαίου περιεῖδε, τῇ δὲ ἱεροφάντιδι πυρῶν ἡμίεκτον προσαιτούσῃ πεπέρεως ἔπεμψε, τοὺς δὲ βουλευτὰς καὶ ἱερεῖς ἱκετεύοντας οἰκτεῖραι τὴν πόλιν καὶ διαλύσασθαι πρὸς Σύλλαν τοξεύμασι βάλλων διεσκέδασεν. ὀψὲ δὲ ἤδη που μόλις ἐξέπεμψεν ὑπὲρ εἰρήνης δύο ἢ τρεῖς τῶν συμποτῶν πρὸς οὓς οὐδὲν ἀξιοῦντας σωτήριον, ἀλλὰ τὸν Θησέα καὶ τὸν Εὔμολπον καὶ τὰ Μηδικὰ σεμνολογουμένους ὁ Σύλλας· ἄπιτε, εἶπεν, ὦ μακάριοι, τοὺς λόγους τούτους ἀναλαβόντες· ἐγὼ γὰρ οὐ φιλομαθήσων εἰς Ἀθήνας ὑπὸ Ῥωμαίων ἐπέμφθην, ἀλλὰ τοὺς ἀφισταμένους καταστρεψόμενος.", "st": "Sull. 13.1"}, {"sp": "N", "t": "ἐν δὲ τούτῳ λέγεταί τινας ἐν Κεραμεικῷ πρεσβυτῶν ἀκούσαντας διαλεγομένων πρὸς ἀλλήλους καὶ κακιζόντων τὸν τύραννον, ὡς μὴ φυλάττοντα τοῦ τείχους τὴν περὶ τὸ Ἑπτάχαλκον ἔφοδον καὶ προσβολήν, ᾗ μόνῃ δυνατὸν εἶναι καὶ ῥᾴδιον ὑπερβῆναι τοὺς πολεμίους, ἀπαγγεῖλαι ταῦτα πρὸς τὸν Σύλλαν. ὁ δὲ οὐ κατεφρόνησεν, ἀλλὰ ἐπελθὼν νυκτὸς καὶ θεασάμενος τὸν τόπον ἁλώσιμον εἴχετο τοῦ ἔργου, λέγει δὲ αὐτός ὁ Σύλλας ἐν τοῖς ὑπομνήμασι τὸν πρῶτον ἐπιβάντα τοῦ τείχους Μάρκον Ἀτήϊον ἀντιστάντος αὐτῷ πολεμίου δόντα πληγὴν ἐκ καταφορᾶς τῷ κράνει περικλάσαι τὸ ξίφος, οὐ μὴν ὑφέσθαι τῆς χώρας, ἀλλὰ μεῖναι καὶ κατασχεῖν. κατελήφθη μὲν οὖν ἡ πόλις ἐκεῖθεν, ὡς Ἀθηναίων οἱ πρεσβύτατοι διεμνημόνευον. αὐτός δὲ Σύλλας τὸ μεταξὺ τῆς Πειραϊκῆς πύλης καὶ τῆς ἱερᾶς κατασκάψας καὶ συνομαλύνας, περὶ μέσας νύκτας εἰσήλαυνε, φρικώδης ὑπό τε σάλπιγξι καὶ κέρασι πολλοῖς, ἀλαλαγμῷ καὶ κραυγῇ τῆς δυνάμεως ἐφ’ ἁρπαγὴν καὶ φόνον ἀφειμένης ὑπ’ αὐτοῦ, καὶ φερομένης διὰ τῶν στενωπῶν ἐσπασμένοις τοῖς ξίφεσιν, ὥστε ἀριθμὸν μηδένα γενέσθαι τῶν ἀποσφαγέντων, ἀλλὰ τῷ τόπῳ τοῦ ῥυέντος αἵματος ἔτι νῦν μετρεῖσθαι τὸ πλῆθος. ἄνευ γὰρ τῶν κατὰ τὴν ἄλλην πόλιν ἀναιρεθέντων ὁ περὶ τὴν ἀγορὰν φόνος ἐπέσχε πάντα τὸν ἐντὸς τοῦ Διπύλου Κεραμεικόν πολλοῖς δὲ λέγεται καὶ διὰ πυλῶν κατακλύσαι τὸ προάστειον. ἀλλὰ τῶν οὕτως ἀποθανόντων, τοσούτων γενομένων, οὐκ ἐλάσσονες ἦσαν οἱ σφᾶς αὐτοὺς διαφθείροντες οἴκτῳ καὶ πόθῳ τῆς πατρίδος ὡς ἀναιρεθησομένης. τοῦτο γὰρ ἀπογνῶναι καὶ φοβηθῆναι τὴν σωτηρίαν ἐποίησε τοὺς βελτίστους, οὐδὲν ἐν τῷ Σύλλᾳ φιλάνθρωπον οὐδὲ μέτριον ἐλπίσαντας. ἀλλὰ γὰρ τοῦτο μὲν Μειδίου καὶ Καλλιφῶντος τῶν φυγάδων δεομένων καὶ προκυλινδουμένων αὐτοῦ, τοῦτο δὲ τῶν συγκλητικῶν, ὅσοι συνεστράτευον, ἐξαιτουμένων τὴν πόλιν, αὐτός τε μεστὸς ὢν ἤδη τῆς τιμωρίας, ἐγκώμιόν τι τῶν παλαιῶν Ἀθηναίων ὑπειπὼν ἔφη χαρίζεσθαι πολλοῖς μὲν ὀλίγους, ζῶντας δὲ τεθνηκόσιν.", "st": "Sull. 14.1"}, {"sp": "N", "t": "ἑλεῖν δὲ τὰς Ἀθήνας αὐτός φησιν ἐν τοῖς ὑπομνήμασι Μαρτίαις καλάνδαις, ἥτις ἡμέρα μάλιστα συμπίπτει τῇ νουμηνίᾳ τοῦ Ἀνθεστηριῶνος μηνός, ἐν ᾧ κατὰ τύχην ὑπομνήματα πολλὰ τοῦ διὰ τὴν ἐπομβρίαν ὀλέθρου καὶ τῆς φθορᾶς ἐκείνης δρῶσιν, ὡς τότε καὶ περὶ τὸν χρόνον ἐκεῖνόν μάλιστα τοῦ κατακλυσμοῦ συμπεσόντος. ἑαλωκότος δὲ τοῦ ἄστεος ὁ μὲν τύραννος εἰς τὴν ἀκρόπολιν καταφυγὼν ἐπολιορκεῖτο, Κουρίωνος ἐπὶ τούτῳ τεταγμένου· καὶ χρόνον ἐγκαρτερήσας συχνὸν αὐτός ἑαυτὸν ἐνεχείρισε δίψει πιεσθείς, καὶ τὸ δαιμόνιον εὐθὺς ἐπεσήμηνε· τῆς γὰρ αὐτῆς ἡμέρας τε καὶ ὥρας ἐκεῖνόν τε Κουρίων κατῆγε, καὶ νεφῶν ἐξ αἰθρίας συνδραμόντων πλῆθος ὄμβρου καταρραγὲν ἐπλήρωσεν ὕδατος τὴν ἀκρόπολιν. εἷλε δὲ καὶ τὸν Πειραιᾶ μετ’ οὐ πολὺν χρόνον ὁ Σύλλας, καὶ τὰ πλεῖστα κατέκαυσεν, ὧν ἦν καὶ ἡ Φίλωνος ὁπλοθήκη, θαυμαζόμενον ἔργον.", "st": "Sull. 14.6"}, {"sp": "N", "t": "ἐν δὲ τούτῳ Ταξίλης ὁ Μιθριδάτου στρατηγὸς ἐκ Θρᾴκης καὶ Μακεδονίας καταβεβηκὼς δέκα μυριάσι πεζῶν καὶ μυρίοις ἱππεῦσι καὶ τεθρίπποις ἐνενήκοντα δρεπανηφόροις ἐκάλει τὸν Ἀρχέλαον, ἔτι ναυλοχοῦντα περὶ τὴν Μουνυχίαν καὶ μήτε τῆς θαλάττης βουλόμενον ἀποστῆναι μήτε πρόθυμον ὄντα συμπλέκεσθαι τοῖς Ῥωμαίοις, ἀλλὰ χρονοτριβεῖν τὸν πόλεμον καὶ τὰς εὐπορίας αὐτῶν ἀφαιρεῖν. ἃ δὴ πολὺ μᾶλλον ἐκείνου συνορῶν ὁ Σύλλας ἀνέζευξεν εἰς Βοιωτίαν ἐκ χωρίων γλίσχρων καὶ μηβὲ ἐν εἰρήνῃ τρέφειν ἱκανῶν ὄντων, καὶ τοῖς πολλοῖς ἐδόκει σφάλλεσθαι τὸν λογισμόν, ὅτι τὴν Ἀττικὴν τραχεῖαν οὖσαν καὶ δύσιππον ἀπολιπὼν ἐνέβαλεν ἑαυτὸν πεδιάσι καὶ ἀναπεπταμέναις ταῖς περὶ τὴν Βοιωτίαν χώραις, ὁρῶν ἐν ἅρμασι καὶ ἵπποις τὴν βαρβαρικὴν οὖσαν ἀλκήν. ἀλλὰ φεύγων, ὥσπερ εἴρηται, λιμὸν καὶ σπάνιν ἠναγκάζετο διώκειν τὸν ἐκ τῆς μάχης κίνδυνον. ἔτι δὲ Ὁρτήσιος αὐτὸν ἐφόβει, στρατηγικὸς ἀνὴρ καὶ φιλόνεικος, ὃν ἐκ Θετταλίας ἄγοντα τῷ Σύλλᾳ δύναμιν ἐν τοῖς στενοῖς οἱ βάρβαροι παρεφύλαττον. διὰ ταῦτα μὲν εἰς τὴν Βοιωτίαν ἀνέζευξεν ὁ Σύλλας· Ὁρτήσιον δὲ Κάφις, ἡμέτερος ὤν, ἑτέραις ὁδοῖς ψευσάμενος τοὺς βαρβάρους διὰ τοῦ Παρνασσοῦ κατῆγεν ὑπ’ αὐτὴν τὴν Τιθόραν, οὔπω τοσαύτην πόλιν οὖσαν ὅση νῦν ἐστιν, ἀλλὰ φρούριον ἀπορρῶγι κρημνῷ περικοπτόμενον, εἰς ὃ καὶ πάλαι ποτὲ Φωκέων οἱ Ξέρξην ἐπιόντα φεύγοντες ἀνεσκευάσαντο καὶ διεσώθησαν, ἐνταῦθα καταστρατοπεδεύσας Ὁρτήσιος ἡμέρας μὲν ἀπεκρούσατο τοὺς πολεμίους, νύκτωρ δ’ ἐπὶ Πατρωνίδα ταῖς δυσχωρίαις καταβὰς ἀπαντήσαντι τῷ Σύλλᾳ μετὰ τῆς δυνάμεως συνέμιξε.", "st": "Sull. 15.1"}, {"sp": "N", "t": "γενόμενοι δὲ κοινῇ καταλαμβάνονται βουνὸν ἐκ μέσων ἑστῶτα τῶν Ἐλατικῶν πεδίων, εὔγεων καὶ ἀμφιλαφῆ καὶ παρὰ τήν ῥίζαν ὕδωρ ἔχοντα· Φιλοβοιωτὸς καλεῖται, καὶ τήν φύσιν αὐτοῦ καὶ τήν θέσιν ἐπαινεῖ θαυμασίως ὁ Σύλλας. στρατοπεδεύσαντες δὲ παντάπασιν ὀλίγοι τοῖς πολεμίοις κατεφάνησαν ἱππεῖς μὲν γὰρ οὐ πλείους πεντακοσίων καὶ χιλίων ἐγένοντο, πεζοὶ δὲ πεντακισχιλίων καὶ μυρίων ἐλάττους. ὅθεν ἐκβιασάμενοι τόν Ἀρχέλαον οἱ λοιποὶ στρατηγοὶ καὶ παρατάξαντες τήν δύναμιν, ἐνέπλησαν ἵππων, ἁρμάτων, ἀσπίδων, θυρεῶν τὸ πεδίον.", "st": "Sull. 16.1"}, {"sp": "N", "t": "τὴν δὲ κραυγὴν καὶ ἀλαλαγμὸν οὐκ ἔστεγεν ὁ ἀὴρ ἐθνῶν τοσούτων ἅμα καθισταμένων εἰς τάξιν. ἦν δὲ ἅμα καὶ τὸ κομπῶδες καὶ σοβαρὸν αὐτῶν τῆς πολυτελείας οὐκ ἀργὸν οὐδὲ ἄχρηστον εἰς ἔκπληξιν, ἀλλ’ αἵ τε μαρμαρυγαὶ τῶν ὅπλων ἠσκημένων χρυσῷ τε καὶ ἀργύρῳ διαπρεπῶς, αἵ τε βαφαὶ τῶν Μηδικῶν καὶ Σκυθικῶν χιτώνων ἀναμεμιγμέναι χαλκῷ καὶ σιδήρῳ λάμποντι πυροειδῆ καὶ φοβερὰν ἐν τῷ σαλεύεσθαι καὶ διαφέρεσθαι προσέβαλον ὄψιν, ὥστε τοὺς Ῥωμαίους ὑπὸ τόν χάρακα συστέλλειν ἑαυτούς, καὶ τόν Σύλλαν μηδενὶ λόγῳ τὸ θάμβος αὐτῶν ἀφελεῖν δυνάμενον, βιάζεσθαί τε ἀποδιδράσκοντας οὐ βουλόμενον, ἡσυχίαν ἄγειν καὶ φέρειν βαρέως ἐφυβρίζοντας ὁρῶντα κομπασμῷ καὶ γέλωτι τοὺς βαρβάρους, ὤνησε μέντοι τοῦτο μάλιστα πάντων αὐτόν. οἱ γὰρ ἐναντίοι καταφρονήσαντες ἐτράποντο πρὸς ἀταξίαν πολλήν, οὐδὲ ἄλλως ὑπήκοοι τῶν στρατηγῶν διὰ πολυαρχίαν ὄντες· ὥστε ὀλίγοι μὲν ἐν τῷ χάρακι διεκαρτέρουν, ὁ δὲ πλεῖστος ὄχλος ἁρπαγαῖς καὶ πορθήμασι δελεαζόμενος ὁδὸν ἡμερῶν πολλῶν ἀπὸ τοῦ στρατοπέδου διεσπείρετο. καὶ τήν τε τῶν Πανοπέων πόλιν ἐκκόψαι λέγονται καὶ τήν Λεβαδέων διαρπάσαι καὶ συλῆσαι τὸ μαντεῖον, οὐδενὸς στρατηγοῦ πρόσταγμα δόντος.", "st": "Sull. 16.3"}, {"sp": "N", "t": "ὁ δὲ Σύλλας, ἐν ὄμμασιν αὐτοῦ πόλεων ἀπολλυμένων, δυσανασχετῶν καὶ λυπούμενος, οὐκ εἴα τοὺς στρατιώτας σχολάζειν, ἀλλὰ προσάγων αὐτοὺς ἠνάγκαζε τόν τε Κηφισὸν ἐκ τοῦ ῥείθρου παρατρέπειν καὶ τάφρους ὀρύσσειν, ἀνάπαυλαν οὐδενὶ διδοὺς καὶ τῶν ἐνδιδόντων ἀπαραίτητος ἐφεστὼς κολαστής, ὅπως ἀπαγορεύσαντες πρὸς τὰ ἔργα διὰ τόν πόνον ἀσπάσωνται τόν κίνδυνον. ὃ καὶ συνέβη, τρίτην γὰρ ἡμέραν ἐργαζόμενοι τοῦ Σύλλα παρεξιόντος ἐδέοντο μετὰ κραυγῆς ἄγειν ἐπὶ τοὺς πολεμίους, ὁ δὲ οὐ μάχεσθαι βουλομένων, ἀλλὰ μὴ βουλομένων πονεῖν ἔφησεν εἶναι τόν λόγον εἰ δὲ ὄντως ἔχουσιν ἀγωνιστικῶς, ἐκέλευσεν ἤδη μετὰ τῶν ὅπλων ἐλθεῖν ἐκεῖσε, δείξας αὐτοῖς τήν πρότερον μὲν γενομένην ἀκρόπολιν τῶν Παραποταμίων, τότε δὲ ἀνῃρημένης τῆς πόλεως λόφος ἐλείπετο πετρώδης καὶ περίκρημνος, τοῦ Ἡδυλίου διωρισμένος ὄρους ὅσον ὁ Ἄσσος ἐπέχει ῥέων, εἶτα συμπίπτων ὑπὸ τήν ῥίζαν αὐτὴν τῷ Κηφισῷ καὶ συνεκτραχυνόμενος ὀχυρὰν ἐνστρατοπεδεῦσαι τήν ἄκραν ποιεῖ, διὸ καὶ τοὺς χαλκάσπιδας ὁρῶν τῶν πολεμίων ὠθουμένους ἐπ’ αὐτὴν ὁ Σύλλας ἐβούλετο φθῆναι καταλαβὼν τόν τόπον καὶ κατέλαβε χρησάμενος τοῖς στρατιώταις προθύμοις. ἐπεὶ δὲ ἀποκρουσθεὶς ἐκεῖθεν ὁ Ἀρχέλαος ὥρμησεν ἐπὶ τήν Χαιρώνειαν, οἱ δὲ συστρατευσάμενοι τῶν Χαιρωνέων ἐδέοντο τοῦ Σύλλα μὴ προέσθαι τήν πόλιν, ἐκπέμπει τῶν χιλιάρχων ἕνα Γαβίνιον μετὰ τάγματος ἑνὸς καὶ τοὺς Χαιρωνεῖς ἀφίησι, βουληθέντας μέν, οὐ μὴν δυνηθέντας φθῆναι τόν Γαβίνιον. οὕτως ἦν ἀγαθὸς καὶ προθυμότερος εἰς τὸ σῶσαι τῶν σωθῆναι δεομένων. ὁ δὲ Ἰόβας οὐ Γαβίνιόν φησι πεμφθῆναι, ἀλλὰ Ἐρίκιον. ἡ μὲν οὖν πόλις ἡμῶν παρὰ τοσοῦτον ἐξέφυγε τόν κίνδυνον.", "st": "Sull. 16.5"}, {"sp": "N", "t": "ἐκ δὲ Λεβαδείας καὶ τοῦ Τροφωνίου φῆμαί τε χρησταὶ καὶ νικηφόρα μαντεύματα τοῖς Ῥωμαίοις ἐξεπέμποντο. περὶ ὧν οἱ μὲν ἐπιχώριοι πλείονα λέγουσιν ὡς δὲ Σύλλας αὐτὸς ἐν δεκάτῳ τῶν ὑπομνημάτων γέγραφε, Κόϊντος Τίτιος, οὐκ ἀφανὴς ἀνὴρ τῶν ἐν τῇ Ἑλλάδι πραγματευομένων, ἧκε πρὸς αὐτὸν ἤδη τὴν ἐν Χαιρωνείᾳ νενικηκότα μάχην, ἀπαγγέλλων ὅτι καὶ δευτέραν ὁ Τροφώνιος αὐτόθι μάχην καὶ νίκην προσημαίνει ἐντὸς ὀλίγου χρόνου. μετὰ δὲ τοῦτον ἀνὴρ τῶν ἐν τάξει στρατευομένων ὄνομα Σαλουήνιος ἀνήνεγκε παρὰ τοῦ θεοῦ τέλος οἷον αἱ κατὰ τὴν Ἰταλίαν πράξεις ἔμελλον ἕξειν. ἀμφότεροι δὲ ταὐτὰ περὶ τῆς ὀμφῆς ἔφραζον τῷ γὰρ Ὀλυμπίῳ Διῒ καὶ τὸ κάλλος καὶ τὸ μέγεθος παραπλήσιον ἰδεῖν ἔφασαν.", "st": "Sull. 17.1"}, {"sp": "N", "t": "ἐπειδὴ δὲ διέβη τὸν Ἄσσον ὁ Σύλλας, παρελθὼν ὑπὸ τὸ Ἡδύλιον τῷ Ἀρχελάῳ παρεστρατοπέδευσε, βεβλημένῳ χάρακα καρτερὸν ἐν μέσῳ τοῦ Ἀκοντίου καὶ τοῦ Ἡδυλίου πρὸς τοῖς λεγομένοις Ἀσσίοις. ὁ μέντοι τόπος ἐν ᾧ κατεσκήνωσεν ἄχρι νῦν Ἀρχέλαος ἀπ’ ἐκείνου καλεῖται, διαλιπὼν δὲ μίαν ἡμέραν ὁ Σύλλας Μουρήναν μὲν ἔχοντα τάγμα καὶ σπείρας δύο πρὸς τὸ τοῖς πολεμίοις ἐνοχλῆσαι παραταττομένοις ἀπέλιπεν, αὐτὸς δὲ παρὰ τὸν Κηφισὸν ἐσφαγιάζετο, καὶ τῶν ἱερῶν γενομένων ἐχώρει πρὸς τὴν Χαιρώνειαν, ἀναληψόμενός τε τὴν αὐτόθι στρατιὰν καὶ κατοψόμενος τὸ καλούμενον Θούριον ὑπὸ τῶν πολεμίων προκατειλημμένον. ἔστι δὲ κορυφὴ τραχεῖα καὶ στροβιλῶδες ὄρος, ὃ καλοῦμεν Ὀρθόπαγον, ὑπὸ δὲ αὐτὸ τὸ ῥεῦμα τοῦ Μόλου καὶ Θουρίου νεὼς Ἀπόλλωνος. ὠνόμασται δὲ ὁ θεὸς ἀπὸ Θουροῦς, τῆς Χαίρωνος μητρός, ὃν οἰκιστὴν γεγονέναι τῆς Χαιρωνείας ἱστοροῦσιν. οἱ δέ φασι τὴν Κάδμῳ δοθεῖσαν ὑπὸ τοῦ Πυθίου καθηγεμόνα βοῦν ἐκεῖ φανῆναι, καὶ τὸν τόπον ἀπ’ αὐτῆς οὕτω προσαγορευθῆναι θὼρ γὰρ οἱ Φοίνικες τὴν βοῦν καλοῦσι.", "st": "Sull. 17.3"}, {"sp": "N", "t": "προσιόντος δὲ τοῦ Σύλλα πρὸς τὴν Χαιρώνειαν ὁ τεταγμένος ἐν τῇ πόλει χιλίαρχος, ἐξωπλισμένους ἄγων τοὺς στρατιώτας, ἀπήντησε στέφανον δάφνης κομίζων. ὡς δὲ δεξάμενος ἠσπάσατο τοὺς στρατιώτας καὶ παρώρμησε πρὸς τὸν κίνδυνον, ἐντυγχάνουσιν αὐτῷ δύο τῶν Χαιρωνέων ἄνδρες, Ὁμολόϊχος καὶ Ἀναξίδαμος, ὑφιστάμενοι τοὺς τὸ Θούριον κατασχόντας ἐκκόψειν, ὀλίγους στρατιώτας παρ’ ἐκείνου λαβόντες· ἀτραπὸν γὰρ εἶναι τοῖς βαρβάροις ἄδηλον, ἀπὸ τοῦ καλουμένου Πετράχου παρὰ τὸ Μουσεῖον ἐπὶ τὸ Θούριον ὑπὲρ κεφαλῆς ἄγουσαν, ᾗ πορευθέντες οὐ χαλεπῶς ἐπιπεσεῖσθαι καὶ καταλεύσειν ἄνωθεν αὐτοὺς ἢ συνώσειν εἰς τὸ πεδίον. τοῦ δὲ Γαβινίου τοῖς ἀνδράσι μαρτυρήσαντος ἀνδρείαν καὶ πίστιν, ἐκέλευσεν ἐπιχειρεῖν ὁ Σύλλας· αὐτὸς δὲ συνέταττε τὴν φάλαγγα καὶ διένειμε τοὺς ἱππότας ἐπὶ κέρως ἑκατέρου, τὸ δεξιὸν αὐτὸς ἔχων, τὸ δ’ εὐώνυμον ἀποδοὺς Μουρήνᾳ. Γάλβας δὲ καὶ Ὁρτήσιος οἱ πρεσβευταὶ σπείρας ἐπιτάκτους ἔχοντες ἔσχατοι παρενέβαλον ἐπὶ τῶν ἄκρων φύλακες πρὸς τὰς κυκλώσεις· ἑωρῶντο γὰρ οἱ πολέμιοι κατασκευάζοντες ἱππεῦσι πολλοῖς καὶ ψιλοῖς ποδώκεσιν εἰς ἐπιστροφὴν τὸ κέρας εὐκαμπὲς καὶ κοῦφον, ὡς μακρὰν ἀνάξοντες καὶ κυκλωσόμενοι τοὺς Ῥωμαίους.", "st": "Sull. 17.6"}, {"sp": "N", "t": "ἐν δὲ τούτῳ τῶν Χαιρωνέων Ἐρίκιον ἄρχοντα παρὰ τοῦ Σύλλα λαβόντων καί περιελθόντων ἀδήλως τὸ Θούριον, εἶτα ἐπιφανέντων, θόρυβος ἦν πολὺς καί φυγὴ τῶν βαρβάρων καί φόνος ὑπ’ ἀλλήλων ὁ πλεῖστος, οὐ γὰρ ὑπέμειναν, ἀλλὰ κατὰ πρανοῦς φερόμενοι τοῖς τε δόρασι περιέπιπτον αὐτοὶ τοῖς ἑαυτῶν καί κατεκρήμνιζον ὠθοῦντες ἀλλήλους, ἄνωθεν ἐπικειμένων τῶν πολεμίων καί τὰ γυμνὰ παιόντων, ὥστε τρισχιλίους πεσεῖν περὶ τὸ Θούριον. τῶν δὲ φευγόντων τοὺς μὲν εἰς τάξιν ἤδη καθεστὼς ὁ Μουρήνας ἀπετέμνετο καί διέφθειρεν ὑπαντιάζων, οἱ δὲ ὠσάμενοι πρὸς τὸ φίλιον στρατόπεδον καί τῇ φάλαγγι φύρδην ἐμπεσόντες ἀνέπλησαν δέους καί ταραχῆς τὸ πλεῖστον μέρος, καί διατριβὴν τοῖς στρατηγοῖς ἐνεποίησαν οὐχ ἥκιστα βλάψασαν αὐτούς, ὀξέως γὰρ ὁ Σύλλας ταρασσομένοις ἐπαγαγὼν καί τὸ μέσον διάστημα τῷ τάχει συνελὼν ἀφείλετο τὴν τῶν δρεπανηφόρων ἐνέργειαν. ἔρρωται γὰρ μάλιστα μήκει δρόμου σφοδρότητα καὶ ῥύμην τῇ διεξελάσει διδόντος, αἱ δὲ ἐκ βραχέος ἀφέσεις ἄπρακτοι καί ἀμβλεῖαι, καθάπερ βελῶν τάσιν οὐ λαβόντων. ὃ δὴ καί τότε τοῖς βαρβάροις ἀπήντα καί τὰ πρῶτα τῶν ἁρμάτων ἀργῶς ἐξελαυνόμενα καί προσπίπτοντα νωθρῶς ἐκκρούσαντες οἱ Ῥωμαῖοι μετὰ κρότου καὶ γέλωτος ἄλλα ᾔτουν, ὥσπερ εἰώθασιν ἐν ταῖς θεατρικαῖς ἱπποδρομίαις. τοὐντεῦθεν αἱ πεζαὶ δυνάμεις συνερράγησαν, τῶν μὲν βαρβάρων προβαλλομένων τὰς σαρίσας μακρὰς καί πειρωμένων τῷ συνασπισμῷ τὴν φάλαγγα διατηρεῖν ἐν τάξει, τῶν δὲ Ῥωμαίων τοὺς μὲν ὑσσοὺς αὐτοῦ καταβαλόντων, σπασαμένων δὲ τὰς μαχαίρας καί παρακρουομένων τὰς σαρίσας, ὡς τάχιστα προσμίξειαν αὐτοῖς δι’ ὀργήν. προτεταγμένους γὰρ ἑώρων τῶν πολεμίων μυρίους καί πεντακισχιλίους θεράποντας, οὓς ἐκ τῶν πόλεων κηρύγμασιν ἐλευθεροῦντες οἱ βασιλέως στρατηγοὶ κατελόχιζον εἰς τοὺς ὁπλίτας. καί τις ἑκατοντάρχης λέγεται Ῥωμαῖος εἰπεῖν ὡς ἐν Κρονίοις μόνον εἰδείη τῆς παρρησίας δούλους μετέχοντας· τούτους μὲν οὖν διὰ βάθος καί πυκνότητα βραδέως ἐξωθουμένους ὑπὸ τῶν ὁπλιτῶν καί παρὰ φύσιν μένειν τολμῶντας αἵ τε βελοσφενδόναι καί οἱ γρόσφοι, χρωμένων ἀφειδῶς τῶν κατόπιν Ῥωμαίων, ἀπέστρεφον καὶ συνετάραττον.", "st": "Sull. 18.1"}, {"sp": "N", "t": "Ἀρχελάου δὲ τὸ δεξιὸν κέρας εἰς κύκλωσιν ἀνάγοντος, Ὁρτήσιος ἐφῆκε τὰς σπείρας δρόμῳ προσφερομένας ὡς ἐμβαλῶν πλαγίοις. ἐπιστρέψαντος δὲ ταχέως ἐκείνου τοὺς περὶ αὑτὸν ἱππεῖς δισχιλίους, ἐκθλιβόμενος ὑπὸ πλήθους προσεστέλλετο τοῖς ὀρεινοῖς, κατὰ μικρὸν ἀπορρηγνύμενος τῆς φάλαγγος καὶ περιλαμβανόμενος ὑπὸ τῶν πολεμίων. πυθόμενος δὲ ὁ Σύλλας ἀπὸ τοῦ δεξιοῦ μήπω συμπεπτωκότος εἰς μάχην ἐδίωκε βοηθῶν. Ἀρχέλαος δὲ τῷ κονιορτῷ τῆς ἐλάσεως ὅπερ ἦν τεκμηράμενος, Ὁρτήσιον μὲν εἴα χαίρειν, αὐτὸς δὲ ἐπιστρέψας ὥρμησεν ὅθεν ὁ Σύλλας πρός τὸ δεξιόν, ὡς ἔρημον ἄρχοντος αἱρήσων, ἅμα δὲ καὶ Μουρήνᾳ Ταξίλης ἐπῆγε τοὺς χαλκάσπιδας, ὥστε τῆς κραυγῆς διχόθεν φερομένης καὶ τῶν ὀρῶν ἀνταποδιδόντων τὴν περιήχησιν, ἐπιστήσαντα τὸν Σύλλαν διαπορεῖν ὁποτέρωσε χρὴ προσγενέσθαι. δόξαν δὲ τὴν ἑαυτοῦ τάξιν ἀναλαμβάνειν, Μουρήνᾳ μὲν ἀρωγὸν ἔπεμψεν Ὁρτήσιον ἔχοντα τέσσαρας σπείρας, αὐτὸς δὲ τὴν πέμπτην ἕπεσθαι κελεύσας ἐπὶ τὸ δεξιὸν ἠπείγετο καὶ καθ’ ἑαυτὸ μὲν ἀξιομάχως ἤδη τῷ Ἀρχελάῳ συνεστηκός, ἐκείνου δὲ ἐπιφανέντος παντάπασιν ἐξεβιάσαντο, καὶ κρατήσαντες ἐδίωκον πρός τε τὸν ποταμὸν καὶ τὸ Ἀκόντιον ὄρος προτροπάδην φεύγοντας. οὐ μὴν ὅ γε Σύλλας ἠμέλησε Μουρήνα κινδυνεύοντος, ἀλλὰ ὥρμησε τοῖς ἐκεῖ βοηθεῖν ἰδὼν δὲ νικῶντας, τότε τῆς διώξεως μετεῖχε. πολλοὶ μὲν οὖν ἐν τῷ πεδίῳ τῶν βαρβάρων ἀνῃροῦντο, πλεῖστοι δὲ τῷ χάρακι προσφερόμενοι κατεκόπησαν, ὥστε μυρίους διαπεσεῖν εἰς Χαλκίδα μόνους ἀπὸ τοσούτων μυριάδων, ὁ δὲ Σύλλας λέγει τέσσαρας καὶ δέκα ἐπιζητῆσαι τῶν αὐτοῦ στρατιωτῶν, εἶτα καὶ τούτων δύο πρός τὴν ἑσπέραν παραγενέσθαι. διὸ καὶ τοῖς τροπαίοις ἐπέγραψεν Ἄρη καὶ Νίκην καὶ Ἀφροδίτην, ὡς οὐχ ἧττον εὐτυχίᾳ κατορθώσας ἢ δεινότητι καὶ δυνάμει τὸν πόλεμον. ἀλλὰ τοῦτο μὲν τὸ τρόπαιον ἕστηκε τῆς πεδιάδος μάχης ᾗ πρῶτον ἐνέκλιναν οἱ περὶ Ἀρχέλαον παρὰ τὸ Μόλου ῥεῖθρον, ἕτερον δέ ἐστι τοῦ Θουρίου κατὰ κορυφὴν βεβηκὸς ἐπὶ τῇ κυκλώσει τῶν βαρβάρων, γράμμασιν Ἑλληνικοῖς ἐπισημαῖνον Ὁμολόϊχον καὶ Ἀναξίδαμον ἀριστεῖς. ταύτης τὰ ἐπινίκια τῆς μάχης ἦγεν ἐν Θήβαις, περὶ τὴν Οἰδιπόδειον κρήνην κατασκευάσας θυμέλην. οἱ δὲ κρίνοντες ἦσαν Ἕλληνες ἐκ τῶν ἄλλων ἀνακεκλημένοι πόλεων, ἐπεὶ πρός γε Θηβαίους ἀδιαλλάκτως εἶχε, καὶ τῆς χώρας αὐτῶν ἀποτεμόμενος τὴν ἡμίσειαν τῷ Πυθίῳ καὶ τῷ Ὀλυμπίῳ καθιέρωσεν, ἐκ τῶν προσόδων κελεύσας ἀποδίδοσθαι τὰ χρήματα τοῖς θεοῖς ἅπερ αὐτὸς εἰλήφει.", "st": "Sull. 19.1"}, {"sp": "N", "t": "μετὰ ταῦτα πυνθανόμενος Φλάκκον ἀπὸ τῆς ἐναντίας στάσεως ὕπατον ᾑρημένον διαπερᾶν τὸν Ἰόνιον μετὰ δυνάμεως, λόγῳ μὲν ἐπὶ Μιθριδάτην, ἔργῳ δὲ ἐπ’ ἐκεῖνον αὐτόν, ὥρμησεν ἐπὶ Θετταλίας ὡς ἀπαντήσων. γενομένῳ δὲ αὐτῷ περὶ πόλιν Μελίτειαν ἀφικνοῦντο πολλαχόθεν ἀγγελίαι πορθεῖσθαι τὰ κατόπιν αὖθις οὐκ ἐλάττονι στρατιᾷ βασιλικῇ τῆς πρότερον. Δορύλαος γὰρ εἰς Χαλκίδα καταχθεὶς παρασκευῇ νεῶν πολλῇ, ἐν αἷς ἦγεν ὀκτὼ μυριάδας ἠσκημένας καὶ συντεταγμένας ἄριστα δὴ τῆς Μιθριδατικῆς στρατιᾶς, εὐθὺς εἰς Βοιωτίαν ἐνέβαλε καὶ κατεῖχε τὴν χώραν, προθυμούμενος εἰς μάχην ἐπισπάσασθαι τὸν Σύλλαν, οὐ προσέχων Ἀρχελάῳ διακωλύοντι, καὶ λόγον περὶ τῆς προτέρας μάχης διαδιδοὺς ὡς οὐκ ἄνευ προδοσίας μυριάδες τοσαῦται διαφθαρεῖεν. οὐ μὴν ἀλλὰ ὁ Σύλλας ταχέως ὑποστρέψας ἀπέδειξε τῷ Δορυλάῳ τὸν Ἀρχέλαον ἄνδρα φρόνιμον καὶ τῆς Ῥωμαίων ἐμπειρότατον ἀρετῆς, ὥστε μικρὰ αὐτὸν τῷ Σύλλᾳ περὶ τὸ Τιλφώσσιον ἐμπεσόντα πρῶτον εἶναι τῶν οὐκ ἀξιούντων κρίνεσθαι διὰ μάχης, ἀλλὰ δαπάναις καὶ χρόνῳ τρίβειν τὸν πόλεμον. ὅμως δὲ θάρσος τι τῷ Ἀρχελάῳ παρεῖχεν ὁ πρὸς Ὀρχομενῷ τόπος, ἐν ᾧ κατεστρατοπέδευσαν, εὐφυέστατος ὢν ἱπποκρατοῦσιν ἐναγωνίσασθαι. τῶν γὰρ Βοιωτίων πεδίων ὅ τί πέρ ἐστι κάλλιστον καὶ μέγιστον, τοῦτο τῆς Ὀρχομενίων ἐξηρτημένον πόλεως ὁμαλὸν ἀναπέπταται καὶ ἄδενδρον ἄχρι τῶν ἑλῶν ἐν οἷς ὁ Μέλας καταναλίσκεται ποταμός, ἀνατέλλων μὲν ὑπὸ τὴν πόλιν τῶν Ὀρχομενίων πολὺς καὶ πλώϊμος ἐν πηγαῖς μόνος τῶν Ἑλληνικῶν ποταμῶν, αὐξόμενος δὲ ὑπὸ τροπὰς θερινάς, ὥσπερ ὁ Νεῖλος, καὶ φέρων ὅμοια τοῖς ἐκεῖ τὰ φυόμενα, πλὴν ἄκαρπα καὶ ἀναυξῆ. πόρρω δὲ οὐ πρόεισιν, ἀλλὰ τὸ μὲν πλεῖστον εὐθὺς εἰς λίμνας τυφλὰς καὶ ἑλώδεις ἀφανίζεται, μέρος δὲ οὐ πολὺ τῷ Κηφισῷ συμμίγνυται, περὶ ὃν μάλιστα τόπον ἡ λίμνη δοκεῖ τὸν αὐλητικὸν ἐκφέρειν κάλαμον.", "st": "Sull. 20.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐγγὺς κατεστρατοπέδευσαν, ὁ μὲν Ἀρχέλαος ἡσύχαζεν, ὁ δὲ Σύλλας ὤρυττε τάφρους ἑκατέρωθεν, ὅπως, εἰ δύναιτο, τῶν στερεῶν καὶ ἱππασίμων ἀποτεμόμενος τοὺς πολεμίους ὤσειεν εἰς τὰ ἕλη. τῶν δὲ οὐκ ἀνασχομένων, ἀλλ’ ὡς ἀφείθησαν ὑπὸ τῶν στρατηγῶν, ἐντόνως καὶ ῥύδην ἐλαυνόντων, οὐ μόνον οἱ περὶ τὰ ἔργα τοῦ Σύλλα διεσκεδάσθησαν, ἀλλὰ καὶ τοῦ παρατεταγμένου συνεχύθη τὸ πλεῖστον φυγόντος. ἔνθα δὴ Σύλλας αὐτὸς ἀποπηδήσας τοῦ ἵππου καὶ σημεῖον ἀναρπάσας ὠθεῖτο διὰ τῶν φευγόντων εἰς τοὺς πολεμίους, βοῶν ἐμοὶ μὲν ἐνταῦθά που καλόν, ὦ Ῥωμαῖοι, τελευτᾶν, ὑμεῖς δὲ τοῖς πυνθανομένοις ποῦ προδεδώκατε τὸν αὐτοκράτορα, μεμνημένοι φράζειν ὡς ἐν Ὀρχομενῷ. τούτους τε δὴ τὸ ῥηθὲν ἐπέστρεψε, καὶ τῶν ἐπὶ τοῦ δεξιοῦ κέρως σπειρῶν δύο προσεβοήθησαν, ἃς ἐπαγαγὼν τρέπεται τοὺς πολεμίους. ἀναγαγὼν δὲ μικρὸν ὀπίσω, καὶ δοὺς ἄριστον αὐτοῖς, αὖθις ἀπετάφρευε τὸν χάρακα τῶν πολεμίων, οἱ δὲ αὖθις ἐν τάξει μᾶλλον ἢ πρότερον προσεφέροντο. καὶ Διογένης μὲν ὁ τῆς Ἀρχελάου γυναικὸς υἱὸς ἀριστεύων ἐπὶ τοῦ δεξιοῦ περιόπτως ἔπεσεν, οἱ δὲ τοξόται, τῶν Ῥωμαίων ἐκβιαζομένων, οὐκ ἔχοντες ἀναστροφὴν ἀθρόοις τοῖς ὀϊστοῖς ἐκ χειρὸς ὥσπερ ξίφεσι παίοντες ἀνέκοπτον αὐτούς, τέλος δὲ κατακλεισθέντες εἰς τὸν χάρακα μοχθηρῶς ὑπὸ τραυμάτων καὶ φόνου διενυκτέρευσαν. ἡμέρας δὲ πάλιν τῷ χάρακι τοὺς στρατιώτας προσαγαγὼν ὁ Σύλλας ἀπετάφρευεν. ἐξελθόντας δὲ τοὺς πολλοὺς ὡς ἐπὶ μάχην συμβαλὼν τρέπεται, καὶ πρὸς τὸν ἐκείνων φόβον οὐδενὸς μένοντος αἱρεῖ κατὰ κράτος τὸ στρατόπεδον. καὶ κατέπλησαν ἀποθνήσκοντες αἵματος τὰ ἕλη καὶ νεκρῶν τὴν λίμνην, ὥστε μέχρι νῦν πολλὰ βαρβαρικὰ τόξα καὶ κράνη καὶ θωράκων σπάσματα σιδηρῶν καὶ μαχαίρας ἐμβεβαπτισμένας τοῖς τέλμασιν εὑρίσκεσθαι, σχεδὸν ἐτῶν διακοσίων ἀπὸ τῆς μάχης ἐκείνης διαγεγονότων. τὰ μὲν οὖν περὶ Χαιρώνειαν καὶ πρὸς Ὀρχομενῷ τοιαῦτα λέγεται γενέσθαι.", "st": "Sull. 21.1"}, {"sp": "N", "t": "Κίννα δὲ καὶ Κάρβωνος ἐν Ῥώμῃ τοῖς ἐπιφανεστάτοις ἀνδράσι χρωμένων παρανόμως καὶ βιαίως, πολλοὶ τήν τυραννίδα φεύγοντες ὥσπερ εἰς λιμένα τοῦ Σύλλα τὸ στρατόπεδον κατεφέροντο, καὶ περὶ αὐτὸν ὀλίγου χρόνου σχῆμα βουλῆς ἐγεγόνει. καὶ Μετέλλα μόλις διακλέψασα ἑαυτὴν καὶ τοὺς παῖδας, ἧκεν ἀγγέλλουσα τήν οἰκίαν αὐτοῦ καὶ τὰς ἐπαύλεις ὑπὸ τῶν ἐχθρῶν ἐμπεπρῆσθαι καὶ δεομένη τοῖς οἴκοι βοηθεῖν. ἀπορουμένῳ δ’ αὐτῷ, καὶ μήτε τῆς πατρίδος ἀμελεῖν ὑπομένοντι κακουμένης μήτε ὅπως ἄπεισιν ἀτελὲς λιπὼν τοσοῦτον ἔργον, τὸν Μιθριδατικὸν πόλεμον, ἐπινοοῦντι, παραγίνεται Δηλιακὸς ἔμπορος Ἀρχέλαος, ἐλπίδας τινὰς καὶ λόγους κρύφα παρὰ τοῦ βασιλικοῦ κομίζων Ἀρχελάου, καὶ τὸ πρᾶγμα Σύλλας οὕτως ἠγάπησεν ὥστε αὐτὸς εἰς λόγους σπεῦσαι τῷ Ἀρχελάῳ συνελθεῖν· καὶ συνῆλθον ἐπὶ θαλάττῃ περὶ Δήλιον, οὗ τὸ ἱερὸν τοῦ Ἀπόλλωνός ἐστιν, ἀρξαμένου δὲ τοῦ Ἀρχελάου διαλέγεσθαι, καὶ τὸν Σύλλαν ἀξιοῦντος ἀφέντα τήν Ἀσίαν καὶ τὸν Πόντον ἐπὶ τὸν ἐν Ῥώμῃ πόλεμον πλεῖν, χρήματα λαβόντα καὶ τριήρεις καὶ δύναμιν ὅσην βούλοιτο παρὰ τοῦ βασιλέως, ὑπολαβὼν ὁ Σύλλας Μιθριδάτου μὲν ἀμελεῖν ἐκέλευεν, αὐτὸν δὲ βασιλεύειν ἀντ’ ἐκείνου σύμμαχον Ῥωμαίων γενόμενον καὶ παραδόντα τὰς ναῦς. ἀφοσιουμένου δὲ τοῦ Ἀρχελάου τήν προδοσίαν, εἶτα, ἔφη, σὺ μέν, ὦ Ἀρχέλαε, Καππαδόκης ὢν καὶ βαρβάρου βασιλέως δοῦλος, εἰ δὲ βούλει, φίλος, οὐχ ὑπομένεις ἐπὶ τηλικούτοις ἀγαθοῖς τὸ αἰσχρόν, ἐμοὶ δὲ ἡγεμόνι Ῥωμαίων ὄντι καὶ Σύλλᾳ τολμᾷς διαλέγεσθαι περὶ προδοσίας, ὥσπερ οὐκ ἐκεῖνος ὢν Ἀρχέλαος, ὁ φυγὼν μὲν ἐκ Χαιρωνείας ὀλιγοστὸς ἀπὸ μυριάδων δυοκαίδεκα, κρυφθεὶς δὲ δύο ἡμέρας ἐν τοῖς Ὀρχομενίων ἕλεσιν, ἄβατον δὲ τήν Βοιωτίαν ὑπὸ νεκρῶν πλήθους ἀπολελοιπώς; ἐκ τούτου μεταβαλὼν ὁ Ἀρχέλαος καὶ προσκυνήσας ἐδεῖτο παύσασθαι τοῦ πολέμου καὶ διαλλαγῆναι πρὸς τὸν Μιθριδάτην. δεξαμένου δὲ τοῦ Σύλλα τήν πρόκλησιν ἐγένοντο συνθῆκαι, Μιθριδάτην μὲν Ἀσίαν ἀφεῖναι καὶ Παφλαγονίαν, ἐκστῆναι δὲ Βιθυνίας Νικομήδει καὶ Καππαδοκίας Ἀριοβαρζάνῃ, καταβαλεῖν δὲ Ῥωμαίοις δισχίλια τάλαντα καὶ δοῦναι ναῦς ἑβδομήκοντα χαλκήρεις μετὰ τῆς οἰκείας παρασκευῆς, Σύλλαν δὲ ἐκείνῳ τήν τε ἄλλην ἀρχὴν βεβαιοῦν καὶ σύμμαχον Ῥωμαίων ψηφίζεσθαι.", "st": "Sull. 22.1"}, {"sp": "N", "t": "τούτων ὁμολογηθέντων ἀναστρέψας ἐβάδιζε διὰ Θετταλίας καὶ Μακεδονίας ἐπὶ τὸν Ἑλλήσποντον, ἔχων μεθ’ αὐτοῦ τὸν Ἀρχέλαον ἐν τιμῇ. καὶ νοσήσαντος ἐπισφαλῶς περὶ Λάρισσαν ἐπιστήσας τὴν πορείαν, ὡς ἑνὸς τῶν ὑπ’ αὐτὸν ἡγεμόνων καὶ στρατηγῶν ἐπεμελήθη. ταῦτά τε δὴ διέβαλλε τὸ περὶ Χαιρώνειαν ἔργον ὡς οὐχὶ καθαρῶς ἀγωνισθέν, καὶ ὅτι τοὺς ἄλλους Μιθριδάτῃ φίλους, οὓς εἶχεν αἰχμαλώτους, ἀποδοὺς ὁ Σύλλας Ἀριστίωνα μόνον τὸν τύραννον ἀνεῖλε διὰ φαρμάκων Ἀρχελάῳ διάφορον ὄντα· μάλιστα δ’ ἡ δοθεῖσα γῆ τῷ Καππαδόκῃ μυρίων πλέθρων ἐν Εὐβοίᾳ, καὶ τὸ Ῥωμαίων φίλον αὐτὸν καὶ σύμμαχον ὑπὸ Σύλλα ἀναγραφῆναι. περὶ μὲν οὖν τούτων αὐτὸς ὁ Σύλλας ἐν τοῖς ὑπομνήμασιν ἀπολογεῖται.", "st": "Sull. 23.1"}, {"sp": "N", "t": "τότε δὲ πρεσβευτῶν παρὰ τοῦ Μιθριδάτου παραγενομένων καὶ τὰ μὲν ἄλλα φασκόντων δέχεσθαι, Παφλαγονίαν δὲ ἀξιούντων μὴ ἀφαιρεθῆναι, τὰς δὲ ναῦς οὐδὲ ὅλως ὁμολογηθῆναι, χαλεπήνας ὁ Σύλλας, τί φατε; εἶπε, Μιθριδάτης Παφλαγονίας ἀντιποιεῖται καὶ περὶ τῶν νεῶν ἔξαρνός ἐστιν, ὃν ἐγὼ προσκυνήσειν ἐνόμιζον, εἰ τὴν δεξιὰν αὐτῷ καταλείποιμι χεῖρα, δι’ ἧς τοσούτους Ῥωμαίων ἀνεῖλεν; ἑτέρας μέντοι τάχα φωνὰς ἀφήσει διαβάντος εἰς Ἀσίαν ἐμοῦ νῦν δὲ ἐν Περγάμῳ καθήμενος ὃν οὐχ ἑώρακε διαστρατηγεῖ πόλεμον. οἱ μὲν οὖν πρέσβεις φοβηθέντες ἡσύχαζον, ὁ δὲ Ἀρχέλαος ἐδεῖτο τοῦ Σύλλα καὶ κατεπράϋνε τὴν ὀργήν, ἁπτόμενος τῆς δεξιᾶς αὐτοῦ καὶ δακρύων. τέλος δ’ ἔπεισεν ἀποσταλῆναι αὐτὸς πρὸς τὸν Μιθριδάτην διαπράξεσθαι γὰρ ἐφ’ οἷς βούλεται τὴν εἰρήνην, εἰ δὲ μὴ πείθοι, κτενεῖν αὐτὸς αὐτόν. ἐπὶ τούτοις ἐκπέμψας ἐκεῖνον αὐτὸς εἰς τὴν Μαιδικὴν ἐνέβαλε, καὶ τὰ πολλὰ διαπορθήσας πάλιν ἀνέστρεψεν εἰς Μακεδονίαν, καὶ τὸν Ἀρχέλαον ἐδέξατο περὶ Φιλίππους ἀγγέλλοντα καλῶς ἔχειν πάντα· δεῖσθαι δὲ πάντως αὐτῷ τὸν Μιθριδάτην εἰς λόγους ἐλθεῖν. αἴτιος δ’ ἦν μάλιστα Φιμβρίας, ὃς τὸν ἀπὸ τῆς ἑτέρας στάσεως ἄρχοντα Φλάκκον ἀνελὼν καὶ τῶν Μιθριδατικῶν στρατηγῶν κρατήσας ἐπ’ αὐτὸν ἐκεῖνον ἐβάδιζε. ταῦτα γὰρ δείσας ὁ Μιθριδάτης μᾶλλον εἵλετο τῷ Σύλλᾳ φίλος γενέσθαι.", "st": "Sull. 23.3"}, {"sp": "N", "t": "συνῆλθον οὖν τῆς Τρῳάδος ἐν Δαρδάνῳ, Μιθριδάτης μὲν ἔχων ναῦς αὐτόθι διακοσίας ἐνήρεις καὶ τῆς πεζῆς δυνάμεως ὁπλίτας μὲν δισμυρίους, ἱππεῖς δὲ ἑξακισχιλίους καὶ συχνὰ τῶν δρεπανηφόρων, Σύλλας δὲ τέσσαρας σπείρας καὶ διακοσίους ἱππεῖς, ἀπαντήσαντος δὲ τοῦ Μιθριδάτου καὶ τὴν δεξιὰν προτείναντος, ἠρώτησεν αὐτὸν εἰ καταλύσεται τὸν πόλεμον ἐφ’ οἷς ὡμολόγησεν Ἀρχέλαος· σιωπῶντος δὲ τοῦ βασιλέως, ὁ Σύλλας ἀλλὰ μήν, ἔφη, τῶν δεομένων ἐστὶ τὸ προτέρους λέγειν, τοῖς δὲ νικῶσιν ἐξαρκεῖ τὸ σιωπᾶν. ἐπεὶ δὲ ἀρξάμενος τῆς ἀπολογίας ὁ Μιθριδάτης ἐπειρᾶτο τοῦ πολέμου τὰ μὲν εἰς δαίμονας τρέπειν, τὰ δὲ αὐτοὺς αἰτιᾶσθαι τοὺς Ῥωμαίους, ὑπολαβὼν ὁ Σύλλας ἔφη πάλαι μὲν ἑτέρων ἀκούειν, νῦν δ’ αὐτὸς ἐγνωκέναι τὸν Μιθριδάτην δεινότατον ὄντα ῥητορεύειν, ὃς ἐπὶ πράξεσιν οὕτω πονηραῖς καὶ παρανόμοις λόγων ἐχόντων εὐπρέπειαν οὐκ ἠπόρηκεν. ἐξελέγξας δὲ τὰ πεπραγμένα πικρῶς ὑπ’ αὐτοῦ καὶ κατηγορήσας, πάλιν ἠρώτησεν εἰ ποιεῖ τὰ συγκείμενα δι’ Ἀρχελάου. φήσαντος δὲ ποιεῖν, οὕτως ἠσπάσατο καὶ περιλαβὼν ἐφίλησεν αὐτόν, Ἀριοβαρζάνην δὲ αὖθις καὶ Νικομήδην τοὺς βασιλεῖς προσαγαγὼν διήλλαξεν. ὁ μὲν οὖν Μιθριδάτης ἑβδομήκοντα ναῦς παραδοὺς καὶ τοξότας πεντακοσίους εἰς Πόντον ἀπέπλευσεν.", "st": "Sull. 24.1"}, {"sp": "N", "t": "ὁ δὲ Σύλλας, αἰσθόμενος ἀχθομένους τοὺς στρατιώτας τῇ διαλύσει τὸν γὰρ ἔχθιστον τῶν βασιλέων καὶ δεκαπέντε μυριάδας ἡμέρᾳ μιᾷ τῶν ἐν Ἀσίᾳ Ῥωμαίων κατασφαγῆναι παρασκευάσαντα δεινὸν ἡγοῦντο μετὰ πλούτου καὶ λαφύρων ὁρᾶν ἐκπλέοντα τῆς Ἀσίας, ἣν ἔτη τέσσαρα λεηλατῶν καὶ φορολογῶν διετέλεσεν, ἀπελογεῖτο πρὸς αὐτοὺς ὡς οὐκ ἂν ἅμα Φιμβρίᾳ καὶ Μιθριδάτῃ πολεμεῖν, εἰ συνέστησαν ἀμφότεροι κατ’ αὐτοῦ, δυνηθείς.", "st": "Sull. 24.4"}, {"sp": "N", "t": "ὁρμήσας δὲ ἐκεῖθεν ἐπὶ Φιμβρίαν πρὸς Θυατείροις στρατοπεδεύοντα καὶ πλησίον καταζεύξας, τάφρον τῷ στρατοπέδῳ περιέβαλεν. οἱ δὲ τοῦ Φιμβρίου στρατιῶται μονοχίτωνες ἐκ τοῦ στρατοπέδου προϊόντες ἠσπάζοντο τοὺς ἐκείνου καὶ συνελάμβανον αὐτοῖς τῶν ἔργων προθύμως. ὁρῶν δὲ ὁ Φιμβρίας τὴν μεταβολὴν καὶ τὸν Σύλλαν ὡς ἀδιάλλακτον δεδοικὼς αὐτὸς ἑαυτὸν ἐν τῷ στρατοπέδῳ διέφθειρε.", "st": "Sull. 25.1"}, {"sp": "N", "t": "Σύλλας δὲ κοινῇ μὲν ἐζημίωσε τὴν Ἀσίαν δισμυρίοις ταλάντοις, ἰδίᾳ δὲ τοὺς οἴκους ἐξέτριψεν ὕβρει καὶ πολιορκίᾳ τῶν ἐπισταθμευόντων. ἐτέτακτο γὰρ ἑκάστης ἡμέρας τῷ καταλύτῃ τὸν ξένον διδόναι τέσσαρα τετράδραχμα καὶ παρέχειν δεῖπνον αὐτῷ καὶ φίλοις, ὅσους ἂν ἐθέλῃ καλεῖν, ταξίαρχον δὲ πεντήκοντα δραχμὰς λαμβάνειν τῆς ἡμέρας, ἐσθῆτα δὲ ἄλλην μὲν οἰκουρῶν, ἄλλην δὲ εἰς ἀγορὰν προερχόμενος.", "st": "Sull. 25.2"}, {"sp": "N", "t": "ἀναχθεὶς δὲ πάσαις ταῖς ναυσὶν ἐξ Ἐφέσου τριταῖος ἐν Πειραιεῖ καθωρμίσθη καὶ μυηθεὶς ἐξεῖλεν ἑαυτῷ τὴν Ἀπελλικῶνος τοῦ Τηΐου βιβλιοθήκην, ἐν ᾗ τὰ πλεῖστα τῶν Ἀριστοτέλους καὶ Θεοφράστου βιβλίων ἦν, οὔπω τότε σαφῶς γνωριζόμενα τοῖς πολλοῖς, λέγεται δὲ κομισθείσης αὐτῆς εἰς Ῥώμην Τυραννίωνα τὸν γραμματικὸν ἐνσκευάσασθαι τὰ πολλά, καὶ παρ’ αὐτοῦ τὸν Ῥόδιον Ἀνδρόνικον εὐπορήσαντα τῶν ἀντιγράφων εἰς μέσον θεῖναι καὶ ἀναγράψαι τοὺς νῦν φερομένους πίνακας. οἱ δὲ πρεσβύτεροι Περιπατητικοὶ φαίνονται μὲν καθ’ ἑαυτοὺς γενόμενοι χαρίεντες καὶ φιλολόγοι, τῶν δὲ Ἀριστοτέλους καὶ Θεοφράστου γραμμάτων οὔτε πολλοῖς οὔτε ἀκριβῶς ἐντετυχηκότες διὰ τὸ τὸν Νηλέως τοῦ Σκηψίου κλῆρον, ᾧ τὰ βιβλία κατέλιπε Θεόφραστος, εἰς ἀφιλοτίμους καὶ ἰδιώτας ἀνθρώπους περιγενέσθαι.", "st": "Sull. 26.1"}, {"sp": "N", "t": "Σύλλᾳ δὲ διατρίβοντι περὶ τὰς Ἀθήνας ἄλγημα ναρκῶδες μετὰ βάρους εἰς τοὺς πόδας ἐνέπεσεν, ὅ φησιν ὁ Στράβων ποδάγρας ψελλισμὸν εἶναι. διαπλεύσας οὖν εἰς Αἴδηψον ἐχρῆτο τοῖς θερμοῖς ὕδασι, ῥᾳθυμῶν ἅμα καὶ συνδιημερεύων τοῖς περὶ τὸν Διόνυσον τεχνίταις. περιπατοῦντος δὲ πρὸς τὴν θάλατταν ἁλιεῖς τινες ἰχθῦς αὐτῷ παγκάλους προσήνεγκαν. ἡσθεὶς δὲ τοῖς δώροις, καὶ πυθόμενος ὡς ἐξ Ἁλῶν εἶεν, ἔτι γὰρ ζῇ τις Ἁλαίων; ἔφη· ἐτύγχανε γάρ, ὅτε τὴν πρὸς Ὀρχομενῷ μάχην νενικηκὼς ἐδίωκε τοὺς πολεμίους, ἅμα τρεῖς πόλεις τῆς Βοιωτίας, Ἀνθηδόνα, Λάρυμναν, Ἁλὰς ἀνῃρηκώς. τῶν δ’ ἀνθρώπων ὑπὸ δέους ἀφώνων γενομένων, διαμειδιάσας ἐκέλευσεν ἀπιέναι χαίροντας, ὡς οὐ μετὰ φαύλων οὐδὲ ἀξίων ὀλιγωρίας ἥκοντας παραιτητῶν. Ἁλαῖοι μὲν ἐκ τούτου λέγουσι θαρρήσαντες αὖθις εἰς τὴν πόλιν συνελθεῖν.", "st": "Sull. 26.3"}, {"sp": "N", "t": "Σύλλας δὲ διὰ Θετταλίας καὶ Μακεδονίας καταβὰς ἐπὶ θάλατταν παρεσκευάζετο χιλίαις ναυσὶ καὶ διακοσίαις ἀπὸ Δυρραχίου διαβάλλειν εἰς Βρεντέσιον. ἡ δὲ Ἀπολλωνία πλησίον ἐστί, καὶ πρὸς αὕτη τὸ Νύμφαιον, ἱερὸς τόπος ἐκ χλοερᾶς νάπης καὶ λειμώνων ἀναδιδοὺς πυρὸς πηγὰς σποράδας ἐνδελεχῶς ῥέοντος. ἐνταῦθά φασι κοιμώμενον ἁλῶναι σάτυρον, οἷον οἱ πλάσται καὶ γραφεῖς εἰκάζουσιν, ἀχθέντα δὲ ὡς Σύλλαν ἐρωτᾶσθαι δι’ ἑρμηνέων πολλῶν ὅστις εἴη· φθεγξαμένου δὲ μόλις οὐδὲν συνετῶς, ἀλλὰ τραχεῖάν τινα καὶ μάλιστα μεμιγμένην ἵππου τε χρεμετισμῷ καὶ τράγου μηκασμῷ φωνὴν ἀφέντος, ἐκπλαγέντα τὸν Σύλλαν ἀποδιοπομπήσασθαι.", "st": "Sull. 27.1"}, {"sp": "N", "t": "μέλλοντος δὲ τοὺς στρατιώτας διαπεραιοῦν, καὶ δεδιότος μὴ τῆς Ἰταλίας ἐπιλαβόμενοι κατὰ πόλεις ἕκαστοι διαρρυῶσι, πρῶτον μὲν ὤμοσαν ἀφ’ αὑτῶν παραμενεῖν καὶ μηδὲν ἑκουσίως κακουργήσειν τὴν Ἰταλίαν, ἔπειτα χρημάτων δεόμενον πολλῶν ὁρῶντες, ἀπήρχοντο καὶ συνεισέφερον ὡς ἕκαστος εἶχεν εὐπορίας. οὐ μὴν ἐδέξατο τὴν ἀπαρχὴν ὁ Σύλλας, ἀλλ’ ἐπαινέσας καὶ παρορμήσας διέβαινεν, ὥς φησιν αὐτός, ἐπὶ πεντεκαίδεκα στρατηγοὺς πολεμίους πεντήκοντα καὶ τετρακοσίας σπείρας ἔχοντας, ἐκδηλότατα τοῦ θεοῦ τὰς εὐτυχίας προσημαίνοντος αὐτῷ.", "st": "Sull. 27.3"}, {"sp": "N", "t": "θύσαντος μὲν γὰρ εὐθέως ᾗ διέβη περὶ Τάραντα, δάφνης στεφάνου τύπον ἔχων ὁ λοβὸς ὤφθη, καὶ λημνίσκων δύο κατηρτημένων, μικρὸν δὲ πρὸ τῆς διαβάσεως ἐν Καμπανίᾳ περὶ τὸ Τίφατον ὄρος ἡμέρας ὤφθησαν δύο τράγοι μεγάλοι συμφερόμενοι καὶ πάντα δρῶντες καὶ πάσχοντες ἃ συμβαίνει μαχομένοις ἀνθρώποις. ἦν δὲ ἄρα φάσμα, καὶ κατὰ μικρὸν αἰρόμενον ἀπὸ γῆς διεσπείρετο πολλαχοῦ τοῦ ἀέρος εἰδώλοις ἀμαυροῖς ὅμοιον, εἶτα οὕτως ἠφανίσθη. καὶ μετ’ οὐ πολὺν χρόνον ἐν τῷ τόπῳ τούτῳ Μαρίου τοῦ νέου καὶ Νορβανοῦ τοῦ ὑπάτου μεγάλας δυνάμεις ἐπαγαγόντων, ὁ Σύλλας οὔτε τάξιν ἀποδοὺς οὔτε λοχίσας τὸ οἰκεῖον στράτευμα, ῥώμῃ δὲ προθυμίας κοινῆς καὶ φορᾷ τόλμης ἀποχρησάμενος ἐτρέψατο τοὺς πολεμίους καὶ κατέκλεισεν εἰς Καπύην πόλιν τὸν Νορβανόν, ἑπτακισχιλίους ἀποκτείνας.", "st": "Sull. 27.4"}, {"sp": "N", "t": "τοῦτο αἴτιον αὐτῷ γενέσθαι φησὶ τοῦ μὴ διαλυθῆναι τοὺς στρατιώτας κατὰ πόλεις, ἀλλὰ συμμεῖναι καὶ καταφρονῆσαι τῶν ἐναντίων πολλαπλασίων ὄντων, ἐν δὲ Σιλβίῳ φησὶν οἰκέτην Ποντίου θεοφόρητον ἐντυχεῖν αὐτῷ λέγοντα παρὰ τῆς Ἐνυοῦς κράτος πολέμου καὶ νίκην ἀπαγγέλλειν εἰ δὲ μὴ σπεύσειεν, ἐμπεπρήσεσθαι τὸ Καπιτώλιον ὃ καὶ συμβῆναι τῆς ἡμέρας ἐκείνης ἧς ὁ ἄνθρωπος προηγόρευσεν ἦν δὲ αὕτη πρὸ μιᾶς νωνῶν Κυντιλίων, ἃς νῦν Ἰουλίας καλοῦμεν. ἔτι δὲ Μάρκος Λεύκολλος, εἷς τῶν ὑπὸ Σύλλᾳ στρατηγούντων, περὶ Φιδεντίαν ἑκκαίδεκα σπείραις πρὸς πεντήκοντα τῶν πολεμίων ἀντιταχθεὶς τῇ μὲν προθυμίᾳ τῶν στρατιωτῶν ἐπίστευεν, ἀνόπλους δὲ τοὺς πολλοὺς ἔχων ὤκνει. βουλευομένου δὲ αὐτοῦ καὶ διαμέλλοντος, ἀπὸ τοῦ πλησίον πεδίου λειμῶνα ἔχοντος αὔρα φέρουσα μαλακὴ πολλὰ τῶν ἀνθέων ἐπέβαλε τῇ στρατιᾷ καὶ κατέσπειρεν, αὐτομάτως ἐπιμένοντα καὶ περιπίπτοντα τοῖς θυρεοῖς καὶ τοῖς κράνεσιν αὑτῶν, ὥστε φαίνεσθαι τοῖς πολεμίοις ἐστεφανωμένους. γενόμενοι δὲ ὑπὸ τούτου προθυμότεροι συνέβαλον καὶ νικήσαντες ὀκτακισχιλίους ἐπὶ μυρίοις ἀπέκτειναν καὶ τὸ στρατόπεδον εἷλον. οὗτος ὁ Λεύκολλος ἀδελφὸς ἦν Λευκόλλου τοῦ Μιθριδάτην ὕστερον καὶ Τιγράνην καταπολεμήσαντος.", "st": "Sull. 27.6"}, {"sp": "N", "t": "ὁ δὲ Σύλλας ἔτι πολλοῖς στρατοπέδοις καὶ μεγάλαις δυνάμεσι περικεχυμένους αὐτῷ τοὺς πολεμίους ὁρῶν πανταχόθεν ἥπτετο δυνάμει καὶ δι’ ἀπάτης, προκαλούμενος εἰς διαλύσεις τὸν ἕτερον τῶν ὑπάτων Σκηπίωνα. δεξαμένου δ’ ἐκείνου σύλλογοι μὲν ἐγίνοντο καὶ κοινολογίαι πλείονες, ἀεὶ δέ τινα παραγωγὴν καὶ πρόφασιν ἐμβάλλων ὁ Σύλλας διέφθειρε τοὺς περὶ Σκηπίωνα τοῖς ἑαυτοῦ στρατιώταις, ἠσκημένοις πρὸς ἀπάτην καὶ γοητείαν ἅπασαν ὥσπερ αὐτὸς ὁ ἡγεμών. εἰσιόντες γὰρ εἰς τὸν χάρακα τῶν πολεμίων καὶ ἀναμιγνυμένοι τοὺς μὲν εὐθὺς ἀργυρίῳ, τοὺς δὲ ὑποσχέσεσι, τοὺς δὲ κολακεύοντες καὶ ἀναπείθοντες προσήγοντο. τέλος δὲ τοῦ Σύλλα μετὰ σπειρῶν εἴκοσι προσελθόντος ἐγγὺς οἱ μὲν ἠσπάσαντο τοὺς τοῦ Σκηπίωνος, οἱ δὲ ἀντασπασάμενοι προσεχώρησαν ὁ δὲ Σκηπίων ἔρημος ἐν τῇ σκηνῇ ληφθεὶς ἠφείθη, Σύλλας δὲ ταῖς εἴκοσι σπείραις ὥσπερ ἠθάσιν ὄρνισι τεσσαράκοντα τὰς τῶν πολεμίων παλεύσας ἀπήγαγεν εἰς τὸ στρατόπεδον ἅπαντας, ὅτε καὶ Κάρβωνά φασιν εἰπεῖν ὡς ἀλώπεκι καὶ λέοντι πολεμῶν ἐν τῇ Σύλλα ψυχῇ κατοικοῦσιν ὑπὸ τῆς ἀλώπεκος ἀνιῷτο μᾶλλον.", "st": "Sull. 28.1"}, {"sp": "N", "t": "ἐκ τούτου περὶ Σίγνιον Μάριος ὀγδοήκοντα καὶ πέντε σπείρας ἔχων προὐκαλεῖτο Σύλλαν. ὁ δὲ καὶ πάνυ πρόθυμος ἦν διαγωνίσασθαι κατ’ ἐκείνην τὴν ἡμέραν ἐτύγχανε γὰρ ὄψιν ἑωρακὼς τοιάνδε κατὰ τοὺς ὕπνους. ἐδόκει τὸν γέροντα Μάριον τεθνηκότα πάλαι τῷ παιδὶ Μαρίῳ παραινεῖν φυλάξασθαι τὴν ἐπιοῦσαν ἡμέραν ὡς μεγάλην αὐτῷ δυστυχίαν φέρουσαν. διὰ τοῦτο μὲν δὴ πρόθυμος ὁ Σύλλας ἦν μάχεσθαι, καὶ μετεπέμπετο τὸν Δολοβέλλαν ἄπωθεν στρατοπεδεύοντα. τῶν δὲ πολεμίων ἐφισταμένων ταῖς ὁδοῖς καὶ ἀποφραττόντων οἱ τοῦ Σύλλα προσμαχόμενοι καὶ ὁδοποιοῦντες ἔκαμνον καὶ πολὺς ὄμβρος ἅμα τοῖς ἔργοις ἐπιγενόμενος μᾶλλον ἐκάκωσεν αὐτούς, ὅθεν οἱ ταξίαρχοι προσιόντες τῷ Σύλλᾳ ἐδέοντο τὴν μάχην ἀναβαλέσθαι, δεικνύντες ἅμα τοὺς στρατιώτας ἐρριμμένους ὑπὸ κόπου καὶ προσαναπαυομένους χαμᾶζε τοῖς θυρεοῖς κεκλιμένοις. ἐπεὶ δὲ συνεχώρησεν ἄκων καὶ πρόσταγμα καταζεύξεως ἔδωκεν, ἀρχομένων αὐτῶν τὸν χάρακα βάλλειν καὶ τάφρον ὀρύσσειν πρὸ τῆς στρατοπεδείας, ἐπήλαυνε σοβαρῶς ὁ Μάριος προϊππεύων ὡς ἀτάκτους καὶ τεθορυβημένους διασκεδάσων. ἐνταῦθα τῷ Σύλλᾳ τὴν κατὰ τοὺς ὕπνους φωνὴν ὁ δαίμων συνετέλει. ὀργὴ γὰρ αὐτοῦ τοῖς στρατιώταις παρέστη, καὶ παυσάμενοι τῶν ἔργων τοὺς μὲν ὑσσοὺς κατέπηξαν ἐπὶ τῇ τάφρῳ, σπασάμενοι δὲ τὰ ξίφη καὶ συναλαλάξαντες ἐν χερσὶν ἦσαν τῶν πολεμίων. οἱ δὲ οὐ πολὺν ὑπέστησαν χρόνον, ἀλλὰ γίνεται πολὺς φόνος αὐτῶν τραπέντων. Μάριος δὲ φεύγων εἰς Πραινεστὸν ἤδη τὰς πύλας εὗρε κεκλειμένας· καλωδίου δὲ ἄνωθεν ἀφεθέντος ἐνζώσας ἑαυτὸν ἀνελήφθη πρὸς τὸ τεῖχος, ἔνιοι δέ φασιν, ὧν καὶ Φαινεστέλλας ἐστίν, οὐδὲ αἰσθέσθαι τῆς μάχης τὸν Μάριον, ἀλλ’ ἐξ ἀγρυπνιῶν καὶ κόπων ὑπὸ σκιᾷ τινι χαμαὶ κατακλινέντα τοῦ συνθήματος δοθέντος ἐνδοῦναι πρὸς ὕπνον, εἶτα μόλις ἐξεγείρεσθαι τῆς φυγῆς γενομένης. ἐν ταύτῃ τῇ μάχῃ Σύλλας φησὶν εἰκοσιτρεῖς μόνους ἀποβαλεῖν, ἀποκτεῖναι δὲ τῶν πολεμίων δισμυρίους καὶ λαβεῖν ζῶντας ὀκτακισχιλίους. καὶ τἆλλα δὲ ὁμοίως εὐτυχεῖτο διὰ τῶν στρατηγῶν, Πομπηΐου, Κράσσου, Μετέλλου, Σερουϊλίου. οὐδὲν γὰρ ἢ μικρὰ προσκρούσαντες οὗτοι μεγάλας συνέτριψαν δυνάμεις τῶν πολεμίων, ὥστε τὸν μάλιστα τὴν ἐναντίαν στάσιν συνέχοντα Κάρβωνα νύκτωρ ἀποδράντα τὴν ἑαυτοῦ στρατιὰν εἰς Λιβύην ἐκπλεῦσαι.", "st": "Sull. 28.4"}, {"sp": "N", "t": "τὸν μέντοι τελευταῖον ἀγῶνα καθάπερ ἔφεδρος ἀθλητῇ καταπόνῳ προσενεχθεὶς ὁ Σαυνίτης Τελεσῖνος ἐγγὺς ἦλθε τοῦ σφῆλαι καὶ καταβαλεῖν ἐπὶ θύραις τῆς Ῥώμης. ἔσπευδε μὲν γὰρ ἅμα Λαμπωνίῳ τῷ Λευκανῷ χεῖρα πολλὴν ἀθροίσας ἐπὶ Πραινεστὸν ὡς ἐξαρπασόμενος τῆς πολιορκίας τὸν Μάριον· ἐπεὶ δὲ ᾔσθετο Σύλλαν μὲν κατὰ στόμα, Πομπήϊον δὲ κατ’ οὐρὰν βοηδρομοῦντας ἐπ’ αὐτόν, εἰργόμενος τοῦ πρόσω καὶ ὀπίσω πολεμιστὴς ἀνὴρ καὶ μεγάλων ἀγώνων ἔμπειρος ἄρας νυκτὸς ἐπ’ αὐτὴν ἐχώρει παντὶ τῷ στρατοπέδῳ τὴν Ῥώμην. καὶ μικροῦ μὲν ἐδέησεν ἐμπεσεῖν εἰς ἀφύλακτον ἀποσχὼν δὲ τῆς Κολλίνης πύλης δέκα σταδίους ἐπηυλίσατο τῇ πόλει, μεγαλοφρονῶν καὶ ταῖς ἐλπίσιν ἐπηρμένος ὡς τοσούτους ἡγεμόνας καὶ τηλικούτους κατεστρατηγηκώς. ἅμα δ’ ἡμέρᾳ τῶν λαμπροτάτων νέων ἐξιππασαμένων ἐπ’ αὐτὸν ἄλλους τε πολλοὺς καὶ Κλαύδιον Ἄππιον, εὐγενῆ καὶ ἀγαθὸν ἄνδρα, κατέβαλε, θορύβου δ’, οἷον εἰκός, ὄντος ἐν τῇ πόλει καὶ βοῆς γυναικείας καὶ διαδρομῶν ὡς ἁλισκομένων κατὰ κράτος, πρῶτος ὤφθη Βάλβος ἀπὸ Σύλλα προσελαύνων ἀνὰ κράτος ἱππεῦσιν ἑπτακοσίοις. διαλιπὼν δὲ ὅσον ἀναψῦξαι τὸν ἱδρῶτα τῶν ἵππων, εἴτ’ αὖθις ἐγχαλινώσας διὰ ταχέων ἐξήπτετο τῶν πολεμίων.", "st": "Sull. 29.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ καὶ Σύλλας ἐφαίνετο· καὶ τοὺς πρώτους εὐθὺς ἀριστᾶν κελεύων εἰς τάξιν καθίστη. πολλὰ δὲ Δολοβέλλα καὶ Τουρκουάτου δεομένων ἐπισχεῖν καὶ μὴ κατακόπους ἔχοντα τοὺς ἄνδρας ἀποκινδυνεῦσαι περὶ τῶν ἐσχάτων οὐ γὰρ Κάρβωνα καὶ Μάριον, ἀλλὰ Σαυνίτας καὶ Λευκανούς, τὰ ἔχθιστα τῇ Ῥώμῃ καὶ τὰ πολεμικώτατα φῦλα, συμφέρεσθαι, παρωσάμενος αὐτοὺς ἐκέλευσε σημαίνειν τὰς σάλπιγγας ἀρχὴν ἐφόδου, σχεδὸν εἰς ὥραν δεκάτην ἤδη τῆς ἡμέρας καταστρεφούσης. γενομένου δὲ ἀγῶνος, οἷος οὐχ ἕτερος, τὸ μὲν δεξιόν, ἐν ᾧ Κράσσος ἐτέτακτο, λαμπρῶς ἐνίκα, τῷ δὲ εὐωνύμῳ πονοῦντι καὶ κακῶς ἔχοντι Σύλλας παρεβοήθει, λευκὸν ἵππον ἔχων θυμοειδῆ καὶ ποδωκέστατον ἀφ’ οὗ γνωρίσαντες αὐτὸν δύο τῶν πολεμίων διετείνοντο τὰς λόγχας ὡς ἀφήσοντες. αὐτὸς μὲν οὖν οὐ προενόησε, τοῦ δ’ ἱπποκόμου μαστίξαντος τὸν ἵππον ἔφθη παρενεχθεὶς τοσοῦτον ὅσον περὶ τὴν οὐρὰν τοῦ ἵππου τὰς αἰχμὰς συμπεσούσας εἰς τὴν γῆν παγῆναι. λέγεται δὲ ἔχων τι χρυσοῦν Ἀπόλλωνος ἀγαλμάτιον ἐκ Δελφῶν ἀεὶ μὲν αὐτὸ κατὰ τὰς μάχας περιφέρειν ἐν τῷ κόλπῳ, ἀλλὰ καὶ τότε τοῦτο καταφιλεῖν οὕτω δὴ λέγων· ὦ Πύθιε Ἄπολλον, τὸν εὐτυχῆ Σύλλαν Κορνήλιον ἐν τοσούτοις ἀγῶσιν ἄρας λαμπρὸν καὶ μέγαν ἐνταῦθα ῥίψεις ἐπὶ θύραις τῆς πατρίδος ἀγαγών, αἴσχιστα τοῖς ἑαυτοῦ συναπολούμενον πολίταις; τοιαῦτά φασι τὸν Σύλλαν θεοκλυτοῦντα τοὺς μὲν ἀντιβολεῖν, τοῖς δὲ ἀπειλεῖν, τῶν δὲ ἐπιλαμβάνεσθαι· τέλος δὲ τοῦ εὐωνύμου συντριβέντος ἀναμιχθέντα τοῖς φεύγουσιν εἰς τὸ στρατόπεδον καταφυγεῖν, πολλοὺς ἀποβαλόντα τῶν ἑταίρων καὶ γνωρίμων, οὐκ ὀλίγοι δὲ καὶ τῶν ἐκ τῆς πόλεως ἐπὶ θέαν προελθόντες ἀπώλοντο καὶ κατεπατήθησαν, ὥστε τὴν μὲν πόλιν οἴεσθαι διαπεπρᾶχθαι, παρ’ ὀλίγον δὲ καὶ τὴν Μαρίου πολιορκίαν λυθῆναι, πολλῶν ἐκ τῆς τροπῆς ὠσαμένων ἐκεῖ καὶ τὸν ἐπὶ τῇ πολιορκίᾳ τεταγμένον Ὀφέλλαν Λουκρήτιον ἀναζευγνύναι κατὰ τάχος κελευόντων, ὡς ἀπολωλότος τοῦ Σύλλα καὶ τῆς Ῥώμης ἐχομένης ὑπὸ τῶν πολεμίων.", "st": "Sull. 29.4"}, {"sp": "N", "t": "ἤδη δὲ νυκτὸς οὔσης βαθείας ἧκον εἰς τὸ τοῦ Σύλλα στρατόπεδον παρὰ τοῦ Κράσσου δεῖπνον αὐτῷ καὶ τοῖς στρατιώταις μετιόντες· ὡς γὰρ ἐνίκησε τοὺς πολεμίους, εἰς Ἄντεμναν καταδιώξαντες ἐκεῖ κατεστρατοπέδευσαν. ταῦτ’ οὖν πυθόμενος ὁ Σύλλας, καὶ ὅτι τῶν πολεμίων οἱ πλεῖστοι διολώλασιν, ἧκεν εἰς Ἄντεμναν ἅμ’ ἡμέρᾳ, καὶ τρισχιλίων ἐπικηρυκευσαμένων πρὸς αὐτὸν ὑπέσχετο δώσειν τὴν ἀσφάλειαν, εἰ κακόν τι τοὺς ἄλλους ἐργασάμενοι πολεμίους ἔλθοιεν πρὸς αὐτόν. οἱ δὲ πιστεύσαντες ἐπέθεντο τοῖς λοιποῖς, καὶ πολλοὶ κατεκόπησαν ὑπ’ ἀλλήλων. οὐ μὴν ἀλλὰ καὶ τούτους καὶ τῶν ἄλλων τοὺς περιγενομένους εἰς ἑξακισχιλίους ἀθροίσας παρὰ τὸν ἱππόδρομον, ἐκάλει τὴν σύγκλητον εἰς τὸ τῆς Ἐνυοῦς ἱερόν. ἅμα δ’ αὐτός τε λέγειν ἐνήρχετο καὶ κατέκοπτον οἱ τεταγμένοι τοὺς ἑξακισχιλίους. κραυγῆς δέ, ὡς εἰκός, ἐν χωρίῳ μικρῷ τοσούτων σφαττομένων φερομένης καὶ τῶν συγκλητικῶν ἐκπλαγέντων, ὥσπερ ἐτύγχανε λέγων ἀτρέπτῳ καὶ καθεστηκότι τῷ προσώπῳ προσέχειν ἐκέλευσεν αὐτοὺς τῷ λόγῳ, τὰ δ’ ἔξω γινόμενα μὴ πολυπραγμονεῖν νουθετεῖσθαι γὰρ αὐτοῦ κελεύσαντος ἐνίους τῶν πονηρῶν.", "st": "Sull. 30.1"}, {"sp": "N", "t": "τοῦτο καὶ τῷ βραδυτάτῳ Ῥωμαίων νοῆσαι παρέστησεν ὡς ἀλλαγὴ τὸ χρῆμα τυραννίδος, οὐκ ἀπαλλαγὴ γέγονε. Μάριος μὲν οὖν ἀπ’ ἀρχῆς χαλεπὸς ὢν ἐπέτεινεν, οὐ μετέβαλε τῇ ἐξουσίᾳ τὴν φύσιν Σύλλας δὲ μετρίως τὰ πρῶτα καὶ πολιτικῶς ὁμιλήσας τῇ τύχῃ καὶ δόξαν ἀριστοκρατικοῦ καὶ δημωφελοῦς ἡγεμόνος παρασχών, ἔτι δὲ καὶ φιλόγελως ἐκ νέου γενόμενος καὶ πρὸς οἶκτον ὑγρός, ὥστε ῥᾳδίως ἐπιδακρύειν, εἰκότως προσετρίψατο ταῖς μεγάλαις ἐξουσίαις διαβολὴν ὡς τὰ ἤθη μένειν οὐκ ἐώσαις ἐπὶ τῶν ἐξ ἀρχῆς τρόπων, ἀλλ’ ἔμπληκτα καὶ χαῦνα καὶ ἀπάνθρωπα ποιούσαις. τοῦτο μὲν οὖν εἴτε κίνησίς ἐστι καὶ μεταβολὴ φύσεως ὑπὸ τύχης, εἴτε μᾶλλον ὑποκειμένης ἀποκάλυψις ἐν ἐξουσίᾳ κακίας, ἑτέρα τις ἂν διορίσειε πραγματεία.", "st": "Sull. 30.4"}, {"sp": "N", "t": "τοῦ δὲ Σύλλα πρὸς τὸ σφάττειν τραπομένου καὶ φόνων οὔτε ἀριθμὸν οὔτε ὅρον ἐχόντων ἐμπιπλάντος τὴν πόλιν, ἀναιρουμένων πολλῶν καὶ κατ’ ἰδίας ἔχθρας, οἷς οὐδὲν ἦν πρᾶγμα πρὸς Σύλλαν, ἐφιέντος αὐτοῦ καὶ χαριζομένου τοῖς περὶ αὐτόν, ἐτόλμησε τῶν νέων εἷς, Γάϊος Μέτελλος, ἐν τῇ συγκλήτῳ τοῦ Σύλλα πυθέσθαι τί πέρας ἔσται τῶν κακῶν, καὶ ποῖ προελθόντος αὐτοῦ δεῖ πεπαῦσθαι τὰ γινόμενα προσδοκᾶν. παραιτούμεθα γάρ, εἶπεν, οὐχ οὓς σὺ ἔγνωκας ἀναιρεῖν τῆς τιμωρίας, ἀλλὰ τῆς ἀμφιβολίας οὓς ἔγνωκας σώζειν. ἀποκριναμένου δὲ τοῦ Σύλλα μηδέπω γινώσκειν οὓς ἀφίησιν, ὑπολαβὼν ὁ Μέτελλος, οὐκοῦν, ἔφη, δήλωσον οὓς μέλλεις κολάζειν. καὶ ὁ Σύλλας ἔφη τοῦτο ποιήσειν. ἔνιοι δὲ οὐ τὸν Μέτελλον, ἀλλὰ Φουφίδιόν τινα τῶν πρὸς χάριν ὁμιλούντων τῷ Σύλλᾳ τὸ τελευταῖον εἰπεῖν λέγουσιν. ὁ δ’ οὖν Σύλλας εὐθὺς ὀγδοήκοντα προέγραψεν, οὐδενὶ τῶν ἐν τέλει κοινωσάμενος. ἀγανακτούντων δὲ πάντων, μίαν ἡμέραν διαλιπὼν ἄλλους προέγραψεν εἴκοσι καὶ διακοσίους, εἶτα τρίτῃ πάλιν οὐκ ἐλάττους. ἐπὶ δὲ τούτοις δημηγορῶν εἶπεν ὅσους μεμνημένος τυγχάνοι προγράφειν, τοὺς δὲ νῦν διαλανθάνοντας αὖθις προγράψειν. προέγραψε δὲ τῷ μὲν ὑποδεξαμένῳ καὶ διασώσαντι τὸν προγεγραμμένον, ζημίαν τῆς φιλανθρωπίας ὁρίζων θάνατον, οὐκ ἀδελφόν, οὐχ υἱόν, οὐ γονεῖς ὑπεξελόμενος, τῷ δὲ ἀποκτείναντι γέρας δύο τάλαντα τῆς ἀνδροφονίας, κἂν δοῦλος δεσπότην κἂν πατέρα υἱὸς ἀνέλῃ. ὃ δὲ πάντων ἀδικώτατον ἔδοξε, τῶν γὰρ προγεγραμμένων ἠτίμωσε καὶ υἱοὺς καὶ υἱωνούς, καὶ τὰ χρήματα πάντων ἐδήμευσε. προεγράφοντο δὲ οὐκ ἐν Ῥώμῃ μόνον, ἀλλὰ καὶ ἐν πάσῃ πόλει τῆς Ἰταλίας· καὶ φονευομένων οὔτε ναὸς ἦν καθαρὸς θεοῦ οὔτε ἑστία ξένιος οὔτε οἶκος πατρῷος, ἀλλὰ καὶ παρὰ γυναιξὶ γαμεταῖς ἄνδρες ἐσφάττοντο καὶ παρὰ μητράσι παῖδες. ἦσαν δὲ οἱ δι’ ὀργὴν ἀπολλύμενοι καὶ δι’ ἔχθραν οὐδὲν μέρος τῶν διὰ χρήματα σφαττομένων, ἀλλὰ καὶ λέγειν ἐπῄει τοῖς κολάζουσιν ὡς τόνδε μὲν ἀνῄρηκεν οἰκία μεγάλη, τόνδε δὲ κῆπος, ἄλλον ὕδατα θερμά. Κόϊντος δὲ Αὐρήλιος, ἀνὴρ ἀπράγμων καὶ τοσοῦτον αὐτῷ μετεῖναι τῶν κακῶν νομίζων ὅσον ἄλλοις συναλγεῖν ἀτυχοῦσιν, εἰς ἀγορὰν ἐλθὼν ἀνεγίνωσκε τοὺς προγεγραμμένους· εὑρὼν δὲ ἑαυτόν, οἴμοι τάλας, εἶπε, διώκει με τὸ ἐν Ἀλβανῷ χωρίον. καὶ βραχὺ προελθὼν ὑπό τινος ἀπεσφάγη καταδιώξαντος.", "st": "Sull. 31.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Μάριος μὲν ἁλισκόμενος ἑαυτὸν διέφθειρε, Σύλλας δὲ εἰς Πραινεστὸν ἐλθὼν πρῶτα μὲν ἰδίᾳ κατ’ ἄνδρα κρίνων ἐκόλαζεν, εἶτα ὡς οὐ σχολῆς οὔσης πάντας ἀθρόως εἰς ταὐτὸ συναγαγών, μυρίους καὶ δισχιλίους ὄντας, ἐκέλευσεν ἀποσφάττειν, μόνῳ τῷ ξένῳ διδοὺς ἄδειαν. ὁ δὲ εὐγενῶς πάνυ φήσας πρὸς αὐτὸν ὡς οὐδέποτε σωτηρίας χάριν εἴσεται τῷ φονεῖ τῆς πατρίδος, ἀναμιχθεὶς ἑκὼν συγκατεκόπη τοῖς πολίταις. ἔδοξε δὲ καινότατον γενέσθαι τὸ περὶ Λεύκιον Κατιλίναν. οὗτος γὰρ οὔπω τῶν πραγμάτων κεκριμένων ἀνῃρηκὼς ἀδελφὸν ἐδεήθη τοῦ Σύλλα τότε προγράψαι τὸν ἄνθρωπον ὡς ζῶντα καὶ προεγράφη. τούτου δὲ τῷ Σύλλᾳ χάριν ἐκτίνων Μάρκον τινὰ Μάριον τῶν ἐκ τῆς ἐναντίας στάσεως ἀποκτείνας τὴν μὲν κεφαλὴν ἐν ἀγορᾷ καθεζομένῳ τῷ Σύλλᾳ προσήνεγκε, τῷ δὲ περιρραντηρίῳ τοῦ Ἀπόλλωνος ἐγγὺς ὄντι προσελθὼν ἀπενίψατο τὰς χεῖρας.", "st": "Sull. 32.1"}, {"sp": "N", "t": "ἔξω δὲ τῶν φονικῶν καὶ τὰ λοιπὰ τοὺς ἀνθρώπους ἐλύπει. δικτάτορα μὲν γὰρ ἑαυτὸν ἀνηγόρευσε, δι’ ἐτῶν ἑκατὸν εἴκοσι τοῦτο τὸ γένος τῆς ἀρχῆς ἀναλαβών. ἐψηφίσθη δὲ αὐτῷ πάντων ἄδεια τῶν γεγονότων, πρὸς δὲ τὸ μέλλον ἐξουσία θανάτου, δημεύσεως, κληρουχιῶν, κτίσεως, πορθήσεως, ἀφελέσθαι βασιλείαν, καὶ ᾧ βούλοιτο χαρίσασθαι. τὰς δὲ διαπράσεις τῶν δεδημευμένων οἴκων οὕτως ὑπερηφάνως ἐποιεῖτο καὶ δεσποτικῶς ἐπὶ βήματος καθεζόμενος, ὥστε τῶν ἀφαιρέσεων ἐπαχθεστέρας αὐτοῦ τὰς δωρεὰς εἶναι, καὶ γυναιξὶν εὐμόρφοις καὶ λυρῳδοῖς καὶ μίμοις καὶ καθάρμασιν ἐξελευθερικοῖς ἐθνῶν χώρας καὶ πόλεων χαριζομένου προσόδους, ἐνίοις δὲ γάμους ἀκουσίως ζευγνυμένων γυναικῶν. Πομπήϊον γέ τοι βουλόμενος οἰκειώσασθαι τὸν Μάγνον, ἣν μὲν εἶχε γαμετὴν ἀφεῖναι προσέταξεν, Αἰμιλίαν δέ, Σκαύρου θυγατέρα καὶ Μετέλλης τῆς ἑαυτοῦ γυναικός, ἀποσπάσας Μανίου Γλαβρίωνος ἐγκύμονα, συνῴκισεν αὐτῷ· ἀπέθανε δὲ ἡ κόρη παρὰ τῷ Πομπηΐῳ τίκτουσα. Λουκρητίου δὲ Ὀφέλλα τοῦ Μάριον ἐκπολιορκήσαντος αἰτουμένου καὶ μετιόντος ὑπατείαν πρῶτον μὲν ἐκώλυεν ὡς δὲ ἐκεῖνος ὑπὸ πολλῶν σπουδαζόμενος εἰς τὴν ἀγορὰν ἐνέβαλε, πέμψας τινὰ τῶν περὶ αὐτὸν ἑκατονταρχῶν ἀπέσφαξε τὸν ἄνδρα, καθεξόμενος αὐτὸς ἐπὶ βήματος ἐν τῷ Διοσκουρείῳ καὶ τὸν φόνον ἐφορῶν ἄνωθεν, τῶν δὲ ἀνθρώπων τὸν ἑκατοντάρχην συλλαβόντων καὶ προσαγαγόντων τῷ βήματι, σιωπῆσαι κελεύσας τοὺς θορυβοῦντας αὐτὸς ἔφη κελεῦσαι τοῦτο, καὶ τὸν ἑκατοντάρχην ἀφεῖναι προσέταξεν.", "st": "Sull. 33.1"}, {"sp": "N", "t": "ὁ μέντοι θρίαμβος αὐτοῦ τῇ πολυτελείᾳ καὶ καινότητι τῶν βασιλικῶν λαφύρων σοβαρὸς γενόμενος μείζονα κόσμον ἔσχε καί καλὸν θέαμα τοὺς φυγάδας, οἱ γὰρ ἐνδοξότατοι καὶ δυνατώτατοι τῶν πολιτῶν ἐστεφανωμένοι παρείποντο, σωτῆρα καί πατέρα τὸν Σύλλαν ἀποκαλοῦντες, ἅτε δὴ δι’ ἐκεῖνον εἰς τὴν πατρίδα κατιόντες καί κομιζόμενοι παῖδας καί γυναῖκας. ἤδη δὲ συνῃρημένων ἁπάντων, ἀπολογισμὸν ἐν ἐκκλησίᾳ τῶν πράξεων ποιούμενος οὐκ ἐλάσσονι σπουδῇ τὰς εὐτυχίας ἢ τὰς ἀνδραγαθίας κατηριθμεῖτο, καὶ πέρας ἐκέλευσεν ἑαυτὸν ἐπὶ τούτοις Εὐτυχῆ προσαγορεύεσθαι·", "st": "Sull. 34.1"}, {"sp": "N", "t": "τοῦτο γὰρ ὁ Φῆλιξ μάλιστα βούλεται δηλοῦν αὐτὸς δὲ τοῖς Ἕλλησι γράφων καί χρηματίζων ἑαυτὸν Ἐπαφρόδιτον ἀνηγόρευε, καί παρ’ ἡμῖν ἐν τοῖς τροπαίοις οὕτως ἀναγέγραπται Λεύκιος Κορνήλιος Σύλλας Ἐπαφρόδιτος. ἔτι δὲ τῆς Μετέλλης παιδία τεκούσης δίδυμα τὸ μὲν ἄρρεν Φαῦστον, τὸ δὲ θῆλυ Φαῦσταν ὠνόμασε· τὸ γὰρ εὐτυχὲς καί ἱλαρὸν Ῥωμαῖοι φαῦστον καλοῦσιν. οὕτω δὲ ἄρα οὐ ταῖς πράξεσιν ὡς τοῖς εὐτυχήμασιν ἐπίστευεν, ὥστε, παμπόλλων μὲν ἀνῃρημένων ὑπ’ αὐτοῦ, καινοτομίας δὲ γενομένης καί μεταβολῆς ἐν τῇ πόλει τοσαύτης, ἀποθέσθαι τὴν ἀρχὴν καί τὸν δῆμον ἀρχαιρεσιῶν ὑπατικῶν ποιῆσαι κύριον, αὐτὸς δὲ μὴ προσελθεῖν, ἀλλ’ ἐν ἀγορᾷ τὸ σῶμα παρέχων τοῖς βουλομένοις ὑπεύθυνον ὥσπερ ἰδιώτης ἀναστρέφεσθαι. καί τις παρὰ γνώμην αὐτοῦ θρασὺς ἀνὴρ καὶ πολέμιος ἐπίδοξος ἦν ὕπατος αἱρεθήσεσθαι, Μάρκος Λέπιδος, οὐ δι’ ἑαυτόν, ἀλλὰ Πομπηΐῳ σπουδάζοντι καί δεομένῳ τοῦ δήμου χαριζομένου. διὸ καί χαίροντα τῇ νίκῃ τὸν Πομπήϊον ὁ Σύλλας ἰδὼν ἀπιόντα καλέσας πρὸς ἑαυτόν, ὡς καλόν, ἔφη, σοῦ τὸ πολίτευμα, ὦ νεανία, τὸ Κάτλου πρότερον ἀναγορεῦσαι Λέπιδον, τοῦ πάντων ἀρίστου τὸν ἐμπληκτότατον. ὥρα μέντοι σοι μὴ καθεύδειν ὡς ἰσχυρότερον πεποιηκότι κατὰ σαυτοῦ τὸν ἀνταγωνιστήν. τοῦτο μὲν οὖν ὁ Σύλλας ὥσπερ ἀπεθέσπισε· ταχὺ γὰρ ἐξυβρίσας ὁ Λέπιδος εἰς πόλεμον κατέστη τοῖς περὶ τὸν Πομπήϊον.", "st": "Sull. 34.3"}, {"sp": "N", "t": "Ἀποθύων δὲ τῆς οὐσίας ἁπάσης ὁ Σύλλας τῷ Ἡρακλεῖ δεκάτην ἑστιάσεις ἐποιεῖτο τῷ δήμῳ πολυτελεῖς· καὶ τοσοῦτον περιττὴ ἦν ἡ παρασκευὴ τῆς χρείας ὥστε παμπληθῆ καθ’ ἑκάστην ἡμέραν εἰς τὸν ποταμὸν ὄψα ῥιπτεῖσθαι, πίνεσθαι δὲ οἶνον ἐτῶν τεσσαράκοντα καὶ παλαιότερον. διὰ μέσου δὲ τῆς θοίνης πολυημέρου γενομένης ἀπέθνησκεν ἡ Μετέλλα νόσῳ· καὶ τῶν ἱερέων τὸν Σύλλαν οὐκ ἐώντων αὐτῇ προσελθεῖν οὐδὲ τήν οἰκίαν τῷ κήδει μιανθῆναι, γραψάμενος διάλυσιν τοῦ γάμου πρὸς αὐτὴν ὁ Σύλλας ἔτι ζῶσαν ἐκέλευσεν εἰς ἑτέραν οἰκίαν μετακομισθῆναι. καὶ τοῦτο μὲν ἀκριβῶς τὸ νόμιμον ὑπὸ δεισιδαιμονίας ἐτήρησε· τὸν δὲ τῆς ταφῆς ὁρίζοντα τήν δαπάνην νόμον αὐτὸς εἰσενηνοχὼς παρέβη, μηδενὸς ἀναλώματος φεισάμενος. παρέβαινε δὲ καὶ τὰ περὶ τῆς εὐτελείας τῶν δείπνων ὑπ’ αὐτοῦ τεταγμένα, πότοις καὶ συνδείπνοις τρυφὰς καὶ βωμολοχίας ἔχουσι παρηγορῶν τὸ πένθος.", "st": "Sull. 35.1"}, {"sp": "N", "t": "ὀλίγων δὲ μηνῶν διαγενομένων ἦν μὲν θέα μονομάχων, οὔπω δὲ τῶν τόπων διακεκριμένων, ἀλλ’ ἔτι τοῦ θεάτρου συμμιγοῦς ἀνδράσι καὶ γυναιξὶν ὄντος, ἔτυχε πλησίον τοῦ Σύλλα καθεζομένη γυνὴ τήν ὄψιν εὐπρεπὴς καὶ γένους λαμπροῦ· Μεσσάλα γὰρ ἦν θυγάτηρ, Ὁρτησίου δὲ τοῦ ῥήτορος ἀδελφή, Οὐαλλερία δὲ τοὔνομα· συνεβεβήκει δὲ αὕτη νεωστὶ πρὸς ἄνδρα διάστασις. αὕτη παρὰ τὸν Σύλλαν ἐξόπισθεν παραπορευομένη τήν τε χεῖρα πρὸς αὐτὸν ἀπηρείσατο καὶ κροκύδα τοῦ ἱματίου σπάσασα παρῆλθεν ἐπὶ τήν ἑαυτῆς χώραν, ἐμβλέψαντος δὲ τοῦ Σύλλα καὶ θαυμάσαντος, οὐδέν, ἔφη, δεινόν, αὐτόκρατορ, ἀλλὰ βούλομαι τῆς σῆς κἀγὼ μικρὸν εὐτυχίας μεταλαβεῖν. τοῦτο ἤκουσεν οὐκ ἀηδῶς ὁ Σύλλας, ἀλλὰ καὶ δῆλος εὐθὺς ἦν ὑποκεκνισμένος· ἠρώτα γὰρ ὑποπέμπων αὐτῆς ὄνομα, καὶ γένος καὶ βίον ἐμάνθανεν. ἐκ δὲ τούτων ῥίψεις ὀμμάτων ἐπ’ ἀλλήλους ἐγίνοντο καὶ παρεπιστροφαὶ συνεχεῖς προσώπων καὶ μειδιαμάτων διαδόσεις, τέλος δὲ ὁμολογίαι καὶ συνθέσεις περὶ γάμων, ἐκείνῃ μὲν ἴσως ἄμεμπτοι, Σύλλας δέ, εἰ καὶ τὰ μάλιστα σώφρονα καὶ γενναίαν, ἀλλ’ οὐκ ἐκ σώφρονος καὶ καλῆς ἔγημεν ἀρχῆς, ὄψει καὶ λαμυρίᾳ μειρακίου δίκην παραβληθείς, ὑφ’ ὧν τὰ αἴσχιστα καὶ ἀναιδέστατα πάθη κινεῖσθαι πέφυκεν.", "st": "Sull. 35.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ ταύτην ἔχων ἐπὶ τῆς οἰκίας συνῆν μίμοις γυναιξὶ καὶ κιθαριστρίαις καὶ θυμελικοῖς ἀνθρώποις, ἐπὶ στιβάδων ἀφ’ ἡμέρας συμπίνων. οὗτοι γὰρ οἱ τότε παρ’ αὐτῷ δυνάμενοι μέγιστον ἦσαν, Ῥώσκιος ὁ κωμῳδὸς καὶ Σῶριξ ὁ ἀρχιμῖμος καὶ Μητρόβιος ὁ λυσιῳδός, οὗ καίπερ ἐξώρου γενομένου διετέλει μέχρι παντὸς ἐρᾶν οὐκ ἀρνούμενος. ὅθεν καὶ τὴν νόσον ἀπ’ αἰτίας ἐλαφρᾶς ἀρξαμένην ἐξέθρεψε, καὶ πολὺν χρόνον ἠγνόει περὶ τὰ σπλάγχνα γεγονὼς ἔμπυος, ὑφ’ ἧς καὶ τὴν σάρκα διαφθαρεῖσαν εἰς φθεῖρας μετέβαλε πᾶσαν, ὥστε πολλῶν δι’ ἡμέρας ἅμα καὶ νυκτὸς ἀφαιρούντων μηδὲν εἶναι μέρος τοῦ ἐπιγινομένου τὸ ἀποκρινόμενον, ἀλλὰ πᾶσαν ἐσθῆτα καὶ λουτρὸν καὶ ἀπόνιμμα καὶ σιτίον ἀναπίμπλασθαι τοῦ ῥεύματος ἐκείνου καὶ τῆς φθορᾶς· τοσοῦτον ἐξήνθει. διὸ πολλάκις τῆς ἡμέρας εἰς ὕδωρ ἐνέβαινεν ἐκκλύζων τὸ σῶμα καὶ ἀπορρυπτόμενος. ἦν δὲ οὐδὲν ὄφελος· ἐκράτει γὰρ ἡ μεταβολὴ τῷ τάχει, καὶ περιεγίνετο παντὸς καθαρμοῦ τὸ πλῆθος.", "st": "Sull. 36.1"}, {"sp": "N", "t": "λέγεται δὲ τῶν μὲν πάνυ παλαιῶν Ἄκαστον φθειριάσαντα τὸν Πελίου τελευτῆσαι, τῶν δὲ ὑστέρων Ἀλκμᾶνα τὸν μελοποιὸν καὶ Φερεκύδην τὸν θεολόγον καὶ Καλλισθένη τὸν Ὀλύνθιον ἐν εἱρκτῇ φρουρούμενον, ἔτι δὲ Μούκιον τὸν νομικόν. εἰ δὲ δεῖ καὶ τῶν ἀπ’ οὐδενὸς μὲν χρηστοῦ γνωρίμων δὲ ἄλλως ἐπιμνησθῆναι, λέγεται τὸν ἄρξαντα τοῦ δουλικοῦ πολέμου περὶ Σικελίαν δραπέτην, Εὔνουν ὄνομα, μετὰ τὴν ἅλωσιν εἰς Ῥώμην ἀγόμενον ὑπὸ φθειριάσεως ἀποθανεῖν.", "st": "Sull. 36.4"}, {"sp": "N", "t": "ὁ δὲ Σύλλας οὐ μόνον προέγνω τὴν ἑαυτοῦ τελευτήν, ἀλλὰ τρόπον τινὰ καὶ γέγραφε περὶ αὐτῆς, τὸ γὰρ εἰκοστὸν καί δεύτερον τῶν ὑπομνημάτων πρὸ δυεῖν ἡμερῶν ἢ ἐτελεύτα γράφων ἐπαύσατο· καί φησι τοὺς Χαλδαίους αὐτῷ προειπεῖν ὡς δέοι βεβιωκότα καλῶς αὐτὸν ἐν ἀκμῇ τῶν εὐτυχημάτων καταστρέψαι· λέγει δὲ καί τὸν υἱὸν αὐτοῦ, τεθνηκότα μικρὸν ἔμπροσθεν τῆς Μετέλλης, φανῆναι κατὰ τοὺς ὕπνους ἐν ἐσθῆτι φαύλῃ παρεστῶτα καί δεόμενον τοῦ πατρὸς παύσασθαι τῶν φροντίδων, ἰόντα δὲ σὺν αὐτῷ παρὰ τὴν μητέρα Μετέλλαν ἐν ἡσυχίᾳ καί ἀπραγμόνως ζῆν μετ’ αὐτῆς, οὐ μὴν ἐπαύσατό γε τοῦ πράττειν τὰ δημόσια. δέκα μὲν γὰρ ἡμέραις ἔμπροσθεν τῆς τελευτῆς τοὺς ἐν Δικαιαρχείᾳ στασιάζοντας διαλλάξας νόμον ἔγραψεν αὐτοῖς καθ’ ὃν πολιτεύσονται· πρὸ μιᾶς δὲ ἡμέρας πυθόμενος τὸν ἄρχοντα Γράνιον, ὡς ὀφείλων δημόσιον χρέος οὐκ ἀποδίδωσιν, ἀλλ’ ἀναμένει τὴν αὐτοῦ τελευτήν, μετεπέμψατο τὸν ἄνθρωπον εἰς τὸ δωμάτιον καί περιστήσας τοὺς ὑπηρέτας ἐκέλευσε πνίγειν, τῇ δὲ κραυγῇ καί τῷ σπαραγμῷ τὸ ἀπόστημα ῥήξας πλῆθος αἵματος ἐξέβαλεν. ἐκ δὲ τούτου τῆς δυνάμεως ἐπιλιπούσης διαγαγὼν τὴν νύκτα μοχθηρῶς ἀπέθανε, δύο παῖδας ἐκ τῆς Μετέλλης νηπίους καταλιπών. ἡ γὰρ Οὐαλλερία μετὰ τὴν τελευτὴν αὐτοῦ θυγάτριον ἀπεκύησεν, ὃ Πόστουμαν ἐκάλουν τοὺς γὰρ ὕστερον τῆς τῶν πατέρων τελευτῆς γενομένους οὕτω Ῥωμαῖοι προσαγορεύουσιν.", "st": "Sull. 37.1"}, {"sp": "N", "t": "ὥρμησαν μὲν οὖν πολλοὶ καὶ συνέστησαν πρὸς Λέπιδον ὡς εἵρξοντες τὸ σῶμα κηδείας τῆς νενομισμένης· Πομπήϊος δέ, καίπερ ἐγκαλῶν τῷ Σύλλᾳ μόνον γὰρ αὐτὸν ἐν ταῖς διαθήκαις τῶν φίλων παρέλιπε, τοὺς μὲν χάριτι καὶ δεήσει, τοὺς δὲ ἀπειλῇ διακρουσάμενος εἰς Ῥώμην παρέπεμψε τὸ σῶμα, καὶ ταῖς ταφαῖς ἀσφάλειαν ἅμα καὶ τιμὴν παρέσχε. λέγεται δὲ τοσοῦτο πλῆθος ἀρωμάτων ἐπενεγκεῖν τὰς γυναῖκας αὐτῷ ὥστε ἄνευ τῶν ἐν φορήμασι δέκα καὶ διακοσίοις διακομιζομένων πλασθῆναι μὲν εἴδωλον εὐμέγεθες αὐτοῦ Σύλλα, πλασθῆναι δὲ καὶ ῥαβδοῦχον ἔκ τε λιβανωτοῦ πολυτελοῦς καὶ κινναμώμου. τῆς δὲ ἡμέρας συννεφοῦς ἕωθεν οὔσης, ὕδωρ ἐξ οὐρανοῦ προσδοκῶντες ἐνάτης ἦραν μόλις ὥρας τὸν νεκρόν. ἀνέμου δὲ λαμπροῦ καταιγίσαντος εἰς τὴν πυρὰν καὶ φλόγα πολλὴν ἐγείραντος ἔφθη τὸ σῶμα συγκομισθὲν ὅσον ἤδη τῆς πυρᾶς μαραινομένης καὶ τοῦ πυρὸς ἀπιόντος ἐκχυθῆναι πολὺν ὄμβρον καὶ κατασχεῖν ἄχρι νυκτός, ὥστε τὴν τύχην αὐτοῦ δοκεῖν τὸ σῶμα συνθάπτειν παραμένουσαν. τὸ μὲν οὖν μνημεῖον ἐν τῷ πεδίῳ τοῦ Ἄρεώς ἐστι τὸ δὲ ἐπίγραμμά φασιν αὐτὸν ὑπογραψάμενον καταλιπεῖν, οὗ κεφάλαιόν ἐστιν ὡς οὔτε τῶν φίλων τις αὐτὸν εὖ ποιῶν οὔτε τῶν ἐχθρῶν κακῶς ὑπερεβάλετο.", "st": "Sull. 38.1"}, {"sp": "HDR", "t": "Σύγκρισις Λυσάνδρου καὶ Σύλλα"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ τὸν τούτου διεληλύθαμεν βίον, ἴωμεν ἤδη πρὸς τὴν σύγκρισιν. τὸ μὲν οὖν ἀφ’ ἑαυτῶν αὐξήσεως ἀρχὴν λαβοῦσι μεγάλοις γενέσθαι κοινὸν ἀμφοτέροις ὑπῆρξεν, ἴδιον δὲ Λυσάνδρου τὸ βουλομένων τῶν πολιτῶν καὶ ὑγιαινόντων ὅσας ἔσχεν ἀρχὰς λαβεῖν, βιάσασθαι δὲ μηδὲν ἀκόντων μηδ’ ἰσχῦσαι παρὰ τοὺς νόμους.", "st": "Comp. Lys.–Sull. 1.1"}, {"sp": "N", "t": "ἐν δὲ διχοστασίῃ καὶ ὁ πάγκακος ἔλλαχε τιμῆς,", "st": "Comp. Lys.–Sull. 1.2"}, {"sp": "N", "t": "ὥσπερ ἐν Ῥώμῃ τότε διεφθαρμένου τοῦ δήμου καὶ νοσοῦντος αὐτοῖς τοῦ πολιτεύματος ἄλλος ἀλλαχόθεν ἀνίστατο δυνάστης. καὶ οὐδὲν ἦν θαυμαστὸν εἰ Σύλλας ἦρχεν, ὅτε Γλαυκίαι καὶ Σατορνῖνοι Μετέλλους ἤλαυνον ἐκ τῆς πόλεως, ὑπάτων δὲ ἀπεσφάττοντο παῖδες ἐν ἐκκλησίαις, ἀργυρίῳ δὲ καὶ χρυσίῳ τὰ ὅπλα παρελάμβανον ὠνούμενοι τοὺς στρατευομένους, πυρὶ δὲ καὶ σιδήρῳ τοὺς νόμους ἐτίθεσαν βιαζόμενοι τοὺς ἀντιλέγοντας. οὐκ αἰτιῶμαι δὲ τὸν ἐν τοιούτοις πράγμασι μέγιστον ἰσχῦσαι διαπραξάμενον, ἀλλὰ σημεῖον οὐ τίθεμαι τοῦ βέλτιστον εἶναι τὸ γενέσθαι πρῶτον οὕτω πονηρὰ πραττούσης τῆς πόλεως, ὁ δὲ ἀπὸ τῆς Σπάρτης εὐνομουμένης τότε μάλιστα καὶ σωφρονούσης ἐπὶ τὰς μεγίστας ἐκπεμπόμενος ἡγεμονίας καὶ πράξεις σχεδὸν ἀρίστων ἄριστος ἐκρίνετο καὶ πρώτων πρῶτος. ὅθεν ὁ μὲν πολλάκις τὴν ἀρχὴν ἀποδοὺς τοῖς πολίταις ἀνέλαβε πολλάκις· διέμενε γὰρ ἡ τιμὴ τῆς ἀρετῆς ἔχουσα τὸ πρωτεῖον ὁ δὲ ἅπαξ αἱρεθεὶς στρατεύματος ἡγεμών, ἔτη συνεχῶς δέκα, νῦν μὲν ὕπατον, νῦν δὲ δικτάτορα ποιῶν ἑαυτόν, ἀεὶ δὲ ὢν τύραννος, ἐν τοῖς ὅπλοις ἔμενεν.", "st": "Comp. Lys.–Sull. 1.3"}, {"sp": "N", "t": "ἐπεχείρησε μὲν οὖν ὁ Λύσανδρος, ὡς εἴρηται, μεταστῆσαι τὰ περὶ τὴν πολιτείαν πρᾳότερον καὶ νομιμώτερον ἢ Σύλλας· πειθοῖ γὰρ, οὐ δι’ ὅπλων οὐδὲ πάντα συλλήβδην ἀναιρῶν, ὥσπερ ἐκεῖνος, ἀλλ’ αὐτὴν ἐπανορθούμενος τὴν κατάστασιν τῶν βασιλέων ὃ καὶ φύσει που δίκαιον ἐδόκει, τὸν ἐξ ἀρίστων ἄριστον ἄρχειν ἐν πόλει τῆς Ἑλλάδος ἡγουμένῃ δι’ ἀρετήν, οὐ δι’ εὐγένειαν. ὥσπερ γὰρ κυνηγὸς οὐ ζητεῖ τὸ ἐκ κυνός, ἀλλὰ κύνα, καὶ ἱππικὸς ἵππον, οὐ τὸ ἐξ ἵππου· τί γὰρ, ἂν ἐξ ἵππου ἡμίονος γένηται; οὕτως ὁ πολιτικὸς ἁμαρτήσεται τοῦ παντός, ἐὰν μὴ ζητῇ τὸν ἄρχοντα τίς ἐστιν, ἀλλὰ ἐκ τίνος, αὐτοί γέ τοι Σπαρτιᾶται βασιλεύοντας ἐνίους ἀφείλοντο τὴν ἀρχήν, ὡς οὐ βασιλικούς, ἀλλὰ φαύλους καὶ τὸ μηδὲν ὄντας, εἰ δὲ κακία καὶ μετά γένους ἄτιμον, οὐδ’ ἀρετὴ δι’ εὐγένειαν, ἀλλ’ ἀφ’ ἑαυτῆς ἔντιμον.", "st": "Comp. Lys.–Sull. 2.1"}, {"sp": "N", "t": "αἱ τοίνυν ἀδικίαι τῷ μὲν ὑπὲρ φίλων, τῷ δ’ ἄχρι φίλων ἐπράχθησαν. Λύσανδρος μὲν γὰρ ὁμολογεῖται τὰ πλεῖστα διὰ τοὺς ἑταίρους ἐξαμαρτεῖν καὶ τὰς πλείστας σφαγὰς ὑπὲρ τῆς ἐκείνων ἀπεργάσασθαι δυναστείας καὶ τυραννίδος· Σύλλας δὲ καὶ Πομπηΐου περιέκοψε τὸ στρατιωτικὸν φθονήσας, καὶ Δολοβέλλα τὴν ναυαρχίαν ἐπεχείρησε δοὺς ἀφελέσθαι, καὶ Λουκρήτιον Ὀφέλλαν ἀντὶ πολλῶν καὶ μεγάλων ὑπατείαν μνώμενον ἐν ὀφθαλμοῖς ἀποσφάξαι προσέταξε, φρίκην καὶ δέος ἐμποιῶν πρὸς αὑτὸν ἀνθρώποις ἅπασι διὰ τῆς τῶν φιλτάτων ἀναιρέσεως.", "st": "Comp. Lys.–Sull. 2.3"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον ἡ περὶ τὰς ἡδονὰς καὶ τὰ χρήματα σπουδὴ δείκνυσι τὸν μὲν ἡγεμονικήν, τοῦ δὲ τυραννικὴν τὴν προαίρεσιν οὖσαν. ὁ μὲν γὰρ οὐδὲν ἀκόλαστον οὐδὲ μειρακιῶδες ἐν ἐξουσίᾳ καὶ δυνάμει τηλικαύτῃ φαίνεται διαπεπραγμένος, ἀλλ’, εἰ δή τις ἄλλος, ἐκπεφευγὼς τουτὶ τὸ περίακτον οἴκοι λέοντες, ἐν ὑπαίθρῳ δὲ ἀλώπεκες. οὕτω σώφρονα καὶ Λακωνικὴν καὶ κεκολασμένην ἐπεδείκνυτο πανταχοῦ τὴν δίαιταν. ὁ δὲ οὔτε νέος ὢν περὶ τὰς ἐπιθυμίας ἐμετρίαζε διὰ τὴν πενίαν οὔτε γηράσας διὰ τὴν ἡλικίαν, ἀλλὰ τοὺς περὶ γάμων καὶ σωφροσύνης εἰσηγεῖτο νόμους τοῖς πολίταις αὐτὸς ἐρῶν καὶ μοιχεύων, ὥς φησι Σαλούστιος. ὅθεν οὕτω τὴν πόλιν πτωχὴν καὶ κενὴν ἐποίησε χρημάτων ὥστε ταῖς συμμαχίσι καὶ φίλαις πόλεσιν ἀργυρίου πωλεῖν τὴν ἐλευθερίαν καὶ τὴν αὐτονομίαν, καίτοι τοὺς πολυαργυρωτάτους οἴκους καὶ μεγίστους ὁσημέραι δημεύοντος αὑτοῦ καὶ ἀποκηρύττοντος. ἀλλὰ μέτρον οὐδὲν ἦν τῶν ῥιπτουμένων καὶ καταχορηγουμένων εἰς τοὺς κόλακας, τίνα γὰρ εἰκὸς εἶναι λογισμὸν ἢ φειδὼ πρὸς τὰς παρ’ οἶνον συνουσίας αὑτοῦ καὶ χάριτας, ὃς ἐν φανερῷ ποτε τοῦ δήμου περιεστῶτος οὐσίαν μεγάλην διαπιπράσκων τιμῆς τῆς τυχούσης εἰς ἕνα τῶν φίλων ἐκέλευε κατακηρύσσειν, ἑτέρου δὲ τὴν τιμὴν ὑπερβαλομένου καὶ τοῦ κήρυκος τὸ προστεθὲν ἀγορεύσαντος διηγανάκτησε, δεινά γε, ὦ φίλοι πολῖται, καὶ τυραννικὰ πάσχω, φάμενος, εἰ τὰ ἐμά μοι λάφυρα διαθέσθαι μὴ ἔξεστιν ὡς βούλομαι. Λύσανδρος δὲ καὶ τὰς αὐτῷ δοθείσας δωρεὰς μετὰ τῶν ἄλλων ἀπέπεμψε τοῖς πολίταις. καὶ οὐκ ἐπαινῶ τὸ ἔργον· ἴσως γὰρ ἔβλαψε τῇ κτήσει τῶν χρημάτων τὴν Σπάρτην οὗτος ὅσον οὐκ ἔβλαψε τῇ ἀφαιρέσει τὴν Ῥώμην ἐκεῖνος· ἀλλὰ τεκμήριον τοῦτο ποιοῦμαι τῆς ἀφιλοπλουτίας τοῦ ἀνδρός. ἴδιον δέ τι πρὸς τὴν ἑαυτοῦ πόλιν ἑκάτερος ἔπαθε. Σύλλας μὲν γὰρ ἀκόλαστος ὢν καὶ πολυτελὴς ἐσωφρόνιζε τοὺς πολίτας, Λύσανδρος δ’ ὧν αὐτὸς ἀπείχετο παθῶν ἐνέπλησε τὴν πόλιν, ὥστε ἁμαρτάνειν τὸν μὲν αὐτὸν ὄντα χείρονα τῶν ἰδίων νόμων, τὸν δὲ αὑτοῦ χείρονας ἀπεργαζόμενον τοὺς πολίτας· δεῖσθαι γὰρ ἐδίδαξε τὴν Σπάρτην ὧν αὐτὸς ἔμαθε μὴ προσδεῖσθαι. καὶ τὰ μὲν πολιτικὰ ταῦτα.", "st": "Comp. Lys.–Sull. 3.1"}, {"sp": "N", "t": "πολέμων δὲ ἀγῶσι καὶ στρατηγικαῖς πράξεσι καὶ πλήθει τροπαίων καὶ μεγέθει κινδύνων ἀσύγκριτος ὁ Σύλλας. ὁ μέντοι γε δύο νίκας ἐξηνέγκατο ναυμαχίαις δυσί· προσθήσω δὲ αὐτῷ τὴν Ἀθηνῶν πολιορκίαν, ἔργῳ μὲν οὐ μεγάλην, τῇ δὲ δόξῃ λαμπροτάτην γενομένην. τὰ δ’ ἐν Βοιωτίᾳ καὶ Ἁλιάρτῳ δυστυχίᾳ μὲν ἴσως ἐπράχθη τινί, κακοβουλίᾳ δὲ προσέοικεν οὐκ ἀναμείναντος ὅσον οὔπω παροῦσαν ἐκ Πλαταιῶν τὴν μεγάλην τοῦ βασιλέως δύναμιν, ἀλλὰ θυμῷ καὶ φιλοτιμίᾳ παρὰ καιρὸν ὠσαμένου πρὸς τὸ τεῖχος, ὥστε τοὺς τυχόντας ἀνθρώπους ἐκπηδήσαντας ἐν οὐδενὶ λόγῳ καταβαλεῖν αὐτόν, οὐ γὰρ ὡς Κλεόμβροτος ἐν Λεύκτροις ἀντερείδων ἐπικειμένοις τοῖς πολεμίοις, οὐδὲ ὡς Κῦρος οὐδὲ ὡς Ἐπαμεινώνδας κατέχων ἐγκεκλικότας καὶ τὸ νίκημα βεβαιούμενος πληγῇ καιρίᾳ περιέπεσεν· ἀλλ’ οὗτοι μὲν βασιλέων καὶ στρατηγῶν θάνατον ἀπέθνησκον, Λύσανδρος δὲ πελταστοῦ καὶ προδρόμου δίκην ἀκλεῶς παραναλώσας ἑαυτόν, ἐμαρτύρησε τοῖς παλαιοῖς Σπαρτιάταις ὅτι καλῶς ἐφυλάττοντο τὰς τειχομαχίας, ἐν αἷς οὐχ ὑπ’ ἀνδρὸς μόνον τοῦ τυχόντος, ἀλλὰ καὶ ὑπὸ παιδὸς καὶ γυναικὸς ἀποθανεῖν ἂν συντύχοι πληγέντα τὸν κράτιστον, ὥσπερ τὸν Ἀχιλλέα φασὶν ὑπὸ τοῦ Πάριδος ἐν ταῖς πύλαις ἀναιρεθῆναι.", "st": "Comp. Lys.–Sull. 4.1"}, {"sp": "N", "t": "Σύλλας μὲν οὖν ὅσας ἐκ παρατάξεως ἐνίκησε νίκας καὶ κατέβαλε μυριάδας πολεμίων οὐδὲ ἀριθμῆσαι ῥᾴδιόν ἐστιν αὐτὴν δὲ τὴν Ῥώμην δὶς εἷλε, καὶ τὸν Πειραιᾶ τῶν Ἀθηνῶν οὐ λιμῷ καθάπερ Λύσανδρος, ἀλλὰ πολλοῖς ἀγῶσι καὶ μεγάλοις, ἐκβαλὼν Ἀρχέλαον ἐκ τῆς γῆς ἐπὶ τὴν θάλατταν, κατέσχεν. ἔστι δὲ μέγα καὶ τὸ τῶν ἀντιστρατήγων, τρυφὴν γὰρ οἶμαι καὶ παιδιὰν πρὸς Ἀντίοχον διαναυμαχεῖν τὸν Ἀλκιβιάδου κυβερνήτην, καὶ Φιλοκλέα τὸν Ἀθηναίων ἐξαπατᾶν δημαγωγόν,", "st": "Comp. Lys.–Sull. 4.4"}, {"sp": "N", "t": "ἄδοξον, ἄκραν γλῶσσαν ἠκονημένον", "st": "Comp. Lys.–Sull. 4.4b"}, {"sp": "N", "t": "οὓς οὐκ ἂν ἱπποκόμῳ Μιθριδάτης οὐδὲ ῥαβδούχῳ Μάριος ἠξίωσε παραβαλεῖν τῶν ἑαυτοῦ. τῶν δὲ πρὸς Σύλλαν ἀνταραμένων δυναστῶν, ὑπάτων, στρατηγῶν, δημαγωγῶν, ἵνα τοὺς ἄλλους ἐάσω, τίς ἦν Ῥωμαίων Μαρίου φοβερώτερος ἢ Μιθριδάτου βασιλέων δυνατώτερος ἢ Λαμπωνίου καὶ Τελεσίνου τῶν Ἰταλικῶν μαχιμώτερος; ὧν ἐκεῖνος τὸν μὲν ἐξέβαλε, τὸν δὲ ὑπέταξε, τοὺς δὲ ἀπέκτεινε.", "st": "Comp. Lys.–Sull. 4.5"}, {"sp": "N", "t": "τὸ δὲ πάντων μέγιστον, ὡς ἐγὼ νομίζω, τῶν εἰρημένων ἐκεῖνό ἐστιν, ὅτι Λύσανδρος μὲν κατώρθου πάντα τῶν οἴκοι συναγωνιζομένων, Σύλλας δὲ φυγὰς ὢν καὶ κατεστασιασμένος ὑπὸ τῶν ἐχθρῶν, καθ’ ὃν χρόνον ἠλαύνετο μὲν αὐτοῦ γυνή, κατεσκάπτετο δὲ οἰκία, φίλοι δὲ ἀπέθνησκον, αὐτὸς ἐν Βοιωτίᾳ ταῖς ἀναριθμήτοις μυριάσι παρατασσόμενος καὶ κινδυνεύων ὑπὲρ τῆς πατρίδος, ἵστη τρόπαιον, καὶ Μιθριδάτῃ συμμαχίαν διδόντι καὶ δύναμιν ἐπὶ τοὺς ἐχθροὺς οὐδὲν οὐδαμῆ μαλακὸν ἐνέδωκεν οὐδὲ φιλάνθρωπον, ἀλλ’ οὐδὲ προσεῖπεν οὐδὲ τὴν δεξιὰν ἐνέβαλε πρότερον ἢ πυθέσθαι παρόντος ὅτι καὶ τὴν Ἀσίαν ἀφίησι καὶ τὰς ναῦς παραδίδωσι καὶ τοῖς βασιλεῦσιν ἐξίσταται καὶ Βιθυνίας καὶ Καππαδοκίας. ὧν οὐδὲν ὅλως δοκεῖ Σύλλας κάλλιον ἔργον οὐδὲ ἀπὸ μείζονος εἰργάσθαι φρονήματος, ὅτι τὸ κοινὸν τοῦ οἰκείου πρόσθεν θέμενος, καὶ καθάπερ οἱ γενναῖοι κύνες οὐκ ἀνεὶς τὸ δῆγμα καὶ τὴν λαβὴν πρότερον ἢ τὸν ἀνταγωνιστὴν ἀπειπεῖν, τότε πρὸς τὴν τῶν ἰδίων ἄμυναν ὥρμησεν. ἐπὶ πᾶσι δὲ καὶ τὸ περὶ τὰς Ἀθήνας ἔχει τινὰ ῥοπὴν εἰς ἤθους σύγκρισιν εἴγε Σύλλας μὲν ὑπὲρ τῆς Μιθριδάτου δυνάμεως καὶ ἡγεμονίας πολεμήσασαν αὐτῷ τὴν πόλιν ἑλὼν ἐλευθέραν ἀφῆκε καὶ αὐτόνομον, Λύσανδρος δὲ τοσαύτης ἡγεμονίας καὶ ἀρχῆς ἐκπεσοῦσαν οὐκ ᾤκτειρεν, ἀλλὰ καὶ τὴν δημοκρατίαν ἀφελόμενος ὠμοτάτους αὐτῇ καὶ παρανόμους ἀπέδειξε τοὺς τυράννους.", "st": "Comp. Lys.–Sull. 5.1"}, {"sp": "N", "t": "ὥρα δὴ σκοπεῖν, μὴ οὐ πολὺ τἀληθοῦς διαμαρτάνωμεν ἀποφαινόμενοι πλέονα μὲν κατωρθωκέναι Σύλλαν, ἐλάττονα δὲ ἐξημαρτηκέναι Λύσανδρον, καὶ τῷ μὲν ἐγκρατείας καὶ σωφροσύνης, τῷ δὲ στρατηγίας καὶ ἀνδρείας ἀποδιδόντες τὸ πρωτεῖον.", "st": "Comp. Lys.–Sull. 5.5"}, {"sp": "HDR", "t": "Κίμων"}, {"sp": "N", "t": "Περιπόλτας ὁ μάντις ἐκ Θετταλίας εἰς Βοιωτίαν Ὀφέλταν τὸν βασιλέα καὶ τοὺς ὑπ’ αὐτῷ λαοὺς καταγαγὼν γένος εὐδοκιμῆσαν ἐπὶ πολλοὺς χρόνους κατέλιπεν, οὗ τὸ πλεῖστον ἐν Χαιρωνείᾳ κατῴκησεν, ἣν πρώτην πόλιν ἔσχον ἐξελάσαντες τοὺς βαρβάρους. οἱ μὲν οὖν πλεῖστοι τῶν ἀπὸ τοῦ γένους φύσει μάχιμοι καὶ ἀνδρώδεις γενόμενοι καταναλώθησαν ἐν ταῖς Μηδικαῖς ἐπιδρομαῖς καὶ τοῖς Γαλατικοῖς ἀγῶσιν ἀφειδήσαντες ἑαυτῶν· λείπεται δὲ παῖς ὀρφανὸς γονέων, ὄνομα Δάμων, παρωνύμιον δὲ Περιπόλτας, πολὺ δή τι καὶ σώματος κάλλει καὶ ψυχῆς φρονήματι τοὺς καθ’ αὑτὸν ὑπεραίρων νέους, ἄλλως δ’ ἀπαίδευτος καὶ σκληρὸς τὸ ἦθος.", "st": "Cim. 1.1"}, {"sp": "N", "t": "τούτου Ῥωμαῖος ἡγεμὼν σπείρας τινὸς ἐν Χαιρωνείᾳ διαχειμαζούσης ἐρασθεὶς ἄρτι τὴν παιδικὴν ἡλικίαν παρηλλαχότος, ὡς οὐκ ἔπειθε πειρῶν καὶ διδούς, δῆλος ἦν οὐκ ἀφεξόμενος βίας, ἅτε δὴ καὶ τῆς πατρίδος ἡμῶν τότε λυπρὰ πραττούσης καὶ διὰ μικρότητα καὶ πενίαν παρορωμένης. τοῦτο δὴ δεδιὼς ὁ Δάμων, καὶ τὴν πεῖραν αὐτὴν δι’ ὀργῆς πεποιημένος, ἐπεβούλευε τῷ ἀνδρὶ καὶ συνίστη τῶν ἡλικιωτῶν τινας ἐπ’ αὐτόν, οὐ πολλοὺς ἕνεκα τοῦ λαθεῖν, ἀλλ’ οἱ σύμπαντες ἑκκαίδεκα γενόμενοι χρίονται μὲν αἰθάλῳ τὰ πρόσωπα νυκτός, ἐμπιόντες δὲ ἄκρατον ἅμ’ ἡμέρᾳ προσπίπτουσι τῷ Ῥωμαίῳ κατ’ ἀγορὰν θύοντι, καὶ καταβαλόντες αὐτόν τε καὶ τῶν περὶ αὐτὸν οὐκ ὀλίγους ἐκ τῆς πόλεως μετέστησαν. γενομένης δὲ ταραχῆς ἡ τῶν Χαιρωνέων βουλὴ συνελθοῦσα θάνατον αὐτῶν κατέγνω· καὶ τοῦτο ἦν ὑπὲρ τῆς πόλεως ἀπολόγημα πρὸς τοὺς Ῥωμαίους. ἑσπέρας δὲ τῶν ἀρχόντων, ὥσπερ ἔθος ἐστί, κοινῇ δειπνούντων οἱ περὶ τὸν Δάμωνα παρεισπεσόντες εἰς τὸ ἀρχεῖον ἀπέσφαξαν αὐτοὺς καὶ πάλιν ᾤχοντο φεύγοντες ἐκ τῆς πόλεως.", "st": "Cim. 1.3"}, {"sp": "N", "t": "ἔτυχε δὲ περὶ τὰς ἡμέρας ἐκείνας Λεύκιος Λούκουλλος ἐπί τινα πρᾶξιν μετὰ δυνάμεως παρερχόμενος. ἐπιστήσας δὲ τὴν πορείαν καὶ τῶν γεγονότων προσφάτων ὄντων ἐξέτασιν ποιησάμενος εὗρε τὴν πόλιν οὐδενὸς αἰτίαν, ἀλλὰ μᾶλλον συνηδικημένην· καὶ τοὺς στρατιώτας ἀναλαβὼν ἀπήγαγε μεθ’ ἑαυτοῦ. τὸν δὲ Δάμωνα λῃστείαις καὶ καταδρομαῖς πορθοῦντα τὴν χώραν καὶ τῇ πόλει προσκείμενον ὑπηγάγοντο πρεσβείαις καὶ ψηφίσμασι φιλανθρώποις οἱ πολῖται, κατελθόντα δὲ γυμνασίαρχον κατέστησαν· εἶτ’ ἀλειφόμενον ἐν τῷ πυριατηρίῳ διέφθειραν. ἐπὶ πολὺν δὲ χρόνον εἰδώλων τινῶν ἐν τῷ τόπῳ προφαινομένων καὶ στεναγμῶν ἐξακουομένων, ὡς οἱ πατέρες ἡμῶν λέγουσι, τὰς θύρας ἀνῳκοδόμησαν τοῦ πυριατηρίου· καὶ μέχρι νῦν οἱ τῷ τόπῳ γειτνιῶντες οἴονταί τινας ὄψεις καὶ φωνὰς ταραχώδεις φέρεσθαι. τοὺς δ’ ἀπὸ τοῦ γένους αὐτοῦ (διασώζονται γὰρ ἔνιοι, μάλιστα τῆς Φωκίδος περὶ Στεῖριν, αἰολίζοντες) ἀσβολωμένους καλοῦσι διὰ τὸ τὸν Δάμωνα πρὸς τὸν φόνον ἀσβόλῳ χρισάμενον ἐξελθεῖν.", "st": "Cim. 1.5"}, {"sp": "N", "t": "ἐπεὶ δ’ ἀστυγείτονες ὄντες Ὀρχομένιοι καὶ διάφοροι τοῖς Χαιρωνεῦσιν ἐμισθώσαντο Ῥωμαϊκὸν συκοφάντην, ὁ δ’ ὥσπερ ἑνὸς ἀνθρώπου τὸ τῆς πόλεως ὄνομα κατενεγκὼν ἐδίωκε φόνου τῶν ὑπὸ τοῦ Δάμωνος ἀνῃρημένων, ἡ δὲ κρίσις ἦν ἐπὶ τοῦ στρατηγοῦ τῆς Μακεδονίας (οὔπω γὰρ εἰς τὴν Ἑλλάδα Ῥωμαῖοι στρατηγοὺς διεπέμποντο), οἱ λέγοντες ὑπὲρ τῆς πόλεως ἐπεκαλοῦντο τὴν Λουκούλλου μαρτυρίαν, γράψαντος δὲ τοῦ στρατηγοῦ πρὸς Λούκουλλον ἐκεῖνος ἐμαρτύρησε τἀληθῆ, καὶ τὴν δίκην οὕτως ἀπέφυγεν ἡ πόλις κινδυνεύουσα περὶ τῶν μεγίστων. ἐκεῖνοι μὲν οὖν οἱ τότε σωθέντες εἰκόνα τοῦ Λουκούλλου λιθίνην ἐν ἀγορᾷ παρὰ τὸν Διόνυσον ἀνέστησαν, ἡμεῖς δ’, εἰ καὶ πολλαῖς ἡλικίαις λειπόμεθα, τὴν μὲν χάριν οἰόμεθα διατείνειν καὶ πρὸς ἡμᾶς τοὺς νῦν ὄντας, εἰκόνα δὲ πολὺ καλλίονα νομίζοντες εἶναι τῆς τὸ σῶμα καὶ τὸ πρόσωπον ἀπομιμουμένης τὴν τὸ ἦθος καὶ τὸν τρόπον ἐμφανίζουσαν, ἀναληψόμεθα τῇ γραφῇ τῶν παραλλήλων βίων τὰς πράξεις τοῦ ἀνδρός, τἀληθῆ διεξιόντες. ἀρκεῖ γὰρ ἡ τῆς μνήμης χάρις· ἀληθοῦς δὲ μαρτυρίας οὐδ’ ἂν αὐτὸς ἐκεῖνος ἠξίωσε μισθὸν λαβεῖν ψευδῆ καὶ πεπλασμένην ὑπὲρ αὐτοῦ διήγησιν.", "st": "Cim. 2.1"}, {"sp": "N", "t": "ὥσπερ γὰρ τοὺς τὰ καλὰ καὶ πολλὴν ἔχοντα χάριν εἴδη ζῳγραφοῦντας, ἂν προσῇ τι μικρὸν αὐτοῖς δυσχερές, ἀξιοῦμεν μήτε παραλιπεῖν τοῦτο τελέως μήτε ἐξακριβοῦν· τὸ μὲν γὰρ αἰσχράν, τὸ δ’ ἀνομοίαν παρέχεται τὴν ὄψιν· οὕτως, ἐπεὶ χαλεπόν ἐστι, μᾶλλον δ’ ἴσως ἀμήχανον, ἀμεμφῆ καὶ καθαρὸν ἀνδρὸς ἐπιδεῖξαι βίον, ἐν τοῖς καλοῖς ἀναπληρωτέον ὥσπερ ὁμοιότητα τὴν ἀλήθειαν. τὰς δ’ ἐκ πάθους τινὸς ἢ πολιτικῆς ἀνάγκης ἐπιτρεχούσας ταῖς πράξεσιν ἁμαρτίας καὶ κῆρας ἐλλείμματα μᾶλλον ἀρετῆς τινος ἢ κακίας πονηρεύματα νομίζοντας οὐ δεῖ πάνυ προθύμως ἐναποσημαίνειν τῇ ἱστορίᾳ καὶ περιττῶς, ἀλλ’ ὥσπερ αἰδουμένους ὑπὲρ τῆς ἀνθρωπίνης φύσεως, εἰ καλὸν οὐδὲν εἰλικρινὲς οὐδ’ ἀναμφισβήτητον εἰς ἀρετὴν ἦθος γεγονὸς ἀποδίδωσιν.", "st": "Cim. 2.4"}, {"sp": "N", "t": "ὁ δ’ οὖν Λούκουλλος ἐδόκει σκοποῦσιν ἡμῖν τῷ Κίμωνι παραβλητέος εἶναι. πολεμικοὶ γὰρ ἀμφότεροι καὶ πρὸς τοὺς βαρβάρους λαμπροί, πρᾷοι δὲ τὰ πολιτικὰ καὶ μάλιστα τῶν ἐμφυλίων στάσεων ἀναπνοὴν ταῖς πατρίσι παρασχόντες, ἕκαστος δέ τις αὐτῶν στήσαντες τρόπαια καὶ νίκας ἀνελόμενοι περιβοήτους. οὔτε γὰρ Ἑλλήνων Κίμωνος οὔτε Ῥωμαίων Λουκούλλου πρότερος οὐδεὶς οὕτω μακρὰν πολεμῶν προῆλθεν, ἔξω λόγου τιθεμένων τῶν καθ’ Ἡρακλέα καὶ Διόνυσον, εἴ τέ τι Περσέως πρὸς Αἰθίοπας ἢ Μήδους καὶ Ἀρμενίους ἢ Ἰάσονος ἔργον ἀξιόπιστον ἐκ τῶν τότε χρόνων μνήμῃ φερόμενον εἰς τοὺς νῦν ἀφῖκται. κοινὸν δέ πως αὐτῶν καὶ τὸ ἀτελὲς γέγονε τῆς στρατηγίας, ἑκατέρου μὲν συντρίψαντος, οὐδετέρου δὲ καταλύσαντος τὸν ἀνταγωνιστήν. μάλιστα δ’ ἡ περὶ τὰς ὑποδοχὰς καὶ τὰς φιλανθρωπίας ταύτας ὑγρότης καὶ δαψίλεια καὶ τὸ νεαρὸν καὶ ἀνειμένον ἐν τῇ διαίτῃ παραπλήσιον ἐπ’ ἀμφοτέρων ἰδεῖν ὑπάρχει. παραλείπομεν δ’ ἴσως καὶ ἄλλας τινὰς ὁμοιότητας, ἃς οὐ χαλεπὸν ἐκ τῆς διηγήσεως αὐτῆς συναγαγεῖν.", "st": "Cim. 3.1"}, {"sp": "N", "t": "Κίμων ὁ Μιλτιάδου μητρὸς ἦν Ἡγησιπύλης, γένος Θρᾴττης, θυγατρὸς Ὀλόρου τοῦ βασιλέως, ὡς ἐν τοῖς Ἀρχελάου καὶ Μελανθίου ποιήμασιν εἰς αὐτὸν Κίμωνα γεγραμμένοις ἱστόρηται. διὸ καὶ Θουκυδίδης ὁ ἱστορικὸς τοῖς περὶ Κίμωνα κατὰ γένος προσήκων Ὀλόρου τε πατρὸς ἦν, εἰς τὸν πρόγονον ἀναφέροντος τὴν ὁμωνυμίαν, καὶ τὰ χρυσεῖα περὶ τὴν Θρᾴκην ἐκέκτητο. καὶ τελευτῆσαι μὲν ἐν τῇ Σκαπτῇ ὕλῃ (τοῦτο δ’ ἔστι τῆς Θρᾴκης χωρίον) λέγεται φονευθεὶς ἐκεῖ, μνῆμα δ’ αὐτοῦ τῶν λειψάνων εἰς τὴν Ἀττικὴν κομισθέντων ἐν τοῖς Κιμωνείοις δείκνυται παρὰ τὸν Ἐλπινίκης τῆς Κίμωνος ἀδελφῆς τάφον. ἀλλὰ Θουκυδίδης μὲν Ἁλιμούσιος γέγονε τῶν δήμων, οἱ δὲ περὶ τὸν Μιλτιάδην Λακιάδαι.", "st": "Cim. 4.1"}, {"sp": "N", "t": "Μιλτιάδης μὲν οὖν πεντήκοντα ταλάντων ὀφλὼν δίκην καὶ πρὸς τὴν ἔκτισιν εἱρχθεὶς ἐτελεύτησεν ἐν τῷ δεσμωτηρίῳ, Κίμων δὲ μειράκιον παντάπασιν ἀπολειφθεὶς μετὰ τῆς ἀδελφῆς ἔτι κόρης οὔσης καὶ ἀγάμου τὸν πρῶτον ἠδόξει χρόνον ἐν τῇ πόλει καὶ κακῶς ἤκουεν ὡς ἄτακτος καὶ πολυπότης καὶ τῷ πάππῳ Κίμωνι προσεοικὼς τὴν φύσιν, ὃν δι’ εὐήθειάν φασι Κοάλεμον προσαγορευθῆναι. Στησίμβροτος δ’ ὁ Θάσιος περὶ τὸν αὐτὸν ὁμοῦ τι χρόνον τῷ Κίμωνι γεγονώς φησιν αὐτὸν οὔτε μουσικὴν οὔτε ἄλλο τι μάθημα τῶν ἐλευθερίων καὶ τοῖς Ἕλλησιν ἐπιχωριαζόντων ἐκδιδαχθῆναι, δεινότητός τε καὶ στωμυλίας Ἀττικῆς ὅλως ἀπηλλάχθαι, καὶ τῷ τρόπῳ πολὺ τὸ γενναῖον καὶ ἀληθὲς ἐνυπάρχειν, καὶ μᾶλλον εἶναι Πελοποννήσιον τὸ σχῆμα τῆς ψυχῆς τοῦ ἀνδρός,", "st": "Cim. 4.3"}, {"sp": "N", "t": "φαῦλον, ἄκομψον, τὰ μέγιστ’ ἀγαθόν,", "st": "Cim. 4.3b"}, {"sp": "N", "t": "κατὰ τὸν Εὐριπίδειον Ἡρακλέα· ταῦτα γὰρ ἔστι τοῖς ὑπὸ τοῦ Στησιμβρότου γεγραμμένοις ἐπειπεῖν.", "st": "Cim. 4.3c"}, {"sp": "N", "t": "ἔτι δὲ νέος ὢν αἰτίαν ἔσχε πλησιάζειν τῇ ἀδελφῇ. καὶ γὰρ οὐδ’ ἄλλως τὴν Ἐλπινίκην εὔτακτόν τινα γεγονέναι λέγουσιν, ἀλλὰ καὶ πρὸς Πολύγνωτον ἐξαμαρτεῖν τὸν ζῳγράφον· καὶ διὰ τοῦτό φασιν ἐν τῇ Πεισιανακτείῳ τότε καλουμένῃ, Ποικίλῃ δὲ νῦν στοᾷ, γράφοντα τὰς Τρῳάδας τὸ τῆς Λαοδίκης ποιῆσαι πρόσωπον ἐν εἰκόνι τῆς Ἐλπινίκης. ὁ δὲ Πολύγνωτος οὐκ ἦν τῶν βαναύσων οὐδ’ ἀπ’ ἐργολαβίας ἔγραφε τὴν στοάν, ἀλλὰ προῖκα, φιλοτιμούμενος πρὸς τὴν πόλιν, ὡς οἵ τε συγγραφεῖς ἱστοροῦσι καὶ Μελάνθιος ὁ ποιητὴς λέγει τὸν τρόπον τοῦτον·", "st": "Cim. 4.5"}, {"sp": "N", "t": "αὑτοῦ γὰρ δαπάναισι θεῶν ναοὺς ἀγοράν τε<br>Κεκροπίαν κόσμησ’ ἡμιθέων ἀρεταῖς.", "st": "Cim. 4.5b"}, {"sp": "N", "t": "εἰσὶ δ’ οἳ τὴν Ἐλπινίκην οὐ κρύφα τῷ Κίμωνι, φανερῶς δὲ γημαμένην συνοικῆσαι λέγουσιν, ἀξίου τῆς εὐγενείας νυμφίου διὰ τὴν πενίαν ἀποροῦσαν· ἐπεὶ δὲ Καλλίας τῶν εὐπόρων τις Ἀθήνησιν ἐρασθεὶς προσῆλθε τὴν ὑπὲρ τοῦ πατρὸς καταδίκην ἐκτίνειν ἕτοιμος ὢν πρὸς τὸ δημόσιον, αὐτήν τε πεισθῆναι καὶ τὸν Κίμωνα τῷ Καλλίᾳ συνοικίσαι τὴν Ἐλπινίκην.", "st": "Cim. 4.7"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ ὅλως φαίνεται τοῖς περὶ τὰς γυναῖκας ἐρωτικοῖς ὁ Κίμων ἔνοχος γενέσθαι. καὶ γὰρ Ἀστερίας τῷ γένει Σαλαμινίας καὶ πάλιν Μνήστρας τινὸς ὁ ποιητὴς Μελάνθιος μνημονεύει πρὸς τὸν Κίμωνα παίζων δι’ ἐλεγείας, ὡς σπουδαζομένων ὑπ’ αὐτοῦ. δῆλος δ’ ἐστὶ καὶ πρὸς Ἰσοδίκην τὴν Εὐρυπτολέμου μὲν θυγατέρα τοῦ Μεγακλέους, κατὰ νόμους δ’ αὐτῷ συμβιώσασαν ὁ Κίμων ἐμπαθέστερον διατεθεὶς καὶ δυσφορήσας ἀποθανούσης, εἴ τι δεῖ τεκμαίρεσθαι ταῖς γεγραμμέναις ἐπὶ παρηγορίᾳ τοῦ πένθους ἐλεγείαις πρὸς αὐτόν, ὧν Παναίτιος ὁ φιλόσοφος οἴεται ποιητὴν γεγονέναι τὸν φυσικὸν Ἀρχέλαον, οὐκ ἀπὸ τρόπου τοῖς χρόνοις εἰκάζων.", "st": "Cim. 4.8"}, {"sp": "N", "t": "τὰ δ’ ἄλλα πάντα τοῦ ἤθους ἀγαστὰ καὶ γενναῖα τοῦ Κίμωνος. οὔτε γὰρ τόλμῃ Μιλτιάδου λειπόμενος οὔτε συνέσει Θεμιστοκλέους, δικαιότερος ἀμφοῖν ὁμολογεῖται γενέσθαι, καὶ ταῖς πολεμικαῖς οὐδὲ μικρὸν ἀποδέων ἀρεταῖς ἐκείνων ἀμήχανον ὅσον ἐν ταῖς πολιτικαῖς ὑπερβαλέσθαι νέος ὢν ἔτι καὶ πολέμων ἄπειρος. ὅτε γὰρ τὸν δῆμον ἐπιόντων Μήδων Θεμιστοκλῆς ἔπειθε προέμενον τὴν πόλιν καὶ τὴν χώραν ἐκλιπόντα πρὸ τῆς Σαλαμῖνος ἐν ταῖς ναυσὶ τὰ ὅπλα θέσθαι καὶ διαγωνίσασθαι κατὰ θάλατταν, ἐκπεπληγμένων τῶν πολλῶν τὸ τόλμημα πρῶτος Κίμων ὤφθη διὰ τοῦ Κεραμεικοῦ φαιδρὸς ἀνιὼν εἰς τὴν ἀκρόπολιν μετὰ τῶν ἑταίρων ἵππου τινὰ χαλινὸν ἀναθεῖναι τῇ θεῷ, διὰ χειρῶν κομίζων, ὡς οὐδὲν ἱππικῆς ἀλκῆς, ἀλλὰ ναυμάχων ἀνδρῶν ἐν τῷ παρόντι τῆς πόλεως δεομένης. ἀναθεὶς δὲ τὸν χαλινὸν καὶ λαβὼν ἐκ τῶν περὶ τὸν ναὸν κρεμαμένων ἀσπίδων, καὶ προσευξάμενος τῇ θεῷ, κατέβαινεν ἐπὶ θάλασσαν, οὐκ ὀλίγοις ἀρχὴ τοῦ θαρρεῖν γενόμενος.", "st": "Cim. 5.1"}, {"sp": "N", "t": "ἦν δὲ καὶ τὴν ἰδέαν οὐ μεμπτός, ὡς Ἴων ὁ ποιητής φησιν, ἀλλὰ μέγας, οὔλῃ καὶ πολλῇ τριχὶ κομῶν τὴν κεφαλήν. φανεὶς δὲ καὶ κατ’ αὐτὸν τὸν ἀγῶνα λαμπρὸς καὶ ἀνδρώδης ταχὺ δόξαν ἐν τῇ πόλει μετ’ εὐνοίας ἔσχεν, ἀθροιζομένων πολλῶν πρὸς αὐτὸν καὶ παρακαλούντων ἄξια τοῦ Μαραθῶνος ἤδη διανοεῖσθαι καὶ πράσσειν. ὁρμήσαντα δ’ αὐτὸν ἐπὶ τὴν πολιτείαν ἄσμενος ὁ δῆμος ἐδέξατο, καὶ μεστὸς ὢν τοῦ Θεμιστοκλέους ἀνῆγε πρὸς τὰς μεγίστας ἐν τῇ πόλει τιμὰς καὶ ἀρχάς, εὐάρμοστον ὄντα καὶ προσφιλῆ τοῖς πολλοῖς διὰ πρᾳότητα καὶ ἀφέλειαν. οὐχ ἥκιστα δὲ αὐτὸν ηὔξησεν Ἀριστείδης ὁ Λυσιμάχου, τὴν εὐφυΐαν ἐνορῶν τῷ ἤθει, καὶ ποιούμενος οἷον ἀντίπαλον πρὸς τὴν Θεμιστοκλέους δεινότητα καὶ τόλμαν.", "st": "Cim. 5.4"}, {"sp": "N", "t": "ἐπεὶ δὲ Μήδων φυγόντων ἐκ τῆς Ἑλλάδος ἐπέμφθη στρατηγός, κατὰ θάλατταν οὔπω τὴν ἀρχὴν Ἀθηναίων ἐχόντων, ἔτι δὲ Παυσανίᾳ τε καὶ Λακεδαιμονίοις ἑπομένων, πρῶτον μὲν ἐν ταῖς στρατείαις ἀεὶ παρεῖχε τοὺς πολίτας κόσμῳ τε θαυμαστοὺς καὶ προθυμίᾳ πολὺ πάντων διαφέροντας· ἔπειτα Παυσανίου τοῖς μὲν βαρβάροις διαλεγομένου περὶ προδοσίας καὶ βασιλεῖ γράφοντος ἐπιστολάς, τοῖς δὲ συμμάχοις τραχέως καὶ αὐθαδῶς προσφερομένου καὶ πολλὰ δι’ ἐξουσίαν καὶ ὄγκον ἀνόητον ὑβρίζοντος, ὑπολαμβάνων πράως τοὺς ἀδικουμένους καὶ φιλανθρώπως ἐξομιλῶν ἔλαθεν οὐ δι’ ὅπλων τὴν τῆς Ἑλλάδος ἡγεμονίαν, ἀλλὰ λόγῳ καὶ ἤθει παρελόμενος. προσετίθεντο γὰρ οἱ πλεῖστοι τῶν συμμάχων ἐκείνῳ τε καὶ Ἀριστείδῃ τὴν χαλεπότητα καὶ ὑπεροψίαν τοῦ Παυσανίου μὴ φέροντες. οἱ δὲ καὶ τούτους ἅμα προσήγοντο καὶ τοῖς ἐφόροις πέμποντες ἔφραζον, ὡς ἀδοξούσης τῆς Σπάρτης καὶ ταραττομένης τῆς Ἑλλάδος, ἀνακαλεῖν τὸν Παυσανίαν.", "st": "Cim. 6.1"}, {"sp": "N", "t": "λέγεται δὲ παρθένον τινὰ Βυζαντίαν ἐπιφανῶν γονέων, ὄνομα Κλεονίκην, ἐπ’ αἰσχύνῃ τοῦ Παυσανίου μεταπεμπομένου, τοὺς μὲν γονεῖς ὑπ’ ἀνάγκης καὶ φόβου προέσθαι τὴν παῖδα, τὴν δὲ τῶν πρὸ τοῦ δωματίου δεηθεῖσαν ἀνελέσθαι τὸ φῶς, διὰ σκότους καὶ σιωπῆς τῇ κλίνῃ προσιοῦσαν ἤδη τοῦ Παυσανίου καθεύδοντος, ἐμπεσεῖν καὶ ἀνατρέψαι τὸ λυχνίον ἄκουσαν· τὸν δ’ ὑπὸ τοῦ ψόφου ταραχθέντα καὶ σπασάμενον τὸ παρακείμενον ἐγχειρίδιον, ὥς τινος ἐπ’ αὐτὸν ἐχθροῦ βαδίζοντος, πατάξαι καὶ καταβαλεῖν τὴν παρθένον, ἐκ δὲ τῆς πληγῆς ἀποθανοῦσαν αὐτὴν οὐκ ἐᾶν τὸν Παυσανίαν ἡσυχάζειν, ἀλλὰ νύκτωρ εἴδωλον αὐτῷ φοιτῶσαν εἰς τὸν ὕπνον ὀργῇ λέγειν τόδε τὸ ἡρῷον·", "st": "Cim. 6.4"}, {"sp": "N", "t": "στεῖχε δίκης ἆσσον· μάλα τοι κακὸν ἀνδράσιν ὕβρις.", "st": "Cim. 6.4b"}, {"sp": "N", "t": "ἐφ’ ᾧ καὶ μάλιστα χαλεπῶς ἐνεγκόντες οἱ σύμμαχοι μετὰ τοῦ Κίμωνος ἐξεπολιόρκησαν αὐτόν. ὁ δ’ ἐκπεσὼν τοῦ Βυζαντίου καὶ τῷ φάσματι ταραττόμενος, ὡς λέγεται, κατέφυγε πρὸς τὸ νεκυομαντεῖον εἰς Ἡράκλειαν, καὶ τὴν ψυχὴν ἀνακαλούμενος τῆς Κλεονίκης παρῃτεῖτο τὴν ὀργήν. ἡ δ’ εἰς ὄψιν ἐλθοῦσα ταχέως ἔφη παύσεσθαι τῶν κακῶν αὐτὸν ἐν Σπάρτῃ γενόμενον, αἰνιττομένη, ὡς ἔοικε, τὴν μέλλουσαν αὐτῷ τελευτήν. ταῦτα μὲν οὖν ὑπὸ πολλῶν ἱστόρηται.", "st": "Cim. 6.6"}, {"sp": "N", "t": "Κίμων δέ, τῶν συμμάχων ἤδη προσκεχωρηκότων αὐτῷ, στρατηγὸς εἰς Θρᾴκην ἔπλευσε, πυνθανόμενος Περσῶν ἄνδρας ἐνδόξους καὶ συγγενεῖς βασιλέως Ἠϊόνα πόλιν παρὰ τῷ Στρυμόνι κειμένην ποταμῷ κατέχοντας ἐνοχλεῖν τοῖς περὶ τὸν τόπον ἐκεῖνον Ἕλλησι. πρῶτον μὲν οὖν αὐτοὺς μάχῃ τοὺς Πέρσας ἐνίκησε καὶ κατέκλεισεν εἰς τὴν πόλιν· ἔπειτα τοὺς ὑπὲρ Στρυμόνα Θρᾷκας, ὅθεν αὐτοῖς ἐφοίτα σῖτος, ἀναστάτους ποιῶν καὶ τὴν χώραν παραφυλάττων ἅπασαν εἰς τοσαύτην ἀπορίαν τοὺς πολιορκουμένους κατέστησεν, ὥστε Βούτην τὸν βασιλέως στρατηγὸν ἀπογνόντα τὰ πράγματα τῇ πόλει πῦρ ἐνεῖναι καὶ συνδιαφθεῖραι μετὰ τῶν φίλων καὶ τῶν χρημάτων ἑαυτόν. οὕτω δὲ λαβὼν τὴν πόλιν ἄλλο μὲν οὐδὲν ἀξιόλογον ὠφελήθη, τῶν πλείστων τοῖς βαρβάροις συγκατακαέντων, τὴν δὲ χώραν εὐφυεστάτην οὖσαν καὶ καλλίστην οἰκῆσαι παρέδωκε τοῖς Ἀθηναίοις. καὶ τοὺς Ἑρμᾶς αὐτῷ τοὺς λιθίνους ὁ δῆμος ἀναθεῖναι συνεχώρησεν, ὧν ἐπιγέγραπται τῷ μὲν πρώτῳ·", "st": "Cim. 7.1"}, {"sp": "N", "t": "ἦν ἄρα κἀκεῖνοι ταλακάρδιοι, οἵ ποτε Μήδων<br>παισὶν ἐπ’ Ἠϊόνι, Στρυμόνος ἀμφὶ ῥοάς,<br>λιμόν τ’ αἴθωνα κρυερόν τ’ ἐπάγοντες Ἄρηα<br>πρῶτοι δυσμενέων εὗρον ἀμηχανίην.<br>τῷ δὲ δευτέρῳ·<br>ἡγεμόνεσσι δὲ μισθὸν Ἀθηναῖοι τάδ’ ἔδωκαν<br>ἀντ’ εὐεργεσίης καὶ μεγάλων ἀγαθῶν.", "st": "Cim. 7.4"}, {"sp": "N", "t": "μᾶλλόν τις τάδ’ ἰδὼν καὶ ἐπεσσομένων ἐθελήσει<br>ἀμφὶ περὶ ξυνοῖς πράγμασι δῆριν ἔχειν.", "st": "Cim. 7.4b"}, {"sp": "N", "t": "τῷ δὲ τρίτῳ·<br>ἔκ ποτε τῆσδε πόληος ἅμ’ Ἀτρείδῃσι Μενεσθεὺς<br>ἡγεῖτο ζάθεον Τρωϊκὸν ἐς πεδίον·", "st": "Cim. 7.5"}, {"sp": "N", "t": "ὅν ποθ’ Ὅμηρος ἔφη Δαναῶν πύκα θωρηκτάων<br>κοσμητῆρα μάχης ἔξοχον ὄντα μολεῖν.", "st": "Cim. 7.5b"}, {"sp": "N", "t": "οὕτως οὐδὲν ἀεικὲς Ἀθηναίοισι καλεῖσθαι κοσμηταῖς<br>πολέμου τ’ ἀμφὶ καὶ ἠνορέης.", "st": "Cim. 7.5c"}, {"sp": "N", "t": "ταῦτα καίπερ οὐδαμοῦ τὸ Κίμωνος ὄνομα δηλοῦντα τιμῆς ὑπερβολὴν ἔχειν ἐδόκει τοῖς τότε ἀνθρώποις. οὔτε γὰρ Θεμιστοκλῆς τοιούτου τινὸς οὔτε Μιλτιάδης ἔτυχεν, ἀλλὰ τούτῳ γε θαλλοῦ στέφανον αἰτοῦντι Σωφάνης ὁ Δεκελεὺς ἐκ μέσου τῆς ἐκκλησίας ἀναστὰς ἀντεῖπεν, οὐκ εὐγνώμονα μέν, ἀρέσασαν δὲ τῷ δήμῳ τότε φωνὴν ἀφείς· ὅταν γάρ, ἔφη, μόνος ἀγωνισάμενος, ὦ Μιλτιάδη, νικήσῃς τοὺς βαρβάρους, τότε καὶ τιμᾶσθαι μόνος ἀξίου. διὰ τί τοίνυν τὸ Κίμωνος ὑπερηγάπησαν ἔργον; ἢ ὅτι τῶν μὲν ἄλλων στρατηγούντων ὑπὲρ τοῦ μὴ παθεῖν ἠμύνοντο τοὺς πολεμίους, τούτου δὲ καὶ ποιῆσαι κακῶς ἠδυνήθησαν ἐπὶ τὴν ἐκείνων αὐτοὶ στρατεύσαντες, καὶ προσεκτήσαντο χώρας αὐτήν τε τὴν Ἠϊόνα καὶ τὴν Ἀμφίπολιν οἰκίσαντες;", "st": "Cim. 8.1"}, {"sp": "N", "t": "ὤικισαν δὲ καὶ Σκῦρον ἑλόντος Κίμωνος ἐξ αἰτίας τοιαύτης. Δόλοπες ᾤκουν τὴν νῆσον, ἐργάται κακοὶ γῆς· ληϊζόμενοι δὲ τὴν θάλασσαν ἐκ παλαιοῦ, τελευτῶντες οὐδὲ τῶν εἰσπλεόντων παρ’ αὐτοὺς καὶ χρωμένων ἀπείχοντο ξένων, ἀλλὰ Θετταλούς τινας ἐμπόρους περὶ τὸ Κτήσιον ὁρμισαμένους συλήσαντες εἷρξαν. ἐπεὶ δὲ διαδράντες ἐκ τῶν δεσμῶν οἱ ἄνθρωποι δίκην κατεδικάσαντο τῆς πόλεως Ἀμφικτυονικήν, οὐ βουλομένων τὰ χρήματα τῶν πολλῶν συνεκτίνειν, ἀλλὰ τοὺς ἔχοντας καὶ διηρπακότας ἀποδοῦναι κελευόντων, δείσαντες ἐκεῖνοι πέμπουσι γράμματα πρὸς Κίμωνα, κελεύοντες ἥκειν μετὰ τῶν νεῶν ληψόμενον τὴν πόλιν ὑπ’ αὐτῶν ἐνδιδομένην.", "st": "Cim. 8.3"}, {"sp": "N", "t": "παραλαβὼν δ’ οὕτω τὴν νῆσον ὁ Κίμων τοὺς μὲν Δόλοπας ἐξήλασε καὶ τὸν Αἰγαῖον ἠλευθέρωσε, πυνθανόμενος δὲ τὸν παλαιὸν Θησέα τὸν Αἰγέως φυγόντα μὲν ἐξ Ἀθηνῶν εἰς Σκῦρον, αὐτοῦ δ’ ἀποθανόντα δόλῳ διὰ φόβον ὑπὸ Λυκομήδους τοῦ βασιλέως, ἐσπούδασε τὸν τάφον ἀνευρεῖν. καὶ γὰρ ἦν χρησμὸς Ἀθηναίοις τὰ Θησέως λείψανα κελεύων ἀνακομίζειν εἰς ἄστυ καὶ τιμᾶν ὡς ἥρωα πρεπόντως, ἀλλ’ ἠγνόουν ὅπου κεῖται, Σκυρίων οὐχ ὁμολογούντων οὐδ’ ἐώντων ἀναζητεῖν. τότε δὴ πολλῇ φιλοτιμίᾳ τοῦ σηκοῦ μόγις ἐξευρεθέντος, ἐνθέμενος ὁ Κίμων εἰς τὴν αὑτοῦ τριήρη τὰ ὀστᾶ καὶ τἆλλα κοσμήσας μεγαλοπρεπῶς κατήγαγεν εἰς τὴν αὐτοῦ δι’ ἐτῶν σχεδὸν τετρακοσίων. ἐφ’ ᾧ καὶ μάλιστα πρὸς αὐτὸν ἡδέως ὁ δῆμος ἔσχεν.", "st": "Cim. 8.5"}, {"sp": "N", "t": "ἔθεντο δ’ εἰς μνήμην αὐτοῦ καὶ τὴν τῶν τραγῳδῶν κρίσιν ὀνομαστὴν γενομένην. πρώτην γὰρ διδασκαλίαν τοῦ Σοφοκλέους ἔτι νέου καθέντος, Ἀψεφίων ὁ ἄρχων, φιλονεικίας οὔσης καὶ παρατάξεως τῶν θεατῶν, κριτὰς μὲν οὐκ ἐκλήρωσε τοῦ ἀγῶνος, ὡς δὲ Κίμων μετὰ τῶν συστρατήγων προελθὼν εἰς τὸ θέατρον ἐποιήσατο τῷ θεῷ τὰς νενομισμένας σπονδάς, οὐκ ἀφῆκεν αὐτοὺς ἀπελθεῖν, ἀλλ’ ὁρκώσας ἠνάγκασε καθίσαι καὶ κρῖναι δέκα ὄντας, ἀπὸ φυλῆς μιᾶς ἕκαστον. ὁ μὲν οὖν ἀγὼν καὶ διὰ τὸ τῶν κριτῶν ἀξίωμα τὴν φιλοτιμίαν ὑπερέβαλε. νικήσαντος δὲ τοῦ Σοφοκλέους λέγεται τὸν Αἰσχύλον περιπαθῆ γενόμενον καὶ βαρέως ἐνεγκόντα χρόνον οὐ πολὺν Ἀθήνησι διαγαγεῖν, εἶτ’ οἴχεσθαι δι’ ὀργὴν εἰς Σικελίαν, ὅπου καὶ τελευτήσας περὶ Γέλαν τέθαπται.", "st": "Cim. 8.7"}, {"sp": "N", "t": "συνδειπνῆσαι δὲ τῷ Κίμωνί φησιν ὁ Ἴων παντάπασι μειράκιον ἥκων εἰς Ἀθήνας ἐκ Χίου παρὰ Λαομέδοντι· καὶ τῶν σπονδῶν γενομένων παρακληθέντος ᾆσαι, καὶ ᾄσαντος οὐκ ἀηδῶς ἐπαινεῖν τοὺς παρόντας ὡς δεξιώτερον Θεμιστοκλέους· ἐκεῖνον γὰρ ᾄδειν μὲν οὐ φάναι μαθεῖν οὐδὲ κιθαρίζειν, πόλιν δὲ ποιῆσαι μεγάλην καὶ πλουσίαν ἐπίστασθαι· τοὐντεῦθεν, οἷον εἰκὸς ἐν πότῳ, τοῦ λόγου ῥυέντος ἐπὶ τὰς πράξεις τοῦ Κίμωνος καὶ μνημονευομένων τῶν μεγίστων, αὐτὸν ἐκεῖνον ἓν διελθεῖν στρατήγημα τῶν ἰδίων ὡς σοφώτατον. ἐπεὶ γὰρ ἐκ Σηστοῦ καὶ Βυζαντίου πολλοὺς τῶν βαρβάρων αἰχμαλώτους λαβόντες οἱ σύμμαχοι τῷ Κίμωνι διανεῖμαι προσέταξαν, ὁ δὲ χωρὶς μὲν αὐτούς, χωρὶς δὲ τὸν περὶ τοῖς σώμασι κόσμον αὐτῶν ἔθηκεν, ᾐτιῶντο τὴν διανομὴν ὡς ἄνισον. ὁ δὲ τῶν μερίδων ἐκέλευσεν αὐτοὺς ἑλέσθαι τὴν ἑτέραν, ἣν δ’ ἂν ἐκεῖνοι καταλίπωσιν, ἀγαπήσειν Ἀθηναίους. Ἡροφύτου δὲ τοῦ Σαμίου συμβουλεύσαντος αἱρεῖσθαι τὰ Περσῶν μᾶλλον ἢ Πέρσας, τὸν μὲν κόσμον αὐτοὶ ἔλαβον, Ἀθηναίοις δὲ τοὺς αἰχμαλώτους ἀπέλιπον. καὶ τότε μὲν ὁ Κίμων ἀπῄει γελοῖος εἶναι δοκῶν διανομεύς, τῶν μὲν συμμάχων ψέλια χρυσᾶ καὶ μανιάκας καὶ στρεπτοὺς καὶ κάνδυας καὶ πορφύραν φερομένων, τῶν δ’ Ἀθηναίων γυμνὰ σώματα κακῶς ἠσκημένα πρὸς ἐργασίαν παραλαβόντων. μικρὸν δὲ ὕστερον οἱ τῶν ἑαλωκότων φίλοι καὶ οἰκεῖοι καταβαίνοντες ἐκ Φρυγίας καὶ Λυδίας ἐλυτροῦντο μεγάλων χρημάτων ἕκαστον, ὥστε τῷ Κίμωνι τεσσάρων μηνῶν τροφὰς εἰς τὰς ναῦς ὑπάρξαι καὶ προσέτι τῇ πόλει χρυσίον οὐκ ὀλίγον ἐκ τῶν λύτρων περιγενέσθαι.", "st": "Cim. 9.1"}, {"sp": "N", "t": "ἤδη δ’ εὐπορῶν ὁ Κίμων ἐφόδια τῆς στρατηγίας ἃ καλῶς ἀπὸ τῶν πολεμίων ἔδοξεν ὠφελῆσθαι κάλλιον ἀνήλισκεν εἰς τοὺς πολίτας. τῶν τε γὰρ ἀγρῶν τοὺς φραγμοὺς ἀφεῖλεν, ἵνα καὶ τοῖς ξένοις καὶ τῶν πολιτῶν τοῖς δεομένοις ἀδεῶς ὑπάρχῃ λαμβάνειν τῆς ὀπώρας, καὶ δεῖπνον οἴκοι παρ’ αὐτῷ λιτὸν μέν, ἀρκοῦν δὲ πολλοῖς, ἐποιεῖτο καθ’ ἡμέραν, ἐφ’ ὃ τῶν πενήτων ὁ βουλόμενος εἰσῄει καὶ διατροφὴν εἶχεν ἀπράγμονα, μόνοις τοῖς δημοσίοις σχολάζων. ὡς δ’ Ἀριστοτέλης φησίν, οὐχ ἁπάντων Ἀθηναίων, ἀλλὰ τῶν δημοτῶν αὐτοῦ Λακιαδῶν παρεσκευάζετο τῷ βουλομένῳ τὸ δεῖπνον. αὐτῷ δὲ νεανίσκοι παρείποντο συνήθεις ἀμπεχόμενοι καλῶς, ὧν ἕκαστος, εἴ τις συντύχοι τῷ Κίμωνι τῶν ἀστῶν πρεσβύτερος ἠμφιεσμένος ἐνδεῶς, διημείβετο πρὸς αὐτὸν τὰ ἱμάτια· καὶ τὸ γινόμενον ἐφαίνετο σεμνόν. οἱ δ’ αὐτοὶ καὶ νόμισμα κομίζοντες ἄφθονον παριστάμενοι τοῖς κομψοῖς τῶν πενήτων ἐν ἀγορᾷ σιωπῇ τῶν κερματίων ἐνέβαλλον εἰς τὰς χεῖρας. ὧν δὴ καὶ Κρατῖνος ὁ κωμικὸς ἐν Ἀρχιλόχοις ἔοικε μεμνῆσθαι διὰ τούτων·", "st": "Cim. 10.1"}, {"sp": "N", "t": "κἀγὼ γὰρ ηὔχουν Μητρόβιος ὁ γραμματεὺς<br>σὺν ἀνδρὶ θείῳ καὶ φιλοξενωτάτῳ<br>καὶ πάντ’ ἀρίστῳ τῶν Πανελλήνων πρὸ τοῦ<br>Κίμωνι λιπαρὸν γῆρας εὐωχούμενος<br>αἰῶνα πάντα συνδιατρίψειν. ὁ δὲ<br>λιπὼν βέβηκε πρότερος.", "st": "Cim. 10.4"}, {"sp": "N", "t": "ἔτι τοίνυν Γοργίας μὲν ὁ Λεοντῖνός φησι τὸν Κίμωνα τὰ χρήματα κτᾶσθαι μὲν ὡς χρῷτο, χρῆσθαι δὲ ὡς τιμῷτο, Κριτίας δὲ τῶν τριάκοντα γενόμενος ἐν ταῖς ἐλεγείαις εὔχεται·<br>πλοῦτον μὲν Σκοπαδῶν, μεγαλοφροσύνην δὲ Κίμωνος,<br>νίκας δ’ Ἀρκεσίλα τοῦ Λακεδαιμονίου.", "st": "Cim. 10.5"}, {"sp": "N", "t": "καίτοι Λίχαν γε τὸν Σπαρτιάτην ἀπ’ οὐδενὸς ἄλλου γινώσκομεν ἐν τοῖς Ἕλλησιν ὀνομαστὸν γενόμενον ἢ ὅτι τοὺς ξένους ἐν ταῖς γυμνοπαιδίαις ἐδείπνιζεν· ἡ δὲ Κίμωνος ἀφθονία καὶ τὴν παλαιὰν τῶν Ἀθηναίων φιλοξενίαν καὶ φιλανθρωπίαν ὑπερέβαλεν. οἱ μὲν γάρ, ἐφ’ οἷς ἡ πόλις μέγα φρονεῖ δικαίως, τό τε σπέρμα τῆς τροφῆς εἰς τοὺς Ἕλληνας ἐξέδωκαν ὑδάτων τε πηγαίων … καὶ πυρὸς ἔναυσιν χρῄζουσιν ἀνθρώποις ἐδίδαξαν, ὁ δὲ τὴν μὲν οἰκίαν τοῖς πολίταις πρυτανεῖον ἀποδείξας κοινόν, ἐν δὲ τῇ χώρᾳ καρπῶν ἑτοίμων ἀπαρχὰς καὶ ὅσα ὧραι καλὰ φέρουσι χρῆσθαι καὶ λαμβάνειν ἅπαντα τοῖς ξένοις παρέχων, τρόπον τινὰ τὴν ἐπὶ Κρόνου μυθολογουμένην κοινωνίαν εἰς τὸν βίον αὖθις κατῆγεν. οἱ δὲ ταῦτα κολακείαν ὄχλου καὶ δημαγωγίαν εἶναι διαβάλλοντες ὑπὸ τῆς ἄλλης ἐξηλέγχοντο τοῦ ἀνδρὸς προαιρέσεως ἀριστοκρατικῆς καὶ Λακωνικῆς οὔσης, ὅς γε καὶ Θεμιστοκλεῖ πέρα τοῦ δέοντος ἐπαίροντι τὴν δημοκρατίαν ἀντέβαινε μετ’ Ἀριστείδου, καὶ πρὸς Ἐφιάλτην ὕστερον χάριτι τοῦ δήμου καταλύοντα τὴν ἐξ Ἀρείου πάγου βουλὴν διηνέχθη, λημμάτων δὲ δημοσίων τοὺς ἄλλους πλὴν Ἀριστείδου καὶ Ἐφιάλτου πάντας ἀναπιμπλαμένους ὁρῶν, αὑτὸν ἀδέκαστον καὶ ἄθικτον ἐκ τῇ πολιτείᾳ δωροδοκίας καὶ πάντα προῖκα καὶ καθαρῶς πράττοντα καὶ λέγοντα διὰ τέλους παρέσχε.", "st": "Cim. 10.6"}, {"sp": "N", "t": "λέγεταί γέ τοι Ῥοισάκην τινὰ βάρβαρον ἀποστάτην βασιλέως ἐλθεῖν μετὰ χρημάτων πολλῶν εἰς Ἀθήνας, καὶ σπαραττόμενον ὑπὸ τῶν συκοφαντῶν καταφυγεῖν πρὸς Κίμωνα, καὶ θεῖναι παρὰ τὴν αὔλειον αὐτοῦ φιάλας δύο, τὴν μὲν ἀργυρείων ἐμπλησάμενον Δαρεικῶν, τὴν δὲ χρυσῶν· ἰδόντα δὲ τὸν Κίμωνα καὶ μειδιάσαντα πυθέσθαι τοῦ ἀνθρώπου, πότερον αἱρεῖται Κίμωνα μισθωτὸν ἢ φίλον ἔχειν· τοῦ δὲ φήσαντος φίλον οὐκοῦν, φάναι, ταῦτ’ ἄπιθι μετὰ σεαυτοῦ κομίζων· χρήσομαι γὰρ αὐτοῖς ὅταν δέωμαι φίλος γενόμενος.", "st": "Cim. 10.9"}, {"sp": "N", "t": "ἐπεὶ δ’ οἱ σύμμαχοι τοὺς φόρους μὲν ἐτέλουν, ἄνδρας δὲ καὶ ναῦς ὡς ἐτάχθησαν οὐ παρεῖχον, ἀλλ’ ἀπαγορεύοντες ἤδη πρὸς τὰς στρατείας, καὶ πολέμου μὲν οὐδὲν δεόμενοι, γεωργεῖν δὲ καὶ ζῆν καθ’ ἡσυχίαν ἐπιθυμοῦντες, ἀπηλλαγμένων τῶν βαρβάρων καὶ μὴ διοχλούντων, οὔτε τὰς ναῦς ἐπλήρουν οὔτ’ ἄνδρας ἀπέστελλον, οἱ μὲν ἄλλοι στρατηγοὶ τῶν Ἀθηναίων προσηνάγκαζον αὐτοὺς ταῦτα ποιεῖν καὶ τοὺς ἐλλείποντας ὑπάγοντες δίκαις καὶ κολάζοντες ἐπαχθῆ τὴν ἀρχὴν καὶ λυπηρὰν ἐποίουν, Κίμων δὲ τὴν ἐναντίαν ὁδὸν ἐν τῇ στρατηγίᾳ πορευόμενος βίαν μὲν οὐδενὶ τῶν Ἑλλήνων προσῆγε, χρήματα δὲ λαμβάνων παρὰ τῶν οὐ βουλομένων στρατεύεσθαι καὶ ναῦς κενάς, ἐκείνους εἴα δελεαζομένους τῇ σχολῇ περὶ τὰ οἰκεῖα διατρίβειν, γεωργοὺς καὶ χρηματιστὰς ἀπολέμους ἐκ πολεμικῶν ὑπὸ τρυφῆς καὶ ἀνοίας γινομένους, τῶν δ’ Ἀθηναίων ἀνὰ μέρος πολλοὺς ἐμβιβάζων καὶ διαπονῶν ταῖς στρατείαις ἐν ὀλίγῳ χρόνῳ τοῖς παρὰ τῶν συμμάχων μισθοῖς καὶ χρήμασι δεσπότας αὐτῶν τῶν διδόντων ἐποίησε. πλέοντας γὰρ αὐτοὺς συνεχῶς καὶ διὰ χειρὸς ἔχοντας ἀεὶ τὰ ὅπλα καὶ τρεφομένους καὶ ἀσκοῦντας ἐκ τῆς αὐτῶν ἀστρατείας ἐθισθέντες φοβεῖσθαι καὶ κολακεύειν, ἔλαθον ἀντὶ συμμάχων ὑποτελεῖς καὶ δοῦλοι γεγονότες.", "st": "Cim. 11.1"}, {"sp": "N", "t": "καὶ μὴν αὐτοῦ γε τοῦ μεγάλου βασιλέως οὐδεὶς ἐταπείνωσε καὶ συνέστειλε τὸ φρόνημα μᾶλλον ἢ Κίμων. οὐ γὰρ ἀνῆκεν ἐκ τῆς Ἑλλάδος ἀπηλλαγμένον, ἀλλ’ ὥσπερ ἐκ ποδὸς διώκων, πρὶν διαπνεῦσαι καὶ στῆναι τοὺς βαρβάρους, τὰ μὲν ἐπόρθει καὶ κατεστρέφετο, τὰ δὲ ἀφίστη καὶ προσήγετο τοῖς Ἕλλησιν, ὥστε τὴν ἀπ’ Ἰωνίας Ἀσίαν ἄχρι Παμφυλίας παντάπασι Περσικῶν ὅπλων ἐρημῶσαι. πυθόμενος δὲ τοὺς βασιλέως στρατηγοὺς μεγάλῳ στρατῷ καὶ ναυσὶ πολλαῖς ἐφεδρεύειν περὶ Παμφυλίαν, καὶ βουλόμενος αὐτοῖς ἄπλουν καὶ ἀνέμβατον ὅλως ὑπὸ φόβου τὴν ἐντὸς Χελιδονίων ποιήσασθαι θάλατταν, ὥρμησεν ἄρας ἀπὸ Κνίδου καὶ Τριοπίου διακοσίαις τριήρεσι, πρὸς μὲν τάχος ἀπ’ ἀρχῆς καὶ περιαγωγὴν ὑπὸ Θεμιστοκλέους ἄριστα κατεσκευασμέναις, ἐκεῖνος δὲ τότε καὶ πλατυτέρας ἐποίησεν αὐτὰς καὶ διάβασιν τοῖς καταστρώμασιν ἔδωκεν, ὡς ἂν ὑπὸ πολλῶν ὁπλιτῶν μαχιμώτεραι προσφέροιντο τοῖς πολεμίοις. ἐπιπλεύσας δὲ τῇ πόλει τῶν Φασηλιτῶν, Ἑλλήνων μὲν ὄντων, οὐ δεχομένων δὲ τὸν στόλον οὐδὲ βουλομένων ἀφίστασθαι βασιλέως, τήν τε χώραν κακῶς ἐποίει καὶ προσέβαλλε τοῖς τείχεσιν. οἱ δὲ Χῖοι συμπλέοντες αὐτῷ, πρὸς δὲ τοὺς Φασηλίτας ἐκ παλαιοῦ φιλικῶς ἔχοντες, ἅμα μὲν τὸν Κίμωνα κατεπράϋνον, ἅμα δὲ τοξεύοντες ὑπὲρ τὰ τείχη βιβλίδια προσκείμενα τοῖς ὀϊστοῖς ἐξήγγελλον τοῖς Φασηλίταις. τέλος δὲ διήλλαξεν αὐτούς, ὅπως δέκα τάλαντα δόντες ἀκολουθῶσι καὶ συστρατεύωσιν ἐπὶ τοὺς βαρβάρους.", "st": "Cim. 12.1"}, {"sp": "N", "t": "ἔφορος μὲν οὖν Τιθραύστην φησὶ τῶν βασιλικῶν νεῶν ἄρχειν καὶ τοῦ πεζοῦ Φερενδάτην, Καλλισθένης δ’ Ἀριομάνδην τὸν Γωβρύου κυριώτατον ὄντα τῆς δυνάμεως παρὰ τὸν Εὐρυμέδοντα ταῖς ναυσὶ παρορμεῖν, οὐκ ὄντα μάχεσθαι τοῖς Ἕλλησι πρόθυμον, ἀλλὰ προσδεχόμενον ὀγδοήκοντα ναῦς Φοινίσσας ἀπὸ Κύπρου προσπλεούσας. ταύτας φθῆναι βουλόμενος ὁ Κίμων ἀνήχθη, βιάζεσθαι παρεσκευασμένος, ἂν ἑκόντες μὴ ναυμαχῶσιν. οἱ δὲ πρῶτον μέν, ὡς μὴ βιασθεῖεν, εἰς τὸν ποταμὸν εἰσωρμίσαντο, προσφερομένων δὲ τῶν Ἀθηναίων ἀντεξέπλευσαν, ὡς ἱστορεῖ Φανόδημος, ἑξακοσίαις ναυσίν, ὡς δ’ Ἔφορος, πεντήκοντα καὶ τριακοσίαις. ἔργον δὲ κατὰ γοῦν τὴν θάλατταν οὐδὲν ὑπ’ αὐτῶν ἐπράχθη τῆς δυνάμεως ἄξιον, ἀλλ’ εὐθὺς εἰς τὴν γῆν ἀποστρέφοντες ἐξέπιπτον οἱ πρῶτοι καὶ κατέφευγον εἰς τὸ πεζὸν ἐγγὺς παρατεταγμένον, οἱ δὲ καταλαμβανόμενοι διεφθείροντο μετὰ τῶν νεῶν. ᾧ καὶ δῆλόν ἐστιν, ὅτι πάμπολλαί τινες αἱ πεπληρωμέναι τοῖς βαρβάροις νῆες ἦσαν, ὅτε πολλῶν μέν, ὡς εἰκός, ἐκφυγουσῶν, πολλῶν δὲ συντριβεισῶν, ὅμως αἰχμαλώτους διακοσίας ἔλαβον οἱ Ἀθηναῖοι.", "st": "Cim. 12.5"}, {"sp": "N", "t": "τῶν δὲ πεζῶν ἐπικαταβάντων πρὸς τὴν θάλασσαν μέγα μὲν ἔργον ἐφαίνετο τῷ Κίμωνι τὸ βιάζεσθαι τὴν ἀπόβασιν καὶ κεκμηκότας ἀκμῆσι καὶ πολλαπλασίοις ἐπάγειν τοὺς Ἕλληνας, ὅμως δὲ ῥώμῃ καὶ φρονήματι τοῦ κρατεῖν ὁρῶν ἐπηρμένους καὶ προθύμους ὁμόσε χωρεῖν τοῖς βαρβάροις, ἀπεβίβαζε τοὺς ὁπλίτας ἔτι θερμοὺς τῷ κατὰ τὴν ναυμαχίαν ἀγῶνι μετὰ κραυγῆς καὶ δρόμου προσφερομένους. ὑποστάντων δὲ τῶν Περσῶν καὶ δεξαμένων οὐκ ἀγεννῶς κρατερὰ μάχη συνέστη· καὶ τῶν Ἀθηναίων ἄνδρες ἀγαθοὶ καὶ τοῖς ἀξιώμασι πρῶτοι καὶ διαπρεπεῖς ἔπεσον. πολλῷ δ’ ἀγῶνι τρεψάμενοι τοὺς βαρβάρους ἔκτεινον, εἶτα ᾕρουν αὐτούς τε καὶ σκηνὰς παντοδαπῶν χρημάτων γεμούσας.", "st": "Cim. 13.1"}, {"sp": "N", "t": "Κίμων δ’ ὥσπερ ἀθλητὴς δεινὸς ἡμέρᾳ μιᾷ δύο καθῃρηκὼς ἀγωνίσματα, καὶ τὸ μὲν ἐν Σαλαμῖνι πεζομαχίᾳ, τὸ δ’ ἐν Πλαταιαῖς ναυμαχίᾳ παρεληλυθὼς τρόπαιον, ἐπηγωνίσατο ταῖς νίκαις, καὶ τὰς ὀγδοήκοντα Φοινίσσας τριήρεις, αἳ τῆς μάχης ἀπελείφθησαν, Ὕδρῳ προσβεβληκέναι πυθόμενος διὰ τάχους ἔπλευσεν, οὐδὲν εἰδότων βέβαιον οὔπω περὶ τῆς μείζονος δυνάμεως τῶν στρατηγῶν, ἀλλὰ δυσπίστως ἔτι καὶ μετεώρως ἐχόντων· ᾗ καὶ μᾶλλον ἐκπλαγέντες ἀπώλεσαν τὰς ναῦς ἁπάσας, καὶ τῶν ἀνδρῶν οἱ πλεῖστοι συνδιεφθάρησαν. τοῦτο τὸ ἔργον οὕτως ἐταπείνωσε τὴν γνώμην τοῦ βασιλέως, ὥστε συνθέσθαι τὴν περιβόητον εἰρήνην ἐκείνην, ἵππου μὲν δρόμον ἀεὶ τῆς Ἑλληνικῆς ἀπέχειν θαλάσσης, ἔνδον δὲ Κυανέων καὶ Χελιδονίων μακρᾷ νηῒ καὶ χαλκεμβόλῳ μὴ πλέειν.", "st": "Cim. 13.3"}, {"sp": "N", "t": "καίτοι Καλλισθένης οὔ φησι ταῦτα συνθέσθαι τὸν βάρβαρον, ἔργῳ δὲ ποιεῖν διὰ φόβον τῆς ἥττης ἐκείνης, καὶ μακρὰν οὕτως ἀποστῆναι τῆς Ἑλλάδος, ὥστε πεντήκοντα ναυσὶ Περικλέα καὶ τριάκοντα μόναις Ἐφιάλτην ἐπέκεινα πλεῦσαι Χελιδονίων καὶ μηδὲν αὐτοῖς ναυτικὸν ἀπαντῆσαι παρὰ τῶν βαρβάρων. ἐν δὲ τοῖς ψηφίσμασιν, ἃ συνήγαγε Κρατερός, ἀντίγραφα συνθηκῶν ὡς γενομένων κατατέτακται. φασὶ δὲ καὶ βωμὸν εἰρήνης διὰ ταῦτα τοὺς Ἀθηναίους ἱδρύσασθαι, καὶ Καλλίαν τὸν πρεσβεύσαντα τιμῆσι διαφερόντως.", "st": "Cim. 13.5"}, {"sp": "N", "t": "πραθέντων δὲ τῶν αἰχμαλώτων λαφύρων εἴς τε τὰ ἄλλα χρήμασιν ὁ δῆμος ἐρρώσθη, καὶ τῇ ἀκροπόλει τὸ νότιον τεῖχος κατεσκεύασεν ἀπ’ ἐκείνης εὐπορήσας τῆς στρατείας. λέγεται δὲ καὶ τῶν μακρῶν τειχῶν, ἃ σκέλη καλοῦσι, συντελεσθῆναι μὲν ὕστερον τὴν οἰκοδομίαν, τὴν δὲ πρώτην θεμελίωσιν εἰς τόπους ἑλώδεις καὶ διαβρόχους τῶν ἔργων ἐμπεσόντων ἐρεισθῆναι διὰ Κίμωνος ἀσφαλῶς, χάλικι πολλῇ καὶ λίθοις βαρέσι τῶν ἑλῶν πιεσθέντων, ἐκείνου χρήματα πορίζοντος καὶ διδόντος. πρῶτος δὲ ταῖς λεγομέναις ἐλευθερίοις καὶ γλαφυραῖς διατριβαῖς, αἳ μικρὸν ὕστερον ὑπερφυῶς ἠγαπήθησαν, ἐκαλλώπισε τὸ ἄστυ, τὴν μὲν ἀγορὰν πλατάνοις καταφυτεύσας, τὴν δ’ Ἀκαδήμειαν ἐξ ἀνύδρου καὶ αὐχμηρᾶς κατάρρυτον ἀποδείξας ἄλσος ἠσκημένον ὑπ’ αὐτοῦ δρόμοις καθαροῖς καὶ συσκίοις περιπάτοις.", "st": "Cim. 13.7"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν Περσῶν τινες οὐκ ἐβούλοντο τὴν Χερρόνησον ἐκλιπεῖν, ἀλλὰ καὶ τοὺς Θρᾷκας ἄνωθεν ἐπεκαλοῦντο καταφρονοῦντες τοῦ Κίμωνος μετ’ ὀλίγων παντάπασι τριήρων Ἀθήνηθεν ἐκπεπλευκότος, ὁρμήσας ἐπ’ αὐτοὺς τέσσαρσι μὲν ναυσὶ τρισκαίδεκα τὰς ἐκείνων ἔλαβεν, ἐξελάσας δὲ τοὺς Πέρσας καὶ κρατήσας τῶν Θρᾳκῶν πᾶσαν ᾠκειώσατο τῇ πόλει τὴν Χερρόνησον. ἐκ δὲ τούτου Θασίους μὲν ἀποστάντας Ἀθηναίων καταναυμαχήσας τρεῖς καὶ τριάκοντα ναῦς ἔλαβε καὶ τὴν πόλιν ἐξεπολιόρκησε καὶ τὰ χρυσεῖα τὰ πέραν Ἀθηναίοις προσεκτήσατο καὶ χώραν, ἧς ἐπῆρχον Θάσιοι, παρέλαβεν.", "st": "Cim. 14.1"}, {"sp": "N", "t": "ἐκεῖθεν δὲ ῥᾳδίως ἐπιβῆναι Μακεδονίας καὶ πολλὴν ἀποτεμέσθαι παρασχόν, ὡς ἐδόκει, μὴ θελήσας αἰτίαν ἔσχε δώροις ὑπὸ τοῦ βασιλέως Ἀλεξάνδρου συμπεπεῖσθαι, καὶ δίκην ἔφυγε τῶν ἐχθρῶν συστάντων ἐπ’ αὐτόν. ἀπολογούμενος δὲ πρὸς τοὺς δικαστὰς οὐκ Ἰώνων ἔφη προξενεῖν οὐδὲ Θεσσαλῶν, πλουσίων ὄντων, ὥσπερ ἑτέρους, ἵνα θεραπεύωνται καὶ λαμβάνωσιν, ἀλλὰ Λακεδαιμονίων, μιμούμενος καὶ ἀγαπῶν τὴν παρ’ αὐτοῖς εὐτέλειαν καὶ σωφροσύνην, ἧς οὐδένα προτιμᾶν πλοῦτον, ἀλλὰ πλουτίζων ἀπὸ τῶν πολεμίων τὴν πόλιν ἀγάλλεσθαι. μνησθεὶς δὲ τῆς κρίσεως ἐκείνης ὁ Στησίμβροτός φησι τὴν Ἐλπινίκην ὑπὲρ τοῦ Κίμωνος δεομένην ἐλθεῖν ἐπὶ τὰς θύρας τοῦ Περικλέους (οὗτος γὰρ ἦν τῶν κατηγόρων ὁ σφοδρότατος), τὸν δὲ μειδιάσαντα γραῦς εἶ, φάναι, γραῦς, ὦ Ἐλπινίκη, ὡς τηλικαῦτα διαπράττεσθαι πράγματα· πλὴν ἔν γε τῇ δίκῃ πρᾳότατον γενέσθαι τῷ Κίμωνι καὶ πρὸς τὴν κατηγορίαν ἅπαξ ἀναστῆναι μόνον, ὥσπερ ἀφοσιούμενον.", "st": "Cim. 14.3"}, {"sp": "N", "t": "ἐκείνην μὲν οὖν ἀπέφυγε τὴν δίκην· ἐν δὲ τῇ λοιπῇ πολιτείᾳ παρὼν μὲν ἐκράτει καὶ συνέστελλε τὸν δῆμον ἐπιβαίνοντα τοῖς ἀρίστοις καὶ περισπῶντα τὴν πᾶσαν εἰς ἑαυτὸν ἀρχὴν καὶ δύναμιν· ὡς δὲ πάλιν ἐπὶ στρατείαν ἐξέπλευσε, τελέως ἀνεθέντες οἱ πολλοὶ καὶ συγχέαντες τὸν καθεστῶτα τῆς πολιτείας κόσμον τά τε πάτρια νόμιμα, οἷς ἐχρῶντο πρότερον, Ἐφιάλτου προεστῶτος ἀφείλοντο τῆς ἐξ Ἀρείου πάγου βουλῆς τὰς κρίσεις πλὴν ὀλίγων ἁπάσας, καὶ τῶν δικαστηρίων κυρίους ἑαυτοὺς ποιήσαντες εἰς ἄκρατον δημοκρατίαν ἐνέβαλον τὴν πόλιν, ἤδη καὶ Περικλέους δυναμένου καὶ τὰ τῶν πολλῶν φρονοῦντος. διὸ καὶ τοῦ Κίμωνος, ὡς ἐπανῆλθεν, ἀγανακτοῦντος ἐπὶ τῷ προπηλακίζεσθαι τὸ ἀξίωμα τοῦ συνεδρίου, καὶ πειρωμένου πάλιν ἄνω τὰς δίκας ἀνακαλεῖσθαι καὶ τὴν ἐπὶ Κλεισθένους ἐγείρειν ἀριστοκρατίαν, κατεβόων συνιστάμενοι καὶ τὸν δῆμον ἐξηρέθιζον, ἐκεῖνά τε τὰ πρὸς τὴν ἀδελφὴν ἀνανεούμενοι καὶ Λακωνισμὸν ἐπικαλοῦντες. εἰς ἃ καὶ τὰ Εὐπόλιδος διατεθρύληται περὶ Κίμωνος, ὅτι", "st": "Cim. 15.1"}, {"sp": "N", "t": "κακὸς μὲν οὐκ ἦν, φιλοπότης δὲ κἀμελής·<br>κἀνίοτ’ ἂν ἀπεκοιμᾶτ’ ἂν ἐν Λακεδαίμονι,<br>κἂν Ἐλπινίκην τήνδε καταλιπὼν μόνην.", "st": "Cim. 15.1b"}, {"sp": "N", "t": "εἰ δ’ ἀμελῶν καὶ μεθυσκόμενος τοσαύτας πόλεις εἷλε καὶ τοσαύτας νίκας ἐνίκησε, δῆλον ὅτι νήφοντος αὐτοῦ καὶ προσέχοντος οὐδεὶς ἂν οὔτε τῶν πρότερον οὔτε τῶν ὕστερον Ἑλλήνων παρῆλθε τὰς πράξεις.", "st": "Cim. 15.1c"}, {"sp": "N", "t": "ἦν μὲν οὖν ἀπ’ ἀρχῆς φιλολάκων· καὶ τῶν γε παίδων τῶν διδύμων τὸν ἕτερον Λακεδαιμόνιον ὠνόμασε, τὸν δ’ ἕτερον Ἠλεῖον, ἐκ γυναικὸς αὐτῷ Κλειτορίας γενομένους, ὡς Στησίμβροτος ἱστορεῖ· διὸ πολλάκις τὸν Περικλέα τὸ μητρῷον αὐτοῖς γένος ὀνειδίζειν. Διόδωρος δ’ ὁ Περιηγητὴς καὶ τούτους φησὶ καὶ τὸν τρίτον τῶν Κίμωνος υἱῶν Θεσσαλὸν ἐξ Ἰσοδίκης γεγονέναι τῆς Εὐρυπτολέμου τοῦ Μεγακλέους. ηὐξήθη δ’ ὑπὸ τῶν Λακεδαιμονίων ἤδη τῷ Θεμιστοκλεῖ προσπολεμούντων καὶ τοῦτον ὄντα νέον ἐν Ἀθήναις μᾶλλον ἰσχύειν καὶ κρατεῖν βουλομένων. οἱ δ’ Ἀθηναῖοι τὸ πρῶτον ἡδέως ἑώρων οὐ μικρὰ τῆς πρὸς ἐκεῖνον εὐνοίας τῶν Σπαρτιατῶν ἀπολαύοντες· αὐξανομένοις γὰρ αὐτοῖς κατ’ ἀρχὰς καὶ τὰ συμμαχικὰ πολυπραγμονοῦσιν οὐκ ἤχθοντο τιμῇ καὶ χάριτι τοῦ Κίμωνος. τὰ γὰρ πλεῖστα δι’ ἐκείνου τῶν Ἑλληνικῶν διεπράττετο, πρᾴως μὲν τοῖς συμμάχοις, κεχαρισμένως δὲ τοῖς Λακεδαιμονίοις ὁμιλοῦντος. ἔπειτα δυνατώτεροι γενόμενοι καὶ τὸν Κίμωνα τοῖς Σπαρτιάταις οὐκ ἠρέμα προσκείμενον ὁρῶντες ἤχθοντο. καὶ γὰρ αὐτὸς ἐπὶ παντὶ μεγαλύνων τὴν Λακεδαίμονα πρὸς Ἀθηναίους, καὶ μάλιστα ὅτε τύχοι μεμφόμενος αὐτοῖς ἢ παροξύνων, ὥς φησι Στησίμβροτος, εἰώθει λέγειν· ἀλλ’ οὐ Λακεδαιμόνιοί γε τοιοῦτοι. ὅθεν φθόνον ἑαυτῷ συνῆγε καὶ δυσμένειάν τινα παρὰ τῶν πολιτῶν.", "st": "Cim. 16.1"}, {"sp": "N", "t": "ἡ δ’ οὖν ἰσχύσασα μάλιστα κατ’ αὐτοῦ τῶν διαβολῶν αἰτίαν ἔσχε τοιαύτην. Ἀρχιδάμου τοῦ Ζευξιδάμου τέταρτον ἔτος ἐν Σπάρτῃ βασιλεύοντος ὑπὸ σεισμοῦ μεγίστου δὴ τῶν μνημονευομένων πρότερον ἥ τε χώρα τῶν Λακεδαιμονίων χάσμασιν ἐνώλισθε πολλοῖς καὶ τῶν Ταϋγέτων τιναχθέντων κορυφαί τινες ἀπερράγησαν, αὐτὴ δ’ ἡ πόλις ὅλη συνεχύθη πλὴν οἰκιῶν πέντε, τὰς δ’ ἄλλας ἤρειψεν ὁ σεισμός.", "st": "Cim. 16.1b"}, {"sp": "N", "t": "ἐν δὲ μέσῃ τῇ στοᾷ γυμναζομένων ὁμοῦ τῶν ἐφήβων καὶ τῶν νεανίσκων λέγεται μικρὸν πρὸ τοῦ σεισμοῦ λαγὼν παραφανῆναι, καὶ τοὺς μὲν νεανίσκους, ὥσπερ ἦσαν ἀληλιμμένοι, μετὰ παιδιᾶς ἐκδραμεῖν καὶ διώκειν, τοῖς δ’ ἐφήβοις ὑπολειφθεῖσιν ἐπιπεσεῖν τὸ γυμνάσιον καὶ πάντας ὁμοῦ τελευτῆσαι. τὸν δὲ τάφον αὐτῶν ἔτι νῦν Σεισματίαν προσαγορεύουσι.", "st": "Cim. 16.5"}, {"sp": "N", "t": "ταχὺ δὴ συνιδὼν ἀπὸ τοῦ παρόντος τὸν μέλλοντα κίνδυνον ὁ Ἀρχίδαμος, καὶ τοὺς πολίτας ὁρῶν ἐκ τῶν οἰκιῶν τὰ τιμιώτατα πειρωμένους σώζειν, ἐκέλευσε τῇ σάλπιγγι σημαίνειν, ὡς πολεμίων ἐπιόντων, ὅπως ὅτι τάχιστα μετὰ τῶν ὅπλων ἀθροίζωνται πρὸς αὐτόν. ὃ δὴ καὶ μόνον ἐν τῷ τότε καιρῷ τὴν Σπάρτην διέσωσεν. οἱ γὰρ εἵλωτες ἐκ τῶν ἀγρῶν συνέδραμον πανταχόθεν ὡς ἀναρπασόμενοι τοὺς σεσωσμένους τῶν Σπαρτιατῶν. ὡπλισμένους δὲ καὶ συντεταγμένους εὑρόντες ἀνεχώρησαν ἐπὶ τὰς πόλεις καὶ φανερῶς ἐπολέμουν, τῶν τε περιοίκων ἀναπείσαντες οὐκ ὀλίγους, καὶ Μεσσηνίων ἅμα τοῖς Σπαρτιάταις συνεπιθεμένων.", "st": "Cim. 16.6"}, {"sp": "N", "t": "πέμπουσιν οὖν οἱ Λακεδαιμόνιοι Περικλείδαν εἰς Ἀθήνας δεόμενοι βοηθεῖν, ὅν φησι κωμῳδῶν Ἀριστοφάνης καθεζόμενον ἐπὶ τοῖς βωμοῖς ὠχρὸν ἐν φοινικίδι στρατιὰν ἐπαιτεῖν. Ἐφιάλτου δὲ κωλύοντος καὶ διαμαρτυρομένου μὴ βοηθεῖν μηδ’ ἀνιστάναι πόλιν ἀντίπαλον ἐπὶ τὰς Ἀθήνας, ἀλλ’ ἐᾶν κεῖσθαι καὶ πατηθῆναι τὸ φρόνημα τῆς Σπάρτης, Κίμωνά φησι Κριτίας τὴν τῆς πατρίδος αὔξησιν ἐν ὑστέρῳ θέμενον τοῦ Λακεδαιμονίων συμφέροντος ἀναπείσαντα τὸν δῆμον ἐξελθεῖν βοηθοῦντα μετὰ πολλῶν ὁπλιτῶν. ὁ δ’ Ἴων ἀπομνημονεύει καὶ τὸν λόγον, ᾧ μάλιστα τοὺς Ἀθηναίους ἐκίνησε, παρακαλῶν μήτε τὴν Ἑλλάδα χωλὴν μήτε τὴν πόλιν ἑτερόζυγα περιϊδεῖν γεγενημένην.", "st": "Cim. 16.8"}, {"sp": "N", "t": "ἐπεὶ δὲ βοηθήσας τοῖς Λακεδαιμονίοις ἀπῄει διὰ Κορίνθου τὴν στρατιὰν ἄγων, ἐνεκάλει Λάχαρτος αὐτῷ πρὶν ἐντυχεῖν τοῖς πολίταις εἰσαγαγόντι τὸ στράτευμα· καὶ γὰρ θύραν κόψαντας ἀλλοτρίαν οὐκ εἰσιέναι πρότερον ἢ τὸν κύριον κελεῦσαι. καὶ ὁ Κίμων ἀλλ’ οὐχ ὑμεῖς, εἶπεν, ὦ Λάχαρτε, τὰς Κλεωναίων καὶ Μεγαρέων πύλας κόψαντες, ἀλλὰ κατασχίσαντες εἰσεβιάσασθε μετὰ τῶν ὅπλων ἀξιοῦντες ἀνεῳγέναι πάντα τοῖς μεῖζον δυναμένοις. οὕτω μὲν ἐθρασύνατο πρὸς τὸν Κορίνθιον ἐν δέοντι, καὶ μετὰ τῆς στρατιᾶς διεξῆλθεν.", "st": "Cim. 17.1"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι τοὺς Ἀθηναίους αὖθις ἐκάλουν ἐπὶ τοὺς ἐν Ἰθώμῃ Μεσσηνίους καὶ εἵλωτας, ἐλθόντων δὲ τὴν τόλμαν καὶ τὴν λαμπρότητα δείσαντες ἀπεπέμψαντο μόνους τῶν συμμάχων ὡς νεωτεριστάς. οἱ δὲ πρὸς ὀργὴν ἀπελθόντες ἤδη τοῖς λακωνίζουσι φανερῶς ἐχαλέπαινον, καὶ τὸν Κίμωνα μικρᾶς ἐπιλαβόμενοι προφάσεως ἐξωστράκισαν εἰς ἔτη δέκα· τοσοῦτον γὰρ ἦν χρόνου τεταγμένον ἅπασι τοῖς ἐξοστρακιζομένοις.", "st": "Cim. 17.2"}, {"sp": "N", "t": "ἐν δὲ τούτῳ τῶν Λακεδαιμονίων, ὡς ἐπανήρχοντο Δελφοὺς ἀπὸ Φωκέων ἐλευθερώσαντες, ἐν Τανάγρᾳ καταστρατοπεδευσάντων Ἀθηναῖοι μὲν ἀπήντων διαμαχούμενοι, Κίμων δὲ μετὰ τῶν ὅπλων ἧκεν εἰς τὴν αὑτοῦ φυλὴν τὴν Οἰνηΐδα, πρόθυμος ὢν ἀμύνεσθαι τοὺς Λακεδαιμονίους μετὰ τῶν πολιτῶν. ἡ δὲ βουλὴ τῶν πεντακοσίων πυθομένη καὶ φοβηθεῖσα, τῶν ἐχθρῶν αὐτοῦ καταβοώντων ὡς συνταράξαι τὴν φάλαγγα βουλομένου καὶ τῇ πόλει Λακεδαιμονίους ἐπαγαγεῖν, ἀπηγόρευσε τοῖς στρατηγοῖς μὴ δέχεσθαι τὸν ἄνδρα. κἀκεῖνος μὲν ᾤχετο δεηθεὶς Εὐθίππου τοῦ Ἀναφλυστίου καὶ τῶν ἄλλων ἑταίρων, ὅσοι μάλιστα τὴν τοῦ λακωνίζειν αἰτίαν ἔσχον, ἐρρωμένως ἀγωνίσασθαι πρὸς τοὺς πολεμίους καὶ δι’ ἔργων ἀπολύσασθαι τὴν αἰτίαν πρὸς τοὺς πολίτας. οἱ δὲ λαβόντες αὐτοῦ τὴν πανοπλίαν εἰς τὸν λόχον ἔθεντο· καὶ μετ’ ἀλλήλων συστάντες ἐκθύμως ἑκατὸν ὄντες ἔπεσον, πολὺν αὑτῶν πόθον καὶ μεταμέλειαν ἐφ’ οἷς ᾐτιάθησαν ἀδίκως ἀπολιπόντες τοῖς Ἀθηναίοις. ὅθεν οὐδὲ τῷ πρὸς Κίμωνα θυμῷ πολὺν χρόνον ἐνέμειναν, τὰ μέν, ὡς εἰκός, ὧν ἔπαθον εὖ μεμνημένοι, τὰ δὲ τοῦ καιροῦ συλλαμβανομένου. νενικημένοι γὰρ ἐν Τανάγρᾳ μάχῃ μεγάλῃ καὶ προσδοκῶντες εἰς ὥραν ἔτους στρατιὰν Πελοποννησίων ἐπ’ αὐτοὺς ἐκάλουν ἐκ τῆς φυγῆς τὸν Κίμωνα· καὶ κατῆλθε τὸ ψήφισμα γράψαντος αὐτῷ Περικλέους. οὕτω τότε πολιτικαὶ μὲν ἦσαν αἱ διαφοραί, μέτριοι δ’ οἱ θυμοὶ καὶ πρὸς τὸ κοινὸν εὐανάκλητοι συμφέρον, ἡ δὲ φιλοτιμία πάντων ἐπικρατοῦσα τῶν παθῶν τοῖς τῆς πατρίδος ὑπεχώρει καιροῖς.", "st": "Cim. 17.3"}, {"sp": "N", "t": "εὐθὺς μὲν οὖν ὁ Κίμων κατελθὼν ἔλυσε τὸν πόλεμον καὶ διήλλαξε τὰς πόλεις· γενομένης δ’ εἰρήνης ὁρῶν τοὺς Ἀθηναίους ἡσυχίαν ἄγειν μὴ δυναμένους, ἀλλὰ κινεῖσθαι καὶ αὐξάνεσθαι ταῖς στρατείαις βουλομένους, ἵνα μὴ τοῖς Ἕλλησι διοχλῶσι μηδὲ περὶ τὰς νήσους ἢ Πελοπόννησον ἀναστρεφόμενοι ναυσὶ πολλαῖς αἰτίας ἐμφυλίων πολέμων καὶ συμμαχικῶν ἐγκλημάτων ἀρχὰς ἐπισπάσωνται κατὰ τῆς πόλεως, ἐπλήρου διακοσίας τριήρεις ὡς ἐπ’ Αἴγυπτον καὶ Κύπρον αὖθις ἐκστρατευσόμενος, ἅμα μὲν ἐμμελετᾶν τοῖς πρὸς τοὺς βαρβάρους ἀγῶσι βουλόμενος τοὺς Ἀθηναίους, ἅμα δ’ ὠφελεῖσθαι δικαίως τὰς ἀπὸ τῶν φύσει πολεμίων εὐπορίας εἰς τὴν Ἑλλάδα κομίζοντας.", "st": "Cim. 18.1"}, {"sp": "N", "t": "ἤδη δὲ παρεσκευασμένων ἁπάντων καὶ τοῦ στρατοῦ παρὰ ταῖς ναυσὶν ὄντος ὄναρ εἶδεν ὁ Κίμων. ἐδόκει κύνα θυμουμένην ὑλακτεῖν πρὸς αὐτόν, ἐκ δὲ τῆς ὑλακῆς μεμιγμένον ἀφεῖσαν ἀνθρώπου φθόγγον εἰπεῖν·", "st": "Cim. 18.3"}, {"sp": "N", "t": "στεῖχε· φίλος γὰρ ἔσῃ καὶ ἐμοὶ καὶ ἐμοῖς σκυλάκεσσιν.", "st": "Cim. 18.3b"}, {"sp": "N", "t": "οὕτω δὲ δυσκρίτου τῆς ὄψεως οὔσης Ἀστύφιλος ὁ Ποσειδωνιάτης, μαντικὸς ἀνὴρ καὶ συνήθης τῷ Κίμωνι, φράζει θάνατον αὐτῷ προσημαίνειν τὴν ὄψιν, οὕτω διαιρῶν· κύων ἀνθρώπῳ, πρὸς ὃν ὑλακτεῖ, πολέμιος· πολεμίῳ δ’ οὐκ ἄν τις μᾶλλον ἢ τελευτήσας φίλος γένοιτο· τὸ δὲ μῖγμα τῆς φωνῆς Μῆδον ἀποδηλοῖ τὸν ἐχθρόν· ὁ γὰρ Μήδων στρατὸς Ἕλλησιν ὁμοῦ καὶ βαρβάροις μέμικται. μετὰ δὲ ταύτην τὴν ὄψιν αὐτοῦ τῷ Διονύσῳ θύσαντος ὁ μὲν μάντις ἀπέτεμε τὸ ἱερεῖον, τοῦ δ’ αἵματος τὸ πηγνύμενον ἤδη μύρμηκες πολλοὶ λαμβάνοντες κατὰ μικρὸν ἔφερον πρὸς τὸν Κίμωνα καὶ τοῦ ποδὸς περὶ τὸν μέγαν δάκτυλον περιέπλαττον, ἐπὶ πολὺν χρόνον λανθάνοντες. ἅμα δέ πως ὅ τε Κίμων τῷ γινομένῳ προσέσχε καὶ παρῆν ὁ θύτης ἐπιδεικνύμενος αὐτῷ τὸν λοβὸν οὐκ ἔχοντα κεφαλήν.", "st": "Cim. 18.4"}, {"sp": "N", "t": "ἄλλ’ οὐ γὰρ ἦν ἀνάδυσις τῆς στρατείας ἐξέπλευσε, καὶ τῶν νεῶν ἑξήκοντα μὲν ἀπέστειλεν εἰς Αἴγυπτον, ταῖς δ’ ἄλλαις πάλιν … ἔπλει. καὶ καταναυμαχήσας Φοινισσῶν νεῶν καὶ Κιλισσῶν βασιλικὸν στόλον ἀνεκτᾶτο τε τὰς ἐν κύκλῳ πόλεις καὶ τοῖς περὶ Αἴγυπτον ἐφήδρευεν, οὐδὲν μικρόν, ἀλλ’ ὅλης ἐπινοῶν τῆς βασιλέως ἡγεμονίας κατάλυσιν, καὶ μάλιστα ὅτι τοῦ Θεμιστοκλέους ἐπυνθάνετο δόξαν εἶναι καὶ δύναμιν ἐν τοῖς βαρβάροις μεγάλην, ὑποδεδεγμένου βασιλεῖ κινοῦντι τὸν Ἑλληνικὸν πόλεμον στρατηγήσειν.", "st": "Cim. 18.5"}, {"sp": "N", "t": "Θεμιστοκλῆς μὲν οὖν οὐχ ἥκιστα λέγεται τὰς Ἑλληνικὰς πράξεις ἀπογνούς, ὡς οὐκ ἂν ὑπερβαλόμενος τὴν Κίμωνος εὐτυχίαν καὶ ἀρετήν, ἑκὼν τελευτῆσαι, Κίμων δὲ μεγάλων ἐπαιρόμενος ἀρχὰς ἀγώνων καὶ περὶ Κύπρον συνέχων τὸ ναυτικὸν ἔπεμψεν εἰς Ἄμμωνος ἄνδρας ἀπόρρητόν τινα μαντείαν ποιησομένους παρὰ τῷ θεῷ· γινώσκει γὰρ οὐδεὶς ὑπὲρ ὧν ἐπέμφθησαν, οὐδὲ χρησμὸν αὐτοῖς ὁ θεὸς ἐξήνεγκεν, ἀλλ’ ἅμα τῷ προσελθεῖν ἐκέλευσεν ἀπιέναι τοὺς θεοπρόπους· αὐτὸν γὰρ ἤδη τὸν Κίμωνα παρ’ ἑαυτῷ τυγχάνειν ὄντα. ταῦτα ἀκούσαντες οἱ θεοπρόποι κατέβαινον ἐπὶ θάλασσαν· γενόμενοι δὲ ἐν τῷ στρατοπέδῳ τῶν Ἑλλήνων, ὃ τότε περὶ Αἴγυπτον ἦν, ἐπύθοντο τεθνάναι τὸν Κίμωνα· καὶ τὰς ἡμέρας πρὸς τὸ μαντεῖον ἀνάγοντες ἔγνωσαν ᾐνιγμένην τὴν τελευτὴν τοῦ ἀνδρός, ὡς ἤδη παρὰ θεοῖς ὄντος.", "st": "Cim. 18.6"}, {"sp": "N", "t": "ἀπέθανε δὲ πολιορκῶν Κίτιον, ὡς οἱ πλεῖστοι λέγουσι, νοσήσας· ἔνιοι δέ φασιν ἐκ τραύματος, ὃ πρὸς τοὺς βαρβάρους ἀγωνιζόμενος ἔσχε. τελευτῶν δὲ τοὺς περὶ αὐτὸν ἐκέλευσεν εὐθὺς ἀποπλεῖν ἀποκρυψαμένους τὸν θάνατον αὐτοῦ· καὶ συνέβη μήτε τῶν πολεμίων μήτε τῶν συμμάχων αἰσθομένων ἀσφαλῶς αὐτοὺς ἀνακομισθῆναι στρατηγουμένους ὑπὸ Κίμωνος, ὥς φησι Φανόδημος, τεθνηκότος ἐφ’ ἡμέρας τριάκοντα.", "st": "Cim. 19.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν ἐκείνου τελευτὴν πρὸς μὲν τοὺς βαρβάρους οὐδὲν ἔτι λαμπρὸν ὑπ’ οὐδενὸς ἐπράχθη στρατηγοῦ τῶν Ἑλλήνων, ἀλλὰ τραπέντες ὑπὸ δημαγωγῶν καὶ πολεμοποιῶν ἐπ’ ἀλλήλους, οὐδενὸς τὰς χεῖρας ἐν μέσῳ διασχόντος, συνερράγησαν εἰς τὸν πόλεμον, ἀναπνοὴ μὲν τοῖς βασιλέως πράγμασι γενόμενοι, φθόρον δ’ ἀμύθητον τῆς Ἑλληνικῆς δυνάμεως ἀπεργασάμενοι. ὀψὲ δ’ οἱ περὶ τὸν Ἀγησίλαον εἰς τὴν Ἀσίαν ἐξενεγκάμενοι τὰ ὅπλα βραχέος ἥψαντο πολέμου πρὸς τοὺς ἐπὶ θαλάσσῃ βασιλέως στρατηγούς· καὶ λαμπρὸν οὐδὲν οὐδὲ μέγα δράσαντες, αὖθις δὲ ταῖς Ἑλληνικαῖς στάσεσι καὶ ταραχαῖς ἀφ’ ἑτέρας ἀρχῆς ὑπενεχθέντες, ᾤχοντο τοὺς Περσῶν φορολόγους ἐν μέσαις ταῖς συμμάχοις καὶ φίλαις πόλεσιν ἀπολιπόντες, ὧν οὐδὲ γραμματοφόρος κατέβαινεν οὐδ’ ἵππος πρὸς θαλάσσῃ τετρακοσίων σταδίων ἐντὸς ὤφθη στρατηγοῦντος Κίμωνος.", "st": "Cim. 19.2"}, {"sp": "N", "t": "ὅτι μὲν οὖν εἰς τὴν Ἀττικὴν ἀπεκομίσθη τὰ λείψανα αὐτοῦ, μαρτυρεῖ τῶν μνημάτων τὰ μέχρι νῦν Κιμώνεια προσαγορευόμενα· τιμῶσι δὲ καὶ Κιτιεῖς τάφον τινὰ Κίμωνος, ὡς Ναυσικράτης ὁ ῥήτωρ φησίν, ἐν λοιμῷ καὶ γῆς ἀφορίᾳ τοῦ θεοῦ προστάξαντος αὐτοῖς μὴ ἀμελεῖν Κίμωνος, ἀλλ’ ὡς κρείττονα σέβεσθαι καὶ γεραίρειν. τοιοῦτος μὲν ὁ Ἑλληνικὸς ἡγεμών.", "st": "Cim. 19.4"}, {"sp": "HDR", "t": "Λούκουλλος"}, {"sp": "N", "t": "τῷ δὲ Λουκούλλῳ πάππος μὲν ἦν ὑπατικός, θεῖος δὲ πρὸς μητρὸς Μέτελλος ὁ Νομαδικὸς ἐπικληθείς. τῶν δὲ γονέων ὁ μὲν πατὴρ ἑάλω κλοπῆς, Κεκιλία δὲ ἡ μήτηρ ἠδόξησεν ὡς οὐ βεβιωκυῖα σωφρόνως. αὐτὸς δ’ ὁ Λούκοθλλος ἔτι μειράκιον ὢν, πρὶν ἀρχήν τινα μετελθεῖν καί πολιτείας ἅψασθαι, πρῶτον ἔργον ἐποιήσατο τὸν τοῦ πατρὸς κατήγορον κρῖναι Σερουίλιον αὔγουρα, λαβὼν ἀδικοῦντα δημοσίᾳ. καί τὸ πρᾶγμα λαμπρὸν ἐφάνη Ῥωμαίοις, καί τὴν δίκην ἐκείνην ὥσπερ ἀριστείαν διὰ στόματος ἔσχον. ἐδόκει δὲ καί ἄλλως αὐτοῖς ἄνευ προφάσεως οὐκ ἀγεννὲς εἶναι τὸ τῆς κατηγορίας ἔργον, ἀλλὰ καί πάνυ τοὺς νέους ἐβούλοντο τοῖς ἀδικοῦσιν ἐπιφυομένους ὁρᾶν ὥσπερ θηρίοις εὐγενεῖς σκύλακας. οὐ μὴν ἀλλὰ μεγάλης περὶ τὴν δίκην ἐκείνην φιλονεικίας γενομένης, ὥστε καί τρωθῆναί τινας καί πεσεῖν, ἀπέφυγεν ὁ Σερουίλιος.", "st": "Luc. 1.1"}, {"sp": "N", "t": "ὁ δὲ Λούκοθλλος ἤσκητο καί λέγειν ἱκανῶς ἑκατέραν γλῶτταν, ὥστε καί Σύλλας τὰς αὐτοῦ πράξεις ἀναγράφων ἐκείνῳ προσεφώνησεν ὡς συνταξομένῳ καὶ διαθήσοντι τὴν ἱστορίαν ἄμεινον. ἦν γὰρ οὐκ ἐπὶ τὴν χρείαν μόνην ἐμμελὴς αὐτοῦ καί πρόχειρος ὁ λόγος, καθάπερ ὁ τῶν ἄλλων τὴν μὲν ἀγορὰν", "st": "Luc. 1.3"}, {"sp": "N", "t": "θύννος βολαῖος πέλαγος ὣς διεστρόβει,<br>γενόμενος δὲ τῆς ἀγορᾶς ἐκτὸς αὖος, ἀμουσίᾳ τεθνηκώς,", "st": "Luc. 1.3b"}, {"sp": "N", "t": "ἀλλὰ καί τὴν ἐμμελῆ ταύτην καί λεγομένην ἐλευθέριον ἐπὶ τῷ καλῷ προσεποιεῖτο παιδείαν ἔτι καί μειράκιον ὤν. γενόμενος δὲ πρεσβύτερος ἤδη παντάπασιν ὥσπερ ἐκ πολλῶν ἀγώνων ἀφῆκε τὴν διάνοιαν ἐν φιλοσοφίᾳ σχολάζειν καί ἀναπαύεσθαι, τὸ θεωρητικὸν αὐτῆς ἐγείρας, καταλύσας δ’ ἐν καιρῷ καί κολούσας τὸ φιλότιμον ἐκ τῆς πρὸς Πομπήϊον διαφορᾶς. περὶ μὲν οὖν τῆς φιλολογίας αὐτοῦ πρὸς τοῖς εἰρημένοις καὶ ταῦτα λέγεται· νέον ὄντα πρὸς Ὁρτήσιον τὸν δικολόγον καί Σισεννᾶν τὸν ἱστορικὸν ἐκ παιδιᾶς τινος εἰς σπουδὴν προελθούσης ὁμολογῆσαι, προθεμένων ποίημα καί λόγον Ἑλληνικόν τε καί Ῥωμαϊκόν, εἰς ὅ τι ἂν λάχῃ τούτων, τὸν Μαρσικὸν ἐντενεῖν πόλεμον. καί πως ἔοικεν εἰς λόγον Ἑλληνικὸν ὁ κλῆρος ἀφικέσθαι διασῴζεται γὰρ Ἑλληνική τις ἱστορία τοῦ Μαρσικοῦ πολέμου.", "st": "Luc. 1.4"}, {"sp": "N", "t": "τῆς δὲ πρὸς τὸν ἀδελφὸν αὐτοῦ Μᾶρκον εὐνοίας πολλῶν τεκμηρίων ὄντων μάλιστα Ῥωμαῖοι τοῦ πρώτου μνημονεύουσι. πρεσβύτερος γὰρ ὢν αὐτοῦ λαβεῖν ἀρχήν μόνος οὐκ ἠθέλησεν, ἀλλὰ τὸν ἐκείνου καιρὸν ἀναμείνας οὕτως ἐπηγάγετο τὸν δῆμον, ὥστε σὺν ἐκείνῳ μὴ παρὼν ἀγορανόμος αἱρεθῆναι.", "st": "Luc. 1.6"}, {"sp": "N", "t": "νέος δ’ ὢν ἐν τῷ Μαρσικῷ πολέμῳ πολλὰ μὲν τόλμης δείγματα παρέσχε καὶ συνέσεως, μᾶλλόν γε μὴν αὐτὸν δι’ εὐστάθειαν καὶ πρᾳότητα Σύλλας προσηγάγετο, καὶ χρώμενος ἀπ’ ἀρχῆς ἐπὶ τὰ πλείστης ἄξια σπουδῆς διετέλεσεν ὧν ἦν καὶ ἡ περὶ τὸ νόμισμα πραγματεία. δι’ ἐκείνου γὰρ ἐκόπη τὸ πλεῖστον ἐν Πελοποννήσῳ περὶ τὸν Μιθριδατικὸν πόλεμον, καὶ Λουκούλλειον ἀπ’ ἐκείνου προσηγορεύθη, καὶ διετέλεσεν ἐπὶ πλεῖστον, ὑπὸ τῶν στρατιωτικῶν χρειῶν ἐν τῷ πολέμῳ λαμβάνον ἀμοιβὴν ταχεῖαν. ἐκ τούτου τῆς μὲν γῆς ἐπικρατῶν ὁ Σύλλας ἐν ταῖς Ἀθήναις, περικοπτόμενος δὲ τὴν ἀγορὰν ἐκ τῆς θαλάττης ὑπὸ τῶν πολεμίων ναυκρατούντων, ἐξέπεμψεν ἐπ’ Αἰγύπτου καὶ Λιβύης τὸν Λούκουλλον ἄξοντα ναῦς ἐκεῖθεν. ἦν μὲν οὖν ἀκμὴ χειμῶνος, ἐξέπλευσε δὲ τρισὶν Ἑλληνικοῖς μυοπάρωσι καὶ δικρότοις ἴσαις Ῥοδιακαῖς πρὸς μέγα πέλαγος καὶ ναῦς πολεμίας, πανταχόσε τῷ κρατεῖν πολλὰς διαφερομένας, παραβαλλόμενος. οὐ μὴν ἀλλὰ καὶ Κρήτην κατάρας ὠκειώσατο καὶ Κυρηναίους καταλαβὼν ἐκ τυραννίδων συνεχῶν καὶ πολέμων ταραττομένους ἀνέλαβε, καὶ κατεστήσατο τὴν πολιτείαν Πλατωνικῆς τινος φωνῆς ἀναμνήσας τὴν πόλιν, ἣν ἐκεῖνος ἀπεθέσπισε πρὸς αὐτούς. δεομένων γὰρ, ὡς ἔοικεν, ὅπως τε νόμους γράψῃ καὶ τὸν δῆμον αὐτὸν εἰς τύπον τινὰ καταστήσῃ πολιτείας σώφρονος, ἔφη χαλεπὸν εἶναι Κυρηναίοις οὕτως εὐτυχοῦσι νομοθετεῖν. οὐδὲν γὰρ ἀνθρώπου δυσαρκτότερον εὖ πράσσειν δοκοῦντος, οὐδ’ αὖ πάλιν δεκτικώτερον ἐπιστασίας συσταλέντος ὑπὸ τῆς τύχης, ὃ καὶ τότε Κυρηναίους νομοθετοῦντι Λουκούλλῳ πρᾴους παρέσχεν.", "st": "Luc. 2.1"}, {"sp": "N", "t": "ἐκεῖθεν δ’ ἀναχθεὶς ἐπ’ Αἰγύπτου τὰ πλεῖστα τῶν σκαφῶν ἀπέβαλε πειρατῶν ἐπιφανέντων, αὐτὸς δὲ διασωθεὶς κατήγετο λαμπρῶς εἰς Ἀλεξάνδρειαν. ἀπήντησε γὰρ αὐτῷ σύμπας ὁ στόλος, ὥσπερ εἰώθει βασιλεῖ καταπλέοντι, κεκοσμημένος ἐκπρεπῶς· καὶ τὸ μειράκιον ὁ Πτολεμαῖος ἄλλην τε θαυμαστὴν ἐπεδείκνυτο φιλοφροσύνην πρὸς αὐτόν, οἴκησίν τε καὶ δίαιταν ἐν τοῖς βασιλείοις ἔδωκεν, οὐδενός πω ξένου πρότερον ἡγεμόνος αὐτόθι καταχθέντος. δαπάνην δὲ καὶ σύνταξιν οὐχ ὅσην ἐδίδου τοῖς ἄλλοις, ἀλλὰ τετραπλῆν ἐκείνῳ παρεῖχεν, οὐ προσιεμένῳ τῶν ἀναγκαίων πλέον οὐδὲν οὐδὲ δῶρον λαβόντι, καίπερ ὀγδοήκοντα ταλάντων ἄξια πέμψαντος αὐτῷ. λέγεται δὲ μήτ’ εἰς Μέμφιν ἀναβῆναι μήτ’ ἄλλο τῶν θαυμαζομένων ἐν Αἰγύπτῳ καὶ περιβοήτων ἱστορῆσαι· σχολάζοντος γὰρ εἶναι ταῦτα θεατοῦ καὶ τρυφῶντος, οὐχ, ὡς αὐτὸς, ἐν ὑπαίθρῳ τὸν αὐτοκράτορα σκηνοῦντα παρὰ ταῖς ἐπάλξεσι τῶν πολεμίων ἀπολελοιπότος.", "st": "Luc. 2.5"}, {"sp": "N", "t": "ἐπεὶ δ’ ἀπέλιπε τὴν συμμαχίαν ὁ Πτολεμαῖος πρὸς τὸν πόλεμον ἀποδειλιάσας, ἐκείνῳ δὲ ναῦς ἄχρι Κύπρου πομποὺς παρέσχε, καὶ περὶ τὸν ἔκπλουν αὐτὸν ἀσπαζόμενος καὶ θεραπεύων ἐδωρεῖτο χρυσένδετον σμάραγδον τῶν πολυτελῶν, τὸ μὲν πρῶτον ὁ Λούκουλλος παρῃτεῖτο, δείξαντος δὲ τὴν γλυφὴν τοῦ βασιλέως εἰκόνα οὖσαν ἰδίαν ἐφοβήθη διώσασθαι, μὴ παντάπασιν ἐχθρὸς ἀποπλεῖν νομισθεὶς ἐπιβουλευθείη κατὰ θάλατταν. ἐπεὶ δὲ πλῆθος ἐν παράπλῳ νεῶν ἐκ τῶν παραλίων πόλεων ἀθροίσας, πλὴν ὅσοι πειρατικῶν μετεῖχον ἀδικημάτων, εἰς τὴν Κύπρον διεπέρασεν, ἐνταῦθα πυνθανόμενος τοὺς πολεμίους ναυλοχοῦντας ἐπὶ ταῖς ἄκραις παραφυλάττειν αὑτόν, ἐνεώλκησε τὰ σκάφη πάντα, καὶ ταῖς πόλεσιν ἔγραψε περὶ χειμαδίων καὶ ἀγορᾶς, ὡς αὐτόθι τὴν ὥραν ἀναμενῶν. εἶτα πλοῦ φανέντος ἐξαπίνης κατασπάσας τὰς ναῦς ἀνήχθη, καὶ μεθ’ ἡμέραν μὲν ὑφειμένοις πλέων τοῖς ἱστίοις καὶ ταπεινοῖς, νύκτωρ δ’ ἐπαιρομένοις εἰς Ῥόδον ἐσώθη. Ῥοδίων δὲ ναῦς αὐτῷ προσπαρασχόντων Κῴους ἔπεισε καὶ Κνιδίους τῶν βασιλικῶν ἀπαλλαγέντας ἐπὶ Σαμίους συστρατεύειν. ἐκ δὲ Χίου τοὺς βασιλικοὺς αὐτὸς ἐξήλασε, Κολοφωνίους δ’ ἠλευθέρωσε συλλαβὼν Ἐπίγονον τὸν τύραννον αὐτῶν.", "st": "Luc. 3.1"}, {"sp": "N", "t": "ἐτύγχανε δὲ κατ’ ἐκεῖνον τὸν χρόνον ἤδη Μιθριδάτης τὸ Πέργαμον ἐκλελοιπὼς καὶ συνεσταλμένος εἰς Πιτάνην. ἐκεῖ δὲ Φιμβρίου κατέχοντος αὐτὸν ἐκ γῆς καὶ πολιορκοῦντος, εἰς τὴν θάλατταν ἀφορῶν συνῆγε καὶ μετεπέμπετο τοὺς πανταχόθεν στόλους πρὸς αὑτόν, ἀνδρὶ τολμητῇ καὶ νενικηκότι τῷ Φιμβρίᾳ συμπλέκεσθαι καὶ πολεμεῖν ἀπεγνωκώς. ὁ δὲ ταῦτα συνορῶν, ναυτικῷ δὲ λειπόμενος πρὸς Λούκουλλον ἔπεμπεν, ἥκειν τῷ στόλῳ δεόμενος καὶ συνεξελεῖν ἔχθιστον καὶ πολεμιώτατον βασιλέων, ὡς μὴ τὸ μέγα καὶ διὰ πολλῶν ἀγώνων καὶ πόνων διωκόμενον ἆθλον ἐκφύγοι Ῥωμαίους, Μιθριδάτης εἰς λαβὰς ἥκων καὶ γεγονὼς ἐντὸς ἀρκύων, οὗ ληφθέντος οὐδένα τῆς δόξης οἴσεσθαι πλέον ἢ τὸν ἐμποδὼν τῇ φυγῇ στάντα καὶ διαδιδράσκοντος ἐπιλαβόμενον· ὑφ’ ἑαυτοῦ μὲν ἐξεωσμένον τῆς γῆς, ὑπ’ ἐκείνου δὲ τῆς θαλάττης εἰργόμενον ἀμφοτέροις ἀποδώσειν τὸ κατόρθωμα, τὰς δὲ Σύλλα πρὸς Ὀρχομενῷ καὶ περὶ Χαιρώνειαν ὑμνουμένας ἀριστείας ἐν οὐδενὶ λόγῳ θήσεσθαι Ῥωμαίους. καὶ οὐδὲν ἦν ἀπὸ τρόπου τῶν λεγομένων, ἀλλὰ παντὶ δῆλον, ὡς, εἰ Φιμβρίᾳ τότε πεισθεὶς ὁ Λούκουλλος οὐ μακρὰν ὢν περιήγαγεν ἐκεῖσε τὰς ναῦς καὶ συνέφραξε τὸν λιμένα τῷ στόλῳ, πέρας ἂν εἶχεν ὁ πόλεμος καὶ μυρίων ἀπηλλαγμένοι κακῶν ἅπαντες ἦσαν. ἀλλ’ εἴτε τὰ πρὸς Σύλλαν δίκαια πρεσβεύων πρὸ παντὸς ἰδίου τε καὶ κοινοῦ συμφέροντος, εἴτε τὸν Φιμβρίαν μιαρὸν ὄντα καὶ φονέα γεγενημένον ἔναγχος ἀνδρὸς φίλου καὶ στρατηγοῦ διὰ φιλαρχίαν προβαλλόμενος, εἴτε κατὰ θείαν δή τινα τύχην περιφεισάμενος αὐτὸς τοῦ Μιθριδάτου καὶ φυλάξας ἀνταγωνιστήν, οὐχ ὑπήκουσεν, ἀλλὰ Μιθριδάτῃ μὲν ἐκπλεῦσαι παρέσχε καὶ καταγελάσαι τῆς Φιμβρίου δυνάμεως, αὐτὸς δὲ πρῶτον μὲν ἐπὶ Λεκτοῦ τῆς Τρῳάδος βασιλικὰς ναῦς ἐπιφανείσας κατεναυμάχησεν, αὖθις δὲ πρὸς Τενέδῳ ναυλοχοῦντα μείζονι παρασκευῇ κατιδὼν Νεοπτόλεμον ἐπέπλει πρὸ τῶν ἄλλων, Ῥοδιακῆς πεντήρους ἐπιβεβηκώς, ἧς ἐναυάρχει Δαμαγόρας, ἀνὴρ εὔνους τε Ῥωμαίοις καὶ θαλασσίων ἀγώνων ἐμπειρότατος. ἐπελαύνοντος δὲ ῥοθίῳ τοῦ Νεοπτολέμου καὶ κελεύσαντος εἰς ἐμβολὴν ἀγαγεῖν τὸν κυβερνήτην, δείσας ὁ Δαμαγόρας τὸ βάρος τῆς βασιλικῆς καὶ τὴν τραχύτητα τοῦ χαλκώματος οὐκ ἐτόλμησε συμπεσεῖν ἀντίπρῳρος, ἀλλ’ ὀξέως ἐκ περιαγωγῆς ἀποστρέψας ἐκέλευσεν ἐπὶ πρύμναν ὤσασθαι καὶ πιεσθείσης ἐνταῦθα τῆς νεώς ἐδέξατο τὴν πληγήν ἀβλαβῆ γενομένην, ἅτε δὴ τοῖς θαλαττεύουσι τῆς νεώς μέρεσι προσπεσοῦσαν. ἐν τούτῳ δὲ τῶν φίλων προσφερομένων, ἐγκελευσάμενος ὁ Λούκουλλος ἐπιστρέφειν καὶ πολλὰ δράσας ἄξια λόγου τρέπεται τοὺς πολεμίους καὶ καταδιώκει τὸν Νεοπτόλεμον.", "st": "Luc. 3.4"}, {"sp": "N", "t": "ἐκεῖθεν δὲ Σύλλᾳ περὶ Χερρόνησον ἤδη μέλλοντι διαβαίνειν συμβαλὼν τόν τε πόρον ἀσφαλῆ παρεῖχε καὶ τήν στρατιὰν συνδιεβίβαζεν, ἐπεὶ δὲ συνθηκῶν γενομένων Μιθριδάτης μὲν ἀπέπλευσεν εἰς τὸν Εὔξεινον πόντον, Σύλλας δὲ τήν Ἀσίαν δισμυρίοις ταλάντοις ἐζημίωσε, προσταχθὲν οὕτω τά τε χρήματα ταῦτα πρᾶξαι καὶ νόμισμα κόψαι, παραμύθιόν τι δοκεῖ τῆς Σύλλα χαλεπότητος γενέσθαι ταῖς πόλεσιν, οὐ μόνον καθαρὸν καὶ δίκαιον, ἀλλὰ καὶ πρᾷον εἰς οὕτω βαρὺ καὶ σκυθρωπὸν ὑπηρέτημα παρασχὼν ἑαυτόν. Μιτυληναίους δ’ ἄντικρυς ἀφεστῶτας ἐβούλετο μὲν εὐγνωμονῆσαι καὶ δίκης τυχεῖν μετρίας ἐφ’ οἷς περὶ Μάριον ἐξήμαρτον, ὡς δ’ ἑώρα κακοδαιμονοῦντας, ἐπιπλεύσας ἐκράτησε μάχῃ καὶ κατέκλεισεν εἰς τὰ τείχη, καὶ πολιορκίαν συστησάμενος ἐξέπλευσε μὲν ἡμέρας καὶ φανερῶς εἰς Ἐλαίαν, ὑπέστρεψε δὲ λεληθότως καὶ περὶ τήν πόλιν ὑφεὶς ἐνέδραν ἡσύχαζεν. ἐπεὶ δ’ ἀτάκτως καὶ μετὰ θράσους ὡς ἔρημον ἁρπασόμενοι τὸ στρατόπεδον οἱ Μιτυληναῖοι προῆλθον, ἐπεισπεσὼν αὐτοῖς ἔλαβέ τε παμπόλλους ζῶντας καὶ τῶν ἀμυνομένων πεντακοσίους ἀπέκτεινεν, ἀνδραπόδων δὲ χιλιάδας ἓξ καὶ τὴν ἄλλην ἀναρίθμητον ἠλάσατο λείαν.", "st": "Luc. 4.1"}, {"sp": "N", "t": "τῶν δὲ περὶ τήν Ἰταλίαν κακῶν, ἃ τότε Σύλλας καὶ Μάριος ἄφθονα καὶ παντοδαπὰ τοῖς ἀνθρώποις παρεῖχον, οὐ πάνυ μετέσχε θείᾳ τινὶ τύχῃ περὶ τὰς ἐν Ἀσίᾳ πράξεις βραδύνας. οὐ μὴν ἔλαττόν τι παρὰ Σύλλα τῶν ἄλλων φίλων ἔσχεν, ἀλλὰ τήν τε γραφὴν, ὡς εἴρηται, τῶν ὑπομνημάτων ἐκείνῳ δι’ εὔνοιαν ἀνέθηκε, καὶ τελευτῶν ἐπίτροπον τοῦ παιδὸς ἔγραψεν ὑπερβὰς Πομπήιον. καὶ δοκεῖ τοῦτο πρῶτον αὐτοῖς ὑπάρξαι διαφορᾶς αἴτιον καὶ ζηλοτυπίας νέοις οὖσι καὶ διαπύροις πρὸς δόξαν.", "st": "Luc. 4.4"}, {"sp": "N", "t": "ὀλίγῳ δ’ ὕστερον ἢ Σύλλαν ἀποθανεῖν ὑπάτευσε μετὰ Μάρκου Κόττα περὶ τὴν ἕκτην καὶ ἑβδομηκοστὴν πρὸς ταῖς ἑκατὸν ὀλυμπιάδα. πολλῶν οὖν αὖθις ἀνακινούντων τὸν Μιθριδατικὸν πόλεμον, ἔφη Μᾶρκος αὐτὸν οὐ πεπαῦσθαι, ἀλλ’ ἀναπεπαῦσθαι. διὸ καὶ λαχὼν τῶν ἐπαρχιῶν ὁ Λούκουλλος τὴν ἐντὸς Ἄλπεων Γαλατίαν ἤχθετο, πράξεων ὑποθέσεις μεγάλων οὐκ ἔχουσαν. μάλιστα δ’ αὐτὸν εὐδοκιμῶν Πομπήιος ἐν Ἰβηρίᾳ παρώξυνεν, ὡς ἄλλος οὐδεὶς ἐπίδοξος ὤν, εἰ συμβαίη παύσασθαι τὸν Ἰβηρικὸν πόλεμον, εὐθὺς αἱρεθήσεσθαι στρατηγὸς ἐπὶ Μιθριδάτην. διὸ καὶ χρήματα αἰτοῦντος αὐτοῦ καὶ γράφοντος, ὡς, εἰ μὴ πέμποιεν, ἀφεὶς Ἰβηρίαν καὶ Σερτώριον εἰς Ἰταλίαν ἀπάξοι τὰς δυνάμεις, συνέπραξεν ὁ Λούκουλλος προθυμότατα πεμφθῆναι τὰ χρήματα καὶ μηδ’ ἀφ’ ἡστινοσοῦν προφάσεως ἐκεῖνον ἐπανελθεῖν ὑπατεύοντος αὐτοῦ· πάντα γὰρ ἂν ἐπ’ ἐκείνῳ γενήσεσθαι τὰ τῆς πόλεως παρόντι μετὰ τοσαύτης στρατιᾶς, καὶ γὰρ ὁ κρατῶν τότε τῆς πολιτείας τῷ πρὸς χάριν ἅπαντα καὶ λέγειν καὶ πράττειν Κέθηγος ἔχθραν τινὰ πρὸς Λούκουλλον εἶχε, βδελυττόμενον αὐτοῦ τὸν βίον αἰσχρῶν ἐρώτων καὶ ὕβρεως καὶ πλημμελείας μεστὸν ὄντα. τοῦτον μὲν οὖν ἄντικρυς ἐπολέμει· Λεύκιον δὲ Κόϊντον, ἄλλον δημαγωγόν, ἐπαναστάντα τοῖς Σύλλα πολιτεύμασι καὶ ταράττειν τὰ πράγματα πειρώμενον ἐκ τοῦ καθεστῶτος, ἰδίᾳ τε πολλὰ παραμυθούμενος καὶ δημοσίᾳ νουθετῶν ἀπέστησε τῆς πείρας καὶ κατεστόρεσε τὴν φιλοτιμίαν, ὡς ἐνῆν μάλιστα πολιτικῶς καὶ σωτηρίως ἀρχὴν νοσήματος μεγάλου μεταχειρισάμενος.", "st": "Luc. 5.1"}, {"sp": "N", "t": "ἐν τούτῳ δ’ ὁ τὴν Κιλικίαν ἔχων Ὀκτάουϊος ἠγγέλθη τεθνηκώς. σπαργώντων δὲ πολλῶν πρὸς τὴν ἐπαρχίαν καὶ Κέθηγον ὡς δυνατώτατον ὄντα διαπράξασθαι θεραπευόντων, αὐτῆς μὲν ὁ Λούκουλλος Κιλικίας οὐ πολὺν εἶχε λόγον, οἰόμενος δ’, εἰ λάβοι ταύτην, ἐγγὺς οὔσης Καππαδοκίας, ἄλλον οὐδένα πεμφθήσεσθαι πολεμήσοντα Μιθριδάτῃ, πᾶσαν ἔστρεφε μηχανὴν ὑπὲρ τοῦ μὴ προέσθαι τὴν ἐπαρχίαν ἑτέρῳ. καὶ τελευτῶν ἔργον οὐ σεμνὸν οὐδ’ ἐπαινετόν, ἄλλως δ’ ἀνύσιμον πρὸς τὸ τέλος ἐκ τῆς ἀνάγκης ὑπέμεινε παρὰ τὴν ἑαυτοῦ φύσιν.", "st": "Luc. 6.1"}, {"sp": "N", "t": "Πραικία τις ἦν ὄνομα τῶν ἐφ’ ὥρᾳ καὶ λαμυρίᾳ διαβοήτων ἐν τῇ πόλει, τὰ μὲν ἄλλα κρείττων οὐδὲν ἀνέδην ἑταιρούσης γυναικός, ἐκ δὲ τοῦ χρῆσθαι τοῖς ἐντυγχάνουσιν αὐτῇ καὶ διαλεγομένοις πρὸς τὰς ὑπὲρ τῶν φίλων σπουδὰς καὶ πολιτείας προσλαβοῦσα τῇ λοιπῇ χάριτι τὸ δοκεῖν φιλέταιρός τις εἶναι καὶ δραστήριος ἴσχυσε μέγιστον. ὡς δὲ καὶ Κέθηγον ἀνθοῦντα τῇ δόξῃ τότε καὶ φέροντα τὴν πόλιν ὑπηγάγετο καὶ συνῆν ἐρῶντι, παντάπασιν εἰς ἐκείνην περιῆλθεν ἡ τῆς πόλεως δύναμις· οὐδὲ γὰρ ἐπράττετό τι δημοσίᾳ Κεθήγου μὴ σπουδάζοντος οὐδὲ Πραικίας μὴ κελευούσης παρὰ Κεθήγῳ. ταύτην οὖν ὑπελθὼν δώροις ὁ Λουκούλλος καὶ κολακείαις ἦν δέ που καὶ τῷ Λουκούλλῳ συμφιλοτιμουμένην ὁρᾶσθαι μέγας γυναικὶ σοβαρᾷ καὶ πανηγυρικῇ μισθός, εὐθὺς εἶχε τὸν Κέθηγον ἐπαινέτην καὶ προμνώμενον αὐτῷ Κιλικίαν. ἐπεὶ δ’ ἅπαξ ἔτυχε ταύτης, οὐδὲν ἔτι Πραικίαν οὐδὲ Κέθηγον ἔδει παρακαλεῖν, ἀλλὰ πάντες ὁμαλῶς ἐκείνῳ φέροντες ἐνεχείρισαν τὸν Μιθριδατικὸν πόλεμον ὡς ὑφ’ ἑτέρου μηδενὸς ἄμεινον διαπολεμηθῆναι δυνάμενον, Πομπηΐου μὲν ἔτι Σερτωρίῳ προσπολεμοῦντος, Μετέλλου δ’ ἀπειρηκότος ἤδη διὰ γῆρας, οὓς μόνους ἄν τις ἐναμίλλους ἐποιήσατο Λουκούλλῳ περὶ τῆς στρατηγίας ἀμφισβητοῦντας. οὐ μὴν ἀλλὰ Κόττας ὁ συνάρχων αὐτοῦ πολλὰ λιπαρήσας τὴν σύγκλητον ἀπεστάλη μετὰ νεῶν τὴν Προποντίδα φυλάξων καὶ προπολεμήσων Βιθυνίας.", "st": "Luc. 6.3"}, {"sp": "N", "t": "Λούκουλλος δὲ τάγμα μὲν αὐτόθεν ἔχων συντεταγμένον ὑπ’ αὐτοῦ διέβαινεν εἰς τὴν Ἀσίαν ἐκεῖ δὲ τὴν ἄλλην παρέλαβε δύναμιν, πάντων μὲν πάλαι τρυφαῖς διεφθορότων καὶ πλεονεξίαις, τῶν δὲ Φιμβριανῶν λεγομένων καὶ διὰ συνήθειαν ἀναρχίας δυσμεταχειρίστων γεγονότων. οὗτοι γὰρ ἦσαν οἱ Φλάκκον τε μετὰ Φιμβρίου τὸν ὕπατον καὶ στρατηγὸν ἀνῃρηκότες αὐτόν τε τὸν Φιμβρίαν Σύλλᾳ προδεδωκότες, αὐθάδεις μὲν ἄνθρωποι καὶ παράνομοι, μάχιμοι δὲ καὶ τλήμονες μετ’ ἐμπειρίας πολέμου, οὐ μὴν ἀλλὰ βραχεῖ χρόνῳ καὶ τούτων τὸ θράσος ὁ Λούκουλλος ἐξέκοψε καὶ τοὺς ἄλλους ἐπέστρεψε, τότε πρῶτον, ὡς ἔοικε, πειρωμένους ἄρχοντος ἀληθινοῦ καὶ ἡγεμόνος· ἄλλως δ’ ἐδημαγωγοῦντο πρὸς ἡδονὴν ἐθιζόμενοι στρατεύεσθαι.", "st": "Luc. 7.1"}, {"sp": "N", "t": "τὰ δὲ τῶν πολεμίων οὕτως εἶχε. Μιθριδάτης, ὥσπερ οἱ πολλοὶ τῶν σοφιστῶν, κομπώδης ἐν ἀρχῇ καὶ σοβαρὸς ἐπὶ Ῥωμαίους ἀναστὰς διακένῳ δυνάμει, λαμπρᾷ δὲ καὶ πανηγυρικῇ τὴν ὄψιν, εἶτ’ ἐκπεσὼν καταγελάστως καὶ νουθετηθείς, ὅτε τὸ δεύτερον πολεμεῖν ἔμελλεν, εἰς ἀληθινὴν καὶ πραγματικὴν συνέστελλε τὰς δυνάμεις παρασκευήν. ἀφελὼν γὰρ τὰ παντοδαπὰ πλήθη καὶ τὰς πολυγλώσσους ἀπειλὰς τῶν βαρβάρων, ὅπλων τε διαχρύσων καὶ διαλίθων κατασκευάς, ὡς λάφυρα τῶν κρατούντων, οὐκ ἀλκήν τινα τῶν κεκτημένων ὄντα, ξίφη μὲν ἠλαύνετο Ῥωμαϊκά καὶ θυρεοὺς ἐμβριθεῖς ἐπήγνυτο καὶ γεγυμνασμένους μᾶλλον ἢ κεκοσμημένους ἤθροιζεν ἵππους, πεζῶν δὲ μυριάδας δώδεκα κατεσκευασμένων εἰς φάλαγγα Ῥωμαϊκήν, ἱππεῖς δὲ πρὸς μυρίοις ἑξακισχιλίους ἄνευ τῶν δρεπανηφόρων τεθρίππων ταῦτα δ’ ἦν ἑκατόν· ἔτι δὲ ναῦς οὐ χρυσορόφοις σκηνίσιν οὐδὲ λουτροῖς παλλακίδων καὶ γυναικωνίτισι τρυφώσαις ἠσκημένας, ἀλλ’ ὅπλων καὶ βελῶν καὶ χρημάτων γεμούσας παραρτυσάμενος ἐνέβαλεν εἰς Βιθυνίαν, τῶν πόλεων αὖθις ἀσμένως ὑποδεχομένων οὐ μόνον τούτων, ἀλλὰ καὶ τὴν Ἀσίαν ὅλην ὑποτροπὴ τῶν ἔμπροσθεν νοσημάτων εἶχεν, ἀφόρητα πάσχουσαν ὑπὸ Ῥωμαϊκῶν δανειστῶν καὶ τελωνῶν· οὓς ὕστερον μὲν ὥσπερ Ἁρπυίας τὴν τροφὴν ἁρπάζοντας αὐτῶν ὁ Λούκουλλος ἐξήλασε, τότε δὲ μετριωτέρους ἐπειρᾶτο νουθετῶν ποιεῖν, καὶ τὰς ἀποστάσεις κατέπαυε τῶν δήμων, οὐδενὸς, ὡς ἔπος εἰπεῖν, ἡσυχάζοντος.", "st": "Luc. 7.3"}, {"sp": "N", "t": "ὃν δὲ περὶ ταῦτα Λούκουλλος ἠσχολεῖτο χρόνον αὑτοῦ καιρὸν εἶναι νομίζων ὁ Κόττας παρεσκευάζετο μάχεσθαι πρὸς Μιθριδάτην. καὶ πολλῶν ἀπαγγελλόντων ἤδη Λούκουλλον ἐν Φρυγίᾳ στρατοπεδεύειν ἐπιόντα, μόνον οὐκ ἐν ταῖς χερσὶν ἔχειν τὸν θρίαμβον οἰόμενος, ὡς μὴ μεταλάβῃ Λούκουλλος αὐτοῦ, συμβαλεῖν ἔσπευσε. πληγεὶς δ’ ἅμα καὶ κατὰ γῆν καὶ κατὰ θάλατταν ἑξήκοντα μὲν ἀπώλεσεν αὔτανδρα σκάφη, πεζοὺς δὲ τετρακισχιλίους, αὐτὸς δὲ κατακλεισθεὶς εἰς Χαλκηδόνα καὶ πολιορκούμενος εἰς τὰς Λουκούλλου χεῖρας ἀπέβλεπεν.", "st": "Luc. 8.1"}, {"sp": "N", "t": "ἦσαν μὲν οὖν οἱ τὸν Λούκουλλον ἀμελήσαντα Κόττα πρόσω χωρεῖν παρορμῶντες ὡς ἔρημον αἱρήσοντα τὴν Μιθριδάτου βασιλείαν, καὶ μάλιστα τῶν στρατιωτῶν οὗτος ἦν ὁ λόγος, ἀγανακτούντων, εἰ μὴ μόνον αὑτὸν ἀπολεῖ καὶ τοὺς σὺν αὐτῷ βουλευσάμενος κακῶς ὁ Κόττας, ἀλλὰ καὶ σφίσιν ἐμποδὼν ἔσται νικᾶν ἀμαχεῖ δυναμένοις. Λούκουλλος δὲ πρὸς μὲν τούτους δημηγορῶν εἶπεν, ὡς ἕνα βούλοιτ’ ἂν ἐκ πολεμίων σῶσαι Ῥωμαῖον ἢ πάντα λαβεῖν τὰ τῶν πολεμίων Ἀρχελάου δὲ τοῦ περὶ Βοιωτίαν Μιθριδάτῃ στρατηγήσαντος, εἶτ’ ἀποστάντος καὶ Ῥωμαίοις συστρατεύοντος, διαβεβαιουμένου ὀφθέντα Λούκουλλον ἐν Πόντῳ πάντων ὁμοῦ κρατήσειν, οὐκ ἔφη δειλότερος εἶναι τῶν κυνηγῶν, ὥστε τὰ θηρία παρελθὼν ἐπὶ κενοὺς αὐτῶν τοὺς φωλεοὺς βαδίζειν. καὶ ταῦτ’ εἰπὼν ἐπὶ Μιθριδάτην προῆγε πεζοὺς μὲν ἔχων τρισμυρίους, ἱππεῖς δὲ δισχιλίους πεντακοσίους, καταστὰς δ’ εἰς ἔποψιν τῶν πολεμίων καὶ θαυμάσας τὸ πλῆθος ἐβούλετο μὲν ἀπέχεσθαι μάχης καὶ τρίβειν τὸν χρόνον, Μαρίου δ’, ὃν Σερτώριος ἐξ Ἰβηρίας ἀπεστάλκει Μιθριδάτῃ μετὰ δυνάμεως στρατηγόν, ἀπαντήσαντος αὐτῷ καὶ προκαλουμένου κατέστη μὲν εἰς τάξιν ὡς διαμαχούμενος, ἤδη δὲ ὅσον οὔπω συμφερομένων, ἀπ’ οὐδεμιᾶς ἐπιφανοῦς μεταβολῆς, ἀλλ’ ἐξαίφνης τοῦ ἀέρος ὑπορραγέντος ὤφθη μέγα σῶμα φλογοειδὲς εἰς μέσον τῶν στρατοπέδων καταφερόμενον, τὸ μὲν σχῆμα πίθῳ μάλιστα, τὴν δὲ χρόαν ἀργύρῳ διαπύρῳ προσεοικός, ὥστε δείσαντας ἀμφοτέρους τὸ φάσμα διακριθῆναι. τοῦτο μὲν οὖν φασιν ἐν Φρυγίᾳ περὶ τὰς λεγομένας Ὀτρύας συμβῆναι τὸ πάθος.", "st": "Luc. 8.3"}, {"sp": "N", "t": "ὁ δὲ Λούκουλλος οὐδεμιᾶς εἶναι νομίζων ἀνθρωπίνης παρασκευῆς οὐδὲ πλούτου θρέψαι μυριάδας ἐπὶ πολὺν χρόνον ἀντικαθημένων πολεμίων τοσαύτας, ὅσας εἶχε Μιθριδάτης, ἐκέλευσεν ἀχθῆναι τῶν αἰχμαλώτων ἕνα· καὶ πρῶτον ἀνέκρινε, μετὰ πόσων διαιτῷτο συσκήνων, ἔπειτα πόσον ἐν τῇ σκηνῇ καταλέλοιπε σῖτον. ἀποκριναμένου δὲ τἀνθρώπου τὸν μὲν ἐκέλευσε μεταστῆναι, δεύτερον δὲ καὶ τρίτον ὁμοίως ἀνέκρινεν. εἶτα συνθεὶς τὸ τῆς παρεσκευασμένης τροφῆς πλῆθος πρὸς τὸ τῶν τρεφομένων, ἔγνω τριῶν ἢ τεσσάρων ἡμερῶν ἐπιλείψοντα σῖτον τοὺς πολεμίους, καὶ πολὺ μᾶλλον εἴχετο τοῦ χρόνου, καὶ συνῆγεν εἰς τὸν χάρακα παμπληθῆ σῖτον, ὡς ἐν ἀφθόνοις διάγων αὐτὸς ἐφεδρεύοι ταῖς ἐκείνων ἀπορίαις.", "st": "Luc. 8.8"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Μιθριδάτης ἐπεβούλευε Κυζικηνοῖς πεπληγόσιν ἐν τῇ περὶ Χαλκηδόνα μάχῃ· τρισχιλίων γὰρ ἀνδρῶν καὶ δέκα νεῶν ἐστέρηντο. βουλόμενος οὖν λαθεῖν τὸν Λούκουλλον, εὐθὺς ἀπὸ δείπνου νύκτα δυσφανῆ καὶ νοτερὰν ἔχων ἐκίνει καὶ φθάνει τῆς πόλεως ἄντικρυς ἅμ’ ἡμέρᾳ περὶ τὸ τῆς Ἀδραστείας ὄρος ἱδρύσας τὴν δύναμιν. ὁ δὲ Λούκουλλος αἰσθόμενος καὶ διώξας ἠγάπησε μὲν οὐκ ἐμπεσὼν ἀσύντακτος εἰς τοὺς πολεμίους, καθίζει δὲ τὸν στρατὸν περὶ τὴν Θρᾳκίαν λεγομένην κώμην ἐν τόπῳ κατὰ τῶν ὁδῶν ἄριστα πεφυκότι καὶ τῶν χωρίων, ἀφ’ ὧν καὶ δι’ ὧν ἀναγκαῖον ἦν τοῖς Μιθριδατικοῖς τὰ ἐπιτήδεια φοιτᾶν. διὸ καὶ περιλαβὼν τῇ διανοίᾳ τὸ μέλλον οὐκ ἀπεκρύψατο τοὺς στρατιώτας, ἀλλ’ ἅμα τῷ θέσθαι τὸ στρατόπεδον καὶ ἀπὸ τῶν ἔργων γενέσθαι συναγαγὼν αὐτοὺς ἐμεγαληγόρησεν, ὡς ὀλίγων ἡμερῶν ἀναιμωτὶ τὸ νίκημα παραδώσων αὐτοῖς.", "st": "Luc. 9.1"}, {"sp": "N", "t": "Κυζικηνοὺς δὲ Μιθριδάτης δέκα μὲν ἐκ γῆς στρατοπέδοις περιλαβών, ταῖς δὲ ναυσὶν ἐκ θαλάσσης τὸν ἀπὸ τῆς ἠπείρου διείργοντα τὴν πόλιν εὔριπον ἐμφράξας, ἑκατέρωθεν ἐπολιόρκει, τὰ μὲν ἄλλα διακειμένους πρὸς τὸν κίνδυνον εὐθαρσῶς καὶ πᾶν ἕνεκα Ῥωμαίων ἐγνωκότας ἐκδέχεσθαι δυσχερές, ἀγνοοῦντας δὲ ὅπῃ Λούκουλλος εἴη καὶ τῷ μηδὲν περὶ αὐτοῦ πεπύσθαι ταραττομένους. καίτοι καταφανὴς ἦν ἡ στρατοπεδεία καὶ ἄποπτος, ἀλλ’ ὑπὸ τῶν Μιθριδατικῶν ἐξηπατῶντο. δεικνύντες γὰρ αὐτοῖς τοὺς Ῥωμαίους ἄνω παρεμβεβληκότας ὁρᾶτε τούτους; ἔφασαν, Ἀρμενίων στρατός ἐστι καὶ Μήδων, Τιγράνου Μιθριδάτῃ καταπέμψαντος ἐπικουρίαν οἱ δ’ ἐξεπλήσσοντο τοσούτου πολέμου περικεχυμένου μηδ’, εἰ παραγένοιτο Λούκουλλος, χώραν ἔτι λελεῖφθαι βοηθείας ἐλπίζοντες.", "st": "Luc. 9.3"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ πρῶτος αὐτοῖς εἰσπεμφθεὶς ὑπ’ Ἀρχελάου Δημῶναξ ἔφρασε τὴν τοῦ Λουκούλλου παρουσίαν. τούτων δ’ ἀπιστούντων καὶ νομιζόντων αὐτὸν τῶν παρόντων ἐπὶ παρηγορίᾳ πεπλασμένα λέγειν, ἧκε παιδάριον αἰχμάλωτον ἐκ τῶν πολεμίων ἀποδεδρακός. πυνθανομένων δ’ αὐτῶν, ποῦ λέγοι τὸν Λούκουλλον εἶναι, κατεγέλα παίζειν αὐτοὺς οἰόμενον. ὡς δ’ ἑώρα σπουδάζοντας, ἐσήμηνε τῇ χειρὶ τὸν χάρακα τῶν Ῥωμαίων, οἱ δ’ ἀνεθάρσησαν. τῆς δὲ Δασκυλίτιδος λίμνης πλεομένης ἀκατίοις ἐπιεικῶς εὐμεγέθεσι, τὸ μέγιστον αὐτῶν ὁ Λούκουλλος ἀνελκύσας καὶ διαγαγὼν ἁμάξῃ πρὸς τὴν θάλατταν ὅσους ἐχώρει στρατιώτας ἐνεβίβασεν. ἔλαθον δὲ νυκτὸς διαπεράσαντες καὶ παρεισῆλθον εἰς τὴν πόλιν.", "st": "Luc. 9.5"}, {"sp": "N", "t": "ἔοικε δὲ καὶ τὸ θεῖον ἐπιθαρρῦναι τοὺς Κυζικηνούς, ἀγασθὲν αὐτῶν τὴν ἀνδραγαθίαν, ἄλλοις τε σημείοις ἐναργέσι, καὶ τῆς τῶν Φερεφαττίων ἑορτῆς ἐνεστώσης οἱ μὲν ἠπόρουν βοὸς μελαίνης πρὸς τὴν θυσίαν καὶ σταιτίνην πλάσαντες τῷ βωμῷ παρέστησαν, ἡ δ’ ἱερὰ καὶ τρεφομένη τῇ θεῷ νομὴν μὲν εἶχεν, ὥσπερ τἆλλα βοτὰ τῶν Κυζικηνῶν, ἐν τῇ περαίᾳ, κατ’ ἐκείνην δὲ τὴν ἡμέραν ἀποκριθεῖσα τῆς ἀγέλης μόνη διενήξατο πρὸς τὴν πόλιν καὶ κατέστησεν ἐπὶ τὴν θυσίαν αὑτήν. ὄναρ δ’ ἡ θεὸς Ἀρισταγόρᾳ τῷ τοῦ δήμου γραμματιστῇ παραστᾶσα, καὶ μὴν ἔγωγε, εἶπεν, ἥκω τὸν Λιβυκὸν αὐλητὴν ἐπὶ τὸν Ποντικὸν σαλπιγκτὴν ἐπάγουσα. φράσον οὖν θαρρεῖν τοῖς πολίταις. θαυμαζόντων δὲ τὴν φωνὴν τῶν Κυζικηνῶν ἅμ’ ἡμέρᾳ σάλον εἶχεν ἡ θάλασσα κατιόντος ἀκρίτου πνεύματος, αἵ τε μηχαναὶ τοῦ βασιλέως παρεστῶσαι τοῖς τείχεσιν, ἔργα θαυμαστὰ Νικωνίδου τοῦ Θεσσαλοῦ, ῥοίζῳ καὶ πατάγῳ πρῶτον ἀπεδήλουν τὸ μέλλον· εἶτα νότος ἐκραγεὶς ἄπιστος τὸ μέγεθος τά τ’ ἄλλα συνέτριψε μηχανήματα ὥρας βραχεῖ μορίῳ, καὶ τὸν ξύλινον πύργον ἑκατὸν πηχῶν ὕψος ὄντα διασείσας κατέβαλεν. ἱστορεῖται δὲ τῶν ἐν Ἰλίῳ πολλοῖς καθ’ ὕπνον ὀφθῆναι τὴν Ἀθηνᾶν ἱδρῶτι πολλῷ ῥεομένην καὶ ὑποφαίνουσάν τι τοῦ πέπλου παρερρωγός, λέγουσαν, ὡς ἀρτίως ἥκοι βοηθήσασα Κυζικηνοῖς. καὶ στήλην τινὰ δόγματα καὶ γράμματα περὶ τούτων ἔχουσαν ἐδείκνυον Ἰλιεῖς.", "st": "Luc. 10.1"}, {"sp": "N", "t": "Μιθριδάτην δέ, ἄχρι μὲν ὑπὸ τῶν ἑαυτοῦ στρατηγῶν φενακιζόμενος ἠγνόει τὸν ἐν τῷ στρατοπέδῳ λιμόν, ἠνίων Κυζικηνοὶ διαφεύγοντες τὴν πολιορκίαν. ταχὺ δ’ ἐξερρύη τὸ φιλότιμον αὐτοῦ καὶ φιλόνεικον ἐν αἰσθήσει γενομένου τῶν ἀποριῶν, αἷς οἱ στρατιῶται συνείχοντο, καὶ τῶν ἀνθρωποφαγιῶν, ἅτε δὴ μὴ θεατρικῶς μηδ’ ἐπιδεικτικῶς Λουκούλλου πολεμοῦντος, ἀλλὰ, τοῦτο δὴ τὸ λεγόμενον, εἰς τὴν γαστέρα ἐναλλομένου καὶ ὅπως ὑφαιρήσει τὴν τροφὴν ἅπαντα πραγματευομένου. διὸ καὶ φρούριόν τι πολιορκοῦντος αὐτοῦ τῷ καιρῷ χρήσασθαι σπεύδων ὁ Μιθριδάτης ἐξέπεμψεν εἰς Βιθυνίαν τοὺς μὲν ἱππεῖς σχεδὸν ἅπαντας μετὰ τῶν ὑποζυγίων, τῶν δὲ πεζῶν τοὺς ἀχρήστους, πυθόμενος δ’ ὁ Λούκουλλος ἔτι νυκτὸς ἧκεν εἰς τὸ στρατόπεδον, πρωὶ δὲ χειμῶνος ὄντος ἀναλαβὼν σπείρας δέκα καὶ τὴν ἵππον ἐδίωκε νιφόμενος καὶ κακοπαθῶν, ὥστε πολλοὺς ὑπὸ κρύους ἐνδιδόντας ἀπολείπεσθαι τῶν στρατιωτῶν, τοῖς δ’ ἄλλοις περὶ τὸν Ῥυνδακὸν ποταμόν καταλαβὼν τοὺς πολεμίους τοσαύτην τροπὴν ἐποίησεν, ὥστε τὰς γυναῖκας ἐκ τῆς Ἀπολλωνίας προερχομένας ἀφαρπάζειν τὰ φορτία καὶ σκυλεύειν τοὺς φονευομένους. πολλῶν δ’, ὡς εἰκὸς, ἀποθανόντων ἑάλωσαν ἵπποι μὲν ἑξακισχίλιοι καὶ πλῆθος ἀναρίθμητον ὑποζυγίων, ἄνδρες δὲ μύριοι πεντακισχίλιοι· καὶ τούτους ἄγων πάντας παρεξῄει παρὰ τὸ στρατόπεδον τῶν πολεμίων. Σαλουστίου δὲ θαυμάζω τότε πρῶτον ὦφθαι Ῥωμαίοις καμήλους λέγοντος, εἰ μήτε πρότερον τοὺς μετὰ Σκηπίωνος νικήσαντας Ἀντίοχον ᾤετο μήτε τοὺς ἔναγχος πρὸς Ὀρχομενῷ καὶ περὶ Χαιρώνειαν Ἀρχελάῳ μεμαχημένους ἐγνωκέναι κάμηλον.", "st": "Luc. 11.1"}, {"sp": "N", "t": "ἀλλὰ τῷ γε Μιθριδάτῃ φεύγειν μὲν ἔγνωστο τὴν ταχίστην, ἀνθολκὰς δὲ Λουκούλλῳ καὶ διατριβὰς ὀπίσω μηχανώμενος ἔστελλε τὸν ναύαρχον Ἀριστόνικον ἐπὶ τὴν Ἑλληνικὴν θάλασσαν· καὶ ὅσον οὔπω μέλλοντος ἐκπλεῖν ἐκ προδοσίας ὁ Λούκουλλος ἐκυρίευσε μετὰ χρυσῶν μυρίων, οὓς ἐκόμιζε διαφθερῶν τι τοῦ Ῥωμαϊκοῦ στρατεύματος, ἐκ τούτου Μιθριδάτης μὲν ἔφυγεν ἐπὶ θάλασσαν, οἱ δὲ στρατηγοὶ πεζοὶ τὸν στρατὸν ἀπήγαγον. ἐπιπεσὼν δὲ Λούκουλλος αὐτοῖς περὶ τὸν Γρανικὸν ποταμόν εἷλέ τε παμπόλλους καὶ δισμυρίους ἀπέκτεινε. λέγονται δ’ ἐκ τοῦ παντὸς ἀκολούθων τε καὶ μαχίμων ὄχλου μυριάδες οὐ πολὺ δὴ τῶν τριάκοντα λείπουσαι διαφθαρῆναι.", "st": "Luc. 11.5"}, {"sp": "N", "t": "Λούκουλλος δὲ πρῶτον εἰς Κύζικον παρελθών ἀπέλαυσεν ἡδονῆς καὶ φιλοφροσύνης πρεπούσης· ἔπειτα ναυτικὸν ἐξηρτύετο τὸν Ἑλλήσποντον ἐπιπορευόμενος. εἰς δὲ Τρῳάδα καταχθείς ἐσκήνωσε μὲν ἐν τῷ ἱερῷ τῆς Ἀφροδίτης, κατακοιμηθεὶς δὲ νύκτωρ ἐδόκει τὴν θεὰν ὁρᾶν ἐφεστῶσαν αὐτῷ καὶ λέγουσαν·", "st": "Luc. 12.1"}, {"sp": "N", "t": "τί κνώσσεις, μεγάθυμε λέον; νεβροὶ δέ τοι ἐγγύς.", "st": "Luc. 12.1b"}, {"sp": "N", "t": "ἐξαναστὰς δὲ καὶ τοὺς φίλους καλέσας διηγεῖτο τὴν ὄψιν ἔτι νυκτὸς οὔσης. καὶ παρῆσαν ἐξ Ἰλίου τινὲς ἀπαγγέλλοντες ὦφθαι περὶ τὸν Ἀχαιῶν λιμένα τρισκαίδεκα πεντήρεις τῶν βασιλικῶν ἐπὶ Λῆμνον πλεούσας, εὐθὺς οὖν ἀναχθείς τούτους μὲν εἷλε καὶ τὸν στρατηγὸν αὐτῶν Ἰσίδωρον ἀπέκτεινεν, ἐπὶ δὲ τοὺς ἄλλους ἔπλει πρωρέας. οἱ δὲ ἔτυχον ὁρμοῦντες, καὶ τὰ πλοῖα πάντα πρὸς τὴν γῆν συνέλκοντες ἀπὸ τῶν καταστρωμάτων διεμάχοντο καὶ πληγὰς ἐδίδοσαν τοῖς περὶ τὸν Λούκουλλον, οὔτε περιπλεῦσαι τοῦ χωρίου διδόντος οὔτε βιάσασθαι ναυσὶ μετεώροις τὰς τῶν πολεμίων προσερηρεισμένας τῇ γῇ καὶ βεβηκυίας ἀσφαλῶς. οὐ μὴν ἀλλὰ μόλις ᾗ προσβολήν τινα ἡ νῆσος εἶχεν ἀποβιβάζει τῶν στρατιωτῶν τοὺς ἀρίστους, οἳ κατόπιν ἐπιπεσόντες τοῖς πολεμίοις τοὺς μὲν διέφθειρον αὐτῶν, τοὺς δ’ ἠνάγκαζον ἀποκόπτοντας τὰ πρυμνήσια τῶν νεῶν καὶ φεύγοντας ἐκ τῆς γῆς ἀλλήλοις τε συγκρούειν τὰ πλοῖα καὶ ταῖς ἐμβολαῖς ταῖς περὶ τὸν Λούκουλλον ὑποπίπτειν. πολλοὶ μὲν οὖν διεφθάρησαν, ἐν δὲ τοῖς ἁλοῦσιν ἀνήχθη καὶ Μάριος ὁ παρὰ Σερτωρίου στρατηγός· ἦν γὰρ ἑτερόφθαλμος, καὶ παρήγγελτο τοῖς στρατιώταις εὐθὺς ἐπιπλέουσιν ὑπὸ Λουκούλλου μηδένα κτείνειν ἑτερόφθαλμον, ὅπως ἐξονειδισθεὶς καὶ καθυβρισθεὶς ἀποθάνοι.", "st": "Luc. 12.2"}, {"sp": "N", "t": "γενόμενος δ’ ἀπὸ τούτων ἠπείγετο πρὸς τὴν αὐτοῦ Μιθριδάτου δίωξιν. ἤλπιζε γὰρ ἔτι περὶ Βιθυνίαν εὑρήσειν αὐτόν ὑπὸ Βοκωνίου φρουρούμενον, ὃν αὐτὸς ἐνστησόμενον τῇ φυγῇ μετὰ νεῶν ἀπεστάλκει πρὸς Νικομήδειαν. ἀλλὰ Βοκώνιος μὲν. ἐν Σαμοθρᾴκῃ μυούμενος καὶ πανηγυρίζων καθυστέρησε· Μιθριδάτην δὲ ἀναχθέντα μετὰ τοῦ στόλου, σπεύδοντα πρὶν ἐπιστρέφειν Λούκουλλον εἰς τὸν Πόντον εἰσπλεῦσαι, καταλαμβάνει χειμὼν πολύς, ὑφ’ οὗ τὰ μὲν ἀφηρπάγη, τὰ δ’ ἐβυθίσθη τῶν σκαφῶν, πᾶσα δ’ ἡ παραλία τῶν ναυαγίων ἐκφερομένων ὑπὸ τοῦ κλύδωνος ἐπὶ πολλὰς ἡμέρας ἦν περίπλεως. αὐτὸς δέ, τῆς ὁλκάδος, ἐφ’ ἧς ἔπλει, μήτε πρὸς τὴν γῆν εὐπαρακομίστου διὰ μέγεθος ἐν σάλῳ μεγάλῳ καὶ κύματι τυφλῷ παρισταμένης τοῖς κυβερνήταις, πρός τε τὴν θάλασσαν ἤδη βαρείας καὶ ὑπεράντλου γενομένης, μετεμβὰς εἰς λῃστρικὸν μυοπάρωνα καὶ τὸ σῶμα πειραταῖς ἐγχειρίσας ἀνελπίστως καὶ παραβόλως εἰς τὴν Ποντικὴν Ἡράκλειαν ἐξεσώθη. Λουκούλλῳ δ’ ἀνεμέσητος ἡ πρὸς τὴν σύγκλητον ἀπέβη φιλοτιμία, ψηφιζομένης γὰρ αὐτῆς πρὸς τὸν πόλεμον ἀπὸ τρισχιλίων ταλάντων ἐξαρτύεσθαι ναυτικόν, ἐκώλυσε πέμψας γράμματα καὶ μεγαληγορήσας, ὡς ἄνευ δαπάνης καὶ τοσαύτης παρασκευῆς ταῖς τῶν συμμάχων ναυσὶ Μιθριδάτην ἐκβαλεῖ τῆς θαλάττης. καὶ τοῦτο ὑπῆρξεν αὐτῷ τοῦ θεοῦ συναγωνισαμένου. λέγεται γὰρ Ἀρτέμιδος χόλῳ Πριαπίνης ὁ χειμὼν ἐμπεσεῖν τοῖς Ποντικοῖς συλήσασιν αὐτῆς τὸ ἱερὸν καὶ τὸ ξόανον ἀνασπάσασι.", "st": "Luc. 13.1"}, {"sp": "N", "t": "πολλῶν δὲ Λουκούλλῳ παραινούντων ἀναβάλλεσθαι τὸν πόλεμον, οὐ φροντίσας ἐνέβαλε διὰ Βιθυνίας καὶ Γαλατίας εἰς τὴν βασιλικήν, ἐν ἀρχῇ μὲν ἐνδεὴς τῶν ἀναγκαίων, ὥστε Γαλάτας ἕπεσθαι τρισμυρίους ἕκαστον ἐπὶ τῶν ὤμων κομίζοντα σίτου μέδιμνον, προϊὼν δὲ καὶ κρατῶν ἁπάντων εἰς τοσαύτην ἦλθεν εὐπορίαν, ὥστε τὸν μὲν βοῦν ἐν στρατοπέδῳ δραχμῆς, τὸ δὲ ἀνδράποδον τεττάρων ὤνιον εἶναι, τὴν δ’ ἄλλην λείαν ἐν οὐδενὶ λόγῳ τοὺς μὲν ἀπολείπειν, τοὺς δὲ ἀναλίσκειν. διάθεσις γὰρ ἦν οὐδενὸς πρὸς οὐδένα πάντων εὐπορούντων.", "st": "Luc. 14.1"}, {"sp": "N", "t": "ἀλλ’ ὅσον φθεῖραι καὶ κακῶσαι τὴν χώραν ἱππασάμενοι καὶ καταδραμόντες ἄχρι Θεμισκύρας καὶ τῶν περὶ Θερμώδοντα πεδίων, ᾐτιῶντο τὸν Λούκουλλον, ὅτι πάσας προσάγεται τὰς πόλεις, κατὰ κράτος δὲ οὐδεμίαν ᾕρηκεν οὐδὲ παρέσχηκεν αὐτοῖς ὠφεληθῆναι διαρπάσασιν. ἀλλὰ καὶ νῦν, ἔφασαν, Ἀμισόν, πόλιν εὐδαίμονα καὶ πλουσίαν, οὐ μέγα ὂν ἔργον, εἴ τις ἐντείναι τὴν πολιορκίαν, κατασχεῖν, ἀπολιπόντας ἡμᾶς ἄγει περὶ τὴν Τιβαρηνῶν καὶ Χαλδαίων ἐρημίαν Μιθριδάτῃ πολεμήσοντας. ἀλλὰ ταῦτα μὲν οὐκ ἂν ὁ Λούκουλλος ἐλπίσας εἰς τοσοῦτον ἀπονοίας τοὺς στρατιώτας παραγαγεῖν, ὅσον ὕστερον ἐξέφηναν, ὑπερεώρα καὶ οὐκ ἐφρόντιζεν, ἐκείνοις δ’ ἀπελογεῖτο μᾶλλον, οἳ βραδυτῆτα κατηγόρουν αὐτοῦ διατρίβοντος ἐνταῦθα περὶ κώμας καὶ πόλεις οὐ πολλοῦ τινος ἀξίας πολὺν χρόνον, ἐῶντος δ’ αὔξεσθαι Μιθριδάτην. αὐτὸ γὰρ, ἔφη, τοῦτο καὶ βούλομαι καὶ κάθημαι τεχνάζων, μέγαν αὖθις γενέσθαι τὸν ἄνδρα καὶ συναγαγεῖν αὐτὸν ἀξιόμαχον δύναμιν, ἵνα μείνῃ καὶ μὴ φύγῃ προσιόντας ἡμᾶς. ἢ οὐχ ὁρᾶτε πολλὴν μὲν αὐτῷ καὶ ἀτέκμαρτον ἐρημίαν ὀπίσω παροῦσαν; ἐγγὺς δὲ ὁ Καύκασος καὶ ὄρη πολλὰ καὶ βαθέα καὶ μυρίους βασιλεῖς φυγομαχοῦντας ἀρκοῦντα κατακρύψαι καὶ περισχεῖν ὀλίγων δ’ ἡμερῶν ὁδὸς εἰς Ἀρμενίαν ἐκ Καβείρων, καὶ ὑπὲρ Ἀρμενίας κάθηται Τιγράνης, βασιλεὺς βασιλέων, ἔχων δύναμιν, ᾗ Πάρθους τε περικόπτει τῆς Ἀσίας καὶ πόλεις Ἑλληνίδας εἰς Μηδίαν ἀνακομίζει καὶ Συρίας κρατεῖ καὶ Παλαιστίνης καὶ τοὺς ἀπὸ Σελεύκου βασιλεῖς ἀποκτιννύει, θυγατέρας δ’ αὐτῶν ἄγει καὶ γυναῖκας ἀνασπάστους. οὗτος οἰκεῖός ἐστι Μιθριδάτου καὶ γαμβρός, οὐ περιόψεται δὲ αὐτὸν ἱκέτην ὑποδεξάμενος, ἀλλὰ πολεμήσει πρὸς ἡμᾶς καὶ σπεύδοντες ἐκβάλλειν Μιθριδάτην κινδυνεύσομεν ἐπισπάσασθαι Τιγράνην, πάλαι μὲν αἰτίας δεόμενον ἐφ’ ἡμᾶς, εὐπρεπεστέραν δὲ οὐκ ἂν λαβόντα τῆς ὑπὲρ ἀνδρὸς οἰκείου καὶ βασιλέως ἀναγκασθέντα ὑπουργεῖν αὐτῷ. τί οὖν δεῖ τοῦθ’ ἡμᾶς ἐξεργάσασθαι καὶ διδάξαι Μιθριδάτην ἀγνοοῦντα, μεθ’ ὧν ἐστιν αὐτῷ πρὸς ἡμᾶς πολεμητέον, καὶ μὴ βουλόμενον, ἀλλ’ ἀδοξοῦντα συνελαύνειν εἰς τὰς Τιγράνου χεῖρας, ἀλλ’ οὐχὶ δόντας αὐτῷ χρόνον ἐκ τῶν οἰκείων παρασκευάσασθαι καὶ ἀναθαρρῦναι, Κόλχοις καὶ Τιβαρηνοῖς καὶ Καππάδοξιν, ὧν πολλάκις κεκρατήκαμεν, μάχεσθαι μᾶλλον ἢ Μήδοις καὶ Ἀρμενίοις;", "st": "Luc. 14.2"}, {"sp": "N", "t": "ἐπὶ τοιούτων λογισμῶν γενόμενος ὁ Λούκουλλος περί τε τὴν Ἀμισὸν διέτριψε, μαλακῶς τῇ πολιορκίᾳ χρώμενος, καὶ μετὰ χειμῶνα Μουρήναν ἀπολιπὼν ἐπὶ τῆς πολιορκίας ἐβάδιζεν ἐπὶ Μιθριδάτην καθήμενον ἐν Καβείροις καὶ διανοούμενον ὑφίστασθαι τοὺς Ῥωμαίους, ἠθροισμένης αὐτῷ δυνάμεως εἰς τετρακισμυρίους πεζούς, ἱππεῖς δὲ τετρακισχιλίους, οἷς ἐθάρρει μάλιστα. καὶ διαβὰς τὸν Λύκον ποταμὸν εἰς τὸ πεδίον προὐκαλεῖτο τοὺς Ῥωμαίους. γενομένης δ’ ἱππομαχίας ἔφυγον οἱ Ῥωμαῖοι· Πομπώνιος δ’ ἀνὴρ οὐκ ἄδοξος ἑάλω τετρωμένος καὶ πρὸς τὸν Μιθριδάτην ἀνήχθη κακῶς ὑπὸ τραυμάτων διακείμενος, πυθομένου δὲ τοῦ βασιλέως, εἰ σωθεὶς ὑπ’ αὐτοῦ γενήσεται φίλος, ἄν γε δή, ἔφη, Ῥωμαίοις διαλλαγῇς· εἰ δὲ μή, πολέμιος. τοῦτον μὲν θαυμάσας ὁ Μιθριδάτης οὐκ ἠδίκησε.", "st": "Luc. 15.1"}, {"sp": "N", "t": "τοῦ δὲ Λουκούλλου τὰ μὲν πεδία τῶν πολεμίων ἱπποκρατούντων δεδιότος, τὴν δ’ ὀρεινὴν ὀκνοῦντος προϊέναι, μακρὰν καὶ ὑλώδη καὶ δύσβατον οὖσαν, ἁλίσκονταί τινες κατὰ τύχην Ἕλληνες εἴς τι σπήλαιον καταφυγόντες, ὧν ὁ πρεσβύτερος Ἀρτεμίδωρος ὑπέσχετο τὸν Λούκουλλον ἄξειν καὶ καταστάσειν ἐπὶ τόπῳ ἀσφαλεῖ τῷ στρατοπέδῳ καὶ φρούριον ἔχοντι τοῖς Καβείροις ἐπικρεμάμενον. πιστεύσας δ’ ὁ Λούκουλλος ἅμα τῇ νυκτὶ πυρὰ καύσας ἐκίνει καὶ τὰ στενὰ παρελθὼν ἀσφαλῶς τὸ χωρίον εἶχε, καὶ μεθ’ ἡμέραν ὑπερεφαίνετο τῶν πολεμίων ἱδρύων τὸν στρατὸν ἐν τόποις, οἳ μάχεσθαι βουλομένῳ προσαγωγὴν ἐδίδοσαν καὶ τὸ μὴ βιασθῆναι παρεῖχον ἡσυχάζοντι.", "st": "Luc. 15.3"}, {"sp": "N", "t": "γνώμην μὲν οὖν οὐδέτερος εἶχεν ἔν γε τῷ παρόντι διακινδυνεύειν ἔλαφον δὲ λέγεται τῶν βασιλικῶν διωκόντων ὑποτεμνομένους ἀπαντῆσαι τοὺς Ῥωμαίους, ἐκ δὲ τούτου συμπεσόντας ἀγωνίζεσθαι πλειόνων ἑκατέροις ἀεὶ προσγινομένων. τέλος δ’ ἐνίκων οἱ βασιλικοί· καὶ τὴν φυγὴν ἐκ τοῦ χάρακος οἱ Ῥωμαῖοι καθορῶντες ἤσχαλλον καὶ συνέτρεχον πρὸς τὸν Λούκουλλον, ἄγειν σφᾶς δεόμενοι καὶ σύνθημα πρὸς τὴν μάχην αἰτοῦντες. ὁ δὲ βουλόμενος αὐτοὺς μαθεῖν, ἡλίκον ἐστὶν ἐν ἀγῶνι πολέμου καὶ κινδύνῳ παρουσία καὶ ὄψις ἡγεμόνος ἔμφρονος, ἐκείνους μὲν ἡσυχίαν ἄγειν ἐκέλευσεν, αὐτὸς δὲ κατέβαινεν εἰς τὸ πεδίον καὶ τοῖς πρώτοις ἀπαντήσας τῶν φευγόντων ἵστασθαι προσέταξε καὶ ἀναστρέφειν μετ’ αὐτοῦ. πεισθέντων δὲ τούτων καὶ οἱ λοιποὶ μεταβαλόμενοι καὶ συστάντες ὀλίγῳ πόνῳ τρέπονται τοὺς πολεμίους καὶ καταδιώκουσιν εἰς τὸ στρατόπεδον. ἐπανελθὼν δὲ Λούκουλλος ἀτιμίαν τινὰ τοῖς φεύγουσι νενομισμένην προσέβαλε, κελεύσας ἐν χιτῶσιν ἀζώστοις ὀρύξαι δώδεκα ποδῶν τάφρον, ἐφεστώτων καὶ θεωμένων τῶν ἄλλων στρατιωτῶν.", "st": "Luc. 15.5"}, {"sp": "N", "t": "τὴν δέ τις ἐν τῷ Μιθριδάτου στρατοπέδῳ Δανδαρίων δυνάστης Ὀλθακὸς γένος δ’ εἰσὶν οἱ Δανδάριοι βαρβάρων τῶν περὶ τήν Μαιῶτιν οἰκούντων, ἀνὴρ ὅσα χειρὸς ἔργα καί τόλμης ἐν πολέμῳ διαπρεπὴς ἅπαντα, καί γνώμην ἱκανὸς ἐν τοῖς μεγίστοις, ἔτι δ’ ἐμμελὴς ὁμιλῆσαι καί θεραπευτικός, οὗτος ἔχων ἀεὶ πρός τινα τῶν ὁμοφύλων δυναστῶν ἅμιλλαν ὑπὲρ πρωτείων καὶ ζηλοτυπίαν ὑπέσχετο τῷ Μιθριδάτῃ μέγα ἔργον, ἀποκτενεῖν Λούκουλλον. ἐπαινέσαντος δὲ τοῦ βασιλέως καί τινας αὐτῷ προσβαλόντος ἐπίτηδες ἀτιμίας εἷς προσποίησιν ὀργῆς ἀφιππάσατο πρός Λούκουλλον· ὁ δ’ ἄσμενος ἐδέξατο· λόγος γὰρ ἦν αὐτοῦ πολὺς ἐν τῷ στρατοπέδῳ· καί ταχὺ πειρώμενος ἠσπάζετο τήν τε ἀγχίνοιαν αὐτοῦ καί τὸ λιπαρές, ὥστε τραπέζης καί συνεδρίου ποτὲ ποιεῖσθαι κοινωνόν.", "st": "Luc. 16.1"}, {"sp": "N", "t": "ἐπεὶ δ’ ἐδόκει καιρὸν ἔχειν ὁ Δανδάριος, τὸν μὲν ἵππον ἔξω τοῦ χάρακος ἐκέλευσε προαγαγεῖν τοὺς παῖδας, αὐτὸς δὲ μεσημβρίας οὔσης καί τῶν στρατιωτῶν ἐνδιαζόντων καί ἀναπαυομένων ἐβάδιζεν ἐπὶ τήν στρατηγικὴν σκηνήν, ὡς οὐδενὸς κωλύσοντος εἰσελθεῖν ἄνδρα συνήθη καί λόγους τινὰς ἀξίους σπουδῆς τῷ στρατηγῷ κομίζειν φάσκοντα. κἂν εἰσῆλθεν ἀδεῶς, εἰ μὴ ὁ πολλοὺς ἀνῃρηκὼς στρατηγοὺς ὕπνος Λούκουλλον ἔσωσεν. ἐτύγχανε γὰρ καθεύδων καί Μενέδημος, εἷς τῶν κατευναστῶν, παρὰ ταῖς θύραις ἑστὼς οὐκ ἔφη κατὰ καιρὸν ἥκειν τὸν Ὀλθακόν, ἄρτι Λουκούλλου πρός ἀνάπαυσιν ἐκ μακρᾶς ἀγρυπνίας καί πόνων τοσούτων δεδωκότος ἑαυτόν. ἐπεὶ δ’ οὐκ ἀπῄει κελεύοντος, ἀλλ’ ἔφη καί κωλύοντος εἰσελεύσεσθαι περὶ πράγματος ἀναγκαίου καί μεγάλου διαλεχθῆναι βουλόμενος, ἤδη πρὸς ὀργὴν ὁ Μενέδημος εἰπὼν μηδὲν ἀναγκαιότερον τοῦ σῴζεσθαι Λούκουλλον ἀπεώσατο τὸν ἄνθρωπον ἀμφοτέραις ταῖς χερσίν. ὁ δὲ δείσας ὑπεξῆλθε τοῦ χάρακος, καί λαβὼν τὸν ἵππον ἀπήλασεν εἷς τὸ Μιθριδάτου στρατόπεδον ἄπρακτος, οὕτως ἄρα καί τοῖς πράγμασιν ὁ καιρὸς ὥσπερ τοῖς φαρμάκοις καί τήν σῴζουσαν καί τήν ἀναιροῦσαν ῥοπὴν προστίθησιν.", "st": "Luc. 16.3"}, {"sp": "N", "t": "ἐκ τούτου Σωρνάτιος μὲν ἐπὶ σίτου κομιδὴν ἐπέμφθη μετὰ δέκα σπειρῶν καὶ καταδιωχθεὶς ὑπὸ Μενάνδρου, τῶν Μιθριδάτου στρατηγῶν ἑνός, ἀντέστη καὶ συμβαλὼν φόνον ἐποίησε πολὺν καὶ τροπὴν τῶν πολεμίων, αὖθις δὲ πεμφθέντος Ἀδριανοῦ μετὰ δυνάμεως, ὅπως ἐκ περιουσίας ἔχωσιν οἱ στρατιῶται σῖτον, οὐ περιεῖδε Μιθριδάτης, ἀλλ’ ἀπέστειλε Μενέμαχον καὶ Μύρωνα πολλῶν μὲν ἱππέων, πολλῶν δὲ πεζῶν ἡγουμένους. οὗτοι πάντες, ὡς λέγεται, πλὴν δυεῖν κατεκόπησαν ὑπὸ τῶν Ῥωμαίων. καὶ Μιθριδάτης μὲν ἔκρυπτε τὴν συμφοράν ὡς οὐ τοσαύτην οὖσαν, ἀλλὰ μικράν, προσκεκρουκότων ἀπειρίᾳ τῶν στρατηγῶν, Ἀδριανὸς δὲ λαμπρὸς παρημείβετο τὸ στρατόπεδον πολλὰς κατάγων ἁμάξας σίτου καὶ λαφύρων γεμούσας, ὥστε δυσθυμίαν μὲν αὐτῷ, ταραχὴν δὲ καὶ φόβον ἀμήχανον ἐμπεσεῖν τοῖς στρατιώταις. ἐδέδοκτο μὲν οὖν μηκέτι μένειν ἐπεὶ δὲ προεξέπεμπον οἱ βασιλικοὶ τὰ σφέτερα χρήματα καθ’ ἡσυχίαν, τοὺς δ’ ἄλλους ἐκώλυον, ἤδη καὶ πρὸς ὀργὴν ἐπὶ τὰς ἐξόδους ὠθούμενοι καὶ βιαζόμενοι τὰ μὲν χρήματα ἥρπαζον, αὐτοὺς δὲ ἀπέσφαττον. ὅπου καὶ Δορύλαος ὁ στρατηγός οὐδὲν ἕτερον ἔχων ἢ τὴν πορφύραν περὶ αὑτόν ἀπώλετο διὰ ταύτην, Ἑρμαῖος δὲ ὁ θύτης κατεπατήθη περὶ τὰς πύλας.", "st": "Luc. 17.1"}, {"sp": "N", "t": "αὐτὸς δ’ ὁ Μιθριδάτης, οὔτε ὀπαδοῦ τινος οὔτε ἱπποκόμου παραμείναντος αὐτῷ, συνεξέπεσεν ἀπὸ τοῦ στρατοπέδου τοῖς πολλοῖς ἀναμεμιγμένος, οὐδ’ ἵππου τῶν βασιλικῶν εὐπορήσας, ἀλλ’ ὀψέ που κατιδὼν αὐτόν ἐν τῷ ῥεύματι τῆς τροπῆς ἐκείνης διαφερόμενον Πτολεμαῖος ὁ εὐνοῦχος ἵππον ἔχων αὐτὸς ἀπεπήδησε καὶ παρέσχεν. ἤδη γὰρ αὑτόν οἱ Ῥωμαῖοι κατεῖχον ἐπικείμενοι· καὶ τάχει μὲν οὐκ ἀπελίποντο τοῦ λαβεῖν αὐτόν, ἀλλ’ ἦλθον ἔγγιστα τούτου, φιλοπλουτία δὲ καὶ μικρολογία στρατιωτικὴ τὸ πολλοῖς ἀγῶσι καὶ μεγάλοις κινδύνοις διωκόμενον ἐκ μακροῦ θήραμα Ῥωμαίους ἀφείλετο καὶ Λούκουλλον ἀπεστέρησε νικῶντα τῶν ἐπάθλων. ἦν μὲν γὰρ ἐν ἐφικτῷ τῆς διώξεως ὁ ὑπεκφέρων τὸν ἄνδρα ἵππος, ἡμιόνου δὲ τῶν τὸ χρυσίον κομιζόντων μεταξὺ τοῦ βασιλέως εἴτ’ ἀπὸ ταὐτομάτου παρεισπεσόντος, εἴτε τοῦ βασιλέως ἐπίτηδες ἐμβαλόντος αὑτόν εἰς τοὺς διώκοντας, ἁρπάζοντες καὶ συλλέγοντες τὸ χρυσίον καὶ διαμαχόμενοι πρὸς ἀλλήλους καθυστέρησαν. καὶ οὐ τοῦτο μόνον αὐτῶν ἀπέλαυσε τῆς πλεονεξίας Λούκουλλος, ἀλλὰ καὶ τὸν ἐπὶ τῶν ἀπορρήτων τοῦ βασιλέως ὄντα Καλλίστρατον ὁ μὲν ἄγειν ἐκέλευσεν, οἱ δ’ ἄγοντες αἰσθόμενοι πεντακοσίους χρυσοῦς ὑπεζωσμένον ἀπέκτειναν. οὐ μὴν ἀλλὰ τούτοις μὲν ἐπέτρεψε τὸν χάρακα πορθῆσαι.", "st": "Luc. 17.4"}, {"sp": "N", "t": "τὰ δὲ Κάβειρα λαβὼν καὶ τῶν ἄλλων φρουρίων τὰ πλεῖστα θησαυρούς τε μεγάλους εὗρε καὶ δεσμωτήρια, πολλῶν μὲν Ἑλλήνων, πολλῶν δὲ συγγενῶν τοῦ βασιλέως καθειργμένων, οἷς πάλαι τεθνάναι δοκοῦσιν οὐ σωτηρίαν, ἀλλ’ ἀναβίωσιν καὶ δευτέραν τινὰ γέννησιν ἡ Λουκούλλου χάρις παρέσχεν. ἑάλω δὲ καὶ ἀδελφὴ τοῦ Μιθριδάτου Νύσσα σωτήριον ἅλωσιν αἱ δ’ ἀπωτάτω τοῦ κινδύνου καὶ καθ’ ἡσυχίαν ἀποκεῖσθαι δοκοῦσαι περὶ Φαρνάκειαν ἀδελφαί καὶ γυναῖκες οἰκτρῶς ἀπώλοντο, Μιθριδάτου πέμψαντος ἐπ’ αὐτὰς ἐκ τῆς φυγῆς Βακχίδην εὐνοῦχον. ἦσαν δὲ μετὰ πολλῶν ἀδελφαί τε δύο τοῦ βασιλέως, Ῥωξάνη καὶ Στάτειρα, περὶ τεσσαράκοντα ἔτη παρθενευόμεναι, καὶ γαμεταὶ δύο, γένος Ἰωνίδες, Βερενίκη μὲν ἐκ Χίου, Μονίμη δὲ Μιλησία. ταύτης ὁ πλεῖστος ἦν λόγος ἐν τοῖς Ἕλλησιν, ὅτι τοῦ βασιλέως πειρῶντος αὐτὴν καὶ μυρίους πεντακισχιλίους χρυσοῦς προσπέμψαντος ἀντέσχε, μέχρι οὗ γάμων ἐγένοντο συνθῆκαι καὶ διάδημα πέμψας αὐτῇ βασίλισσαν ἀνηγόρευσεν. αὕτη καὶ παρὰ τὸν ἄλλον χρόνον ἀνιαρῶς εἶχε καὶ ἀπεθρήνει τὴν τοῦ σώματος εὐμορφίαν, ὡς δεσπότην μὲν ἀντ’ ἀνδρὸς αὐτῇ, φρουρὰν δὲ βαρβάρων ἀντὶ γάμου καὶ οἴκου προξενήσασαν, πόρρω δέ που τῆς Ἑλλάδος ἀπῳκισμένη τοῖς ἐλπισθεῖσιν ἀγαθοῖς ὄναρ σύνεστι, τῶν δ’ ἀληθινῶν ἐκείνων ἀπεστέρηται.", "st": "Luc. 18.1"}, {"sp": "N", "t": "καὶ δὴ τοῦ Βακχίδου παραγενομένου καὶ προστάξαντος αὐταῖς ἀποθνῄσκειν, ὡς ἑκάστῃ δοκοίη ῥᾷστον εἶναι καὶ ἀλυπότατον, περισπάσασα τῆς κεφαλῆς τὸ διάδημα τῷ τραχήλῳ περιῆψε καὶ ἀνήρτησεν ἑαυτήν. ταχὺ δ’ ἀπορραγέντος ὦ κατηραμένον, ἔφη, ῥάκος, οὐδὲ πρὸς τοῦτό μοι χρήσιμον ἔσῃ; κἀκεῖνο μὲν ἀπέρριψε προσπτύσασα, τῷ δὲ Βακχίδῃ τὴν σφαγὴν παρέσχεν. ἡ δὲ Βερενίκη κύλικα φαρμάκου λαβοῦσα, τῆς μητρὸς αὐτῇ παρούσης καὶ δεομένης, μετέδωκε. καὶ συνεξέπιον μὲν ἀμφότεραι, ἤρκεσε δὲ ἡ τοῦ φαρμάκου δύναμις εἰς τὸ ἀσθενέστερον σῶμα, τὴν δὲ Βερενίκην οὐχ ὅσον ἔδει πιοῦσαν οὐκ ἀπήλλαξεν, ἀλλὰ δυσθανατοῦσα τοῦ Βακχίδου σπεύδοντος ἀπεπνίγη. λέγεται δὲ καὶ τῶν ἀγάμων ἀδελφῶν ἐκείνων τὴν μὲν ἐπαρωμένην πολλὰ καὶ λοιδοροῦσαν ἐκπιεῖν τὸ φάρμακον, τὴν δὲ Στάτειραν οὔτε δύσφημόν τι φθεγξαμένην οὔτ’ ἀγεννές, ἀλλ’ ἐπαινοῦσαν τὸν ἀδελφόν, ὅτι περὶ τοῦ σώματος κινδυνεύων οὐκ ἠμέλησεν αὐτῶν, ἀλλὰ προὐνόησεν ἐλευθέρας καὶ ἀνυβρίστους ἀποθανεῖν. ταῦτα μὲν οὖν φύσει χρηστὸν ὄντα καὶ φιλάνθρωπον ἠνία τὸν Λούκουλλον.", "st": "Luc. 18.4"}, {"sp": "N", "t": "ἐλάσας δ’ ἄχρι Ταλαύρων, ἔνθεν ἡμέρᾳ τετάρτῃ πρότερον ἐφθάκει Μιθριδάτης εἰς Ἀρμενίαν πρὸς Τιγράνην πεφευγώς, ἀποτρέπεται, καταστρεψάμενος δὲ Χαλδαίους καὶ Τιβαρηνοὺς καὶ τὴν μικρὰν Ἀρμενίαν παραλαβών καὶ φρούρια καὶ πόλεις παραστησάμενος, Ἄππιον μὲν ἔπεμψε πρὸς Τιγράνην ἐξαιτῶν Μιθριδάτην, αὐτὸς δ’ ἧκε πρὸς Ἀμισὸν ἔτι πολιορκουμένην. αἴτιος δ’ ἦν Καλλίμαχος ὁ στρατηγός ἐμπειρίᾳ μηχανικῆς παρασκευῆς καὶ δεινότητι πανουργίας, ὅσην πολιορκία δέχεται, πλεῖστα λυπήσας Ῥωμαίους· ὧν ὕστερον ἔδωκε δίκην. τότε δ’ ὑπὸ Λουκούλλου καταστρατηγηθείς, ὑφ’ ἣν ἔθος εἶχεν ὥραν τῆς ἡμέρας ἀπάγειν καὶ ἀναπαύειν τούς στρατιώτας, ἐν ἐκείνῃ προσβαλόντος αἰφνιδίως καὶ κατασχόντος οὐ πολὺ μέρος τοῦ τείχους, αὐτὸς ἐκλιπὼν τὴν πόλιν ὑφῆψεν, εἴτε φθονῶν ὠφεληθῆναι Ῥωμαίοις, εἴτε ῥᾳστώνην φυγῆς ἑαυτῷ μηχανώμενος. οὐδεὶς γὰρ ἐφρόντιζε τῶν ἐκπλεόντων, ἀλλὰ ὡς ἡ φλὸξ ἀναδραμοῦσα πολλὴ τὰ τείχη περιέσχεν, οἱ μὲν στρατιῶται παρεσκευάζοντο πρὸς ἁρπαγήν, ὁ δὲ Λούκουλλος οἰκτείρων ἀπολλυμένην τὴν πόλιν ἔξωθεν ἐβοήθει πρὸς τὸ πῦρ καὶ σβεννύναι παρεκάλει, μηδενὸς αὐτῷ προσέχοντος, ἀλλ’ ἐξαιτουμένων τὰ χρήματα καὶ μετὰ βοῆς ὅπλα κρουόντων, ἕως ἐκβιασθεὶς ἐπέτρεψεν, ὡς αὐτήν γε τὴν πόλιν ἐξαιρησόμενος τοῦ πυρός. οἱ δὲ τοὐναντίον ἔπραξαν, πάντα γὰρ ἐξερευνῶντες ὑπὸ λαμπάδων καὶ πανταχοῦ φῶς ἐπιφέροντες αὐτοὶ τὰ πλεῖστα τῶν οἰκημάτων καθεῖλον, ὥστε τὸν Λούκουλλον εἰσελθόντα μεθ’ ἡμέραν καὶ δακρύσαντα πρὸς τούς φίλους εἰπεῖν, ὡς πολλάκις ἤδη Σύλλαν μακαρίσας μάλιστα τῇ σήμερον ἡμέρᾳ τὴν τἀνδρὸς εὐτυχίαν θαυμάσειεν, ὅτι σῶσαι βουληθεὶς ἐδυνήθη τὰς Ἀθήνας. ἐμὲ δ’, ἔφη, τούτου ζηλωτὴν γενόμενον εἰς τὴν Μομμίου δόξαν ὁ δαίμων περιέστησεν.", "st": "Luc. 19.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐκ τῶν παρόντων ἀναλαμβάνειν ἐπειρᾶτο τὴν πόλιν. καὶ τὸ μὲν πῦρ ὄμβροι κατέσβεσαν ἔκ τινος θείας τύχης περὶ τὴν ἅλωσιν αὐτήν συμπεσόντες, τὰ δὲ πλεῖστα τῶν ἀπολωλότων αὐτὸς ἔτι παρὼν ἀνῳκοδόμησε, καὶ τούς φεύγοντας Ἀμισηνῶν ἐδέξατο, καὶ τῶν ἄλλων Ἑλλήνων κατῴκισε τούς βουλομένους, εἴκοσι καὶ ἑκατὸν σταδίων χώραν προσορίσας. ἦν δ’ ἡ πόλις Ἀθηναίων ἄποικος, ἐν ἐκείνοις ἄρα τοῖς καιροῖς, ἐν οἷς ἤκμαζεν ἡ δύναμις αὐτῶν καὶ κατεῖχε τὴν θάλασσαν, οἰκισθεῖσα. καὶ διὰ τοῦτο πολλοὶ τῶν τὴν Ἀριστίωνος τυραννίδα βουλομένων φεύγειν εἰσπλεύσαντες αὐτοῦ κατῴκουν καὶ μετεῖχον τῆς πολιτείας, οἷς συνέβη τὰ οἰκεῖα κακὰ φεύγουσιν ἀπολαῦσαι τῶν ἀλλοτρίων, ἀλλὰ τούς γε σωθέντας αὐτῶν ὁ Λούκουλλος ἀμφιέσας καλῶς καὶ διακοσίας ἑκάστῳ δραχμὰς ἐπιδοὺς ἀπέστειλε. τότε καὶ Τυραννίων ὁ γραμματικὸς ἑάλω Μουρήνας δ’ αὐτὸν ἐξῃτήσατο καὶ λαβὼν ἀπηλευθέρωσεν, ἀνελευθέρως τῇ δωρεᾷ χρησάμενος. οὐ γὰρ ἠξίου Λούκουλλος ἄνδρα διὰ παιδείαν ἐσπουδασμένον δοῦλον γενέσθαι πρότερον, εἶτ’ ἀπελεύθερον. ἀφαίρεσις γὰρ ἦν τῆς ὑπαρχούσης ἡ τῆς δοκούσης ἐλευθερίας δόσις. ἀλλὰ Μουρήνας μὲν οὐκ ἐνταῦθα μόνον ὤφθη πολὺ τῆς τοῦ στρατηγοῦ καλοκαγαθίας ἀποδέων.", "st": "Luc. 19.6"}, {"sp": "N", "t": "Λούκουλλος δὲ τρέπεται πρὸς τὰς ἐν Ἀσίᾳ πόλεις, ὅπως, τῶν πολεμικῶν ἔργων σχολάζοντος αὐτοῦ, καὶ δίκης τινὸς μετάσχῃ καὶ θεσμῶν, ὧν ἐπὶ πολὺν χρόνον ἐνδεῆ τὴν ἐπαρχίαν οὖσαν ἄρρητοι καὶ ἄπιστοι δυστυχίαι κατεῖχον, ὑπὸ τῶν τελωνῶν καὶ τῶν δανειστῶν πορθουμένην καὶ ἀνδραποδιζομένην, πιπράσκειν ἰδίᾳ μὲν υἱοὺς εὐπρεπεῖς θυγατέρας τε παρθένους, δημοσίᾳ δ’ ἀναθήματα, γραφάς, ἱεροὺς ἀνδριάντας ἀναγκαζομένων. αὐτοῖς δὲ τέλος μὲν ἦν προσθέτοις γενομένοις δουλεύειν, τὰ δὲ πρὸ τούτου χαλεπώτερα, σχοινισμοὶ καὶ κιγκλίδες καὶ ἵπποι καὶ στάσεις ὕπαιθροι, καύματος μὲν ἐν ἡλίῳ, ψύχους δ’ εἰς πηλὸν ἐμβιβαζομένων ἢ πάγον, ὥστε τὴν δουλείαν σεισάχθειαν δοκεῖν εἶναι καὶ εἰρήνην. τοιαῦτα μὲν κακὰ Λούκουλλος εὑρὼν ἐν ταῖς πόλεσιν ὀλίγῳ χρόνῳ πάντων ἀπήλλαξε τοὺς ἀδικουμένους.", "st": "Luc. 20.1"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ ἑκατοστὴν ἐκέλευσε καὶ μὴ πλέον εἰς τοὺς τόκους λογίζεσθαι· δεύτερον δὲ τοὺς μακροτέρους τοῦ ἀρχαίου τόκους ἀπέκοψε· τὸ δὲ τρίτον καὶ μέγιστον, ἔταξε τῶν τοῦ χρεωφειλέτου προσόδων τὴν τετάρτην μερίδα καρποῦσθαι τὸν δανειστήν ὁ δὲ τόκον κεφαλαίῳ συνάψας ἐστέρητο τοῦ παντός· ὥστ’ ἐν ἐλάττονι χρόνῳ τετραετίας διαλυθῆναι τὰ χρέα πάντα καὶ τὰς κτήσεις ἐλευθέρας ἀποδοθῆναι τοῖς δεσπόταις. ἦν δὲ τοῦτο κοινὸν δάνειον ἐκ τῶν δισμυρίων ταλάντων, οἷς τὴν Ἀσίαν ἐζημίωσεν ὁ Σύλλας καὶ διπλοῦν ἀπεδόθη τοῖς δανείσασιν, ὑπ’ ἐκείνων ἀνηγμένον ἤδη τοῖς τόκοις εἰς δώδεκα μυριάδας ταλάντων. ἐκεῖνοι μὲν οὖν ὡς δεινὰ πεπονθότες ἐν Ῥώμῃ τοῦ Λουκούλλου κατεβόων, καὶ χρήμασιν ἀνίστασαν ἐπ’ αὐτὸν ἐνίους τῶν δημαγωγῶν, μέγα δυνάμενοι καὶ πολλοὺς ὑπόχρεως πεποιημένοι τῶν πολιτευομένων, ὁ δὲ Λούκουλλος οὐ μόνον ὑπὸ τῶν εὖ πεπονθότων ἠγαπᾶτο δήμων, ἀλλὰ καὶ ταῖς ἄλλαις ἐπαρχίαις ποθεινὸς ἦν, εὐδαιμονιζούσαις τοὺς ἡγεμόνος τοιούτου τυχόντας.", "st": "Luc. 20.4"}, {"sp": "N", "t": "Ἄππιος δὲ Κλώδιος, ὁ πεμφθεὶς πρὸς Τιγράνην ἦν δὲ ὁ Κλώδιος ἀδελφὸς τῆς τότε Λουκούλλῳ συνοικούσης πρῶτον μὲν ὑπὸ τῶν βασιλικῶν ὁδηγῶν κύκλον τινὰ καὶ περιβολὴν ἔχουσαν οὐκ ἀναγκαίαν καὶ πολυήμερον ὁδὸν διὰ τῆς ἄνω χώρας ἀγόμενος, μηνύσαντος αὐτῷ τὴν εὐθεῖαν ὁδὸν ἀπελευθέρου Σύρου τὸ γένος, ἐκτρέπεται τῆς μακρᾶς ἐκείνης καὶ σοφιστικῆς, ἐρρῶσθαι φράσας πολλὰ τοῖς βαρβάροις ἀγωγοῖς, καὶ δι’ ἡμερῶν ὀλίγων τὸν Εὐφράτην περάσας εἷς Ἀντιόχειαν ἧκε τὴν ἐπὶ Δάφνης. ἔπειτα Τιγράνην αὐτοῦ κελευσθεὶς περιμένειν ἀπῆν γὰρ ἐνίας ἔτι τῶν ἐν Φοινίκῃ πόλεων καταστρεφόμενος, πολλοὺς μὲν ᾠκειώσατο τῶν ὑπούλως ἀκροωμένων τοῦ Ἀρμενίου δυναστῶν, ὧν εἷς ἦν καὶ Ζαρβιηνὸς ὁ τῆς Γορδυηνῆς βασιλεύς, πολλαῖς δὲ κρύφα τῶν δεδουλωμένων πόλεων διαπεμπομέναις πρὸς αὑτὸν ὑπέσχετο τὴν Λουκούλλου βοήθειαν, ἐν τῷ παρόντι κελεύσας ἡσυχάζειν.", "st": "Luc. 21.1"}, {"sp": "N", "t": "ἦν γὰρ οὐκ ἀνασχετὸς ἡ τῶν Ἀρμενίων ἀρχὴ τοῖς Ἕλλησιν, ἀλλὰ χαλεπή καὶ μάλιστα τοῦ βασιλέως αὐτοῦ τὸ φρόνημα τραγικὸν καὶ ὑπέρογκον ἐν ταῖς μεγάλαις εὐτυχίαις ἐγεγόνει, πάντων, ὅσα ζηλοῦσιν οἱ πολλοὶ καὶ θαυμάζουσιν, οὐ μόνον ὄντων περὶ αὐτόν, ἀλλὰ καὶ δι’ αὑτὸν γεγονέναι δοκούντων. ἀρξάμενος γὰρ ἀπὸ μικρᾶς καὶ καταφρονουμένης ἐλπίδος ἔθνη πολλὰ κατεστρέψατο, καὶ τὴν Πάρθων, ὡς ἄλλος οὐδεὶς, δύναμιν ἐταπείνωσεν, Ἑλλήνων δὲ τὴν Μεσοποταμίαν ἐνέπλησε, πολλοὺς μὲν ἐκ Κιλικίας, πολλοὺς δ’ ἐκ Καππαδοκίας ἀνασπάστους κατοικίζων. ἐκίνησε δ’ ἐξ ἠθῶν καὶ Ἄραβας τοὺς Σκηνίτας μεταγαγὼν καὶ πλησίον ἱδρύσας, ὅπως χρῷτο δι’ ἐκείνων ταῖς ἐμπορίαις. βασιλεῖς δὲ πολλοὶ μὲν ἦσαν οἱ θεραπεύοντες αὐτόν, τέσσαρες δέ, οὓς ἀεὶ περὶ αὑτὸν εἶχεν ὥσπερ ὀπαδοὺς ἢ δορυφόρους, ἱππότῃ μὲν ἐλαύνοντι πεζοὺς παραθέοντας ἐν χιτωνίσκοις, καθημένῳ δὲ καὶ χρηματίζοντι περιεστῶτας ἐπηλλαγμέναις δι’ ἀλλήλων ταῖς χερσίν, ὅπερ ἐδόκει μάλιστα τῶν σχημάτων ἐξομολόγησις εἶναι δουλείας, οἷον ἀποδομένων τὴν ἐλευθερίαν καὶ τὸ σῶμα τῷ κυρίῳ παρεχόντων παθεῖν ἑτοιμότερον ἢ ποιῆσαι.", "st": "Luc. 21.3"}, {"sp": "N", "t": "ταύτην μέντοι τὴν τραγῳδίαν οὐχ ὑποτρέσας οὐδ’ ἐκπλαγεὶς ὁ Ἄππιος, ὡς ἔτυχε λόγου πρῶτον, ἄντικρυς ἥκειν ἔφη Μιθριδάτην ἀπάξων ὀφειλόμενον τοῖς Λουκούλλου θριάμβοις ἢ καταγγελῶν Τιγράνῃ πόλεμον, ὥστε τὸν Τιγράνην, καίπερ ἐν διαχύσει τοῦ προσώπου καὶ μειδιάματι πεπλασμένῳ πειρώμενον ἀκούειν τῶν λόγων, μὴ λαθεῖν τοὺς παρόντας ἠλλοιωμένον τῇ παρρησίᾳ τοῦ νεανίσκου, φωνῆς σχεδὸν ἐλευθέρας ἀκούοντα διὰ πέντε καὶ εἴκοσιν ἐτῶν τοσαῦτα γὰρ ἐβασίλευσε, μᾶλλον δὲ ὕβρισεν. ἀπεκρίνατο μὲν οὖν τῷ Ἀππίῳ μὴ προήσεσθαι Μιθριδάτην, καὶ Ῥωμαίους πολέμου ἄρχοντας ἀμυνεῖσθαι. Λουκούλλῳ δ’ ὀργιζόμενος, ὅτι βασιλέα μόνον αὐτόν, οὐ βασιλέων ἐν τῇ ἐπιστολῇ προσηγόρευσεν, οὐδ’ αὐτὸς ἀντιγράφων αὐτοκράτορα προσεῖπεν. ἔπεμψε δὲ δῶρα τῷ Ἀππίῳ λαμπρά, καὶ μὴ λαβόντος ἄλλα πλείω προσέθηκεν. ἐκ τούτων ὁ Ἄππιος οὐκ ἐθέλων δοκεῖν ἔχθρᾳ τινὶ διωθεῖσθαι φιάλην δεξάμενος μίαν ἀπέπεμψε τὰ λοιπά, καὶ διὰ ταχέων ἀπήλαυνε πρὸς τὸν αὐτοκράτορα.", "st": "Luc. 21.6"}, {"sp": "N", "t": "Τιγράνης δὲ Μιθριδάτην πρότερον μὲν οὐδὲ ἰδεῖν ἠξίωσεν οὐδὲ προσειπεῖν οἰκεῖον ἄνδρα βασιλείας ἐκπεπτωκότα τηλικαύτης, ἀλλ’ ἀτίμως καὶ ὑπερηφάνως ἀπωτάτω περιεῖδεν αὐτὸν τρόπον τινὰ φρουρούμενον ἐν χωρίοις ἑλώδεσι καὶ νοσεροῖς· τότε δὲ σὺν τιμῇ καὶ φιλοφροσύνῃ μετεπέμψατο αὐτὸν εἰς τὰ βασίλεια. καὶ δὴ λόγων γενομένων ἀπορρήτων τὰς πρὸς ἀλλήλους ἐθεράπευον ὑποψίας ἐπὶ κακῷ τῶν φίλων, εἰς ἐκείνους τὰς αἰτίας τρέποντες. ὧν ἦν καὶ Μητρόδωρος ὁ Σκήψιος, ἀνὴρ εἰπεῖν οὐκ ἀηδὴς καὶ πολυμαθής, ἀκμῇ δὲ φιλίας τοσαύτῃ χρησάμενος, ὥστε πατὴρ προσαγορεύεσθαι τοῦ βασιλέως. τοῦτον, ὡς ἔοικεν, ὁ Τιγράνης πεμφθέντα πρεσβευτὴν ὑπὸ τοῦ Μιθριδάτου πρὸς αὐτὸν δεομένου βοηθεῖν ἐπὶ Ῥωμαίους ἤρετο· σὺ δ’ αὐτὸς, ὦ Μητρόδωρε, τί μοι περὶ τούτων παραινεῖς; κἀκεῖνος εἴτε πρὸς τὸ Τιγράνου συμφέρον εἴτε Μιθριδάτην σῴζεσθαι μὴ βουλόμενος, ὡς μὲν πρεσβευτὴς ἔφη κελεύειν, ὡς δὲ σύμβουλος ἀπαγορεύειν. ταῦτ’ ἐξήνεγκεν ὁ Τιγράνης τῷ Μιθριδάτῃ καὶ κατεῖπεν ὡς οὐδὲν ἐργασομένῳ τὸν Μητρόδωρον ἀνήκεστον. ὁ δ’ εὐθὺς ἀνῄρητο· καὶ μετάνοια τὸν Τιγράνην εἶχεν, οὐ παντελῶς ὄντα τῷ Μητροδώρῳ τῆς συμφορᾶς αἴτιον, ἀλλὰ ῥοπήν τινα τῷ πρὸς αὐτὸν ἔχθει τοῦ Μιθριδάτου προσθέντα. πάλαι γὰρ ὑπούλως εἶχε πρὸς τὸν ἄνδρα, καὶ τοῦτ’ ἐφωράθη τῶν ἀπορρήτων αὐτοῦ γραμμάτων ἁλόντων, ἐν οἷς ἦν καὶ Μητρόδωρον ἀπολέσθαι διατεταγμένον. ἔθαψεν οὖν ὁ Τιγράνης λαμπρῶς τὸ σῶμα, μηδεμιᾶς πολυτελείας φεισάμενος εἰς νεκρὸν ὃν ζῶντα προὔδωκεν.", "st": "Luc. 22.1"}, {"sp": "N", "t": "ἐτελεύτησε δὲ παρὰ τῷ Τιγράνῃ καὶ Ἀμφικράτης ὁ ῥήτωρ, εἰ δεῖ καὶ τούτου μνήμην τινὰ γενέσθαι διὰ τὰς Ἀθήνας, λέγεται γὰρ φυγεῖν μὲν αὐτὸν εἰς Σελεύκειαν τὴν ἐπὶ Τίγριδι, δεομένων δ’ αὐτόθι σοφιστεύειν ὑπεριδεῖν καταλαζονευσάμενον, ὡς οὐδὲ λεκάνη δελφῖνα χωροίη, μεταστάντα δὲ πρὸς Κλεοπάτραν τὴν Μιθριδάτου θυγατέρα, Τιγράνῃ δὲ συνοικοῦσαν ἐν διαβολῇ γενέσθαι ταχύ, καὶ τῆς πρὸς τοὺς Ἕλληνας ἐπιμιξίας εἰργόμενον ἀποκαρτερῆσαι· ταφῆναι δὲ καὶ τοῦτον ἐντίμως ὑπὸ τῆς Κλεοπάτρας καὶ κεῖσθαι περὶ Σαφάν, ἐκεῖ τι χωρίον οὕτω καλούμενον.", "st": "Luc. 22.5"}, {"sp": "N", "t": "Λούκουλλος δὲ τὴν Ἀσίαν πολλῆς μὲν εὐνομίας, πολλῆς δ’ εἰρήνης ἐμπεπληκώς οὐδὲ τῶν πρὸς ἡδονὴν καὶ χάριν ἠμέλησεν, ἀλλὰ πομπαῖς καὶ πανηγύρεσιν ἐπινικίοις καὶ ἀγῶσιν ἀθλητῶν καὶ μονομάχων ἐν Ἐφέσῳ καθήμενος ἐδημαγώγει τὰς πόλεις, αἱ δ’ ἀμειβόμεναι Λουκούλλειά τε ἦγον ἐπὶ τιμῇ τοῦ ἀνδρός, καὶ τῆς τιμῆς ἡδίονα τὴν ἀληθινὴν εὔνοιαν αὐτῷ παρεῖχον. ἐπεὶ δ’ Ἄππιός τε ἧκε καὶ πολεμητέον πρὸς Τιγράνην ἐφαίνετο, παρῆλθεν αὖθις εἰς Πόντον, καὶ τοὺς στρατιώτας ἀναλαβὼν ἐπολιόρκει Σινώπην, μᾶλλον δὲ τοὺς κατέχοντας αὐτὴν βασιλικοὺς Κίλικας, οἳ πολλοὺς μὲν ἀνελόντες τῶν Σινωπέων, τὴν δὲ πόλιν ἐμπρήσαντες διὰ νυκτὸς ἔφυγον. αἰσθόμενος δ’ ὁ Λούκουλλος καὶ παρελθὼν εἰς τὴν πόλιν ὀκτακισχιλίους αὐτῶν τοὺς ἐγκαταλειφθέντας ἀπέκτεινε, τοῖς δ’ ἄλλοις ἀπέδωκε τὰ οἰκεῖα καὶ τῆς πόλεως ἐπεμελήθη μάλιστα διὰ τὴν τοιαύτην ὄψιν. ἐδόκει τινὰ κατὰ τοὺς ὕπνους εἰπεῖν παραστάντα πρόελθε, Λούκουλλε, μικρόν ἥκει γὰρ Αὐτόλυκος ἐντυχεῖν σοι βουλόμενος. ἐξαναστὰς δὲ τὴν μὲν ὄψιν οὐκ εἶχε συμβαλεῖν εἰς ὅ τι φέροι, τὴν δὲ πόλιν εἷλε κατ’ ἐκείνην τὴν ἡμέραν, καὶ τοὺς ἐκπλέοντας τῶν Κιλίκων διώκων ὁρᾷ παρὰ τὸν αἰγιαλὸν ἀνδριάντα κείμενον, ὃν ἐκκομίζοντες οἱ Κίλικες οὐκ ἔφθησαν ἐμβαλέσθαι τὸ δ’ ἔργον ἦν Σθένιδος τῶν καλῶν, φράζει οὖν τις, ὡς Αὐτολύκου τοῦ κτίσαντος τὴν Σινώπην ὁ ἀνδριὰς εἴη.", "st": "Luc. 23.1"}, {"sp": "N", "t": "λέγεται δ’ ὁ Αὐτόλυκος γενέσθαι τῶν ἐπὶ τὰς Ἀμαζόνας ἐκ Θετταλίας Ἡρακλεῖ συστρατευσάντων, Δηιμάχου παῖς· ἐκεῖθεν δ’ ἀποπλέων ἅμα Δημολέοντι καὶ Φλογίῳ τὴν μὲν ναῦν ἀπολέσαι περιπεσοῦσαν τῆς Χερρονήσου κατὰ τὸ καλούμενον Πηδάλιον, αὐτὸς δὲ σωθεὶς μετὰ τῶν ὅπλων καὶ τῶν ἑταίρων πρὸς τὴν Σινώπην ἀφελέσθαι τοὺς Σύρους τὴν πόλιν· Σύροι γὰρ αὐτὴν κατεῖχον ἀπὸ Σύρου γεγονότες τοῦ Ἀπόλλωνος, ὡς λέγεται, καὶ Σινώπης τῆς Ἀσωπίδος.", "st": "Luc. 23.5"}, {"sp": "N", "t": "ταῦτ’ ἀκούων ὁ Λούκουλλος ἀνεμιμνῄσκετο τῆς Σύλλα παραινέσεως· παρῄνει δὲ διὰ τῶν ὑπομνημάτων ἐκεῖνος μηδὲν οὕτως ἀξιόπιστον ἡγεῖσθαι καὶ βέβαιον, ὡς ὅ τι ἂν ἀποσημανθῇ διὰ τῶν ἐνυπνίων.", "st": "Luc. 23.5b"}, {"sp": "N", "t": "πυνθανόμενος δὲ Μιθριδάτην τε καὶ Τιγράνην εἰς Λυκαονίαν καὶ Κιλικίαν ὅσον οὔπω διαβιβάζειν δύναμιν ὡς προτέρους ἐμβαλοῦντας εἰς τὴν Ἀσίαν, ἐθαύμαζε τὸν Ἀρμένιον, εἰ γνώμην ἔχων ἐπιθέσθαι Ῥωμαίοις, ἀκμάζοντι μὲν οὐκ ἐχρῆτο Μιθριδάτῃ πρὸς τὸν πόλεμον, οὐδ’ ἐρρωμένοις τοῖς ἐκείνου τὰ παρ’ αὑτοῦ συνῆπτεν, ἀπολέσθαι δ’ ἐάσας καὶ συντριβῆναι νῦν ἐπὶ ψυχραῖς ἐλπίσιν ἄρχεται πολέμου τοῖς ἀναστῆναι μὴ δυναμένοις συγκαταβάλλων ἑαυτόν.", "st": "Luc. 23.7"}, {"sp": "N", "t": "ἐπειδὴ δὲ καὶ Μαχάρης ὁ Μιθριδάτου παῖς ἔχων τὸν Βόσπορον ἔπεμψεν αὐτῷ στέφανον ἀπὸ χρυσῶν χιλίων, δεόμενος Ῥωμαίων ἀναγραφῆναι φίλος καὶ σύμμαχος, ἤδη οἰόμενος τὰ τοῦ προτέρου πολέμου πέρας ἔχειν Σωρνάτιον μὲν αὐτοῦ φύλακα τῶν Ποντικῶν ἀπέλιπε μετὰ στρατιωτῶν ἑξακισχιλίων, αὐτὸς δὲ μυρίους μὲν ἄγων καὶ δισχιλίους πεζούς, ἱππεῖς δὲ τρισχιλίων ἐλάττους, ἐπὶ τὸν δεύτερον ἐχώρει πόλεμον, ὁρμῇ τινι δοκῶν παραβόλῳ καὶ σωτήριον οὐκ ἐχούσῃ λογισμὸν ἐμβαλεῖν αὑτὸν εἰς ἔθνη μάχιμα καὶ μυριάδας ἱππέων πολλὰς καὶ ἀχανῆ χώραν, βαθέσι μὲν ποταμοῖς, ἀεὶ δὲ κατανιφομένοις ὄρεσι περιεχομένην, ὥστε τοὺς μὲν στρατιώτας οὐδ’ ἄλλως ὄντας εὐτάκτους ἄκοντας ἕπεσθαι καὶ ζυγομαχοῦντας, ἐν δὲ Ῥώμῃ καταβοᾶν καὶ διαμαρτύρεσθαι τοὺς δημαγωγούς, ὡς πόλεμον ἐκ πολέμου διώκει Λούκουλλος οὐδὲν τῆς πόλεως δεομένης, ἀλλ’ ὑπὲρ τοῦ στρατηγῶν μηδέποτε καταθέσθαι τὰ ὅπλα μηδὲ παύσασθαι χρηματιζόμενος ἀπὸ τῶν κοινῶν κινδύνων. οὗτοι μὲν οὖν ἐξειργάσαντο χρόνῳ τὴν αὑτῶν ὑπόθεσιν Λούκουλλος δὲ συντόνως ὁδεύσας ἐπὶ τὸν Εὐφράτην, καὶ κατιόντα πολὺν καὶ θολερὸν ὑπὸ χειμῶνος εὑρών, ἤσχαλλεν, ὡς διατριβῆς αὐτῷ καὶ πραγματείας ἐσομένης συνάγοντι πορθμεῖα καὶ πηγνυμένῳ σχεδίας, ἀρξάμενον δ’ ἀφ’ ἑσπέρας ὑποχωρεῖν τὸ ῥεῦμα καὶ μειούμενον διὰ τῆς νυκτός ἅμ’ ἡμέρᾳ κοῖλον παρέσχεν ὀφθῆναι τὸν ποταμόν. οἱ δ’ ἐπιχώριοι νησῖδας ἐν τῷ πόρῳ μικρᾶς διαφανείσας θεασάμενοι καὶ τεναγίζοντα τὸν ῥοῦν ἐπ’ αὐταῖς, προσεκύνουν τὸν Λούκουλλον, ὡς ὀλιγάκις τούτου συμβεβηκότος πρότερον, ἐκείνῳ δ’ ἑκουσίως χειροήθη καὶ πρᾷον αὑτὸν ἐνδιδόντος τοῦ ποταμοῦ καὶ παρέχοντος ἀπράγμονα καὶ ταχεῖαν τὴν διάβασιν.", "st": "Luc. 24.1"}, {"sp": "N", "t": "χρησάμενος οὖν τῷ καιρῷ διεβίβαζε τὴν στρατιάν· καὶ γίνεται σημεῖον αὐτῷ χρηστὸν ἅμα τῇ διαβάσει, βόες ἱεραὶ νέμονται Περσίας Ἀρτέμιδος, ἣν μάλιστα θεῶν οἱ πέραν Εὐφράτου βάρβαροι τιμῶσι χρῶνται δὲ ταῖς βουσὶ πρὸς θυσίαν μόνον, ἄλλως δὲ πλάζονται κατὰ τὴν χώραν ἄφετοι, χαράγματα φέρουσαι τῆς θεοῦ λαμπάδα, καὶ λαβεῖν ἐξ αὑτῶν, ὅταν δεηθῶσιν, οὐ πάνυ ῥᾴδιόν ἐστιν οὐδὲ μικρᾶς πραγματείας. τούτων μία, τοῦ στρατοῦ διαβάντος τὸν Εὐφράτην, ἐλθοῦσα πρός τινα πέτραν ἱερὰν τῆς θεοῦ νομιζομένην ἐπ’ αὐτῆς ἔστη, καὶ καταβαλοῦσα τὴν κεφαλὴν, ὥσπερ αἱ δεσμῷ κατατεινόμεναι, θῦσαι τῷ Λουκούλλῳ παρέσχεν αὑτήν, ἔθυσε δὲ καὶ τῷ Εὐφράτῃ ταῦρον διαβατήρια. κἀκείνην μὲν αὐτοῦ τὴν ἡμέραν ηὐλίσατο, τῇ δ’ ὑστεραίᾳ καὶ ταῖς ἐφεξῆς προῆγε διὰ τῆς Σωφηνῆς, οὐδὲν ἀδικῶν τοὺς ἀνθρώπους προσχωροῦντας αὐτῷ καὶ δεχομένους τὴν στρατιὰν ἀσμένους, ἀλλὰ καὶ τῶν στρατιωτῶν φρούριόν τι δοκοῦν ἔχειν χρήματα πολλὰ βουλομένων λαβεῖν ἐκεῖνο, ἔφη, μᾶλλον τὸ φρούριον ἡμῖν ἐκκοπτέον ἐστί δεῖξας τὸν Ταῦρον ἄπωθεν ὄντα, ταῦτα δ’ ἀπόκειται τοῖς νικῶσι. συντείνας δὲ τὴν πορείαν καὶ τὸν Τίγριν διαβάς ἐνέβαλεν εἰς τὴν Ἀρμενίαν.", "st": "Luc. 24.6"}, {"sp": "N", "t": "Τιγράνῃ δ’, ὡς ὁ πρῶτος ἀγγείλας ἥκοντα Λούκουλλον οὐκ ἐχαίρησεν, ἀλλ’ ἀπετέτμητο τὴν κεφαλήν, οὐδεὶς ἄλλος ἔφραζεν, ἀλλ’ ἀγνοῶν καθῆστο περικαιόμενος ἤδη τῷ πολεμίῳ πυρί, λόγους ἀκούων πρὸς χάριν, ὡς μέγαν ὄντα Λούκουλλον στρατηγόν, εἰ πρὸς Ἐφέσῳ Τιγράνην ὑποσταίη καὶ μὴ φεύγων εὐθὺς ἐξ Ἀσίας οἴχοιτο τὰς τοσαύτας μυριάδας ἰδών. οὕτως οὔτε σώματος παντός ἐστι πολὺν ἄκρατον ἐνεγκεῖν οὔτε διανοίας τῆς τυχούσης ἐν εὐτυχήμασι μεγάλοις μὴ ἐκστῆναι τῶν λογισμῶν, πρῶτος δ’ αὐτῷ τῶν φίλων ἐτόλμησε Μιθροβαρζάνης φράσαι τὸ ἀληθές, οὐδ’ οὗτος δὲ χρηστὸν ἠνέγκατο γέρας τῆς παρρησίας. ἐπέμφθη γὰρ εὐθὺς ἐπὶ τὸν Λούκουλλον σὺν ἱππεῦσι τρισχιλίοις, πεζοῖς δὲ παμπόλλοις, κελευσθεὶς τὸν μὲν στρατηγὸν ἄγειν ζῶντα, τοὺς δ’ ἄλλους καταπατῆσαι.", "st": "Luc. 25.1"}, {"sp": "N", "t": "Λουκούλλῳ δὲ τῆς στρατιᾶς ἡ μὲν ἤδη κατεζεύγνυεν, ἡ δὲ ἔτι προσῄει. τῶν δὲ σκοπῶν αὐτῷ φρασάντων ἐπελαύνοντα τὸν βάρβαρον, ἔδεισε μὴ χωρὶς ὄντας καὶ οὐκ ἐν τάξει προσπεσὼν ταράξῃ. καὶ αὐτὸς μὲν καθίστατο τὴν στρατοπεδείαν, Σεξτίλιον δὲ πρεσβευτὴν ἔπεμψεν ἱππεῖς ἔχοντα χιλίους ἑξακοσίους, ὁπλίτας δὲ καὶ ψιλοὺς οὐ πολλῷ πλείονας, κελεύσας ἐγγὺς προσελθόντα τοῖς πολεμίοις μένειν, ἕως ἂν πύθηται τοὺς μετ’ αὐτοῦ κατεστρατοπεδευκότας. ἐβούλετο μὲν οὖν ὁ Σεξτίλιος ταῦτα ποιεῖν, ἐβιάσθη δ’ ὑπὸ τοῦ Μιθροβαρζάνου θρασέως ἐπελαύνοντος εἰς χεῖρας ἐλθεῖν. καὶ γενομένης μάχης ὁ μὲν Μιθροβαρζάνης ἔπεσεν ἀγωνιζόμενος, οἱ δ’ ἄλλοι φεύγοντες ἀπώλοντο πλὴν ὀλίγων ἅπαντες.", "st": "Luc. 25.3"}, {"sp": "N", "t": "ἐκ τούτου Τιγράνης μὲν ἐκλιπὼν Τιγρανόκερτα, μεγάλην πόλιν ἐκτισμένην ὑπ’ αὐτοῦ, πρὸς τὸν Ταῦρον ἀνεχώρησε καὶ τὰς δυνάμεις πανταχόθεν ἐνταῦθα συνῆγε, Λούκουλλος δὲ τῇ παρασκευῇ χρόνον οὐ διδούς Μουρήναν μὲν ἐξέπεμψεν ἐνοχλήσοντα καὶ περικόψοντα τοὺς ἀθροιζομένους πρὸς τὸν Τιγράνην, Σεξτίλιον δὲ πάλιν Ἀράβων χεῖρα μεγάλην ἀνείρξοντα βασιλεῖ προσιοῦσαν· ὁμοῦ δὲ Σεξτίλιος μὲν ἐπιπεσὼν στρατόπεδον ποιουμένοις τοῖς Ἄραψι τοὺς πλείστους διέφθειρε, Μουρήνας δ’ ἑπόμενος Τιγράνῃ τραχὺν αὐλῶνα καὶ στενόπορον στρατῷ μακρῷ διεκβάλλοντι καιροῦ παρασχόντος ἐπιτίθεται, καὶ φεύγει μὲν αὐτὸς Τιγράνης προέμενος τὴν ἀποσκευὴν ἅπασαν, ἀποθνῄσκουσι δὲ πολλοὶ καὶ πλείονες ἁλίσκονται τῶν Ἀρμενίων.", "st": "Luc. 25.5"}, {"sp": "N", "t": "οὕτω δὲ τούτων προχωρούντων ἄρας ὁ Λούκουλλος ἐπορεύετο πρὸς Τιγρανόκερτα, καὶ περιστρατοπεδεύσας ἐπολιόρκει τὴν πόλιν. ἦσαν δ’ ἐν αὐτῇ πολλοὶ μὲν Ἕλληνες τῶν ἀναστάτων ἐκ Κιλικίας, πολλοὶ δὲ βάρβαροι τοῖς Ἕλλησιν ὅμοια πεπονθότες, Ἀδιαβηνοὶ καὶ Ἀσσύριοι καὶ Γορδυηνοὶ καὶ Καππάδοκες, ὧν κατασκάψας τὰς πατρίδας, αὐτοὺς δὲ κομίσας ἐκεῖ κατοικεῖν ἠνάγκασεν. ἦν δὲ καὶ χρημάτων ἡ πόλις μεστὴ καὶ ἀναθημάτων, παντὸς ἰδιώτου καὶ δυνάστου τῷ βασιλεῖ συμφιλοτιμουμένου πρὸς αὔξησιν καὶ κατασκευὴν τῆς πόλεως, διὸ καὶ συντόνως ἐπολιόρκει ὁ Λούκουλλος αὐτήν, οὐκ ἀνέξεσθαι τὸν Τιγράνην οἰόμενος, ἀλλὰ καὶ παρὰ γνώμην ὑπ’ ὀργῆς καταβήσεσθαι διαμαχούμενον, ὀρθῶς οἰόμενος. πολλὰ δὲ Μιθριδάτης ἀπηγόρευσεν ἀγγέλους πέμπων καὶ γράμματα μὴ συνάπτειν μάχην, ἀλλὰ τοῖς ἱππεῦσι περικόπτειν τὴν ἀγοράν πολλὰ δὲ Ταξίλης ἥκων παρ’ αὐτοῦ καὶ συστρατεύων ἐδεῖτο τοῦ βασιλέως φυλάττεσθαι καὶ φεύγειν ὡς ἄμαχον πρᾶγμα τὰ Ῥωμαίων ὅπλα. καὶ τά γε πρῶτα πρᾴως ἤκουε τούτων, ἐπεὶ δὲ πανστρατιᾷ μὲν αὐτῷ συνῆλθον Ἀρμένιοι καὶ Γορδυηνοί, πανστρατιᾷ δὲ Μήδους καὶ Ἀδιαβηνοὺς ἄγοντες οἱ βασιλεῖς παρῆσαν, ἧκον δὲ πολλοὶ μὲν ἀπὸ τῆς ἐν Βαβυλῶνι θαλάσσης Ἄραβες, πολλοὶ δὲ ἀπὸ τῆς Κασπίας Ἀλβανοὶ καὶ Ἴβηρες Ἀλβανοῖς προσοικοῦντες, οὐκ ὀλίγοι δὲ τῶν περὶ τὸν Ἀράξην νεμομένων ἀβασίλευτοι χάριτι καὶ δώροις πεισθέντες ἀπήντησαν, ἐλπίδων δὲ καὶ θράσους καὶ βαρβαρικῶν ἀπειλῶν μεστὰ μὲν ἦν τὰ συμπόσια τοῦ βασιλέως, μεστὰ δὲ τὰ συμβούλια, παρεκινδύνευσε μὲν ὁ Ταξίλης ἀποθανεῖν ὑπεναντιούμενος τῇ γνώμῃ τῆς μάχης, ἐδόκει δὲ καὶ Μιθριδάτης φθονῶν ἀποτρέπειν μεγάλου κατορθώματος. ὅθεν οὐδ’ ἀνέμεινεν αὐτὸν ὁ Τιγράνης, μὴ μετάσχοι τῆς δόξης, ἀλλ’ ἐχώρει παντὶ τῷ στρατῷ σφόδρα δυσφορῶν, ὡς λέγεται, πρὸς τοὺς φίλους, ὅτι πρὸς Λούκουλλον αὐτῷ μόνον, οὐ πρὸς ἅπαντας ὁ ἀγὼν ἔσοιτο τοὺς Ῥωμαίων στρατηγοὺς ἐν ταὐτῷ γενομένους.", "st": "Luc. 26.1"}, {"sp": "N", "t": "καὶ οὐ παντάπασιν ἦν τὸ θράσος αὐτοῦ μανιῶδες οὐδ’ ἄλογον, ἔθνη τοσαῦτα καὶ βασιλεῖς ἑπομένους καὶ φάλαγγας ὁπλιτῶν καὶ μυριάδας ἱππέων ἀποβλέποντος. τοξότας μὲν γὰρ καὶ σφενδονήτας δισμυρίους ἦγεν, ἱππεῖς δὲ πεντακισμυρίους καὶ πεντακισχιλίους, ὧν ἑπτακισχίλιοι καὶ μύριοι κατάφρακτοι ἦσαν, ὡς Λούκουλλος ἔγραψε πρὸς τὴν σύγκλητον, ὁπλιτῶν δέ, τῶν μὲν εἰς σπείρας, τῶν δ’ εἰς φάλαγγας συντεταγμένων, πεντεκαίδεκα μυριάδας, ὁδοποιοὺς δὲ καὶ γεφυρωτὰς καὶ καθαρτὰς ποταμῶν καὶ ὑλοτόμους καὶ τῶν ἄλλων χρειῶν ὑπηρέτας τρισμυρίους καὶ πεντακισχιλίους, οἳ τοῖς μαχομένοις ἐπιτεταγμένοι κατόπιν ὄψιν ἅμα καὶ ῥώμην παρεῖχον.", "st": "Luc. 26.6"}, {"sp": "N", "t": "ὡς δ’ ὑπερβαλὼν τὸν Ταῦρον ἄθρους κατεφάνη καὶ κατεῖδε πρὸς τοῖς Τιγρανοκέρτοις ἐπικαθήμενον τὸ στράτευμα τῶν Ῥωμαίων, ὁ μὲν ἐν τῇ πόλει βάρβαρος ὅμιλος ὀλολυγῇ καὶ κρότῳ τὴν ὄψιν ἐδέξατο, καὶ τοῖς Ῥωμαίοις ἀπὸ τῶν τειχῶν ἀπειλοῦντες ἐδείκνυσαν τοὺς Ἀρμενίους· Λουκούλλῳ δὲ σκοποῦντι περὶ τῆς μάχης οἱ μὲν ἄγειν ἐπὶ Τιγράνην ἐάσαντα τὴν πολιορκίαν συνεβούλευον, οἱ δὲ μὴ καταλιπεῖν ὀπίσω πολεμίους τοσούτους μηδ’ ἀνεῖναι τὴν πολιορκίαν. ὁ δ’ εἰπὼν ἑκατέρους μὲν οὐκ ὀρθῶς, ἀμφοτέρους δὲ καλῶς παραινεῖν διεῖλε τὴν στρατιάν. καὶ Μουρήναν μὲν ἑξακισχιλίους ἔχοντα πεζοὺς ἐπὶ τῆς πολιορκίας ἀπέλιπεν, αὐτὸς δὲ τέσσαρας καὶ εἴκοσι σπείρας ἀναλαβών, ἐν αἷς οὐ πλείονες ἦσαν μυρίων ὁπλιτῶν, καὶ τοὺς ἱππεῖς ἅπαντας καὶ σφενδονήτας καὶ τοξότας περὶ χιλίους, ἐχώρει.", "st": "Luc. 27.1"}, {"sp": "N", "t": "καὶ παρὰ τὸν ποταμὸν ἐν πεδίῳ μεγάλῳ καταστρατοπεδεύσας παντάπασι μικρὸς ἐφάνη Τιγράνῃ, καὶ τοῖς κολακεύουσιν αὐτὸν διατριβὴν παρεῖχεν. οἱ μὲν γὰρ ἔσκωπτον, οἱ δ’ ὑπὲρ τῶν λαφύρων ἐν παιδιᾷ διεβάλλοντο κλῆρον τῶν δὲ στρατηγῶν καὶ βασιλέων ἕκαστος ᾐτεῖτο προσιὼν αὐτοῦ μόνου γενέσθαι τὸ ἔργον, ἐκεῖνον δὲ καθέζεσθαι θεατήν. βουλόμενος δέ τι καὶ αὐτὸς ὁ Τιγράνης χαρίεις εἶναι καὶ σκωπτικός εἶπε τὸ θρυλούμενον· εἰ μὲν ὡς πρεσβευταί, πολλοὶ πάρεισιν εἰ δ’ ὡς στρατιῶται, ὀλίγοι. καὶ τότε μὲν οὕτως εἰρωνευόμενοι καὶ παίζοντες διετέλεσαν, ἅμα δ’ ἡμέρᾳ Λούκουλλος ὡπλισμένην τὴν δύναμιν ἐξῆγε. καὶ πρὸς ἕω μὲν ἦν τοῦ ποταμοῦ τὸ βαρβαρικὸν στράτευμα· τοῦ δὲ ῥεύματος ἀποστροφὴν λαμβάνοντος ἐπὶ τὰς δύσεις, ᾗ μάλιστα περάσιμον ἦν, ἀντιπαρεξάγων τὴν δύναμιν καὶ σπεύδων ἔδοξεν ἀποχωρεῖν τῷ Τιγράνῃ. καὶ καλέσας τὸν Ταξίλην ἅμα γέλωτι τοὺς ἀμάχους, ἔφη, Ῥωμαίων ὁπλίτας οὐχ ὁρᾷς φεύγοντας; καὶ ὁ Ταξίλης βουλοίμην ἄν, εἶπεν, ὦ βασιλεῦ, γενέσθαι τι τῷ σῷ δαίμονι τῶν παραλόγων, ἀλλ’ οὔτ’ ἐσθῆτα λαμπρὰν οἱ ἄνδρες λαμβάνουσιν ὁδοιποροῦντες οὔτε θυρεοῖς ἐκκεκαθαρμένοις χρῶνται καὶ κράνεσι γυμνοῖς, ὥσπερ νῦν τὰ σκύτινα τῶν ὅπλων σκεπάσματα περισπάσαντες, ἀλλὰ μαχουμένων ἐστὶν ἡ λαμπρότης αὕτη καὶ βαδιζόντων ἤδη πρὸς τοὺς πολεμίους· ταῦτα λέγοντος ἔτι τοῦ Ταξίλου καταφανὴς ἦν πρῶτος ἀετὸς ἐπιστρέφοντος τοῦ Λουκούλλου καὶ τάξιν αἱ σπεῖραι κατὰ λόχους λαμβάνουσαι πρὸς τὴν διάβασιν καὶ μόλις ὥσπερ ἐκ μέθης τινὸς ἀναφέρων ὁ Τιγράνης δὶς ἢ τρὶς ἐξέκραγεν· ἐφ’ ἡμᾶς οἱ ἄνδρες; ὥστε θορύβῳ πολλῷ τὸ πλῆθος εἰς τάξιν καθίστασθαι, βασιλέως μὲν αὐτοῦ τὸ μέσον ἔχοντος, τῶν δὲ κεράτων τὸ μὲν ἀριστερὸν τῷ Ἀδιαβηνῷ, τὸ δὲ δεξιὸν τῷ Μήδῳ παραδόντος, ἐφ’ οὗ καὶ τῶν καταφράκτων ἐν προτάγματι τὸ πλεῖστον ἦν.", "st": "Luc. 27.3"}, {"sp": "N", "t": "Λουκούλλῳ δὲ μέλλοντι διαβαίνειν τὸν ποταμὸν ἔνιοι τῶν ἡγεμόνων παρῄνουν φυλάττεσθαι τὴν ἡμέραν μίαν οὖσαν τῶν ἀποφράδων, ἃς μελαίνας καλοῦσιν· ἐν ἐκείνῃ γὰρ τῇ ἡμέρᾳ ἡ μετὰ Καιπίωνος ἀπώλετο στρατιὰ συμβαλοῦσα Κίμβροις. ὁ δ’ ἀπεκρίνατο τὴν μνημονευομένην φωνήν. ἐγὼ γάρ, ἔφη, καὶ ταύτην εὐτυχῆ ποιήσω Ῥωμαίοις τὴν ἡμέραν. ᾖν δὲ πρὸ μιᾶς νωνῶν Ὀκτωβρίων.", "st": "Luc. 27.7"}, {"sp": "N", "t": "ταῦτα δ’ εἰπὼν καὶ θαρρεῖν κελεύσας τόν τε ποταμὸν διέβαινε καὶ πρῶτος ἐπὶ τοὺς πολεμίους ἡγεῖτο, θώρακα μὲν ἔχων σιδηροῦν φολιδωτὸν ἀποστίλβοντα, κροσσωτὴν δὲ ἐφεστρίδα, τὸ δὲ ξίφος αὐτόθεν ὑποφαίνων γυμνόν, ὡς εὐθὺς εἰς χεῖρας ἵεσθαι δέον ἑκηβόλοις ἀνδράσι καὶ συναιρεῖν τὴν διατοξεύσιμον χώραν τῷ τάχει τῆς ἐπαγωγῆς. ἐπεὶ δὲ τὴν κατάφρακτον ἵππον, ἧς πλεῖστος ἦν λόγος, κατεῖδε κατατεταγμένην ὑπὸ λόφῳ τινὶ τὴν ἄνω χώραν ἐπίπεδον καὶ πλατεῖαν ἔχοντι, πρόσβασιν δὲ τεττάρων σταδίων οὐ παντάπασι χαλεπὴν οὐδ’ ἀποκεκομμένην, Θρᾷκας μὲν ἱππεῖς καὶ Γαλάτας, οὓς εἶχεν, ἐκέλευσεν ἐκ πλαγίου προσφερομένους παρακρούεσθαι ταῖς μαχαίραις τοὺς κοντούς. μία γὰρ ἀλκὴ τῶν καταφράκτων κοντός· ἄλλο δ’ οὐδὲν οὔθ’ ἑαυτοῖς οὔτε τοῖς πολεμίοις χρῆσθαι δύνανται διὰ βάρος καὶ σκληρότητα τῆς σκευῆς, ἀλλ’ ἐγκατῳκοδομημένοις ἐοίκασιν. αὐτὸς δὲ δύο σπείρας ἀναλαβὼν ἡμιλλᾶτο πρὸς τόν λόφον, ἐρρωμένως ἑπομένων τῶν στρατιωτῶν διὰ τὸ κἀκεῖνον ἐν τοῖς ὅπλοις ὁρᾶν πρῶτον κακοπαθοῦντα πεζὸν καὶ προσβιαζόμενον.", "st": "Luc. 28.1"}, {"sp": "N", "t": "γενόμενος δ’ ἄνω καὶ στὰς ἐν τῷ περιφανεῖ τοῦ χωρίου μέγα βοήσας· νενικήκαμεν, ἔφη, νενικήκαμεν, ὦ συστρατιῶται. καὶ τοῦτο εἰπὼν ἐπῆγε τοῖς καταφράκτοις, κελεύσας μηδὲν ἔτι χρῆσθαι τοῖς ὑσσοῖς, ἀλλ’ ἐκ χειρὸς ἕκαστον διαλαβόντα παίειν τῶν πολεμίων κνήμας τε καὶ μηρούς, ἃ μόνα γυμνὰ τῶν καταφράκτων ἐστίν, οὐ μὴν ἐδέησέ τι ταύτης τῆς μάχης οὐ γὰρ ἐδέξαντο τοὺς Ῥωμαίους, ἀλλ’ ἀλαλάξαντες καὶ φεύγοντες αἴσχιστα πάντων ἐνέωσαν ἑαυτούς τε καὶ τοὺς ἵππους βαρεῖς ὄντας εἰς τὰ τῶν πεζῶν ὅπλα πρὶν ἄρξασθαί τινος ἐκείνους μάχης, ὥστε μήτε τραύματος γενομένου μήθ’ αἵματος ὀφθέντος ἡττᾶσθαι τὰς τοσαύτας μυριάδας. ὁ δὲ πολὺς φόνος ἤδη φευγόντων ἐγίνετο, μᾶλλον δὲ βουλομένων φεύγειν οὐ γὰρ ἐδύναντο πυκνότητι καὶ βάθει τῶν τάξεων ὑφ’ αὑτῶν ἐμποδιζόμενοι.", "st": "Luc. 28.4"}, {"sp": "N", "t": "Τιγράνης δ’ ἐξελάσας ἐν ἀρχῇ μετ’ ὀλίγων ἔφευγε· καὶ τόν υἱὸν ὁρῶν κοινωνοῦντα τῆς αὐτῆς τύχης περιεσπάσατο τὸ διάδημα τῆς κεφαλῆς κἀκείνῳ δακρύσας παρέδωκε, σῴζειν ἑαυτὸν, ὅπως δύναται, καθ’ ἑτέρας ὁδοὺς κελεύσας. ὁ δὲ νεανίας ἀναδήσασθαι μὲν οὐκ ἐτόλμησε, τῶν δὲ παίδων τῷ πιστοτάτῳ φυλάττειν ἔδωκεν. οὗτος ἁλοὺς κατὰ τύχην ἀνήχθη πρὸς Λούκουλλον, ὥστε μετὰ τῶν ἄλλων αἰχμάλωτον καὶ τὸ διάδημα γενέσθαι τοῦ Τιγράνου. λέγεται δὲ τῶν μὲν πεζῶν ὑπὲρ δέκα μυριάδας διαφθαρῆναι, τῶν δ’ ἱππέων ὀλίγους παντάπασι διαφυγεῖν. Ῥωμαίων δ’ ἑκατὸν ἐτρώθησαν, ἔπεσον δὲ πέντε.", "st": "Luc. 28.6"}, {"sp": "N", "t": "ταύτης τῆς μάχης Ἀντίοχος ὁ φιλόσοφος ἐν τῇ Περὶ θεῶν γραφῇ μνησθεὶς οὔ φησιν ἄλλην ἐφεωρακέναι τοιαύτην τόν ἥλιον. Στράβων δ’, ἕτερος φιλόσοφος, ἐν τοῖς ἱστορικοῖς ὑπομνήμασιν αὐτοὺς λέγει τοὺς Ῥωμαίους αἰσχύνεσθαι καὶ καταγελᾶν ἑαυτῶν ἐπ’ ἀνδράποδα τοιαῦτα δεηθέντας ὅπλων. Λίουϊος δ’ εἴρηκεν, ὡς οὐδέποτε Ῥωμαῖοι πολεμίοις ἀποδέοντες τοσούτῳ πλήθει παρετάξαντο· σχεδὸν γὰρ οὐδ’ εἰκοστόν, ἀλλ’ ἔλαττον ἐγένοντο μέρος οἱ νικῶντες τῶν ἡσσημένων. Ῥωμαίων δ’ οἱ δεινότατοι στρατηγοὶ καὶ πλεῖστα πολέμοις ὡμιληκότες ἐπῄνουν μάλιστα τοῦ Λουκούλλου τὸ δύο βασιλεῖς τοὺς ἐπιφανεστάτους καὶ μεγίστους δυσὶ τοῖς ἐναντιωτάτοις, τάχει καὶ βραδυτῆτι, καταστρατηγῆσαι. Μιθριδάτην μὲν γὰρ ἀκμάζοντα χρόνῳ καὶ τριβῇ κατανάλωσε, Τιγράνην δὲ τῷ σπεῦσαι συνέτριψεν, ἐν ὀλίγοις τῶν πώποτε ἡγεμόνων τῇ μελλήσει μὲν ἔργῳ, τῇ τόλμῃ δ’ ὑπὲρ ἀσφαλείας χρησάμενος.", "st": "Luc. 28.7"}, {"sp": "N", "t": "διὸ καὶ Μιθριδάτης οὐ συνέτεινεν ἐπὶ τὴν μάχην, τῇ συνήθει τὸν Λούκουλλον εὐλαβείᾳ καὶ παραγωγῇ πολεμήσειν οἰόμενος, ἀλλὰ καθ’ ἡσυχίαν ἐπορεύετο πρὸς τὸν Τιγράνην. καὶ πρῶτον μὲν ὀλίγοις τῶν Ἀρμενίων ἐντυχὼν καθ’ ὁδὸν ἐπτοιημένοις καὶ περιφόβοις ἀπιοῦσιν εἴκασε τὸ πάθος, εἶτ’ ἤδη πλειόνων γυμνῶν καὶ τετρωμένων ἀπαντώντων πυθόμενος τὴν ἧτταν ἐζήτει τὸν Τιγράνην. εὑρὼν δὲ πάντων ἔρημον καὶ ταπεινόν οὐκ ἀνθύβρισεν, ἀλλὰ καταβὰς καὶ συνδακρύσας τὰ κοινὰ πάθη θεραπείαν τε τὴν ἑπομένην αὐτῷ βασιλικὴν ἔδωκε καὶ κατεθάρρυνε πρὸς τὸ μέλλον, οὗτοι μὲν οὖν αὖθις ἑτέρας δυνάμεις συνῆγον.", "st": "Luc. 29.1"}, {"sp": "N", "t": "ἐν δὲ τῇ πόλει τοῖς Τιγρανοκέρτοις τῶν Ἑλλήνων πρὸς τοὺς βαρβάρους στασιασάντων καὶ τῷ Λουκούλλῳ τὴν πόλιν ἐνδιδόντων προσβαλὼν εἷλε· καὶ τοὺς μὲν ἐν τῇ πόλει θησαυροὺς παρελάμβανε, τὴν δὲ πόλιν διαρπάσαι παρέδωκε τοῖς στρατιώταις, μετὰ τῶν ἄλλων χρημάτων ὀκτακισχίλια τάλαντα νομίσματος ἔχουσαν. χωρὶς δὲ τούτων ὀκτακοσίας δραχμὰς κατ’ ἄνδρα διένειμεν ἀπὸ τῶν λαφύρων. πυνθανόμενος δὲ πολλοὺς ἐν τῇ πόλει κατειλῆφθαι τῶν περὶ τὸν Διόνυσον τεχνιτῶν, οὓς ὁ Τιγράνης πανταχόθεν ἠθροίκει μέλλων ἀποδεικνύναι τὸ κατεσκευασμένον ὑπ’ αὑτοῦ θέατρον, ἐχρήσατο τούτοις πρὸς τοὺς ἀγῶνας καὶ τὰς θέας τῶν ἐπινικίων. τοὺς δ’ Ἕλληνας εἰς τὰς αὑτῶν πατρίδας ἔπεμψε προσθεὶς ἐφόδια, καὶ τῶν βαρβάρων ὁμοίως τοὺς ἠναγκασμένους κατοικεῖν, ὥστε συνέβη μιᾶς πόλεως διαλυθείσης πολλὰς ἀνοικίζεσθαι πάλιν κομιζομένας τοὺς αὑτῶν οἰκήτορας, ὑφ’ ὧν ὡς εὐεργέτης ὁ Λούκουλλος καὶ κτίστης ἠγαπᾶτο.", "st": "Luc. 29.3"}, {"sp": "N", "t": "προὐχώρει δὲ καὶ τἆλλα κατ’ ἀξίαν τἀνδρί τῶν ἀπὸ δικαιοσύνης καὶ φιλανθρωπίας ἐπαίνων ὀρεγομένῳ μᾶλλον ἢ τῶν ἐπὶ τοῖς πολεμικοῖς κατορθώμασιν. ἐκείνων μὲν γὰρ οὐκ ὀλίγον ἡ στρατιὰ καὶ πλεῖστον ἡ τύχη μετεῖχε, ταῦτα δ’ ἦν ἡμέρου ψυχῆς καὶ πεπαιδευμένης ἐπίδειξις, οἷς ὁ Λούκουλλος τότε χωρὶς ὅπλων ἐχειροῦτο τοὺς βαρβάρους, καὶ γὰρ Ἀράβων βασιλεῖς ἧκον πρὸς αὐτὸν ἐγχειρίζοντες τὰ σφέτερα, καὶ τὸ Σωφηνῶν ἔθνος προσεχώρει· τὸ δὲ Γορδυηνῶν οὕτω διέθηκεν, ὥστε βούλεσθαι τὰς πόλεις ἐκλιπόντας ἀκολουθεῖν ἐκείνῳ μετὰ παίδων καὶ γυναικῶν ἐθελοντὰς ἐξ αἰτίας τοιᾶσδε. Ζαρβιηνὸς γὰρ ὁ τῶν Γορδυηνῶν βασιλεὺς, ὥσπερ εἴρηται, δι’ Ἀππίου κρύφα Λουκούλλῳ διείλεκτο περὶ συμμαχίας τὴν Τιγράνου τυραννίδα βαρυνόμενος· μηνυθεὶς δ’ ἀπεσφάγη, καὶ παῖδες αὑτοῦ καὶ γυνὴ συναπώλοντο πρὶν ἢ Ῥωμαίους εἰς Ἀρμενίαν ἐμβαλεῖν. τούτων οὐκ ἠμνημόνησεν ὁ Λούκουλλος, ἀλλὰ παρελθὼν εἰς τὴν Γορδυηνῶν ταφὰς προὔθετο τοῦ Ζαρβιηνοῦ, καὶ πυρὰν ἐσθῆτι καὶ χρυσῷ βασιλικῷ καὶ τοῖς ἀπὸ Τιγράνου κοσμήσας λαφύροις αὐτὸς παρὼν ὑφῆψε, καὶ χοὰς ἐπήνεγκε μετὰ φίλων καὶ οἰκείων τοῦ ἀνδρός, ἑταῖρον ἑαυτοῦ καὶ Ῥωμαίων σύμμαχον ἀνακαλούμενος. ἐκέλευσε δὲ καὶ μνημεῖον ἀπὸ χρημάτων συχνῶν αὐτῷ γενέσθαι· πάμπολλα γὰρ εὑρέθη, καὶ χρυσὸς καὶ ἄργυρος ἐν τοῖς τοῦ Ζαρβιηνοῦ βασιλείοις, σίτου δ’ ἀπέκειντο μυριάδες τριακόσιαι μεδίμνων, ὥστε καὶ τοὺς στρατιώτας ὠφελεῖσθαι καὶ τὸν Λούκουλλον θαυμάζεσθαι, ὅτι δραχμὴν μίαν ἐκ τοῦ δημοσίου ταμιείου μὴ λαβὼν αὐτὸν ἐξ αὑτοῦ διῴκει τὸν πόλεμον.", "st": "Luc. 29.5"}, {"sp": "N", "t": "ἐνταῦθα καὶ παρὰ τοῦ Πάρθων βασιλέως ἧκε πρεσβεία παρ’ αὐτόν εἰς φιλίαν προκαλουμένου καὶ συμμαχίαν. ἦν δ’ ἀσμένῳ ταῦτα τῷ Λουκούλλῳ· καὶ πάλιν ἀντέπεμψε παρ’ ἑαυτοῦ πρεσβείαν πρὸς τὸν Πάρθον, οἳ κατεφώρασαν αὐτόν ἐπαμφοτερίζοντα τῇ γνώμῃ καὶ μισθὸν αἰτοῦντα κρύφα τοῦ συμμαχῆσαι τῷ Τιγράνῃ τὴν Μεσοποταμίαν. ὡς οὖν ταῦθ’ ὁ Λούκουλλος ᾔσθετο, Τιγράνην μὲν ἔγνω καὶ Μιθριδάτην παρελθεῖν ὥσπερ ἀνταγωνιστὰς ἀπειρηκότας, ἀποπειρᾶσθαι δὲ τῆς Πάρθων δυνάμεως καὶ στρατεύειν ἐπ’ αὐτούς, καλὸν ἡγούμενος μιᾷ ῥύμῃ πολέμου τρεῖς ἐφεξῆς ὥσπερ ἀθλητὴς βασιλεῖς καταπαλαῖσαι καὶ διὰ τριῶν τῶν ὑπὸ τὸν ἥλιον μεγίστων ἡγεμονιῶν ἀήττητος καὶ νικῶν διεξελθεῖν.", "st": "Luc. 30.1"}, {"sp": "N", "t": "ἔπεμψεν οὖν εἰς Πόντον τοῖς περὶ Σωρνάτιον ἡγεμόσιν ἐπιστείλας ἄγειν τὴν ἐκεῖ στρατιὰν πρὸς αὐτόν, ὡς ἐκ τῆς Γορδυηνῆς ἀναβησόμενος. οἱ δὲ καὶ πρότερον χαλεποῖς χρώμενοι καὶ δυσπειθέσι τοῖς στρατιώταις τότε παντελῶς ἀπεκάλυψαν αὐτῶν τὴν ἀκολασίαν, οὐδενὶ τρόπῳ πειθοῦς οὐδ’ ἀνάγκης εὑρόμενοι προσαγαγέσθαι μαρτυρομένους καὶ βοῶντας, ὡς οὐδ’ αὐτόθι μενοῦσιν, ἀλλ’ οἰχήσονται τὸν Πόντον ἔρημον ἀπολιπόντες. ταῦτα πρὸς Λούκουλλον ἀπαγγελθέντα καὶ τοὺς ἐκεῖ προσδιέφθειρε στρατιώτας, ἤδη μὲν ὑπὸ πλούτου καὶ τρυφῆς βαρεῖς γεγονότας πρὸς τὴν στρατείαν καὶ σχολῆς δεομένους, ὡς δὲ τὴν ἐκείνων ἐπύθοντο παρρησίαν, ἄνδρας αὐτοὺς ἀπεκάλουν καὶ μιμητέον αὐτοὺς ἔφασαν εἶναι· πολλὰ γὰρ αὐτοῖς ἄξια σωτηρίας καὶ ἀναπαύσεως κατειργάσθαι.", "st": "Luc. 30.3"}, {"sp": "N", "t": "τοιούτων δὲ καὶ πονηροτέρων ἔτι λόγων αἰσθόμενος ὁ Λούκουλλος τὴν ἐπὶ Πάρθους στρατείαν ἀφῆκεν, αὖθις δ’ ἐπὶ τὸν Τιγράνην ἐβάδιζε θέρους ἀκμάζοντος, καὶ τὸν Ταῦρον ὑπερβαλὼν ἠθύμησε χλωρῶν τῶν πεδίων ἐκφανέντων τοσοῦτον αἱ ὧραι διὰ τὴν ψυχρότητα τοῦ ἀέρος ὑστερίζουσιν. οὐ μὴν ἀλλὰ καταβὰς καὶ δὶς ἢ τρὶς ἀνατολμήσαντας ἐπ’ αὐτὸν τοὺς Ἀρμενίους τρεψάμενος ἀδεῶς ἐπόρθει τὰς κώμας, καὶ τὸν παρεσκευασμένον τῷ Τιγράνῃ σῖτον ἐξαιρῶν ἣν αὐτὸς ἐφοβεῖτο τοῖς πολεμίοις περιέστησεν ἀπορίαν. ἐπεὶ δὲ προκαλούμενος εἰς μάχην αὐτούς περιταφρεύων τὸν χάρακα καὶ πορθῶν ἐν ὄψει τὴν χώραν οὐκ ἐκίνει πεπληγότας πολλάκις, ἀναστὰς ἐβάδιζεν ἐπ’ Ἀρτάξατα τὸ Τιγράνου βασίλειον, ὅπου καὶ παῖδες αὐτῷ νήπιοι καὶ γαμεταὶ γυναῖκες ἦσαν, οὐκ ἂν οἰόμενος ἀμαχεὶ ταῦτα προήσεσθαι τὸν Τιγράνην.", "st": "Luc. 31.1"}, {"sp": "N", "t": "λέγεται δ’ Ἀννίβαν τὸν Καρχηδόνιον, Ἀντιόχου καταπολεμηθέντος ὑπὸ Ῥωμαίων, μεταβάντα πρὸς Ἀρτάξαν τὸν Ἀρμένιον ἄλλων τε πολλῶν εἰσηγητὴν καὶ διδάσκαλον αὐτῷ γενέσθαι χρησίμων, καὶ τῆς χώρας καταμαθόντα τόπον εὐφυέστατον καὶ ἥδιστον ἀργοῦντα καὶ παρορώμενον σχῆμα πόλεως ἐν αὐτῷ προϋπογράψασθαι, καὶ τὸν Ἀρτάξαν ἐπαγαγόντα δεῖξαι καὶ παρορμῆσαι πρὸς τὸν οἰκισμόν. ἡσθέντος δὲ τοῦ βασιλέως καὶ δεηθέντος, ὅπως αὐτὸς ἐπιστατήσῃ τοῦ ἔργου, μέγα τι καὶ πάγκαλον χρῆμα πόλεως ἀναστῆναι, καὶ γενομένην ἐπώνυμον τοῦ βασιλέως μητρόπολιν ἀποδειχθῆναι τῆς Ἀρμενίας.", "st": "Luc. 31.3"}, {"sp": "N", "t": "ἐπὶ ταύτην τοῦ Λουκούλλου βαδίζοντος οὐκ ἠνέσχετο Τιγράνης, ἀλλὰ τὴν δύναμιν ἀναλαβὼν ἡμέρᾳ τετάρτῃ παρεστρατοπέδευσε τοῖς Ῥωμαίοις, ἐν μέσῳ λαβὼν τὸν Ἀρσανίαν ποταμόν, ὃν ἐξ ἀνάγκης διαβατέον ἦν τοῖς Ῥωμαίοις τὴν ἐπ’ Ἀρταξάτων πορευομένοις. θύσας δὲ τοῖς θεοῖς Λούκουλλος, ὡς ἐν χερσὶν οὔσης τῆς νίκης, διεβίβαζε τὸν στρατὸν ἐν δώδεκα σπείραις προτεταγμέναις, ταῖς δ’ ἄλλαις ἐπιτεταγμέναις πρὸς τὰς κυκλώσεις τῶν πολεμίων. πολλοὶ γὰρ ἦσαν ἱππεῖς καὶ λογάδες ἀντιπαρατεταγμένοι, πρὸ δ’ αὐτῶν ἱπποτοξόται Μάρδοι καὶ λογχοφόροι Ἴβηρες, οἷς μάλιστα τῶν ξένων ὁ Τιγράνης ἐπίστευεν ὡς μαχιμωτάτοις. οὐ μὴν ἐπράχθη τι λαμπρὸν ἀπ’ αὐτῶν, μικρὰ δὲ τοῖς ἱππεῦσι τῶν Ῥωμαίων διαπληκτισάμενοι τοὺς πεζοὺς ἐπιόντας οὐχ ὑπέμειναν, ἀλλ’ ἑκατέρωσε τῆς φυγῆς σχισθέντες ἐπεσπάσαντο τοὺς ἱππεῖς πρὸς τὴν δίωξιν. ἅμα δὲ τῷ τούτους διασπαρῆναι τῶν περὶ τὸν Τιγράνην ἐξιππασαμένων ἰδὼν τὴν λαμπρότητα καὶ τὸ πλῆθος ὁ Λούκουλλος ἔδεισε. καὶ τοὺς μὲν ἱππεῖς ἀπὸ τῆς διώξεως ἀνεκαλεῖτο, πρῶτος δ’ αὐτὸς ἀντέστη τοῖς Ἀτροπατηνοῖς κατ’ αὐτὸν οὖσι μετὰ τῶν ἀρίστων, καὶ πρὶν εἰς χεῖρας ἐλθεῖν φοβήσας ἐτρέψατο. τριῶν δ’ ὁμοῦ παρατεταγμένων βασιλέων αἴσχιστα δοκεῖ φυγεῖν ὁ Ποντικὸς Μιθριδάτης, οὐδὲ τὴν κραυγὴν τῶν Ῥωμαίων ἀνασχόμενος. γενομένης δὲ τῆς διώξεως μακρᾶς καὶ δι’ ὅλης νυκτός, οὐ μόνον κτείνοντες αὐτούς, ἀλλὰ καὶ ζωγροῦντες καὶ χρήματα καὶ λείαν ἄγοντες καὶ φέροντες ἀπεῖπον οἱ Ῥωμαῖοι. φησὶ δὲ ὁ Λίουϊος ἐν μὲν τῇ προτέρᾳ μάχῃ πλείονας, ἐν δὲ ταύτῃ γνωριμωτέρους πεσεῖν καὶ ληφθῆναι τῶν πολεμίων.", "st": "Luc. 31.5"}, {"sp": "N", "t": "ἐκ τούτου Λούκουλλος μὲν ἐπηρμένος καὶ τεθαρρηκὼς ἄνω προάγειν διενοεῖτο καὶ καταστρέφεσθαι τὴν βάρβαρον ὥρᾳ δ’ ἰσημερίας φθινοπωρινῆς οὐκ ἂν ἐλπίσαντι χειμῶνες ἐπέπεσον βαρεῖς, τὰ μὲν πλεῖστα κατανίφοντες, ἐν δὲ ταῖς αἰθρίαις πάχνην ἐπιφέροντες καὶ πάγον, ὑφ’ οὗ χαλεποὶ μὲν ἦσαν οἱ ποταμοὶ τοῖς ἵπποις πίνεσθαι διὰ ψυχρότητος ὑπερβολήν, χαλεπαὶ δ’ αὐτῶν αἱ διαβάσεις ἐκρηγνυμένου τοῦ κρυστάλλου καὶ διακόπτοντος τὰ νεῦρα τῶν ἵππων τῇ τραχύτητι. τῆς δὲ χώρας ἡ πολλὴ συνηρεφὴς οὖσα καὶ στενόπορος καὶ ἑλώδης ἀεὶ καθύγραινεν αὐτούς, χιόνος ἀναπιμπλαμένους ἐν ταῖς ὁδοιπορίαις καὶ κακῶς ἐν τόποις νοτεροῖς νυκτερεύοντας, οὐ πολλὰς οὖν ἡμέρας ἀκολουθήσαντες τῷ Λουκούλλῳ μετὰ τὴν μάχην ἠναντιοῦντο, πρῶτον δεόμενοι καὶ τοὺς χιλιάρχους προσπέμποντες, ἔπειτα θορυβωδέστερον συνιστάμενοι καὶ κατὰ σκηνὰς νυκτὸς ἀλαλάζοντες, ὅπερ εἶναι δοκεῖ σύμβολον ἀποστατικῶς ἐχούσης στρατιᾶς. καίτοι πολλὰ προσελιπάρει Λούκουλλος ἀξιῶν αὐτοὺς μακροθυμίαν ἐμβαλέσθαι ταῖς ψυχαῖς, ἄχρι οὗ τὴν ἐν Ἀρμενίοις Καρχηδόνα λαβόντες ἀνδρὸς ἐχθίστου, τὸν Ἀννίβαν λέγων, ἔργον ἀνατρέψωσιν. ὡς δ’ οὐκ ἔπειθεν, ἀπῆγεν αὐτοὺς ὀπίσω καὶ κατ’ ἄλλας ὑπερβολὰς διελθὼν τὸν Ταῦρον εἰς τὴν λεγομένην Μυγδονικὴν κατέβαινε, χώραν παμφόρον καὶ ἀλεεινὴν καὶ πόλιν ἐν αὑτῇ μεγάλην καὶ πολυάνθρωπον ἔχουσαν, ἣν οἱ μὲν βάρβαροι Νίσιβιν, οἱ δ’ Ἕλληνες Ἀντιόχειαν Μυγδονικὴν προσηγόρευον. ταύτην εἶχεν ἀξιώματι μὲν ἀδελφὸς Τιγράνου Γούρας, ἐμπειρίᾳ δὲ καὶ δεινότητι μηχανικῇ Καλλίμαχος ὁ καὶ περὶ Ἀμισὸν πλεῖστα πράγματα Λουκούλλῳ παρασχών, βαλόμενος δὲ στρατόπεδον καὶ πᾶσαν ἰδέαν πολιορκίας ἐπαγαγών ὀλίγῳ χρόνῳ κατὰ κράτος λαμβάνει τὴν πόλιν. καὶ Γούρᾳ μὲν ἑαυτὸν ἐγχειρίσαντι φιλανθρώπως ἐχρήσατο, Καλλιμάχῳ δ’ ὑπισχνουμένῳ θήκας ἀπορρήτους μεγάλων χρημάτων ἀνακαλύψειν οὐ προσέσχεν, ἀλλ’ ἐκέλευσεν ἐν πέδαις κομίζεσθαι δίκην ὑφέξοντα τοῦ πυρὸς, ᾧ τὴν Ἀμισηνῶν διαλυμηνάμενος πόλιν ἀφείλετο φιλοτιμίαν αὐτοῦ καὶ χρηστότητος ἐπίδειξιν πρὸς τοὺς Ἕλληνας.", "st": "Luc. 32.1"}, {"sp": "N", "t": "μέχρι τοῦδε φαίη τις ἂν Λουκούλλῳ τὴν τύχην ἑπομένην συστρατηγεῖν. ἐντεῦθεν δ’ ὥσπερ πνεύματος ἐπιλιπόντος προσβιαζόμενος πάντα καὶ παντάπασιν ἀντικρούων ἀρετὴν μὲν ἐπεδείκνυτο καὶ μακροθυμίαν ἡγεμόνος ἀγαθοῦ, δόξαν δὲ καὶ χάριν οὐδεμίαν αἱ πράξεις ἔσχον, ἀλλὰ καὶ τὴν προϋπάρχουσαν ἐγγὺς ἦλθε δυσπραγῶν καὶ διαφερόμενος μάτην ἀποβαλεῖν. τῶν δ’ αἰτιῶν αὐτὸς οὐχὶ τὴν ἐλαχίστην εἰς τοῦτο παρέσχεν, οὐκ ὢν θεραπευτικὸς πλήθους στρατιωτικοῦ, καὶ πᾶν τὸ πρὸς ἡδονὴν τοῦ ἀρχομένου γινόμενον ἀρχῆς ἀτιμίαν καὶ κατάλυσιν ἡγούμενος· τὸ δὲ μέγιστον, οὐδὲ τοῖς δυνατοῖς καὶ ἰσοτίμοις εὐάρμοστος εἶναι πεφυκώς, ἀλλὰ πάντων καταφρονῶν καὶ μηδενὸς ἀξίους πρὸς αὑτὸν ἡγούμενος. ταῦτα γὰρ ὑπάρξαι Λουκούλλῳ κακὰ λέγουσιν ἐν πᾶσι τοῖς ἄλλοις ἀγαθοῖς· καὶ γὰρ μέγας καὶ καλὸς καὶ δεινὸς εἰπεῖν καὶ φρόνιμος ὁμαλῶς ἐν ἀγορᾷ καὶ στρατοπέδῳ δοκεῖ γενέσθαι.", "st": "Luc. 33.1"}, {"sp": "N", "t": "Σαλούστιος μὲν οὖν φησι χαλεπῶς διατεθῆναι τοὺς στρατιώτας πρὸς αὑτὸν εὐθὺς ἐν ἀρχῇ τοῦ πολέμου πρὸς Κυζίκῳ καὶ πάλιν πρὸς Ἀμισῷ, δύο χειμῶνας ἑξῆς ἐν χάρακι διαγαγεῖν ἀναγκασθέντας. ἠνίων δ’ αὐτοὺς καὶ οἱ λοιποὶ χειμῶνες, ἢ γὰρ ἐν τῇ πολεμίᾳ διεχείμαζον ἢ παρὰ τοῖς συμμάχοις ὕπαιθροι σκηνοῦντες, εἰς δὲ πόλιν Ἑλληνίδα καὶ φίλην οὐδ’ ἅπαξ εἰσῆλθε μετὰ στρατοπέδου Λούκουλλος, οὕτω δὲ διακειμένοις αὐτοῖς τὰς μεγίστας ἐνέδωκαν ἀπὸ τῆς Ῥώμης οἱ δημαγωγοὶ προφάσεις, φθόνῳ τοῦ Λουκούλλου κατηγοροῦντες ὡς ὑπὸ φιλαρχίας καὶ φιλοπλουτίας ἕλκοντος τὸν πόλεμον καὶ μονονοὺ κατέχοντος ἐν ταὐτῷ Κιλικίαν, Ἀσίαν, Βιθυνίαν, Παφλαγονίαν, Γαλατίαν, Πόντον, Ἀρμενίαν, τὰ μέχρι Φάσιδος, νυνὶ δὲ καὶ τὰ Τιγράνου βασίλεια πεπορθηκότος, ὥσπερ ἐκδῦσαι τοὺς βασιλεῖς, οὐ καταπολεμῆσαι πεμφθέντος. τοῦτο γὰρ εἰπεῖν φασιν ἕνα τῶν στρατηγῶν Λεύκιον Κόϊντον, ὑφ’ οὗ μάλιστα πεισθέντες ἐψηφίσαντο πέμπειν διαδόχους τῷ Λουκούλλῳ τῆς ἐπαρχίας, ἐψηφίσαντο δὲ καὶ τῶν ὑπ’ αὐτῷ στρατευομένων πολλοὺς ἀφεῖσθαι στρατείας.", "st": "Luc. 33.4"}, {"sp": "N", "t": "τούτοις δὲ τηλικούτοις οὖσι προσγίνεται τὸ μάλιστα Λουκούλλῳ διειργασμένον τὰς πράξεις, Πόπλιος Κλώδιος, ἀνὴρ ὑβριστὴς καὶ μεστὸς ὀλιγωρίας ἁπάσης καὶ θρασύτητος. ἦν δὲ τῆς Λουκούλλου γυναικὸς ἀδελφός, ἣν καὶ διαφθείρειν ἔσχεν αἰτίαν ἀκολαστοτάτην οὖσαν. τότε δὲ τῷ Λουκούλλῳ συστρατεύων οὐχ ὅσης αὑτὸν ἠξίου τιμῆς ἐτύγχανεν ἠξίου δὲ πρῶτος εἶναι, καὶ πολλῶν ἀπολειπόμενος διὰ τὸν τρόπον ὑποικούρει τὴν Φιμβριανὴν στρατιὰν καὶ παρώξυνε κατὰ τοῦ Λουκούλλου, λόγους χρηστοὺς εἰς οὐκ ἄκοντας οὐδ’ ἀήθεις τοῦ δημαγωγεῖσθαι διαδιδούς. οὗτοι γὰρ ἦσαν, οὓς καὶ πρότερον ἀνέπεισε Φιμβρίας ἀποκτείναντας τὸν ὕπατον Φλάκκον αὑτὸν ἑλέσθαι στρατηγόν. διὸ καὶ τὸν Κλώδιον ἡδέως ἐδέχοντο καὶ φιλοστρατιώτην προσηγόρευον, ἀγανακτεῖν προσποιούμενον ὑπὲρ αὐτῶν, εἰ πέρας οὐδὲν ἔσται πολέμων τοσούτων καὶ πόνων, ἀλλὰ παντὶ μὲν ἔθνει μαχόμενοι, πᾶσαν δὲ γῆν πλανώμενοι κατατρίψουσι τὸν βίον οὐδὲν ἄξιον ἐκ τηλικαύτης φερόμενοι στρατείας, ἀλλὰ τὰς Λουκούλλου παραπέμποντες ἁμάξας καὶ καμήλους ἐκπωμάτων χρυσῶν καὶ διαλίθων γεμούσας, οἱ δὲ Πομπηίου στρατιῶται δῆμος ὄντες ἤδη που μετὰ γυναικῶν καὶ τέκνων κάθηνται γῆν εὐδαίμονα καὶ πόλεις ἔχοντες, οὐ Μιθριδάτην καὶ Τιγράνην εἰς τὰς ἀοικήτους ἐμβαλόντες ἐρημίας, οὐδὲ τῆς Ἀσίας τὰ βασίλεια καταρρίψαντες, ἀλλὰ φυγάσιν ἀνθρώποις ἐν Ἰβηρίᾳ καὶ δραπέταις ἐν Ἰταλίᾳ πολεμήσαντες. τί οὖν, εἰ δεῖ μηδέποτε παύσασθαι στρατευομένους, οὐχὶ τοιούτῳ στρατηγῷ καὶ σώματα τὰ λοιπὰ καὶ ψυχὰς φυλάσσομεν, ᾧ κάλλιστος εἶναι δοκεῖ κόσμος ὁ τῶν στρατευομένων πλοῦτος;", "st": "Luc. 34.1"}, {"sp": "N", "t": "τοιαύταις αἰτίαις τὸ Λουκούλλου στράτευμα διαφθαρέν οὔτ’ ἐπὶ Τιγράνην ἠκολούθησεν οὔτ’ ἐπὶ Μιθριδάτην αὖθις ἐξ Ἀρμενίας εἰς Πόντον ἐμβαλόντα καὶ τὴν ἀρχὴν ἀναλαμβάνοντα, πρόφασιν δὲ τὸν χειμῶνα ποιούμενοι περὶ τὴν Γορδυηνὴν διέτριβον, ὅσον οὔπω Πομπήϊον ἤ τιν’ ἄλλον τῶν ἡγεμόνων Λουκούλλῳ διάδοχον ἀφίξεσθαι προσδοκῶντες.", "st": "Luc. 34.5"}, {"sp": "N", "t": "ἐπεὶ δὲ Μιθριδάτης ἤγγελτο Φάβιον νενικηκὼς ἐπὶ Σωρνάτιον καὶ Τριάριον βαδίζειν, αἰσχυνθέντες εἵποντο τῷ Λουκούλλῳ. Τριάριος δ’ ὡς ἕτοιμον ἁρπάσαι τὸ νίκημα, πρὶν ἐπελθεῖν Λούκουλλον ἐγγὺς ὄντα, φιλοτιμούμενος ἡττᾶται μάχῃ μεγάλῃ, λέγονται γὰρ ὑπὲρ ἑπτακισχιλίους Ῥωμαίων ἀποθανεῖν, ἐν οἷς ἑκατόνταρχοι μὲν ἑκατὸν πεντήκοντα, χιλίαρχοι δ’ εἴκοσι καὶ τέσσαρες· τὸ δὲ στρατόπεδον εἷλε Μιθριδάτης. ἐπελθὼν δὲ Λούκουλλος ὀλίγαις ὕστερον ἡμέραις Τριάριον μὲν ὑπὸ τῶν στρατιωτῶν ζητούμενον πρὸς ὀργὴν ἐξέκλεψε, Μιθριδάτου δὲ μὴ θέλοντος μάχεσθαι, ἀλλὰ Τιγράνην περιμένοντος ἤδη καταβαίνοντα μετὰ πολλῆς δυνάμεως, ἔγνω πρὶν ἀμφοτέρους συνελθεῖν πάλιν ἀπαντῆσαι καὶ διαγωνίσασθαι πρὸς τὸν Τιγράνην. πορευομένῳ δ’ αὐτῷ καθ’ ὁδὸν οἱ Φιμβριανοὶ στασιάσαντες ἀπέλιπον τὰς τάξεις, ὡς ἀφειμένοι δόγματι τῆς στρατείας καὶ μηκέτι τῷ Λουκούλλῳ προσῆκον ἄρχειν, ἑτέροις ἀποδεδειγμένων τῶν ἐπαρχιῶν. οὐδὲν οὖν ἐστιν ὅ τι τῶν παρ’ ἀξίαν ὁ Λούκουλλος οὐχ ὑπέμεινεν, ἀντιβολῶν καθ’ ἕνα καὶ κατὰ σκηνὰς περιιὼν ταπεινὸς καὶ δεδακρυμένος, ἔστι δ’ ὧν καὶ χειρὸς ἁπτόμενος. οἱ δ’ ἀπετρίβοντο τὰς δεξιώσεις καὶ κενὰ προσερρίπτουν βαλάντια, καὶ μόνον μάχεσθαι τοῖς πολεμίοις ἐκέλευον, ἀφ’ ὧν μόνος ἠπίστατο πλουτεῖν. οὐ μὴν ἀλλὰ τῶν ἄλλων στρατιωτῶν δεομένων ἐκβιασθέντες οἱ Φιμβριανοὶ συνέθεντο παραμεῖναι τὸ θέρος· ἐὰν δὲ μηδεὶς ἐν τῷ χρόνῳ τούτῳ κατίῃ πρὸς αὐτοὺς ἀγωνιούμενος, ἀπηλλάχθαι. ταῦτ’ ἔδει στέργειν ἐξ ἀνάγκης τὸν Λούκουλλον, ἢ προέσθαι τοῖς βαρβάροις τὴν χώραν ἀπολειφθέντα. συνεῖχεν οὖν αὐτοὺς οὐκέτι προσβιαζόμενος οὐδὲ προάγων πρὸς μάχην, ἀλλ’ εἰ παραμένοιεν ἀγαπῶν, καὶ περιορῶν πορθουμένην ὑπὸ τοῦ Τιγράνου τὴν Καππαδοκίαν καὶ πάλιν ὑβρίζοντα Μιθριδάτην, ὃν αὐτὸς ἐπεστάλκει τῇ συγκλήτῳ γράφων καταπεπολεμῆσθαι· καὶ οἱ πρέσβεις παρῆσαν αὐτῷ πρὸς τὴν διάθεσιν τῶν ἐν Πόντῳ πραγμάτων, ὡς δὴ βεβαίως ἐχομένων. καὶ δὴ παρόντες ἑώρων οὐδ’ αὑτοῦ κύριον, ἀλλὰ παροινούμενον καὶ προπηλακιζόμενον ὑπὸ τῶν στρατιωτῶν, οἷς γε τοσοῦτο περιῆν τῆς εἰς τὸν στρατηγὸν ἀσελγείας, ὥστε τοῦ θέρους λήγοντος ἐνδύντες τὰ ὅπλα καὶ σπασάμενοι τὰς μαχαίρας προεκαλοῦντο τοὺς μηδαμοῦ παρόντας, ἀλλ’ ἀπηρκότας ἤδη πολεμίους, ἀλαλάξαντες δὲ καὶ σκιαμαχήσαντες ἀπεχώρησαν ἐκ τοῦ χάρακος, ἐπιμαρτυράμενοι πεπληρῶσθαι τὸν χρόνον, ὃν ὡμολόγησαν τῷ Λουκούλλῳ παραμενεῖν.", "st": "Luc. 35.1"}, {"sp": "N", "t": "τοὺς δ’ ἄλλους ἐκάλει διὰ γραμμάτων Πομπήιος· ἤδη γὰρ ἀποδέδεικτο τοῦ πρὸς Μιθριδάτην καὶ Τιγράνην πολέμου στρατηγὸς χάριτι τοῦ δήμου καὶ κολακείᾳ τῶν δημαγωγῶν, ἐπεὶ τῇ γε βουλῇ καὶ τοῖς ἀρίστοις ἄδικα πάσχειν ἐδόκει Λούκουλλος οὐ πολέμου διαδόχους, ἀλλὰ θριάμβου λαμβάνων, οὐδὲ τῆς στρατηγίας ἀναγκαζόμενος, ἀλλὰ τῶν ἐπάθλων τῆς στρατηγίας ἐξίστασθαι καὶ παραχωρεῖν ἑτέροις.", "st": "Luc. 35.7"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον ἐφάνη τὸ γινόμενον τοῖς ἐκεῖ παροῦσι νεμεσητόν. οὔτε γὰρ τιμῆς ὁ Λούκουλλος οὔτε τιμωρίας τῶν ἐν πολέμῳ κύριος ὑπῆρχεν, οὐδ’ εἴα τινὰ Πομπήιος βαδίζειν πρὸς αὐτὸν οὐδὲ προσέχειν οἷς ἐκεῖνος ἔγραφε καὶ διένεμε μετὰ τῶν δέκα πρέσβεων, ἀλλ’ ἐκώλυεν ἐκτιθεὶς διαγράμματα καὶ φοβερὸς παρὼν ἀπὸ μείζονος δυνάμεως. ὅμως δὲ ἔδοξε τοῖς φίλοις συναγαγεῖν αὐτούς καὶ συνῆλθον ἐν κώμῃ τινὶ τῆς Γαλατίας καὶ προσεῖπον ἀλλήλους φιλοφρόνως καὶ συνήσθησαν ἐπὶ τοῖς κατωρθωμένοις ἑκατέρῳ, πρεσβύτερος μὲν ὢν ὁ Λούκουλλος, ἀξίωμα δ’ ἦν τὸ Πομπηΐου μεῖζον ἀπὸ πλειόνων στρατηγιῶν καὶ δυεῖν θριάμβων. ῥάβδοι δ’ ἀμφοτέρων προηγοῦντο δαφνηφόροι διὰ τὰς νίκας. καὶ τοῦ γε Πομπηίου μακρὰν ὁδὸν διὰ τόπων ἀνύδρων καὶ αὐχμηρῶν ὁδεύσαντος τὰς δάφνας ξηρὰς περικειμένας ταῖς ῥάβδοις ἰδόντες οἱ τοῦ Λουκούλλον ῥαβδοφόροι φιλοφρονούμενοι τοῖς ἐκείνου μετέδωκαν ἐκ τῶν ἰδίων, προσφάτους καὶ θαλερὰς ἔχοντες, καὶ τὸ γινόμενον εἰς οἰωνὸν ἐτίθεντο χρηστὸν οἱ Πομπηίου φίλοι· τῷ γὰρ ὄντι τὴν ἐκείνου στρατηγίαν αἱ τούτου πράξεις ἐκόσμησαν. ἐκ δὲ τῶν λόγων πρὸς οὐδὲν ἐπιεικὲς συνέβησαν, ἀλλ’ ἔτι μᾶλλον ἀλλοτριωθέντες πρὸς ἀλλήλους ἀπῆλθον καὶ τὰς ὑπὸ τοῦ Λουκούλλου γενομένας διατάξεις ἠκύρωσεν ὁ Πομπήιος, στρατιώτας δὲ τοὺς ἄλλους ἀπαγαγών μόνους αὐτῷ χιλίους ἑξακοσίους ἀπέλιπε συνθριαμβεύσοντας, οὐδὲ τούτους μάλα προθύμως ἑπομένους. οὕτω τις ἦν ἀφυὴς ἢ δυστυχὴς ὁ Λούκουλλος πρὸς τὸ πάντων ἐν ἡγεμονία πρῶτον καὶ μέγιστον ὡς, εἰ τοῦτο μετὰ τῶν ἄλλων ὑπῆρξεν αὐτῷ, τηλικούτων ὄντων καὶ τοσούτων, μετ’ ἀνδρείας, ἐπιμελείας, συνέσεως, δικαιοσύνης, οὐκ ἂν εἶχεν ἡ Ῥωμαίων ἡγεμονία τὸν Εὐφράτην τῆς Ἀσίας ὅρον, ἀλλὰ τὰ ἔσχατα καὶ τὴν Ὑρκανίαν θάλατταν, τῶν μὲν ἄλλων ἐθνῶν Τιγράνῃ προηττημένων, τῆς δὲ Πάρθων δυνάμεως οὐχ ὅση κατὰ Κράσσον ἐξεφάνη τοσαύτης καὶ κατὰ Λούκουλλον οὔσης οὐδ’ ὁμοίως συνεστώσης, ἀλλ’ ὑπ ἐμφυλίων καὶ προσοίκων πολέμων οὐδ’ Ἀρμενίους ὑβρίζοντας ἐρρωμένης ἀμύνεσθαι.", "st": "Luc. 36.1"}, {"sp": "N", "t": "νῦν δέ μοι δοκεῖ Λούκουλλος ὧν ὠφέλησε δι’ αὑτοῦ τὴν πατρίδα βλάψαι μείζονα δι’ ἑτέρων· τὰ γὰρ ἐν Ἀρμενίᾳ τρόπαια Πάρθων πλησίον ἑστῶτα καὶ Τιγρανόκερτα καὶ Νίσιβις καὶ πλοῦτος ἐκ τούτων πολὺς εἰς Ῥώμην κομισθεὶς καὶ τὸ Τιγράνου διάδημα πομπευθὲν αἰχμάλωτον ἐπῆρε Κράσσον ἐπὶ τὴν Ἀσίαν, ὡς λάφυρα καὶ λείαν τοὺς βαρβάρους, ἄλλο δ’ οὐδὲν ὄντας. ταχὺ μέντοι τοῖς Πάρθων τοξεύμασιν ἐντυχών ἀπέδειξε τὸν Λούκουλλον οὐκ ἀφροσύνῃ καὶ μαλακίᾳ τῶν πολεμίων, αὑτοῦ δὲ τόλμῃ καὶ δεινότητι περιγενόμενον. ἀλλὰ ταῦτα μὲν ὕστερον.", "st": "Luc. 36.7"}, {"sp": "N", "t": "ὁ δὲ Λούκουλλος ἀναβὰς εἰς Ῥώμην πρῶτον μὲν κατέλαβε τὸν ἀδελφὸν Μᾶρκον ὑπὸ Γαΐου Μεμμίου κατηγορούμενον ἐφ’ οἷς ἔπραξε ταμιεύων Σύλλα προστάξαντος. ἐκείνου δ’ ἀποφυγόντος ἐπὶ τοῦτον αὐτὸν ὁ Μέμμιος μεταβαλόμενος παρώξυνε τὸν δῆμον, καὶ ὡς πολλὰ νενοσφισμένῳ καὶ μηκύναντι τὸν πόλεμον ἔπεισεν αὐτῷ μὴ δοῦναι θρίαμβον. ἐλθόντος δ’ εἰς ἀγῶνα τοῦ Λουκούλλου μέγαν οἱ πρῶτοι καὶ δυνατώτατοι καταμίξαντες ἑαυτοὺς ταῖς φυλαῖς πολλῇ δεήσει καὶ σπουδῇ μόλις ἔπεισαν τὸν δῆμον ἐπιτρέψαι θριαμβεῦσαι, οὐχ, ὥσπερ ἔνιοι, μήκει τε πομπῆς καὶ πλήθει τῶν κομιζομένων ἐκπληκτικὸν καὶ ὀχλώδη θρίαμβον, ἀλλὰ τοῖς μὲν ὅπλοις τῶν πολεμίων οὖσι παμπόλλοις καὶ τοῖς βασιλικοῖς μηχανήμασι τὸν Φλαμίνειον ἱππόδρομον διεκόσμησε· καὶ θέα τις ἦν αὐτὴ καθ’ ἑαυτὴν οὐκ εὐκαταφρόνητος· ἐν δὲ τῇ πομπῇ τῶν τε καταφράκτων ἱππέων ὀλίγοι καὶ τῶν δρεπανηφόρων ἁρμάτων δέκα παρῆλθον, ἑξήκοντα δὲ φίλοι καὶ στρατηγοὶ τῶν βασιλικῶν, μακραὶ δὲ χαλκέμβολοι νῆες ἑκατὸν καὶ δέκα ἅμα παρεκομίσθησαν, αὐτοῦ τε Μιθριδάτου χρύσεος ἑξάπους κολοσσός, καὶ θυρεός τις διάλιθος, καὶ φορήματα εἴκοσι μὲν ἀργυρῶν σκευῶν, χρυσῶν δ’ ἐκπωμάτων καὶ ὅπλων καὶ νομίσματος δύο καὶ τριάκοντα. ταῦτα μὲν οὖν ἄνδρες παρεκόμιζον ἡμίονοι δ’ ὀκτὼ κλίνας χρυσᾶς ἔφερον, ἓξ δὲ καὶ πεντήκοντα κεχωνευμένον ἀργύριον, ἄλλοι δ’ ἑκατὸν ἑπτὰ νομίσματος ἀργυροῦ, μικρῷ τινι δεούσας ἑβδομήκοντα καὶ διακοσίας μυριάδας, ἐν δὲ δέλτοις ἀναγραφαὶ τῶν ἤδη δεδομένων χρημάτων ὑπ’ αὐτοῦ Πομπηΐῳ πρὸς τὸν πειρατικὸν πόλεμον καὶ τοῖς ἐπὶ τοῦ δημοσίου ταμείου, καὶ χωρὶς ὅτι στρατιώτης ἕκαστος ἐνακοσίας καὶ πεντήκοντα δραχμὰς ἔλαβεν. ἐπὶ τούτοις τήν τε πόλιν εἱστίασε λαμπρῶς καὶ τὰς περιοικίδας κώμας, ἃς οὐΐκους καλοῦσι.", "st": "Luc. 37.1"}, {"sp": "N", "t": "τῆς δὲ Κλωδίας ἀπηλλαγμένος, οὔσης ἀσελγοῦς καὶ πονηρᾶς, Σερουϊλίαν ἔγημεν, ἀδελφὴν Κάτωνος, οὐδὲ τοῦτον εὐτυχῆ γάμον. ἓν γὰρ οὐ προσῆν αὐτῷ τῶν Κλωδίας κακῶν μόνον, ἡ τῶν ἀδελφῶν διαβολή· τἆλλα δὲ βδελυρὰν ὁμοίως οὖσαν καὶ ἀκόλαστον ἠναγκάζετο φέρειν αἰδούμενος Κάτωνα, τέλος δὲ ἀπεῖπεν.", "st": "Luc. 38.1"}, {"sp": "N", "t": "ἐλπίδας δὲ θαυμαστὰς τῇ βουλῇ παρασχών, ὡς ἐχούσῃ τὸν ἄνδρα τοῦτον ἀντίταγμα πρὸς τὴν τοῦ Πομπηίου τυραννίδα καὶ τῆς ἀριστοκρατίας πρόμαχον ἀπὸ δόξης καὶ δυνάμεως ὁρμώμενον μεγάλης, ἐγκατέλιπε καὶ προήκατο τὴν πολιτείαν, εἴτε δυσκάθεκτον ἤδη καὶ νοσοῦσαν ὁρῶν εἴθ’, ὥς φασιν ἔνιοι, μεστὸς ὢν δόξης καὶ πρὸς τὸ ῥᾷστον ἀναπίπτων τοῦ βίου καὶ μαλακώτατον ἐκ πολλῶν ἀγώνων καὶ πόνων οὐκ εὐτυχέστατον τέλος λαβόντων. οἱ μὲν γὰρ ἐπαινοῦσιν αὐτοῦ τὴν τοσαύτην μεταβολήν, τὸ Μαρίου πάθος μὴ παθόντος, ὃς ἐπὶ ταῖς Κιμβρικαῖς νίκαις καὶ τοῖς καλοῖς καὶ μεγάλοις ἐκείνοις κατορθώμασιν οὐκ ἠθέλησεν αὑτὸν ἀνεῖναι τιμῇ τοσαύτῃ ζηλωτόν, ἀλλ’ ἀπληστίᾳ δόξης καὶ ἀρχῆς νέοις ἀνδράσι γέρων ἀντιπολιτευόμενος εἰς ἔργα δεινὰ καὶ πάθη δεινότερα τῶν ἔργων ἐξώκειλε· βέλτιον δ’ ἂν καὶ Κικέρωνα γηρᾶσαι μετὰ Κατιλίναν ὑποστειλάμενον καὶ Σκηπίωνα Καρχηδόνι προσθέντα Νομαντίαν, εἶτα παυσάμενον· εἶναι γάρ τινα καὶ πολιτικῆς περιόδου κατάλυσιν τῶν γὰρ ἀθλητικῶν ἀγώνων τοὺς πολιτικοὺς οὐδὲν ἧττον ἀκμῆς καὶ ὥρας ἐπιλιπούσης ἐλέγχεσθαι. οἱ δὲ περὶ τὸν Κράσσον καὶ Πομπήϊον ἐχλευάζον τὸν Λούκουλλον εἰς ἡδονὴν ἀφεικότα καὶ πολυτέλειαν αὑτόν, ὥσπερ οὐ τοῦ τρυφᾶν μᾶλλον τοῖς τηλικούτοις παρ’ ἡλικίαν ὄντος ἢ τοῦ πολιτεύεσθαι καὶ στρατηγεῖν.", "st": "Luc. 38.2"}, {"sp": "N", "t": "ἔστι δ’ οὖν τοῦ Λουκούλλου βίου, καθάπερ ἀρχαίας κωμῳδίας, ἀναγνῶναι τὰ μὲν πρῶτα πολιτείας καὶ στρατηγίας, τὰ δ’ ὕστερα πότους καὶ δεῖπνα καὶ μονονουχὶ κώμους καὶ λαμπάδας καὶ παιδιὰν ἅπασαν. εἰς παιδιὰν γὰρ ἔγωγε τίθεμαι καὶ οἰκοδομὰς πολυτελεῖς καὶ κατασκευὰς περιπάτων καὶ λουτρῶν καὶ ἔτι μᾶλλον γραφὰς καὶ ἀνδριάντας καὶ τὴν περὶ ταύτας τὰς τέχνας σπουδήν, ἃς ἐκεῖνος συνῆγε μεγάλοις ἀναλώμασιν, εἰς ταῦτα τῷ πλούτῳ ῥύδην καταχρώμενος, ὃν ἠθροίκει πολὺν καὶ λαμπρὸν ἀπὸ τῶν στρατειῶν, ὅπου καὶ νῦν, ἐπίδοσιν τοιαύτην τῆς τρυφῆς ἐχούσης, οἱ Λουκουλλιανοὶ κῆποι τῶν βασιλικῶν ἐν τοῖς πολυτελεστάτοις ἀριθμοῦνται. τὰ δ’ ἐν τοῖς παραλίοις καὶ περὶ Νέαν πόλιν ἔργα, λόφους ἀνακρεμαννύντος αὐτὸν μεγάλοις ὀρύγμασι καὶ τροχοὺς θαλάσσης καὶ διαδρομὰς ἰχθυοτρόφους τοῖς οἰκητηρίοις περιελίσσοντος καὶ διαίτας ἐναλίους κτίζοντος, ὁ Στωικὸς Τουβέρων θεασάμενος Ξέρξην αὐτὸν ἐκ τηβέννου προσηγόρευσεν. ἦσαν δ’ αὐτῷ περὶ Τοῦσκλον ἐγχώριοι δίαιται καὶ κατασκοπαὶ περιόπτων καὶ κατασκευαὶ ἀναπεπταμένων ἀνδρώνων καὶ περιπάτων, ἐν αἷς ὁ Πομπήιος γενόμενος ἐμέμφετο τὸν Λούκουλλον, ὅτι πρὸς θέρος ἄριστα διαθεὶς τὴν ἔπαυλιν ἀοίκητον ἐν χειμῶνι πεποίηκε, γελάσας οὖν ἐκεῖνος εἶτα, ἔφη, σοὶ δοκῶ ἐλάττονα τῶν γεράνων νοῦν ἔχειν καὶ τῶν πελαργῶν, ὥστε ταῖς ὥραις μὴ συμμεταβάλλειν τὰς διαίτας; στρατηγοῦ δέ ποτε φιλοτιμουμένου περὶ θέας καὶ χορῷ τινι κόσμον αἰτουμένου πορφυρᾶς χλαμύδας ἀπεκρίνατο σκεψάμενος, ἂν ἔχῃ, δώσειν, εἶτα μεθ’ ἡμέραν ἠρώτησεν αὐτὸν, ὁπόσων δέοιτο. τοῦ δὲ ἑκατὸν ἀρκέσειν φήσαντος ἐκέλευσε λαβεῖν δὶς τοσαύτας εἰς ὃ καὶ Φλάκκος ὁ ποιητὴς ἐπιπεφώνηκεν, ὡς οὐ νομίζει πλοῦτον, οὗ μὴ τὰ παρορώμενα καὶ λανθάνοντα πλείονα τῶν φαινομένων ἐστί.", "st": "Luc. 39.1"}, {"sp": "N", "t": "Νεόπλουτα δ’ ἦν τοῦ Λουκούλλου τὰ δεῖπνα τὰ καθ’ ἡμέραν, οὐ μόνον στρωμναῖς ἁλουργέσι καὶ διαλίθοις ἐκπώμασι καὶ χοροῖς καὶ ἀκροάμασιν ἐπεισοδίοις, ἀλλ’ ὄψων τε παντοδαπῶν καὶ πεμμάτων περιττῶς διαπεπονημένων παρασκευαῖς ζηλωτὸν ἀνελευθέροις ποιοῦντος ἑαυτόν. ὁ γοῦν Πομπήιος εὐδοκίμησε νοσῶν· τοῦ γὰρ ἰατροῦ κίχλην αὐτὸν λαβεῖν κελεύσαντος, τῶν δ’ οἰκετῶν οὐκ ἂν εὑρεῖν ἀλλαχόθι φαμένων θέρους ὥρᾳ κίχλην ἢ παρὰ Λουκούλλῳ σιτευομένην, οὐκ εἴασε λαβεῖν ἐκεῖθεν, ἀλλ’ εἰπὼν πρὸς τὸν ἰατρόν οὐκοῦν, εἰ μὴ Λούκουλλος ἐτρύφα, Πομπήιος οὐκ ἂν ἔζησεν; ἄλλο τι παρασκευάσαι τῶν εὐπορίστων ἐκέλευσε. Κάτων δ’ ἦν αὐτῷ φίλος καὶ οἰκεῖος, οὕτω δὲ τὸν βίον αὐτοῦ καὶ τὴν δίαιταν ἐδυσχέραινεν, ὥστε, νέου τινὸς ἐν τῇ βουλῇ λόγον ἐπαχθῆ καὶ μακρὸν ἀκαίρως ὑπὲρ εὐτελείας καὶ σωφροσύνης διελθόντος, ἐπαναστὰς ὁ Κάτων οὐ παύσῃ, ἔφη, σὺ πλουτῶν μὲν ὡς Κράσσος, ζῶν δ’ ὡς Λούκουλλος, λέγων δὲ ὡς Κάτων; ἔνιοι δὲ τοῦτο ῥηθῆναι μὲν οὕτως, ὑπὸ Κάτωνος δὲ οὐ λέγουσιν.", "st": "Luc. 40.1"}, {"sp": "N", "t": "ὁ μέντοι Λούκουλλος οὐχ ἡδόμενος μόνον, ἀλλὰ καὶ σεμνυνόμενος τῷ βίῳ τούτῳ δῆλος ἦν ἐκ τῶν ἀπομνημονευομένων, λέγεται γὰρ Ἕλληνας ἀνθρώπους ἀναβάντας εἰς Ῥώμην ἑστιᾶν ἐπὶ πολλὰς ἡμέρας, τοὺς δ’ ὄντως Ἑλληνικόν τι παθόντας, αἰσχύνεσθαι καὶ διωθεῖσθαι τὴν κλῆσιν, ὡς δι’ αὐτοὺς καθ’ ἡμέραν τοσούτων ἀναλισκομένων· τὸν οὖν Λούκουλλον εἰπεῖν μειδιάσαντα πρὸς αὐτούς· γίνεται μέν τι τούτων καὶ δι’ ὑμᾶς, ὦ ἄνδρες Ἕλληνες· τὰ μέντοι πλεῖστα γίνεται διὰ Λούκουλλον. ἐπεὶ δὲ μόνου δειπνοῦντος αὐτοῦ μία τράπεζα καὶ μέτριον παρεσκευάσθη δεῖπνον, ἠγανάκτει καλέσας τὸν ἐπὶ τούτῳ τεταγμένον οἰκέτην. τοῦ δὲ φήσαντος, ὡς οὐκ ᾤετο μηδενὸς κεκλημένου πολυτελοῦς τινος αὐτὸν δεήσεσθαι τί λέγεις; εἶπεν, οὐκ ᾔδεις, ὅτι σήμερον παρὰ Λουκούλλῳ δειπνεῖ Λούκουλλος; ὄντος δὲ περὶ τούτου, ὡς εἰκὸς, ἐν τῇ πόλει λόγου πολλοῦ, προσῆλθον αὐτῷ κατ’ ἀγορὰν σχολὴν ἄγοντι Κικέρων καὶ Πομπήιος, ὁ μέν ἐν τοῖς μάλιστα φίλος ὢν καὶ συνήθης, Πομπηΐῳ δ’ ἦν μέν ἐκ τῆς στρατηγίας διαφορὰ πρὸς αὐτόν, εἰώθεισαν δὲ χρῆσθαι καὶ διαλέγεσθαι πολλάκις ἐπιεικῶς ἀλλήλοις. ἀσπασάμενος οὖν ὁ Κικέρων αὐτὸν ἠρώτησεν, ὅπως ἔχει πρὸς ἔντευξιν τοῦ δὲ φήσαντος, ὡς ἄριστα, καὶ παρακαλοῦντος ἐντυγχάνειν ἡμεῖς, ἔφη, βουλόμεθα δειπνῆσαι παρά σοὶ τήμερον οὕτως, ὅπως ἐστί σοι παρεσκευασμένα θρυπτομένου δὲ τοῦ Λουκούλλου καὶ μεταλαβεῖν ἡμέραν ἀξιοῦντος οὐκ ἔφασαν ἐπιτρέψειν, οὐδ’ εἴων διαλέγεσθαι τοῖς οἰκέταις, ἵνα μή τι πλέον κελεύσῃ γενέσθαι τῶν αὐτῷ γινομένων, πλὴν τοσοῦτο μόνον αἰτουμένῳ συνεχώρησαν εἰπεῖν πρὸς ἕνα τῶν οἰκετῶν ἐναντίον ἐκείνων, ὅτι τήμερον ἐν τῷ Ἀπόλλωνι δειπνήσοι· τοῦτο γάρ τις εἶχε τῶν πολυτελῶν οἴκων ὄνομα· καὶ τοῦτο σεσοφισμένος ἐλελήθει τοὺς ἄνδρας, ἑκάστῳ γὰρ, ὡς ἔοικε, δειπνητηρίῳ τεταγμένον ἦν τίμημα δείπνου, καὶ χορηγίαν ἰδίαν καὶ παρασκευὴν ἕκαστον εἶχεν, ὥστε τοὺς δούλους ἀκούσαντας, ὅπου βούλεται δειπνεῖν, εἰδέναι, πόσον δαπάνημα καὶ ποῖόν τι κόσμῳ καὶ διαθέσει γενέσθαι δεῖ τὸ δεῖπνον εἰώθει δὲ δειπνεῖν ἐν τῷ Ἀπόλλωνι πέντε μυριάδων· καὶ τότε τοσούτου τελεσθέντος ἐξέπληξε τοὺς περὶ τὸν Πομπήϊον ἐν τῷ μεγέθει τῆς δαπάνης τὸ τάχος τῆς παρασκευῆς, εἰς ταῦτα μέν οὖν ὑβριστικῶς ἐχρῆτο τῷ πλούτῳ καθάπερ ὄντως αἰχμαλώτῳ καὶ βαρβάρῳ.", "st": "Luc. 41.1"}, {"sp": "N", "t": "σπουδῆς δ’ ἄξια καὶ λόγου τὰ περὶ τὴν τῶν βιβλίων κατασκευήν, καὶ γὰρ πολλὰ καὶ γεγραμμένα καλῶς συνῆγεν, ἥ τε χρῆσις ἦν φιλοτιμοτέρα τῆς κτήσεως, ἀνειμένων πᾶσι τῶν βιβλιοθηκῶν, καὶ τῶν περὶ αὐτὰς περιπάτων καὶ σχολαστηρίων ἀκωλύτως ὑποδεχομένων τοὺς Ἕλληνας ὥσπερ εἰς Μουσῶν τι καταγώγιον ἐκεῖσε φοιτῶντας καὶ συνδιημερεύοντας ἀλλήλοις, ἀπὸ τῶν ἄλλων χρειῶν ἀσμένως ἀποτρέχοντας. πολλάκις δὲ καὶ συνεσχόλαζεν αὐτὸς ἐμβάλλων εἰς τοὺς περιπάτους τοῖς φιλολόγοις καὶ τοῖς πολιτικοῖς συνέπραττεν ὅτου δέοιντο· καὶ ὅλως ἑστία καὶ πρυτανεῖον Ἑλληνικὸν ὁ οἶκος ἦν αὐτοῦ τοῖς ἀφικνουμένοις εἰς Ῥώμην. φιλοσοφίαν δὲ πᾶσαν μὲν ἠσπάζετο καὶ πρὸς πᾶσαν εὐμενὴς ἦν καὶ οἰκεῖος, ἴδιον δὲ τῆς Ἀκαδημείας ἐξ ἀρχῆς ἔρωτα καὶ ζῆλον ἔσχεν, οὐ τῆς νέας λεγομένης, καίπερ ἀνθούσης τότε τοῖς Καρνεάδου λόγοις διὰ Φίλωνος, ἀλλὰ τῆς παλαιᾶς, πιθανὸν ἄνδρα καὶ δεινὸν εἰπεῖν τότε προστάτην ἐχούσης τὸν Ἀσκαλωνίτην Ἀντίοχον, ὃν πάσῃ σπουδῇ ποιησάμενος φίλον ὁ Λούκουλλος καὶ συμβιωτὴν ἀντέταττε τοῖς Φίλωνος ἀκροαταῖς, ὧν καὶ Κικέρων ἦν. καὶ σύγγραμμά γε πάγκαλον ἐποίησεν εἰς τὴν αἵρεσιν, ἐν ᾧ τὸν ὑπὲρ τῆς καταλήψεως λόγον Λουκούλλῳ περιτέθεικεν, αὑτῷ δὲ τὸν ἐναντίον. Λούκουλλος δ’ ἀναγέγραπται τὸ βιβλίον.", "st": "Luc. 42.1"}, {"sp": "N", "t": "ἦσαν δ’, ὥσπερ εἴρηται, φίλοι σφόδρα καὶ κοινωνοὶ τῆς ἐν πολιτείᾳ προαιρέσεως· οὐδὲ γὰρ αὖ πάμπαν ἀπηλλάχει τῆς πολιτείας ἑαυτὸν ὁ Λούκουλλος, ἀλλὰ τὴν ὑπὲρ τοῦ μέγιστος εἶναι καὶ πλεῖστον δύνασθαι φιλοτιμίαν καὶ ἅμιλλαν, ὡς οὔτε ἀκίνδυνον οὔτ’ ἀνύβριστον οὖσαν, εὐθὺς ἀφῆκε Κράσσῳ καὶ Κάτωνι· τούτους γὰρ οἱ τὴν Πομπηίου δύναμιν ὑφορώμενοι προεβάλλοντο τῆς βουλῆς, ἀπολεγομένου τοῦ Λουκούλλου τὰ πρωτεῖα· κατέβαινε δ’ εἰς τὴν ἀγορὰν διὰ τοὺς φίλους, εἰς δὲ τὴν σύγκλητον, εἰ Πομπηΐου τινὰ δέοι σπουδὴν ἢ φιλοτιμίαν ἐπηρεάσαι. καὶ τάς τε διατάξεις, ἃς ἐκεῖνος ἐποιήσατο τῶν βασιλέων κρατήσας, ἐξέκρουσε, καὶ νέμησίν τινα τοῖς στρατιώταις αὐτοῦ γράφοντος ἐκώλυσε δοθῆναι συμπράττοντος Κάτωνος, ὥστε Πομπήϊον εἰς τὴν Κράσσου καὶ Καίσαρος φιλίαν, μᾶλλον δὲ συνωμοσίαν, καταφυγεῖν καὶ πληρώσαντα τὴν πόλιν ὅπλων καὶ στρατιωτῶν βίᾳ κυρῶσαι τὰ δόγματα, τοὺς περὶ τὸν Κάτωνα καὶ Λούκουλλον ἐκβαλόντα τῆς ἀγορᾶς.", "st": "Luc. 42.5"}, {"sp": "N", "t": "ἀγανακτούντων δὲ τῶν βελτίστων ἐπὶ τοῖς γινομένοις προῆγον οἱ Πομπηιανοὶ Βέττιόν τινα, συνειληφέναι λέγοντες ἐπιβουλεύοντα Πομπηίῳ. κἀκεῖνος ἀνακρινόμενος ἐν μὲν τῇ συγκλήτῳ κατηγόρησεν ἑτέρων τινῶν, ἐν δὲ τῷ δήμῳ Λούκουλλον ὠνόμασεν, ὡς ὑπ’ ἐκείνου παρεσκευασμένος ἀποκτεῖναι Πομπήιον. οὐδεὶς δὲ τῷ λόγῳ προσέσχεν, ἀλλὰ καὶ παραυτίκα δῆλος ἦν ὁ ἄνθρωπος ἐπὶ συκοφαντίᾳ καὶ διαβολῇ προηγμένος ὑπ’ αὐτῶν, καὶ μᾶλλον ἐφωράθη τὸ πρᾶγμα μετ’ ὀλίγας ἡμέρας ῥιφθέντος ἐκ τῆς εἱρκτῆς νεκροῦ, λεγομένου μὲν αὐτομάτως τεθνάναι, σημεῖα δ’ ἀγχόνης καὶ πληγῶν ἔχοντος· ἐδόκει γὰρ ὑπ’ αὐτῶν ἀνῃρῆσθαι τῶν παρεσκευακότων.", "st": "Luc. 42.7"}, {"sp": "N", "t": "ταῦτα δὴ καὶ μᾶλλον ἀπῆγε τῆς πολιτείας τὸν Λούκουλλον. ἐπεὶ δὲ Κικέρων ἐξέπεσε τῆς πόλεως καὶ Κάτων εἰς Κύπρον ἀπεστάλη, παντάπασιν ἐξελύθη. καὶ πρό γε τῆς τελευτῆς λέγεται νοσῆσαι τὴν διάνοιαν αὐτῷ κατὰ μικρὸν ἀπομαραινομένην. Νέπως δὲ Κορνήλιος οὐχ ὑπό γήρως φησὶν οὐδὲ νόσου παραλλάξαι τὸν Λούκουλλον, ἀλλὰ φαρμάκοις ὑπό τινος τῶν ἀπελευθέρων Καλλισθένους διαφθαρέντα· τὰ δὲ φάρμακα δοθῆναι μὲν, ὡς ἀγαπῷτο μᾶλλον ὁ Καλλισθένης ὑπ’ αὐτοῦ, τοιαύτην ἔχειν δοκοῦντα τὴν δύναμιν, ἐκστῆσαι δὲ καὶ κατακλύσαι τὸν λογισμόν, ὥστ’ ἔτι ζῶντος αὐτοῦ τὴν οὐσίαν διοικεῖν τὸν ἀδελφόν· οὐ μὴν ἀλλ’ ὡς ἀπέθανε, καθάπερ ἂν ἐν ἀκμῇ τῆς στρατηγίας καὶ τῆς πολιτείας αὐτοῦ τελευτήσαντος, ὁ δῆμος ἠχθέσθη καὶ συνέδραμε, καὶ τὸ σῶμα κομισθὲν εἰς ἀγορὰν ὑπὸ τῶν εὐγενεστάτων νεανίσκων ἐβιάζετο θάπτειν ἐν τῷ πεδίῳ τοῦ Ἄρεως, ὅπου καὶ Σύλλαν ἔθαψεν. οὐδενὸς δὲ τοῦτο προσδοκήσαντος, οὐδὲ ῥᾳδίας οὔσης τῆς παρασκευῆς, ὁ ἀδελφὸς αὐτοῦ δεόμενος καὶ παραιτούμενος ἔπεισεν ἐπιτρέψαι τὴν παρεσκευασμένην ἐν τῷ περὶ Τοῦσκλον ἀγρῷ τοῦ νεκροῦ κηδείαν γενέσθαι, πολὺν δ’ οὐδ’ αὐτὸς προσεβίω χρόνον, ἀλλ’ ὡς ἡλικίᾳ καὶ δόξῃ μικρὸν ἀπελείφθη, καὶ τῷ χρόνῳ τῆς τελευτῆς, φιλαδελφότατος γενόμενος.", "st": "Luc. 43.1"}, {"sp": "HDR", "t": "Κίμωνος καὶ Λουκούλλος σύγκρισις"}, {"sp": "N", "t": "μάλιστα δ’ ἄν τις εὐδαιμονίσειε τοῦ τέλους Λεύκουλλον, ὅτι πρὸ τῆς μεταβολῆς, ἣν ἤδη κατὰ τῆς πολιτείας ἐτεκταίνετο τοῖς ἐμφυλίοις πολέμοις τὸ πεπρωμένον, ἔφθη προαποθανὼν καὶ καταλύσας ἐν νοσούσῃ μέν, ἔτι δ’ ἐλευθέρᾳ τῇ πατρίδι τὸν βίον. καὶ τοῦτό γε πάντων αὐτῷ πρὸς Κίμωνα κοινότατόν ἐστι. καὶ γὰρ ἐκεῖνος οὔπω συντεταραγμένων τῶν Ἑλληνικῶν, ἀλλ’ ἀκμὴν ἐχόντων ἐτελεύτησεν, ἐπὶ στρατοπέδου μέντοι καὶ στρατηγῶν, οὐκ ἀπειρηκὼς οὐδ’ ἀλύων, οὐδέ τῶν ὅπλων καὶ τῶν στρατηγιῶν καὶ τῶν τροπαίων ἔπαθλον ποιούμενος εὐωχίας καὶ πότους, ὥσπερ Πλάτων ἐπισκώπτει τοὺς περὶ τὸν Ὀρφέα, τοῖς εὖ βεβιωκόσι φάσκοντας ἀποκεῖσθαι γέρας ἐν ᾅδου μέθην αἰώνιον. σχολὴ μὲν οὖν καὶ ἡσυχία καὶ διατριβὴ περὶ λόγους ἡδονήν τινα καὶ θεωρίαν ἔχοντας εὐπρεπέστατον ἀνδρὶ πρεσβύτῃ καὶ πεπαυμένῳ πολέμων καὶ πολιτείας παραμύθιον τὸ δ’ ἐφ’ ἡδονὴν, ὡς τέλος, καταστρέψαντα τὰς καλὰς πράξεις ἤδη λοιπὸν Ἀφροδίσια τῶν πολέμων καὶ στρατηγιῶν ἄγοντα παίζειν καὶ τρυφᾶν οὐκ ἄξια τῆς καλῆς Ἀκαδημείας, οὐδέ τὸν Ξενοκράτη ζηλοῦντος, ἀλλ’ ἐγκεκλικότος πρὸς τὸν Ἐπίκουρον. ὃ καὶ θαυμαστόν ἐστιν ὑπεναντίως γὰρ ἡ νεότης τοῦ μὲν ἐπίψογος καὶ ἀκόλαστος γεγονέναι δοκεῖ, τοῦ δὲ πεπαιδευμένη καὶ σώφρων, βελτίων οὖν ᾧ πρὸς τὸ βέλτιον ἡ μεταβολή· χρηστοτέρα γὰρ ἡ φύσις, ἐν ᾗ γηρᾷ μὲν τὸ χεῖρον, ἐπακμάζει δὲ τὸ ἄμεινον.", "st": "Comp. Cim.–Luc. 1.1"}, {"sp": "N", "t": "καὶ μὴν ὁμοίως γε πλουτήσαντες οὐχ ὁμοίως διέθεντο τὸν πλοῦτον. οὐ γὰρ ἄξιον ὁμοιῶσαι τῷ νοτίῳ τείχει τῆς ἀκροπόλεως, ὃ τοῖς ὑπὸ Κίμωνος κομισθεῖσιν ἐτελέσθη χρήμασι, τοὺς ἐν Νέᾳ πόλει θαλάμους καὶ τὰς περικλύστους ἀπόψεις, ἃς Λούκουλλος ἀπὸ τῶν βαρβαρικῶν ἐξῳκοδόμει λαφύρων οὐδέ γε τῇ Κίμωνος τραπέζῃ τὴν Λουκούλλου παραβαλεῖν, τῇ δημοκρατικῇ καὶ φιλανθρώπῳ τὴν πολυτελῆ καὶ σατραπικήν. ἡ μὲν γὰρ ἀπὸ μικρᾶς δαπάνης πολλοὺς καθ’ ἡμέραν διέτρεφεν, ἡ δ’ εἰς ὀλίγους τρυφῶντας ἀπὸ πολλῶν παρεσκευάζετο χρημάτων, εἰ μὴ νὴ Δία τῶν πραγμάτων ἐποίει διαφορὰν ὁ χρόνος· ἄδηλον γὰρ, εἰ καὶ Κίμων ἀπὸ τῶν πράξεων καὶ στρατηγιῶν εἰς ἀπόλεμον καὶ ἀπολίτευτον γῆρας ἀφεὶς αὑτόν ἔτι μᾶλλον ἂν ἐχρήσατο σοβαρᾷ καὶ πρὸς ἡδονὴν ἀνειμένῃ διαίτῃ· καὶ γὰρ φιλοπότης καὶ πανηγυρικὸς καὶ τὰ πρὸς γυναῖκας, ὡς προείρηται, διαβεβλημένος. αἱ δὲ περὶ τὰς πράξεις καὶ τοὺς ἀγῶνας κατορθώσεις ἡδονὰς ἑτέρας ἔχουσαι τῶν χειρόνων ἐπιθυμιῶν ἀσχολίαν ποιοῦσι καὶ λήθην ταῖς πολιτικαῖς καὶ φιλοτίμοις φύσεσιν. εἰ γοῦν καὶ Λούκουλλος ἐτελεύτησεν ἀγωνιζόμενος καὶ στρατηγῶν, οὐδ’ ἂν ὁ ψογερώτατος καὶ φιλομεμφότατος εὑρεῖν μοι δοκεῖ διαβολὴν ἐπ’ αὐτόν, καὶ ταῦτα μὲν περὶ τῆς διαίτης.", "st": "Comp. Cim.–Luc. 1.5"}, {"sp": "N", "t": "ἐν δὲ τοῖς πολεμικοῖς ὅτι μὲν ἀμφότεροι καὶ κατὰ γῆν καὶ κατὰ θάλασσαν ἀγαθοὶ γεγόνασιν ἀγωνισταί δῆλον ὥσπερ δὲ τῶν ἀθλητῶν τοὺς ἡμέρᾳ μιᾷ πάλῃ καὶ παγκρατίῳ στεφανουμένους ἔθει τινὶ παραδοξονίκας καλοῦσιν, οὕτω Κίμων ἐν ἡμέρᾳ μιᾷ πεζομαχίας καὶ ναυμαχίας ἅμα τροπαίῳ στεφανώσας τὴν Ἑλλάδα δίκαιός ἐστιν ἔχειν τινὰ προεδρίαν ἐν τοῖς στρατηγοῖς. καὶ μὴν Λουκούλλῳ μὲν ἡ πατρίς, Κίμων δὲ τῇ πατρίδι τὴν ἡγεμονίαν περιέθηκε. καὶ ὁ μὲν ἀρχούσῃ τῶν συμμάχων προσεκτήσατο τὰ τῶν πολεμίων, ὁ δ’ ἄλλοις ἑπομένην παραλαβών ἅμα καὶ τῶν συμμάχων ἄρχειν καὶ τῶν πολεμίων κρατεῖν ἐποίησε, Πέρσας μὲν ἀναγκάσας ἡττηθέντας ἐκβῆναι τῆς θαλάσσης, Λακεδαιμονίους δὲ πείσας ἑκόντας ἐκστῆναι. εἰ τοίνυν μέγιστον ἔργον ἡγεμόνος εὐπείθειαν ἐργάσασθαι δι’ εὐνοίας, Λούκουλλος μὲν ὑπὸ τῶν στρατιωτῶν κατεφρονήθη, Κίμων δ’ ὑπὸ τῶν συμμάχων ἐθαυμάσθη· παρ’ οὗ μὲν γὰρ ἀπέστησαν, πρὸς ὃν δὲ μετέστησαν. καὶ ὁ μὲν ὧν ἄρχων ἐξῆλθεν, ὑπὸ τούτων ἀπολειφθεὶς ἐπανῆλθεν, ὁ δὲ μεθ’ ὧν ἑτέροις ποιήσων τὸ προσταττόμενον ἐξεπέμφθη, τούτοις αὐτὸς διδοὺς τὸ παράγγελμα κατέπλευσε, τρία τὰ πάντων δυσκολώτατα διαπεπραγμένος ὁμοῦ τῇ πόλει, πρὸς μὲν τοὺς πολεμίους εἰρήνην, παρὰ δὲ τῶν συμμάχων ἡγεμονίαν, πρὸς δὲ Λακεδαιμονίους ὁμόνοιαν.", "st": "Comp. Cim.–Luc. 2.1"}, {"sp": "N", "t": "μεγάλας τοίνυν ἐπιχειρήσαντες ἀμφότεροι καταλύειν ἡγεμονίας καὶ καταστρέφεσθαι τὴν Ἀσίαν πᾶσαν ἀτελεῖς ἐγένοντο τῶν πράξεων, ὁ μὲν καθάπαξ διὰ τὴν τύχην ἐτελεύτησε γὰρ στρατηγῶν καὶ εὐημερῶν τὸν δ’ οὐ παντελῶς ἄν τις ἐξέλοιτο τῆς παρ’ αὐτὸν αἰτίας, εἴτ’ ἠγνόησεν εἴτ’ οὐκ ἐθεράπευσε τὰς ἐν τῷ στρατιωτικῷ διαφορὰς καὶ μέμψεις, ἀφ’ ὧν εἰς τηλικαύτας ἀπεχθείας προῆλθεν. ἢ τοῦτό γε καὶ πρὸς Κίμωνα κοινόν ἐστι· καὶ γὰρ ἐκεῖνον ὑπήγαγόν τε εἰς δίκας οἱ πολῖται καὶ τελευτῶντες ἐξωστράκισαν, ἵν’ αὐτοῦ δέκα ἐτῶν, ὥς φησιν ὁ Πλάτων, τῆς φωνῆς μὴ ἀκούσωσιν. αἱ γὰρ ἀριστοκρατικαὶ φύσεις ὀλίγα τοῖς πολλοῖς συνᾴδουσι καὶ πρὸς ἡδονὴν ἔχουσι, τὰ δὲ πολλὰ προσβιαζόμεναι τῷ κατευθύνειν διαστρεφομένους ἀνιῶσιν, ὥσπερ οἱ τῶν ἰατρῶν δεσμοί, καίπερ εἰς τὰ κατὰ φύσιν ἄγοντες τὰς παραρθρήσεις. ταύτης μὲν οὖν ἴσως ἀπαλλακτέον τῆς αἰτίας ἑκάτερον.", "st": "Comp. Cim.–Luc. 2.4"}, {"sp": "N", "t": "πολὺ δ’ ὁ Λούκουλλος προῆλθε τῷ πολέμῳ τόν τε Ταῦρον ὑπερβαλὼν στρατοπέδῳ Ῥωμαίων πρῶτος, καὶ τόν Τίγριν διαβάς καὶ τὰ βασίλεια τῆς Ἀσίας ἐν ὄψει τῶν βασιλέων, Τιγρανόκερτα καὶ Κάβειρα καὶ Σινώπην καὶ Νίσιβιν, ἑλὼν καὶ καταφλέξας, καὶ τὰ μὲν βόρεια μέχρι Φάσιδος, τὰ δ’ ἑῷα μέχρι Μηδίας, τὰ δὲ πρὸς νότον καὶ τήν ἐρυθρὰν θάλασσαν οἰκειωσάμενος διὰ τῶν Ἀραβικῶν βασιλέων, συντρίψας δὲ τὰς δυνάμεις τῶν βασιλέων, ἀπολειφθεὶς δὲ μόνου τοῦ τὰ σώματα λαβεῖν, ὥσπερ θηρίων εἰς ἐρημίας καὶ ὕλας ἀστιβεῖς καὶ ἀβάτους ἀποδιδρασκόντων. τεκμήριον δὲ μέγα· Πέρσαι μὲν γὰρ ὡς οὐδὲν μέγα πεπονθότες ὑπὸ Κίμωνος εὐθὺς ἀντετάττοντο τοῖς Ἕλλησι, καὶ τήν γε πολλὴν δύναμιν αὐτῶν ἐν Αἰγύπτῳ κρατήσαντες διέφθειραν, Τιγράνου δὲ καὶ Μιθριδάτου μετὰ Λούκουλλον οὐδὲν ἄλλο ἔργον ἐγένετο, ἀλλ’ ὁ μὲν ἀσθενὴς ἤδη καὶ συγκεκομμένος ὑπὸ τῶν πρώτων ἀγώνων οὐδ’ ἅπαξ ἐτόλμησε δεῖξαι Πομπηΐῳ τήν δύναμιν ἔξω τοῦ χάρακος, ἀλλὰ φυγὼν εἰς Βόσπορον κατέβη κἀκεῖ κατέστρεψε, Τιγράνης δ’ αὐτὸς ἑαυτὸν γυμνὸν καὶ ἄνοπλον φέρων ὑπέρριψε Πομπηΐῳ, καὶ τὸ διάδημα τῆς κεφαλῆς ἀφελόμενος ἔθηκε πρὸ τῶν ποδῶν, οὐ τοῖς ἑαυτοῦ κολακεύων Πομπήϊον, ἀλλὰ τοῖς ὑπὸ Λουκούλλου τεθριαμβευμένοις. ἠγάπησε γοῦν ἀπολαμβάνων τὰ σύμβολα τῆς βασιλείας ὡς ἀφῃρημένος πρότερον. μείζων οὖν στρατηγὸς, ὥσπερ ἀθλητὴς, ὁ τῷ μεθ’ ἑαυτὸν ἀσθενέστερον παραδοὺς τόν ἀντίπαλον.", "st": "Comp. Cim.–Luc. 3.1"}, {"sp": "N", "t": "ἔτι τοίνυν Κίμων μὲν συντετριμμένην τήν βασιλέως δύναμιν καὶ τὸ Περσῶν φρόνημα συνεσταλμένον ἥτταις μεγάλαις καὶ ἀπαύστοις φυγαῖς ὑπὸ Θεμιστοκλέους καὶ Παυσανίου καὶ Λεωτυχίδου καταλαβὼν ἐπενέβη καὶ ὑποπεπτωκότων καὶ προηττημένων ταῖς ψυχαῖς τὰ σώματα ῥᾳδίως ἐνίκησε, Λουκούλλῳ δὲ Τιγράνης ἀήττητος ἐκ πολλῶν ἀγώνων καὶ μέγα φρονῶν συνέπεσε. πλήθει δ’ οὐδ’ ἄξιον παραβαλεῖν τοῖς ἐπὶ Λούκουλλον συνελθοῦσι τοὺς ὑπὸ Κίμωνος κρατηθέντας. ὥστε πάντῃ μεταλαμβάνοντι δυσδιαίτητον εἶναι τήν κρίσιν, ἐπεὶ καὶ τὸ δαιμόνιον ἀμφοτέροις ἔοικεν εὐμενὲς γενέσθαι, τῷ μὲν ἃ χρὴ κατορθοῦν, τῷ δ’ ἃ φυλάττεσθαι χρὴ προμηνῦον, ὥστε καὶ τὴν παρὰ τῶν θεῶν ψῆφον αὐτοῖς ὑπάρχειν ὡς ἀγαθοῖς καὶ θείοις τήν φύσιν ἀμφοτέροις.", "st": "Comp. Cim.–Luc. 3.5"}, {"sp": "HDR", "t": "Νικίας"}, {"sp": "N", "t": "ἐπεὶ δοκοῦμεν οὐκ ἀτόπως τῷ Νικίᾳ τὸν Κράσσον παραβάλλειν, καὶ τὰ Παρθικὰ παθήματα τοῖς Σικελικοῖς, ὥρα παραιτεῖσθαι καὶ παρακαλεῖν ὑπὲρ ἐμοῦ τοὺς ἐντυγχάνοντας τοῖς συγγράμμασι τούτοις, ὅπως ἐπὶ ταῖς διηγήσεσιν αἷς Θουκυδίδης, αὐτὸς αὑτοῦ περὶ ταῦτα παθητικώτατος, ἐναργέστατος, ποικιλώτατος γενόμενος, ἀμιμήτως ἐξενήνοχε, μηδὲν ἡμᾶς ὑπολάβωσι πεπονθέναι Τιμαίῳ πάθος ὅμοιον, ὃς ἐλπίσας τὸν μὲν Θουκυδίδην ὑπερβαλεῖσθαι δεινότητι, τὸν δὲ Φίλιστον ἀποδείξειν παντάπασι φορτικὸν καὶ ἰδιώτην, διὰ μέσων ὠθεῖται τῇ ἱστορίᾳ τῶν μάλιστα κατωρθωμένων ἐκείνοις ἀγώνων καὶ ναυμαχιῶν καὶ δημηγοριῶν, οὐ μὰ Δία", "st": "Nic. 1.1"}, {"sp": "N", "t": "παρὰ Λύδιον ἅρμα πεζὸς οἰχνεύων", "st": "Nic. 1.1b"}, {"sp": "N", "t": "ὥς φησι Πίνδαρος, ἀλλ’ ὅλως τις ὀψιμαθὴς καὶ μειρακιώδης φαινόμενος ἐν τούτοις, καὶ κατὰ τὸν Δίφιλον", "st": "Nic. 1.1c"}, {"sp": "N", "t": "παχύς, ὠνθυλευμένος στέατι Σικελικῷ,", "st": "Nic. 1.1d"}, {"sp": "N", "t": "πολλαχοῦ δ’ ὑπορρέων εἰς τὸν Ξέναρχον, ὥσπερ ὅταν λέγῃ τοῖς Ἀθηναίοις οἰωνὸν ἡγήσασθαι γεγονέναι τὸν ἀπὸ τῆς νίκης ἔχοντα τοὔνομα στρατηγὸν ἀντειπόντα πρὸς τὴν στρατηγίαν, καὶ τῇ περικοπῇ τῶν Ἑρμῶν προσημαίνειν αὐτοῖς τὸ δαιμόνιον, ὡς ὑπὸ Ἑρμοκράτους τοῦ Ἕρμωνος πλεῖστα πείσονται παρὰ τὸν πόλεμον· ἔτι δ’ εἰκὸς εἶναι τὸν Ἡρακλέα τοῖς μὲν Συρακουσίοις βοηθεῖν διὰ τὴν Κόρην, παρ’ ἧς ἔλαβε τὸν Κέρβερον, ὀργίζεσθαι δὲ τοῖς Ἀθηναίοις, ὅτι τοὺς Αἰγεστέας, ἀπογόνους ὄντας Τρώων, ἔσωζον, αὐτὸς δ’ ὑπὸ Λαομέδοντος ἀδικηθεὶς ἀνάστατον ἐποίησε τὴν πόλιν.", "st": "Nic. 1.3"}, {"sp": "N", "t": "ἀλλὰ τούτῳ μὲν ἴσως ἀπὸ τῆς αὐτῆς ἐμμελείας ταῦτά τε γράφειν ἐπῄει καὶ τὴν Φιλίστου διάλεκτον εὐθύνειν, καὶ τοῖς περὶ Πλάτωνα καὶ Ἀριστοτέλην λοιδορεῖσθαι· ἐμοὶ δ’ ὅλως μὲν ἡ περὶ λέξιν ἅμιλλα καὶ ζηλοτυπία πρὸς ἑτέρους μικροπρεπὲς φαίνεται καὶ σοφιστικόν, ἂν δὲ πρὸς τὰ ἀμίμητα γίγνηται, καὶ τελέως ἀναίσθητον. ἃς γοῦν Θουκυδίδης ἐξήνεγκε πράξεις καὶ Φίλιστος, ἐπεὶ παρελθεῖν οὐκ ἔστι, μάλιστά γε δὴ τὸν τρόπον καὶ τὴν διάθεσιν τοῦ ἀνδρὸς ὑπὸ πολλῶν καὶ μεγάλων παθῶν καλυπτομένην περιεχούσας, ἐπιδραμὼν βραχέως καὶ διὰ τῶν ἀναγκαίων, ἵνα μὴ παντάπασιν ἀμελὴς δοκῶ καὶ ἀργὸς εἶναι, τὰ διαφεύγοντα τοὺς πολλούς, ὑφ’ ἑτέρων δ’ εἰρημένα σποράδην ἢ πρὸς ἀναθήμασιν ἢ ψηφίσμασιν εὑρημένα παλαιοῖς πεπείραμαι συναγαγεῖν, οὐ τὴν ἄχρηστον ἀθροίζων ἱστορίαν, ἀλλὰ τὴν πρὸς κατανόησιν ἤθους καὶ τρόπου παραδιδούς.", "st": "Nic. 1.4"}, {"sp": "N", "t": "ἔνεστιν οὖν περὶ Νικίου πρῶτον εἰπεῖν ὃ γέγραφεν Ἀριστοτέλης, ὅτι τρεῖς ἐγένοντο βέλτιστοι τῶν πολιτῶν καὶ πατρικὴν ἔχοντες εὔνοιαν καὶ φιλίαν πρὸς τὸν δῆμον, Νικίας ὁ Νικηράτου καὶ Θουκυδίδης ὁ Μελησίου καὶ Θηραμένης ὁ Ἅγνωνος, ἧττον δὲ οὗτος ἢ ἐκεῖνοι· καὶ γὰρ εἰς δυσγένειαν ὡς ξένος ἐκ Κέω λελοιδόρηται, καὶ διὰ τὸ μὴ μόνιμον, ἀλλ’ ἐπαμφοτερίζον ἀεὶ τῇ προαιρέσει τῆς πολιτείας ἐπεκλήθη Κόθορνος. ἐκείνων δὲ πρεσβύτερος μὲν ὁ Θονκυδίδης ἦν, καὶ πολλὰ καὶ Περικλεῖ δημαγωγοῦντι τῶν καλῶν καὶ ἀγαθῶν προϊστάμενος ἀντεπολιτεύσατο, νεώτερος δὲ Νικίας γενόμενος ἦν μὲν ἔν τινι λόγῳ καὶ Περικλέους ζῶντος, ὥστε κἀκείνῳ συστρατηγῆσαι καὶ καθ’ αὑτὸν ἄρξαι πολλάκις, Περικλέους δ’ ἀποθανόντος εὐθὺς εἰς τὸ πρωτεύειν προήχθη, μάλιστα μὲν ὑπὸ τῶν πλουσίων καὶ γνωρίμων, ἀντίταγμα ποιουμένων αὐτὸν πρὸς τὴν Κλέωνος βδελυρίαν καὶ τόλμαν, οὐ μὴν ἀλλὰ καὶ τὸν δῆμον εἶχεν εὔνουν καὶ συμφιλοτιμούμενον. ἴσχυε μὲν γὰρ ὁ Κλέων μέγα γερονταγωγῶν κἀναμισθαρνεῖν διδούς, ὅμως δὲ καὶ τὴν πλεονεξίαν αὐτοῦ καὶ τὴν ἰταμότητα καὶ τὸ θράσος ὁρῶντες αὐτοὶ οἷς πρὸς χάριν ἔπραττεν, οἱ πολλοὶ τὸν Νικίαν ἐπήγοντο. καὶ γὰρ οὐκ ἦν αὐστηρὸν οὐδ’ ἐπαχθὲς ἄγαν αὐτοῦ τὸ σεμνόν, ἀλλ’ εὐλαβείᾳ τινὶ μεμιγμένον αὐτῷ τῷ δεδιέναι δοκοῦντι τοὺς πολλοὺς δημαγωγοῦν. τῇ φύσει γὰρ ὢν ἀθαρσὴς καὶ δύσελπις, ἐν μὲν τοῖς πολεμικοῖς ἀπέκρυπτεν εὐτυχίᾳ τὴν δειλίαν· κατώρθου γὰρ ὁμαλῶς στρατηγῶν· τὸ δ’ ἐν τῇ πολιτείᾳ ψοφοδεὲς καὶ πρὸς τοὺς συκοφάντας εὐθορύβητον αὐτοῦ καὶ δημοτικὸν ἐδόκει, καὶ δύναμιν οὐ μικρὰν ἀπ’ εὐνοίας τοῦ δήμου παρεῖχε τῷ δεδιέναι τοὺς ὑπερορῶντας, αὔξειν δὲ τοὺς δεδιότας. τοῖς γὰρ πολλοῖς τιμὴ μεγίστη παρὰ τῶν μειζόνων τὸ μὴ καταφρονεῖσθαι.", "st": "Nic. 2.1"}, {"sp": "N", "t": "Περικλῆς μὲν οὖν ἀπό τε ἀρετῆς ἀληθινῆς καὶ λόγου δυνάμεως τὴν πόλιν ἄγων οὐδενὸς ἐδεῖτο σχηματισμοῦ πρὸς τὸν ὄχλον οὐδὲ πιθανότητος, Νικίας δὲ τούτοις μὲν λειπόμενος, οὐσίᾳ δὲ προέχων, ἀπ’ αὐτῆς ἐδημαγώγει. καὶ τῇ Κλέωνος εὐχερείᾳ καὶ βωμολοχίᾳ πρὸς ἡδονὴν μεταχειριζομένῃ τοὺς Ἀθηναίους διὰ τῶν ὁμοίων ἀντιπαρεξάγειν ἀπίθανος ὤν, χορηγίαις ἀνελάμβανε καὶ γυμνασιαρχίαις ἑτέραις τε τοιαύταις φιλοτιμίαις τὸν δῆμον, ὑπερβαλλόμενος πολυτελείᾳ καὶ χάριτι τοὺς πρὸ ἑαυτοῦ καὶ καθ’ ἑαυτὸν ἅπαντας. εἱστήκει δὲ καὶ τῶν ἀναθημάτων αὐτοῦ καθ’ ἡμᾶς τό τε Παλλάδιον ἐν ἀκροπόλει, τὴν χρύσωσιν ἀποβεβληκός, καὶ ὁ τοῖς χορηγικοῖς τρίποσιν ὑποκείμενος ἐν Διονύσου νεώς· ἐνίκησε γὰρ πολλάκις χορηγήσας, ἐλείφθη δὲ οὐδέποτε. λέγεται δ’ ἔν τινι χορηγίᾳ παρελθεῖν οἰκέτης αὐτοῦ κεκοσμημένος εἰς σχῆμα Διονύσου, κάλλιστος ὀφθῆναι καὶ μέγιστος, οὔπω γενειῶν· ἡσθέντων δὲ τῶν Ἀθηναίων τῇ ὄψει καὶ κροτούντων ἐπὶ πολὺν χρόνον, ἀναστὰς ὁ Νικίας εἶπεν ὡς οὐχ ὅσιον ἡγοῖτο δουλεύειν καταπεφημισμένον θεῷ σῶμα, καὶ τὸν νεανίσκον ἀπηλευθέρωσε.", "st": "Nic. 3.1"}, {"sp": "N", "t": "μνημονεύεται δ’ αὐτοῦ καὶ τὰ περὶ Δῆλον ὡς λαμπρὰ καὶ θεοπρεπῆ φιλοτιμήματα. τῶν γὰρ χορῶν, οὓς αἱ πόλεις ἔπεμπον ᾀσομένους τῷ θεῷ, προσπλεόντων μὲν ὡς ἔτυχεν, εὐθὺς δ’ ὄχλου πρὸς τὴν ναῦν ἀπαντῶντος ᾄδειν κελευομένων κατ’ οὐδένα κόσμον, ἀλλ’ ὑπὸ σπουδῆς ἀσυντάκτως ἀποβαινόντων ἅμα καὶ στεφανουμένων καὶ μεταμφιεννυμένων, ἐκεῖνος, ὅτε τὴν θεωρίαν ἦγεν, αὐτὸς μὲν εἰς Ῥήνειαν ἀπέβη τὸν χορὸν ἔχων καὶ τὰ ἱερεῖα καὶ τὴν ἄλλην παρασκευήν, ζεῦγμα δὲ πεποιημένον Ἀθήνησι πρὸς τὰ μέτρα καὶ κεκοσμημένον ἐκπρεπῶς χρυσώσεσι καὶ βαφαῖς καὶ στεφάνοις καὶ αὐλαίαις κομίξων, διὰ νυκτὸς ἐγεφύρωσε τὸν μεταξὺ Ῥηνείας καὶ Δήλου πόρον οὐκ ὄντα μέγαν· εἶθ’ ἅμα ἡμέρᾳ τήν τε πομπὴν τῷ θεῷ καὶ τὸν χορὸν ἄγων κεκοσμημένον πολυτελῶς καὶ ᾄδοντα διὰ τῆς γεφύρας ἀπεβίβαζε. μετὰ δὲ τὴν θυσίαν καὶ τὸν ἀγῶνα καὶ τὰς ἑστιάσεις τόν τε φοίνικα τὸν χαλκοῦν ἔστησεν ἀνάθημα τῷ θεῷ, καὶ χωρίον μυρίων δραχμῶν πριάμενος καθιέρωσεν, οὗ τὰς προσόδους ἔδει Δηλίους καταθύοντας ἑστιᾶσθαι, πολλὰ καὶ ἀγαθὰ Νικίᾳ παρὰ τῶν θεῶν αἰτουμένους· καὶ γὰρ τοῦτο τῇ στήλῃ ἐνέγραψεν, ἣν ὥσπερ φύλακα τῆς δωρεᾶς ἐν Δήλῳ κατέλιπεν. ὁ δὲ φοῖνιξ ἐκεῖνος ὑπὸ τῶν πνευμάτων ἀποκλασθεὶς ἐνέπεσε τῷ Ναξίων ἀνδριάντι τῷ μεγάλῳ καὶ ἀνέτρεψε.", "st": "Nic. 3.4"}, {"sp": "N", "t": "τούτοις δ’ ὅτι μὲν πολὺ τὸ πρὸς δόξαν καὶ φιλοτιμίαν πανηγυρικὸν καὶ ἀγοραῖον ἔνεστιν, οὐκ ἄδηλον, ἀλλὰ τῷ λοιπῷ τρόπῳ τοῦ ἀνδρὸς καὶ ἤθει πιστεύσειεν ἄν τις εὐσεβείας ἐπακολούθημα τὴν τοιαύτην χάριν καὶ δημαγωγίαν γενέσθαι σφόδρα γὰρ ἦν τῶν ἐκπεπληγμένων τὰ δαιμόνια καὶ θειασμῷ προσκείμενος, ὥς φησι Θουκυδίδης. ἐν δέ τινι τῶν Πασιφῶντος διαλόγων γέγραπται ὅτι καθ’ ἡμέραν ἔθυε τοῖς θεοῖς, καὶ μάντιν ἔχων ἐπὶ τῆς οἰκίας προσεποιεῖτο μὲν ἀεὶ σκέπτεσθαι περὶ τῶν δημοσίων, τὰ δὲ πλεῖστα περὶ τῶν ἰδίων καὶ μάλιστα περὶ τῶν ἀργυρείων μετάλλων· ἐκέκτητο γὰρ ἐν τῇ Λαυρεωτικῇ πολλά, μεγάλα μὲν εἰς πρόσοδον, οὐκ ἀκινδύνους δὲ τὰς ἐργασίας ἔχοντα· καὶ πλῆθος ἀνδραπόδων ἔτρεφεν αὐτόθι, καὶ τῆς οὐσίας ἐν ἀργυρίῳ τὸ πλεῖστον εἶχεν. ὅθεν οὐκ ὀλίγοι περὶ αὐτὸν ἦσαν αἰτοῦντες καὶ λαμβάνοντες. ἐδίδου γὰρ οὐχ ἧττον τοῖς κακῶς ποιεῖν δυναμένοις ἢ τοῖς εὖ πάσχειν ἀξίοις, καὶ ὅλως πρόσοδος ἦν αὐτοῦ τοῖς τε πονηροῖς ἡ δειλία καὶ τοῖς χρηστοῖς ἡ φιλανθρωπία.", "st": "Nic. 4.1"}, {"sp": "N", "t": "λαβεῖν δὲ περὶ τούτων μαρτυρίαν καὶ παρὰ τῶν κωμικῶν ἔστι. Τηλεκλείδης μὲν γὰρ εἴς τινα τῶν συκοφαντῶν ταυτὶ πεποίηκε·", "st": "Nic. 4.4"}, {"sp": "N", "t": "Χαρικλέης μὲν οὖν ἔδωκε μνᾶν, ἵν’ αὐτὸν μὴ λέγῃ<br>ὡς ἔφυ τῇ μητρὶ παίδων πρῶτος ἐκ βαλλαντίου·", "st": "Nic. 4.4b"}, {"sp": "N", "t": "τέσσαρας δὲ μνᾶς ἔδωκε Νικίας Νικηράτου·<br>ὧν δ’ ἕκατι τοῦτ’ ἔδωκε, καίπερ εὖ εἰδὼς ἐγὼ<br>οὐκ ἐρῶ, φίλος γὰρ ἁνήρ, σωφρονεῖν δέ μοι δοκεῖ.", "st": "Nic. 4.4c"}, {"sp": "N", "t": "ὁ δ’ ὑπ’ Εὐπόλιδος κωμῳδούμενος ἐν τῷ Μαρικᾷ παράγων τινὰ τῶν ἀπραγμόνων καὶ πενήτων λέγει·", "st": "Nic. 4.5"}, {"sp": "N", "t": "Α.<br>πόσου χρόνου γὰρ συγγεγένησαι Νικίᾳ;", "st": "Nic. 4.5b"}, {"sp": "N", "t": "Β.<br>οὐδ’ εἶδον, εἰ μὴ ἔναγχος ἑστῶτ’ ἐν ἀγορᾷ.", "st": "Nic. 4.5c"}, {"sp": "N", "t": "Α.<br>ἁνὴρ ὁμολογεῖ Νικίαν ἑορακέναι.", "st": "Nic. 4.5d"}, {"sp": "N", "t": "καίτοι τί μαθὼν ἂν εἶδεν, εἰ μὴ προὐδίδου;", "st": "Nic. 4.5e"}, {"sp": "N", "t": "Γ.<br>ἠκούσατ’, ὦ ξυνήλικες,", "st": "Nic. 4.5f"}, {"sp": "N", "t": "ἐπ’ αὐτοφώρῳ Νικίαν εἰλημμένον.<br>Β.", "st": "Nic. 4.5g"}, {"sp": "N", "t": "ὑμεῖς γάρ, ὦ φρενοβλαβεῖς,", "st": "Nic. 4.5h"}, {"sp": "N", "t": "λάβοιτ’ ἂν ἄνδρ’ ἄριστον ἐν κακῷ τινι;", "st": "Nic. 4.5i"}, {"sp": "N", "t": "ὁ δ’ Ἀριστοφάνους Κλέων ἀπειλῶν λέγει·<br>λαρυγγιῶ τοὺς ῥήτορας καὶ Νικίαν ταράξω.", "st": "Nic. 4.6"}, {"sp": "N", "t": "ὑποδηλοῖ δὲ καὶ Φρύνιχος τὸ ἀθαρσὲς αὐτοῦ καὶ καταπεπληγμένον ἐν τούτοις·", "st": "Nic. 4.6b"}, {"sp": "N", "t": "ἦν γὰρ πολίτης ἀγαθός, ὡς εὖ οἶδ’ ἐγώ,<br>κοὐχ ὑποταγεὶς ἐβάδιζεν, ὥσπερ Νικίας.", "st": "Nic. 4.6c"}, {"sp": "N", "t": "οὕτω δὴ διακείμενος εὐλαβῶς πρὸς τοὺς συκοφάντας οὔτε συνεδείπνει τινὶ τῶν πολιτῶν οὔτε κοινολογίαις οὔτε συνδιημερεύσεσιν ἐνέβαλλεν ἑαυτόν, οὐδ’ ὅλως ἐσχόλαζε ταῖς τοιαύταις διατριβαῖς, ἀλλ’ ἄρχων μὲν ἐν τῷ στρατηγίῳ διετέλει μέχρι νυκτός, ἐκ δὲ βουλῆς ὕστατος ἀπῄει πρῶτος ἀφικνούμενος. εἰ δὲ μηδὲν ἐν κοινῷ πράττειν ἔχοι, δυσπρόσοδος ἦν καὶ δυσέντευκτος οἰκουρῶν καὶ κατακεκλεισμένος. οἱ δὲ φίλοι τοῖς ἐπὶ ταῖς θύραις φοιτῶσιν ἐνετύγχανον, καὶ παρῃτοῦντο συγγνώμην ἔχειν, ὡς καὶ τότε Νικίου πρὸς δημοσίας χρείας τινὰς καὶ ἀσχολίας ὄντος.", "st": "Nic. 5.1"}, {"sp": "N", "t": "καὶ ὁ μάλιστα ταῦτα συντραγῳδῶν καὶ συμπεριτιθεὶς ὄγκον αὐτῷ καὶ δόξαν Ἱέρων ἦν, ἀνὴρ τεθραμμένος ἐπὶ τῆς οἰκίας τοῦ Νικίου, περί τε γράμματα καὶ μουσικὴν ἐξησκημένος ὑπ’ αὐτοῦ, προσποιούμενος δ’ υἱὸς εἶναι Διονυσίου τοῦ Χαλκοῦ προσαγορευθέντος, οὗ καὶ ποιήματα σώζεται, καὶ τῆς εἰς Ἰταλίαν ἀποικίας ἡγεμὼν γενόμενος ἔκτισε Θουρίους. οὗτος οὖν ὁ Ἱέρων τά τε πρὸς τοὺς μάντεις ἀπόρρητα διεπράττετο τῷ Νικίᾳ, καὶ λόγους ἐξέφερεν εἰς τὸν δῆμον ὡς ἐπίπονόν τινα καὶ ταλαίπωρον διὰ τὴν πόλιν ζῶντος αὐτοῦ βίον· ᾧ γ’ ἔφη καὶ περὶ λουτρὸν ὄντι καὶ περὶ δεῖπνον ἀεί τι προσπίπτειν δημόσιον· ἀμελῶν δὲ τῶν ἰδίων ὑπὸ τοῦ τὰ κοινὰ φροντίζειν μόλις ἄρχεται καθεύδειν περὶ πρῶτον ὕπνον. ὅθεν αὐτῷ καὶ τὸ σῶμα διάκειται κακῶς, καὶ τοῖς φίλοις οὐ προσηνὴς οὐδὲ ἡδύς ἐστιν, ἀλλὰ καὶ τούτους προσαποβέβληκε τοῖς χρήμασι πολιτευόμενος. οἱ δ’ ἄλλοι καὶ φίλους κτώμενοι καὶ πλουτίζοντες αὑτοὺς ἀπὸ τοῦ βήματος εὐπαθοῦσι καὶ προσπαίζουσι τῇ πολιτείᾳ. τῷ δ’ ὄντι τοιοῦτος ἦν ὁ Νικίου βίος ὥστ’ αὐτὸν εἰπεῖν τὰ τοῦ Ἀγαμέμνονος εἰς αὑτόν·", "st": "Nic. 5.3"}, {"sp": "N", "t": "προστάτην γε τοῦ βίου<br>τὸν ὄγκον ἔχομεν, τῷ τ’ ὄχλῳ δουλεύομεν.", "st": "Nic. 5.3b"}, {"sp": "N", "t": "ὁρῶν δὲ τῶν ἐν λόγῳ δυνατῶν ἢ τῷ φρονεῖν διαφερόντων ἀποχρώμενον εἰς ἔνια ταῖς ἐμπειρίαις τὸν δῆμον, ὑφορώμενον δ’ ἀεὶ καὶ φυλαττόμενον τὴν δεινότητα καὶ κολούοντα τὸ φρόνημα καὶ τὴν δόξαν, ὡς δῆλον ἦν τῇ Περικλέους καταδίκῃ καὶ τῷ Δάημωνος ἐξοστρακισμῷ καὶ τῇ πρὸς Ἀντιφῶντα τὸν Ῥαμνούσιον ἀπιστίᾳ τῶν πολλῶν, καὶ μάλιστα δὴ τοῖς περὶ Πάχητα τὸν ἑλόντα Λέσβον, ὃς εὐθύνας διδοὺς τῆς στρατηγίας ἐν αὐτῷ τῷ δικαστηρίῳ στασάμενος ξίφος ἀνεῖλεν ἑαυτόν, τὰς μὲν ἐργώδεις πάνυ καὶ μακρὰς ἐπειρᾶτο διακρούεσθαι στρατηγίας, ὅπου δ’ αὐτὸς στρατεύοιτο τῆς ἀσφαλείας ἐχόμενος καὶ τὰ πλεῖστα κατορθῶν, ὡς εἰκός, εἰς οὐδεμίαν αὑτοῦ σοφίαν ἢ δύναμιν ἢ ἀρετὴν ἀνέφερε τὰς πράξεις, ἀλλὰ παρεχώρει τῇ τύχῃ καὶ κατέφευγεν εἰς τὸ θεῖον, τῷ φθόνῳ τῆς δόξης ὑφιέμενος.", "st": "Nic. 6.1"}, {"sp": "N", "t": "ἐπεμαρτύρει δὲ καὶ τὰ πράγματα· πολλῶν γὰρ τότε προσκρουσμάτων τῇ πόλει καὶ μεγάλων γενομένων, οὐδενὸς ἁπλῶς ἐκεῖνος μετέσχεν, ἀλλὰ περὶ Θρᾴκην μὲν ἡττήθησαν ὑπὸ Χαλκιδέων Καλλιάδου τε καὶ Ξενοφῶντος στρατηγούντων, τὸ δ’ Αἰτωλικὸν πταῖσμα συνέβη Δημοσθένους ἄρχοντος, ἐν δὲ Δηλίῳ χιλίους αὑτῶν ἀπέβαλον Ἱπποκράτους ἡγουμένου, τοῦ δὲ λοιμοῦ τὴν πλείστην αἰτίαν ἔλαβε Περικλῆς διὰ τὸν πόλεμον εἰς τὸ ἄστυ κατακλείσας τὸν ἀπὸ τῆς χώρας ὄχλον, ἐκ τῆς μεταβολῆς τῶν τόπων καὶ διαίτης ἀήθους γενομένου. Νικίας δὲ τούτων ἁπάντων ἀναίτιος ἔμεινε· καὶ στρατηγῶν εἷλε μὲν Κύθηρα, νῆσον εὖ κατὰ τῆς Λακωνικῆς πεφυκυῖαν καὶ Λακεδαιμονίους ἔχουσαν οἰκήτορας, ἔλαβε δὲ καὶ πολλὰ τῶν ἐπὶ Θρᾴκης ἀφεστώτων καὶ προσηγάγετο, κατακλείσας δὲ Μεγαρεῖς εἰς τὴν πόλιν εὐθὺς μὲν ἔσχε Μίνῳαν τὴν νῆσον, ὀλίγῳ δ’ ὕστερον ἐκ ταύτης ὁρμώμενος Νισαίας ἐκράτησεν, εἰς δὲ τὴν Κορινθίαν ἀποβὰς ἐνίκησε μάχῃ καὶ διέφθειρε Κορινθίων πολλοὺς καὶ Λυκόφρονα τὸν στρατηγόν.", "st": "Nic. 6.3"}, {"sp": "N", "t": "ἔθα δ’ αὐτῷ συνέβη τῶν οἰκείων δύο νεκροὺς ἀπολιπεῖν διαλαθόντας περὶ τὴν ἀναίρεσιν. ὡς οὖν τοῦτ’ ἔγνω, τάχιστα τὸν στόλον ἐπιστήσας ἔπεμψε κήρυκα πρὸς τοὺς πολεμίους περὶ ἀναιρέσεως. καίτοι κατὰ νόμον τινὰ καὶ συνήθειαν ἐδόκουν οἱ νεκρῶν ὑποσπόνδων λαβόντες ἀναίρεσιν ἀπολέγεσθαι τὴν νίκην, καὶ τρόπαιον ἱστάναι τοὺς τούτου τυχόντας οὐκ ἔνθεσμον ἦν· νικᾶν γὰρ τοὺς κρατοῦντας, μὴ κρατεῖν δὲ τοὺς αἰτοῦντας, ὡς λαβεῖν μὴ δυναμένους. ἀλλ’ ὅμως ἐκεῖνος ὑπέμεινε μᾶλλον προέσθαι τὸ νίκημα καὶ τὴν δόξαν ἢ καταλιπεῖν ἀτάφους δύο τῶν πολιτῶν.", "st": "Nic. 6.5"}, {"sp": "N", "t": "πορθήσας δὲ τὴν παραλίαν τῆς Λακωνικῆς καὶ τοὺς ἀντιστάντας Λακεδαιμονίων τρεψάμενος, εἷλε Θυρέαν Αἰγινητῶν ἐχόντων, καὶ τοὺς αἱρεθέντας ἀπήγαγε ζῶντας εἰς Ἀθήνας.", "st": "Nic. 6.5b"}, {"sp": "N", "t": "ἐπεὶ δὲ Δημοσθένους Πύλον τειχίσαντος ἐπεστράτευσαν ἅμα πεζῷ καὶ ναυσὶ Πελοποννήσιοι, καὶ μάχης γενομένης ἀπελήφθησαν ἐν τῇ Σφακτηρίᾳ νήσῳ Σπαρτιατῶν ἄνδρες ἀμφὶ τοὺς τετρακοσίους, μέγα μέν, ὥσπερ ἦν, ἡγούμενοι τὸ λαβεῖν αὐτοὺς Ἀθηναῖοι, χαλεπῆς δὲ καὶ δυσέργου τῆς πολιορκίας οὔσης ἐν χωρίοις ἀνύδροις, καὶ θέρους μὲν μακρὰν καὶ πολυτελῆ τὴν περιαγωγὴν τῶν ἐπιτηδείων ἐχούσης, σφαλερὰν δὲ χειμῶνος καὶ παντελῶς ἄπορον, ἤχθοντο καὶ μετεμέλοντο πρεσβείαν Λακεδαιμονίων ἀπωσάμενοι περὶ σπονδῶν καὶ εἰρήνης ἀφικομένην πρὸς αὐτούς. ἀπεώσαντο δὲ Κλέωνος ἐναντιωθέντος οὐχ ἥκιστα διὰ Νικίαν· ἐχθρὸς γὰρ ὢν αὐτοῦ, καὶ προθύμως ὁρῶν συμπράττοντα τοῖς Λακεδαιμονίοις, ἔπεισε τὸν δῆμον ἀποψηφίσασθαι τὰς σπονδάς. ὡς οὖν ἥ τε πολιορκία μῆκος ἐλάμβανε καὶ δεινὰς ἀπορίας ἐπυνθάνοντο περιεστάναι τὸ στρατόπεδον, δι’ ὀργῆς εἶχον τὸν Κλέωνα.", "st": "Nic. 7.1"}, {"sp": "N", "t": "τοῦ δ’ εἰς τὸν Νικίαν ἐκτρέποντος τὴν αἰτίαν, καὶ κατηγοροῦντος ὅτι δειλίᾳ καὶ μαλακίᾳ προΐεται τοὺς ἄνδρας, ὡς αὐτοῦ γε στρατηγοῦντος οὐκ ἂν περιγενομένους χρόνον τοσοῦτον, τοῖς Ἀθηναίοις εἰπεῖν παρέστη· τί δ’ οὐχὶ καὶ νῦν αὐτὸς σὺ πλεῖς ἐπὶ τοὺς ἄνδρας; ὅ τε Νικίας ἀναστὰς ἐξίστατο τῆς ἐπὶ Πύλον στρατηγίας αὐτῷ, καὶ λαμβάνειν ὁπόσην βούλεται δύναμιν ἐκέλευσε, καὶ μὴ θρασύνεσθαι λόγοις ἀκινδύνοις, ἀλλ’ ἔργον τι τῇ πόλει παρασχεῖν ἄξιον σπουδῆς. ὁ δὲ τὸ μὲν πρῶτον ἀνεδύετο, τῷ μὴ προσδοκῆσαι τοῦτο θορυβούμενος· ἐγκελευομένων δὲ ταὐτὰ τῶν Ἀθηναίων καὶ τοῦ Νικίου καταβοῶντος, ἐξαρθεὶς καὶ ἀναφλεχθεὶς τὸ φιλότιμον ὑπεδέξατό τε τὴν στρατηγίαν, καὶ προσδιωρίσατο πλεύσας ἐντὸς ἡμερῶν εἴκοσιν ἢ κατακτενεῖν ἐκεῖ τοὺς ἄνδρας ἢ ζῶντας ἄξειν Ἀθήναζε. τοῖς δ’ Ἀθηναίοις ἐπῆλθε γελάσαι μέγα μᾶλλον ἢ πιστεῦσαι· καὶ γὰρ ἄλλως εἰώθεσαν αὐτοῦ τὴν κουφότητα καὶ μανίαν φέρειν μετὰ παιδιᾶς οὐκ ἀηδῶς.", "st": "Nic. 7.3"}, {"sp": "N", "t": "λέγεται γὰρ ἐκκλησίας ποτὲ οὔσης τὸν μὲν δῆμον καθήμενον ἄνω περιμένειν πολὺν χρόνον, ὀψὲ δ’ εἰσελθεῖν ἐκεῖνον ἐστεφανωμένον καὶ παρακαλεῖν ὑπερθέσθαι τὴν ἐκκλησίαν εἰς αὔριον· ἀσχολοῦμαι γάρ, ἔφη, σήμερον, ἑστιᾶν μέλλων ξένους καὶ τεθυκὼς τοῖς θεοῖς. τοὺς δ’ Ἀθηναίους γελάσαντας ἀναστῆναι καὶ διαλῦσαι τὴν ἐκκλησίαν.", "st": "Nic. 7.5"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ τότε τύχῃ χρησάμενος ἀγαθῇ καὶ στρατηγήσας ἄριστα μετὰ Δημοσθένους, ἐντὸς οὗ προεῖπε χρόνου τῶν Σπαρτιατῶν ὅσοι μὴ κατὰ μάχην ἔπεσον τὰ ὅπλα παραδόντας ἤγαγεν αἰχμαλώτους. καὶ τοῦτο τῷ Νικίᾳ μεγάλην ἤνεγκεν ἀδοξίαν. οὐ γὰρ ἀσπίδος ῥῖψις, ἀλλ’ αἴσχιόν τι καὶ χεῖρον ἐδόκει τὸ δειλίᾳ τὴν στρατηγίαν ἀποβαλεῖν ἑκουσίως, καὶ προέσθαι τῷ ἐχθρῷ τηλικούτου κατορθώματος ἀφορμάς, αὑτὸν ἀποχειροτονήσαντα τῆς ἀρχῆς. σκώπτει δ’ αὐτὸν εἰς ταῦτα πάλιν Ἀριστοφάνης ἐν μὲν Ὄρνισιν οὕτω πως λέγων·", "st": "Nic. 8.1"}, {"sp": "N", "t": "καὶ μὴν μὰ τὸν Δί’ οὐχὶ νυστάζειν γ’ ἔτι<br>ὥρα ’στὶν ἡμῖν, οὐδὲ μελλονικιᾶν.<br>ἐν δὲ Γεωργοῖς ταῦτα γράφων·<br>Α.<br>ἐθέλω γεωργεῖν.<br>Β.", "st": "Nic. 8.1b"}, {"sp": "N", "t": "εἶτα τίς σε κωλύει;", "st": "Nic. 8.1c"}, {"sp": "N", "t": "Α.<br>ὑμεῖς· ἐπεὶ δίδωμι χιλίας δραχμάς,<br>ἐάν με τῶν ἀρχῶν ἀφῆτε.", "st": "Nic. 8.1d"}, {"sp": "N", "t": "Β.<br>δεχόμεθα·", "st": "Nic. 8.1e"}, {"sp": "N", "t": "δισχίλιαι γάρ εἰσι σὺν ταῖς Νικίου.", "st": "Nic. 8.1f"}, {"sp": "N", "t": "καὶ μέντοι καὶ τὴν πόλιν ἔβλαψεν οὐ μικρὰ τῷ Κλέωνι τοσοῦτον προσγενέσθαι δόξης ἐάσας καὶ δυνάμεως, ὑφ’ ἧς εἰς βαρὺ φρόνημα καὶ θράσος ἐμπεσὼν ἀκάθεκτον ἄλλας τε τῇ πόλει προσετρίψατο συμφοράς, ὧν οὐχ ἥκιστα καὶ αὐτὸς ἀπέλαυσε, καὶ τὸν ἐπὶ τοῦ βήματος κόσμον ἀνελὼν καὶ πρῶτος ἐν τῷ δημηγορεῖν ἀνακραγὼν καὶ περισπάσας τὸ ἱμάτιον καὶ τὸν μηρὸν πατάξας καὶ δρόμῳ μετὰ τοῦ λέγειν ἅμα χρησάμενος, τὴν ὀλίγον ὕστερον ἅπαντα τὰ πράγματα συγχέασαν εὐχέρειαν καὶ ὀλιγωρίαν τοῦ πρέποντος ἐνεποίησε τοῖς πολιτευομένοις.", "st": "Nic. 8.3"}, {"sp": "N", "t": "ἤδη δέ που καὶ Ἀλκιβιάδης ἐνεφύετο τηνικαῦτα τοῖς Ἀθηναίοις δημαγωγὸς οὐχ ὁμοίως ἄκρατος, ἀλλ’ οἷον ἡ Αἰγυπτίων χώρα λέγεται δι’ ἀρετὴν ἐκφέρειν ὁμοῦ", "st": "Nic. 9.1"}, {"sp": "N", "t": "φάρμακα πολλὰ μὲν ἐσθλὰ μεμιγμένα, πολλὰ δὲ λυγρά,", "st": "Nic. 9.1b"}, {"sp": "N", "t": "οὕτως ἡ Ἀλκιβιάδου φύσις ἐπ’ ἀμφότερα πολλὴ ῥυεῖσα καὶ λαμπρά, μεγάλων ἐνέδωκεν ἀρχὰς νεωτερισμῶν. ὅθεν οὐδ’ ἀπαλλαγεὶς τοῦ Κλέωνος ὁ Νικίας καιρὸν ἔσχε παντάπασιν ἀναπαῦσαι καὶ καταστορέσαι τὴν πόλιν, ἀλλ’ εἰς ὁδὸν τὰ πράγματα σωτήριον καταστήσας ἐξέπεσε, ῥύμῃ καὶ σφοδρότητι τῆς Ἀλκιβιάδου φιλοτιμίας αὖθις ἐξωσθεὶς εἰς τὸν πόλεμον.", "st": "Nic. 9.2"}, {"sp": "N", "t": "ἐπράχθη δὲ οὕτως. οἱ μάλιστα προσπολεμοῦντες τῇ εἰρήνῃ τῆς Ἑλλάδος Κλέων καὶ Βρασίδας ἦσαν, ὧν ὁ πόλεμος τοῦ μὲν ἀπέκρυπτε τὴν κακίαν, τοῦ δὲ τὴν ἀρετὴν ἐκόσμει. τῷ μὲν γὰρ ἀδικημάτων μεγάλων, τῷ δὲ κατορθωμάτων ἀφορμὰς παρεῖχε. τούτων οὖν ἅμα πεσόντων ἐν μάχῃ μιᾷ περὶ Ἀμφίπολιν, εὐθὺς ὁ Νικίας παραλαβὼν τοὺς μὲν Σπαρτιάτας ἔκπαλαι τῆς εἰρήνης ὀρεγομένους, τοὺς δ’ Ἀθηναίους οὐκέτι τῷ πολέμῳ θαρροῦντας, ἀμφοτέρους δ’ οἷον ἐκλελυμένους καὶ παρακαθιέντας ἑκουσίως τὰς χεῖρας, ἔπραττεν ὅπως εἰς φιλίαν τὰς πόλεις συναγαγὼν καὶ τοὺς ἄλλους Ἕλληνας ἀπαλλάξας κακῶν καὶ ἀναπαυσάμενος, βέβαιον οὕτω τὸ τῆς εὐτυχίας ὄνομα πρὸς τὸν αὖθις χρόνον ποιοῖτο. τοὺς μὲν οὖν εὐπόρους καὶ πρεσβυτέρους καὶ τῶν γεωργῶν τὸ πλῆθος αὐτόθεν εἰρηνικὸν εἶχεν· ἐπεὶ δὲ καὶ τῶν ἄλλων πολλοῖς ἐντυγχάνων ἰδίᾳ καὶ διδάσκων ἀμβλυτέρους ἐποίησε πρὸς τὸν πόλεμον, οὕτως ἤδη τοῖς Σπαρτιάταις ἐλπίδας ἐνδιδοὺς προεκαλεῖτο καὶ προὔτρεπεν ἔχεσθαι τῆς εἰρήνης. οἱ δ’ ἐπίστευον αὐτῷ διά τε τὴν ἄλλην ἐπιείκειαν, καὶ ὅτι τοῖς ἡλωκόσι περὶ Πύλον καὶ δεδεμένοις ἐπιμελόμενος καὶ περιέπων φιλανθρώπως ἐλαφροτέραν ἐποίει τὴν ἀτυχίαν. ἦσαν οὖν πρότερον πεποιημένοι τινὰ πρὸς ἀλλήλους ἐκεχειρίαν ἐνιαύσιον, ἐν ᾗ συνιόντες εἰς ταὐτὸ καὶ γευόμενοι πάλιν ἀδείας καὶ σχολῆς καὶ πρὸς ξένους καὶ οἰκείους ἐπιμιξίας, ἐπόθουν τὸν ἀμίαντον καὶ ἀπόλεμον βίον, ἡδέως μὲν ᾀδόντων τὰ τοιαῦτα χορῶν ἀκούοντες·", "st": "Nic. 9.3"}, {"sp": "N", "t": "κείσθω δόρυ μοι μίτον ἀμφιπλέκειν ἀράχναις·", "st": "Nic. 9.3b"}, {"sp": "N", "t": "ἡδέως δὲ μεμνημένοι τοῦ εἰπόντος ὅτι τοὺς ἐν εἰρήνῃ καθεύδοντας οὐ σάλπιγγες, ἀλλ’ ἀλεκτρυόνες ἀφυπνίζουσι. λοιδοροῦντες οὖν καὶ προβαλλόμενοι τοὺς λέγοντας ὡς τρὶς ἐννέα ἔτη διαπολεμηθῆναι πέπρωται τὸν πόλεμον, ἔπειθ’ οὕτω περὶ παντὸς εἰς λόγους συμβαίνοντες ἐποιήσαντο τὴν εἰρήνην, δόξα τε παρέστη τοῖς πλείστοις ἀπαλλαγὴν κακῶν σαφῆ γεγονέναι, καὶ τὸν Νικίαν διὰ στόματος εἶχον, ὡς ἀνὴρ εἴη θεοφιλὴς καὶ τὸ δαιμόνιον αὐτῷ δι’ εὐσέβειαν ἐπωνύμῳ γενέσθαι τοῦ μεγίστου καὶ καλλίστου τῶν ἀγαθῶ. δέδωκε· τῷ γὰρ ὄντι Νικίου τὴν εἰρήνην ἐνόμιζον ἔργον, ὡς Περικλέους τὸν πόλεμον. ὁ μὲν γὰρ ἐπ’ αἰτίαις μικραῖς εἰς συμφορὰς μεγάλας ἐμβαλεῖν ἐδόκει τοὺς Ἕλληνας, ὁ δὲ τῶν μεγίστων κακῶν ἔπεισεν ἐκλαθέσθαι φίλους γενομένους. διὸ καὶ τὴν εἰρήνην ἐκείνην ἄχρι νῦν Νικίειον καλοῦσι.", "st": "Nic. 9.6"}, {"sp": "N", "t": "γενομένων δὲ συνθηκῶν ὅπως τὰ χωρία καὶ τὰς πόλεις, ἃς εἶχον ἀλλήλων, καὶ τοὺς αἰχμαλώτους ἀποδιδῶσι, προτέρων ἀποδιδόντων τῶν κλήρῳ λαχόντων, ὠνήσατο τὸν κλῆρον ὁ Νικίας κρύφα χρήμασιν, ὥστε προτέρους ἀποδιδόναι τοὺς Λακεδαιμονίους. καὶ τοῦτο μὲν ἱστορεῖ Θεόφραστος. ἐπεὶ δὲ Κορίνθιοι καὶ Βοιωτοὶ πρὸς τὰ πραττόμενα δυσκολαίνοντες αἰτίαις καὶ μέμψεσιν αὖθις ἐδόκουν ἀνακαλεῖσθαι τὸν πόλεμον, ἔπεισεν ὁ Νικίας τοὺς Ἀθηναίους καὶ Λακεδαιμονίους τῇ εἰρήνῃ τὴν συμμαχίαν ὥσπερ κράτος ἢ δεσμὸν ἐπιθέντας, φοβερωτέρους τε τοῖς ἀφισταμένοις καὶ βεβαιοτέρους ἀλλήλοις γενέσθαι.", "st": "Nic. 10.1"}, {"sp": "N", "t": "πραττομένων δὲ τούτων ὁ Ἀλκιβιάδης οὔτε πρὸς ἡσυχίαν εὖ πεφυκώς, καὶ τοῖς Λακεδαιμονίοις ἀχθόμενος ὅτι τῷ Νικίᾳ προσέκειντο καὶ προσεῖχον, αὐτὸν δ’ ὑπερεώρων καὶ κατεφρόνουν, ἐν ἀρχῇ μὲν εὐθὺς ὑπεναντιωθεὶς τῇ εἰρήνῃ καὶ ἀντιστὰς οὐδὲν ἐπέραινεν, ὀλίγῳ δ’ ὕστερον ὁρῶν οὐκ ἔτι τοῖς Ἀθηναίοις ὁμοίως ἀρέσκοντας τοὺς Λακεδαιμονίους, ἀλλ’ ἀδικεῖν δοκοῦντας ὅτι Βοιωτοῖς ἔθεντο συμμαχίαν καὶ Πάνακτον ἑστῶσαν οὐ παρέδωκαν οὐδ’ Ἀμφίπολιν, ἐπεφύετο ταῖς αἰτίαις καὶ παρώξυνε τὸν δῆμον ἐφ’ ἑκάστῃ. τέλος δὲ πρεσβείαν μεταπεμψάμενος Ἀργείων ἔπραττε συμμαχίαν πρὸς τοὺς Ἀθηναίους. ἐπεὶ δὲ πρέσβεις ἐλθόντες ἐκ Λακεδαίμονος αὐτοκράτορες καὶ τῇ βουλῇ προεντυγχάνοντες ἔδοξαν ἐπὶ πᾶσιν ἥκειν τοῖς δικαίοις, δείσας ὁ Ἀλκιβιάδης μὴ καὶ τὸν δῆμον ἀπὸ τῶν αὐτῶν λόγων ἐπαγάγωνται, περιῆλθεν αὐτοὺς δι’ ἀπάτης καὶ ὅρκων ὡς ἅπαντα συμπράξων, ἂν μὴ φῶσι μηδ’ ὁμολογήσωσιν ἥκειν αὐτοκράτορες· μάλιστα γὰρ οὕτως ἃ βούλονται γενήσεσθαι. πεισθέντων δὲ καὶ μεταστάντων ἀπὸ τοῦ Νικίου πρὸς ἐκεῖνον, ἐμβαλὼν αὐτοὺς εἰς τὸν δῆμον ἠρώτα πρῶτον εἰ περὶ πάντων ἥκουσιν αὐτοκράτορες· ὡς δ’ ἠρνοῦντο, παρ’ ἐλπίδας μεταβαλόμενος τήν τε βουλὴν ἐπεκαλεῖτο μάρτυρα τῶν λόγων, καὶ τὸν δῆμον ἐκέλευε μὴ προσέχειν μηδὲ πιστεύειν οὕτω περιφανῶς ψευδομένοις καὶ νῦν μὲν ταῦτα, νῦν δὲ τἀναντία περὶ τῶν αὐτῶν λέγουσι. θορυβουμένων δ’, ὡς εἰκός, αὐτῶν, καὶ τοῦ Νικίου μηδὲν ἔχοντος εἰπεῖν, ἀλλ’ ἄχει καὶ θαύματι πεπληγότος, ὁ μὲν δῆμος εὐθὺς ὥρμητο τοὺς Ἀργείους καλεῖν καὶ ποιεῖσθαι συμμάχους, ἐβοήθησε δὲ τῷ Νικίᾳ σεισμός τις διὰ μέσου γενόμενος καὶ διαλύσας τὴν ἐκκλησίαν. τῇ δ’ ὑστεραίᾳ πάλιν τοῦ δήμου συνελθόντος πολλὰ ποιήσας καὶ εἰπὼν ἔπεισε μόλις ἐπισχεῖν τὰ πρὸς Ἀργείους, αὐτὸν δὲ πέμψαι πρὸς Λακεδαιμονίους, ὡς πάντων καλῶς γενησομένων.", "st": "Nic. 10.3"}, {"sp": "N", "t": "ἐλθὼν δ’ εἰς Σπάρτην τἆλλα μὲν ὡς ἀνὴρ ἀγαθὸς καὶ πρόθυμος εἰς αὐτοὺς ἐτιμήθη, πράξας δ’ οὐδέν, ἀλλὰ κρατηθεὶς ὑπὸ τῶν βοιωτιαζόντων ἐπανῆλθεν, οὐ μόνον ἀδοξῶν καὶ κακῶς ἀκούων, ἀλλὰ καὶ δεδιὼς τοὺς Ἀθηναίους λυπουμένους καὶ ἀγανακτοῦντας ὅτι πεισθέντες ὑπ’ ἐκείνου τοσούτους καὶ τοιούτους ἄνδρας ἀπέδωκαν· οἱ γὰρ ἐκ Πύλου κομισθέντες ἦσαν ἐξ οἴκων τε πρώτων τῆς Σπάρτης, καὶ φίλους καὶ συγγενεῖς τοὺς δυνατωτάτους ἔχοντες. οὐ μὴν ἔπραξάν τι τραχύτερον ὀργῇ πρὸς ἐκεῖνον, ἀλλὰ τὸν Ἀλκιβιάδην στρατηγὸν εἵλοντο, καὶ Μαντινεῖς καὶ Ἠλείους Λακεδαιμονίων ἀποστάντας ἐποιήσαντο συμμάχους μετ’ Ἀργείων, καὶ λῃστὰς εἰς Πύλον ἔπεμψαν κακουργεῖν τὴν Λακωνικήν· ἐξ ὧν αὖθις εἰς πόλεμον κατέστησαν.", "st": "Nic. 10.7"}, {"sp": "N", "t": "ἀκμαζούσης δὲ τῆς πρὸς τὸν Νικίαν τοῦ Ἀλκιβιάδου διαφορᾶς, καὶ γιγνομένης ὀστρακοφορίας, ἣν εἰώθει διὰ χρόνου τινὸς ὁ δῆμος ποιεῖσθαι, ἕνα τῶν ὑπόπτων ἢ διὰ δόξαν ἄλλως ἢ πλοῦτον ἐπιφθόνων ἀνδρῶν τῷ ὀστράκῳ μεθιστὰς εἰς δέκα ἔτη, πολὺς θόρυβος ἀμφοτέρους περιΐστατο καὶ κίνδυνος, ὡς θατέρου πάντως ὑποπεσουμένου τῷ ἐξοστρακισμῷ. τοῦ μὲν γὰρ Ἀλκιβιάδου καὶ τὸν βίον ἐβδελύττοντο καὶ τὸ θράσος ὠρρώδουν, ὡς μᾶλλον ἐν τοῖς περὶ ἐκείνου γραφομένοις δηλοῦται, τὸν δὲ Νικίαν ὅ τε πλοῦτος ἐπίφθονον ἐποίει καὶ μάλιστα τῆς διαίτης τὸ μὴ φιλάνθρωπον μηδὲ δημοτικόν, ἀλλ’ ἄμικτον καὶ ὀλιγαρχικὸν ἀλλόκοτον ἐδόκει, πολλὰ δ’ ἤδη ταῖς ἐπιθυμίαις αὐτῶν ἀντιτείνων, παρὰ γνώμην βιαζόμενος πρὸς τὸ συμφέρον, ἐπαχθὴς ἦν. ὡς δ’ ἁπλῶς εἰπεῖν, νέων ἦν καὶ πολεμοποιῶν ἅμιλλα πρὸς εἰρηνοποιοὺς καὶ πρεσβυτέρους, τῶν μὲν εἰς τοῦτον, τῶν δ’ εἰς ἐκεῖνον τὸ ὄστρακον τρεπόντων.", "st": "Nic. 11.1"}, {"sp": "N", "t": "ἐν δὲ διχοστασίῃ καὶ ὁ πάγκακος ἔμμορε τιμῆς·", "st": "Nic. 11.1b"}, {"sp": "N", "t": "ὥς που καὶ τότε διαστὰς ὁ δῆμος δίχα χώραν ἔδωκε τοῖς ἰταμωτάτοις καὶ πανουργοτάτοις, ὧν ἦν καὶ Ὑπέρβολος ὁ Περιθοίδης, ἄνθρωπος ἀπ’ οὐδεμιᾶς τολμῶν δυνάμεως, ἀλλ’ ἀπὸ τοῦ τολμᾶν εἰς δύναμιν προελθών, καὶ γενόμενος δι’ ἣν εἶχεν ἐν τῇ πόλει δόξαν ἀδοξία τῆς πόλεως. οὗτος ἐν τῷ τότε χρόνῳ τοῦ μὲν ὀστράκου πόρρω τιθέμενος ἑαυτόν, ἅτε δὴ τῷ κύφωνι μᾶλλον προσήκων, ἐλπίζων δὲ θατέρου τῶν ἀνδρῶν ἐκπεσόντος αὐτὸς ἀντίπαλος τῷ λειπομένῳ γενέσθαι, καταφανὴς ἦν ἡδόμενός τε τῇ διαφορᾷ καὶ παροξύνων τὸν δῆμον ἐπ’ ἀμφοτέρους. συνιδόντες οὖν τὴν μοχθηρίαν οἱ περὶ τὸν Νικίαν καὶ τὸν Ἀλκιβιάδην, καὶ λόγον δόντες ἀλλήλοις κρύφα, καὶ τὰς στάσεις συναγαγόντες εἰς ἓν ἀμφοτέρας καὶ ἀναμίξαντες, ἐκράτησαν ὥστε μηδέτερον αὐτῶν, ἀλλὰ τὸν Ὑπέρβολον ἐξοστρακισθῆναι.", "st": "Nic. 11.4"}, {"sp": "N", "t": "καὶ παραυτίκα μὲν ἡδονὴν τοῦτο καὶ γέλωτα τῷ δήμῳ παρέσχεν, ὕστερον δὲ ἠγανάκτουν ὡς καθυβρισμένον τὸ πρᾶγμα τοῦτο πρὸς ἄνθρωπον ἀνάξιον γεγονέναι νομίζοντες, εἶναι γάρ τι καὶ κολάσεως ἀξίωμα, μᾶλλον δὲ κόλασιν τὸν ἐξοστρακισμὸν ἡγούμενοι Θουκυδίδῃ καὶ Ἀριστείδῃ καὶ τοῖς ὁμοίοις, Ὑπερβόλῳ δὲ τιμὴν καὶ προσποίησιν ἀλαζονείας, εἰ διὰ μοχθηρίαν ἔπαθε ταὐτὰ τοῖς ἀρίστοις, ὥς που καὶ Πλάτων ὁ κωμικὸς εἴρηκε περὶ αὐτοῦ.", "st": "Nic. 11.5"}, {"sp": "N", "t": "καίτοι πέπραχε τῶν προτέρων μὲν ἄξια,<br>αὑτοῦ δὲ καὶ τῶν στιγμάτων ἀνάξια·", "st": "Nic. 11.6"}, {"sp": "N", "t": "οὐ γὰρ τοιούτων εἵνεκ’ ὄστραχ’ εὑρέθη.", "st": "Nic. 11.6b"}, {"sp": "N", "t": "καὶ τὸ πέρας οὐδεὶς ἔτι τὸ παράπαν ἐξωστρακίσθη μετὰ Ὑπέρβολον, ἀλλ’ ἔσχατος ἐκεῖνος, πρῶτος δ’ Ἵππαρχος ὁ Χολαργεὺς συγγενής τις ὢν τοῦ τυράννου.", "st": "Nic. 11.6c"}, {"sp": "N", "t": "ἄκριτον δ’ ἡ τύχη πρᾶγμα καὶ ἄληπτον λογισμῷ. Νικίας γάρ, εἰ τὸν περὶ ὀστράκου κίνδυνον ἀνέρριψε πρὸς Ἀλκιβιάδην, ἢ κρατήσας ἂν ἀσφαλῶς ᾤκει τὴν πόλιν ἐκεῖνον ἐξελάσας, ἢ κρατηθεὶς αὐτὸς ἐξῄει πρὸ τῶν ἐσχάτων ἀτυχιῶν, τὸ δοκεῖν ἄριστος εἶναι στρατηγὸς διαφυλάξας.", "st": "Nic. 11.7"}, {"sp": "N", "t": "οὐκ ἀγνοῶ δ’ ὅτι Θεόφραστος ἐξοστρακισθῆναί φησι τὸν Ὑπέρβολον Φαίακος, οὐ Νικίου, πρὸς Ἀλκιβιάδην ἐρίσαντος. ἀλλ’ οἱ πλείονες οὕτω γεγράφασιν.", "st": "Nic. 11.7b"}, {"sp": "N", "t": "ὁ δ’ οὖν Νικίας, τῶν Αἰγεστέων πρέσβεων καὶ Λεοντίνων παραγενομένων καὶ πειθόντων τοὺς Ἀθηναίους στρατεύειν ἐπὶ Σικελίαν, ἀνθιστάμενος ἡττᾶτο τῆς βουλῆς Ἀλκιβιάδου καὶ φιλοτιμίας, πρὶν ὅλως ἐκκλησίαν γενέσθαι, κατασχόντος ἤδη πλῆθος ἐλπίσι καὶ λόγοις προδιεφθαρμένον, ὥστε καὶ νέους ἐν παλαίστραις καὶ γέροντας ἐν ἐργαστηρίοις καὶ ἡμικυκλίοις συγκαθεζομένους ὑπογράφειν τὸ σχῆμα τῆς Σικελίας, καὶ τὴν φύσιν τῆς περὶ αὐτὴν θαλάσσης, καὶ λιμένας καὶ τόπους οἷς τέτραπται πρὸς Λιβύην ἡ νῆσος. οὐ γὰρ ἆθλον ἐποιοῦντο τοῦ πολέμου Σικελίαν, ἀλλ’ ὁρμητήριον, ὡς ἀπ’ αὐτῆς διαγωνισόμενοι πρὸς Καρχηδονίους καὶ σχήσοντες ἅμα Λιβύην καὶ τὴν ἐντὸς Ἡρακλείων στηλῶν θάλασσαν.", "st": "Nic. 12.1"}, {"sp": "N", "t": "ὡς οὖν ὥρμηντο πρὸς ταῦτα, ὁ Νικίας ἐναντιούμενος οὔτε πολλοὺς οὔτε δυνατοὺς εἶχε συναγωνιστάς. οἱ γὰρ εὔποροι δεδιότες μὴ δοκῶσι τὰς λειτουργίας καὶ τριηραρχίας ἀποδιδράσκειν, παρὰ γνώμην ἡσύχαζον· ὁ δ’ οὐκ ἔκαμνεν οὐδ’ ἀπηγόρευεν, ἀλλὰ καὶ μετὰ τὸ ψηφίσασθαι τὸν πόλεμον Ἀθηναίους καὶ στρατηγὸν ἑλέσθαι πρῶτον ἐκεῖνον μετ’ Ἀλκιβιάδου καὶ Λαμάχου, πάλιν ἐκκλησίας γενομένης, ἀναστὰς ἀπέτρεπε καὶ διεμαρτύρετο, καὶ τελευτῶν διέβαλε τὸν Ἀλκιβιάδην ἰδίων ἕνεκα κερδῶν καὶ φιλοτιμίας τὴν πόλιν εἰς χαλεπὸν ἐξωθεῖν καὶ διαπόντιον κίνδυνον. ἔπραξε δ’ οὐδὲν μᾶλλον, ἀλλ’ ὑπὸ ἐμπειρίας δόξας ἐπιτηδειότερος εἶναι, καὶ πολλὴν ἀσφάλειαν ἕξειν πρὸς τὴν Ἀλκιβιάδου τόλμαν καὶ τὴν Λαμάχου τραχύτητα τῆς ἐκείνου συγκεραννυμένης εὐλαβείας, βεβαιοτέραν ἐποίησε τὴν χειροτονίαν. ἀναστὰς γὰρ ὁ μάλιστα τῶν δημαγωγῶν ἐπὶ τὸν πόλεμον παροξύνων τοὺς Ἀθηναίους, Δημόστρατος, ἔφη τὸν Νικίαν προφάσεις λέγοντα παύσειν· καὶ ψήφισμα γράψας ὅπως αὐτοκράτορες ὦσιν οἱ στρατηγοὶ κἀνταῦθα κἀκεῖ βουλευόμενοι καὶ πράττοντες, ἔπεισε τὸν δῆμον ψηφίσασθαι.", "st": "Nic. 12.3"}, {"sp": "N", "t": "καίτοι λέγεται πολλὰ καὶ παρὰ τῶν ἱερέων ἐναντιοῦσθαι πρὸς τὴν στρατείαν· ἀλλ’ ἑτέρους ἔχων μάντεις ὁ Ἀλκιβιάδης ἐκ δή τινων λογίων προὔφερε παλαιῶν μέγα κλέος τῶν Ἀθηναίων ἀπὸ Σικελίας ἔσεσθαι. καὶ θεοπρόποι τινὲς αὐτῷ παρ’ Ἄμμωνος ἀφίκοντο χρησμὸν κομίζοντες ὡς λήψονται Συρακουσίους ἅπαντας Ἀθηναῖοι· τὰ δ’ ἐναντία φοβούμενοι δυσφημεῖν ἔκρυπτον. οὐδὲ γὰρ τὰ προὖπτα καὶ καταφανῆ τῶν σημείων ἀπέτρεπεν, ἥ τε τῶν Ἑρμῶν περικοπή, μιᾷ νυκτὶ πάντων ἀκρωτηριασθέντων πλὴν ἑνός, ὃν Ἀνδοκίδου καλοῦσιν, ἀνάθημα μὲν τῆς Αἰγηΐδος φυλῆς, κείμενον δὲ πρὸ τῆς τότε οὔσης Ἀνδοκίδου οἰκίας, καὶ τὸ πραχθὲν περὶ τὸν βωμὸν τῶν δώδεκα θεῶν. ἄνθρωπος γάρ τις ἐξαίφνης ἀναπηδήσας ἐπ’ αὐτόν, εἶτα περιβὰς ἀπέκοψεν αὑτοῦ λίθῳ τὸ αἰδοῖον.", "st": "Nic. 13.1"}, {"sp": "N", "t": "ἐν δὲ Δελφοῖς Παλλάδιον ἕστηκε χρυσοῦν ἐπὶ φοίνικος χαλκοῦ βεβηκός, ἀνάθημα τῆς πόλεως ἀπὸ τῶν Μηδικῶν ἀριστείων· τοῦτ’ ἔκοπτον ἐφ’ ἡμέρας πολλὰς προσπετόμενοι κόρακες, καὶ τὸν καρπὸν ὄντα χρυσοῦν τοῦ φοίνικος ἀπέτρωγον καὶ κατέβαλλον. οἱ δὲ ταῦτα μὲν ἔφασαν εἶναι Δελφῶν πλάσματα πεπεισμένων ὑπὸ Συρακουσίων· χρησμοῦ δέ τινος κελεύοντος αὐτοὺς ἐκ Κλαζομενῶν τὴν ἱέρειαν τῆς Ἀθηνᾶς ἄγειν, μετεπέμψαντο τὴν ἄνθρωπον· ἐκαλεῖτο δὲ Ἡσυχία. καὶ τοῦτο ἦν, ὡς ἔοικεν, ὃ παρῄνει τῇ πόλει τὸ δαιμόνιον ἐν τῷ παρόντι, τὴν ἡσυχίαν ἄγειν.", "st": "Nic. 13.3"}, {"sp": "N", "t": "εἴτε δὴ ταῦτα δείσας εἴτ’ ἀνθρωπίνῳ λογισμῷ τὴν στρατείαν φοβηθείς, ὁ ἀστρολόγος Μέτων (ἦν γὰρ ἐφ’ ἡγεμονίας τινὸς τεταγμένος) προσεποιεῖτο τὴν οἰκίαν ὑφάπτειν ὡς μεμηνώς. οἱ δέ φασιν οὐ μανίαν σκηψάμενον, ἀλλὰ νύκτωρ ἐμπρήσαντα τὴν οἰκίαν προελθεῖν εἰς τὴν ἀγορὰν ταπεινόν, καὶ δεῖσθαι τῶν πολιτῶν ὅπως ἐπὶ συμφορᾷ τοσαύτῃ τὸν υἱὸν αὐτοῦ μέλλοντα πλεῖν τριήραρχον εἰς Σικελίαν ἀφῶσι τῆς στρατείας. Σωκράτει δὲ τῷ σοφῷ τὸ δαιμόνιον οἷς εἰώθει συμβόλοις χρησάμενον πρὸς αὐτὸν ἐμήνυσε κἀκεῖνα, τὸν ἔκπλουν ἐπ’ ὀλέθρῳ τῆς πόλεως πραττόμενον. ὁ δὲ τοῖς συνήθεσι καὶ φίλοις ἔφρασε, καὶ διῆλθεν εἰς πολλοὺς ὁ λόγος.", "st": "Nic. 13.5"}, {"sp": "N", "t": "οὐκ ὀλίγους δὲ καὶ τὰ τῶν ἡμερῶν ἐν αἷς τὸν στόλον ἐξέπεμπον ὑπέθραττεν. Ἀδώνια γὰρ εἶχον αἱ γυναῖκες τότε, καὶ προὔκειτο πολλαχόθι τῆς πόλεως εἴδωλα, καὶ ταφαὶ περὶ αὐτὰ καὶ κοπετοὶ γυναικῶν ἦσαν, ὥστε τοὺς ἐν λόγῳ ποιουμένους τινὶ τὰ τοιαῦτα δυσχεραίνειν καὶ δεδιέναι περὶ τῆς παρασκευῆς ἐκείνης καὶ δυνάμεως, μὴ λαμπρότητα καὶ ἀκμὴν ἐπιφανεστάτην σχοῦσα ταχέως μαρανθῇ.", "st": "Nic. 13.7"}, {"sp": "N", "t": "τὸ μὲν οὖν ἐναντιωθῆναι ψηφιζομένῃ τῇ στρατείᾳ τὸν Νικίαν, καὶ μήθ’ ὑπ’ ἐλπίδων ἐπαρθέντα μήτε πρὸς τὸ τῆς ἀρχῆς μέγεθος ἐκπλαγέντα μεταθέσθαι τὴν γνώμην, ἀνδρὸς ἦν χρηστοῦ καὶ σώφρονος· ἐπεὶ δ’ οὔτε τοῦ πολέμου τὸν δῆμον ἀποτρέψαι πειρώμενος οὔθ’ αὑτὸν ἐξελέσθαι τῆς στρατηγίας δεόμενος ἴσχυσεν, ἀλλ’ ὥσπερ ἀράμενος καὶ φέρων αὐτὸν ὁ δῆμος ἐπέθηκε τῇ δυνάμει στρατηγόν, οὐδεὶς ἔτι καιρὸς ἦν τῆς πολλῆς εὐλαβείας καὶ μελλήσεως, ὥστε παιδὸς δίκην ἀπὸ τῆς νεὼς ὀπίσω βλέποντα καὶ τὸ μὴ κρατηθῆναι τοῖς λογισμοῖς ἀναλαμβάνοντα καὶ στρέφοντα πολλάκις ἐναμβλῦναι καὶ τοὺς συνάρχοντας αὐτῷ καὶ τὴν ἀκμὴν διαφθεῖραι τῶν πράξεων, ἀλλ’ εὐθὺς ἔδει τοῖς πολεμίοις ἐμφύντα καὶ προσκείμενον ἐλέγχειν τὴν τύχην ἐπὶ τῶν ἀγώνων. ὁ δέ, Λαμάχου μὲν ἄντικρυς ἀξιοῦντος πλεῖν ἐπὶ Συρακούσας καὶ μάχην ἔγγιστα τῆς πόλεως τιθέναι, Ἀλκιβιάδου δὲ τὰς πόλεις ἀφιστάναι Συρακουσίων, εἶθ’ οὕτως ἐπ’ αὐτοὺς βαδίζειν, τὰ ἐναντία λέγων καὶ κελεύων ἀτρέμα παρὰ τὴν Σικελίαν κομιζομένους καὶ περιπλέοντας ἐπιδείξασθαι τὰ ὅπλα καὶ τὰς τριήρεις, εἶτ’ ἀποπλεῖν Ἀθήναζε μικρὸν τῆς δυνάμεως Αἰγεστεῦσιν ἀπαρξαμένους, αὐτίκα τε τὴν γνώμην ὑπεξέλυσε καὶ κατέβαλε τὸ φρόνημα τῶν ἀνδρῶν.", "st": "Nic. 14.1"}, {"sp": "N", "t": "καὶ μετ’ ὀλίγον χρόνον Ἀλκιβιάδην Ἀθηναίων μεταπεμψαμένων εἰς κρίσιν, λόγῳ μὲν ἀποδειχθεὶς δεύτερος ἡγεμών, δυνάμει δὲ μόνος ὤν, οὐκ ἐπαύσατο καθήμενος ἢ περιπλέων ἢ βουλευόμενος, πρὶν ἐγγηρᾶσαι μὲν αὐτῷ τὴν ἀκμὴν τῆς ἐλπίδος, ἐκρυῆναι δὲ τῶν πολεμίων τὸ θάμβος καὶ τὸν φόβον ὃν ἡ πρώτη παρέθηκεν αὐτοῖς ὄψις τῶν δυνάμεων.", "st": "Nic. 14.4"}, {"sp": "N", "t": "ἔτι δὲ τοῦ Ἀλκιβιάδου παρόντος ἑξήκοντα ναυσὶ πλεύσαντες ἐπὶ Συρακούσας, τὰς μὲν ἄλλας ἀνεῖχον ὑπὲρ τοῦ λιμένος ἔξω παρατάξαντες, δέκα δὲ κατήλαυνον εἴσω κατασκοπῆς εἵνεκα· καὶ Λεοντίνους ἐπὶ τὴν οἰκείαν ἀποκαλοῦσαι διὰ κήρυκος, αὗται λαμβάνουσι ναῦν πολεμίαν σανίδας κομίζουσαν, εἰς ἃς ἀπεγράφοντο κατὰ φυλὰς αὑτοὺς οἱ Συρακούσιοι· κείμεναι δ’ ἄπωθεν τῆς πόλεως ἐν ἱερῷ Διὸς Ὀλυμπίου τότε πρὸς ἐξέτασιν καὶ κατάλογον τῶν ἐν ἡλικίᾳ μετεπέμφθησαν. ὡς οὖν ὑπὸ τῶν Ἀθηναίων ἁλοῦσαι πρὸς τοὺς στρατηγοὺς ἐκομίσθησαν καὶ τὸ πλῆθος ὤφθη τῶν ὀνομάτων, ἠχθέσθησαν οἱ μάντεις μή ποτε ἄρα τὸ χρεὼν ἐνταῦθα τοῦ χρησμοῦ περαίνοι, λέγοντος ὡς Ἀθηναῖοι λήψονται Συρακουσίους ἅπαντας. οὐ μὴν ἀλλ’ ἑτέρῳ φασιν ἔργῳ τοῦτο τοῖς Ἀθηναίοις γενέσθαι ἐπιτελὲς καθ’ ὃν χρόνον ἀποκτείνας Δίωνα Κάλλιππος ὁ Ἀθηναῖος ἔσχε Συρακούσας.", "st": "Nic. 14.5"}, {"sp": "N", "t": "ἀποπλεύσαντος δὲ τοῦ Ἀλκιβιάδου μετ’ ὀλίγον ἐκ Σικελίας, τὸ πᾶν ἤδη κράτος ὁ Νικίας ἔσχεν. ὁ δὲ Λάμαχος ἦν μὲν ἀνδρώδης καὶ δίκαιος ἀνὴρ καὶ τῇ χειρὶ χρώμενος ἀφειδῶς κατὰ τὰς μάχας, πένης δὲ τοσοῦτον καὶ λιτὸς ὥστε καθ’ ἑκάστην στρατηγίαν ἀπολογίζεσθαι τοῖς Ἀθηναίοις μικρὸν ἀργύριον εἰς ἐσθῆτα καὶ κρηπῖδας ἑαυτῷ. τοῦ δὲ Νικίου καὶ διὰ τἆλλα μέγας ἦν καὶ διὰ τὸν πλοῦτον καὶ διὰ τὴν δόξαν ὁ ὄγκος. λέγεται δ’ ἐν τῷ στρατηγίῳ ποτὲ βουλευομένων τι κοινῇ τῶν συναρχόντων, κελευσθεὶς ὑπ’ αὐτοῦ πρῶτος εἰπεῖν γνώμην Σοφοκλῆς ὁ ποιητὴς ὡς πρεσβύτατος ὢν τῶν συστρατήγων, ἐγώ, φάναι, παλαιότατος εἰμί, σὺ δὲ πρεσβύτατος.", "st": "Nic. 15.1"}, {"sp": "N", "t": "οὕτω δὴ καὶ τότε τὸν Λάμαχον ἄγων ὑφ’ ἑαυτῷ στρατηγικώτερον ὄντα, καὶ χρώμενος εὐλαβῶς καὶ διὰ μελλήσεως ἀεὶ τῇ δυνάμει, πρῶτον μὲν ἀπωτάτω τῶν πολεμίων ἐκπεριπλέων Σικελίαν θάρσος ἔδωκεν αὐτοῖς, ἔπειτα προσβαλὼν Ὕβλῃ, πολιχνίῳ μικρῷ, καὶ πρὶν ἑλεῖν ἀποστάς, κομιδῇ κατεφρονήθη. καὶ τέλος εἰς Κατάνην ἀπῆλθε πράξας οὐδὲν ἢ καταστρεψάμενος Ὕκκαρα, βαρβαρικὸν χωρίον, ὅθεν λέγεται καὶ Λαΐδα τὴν ἑταίραν ἔτι κόρην ἐν τοῖς αἰχμαλώτοις πραθεῖσαν εἰς Πελοπόννησον κομισθῆναι.", "st": "Nic. 15.3"}, {"sp": "N", "t": "τοῦ δὲ θέρους διελθόντος, ἐπεὶ τοὺς Συρακουσίους ἐπυνθάνετο προτέρους ἐπ’ αὐτοὺς ἀφίξεσθαι τεθαρρηκότας, οἱ δ’ ἱππεῖς ὕβρει προσελαύνοντες ἤδη πρὸς τὸ στρατόπεδον ἠρώτων εἰ Καταναίοις συνοικήσοντες ἢ Λεοντίνους κατοικιοῦντες ἥκουσι, μόλις ὁ Νικίας ὥρμησε πλεῖν ἐπὶ Συρακούσας. καὶ βουλόμενος ἀδεῶς καὶ καθ’ ἡσυχίαν ἱδρῦσαι τὸν στρατόν, ὑπέπεμψεν ἄνθρωπον ἐκ Κατάνης κελεύοντα τοὺς Συρακουσίους, εἰ βούλονται λαβεῖν ἔρημον ἀνδρῶν τὸ στρατόπεδον καὶ τὰ ὅπλα τῶν Ἀθηναίων, ἐν ἡμέρᾳ ῥητῇ πρὸς Κατάνην πανστρατιᾷ παραγενέσθαι, τῶν δ’ Ἀθηναίων ἐν τῇ πόλει τὰ πλεῖστα διατριβόντων ἐγνωκέναι τοὺς Συρακουσίων φίλους, ὅταν ἐκείνους προσιόντας αἴσθωνται, τάς τε πύλας καταλαμβάνειν ἅμα καὶ τὸν ναύσταθμον ὑποπιμπράναι· πολλοὺς δὲ εἶναι τοὺς συνεστῶτας ἤδη καὶ τὴν ἐκείνων περιμένοντας ἄφιξιν.", "st": "Nic. 16.1"}, {"sp": "N", "t": "τοῦτ’ ἄριστα Νικίας ἐστρατήγησε περὶ Σικελίαν. πανστρατιᾷ γὰρ ἐξαγαγὼν τοὺς πολεμίους καὶ τὴν πόλιν ὁμοῦ τι ποιήσας ἔρημον ἀνδρῶν, αὐτὸς ἐκ Κατάνης ἀναχθεὶς τῶν τε λιμένων ἐκράτησε καὶ τῷ στρατοπέδῳ κατέλαβε χώραν, ὅθεν ἥκιστα βλαπτόμενος οἷς ἐλείπετο τῶν πολεμίων, ἤλπιζεν ἐξ ὧν ἐθάρρει πολεμήσειν ἀκωλύτως. ἐπεὶ δ’ ἀναστρέψαντες ἐκ Κατάνης οἱ Συρακούσιοι παρετάξαντο πρὸ τῆς πόλεως, ἐπαγαγὼν ταχὺ τοὺς Ἀθηναίους ἐκράτησε. καὶ πολλοὺς μὲν οὐκ ἀπέκτεινε τῶν πολεμίων· οἱ γὰρ ἱππεῖς ἐμποδὼν ἐγένοντο τῇ διώξει· τοῦ δὲ ποταμοῦ διαφθείρων καὶ ἀποκόπτων τὰς γεφύρας, παρέσχεν Ἑρμοκράτει λέγειν παραθαρρύνοντι τοὺς Συρακουσίους ὅτι γελοῖός ἐστιν ὁ Νικίας, ὅπως οὐ μαχεῖται στρατηγῶν, ὥσπερ οὐκ ἐπὶ μάχῃ πεπλευκώς. οὐ μὴν ἀλλὰ φόβον τε καὶ κατάπληξιν ἰσχυρὰν ἐνειργάσατο τοῖς Συρακουσίοις, ὥστ’ ἀντὶ τῶν ὄντων τότε πεντεκαίδεκα στρατηγῶν ἑτέρους ἑλέσθαι τρεῖς, οἷς πίστιν ἔδωκεν ὁ δῆμος δι’ ὅρκων, ἦ μὴν ἐάσειν ἄρχειν αὐτοκράτορας.", "st": "Nic. 16.3"}, {"sp": "N", "t": "τοῦ δ’ Ὀλυμπιείου πλησίον ὄντος ὥρμησαν οἱ Ἀθηναῖοι καταλαβεῖν, πολλῶν ὄντων ἐν αὐτῷ χρυσῶν καὶ ἀργυρῶν ἀναθημάτων. ὁ δὲ Νικίας ἐπίτηδες ἀναβαλλόμενος ὑστέρησε καὶ περιεῖδε φρουρὰν εἰσελθοῦσαν παρὰ τῶν Συρακουσίων, ἡγούμενος, ἐὰν τὰ χρήματα διαρπάσωσιν οἱ στρατιῶται, τὸ μὲν κοινὸν οὐκ ὠφεληθήσεσθαι, τὴν δ’ αἰτίαν αὐτὸς ἕξειν τοῦ ἀσεβήματος. τῇ δὲ νίκῃ περιβοήτῳ γενομένῃ χρησάμενος εἰς οὐδέν, ὀλίγων ἡμερῶν διαγενομένων αὖθις ἀνεχώρησεν εἰς Νάξον, κἀκεῖ διεχείμασε, πολλὰ μὲν ἀναλίσκων στρατιᾷ τοσαύτῃ, πράττων δὲ μικρὰ πρὸς Σικελούς τινας ἀφισταμένους πρὸς αὐτόν, ὥστε τοὺς Συρακουσίους αὖθις ἀναθαρρήσαντας ἐξελάσαι πρὸς Κατάνην καὶ τήν τε χώραν τεμεῖν καὶ τὸ στρατόπεδον κατακαῦσαι τῶν Ἀθηναίων.", "st": "Nic. 16.6"}, {"sp": "N", "t": "ἃ δὴ πάντες ᾐτιῶντο τὸν Νικίαν, ὡς ἐν τῷ διαλογίζεσθαι καὶ μέλλειν καὶ φυλάττεσθαι τὸν τῶν πράξεων ἀπολλύντα καιρόν· ἐπεὶ τάς γε πράξεις οὐδεὶς ἂν ἐμέμψατο τοῦ ἀνδρός· ὁρμήσας γὰρ ἦν ἐνεργὸς καὶ δραστήριος, τολμῆσαι δὲ μελλητὴς καὶ ἄτολμος.", "st": "Nic. 16.8"}, {"sp": "N", "t": "ὡς δ’ οὖν ἐκίνησε τὴν στρατιὰν πάλιν ἐπὶ τὰς Συρακούσας, οὕτως ἐστρατήγησε καὶ μετὰ τοσαύτης ὀξύτητος ἅμα καὶ ἀσφαλείας ἐπῆλθεν, ὥστε λαθεῖν μὲν εἰς Θάψον ταῖς ναυσὶ προσμίξας καὶ ἀποβάς, φθάσαι δὲ τὰς Ἐπιπολὰς κατασχών, τῶν δὲ προσβοηθούντων λογάδων κρατήσας ἑλεῖν μὲν τριακοσίους, τρέψασθαι δὲ καὶ τὴν ἵππον τῶν πολεμίων ἄμαχον εἶναι δοκοῦσαν.", "st": "Nic. 17.1"}, {"sp": "N", "t": "ὃ δὲ πάντων μάλιστα καὶ Σικελιώτας ἐξέπληξε καὶ τοῖς Ἕλλησιν ἀπιστίαν παρέσχεν, ὀλίγῳ χρόνῳ περιετείχισε Συρακούσας, πόλιν Ἀθηνῶν οὐκ ἐλάττονα, δυσεργοτέραν δὲ χωρίων ἀνωμαλίαις καὶ θαλάσσῃ γειτνιώσῃ καὶ παρακειμένοις ἕλεσι τεῖχος κύκλῳ περὶ αὐτὴν τοσοῦτον ἀγαγεῖν. ἀλλὰ τοῦτ’ ἐξεργάσασθαι μικρὸν ἐδέησε τοῦ παντὸς ἄνθρωπος οὐδ’ ὑγιαίνοντι χρώμενος ἑαυτῷ πρὸς τοσαύτας φροντίδας, ἀλλὰ νόσον νοσῶν νεφρῖτιν, ἧς τὸ μὴ προσεκπονηθὲν λεῖμμα ποιεῖσθαι δίκαιόν ἐστι. θαυμάζω δὲ τοῦ στρατηγοῦ τὴν ἐπιμέλειαν καὶ τὴν τῶν στρατιωτῶν ἀνδραγαθίαν ἐν οἷς κατώρθουν. ὁ μὲν γὰρ Εὐριπίδης μετὰ τὴν ἧτταν αὐτῶν καὶ τὸν ὄλεθρον γράφων ἐπικήδειον ἐποίησεν·", "st": "Nic. 17.2"}, {"sp": "N", "t": "οἵδε Συρακοσίους ὀκτὼ νίκας ἐκράτησαν<br>ἄνδρες, ὅτ’ ἦν τὰ θεῶν ἐξ ἴσου ἀμφοτέροις·", "st": "Nic. 17.2b"}, {"sp": "N", "t": "οὐκ ὀκτὼ δὲ νίκας, ἀλλὰ πλείονας ἄν τις εὕροι Συρακουσίους νενικημένους ὑπ’ αὐτῶν, πρὶν ἐκ θεῶν ὄντως ἢ τύχης ἀντίστασίν τινα γενέσθαι τοῖς Ἀθηναίοις ἐπὶ πλεῖστον αἰρομένοις δυνάμεως.", "st": "Nic. 17.5"}, {"sp": "N", "t": "ταῖς μὲν οὖν πλείσταις πράξεσι βιαζόμενος τὸ σῶμα παρῆν ὁ Νικίας· ἀκμὴν δέ ποτε τῆς ἀρρωστίας λαβούσης ὁ μὲν ἐν τείχεσι μετ’ ὀλίγων ὑπηρετῶν κατέκειτο, τὴν δὲ στρατιὰν ἔχων ὁ Λάμαχος προσεμάχετο τοῖς Συρακουσίοις ἐκ τῆς πόλεως τεῖχος ἀνάγουσι πρὸς τὸ τῶν Ἀθηναίων, ὃ κωλύσειν ἔμελλε διὰ μέσου τὸν ἀποτειχισμόν. τῷ δὲ κρατεῖν τῶν Ἀθηναίων ἀτακτότερον φερομένων πρὸς τὰς διώξεις, ἀπομονωθεὶς ὁ Λάμαχος ὑπέστη τῶν Συρακουσίων τοὺς ἱππεῖς ἐπιφερομένους. ἦν δὲ πρῶτος αὐτῶν Καλλικράτης, ἀνὴρ πολεμικὸς καὶ θυμοειδής. πρὸς τοῦτον ἐκ προκλήσεως καταστὰς ὁ Λάμαχος ἐμονομάχησε, καὶ λαβὼν πληγὴν πρότερος, εἶτα δοὺς καὶ πεσὼν ὁμοῦ συναπέθανε τῷ Καλλικράτει. καὶ τὸ μὲν σῶμα κρατήσαντες αὐτοῦ μετὰ τῶν ὅπλων ἐξῆραν οἱ Συρακούσιοι, δρόμῳ δ’ ἐφέροντο πρὸς τὰ τείχη τῶν Ἀθηναίων, ἐν οἷς ὁ Νικίας ἦν οὐκ ἔχων τοὺς βοηθοῦντας. ὅμως δ’ ὑπὸ τῆς ἀνάγκης ἐξαναστὰς καὶ κατιδὼν τὸν κίνδυνον ἐκέλευσε τοὺς καθ’ ἑαυτόν, ὅσα ξύλα πρὸ τῶν τειχῶν ἐτύγχανεν εἰς μηχανὰς παραβεβλημένα, καὶ τὰς μηχανὰς αὐτὰς πῦρ κομίσαντας ἅψαι. τοῦτο τοὺς Συρακουσίους ἐπέσχε καὶ τὸν Νικίαν ἔσωσε καὶ τὰ τείχη καὶ τὰ χρήματα τῶν Ἀθηναίων· φλόγα γὰρ ἀρθεῖσαν διὰ μέσου πολλὴν ἰδόντες ἀπετράπησαν οἱ Συρακούσιοι.", "st": "Nic. 18.1"}, {"sp": "N", "t": "τούτων δὲ πραχθέντων ἀπολέλειπτο μὲν ὁ Νικίας μόνος τῶν στρατηγῶν, ἦν δ’ ἐλπίδος μεγάλης. καὶ γὰρ πόλεις μεθίσταντο καὶ πλοῖα μεστὰ σίτου πολλαχόθεν ἦλθεν εἰς τὸ στρατόπεδον, τοῖς πράγμασιν εὖ φερομένοις πάντων προστιθεμένων. καὶ λόγοι τινὲς ἤδη παρὰ τῶν Συρακουσίων ἐγίνοντο περὶ συμβάσεως πρὸς αὐτόν, ἀπεγνωκότων τὴν πόλιν. ὅπου καὶ Γύλιππος ἐκ Λακεδαίμονος πλέων βοηθὸς αὐτοῖς, ὡς ἤκουσε κατὰ πλοῦν τὸν ἀποτειχισμὸν καὶ τὰς ἀπορίας, οὕτως ἔπλει τὸ λοιπὸν ὡς ἐχομένης μὲν ἤδη τῆς Σικελίας, Ἰταλιώταις δὲ τὰς πόλεις διαφυλάξων, εἰ καὶ τοῦτό πως ἐγγένοιτο. μεγάλη γὰρ ἡ δόξα διεφοίτα τοῦ κρατεῖν πάντα τοὺς Ἀθηναίους καὶ στρατηγὸν ἔχειν ἄμαχον δι’ εὐτυχίαν καὶ φρόνησιν.", "st": "Nic. 18.4"}, {"sp": "N", "t": "ὁ δὲ Νικίας εὐθὺς αὐτὸς καὶ παρὰ φύσιν ὑπὸ τῆς ἐν τῷ παρόντι ῥώμης καὶ τύχης ἀνατεθαρρηκώς, μάλιστα δὲ τοῖς ἐκ Συρακουσῶν διαλεγομένοις κρύφα καὶ πέμπουσι πρὸς αὐτὸν ὅσον οὔπω τὴν πόλιν ἐνδίδοσθαι κατὰ συμβάσεις νομίζων, οὐδένα τοῦ Γυλίππου λόγον ἔσχε προσπλέοντος, οὐδὲ φυλακὴν ἐποιήσατο καθαράν, ἀλλὰ τῷ παντελῶς ὑπερορᾶσθαι καὶ καταφρονεῖσθαι λαθὼν αὐτὸν ὁ ἀνὴρ εἰσέπλευσε διὰ πορθμοῦ, καὶ προσκομισθεὶς ἀπωτάτω τῶν Συρακουσῶν στρατιὰν συνηγάγετο πολλήν, οὐδ’ εἰ πάρεστι τῶν Συρακουσίων ἐπισταμένων οὐδὲ προσδοκώντων. διὸ καὶ παρήγγελτο μὲν αὐτοῖς ἐκκλησία περὶ τῶν πρὸς τὸν Νικίαν ὁμολογιῶν, καί τινες ἐβάδιζον ἤδη, πρὶν ἢ παντελῶς ἀποτειχισθῆναι τὴν πόλιν οἰόμενοι δεῖν γενέσθαι τὰς διαλύσεις· βραχὺ γὰρ ἦν κομιδῇ τὸ ἀπολειπόμενον τοῦ ἔργου, καὶ τοῦτο παραβεβλημένην εἶχε τὴν παρασκευὴν τῆς τειχοδομίας σύμπασαν.", "st": "Nic. 18.6"}, {"sp": "N", "t": "ἐν τούτῳ δὲ καιροῦ παρόντος τοῦ κινδύνου ἀφικνεῖται Γογγύλος ἐκ Κορίνθου μιᾷ τριήρει· καὶ συνδραμόντων πρὸς αὐτόν, ὡς εἰκός, πάντων ἔφραζεν ὅτι Γύλιππος ἀφίξεται διὰ ταχέων καὶ νῆες ἄλλαι βοηθοὶ προσπλέουσιν. οὔπω δὲ τῷ Γογγύλῳ πιστευόντων βεβαίως, ἧκεν ἄγγελος παρὰ τοῦ Γυλίππου κελεύοντος ἀπαντᾶν. οἱ δὲ θαρρήσαντες ἐξωπλίζοντο· καὶ προσῆγεν εὐθὺς ὁ Γύλιππος ἐξ ὁδοῦ παρατεταγμένος ἐπὶ τοὺς Ἀθηναίους. ὡς δὲ κἀκείνους ἀντέταξεν ὁ Νικίας, θέμενος ἐπὶ τοὺς Ἀθηναίους ὁ Γύλιππος τὰ ὅπλα καὶ κήρυκα πέμψας ἔλεγε διδόναι τοῖς Ἀθηναίοις ἄδειαν ἀπιοῦσιν ἐκ Σικελίας.", "st": "Nic. 19.1"}, {"sp": "N", "t": "ὁ μὲν οὖν Νικίας οὐθὲν ἠξίωσεν ἀποκρίνασθαι· τῶν δὲ στρατιωτῶν τινες καταγελῶντες ἠρώτων εἰ διὰ παρουσίαν ἑνὸς τρίβωνος καὶ βακτηρίας Λακωνικῆς οὕτως ἰσχυρὰ τὰ Συρακουσίων ἐξαίφνης γέγονεν ὥστ’ Ἀθηναίων καταφρονεῖν, οἳ πολὺ ῥωμαλεωτέρους Γυλίππου καὶ μᾶλλον κομῶντας τριακοσίους ἔχοντες ἐν πέδαις δεδεμένους ἀπέδωκαν Λακεδαιμονίοις. Τίμαιος δὲ καὶ τοὺς Σικελιώτας φησὶν ἐν μηδενὶ λόγῳ ποιεῖσθαι τὸν Γύλιππον, ὕστερον μὲν αἰσχροκέρδειαν αὐτοῦ καὶ μικρολογίαν καταγνόντας, ὡς δὲ πρῶτον ὤφθη, σκώπτοντας εἰς τὸν τρίβωνα καὶ τὴν κόμην. εἶτα μέντοι φησὶν αὐτὸς ὅτι τῷ Γυλίππῳ φανέντι καθάπερ γλαυκὶ πολλοὶ προσέπτησαν ἑτοίμως στρατευόμενοι. καὶ ταῦτα τῶν πρώτων ἀληθέστερά εἰσιν· ἐν γὰρ τῇ βακτηρίᾳ καὶ τῷ τρίβωνι τὸ σύμβολον καὶ τὸ ἀξίωμα τῆς Σπάρτης καθορῶντες συνίσταντο. κἀκείνου τὸ πᾶν ἔργον γεγονέναι φησὶν οὐ Θουκυδίδης μόνον, ἀλλὰ καὶ Φίλιστος, ἀνὴρ Συρακούσιος καὶ τῶν πραγμάτων ὁρατὴς γενόμενος.", "st": "Nic. 19.3"}, {"sp": "N", "t": "τῇ μὲν οὖν πρώτῃ μάχῃ κρατήσαντες οἱ Ἀθηναῖοι τῶν Συρακουσίων ὀλίγους τινὰς ἀπέκτειναν καὶ Γογγύλον τὸν Κορίνθιον, εἰς δὲ τὴν ἐπιοῦσαν ἡμέραν ἔδειξεν ὁ Γύλιππος οἷόν ἐστιν ἐμπειρία. τοῖς γὰρ αὐτοῖς ὅπλοις καὶ ἵπποις καὶ χωρίοις χρησάμενος οὐχ ὡσαύτως, ἀλλὰ μεταθεὶς τὴν τάξιν, ἐνίκησε τοὺς Ἀθηναίους· καὶ φυγόντων εἰς τὸ στρατόπεδον ἐπιστήσας τοὺς Συρακουσίους, τοῖς λίθοις οἷς ἐκεῖνοι προσεκόμιζον καὶ τῇ ὕλῃ παροικοδομῶν εἰς διαστολὰς ἀπέκοψε τὸν ἐκείνων περιτειχισμόν, ὥστ’ αὐτοῖς μηδὲν εἶναι πλέον κρατοῦσιν.", "st": "Nic. 19.6"}, {"sp": "N", "t": "ἐκ τούτου δὲ θαρρήσαντες οἱ Συρακούσιοι τάς τε ναῦς ἐπλήρουν, καὶ τοῖς ἱππεῦσι τοῖς ἑαυτῶν καὶ ἀκολούθοις περιελαύνοντες πολλοὺς ᾕρουν. καὶ ὁ Γύλιππος ἐπιὼν ἐπὶ τὰς πόλεις αὐτὸς ἐξώρμα καὶ συνίστη πάντας ἐρρωμένως ὑπακούοντας αὐτῷ καὶ συλλαμβανομένους, ὥστε τὸν Νικίαν αὖθις εἰς ἐκείνους ἀποτρεπόμενον τοὺς πρώτους λογισμοὺς καὶ συμφρονοῦντα τὴν τῶν πραγμάτων μεταβολὴν ἀθυμεῖν, καὶ γράφειν τοῖς Ἀθηναίοις κελεύοντα πέμπειν ἕτερον στρατὸν ἢ καὶ τοῦτον ἀπαγαγεῖν ἐκ Σικελίας, αὑτῷ δὲ πάντως αἰτούμενον τῆς στρατηγίας ἄφεσιν διὰ τὴν νόσον.", "st": "Nic. 19.7"}, {"sp": "N", "t": "οἱ δ’ Ἀθηναῖοι καὶ πρότερον μὲν ὥρμηντο πέμπειν ἑτέραν δύναμιν εἰς Σικελίαν, φθόνῳ δὲ τῶν πρῶτον πραττομένων πρὸς εὐτυχίαν τοῦ Νικίου τοσαύτην πολλὰς διατριβὰς ἐμβαλόντων τότε γοῦν ἔσπευδον βοηθεῖν. καὶ Δημοσθένης μὲν ἔμελλε μεγάλῳ στόλῳ πλεῖν ἐκ χειμῶνος, Εὐρυμέδων δὲ διὰ χειμῶνος προεξέπλευσε χρήματα κομίζων καὶ συστρατήγους ἀποφαίνων ᾑρημένους τῷ Νικίᾳ τῶν αὐτόθι στρατευομένων Εὐθύδημον καὶ Μένανδρον.", "st": "Nic. 20.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ καὶ κατὰ γῆν καὶ κατὰ θάλατταν ἐξαίφνης ἐπιχειρούμενος ὁ Νικίας ταῖς μὲν ναυσὶν ἡττώμενος τὸ πρῶτον ὅμως ἐξέωσε καὶ κατέδυσε πολλὰς τῶν πολεμίων, πρὸς δὲ τὸ πεζὸν οὐκ ἔφθασε βοηθῶν, ἀλλ’ ἄφνω προσπεσὼν ὁ Γύλιππος εἷλε τὸ Πλημμύριον, ἐν ᾧ σκευῶν τριηρικῶν καὶ χρημάτων πολλῶν ἀποκειμένων ἐκράτησε πάντων καὶ διέφθειρεν ἄνδρας οὐκ ὀλίγους καὶ ζῶντας ἔλαβε· τὸ δὲ μέγιστον, ἀφείλετο τοῦ Νικίου τῆς ἀγορᾶς τὴν εὐπέτειαν. ἦν γὰρ ἡ κομιδὴ παρὰ τὸ Πλημμύριον ἀσφαλὴς καὶ ταχεῖα τῶν Ἀθηναίων κρατούντων, ἐκπεσόντων δὲ χαλεπὴ καὶ μετὰ μάχης ἐγίνετο πρὸς τοὺς πολεμίους ἐκεῖ ναυλοχοῦντας. ἔτι δὲ καὶ τὸ ναυτικὸν τοῖς Συρακουσίοις οὐκ ἀπὸ κράτους ἐφαίνετο νενικημένον, ἀλλ’ ἀταξίᾳ περὶ τὴν δίωξιν. αὖθις οὖν ἐπεχείρουν παρασκευαζόμενοι λαμπρότερον.", "st": "Nic. 20.2"}, {"sp": "N", "t": "ὁ δὲ Νικίας οὐκ ἐβούλετο ναυμαχεῖν, ἀλλὰ πολλὴν ἀβελτερίαν ἔλεγεν εἶναι, στόλου τοσούτου προσπλέοντος αὐτοῖς καὶ δυνάμεως ἀκραιφνοῦς, ἣν ἦγε Δημοσθένης σπεύδων, ἀπ’ ἐλαττόνων καὶ χορηγουμένων φαύλως διαγωνίσασθαι. τοῖς δὲ περὶ τὸν Μένανδρον καὶ τὸν Εὐθύδημον ἀρτίως εἰς τὴν ἀρχὴν καθισταμένοις φιλοτιμία καὶ ζῆλος ἦν πρὸς ἀμφοτέρους τοὺς στρατηγούς, τὸν μὲν Δημοσθένην φθῆναι πράξαντάς τι λαμπρόν, ὑπερβαλέσθαι δὲ τὸν Νικίαν. πρόσχημα δ’ ἦν ἡ δόξα τῆς πόλεως, ἣν ἀπόλλυσθαι καὶ καταλύεσθαι παντάπασι φάσκοντες εἰ φοβηθήσονται Συρακουσίους ἐπιπλέοντας, ἐξεβιάσαντο ναυμαχῆσαι. καὶ καταστρατηγηθέντες ὑπ’ Ἀρίστωνος τοῦ Κορινθίων κυβερνήτου τοῖς περὶ τὸ ἄριστον, ὡς εἴρηκε Θουκυδίδης, κατὰ κράτος ἡττήθησαν καὶ πολλοὺς ἀπέβαλον· καὶ ἀθυμία πολλὴ περιεστήκει τὸν Νικίαν τῇ τε μοναρχίᾳ κακοπαθοῦντα καὶ σφαλλόμενον αὖθις ὑπὸ τῶν συναρχόντων.", "st": "Nic. 20.4"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Δημοσθένης ὑπὲρ τῶν λιμένων ἐπεφαίνετο λαμπρότατος τῇ παρασκευῇ καὶ δεινότατος τοῖς πολεμίοις, ἐπὶ νεῶν ἑβδομήκοντα καὶ τριῶν ἄγων ὁπλίτας πεντακισχιλίους, ἀκοντιστὰς δὲ καὶ τοξότας καὶ σφενδονήτας τρισχιλίων οὐκ ἐλάττους, ὅπλων δὲ κόσμῳ καὶ παρασήμοις τριήρων καὶ πλήθει κελευστῶν καὶ αὐλητῶν θεατρικῶς καὶ πρὸς ἔκπληξιν πολεμίων ἐξησκημένος. ἦν οὖν, ὡς εἰκός, αὖθις ἐν φόβῳ μεγάλῳ τὰ Συρακουσίων εἰς οὐδὲν πέρας οὐδὲ ἀπαλλαγήν, ἀλλὰ πονοῦντας ἄλλως καὶ φθειρομένους αὑτοὺς μάτην ὁρώντων.", "st": "Nic. 21.1"}, {"sp": "N", "t": "τὸν δὲ Νικίαν οὐ πολὺν χρόνον εὔφρανεν ἡ παρουσία τῆς δυνάμεως, ἀλλ’ ἅμα τῷ πρῶτον ἐν λόγοις γενέσθαι, τοῦ Δημοσθένους εὐθὺς ἐπιχειρεῖν τοῖς πολεμίοις κελεύοντος καὶ τῷ ταχίστῳ τῶν κινδύνων περὶ τοῦ παντὸς διαγωνισαμένους ἑλεῖν Συρακούσας ἢ ἀποπλεῖν οἴκαδε, δείσας καὶ θαυμάσας τὴν ὀξύτητα καὶ τόλμαν ἐδεῖτο μηδὲν ἀπεγνωσμένως πράττειν μηδὲ ἀνοήτως. τὴν γὰρ τριβὴν εἶναι κατὰ τῶν πολεμίων οὔτε χρήματα κεκτημένων ἔτι, μήτε τῶν συμμάχων αὐτοῖς πολὺν χρόνον παραμενούντων, εἰ δὲ θλίβοιντο ταῖς ἀπορίαις, ταχὺ πάλιν ἐπ’ αὐτὸν ἐπὶ συμβάσεις τραπησομένων, ὡς πρότερον. καὶ γὰρ ἦσαν ἄνδρες οὐκ ὀλίγοι τῶν ἐν Συρακούσαις διαλεγόμενοι τῷ Νικίᾳ κρύφα καὶ μένειν κελεύοντες, ὡς καὶ νῦν ὑπερπονούντων τῷ πολέμῳ καὶ τὸν Γύλιππον βαρυνομένων, ἐὰν δὲ μικρὸν ἐπιτείνωσιν αἱ ἀνάγκαι, παντάπασιν ἀπαγορευσόντων. τούτων ὁ Νικίας τὰ μὲν αἰνιττόμενος, τὰ δ’ οὐ θέλων ἐν φανερῷ λέγειν, ἀτολμίας παρέσχε τοῖς στρατηγοῖς δόξαν, καὶ ταῦτ’ ἐκεῖνα πάλιν ἥκειν φάσκοντες αὐτοῦ, μελλήματα καὶ διατριβὰς καὶ ἀκριβολογίας, αἷς ἀπώλεσε τὴν ἀκμὴν οὐκ εὐθὺς ἐπιχειρῶν τοῖς πολεμίοις, ἀλλ’ ἕωλος καὶ καταφρονούμενος, τῷ Δημοσθένει προσετίθεντο. καὶ ὁ Νικίας μόλις συνεχώρησεν ἐκβιασθείς.", "st": "Nic. 21.3"}, {"sp": "N", "t": "οὕτω δὴ τὴν πεζὴν στρατιὰν ἀναλαβὼν ὁ Δημοσθένης νυκτὸς ἐπεχείρει ταῖς Ἐπιπολαῖς· καὶ τοὺς μὲν φθάσας πρὶν αἰσθέσθαι τῶν πολεμίων ἀπέκτεινε, τοὺς δ’ ἀμυνομένους ἐτρέψατο. καὶ κρατῶν οὐκ ἔμενεν, ἀλλ’ ἐχώρει προσωτέρω, μέχρι οὗ τοῖς Βοιωτοῖς ἐνέτυχε. πρῶτοι γὰρ οὗτοι συστρέψαντες ἑαυτοὺς καὶ συνδραμόντες εἰς τοὺς Ἀθηναίους ἐναντίοις τοῖς δόρασι μετὰ βοῆς ἐώσαντο καὶ πολλοὺς αὐτοῦ κατέβαλον. δι’ ὅλου δὲ τοῦ στρατεύματος εὐθὺς ἦν πτοία καὶ ταραχή, καὶ τοῦ φεύγοντος ἤδη καταπιμπλάμενον τὸ ἔτι νικῶν, καὶ τὸ ἐπιβαῖνον καὶ προσφερόμενον ὑπὸ τῶν πεφοβημένων ἀνακοπτόμενον ἑαυτῷ περιέπιπτε, τοὺς μὲν φεύγοντας οἰόμενον διώκειν, τοῖς δὲ φίλοις ὡς πολεμίοις χρώμενον. ἡ γὰρ ἄτακτος ἀνάμιξις ἐν ταὐτῷ μετὰ φόβου καὶ ἀγνοίας, καὶ τὸ τῆς ὄψεως ἄπιστον ἐν νυκτὶ μήτε σκότος ἄκρατον μήτε φῶς ἐχούσῃ βέβαιον, ἀλλ’ οἵαν εἰκὸς ἤδη καταφερομένης σελήνης καὶ περισκιαζομένης ὅπλοις πολλοῖς καὶ σώμασι κινουμένοις διὰ τοῦ φωτὸς μὴ διασαφοῦσαν τὰ εἴδη φόβῳ τοῦ πολεμίου καὶ τὸ οἰκεῖον ποιεῖν ὕποπτον, εἰς δεινὰς ἀπορίας καὶ περιπετείας καθίστη τοὺς Ἀθηναίους. ἔτυχον δέ πως καὶ τὴν σελήνην ἔχοντες ὄπισθεν· ὅθεν αὐτοὶ μὲν αὑτοῖς τὰς σκιὰς ἐπιβάλλοντες ἀπέκρυπτον τὸ πλῆθος τῶν ὅπλων καὶ τὴν λαμπρότητα, τοὺς δ’ ἐναντίους ὁ πρὸς τὴν σελήνην τῶν ἀσπίδων ἀντιφωτισμὸς πολὺ πλείονας ὁρᾶσθαι καὶ λαμπροτέρους ἐποίει.", "st": "Nic. 21.5"}, {"sp": "N", "t": "τέλος δὲ πανταχόθεν αὐτοῖς, ὡς ἐνέδοσαν, προσκειμένων τῶν πολεμίων φεύγοντες οἱ μὲν ὑπ’ ἐκείνων, οἱ δ’ ὑπ’ ἀλλήλων ἀπέθνησκον, οἱ δὲ κατὰ τῶν κρημνῶν ὀλισθαίνοντες· τοὺς δ’ ἀποσκεδασθέντας καὶ πλανωμένους ἡμέρας ἐπιγενομένης οἱ ἱππεῖς καταλαμβάνοντες διέφθειρον. ἐγένοντο δὲ νεκροὶ δισχίλιοι, καὶ τῶν περιγενομένων ὀλίγοι μετὰ τῶν ὅπλων ἀπεσώθησαν.", "st": "Nic. 21.9"}, {"sp": "N", "t": "ὁ μὲν οὖν Νικίας πληγεὶς οὐκ ἀπροσδοκήτως ᾐτιᾶτο τοῦ Δημοσθένους τὴν προπέτειαν· ἐκεῖνος δὲ περὶ τούτων ἀπολογησάμενος ἐκέλευσεν ἀποπλεῖν τὴν ταχίστην· οὔτε γὰρ ἄλλην ἀφίξεσθαι δύναμιν αὐτοῖς, οὔτ’ ἀπὸ τῆς παρούσης τῶν πολεμίων κρατεῖν, ὅπου γε καὶ κρατοῦντας ἐκείνων ἔδει μεταστῆναι καὶ φυγεῖν τὸ χωρίον, ἀεὶ μέν, ὡς πυνθάνονται, βαρὺ καὶ νοσῶδες ὂν στρατοπέδῳ, νῦν δ’, ὡς βλέπουσι, καὶ διὰ τὴν ὥραν ὀλέθριον. μετοπώρου γὰρ ἦν ἡ ἀρχή· καὶ πολλοὶ μὲν ἠσθένουν ἤδη, πάντες δὲ ἠθύμουν.", "st": "Nic. 22.1"}, {"sp": "N", "t": "ὁ δὲ Νικίας χαλεπῶς ἤκουε τὴν φυγὴν καὶ τὸν ἀπόπλουν, οὐ τῷ μὴ δεδιέναι τοὺς Συρακουσίους, ἀλλὰ τῷ μᾶλλον τοὺς Ἀθηναίους καὶ τὰς ἐκείνων δίκας καὶ συκοφαντίας φοβεῖσθαι. δεινὸν μὲν οὖν οὐδὲν αὐτόθι προσδοκᾶν ἔφασκεν, εἰ δὲ συμβαίη, μᾶλλον αἱρεῖσθαι τὸν ὑπὸ τῶν πολεμίων θάνατον ἢ τὸν ὑπὸ τῶν πολιτῶν, οὐχ ὅμοια φρονῶν οἷς ὕστερον ὁ Βυζάντιος Λέων εἶπε πρὸς τοὺς ἑαυτοῦ πολίτας· βούλομαι γὰρ, ἔφη, μᾶλλον ὑφ’ ὑμῶν ἢ μεθ’ ὑμῶν ἀποθανεῖν. περὶ μέντοι τόπου καὶ χώρας εἰς ἣν μετατάξουσι τὸ στρατόπεδον, βουλεύσεσθαι καθ’ ἡσυχίαν. ταῦτα δ’ αὐτοῦ λέγοντος ὁ μὲν Δημοσθένης οὐδὲ τῇ προτέρᾳ γνώμῃ κατευτυχήσας ἐπαύσατο βιαζόμενος, τοῖς δ’ ἄλλοις παρέσχε τὸν Νικίαν προσδοκῶντα καὶ πιστεύοντα τοῖς ἔνδον οὕτως ἐρρωμένως ἀναμάχεσθαι περὶ τῆς ἀποβάσεως· διὸ καὶ συνεχώρησαν. ὡς μέντοι στρατιὰ Συρακουσίοις ἐπῆλθεν ἄλλη καὶ μᾶλλον ἥπτετο τῶν Ἀθηναίων ἡ νόσος, ἤδη καὶ τῷ Νικίᾳ συνεδόκει μεθίστασθαι, καὶ παρήγγειλε τοῖς στρατιώταις εὐτρεπεῖς εἶναι πρὸς ἀπόπλουν.", "st": "Nic. 22.3"}, {"sp": "N", "t": "ὡς δ’ ἦν ἕτοιμα ταῦτα πάντα καὶ τῶν πολεμίων οὐδεὶς παρεφύλαττεν, ἅτε δὴ μὴ προσδοκώντων, ἐξέλιπεν ἡ σελήνη τῆς νυκτός, μέγα δέος τῷ Νικίᾳ καὶ τῶν ἄλλων τοῖς ὑπὸ ἀπειρίας ἢ δεισιδαιμονίας ἐκπεπληγμένοις τὰ τοιαῦτα. τοῦ μὲν γὰρ ἡλίου τὴν περὶ τὰς τριακάδας ἐπισκότησιν ἁμῶς γέ πως ἤδη συνεφρόνουν καὶ οἱ πολλοὶ γενομένην ὑπὸ τῆς σελήνης· αὐτὴν δὲ τὴν σελήνην, ᾧτινι συντυγχάνουσα καὶ πῶς αἰφνίδιον ἐκ πανσελήνου τὸ φῶς ἀπόλλυσι καὶ χρόας ἵησι παντοδαπάς, οὐ ῥᾴδιον ἦν καταλαβεῖν, ἀλλ’ ἀλλόκοτον ἡγοῦντο καὶ πρὸ συμφορῶν τινων μεγάλων ἐκ θεοῦ γινόμενον σημεῖον.", "st": "Nic. 23.1"}, {"sp": "N", "t": "ὁ γὰρ πρῶτος σαφέστατόν τε πάντων καὶ θαρραλεώτατον περὶ σελήνης καταυγασμῶν καὶ σκιᾶς λόγον εἰς γραφὴν καταθέμενος Ἀναξαγόρας οὔτ’ αὐτὸς ἦν παλαιὸς οὔτε ὁ λόγος ἔνδοξος, ἀλλ’ ἀπόρρητος ἔτι καὶ δι’ ὀλίγων καὶ μετ’ εὐλαβείας τινὸς ἢ πίστεως βαδίζων. οὐ γὰρ ἠνείχοντο τοὺς φυσικοὺς καὶ μετεωρολέσχας τότε καλουμένους, ὡς εἰς αἰτίας ἀλόγους καὶ δυνάμεις ἀπρονοήτους καὶ κατηναγκασμένα πάθη διατρίβοντας τὸ θεῖον, ἀλλὰ καὶ Πρωταγόρας ἔφυγε, καὶ Ἀναξαγόραν εἱρχθέντα μόλις περιεποιήσατο Περικλῆς, καὶ Σωκράτης, οὐδὲν αὐτῷ τῶν γε τοιούτων προσῆκον, ὅμως ἀπώλετο διὰ φιλοσοφίαν. ὀψὲ δ’ ἡ Πλάτωνος ἐκλάμψασα δόξα διὰ τὸν βίον τοῦ ἀνδρός, καὶ ὅτι ταῖς θείαις καὶ κυριωτέραις ἀρχαῖς ὑπέταξε τὰς φυσικὰς ἀνάγκας, ἀφεῖλε τὴν τῶν λόγων τούτων διαβολήν, καὶ τοῖς μαθήμασιν εἰς ἅπαντας ὁδὸν ἐνέδωκεν. ὁ γοῦν ἑταῖρος αὐτοῦ Δίων, καθ’ ὃν χρόνον ἔμελλεν ἄρας ἐκ Ζακύνθου πλεῖν ἐπὶ Διονύσιον, ἐκλιπούσης τῆς σελήνης, οὐδὲν διαταραχθεὶς ἀνήχθη, καὶ κατασχὼν ἐν Συρακούσαις ἐξέβαλε τὸν τύραννον.", "st": "Nic. 23.3"}, {"sp": "N", "t": "τῷ μέντοι Νικίᾳ συνηνέχθη τότε μηδὲ μάντιν ἔχειν ἔμπειρον· ὁ γὰρ συνήθης αὐτοῦ καὶ τὸ πολὺ τῆς δεισιδαιμονίας ἀφαιρῶν Στιλβίδης ἐτεθνήκει μικρὸν ἔμπροσθεν. ἐπεὶ τὸ σημεῖον, ὥς φησι Φιλόχορος, φεύγουσιν οὐκ ἦν πονηρόν, ἀλλὰ καὶ πάνυ χρηστόν· ἐπικρύψεως γὰρ αἱ σὺν φόβῳ πράξεις δέονται, τὸ δὲ φῶς πολέμιόν ἐστιν αὐταῖς. ἄλλως τε καὶ τῶν περὶ ἥλιον καὶ σελήνην ἐπὶ τρεῖς ἡμέρας ἐποιοῦντο φυλακήν, ὡς Αὐτοκλείδης διέγραψεν ἐν τοῖς ἐξηγητικοῖς· ὁ δὲ Νικίας ἄλλην ἔπεισε σελήνης ἀναμένειν περίοδον, ὥσπερ οὐκ εὐθὺς θεασάμενος αὐτὴν ἀποκαθαρθεῖσαν, ὅτε τὸν σκιερὸν τόπον καὶ ὑπὸ τῆς γῆς ἀντιφραττόμενον παρῆλθε.", "st": "Nic. 23.5"}, {"sp": "N", "t": "μικροῦ δὲ πάντων ἀφέμενος τῶν ἄλλων ἔθυέ τε καὶ διεμαντεύετο καθήμενος, ἕως ἐπῆλθον αὐτοῖς οἱ πολέμιοι, τῷ μὲν πεζῷ τὰ τείχη καὶ τὸ στρατόπεδον αὐτῶν πολιορκοῦντες, ταῖς δὲ ναυσὶ κύκλῳ τὸν λιμένα περιλαμβάνοντες, οὐκ αὐτοὶ μόνον ταῖς τριήρεσιν, ἀλλὰ καὶ τὰ παιδάρια πανταχόθεν ἐπιβαίνοντα τῶν ἁλιάδων καὶ ταῖς σκάφαις προσπλέοντα προὐκαλεῖτο τοὺς Ἀθηναίους καὶ προὐπηλάκιζεν. ὧν ἕνα, παῖδα γνωρίμων γονέων, Ἡρακλείδην, προεξελάσαντα τῷ πλοίῳ ναῦς Ἀττικὴ διώκουσα κατελάμβανε. δείσας δὲ περὶ αὐτῷ Πόλλιχος ὁ θεῖος ἀντελαύνει δέκα τριήρεσιν ὧν ἦρχεν· οἱ δ’ ἄλλοι περὶ τοῦ Πολλίχου φοβηθέντες ὡσαύτως ἀνήγοντο. καὶ ναυμαχίας ἰσχυρᾶς γενομένης ἐνίκησαν οἱ Συρακούσιοι, καὶ τὸν Εὐρυμέδοντα πολλῶν μετ’ ἄλλων διέφθειραν.", "st": "Nic. 24.1"}, {"sp": "N", "t": "ἦν οὖν οὐκέτι μένειν ἀνασχετὰ Ἀθηναίοις, ἀλλὰ τῶν στρατηγῶν κατεβόων πεζῇ κελεύοντες ἀναχωρεῖν. καὶ γὰρ οἱ Συρακούσιοι νικήσαντες εὐθὺς ἐνέφραξαν καὶ ἀπέκλεισαν τὸν διέκπλουν τοῦ λιμένος. οἱ δὲ περὶ τὸν Νικίαν τοῦτο μὲν οὐκ ἐπείθοντο· δεινὸν γὰρ ἦν ἀπολιπεῖν ὁλκάδας τε πολλὰς καὶ τριήρεις ὀλίγον ἀριθμῷ διακοσίω. ἀποδεούσας· ἐμβιβάσαντες δὲ τῶν πεζῶν τοὺς ἀρίστους καὶ τῶν ἀκοντιστῶν τοὺς ἀλκιμωτάτους ἐπλήρωσαν ἑκατὸν καὶ δέκα τριήρεις· αἱ γὰρ ἄλλαι ταρσῶν ἐνδεεῖς ἦσαν. τὸν δὲ λοιπὸν ὄχλον ἔστησε παρὰ θάλασσαν ὁ Νικίας, ἐκλιπὼν τὸ μέγα στρατόπεδον καὶ τὰ τείχη τὰ συνάπτοντα πρὸς τὸ Ἡράκλειον, ὥστε μὴ τεθυκότων τὴν εἰθισμένην θυσίαν τῷ Ἡρακλεῖ τῶν Συρακουσίων, θῦσαι τότε τοὺς ἱερεῖς καὶ στρατηγοὺς ἀναβάντας ἤδη πληρουμένων τῶν τριήρων.", "st": "Nic. 24.3"}, {"sp": "N", "t": "ἐπεὶ δ’ οἱ μάντεις τοῖς Συρακουσίοις ἀπήγγειλαν ἐκ τῶν ἱερῶν λαμπρότητα καὶ νίκην μὴ καταρχομένοις μάχης, ἀλλ’ ἀμυνομένοις (καὶ γὰρ τὸν Ἡρακλέα πάντων κρατεῖν ἀμυνόμενον καὶ προεπιχειρούμενον), ἀνήχθησαν.", "st": "Nic. 25.1"}, {"sp": "N", "t": "ἡ δὲ ναυμαχία πολὺ μεγίστη καὶ καρτερωτάτη γενομένη, καὶ μηδὲν ἐλάττονα πάθη καὶ θορύβους παρασχοῦσα τοῖς θεωμένοις ἢ τοῖς ἀγωνιζομένοις διὰ τὴν παντὸς ἐπίβλεψιν τοῦ ἔργου ποικίλας μεταβολὰς καὶ ἀπροσδοκήτους ἐν ὀλίγῳ λαμβάνοντος, ἔβλαπτε ταῖς αὐτῶν παρασκευαῖς οὐχ ἧττον τῶν πολεμίων τοὺς Ἀθηναίους. ἀθρόαις γὰρ ἐμάχοντο ταῖς ναυσὶ καὶ βαρείαις πρὸς κούφας ἀλλαχόθεν ἄλλας ἐπιφερομένας, καὶ βαλλόμενοι λίθοις ὁμοίαν ἔχουσι τὴν πληγὴν πανταχόθεν ἀντέβαλλον ἀκοντίοις καὶ τοξεύμασιν, ὧν ὁ σάλος τὴν εὐθυβολίαν διέστρεφεν, ὥστε μὴ πάντα κατ’ αἰχμὴν προσφέρεσθαι. ταῦτα δ’ Ἀρίστων ὁ Κορίνθιος κυβερνήτης ἐδίδαξε τοὺς Συρακουσίους, καὶ παρὰ τὴν μάχην αὐτὴν ἀγωνιζόμενος προθύμως ἔπεσεν ἤδη κρατούντων τῶν Συρακουσίων.", "st": "Nic. 25.2"}, {"sp": "N", "t": "γενομένης δὲ μεγάλης τροπῆς καὶ φθορᾶς, ἡ μὲν κατὰ θάλασσαν φυγὴ τοῖς Ἀθηναίοις ἀποκέκοπτο· χαλεπὴν δὲ καὶ διὰ γῆς τὴν σωτηρίαν ὁρῶντες οὔτε ναῦς ἀφέλκοντας ἐγγύθεν ἔτι τοὺς πολεμίους ἐκώλυον οὔτε νεκρῶν ᾔτησαν ἀναίρεσιν, ἅτε δὴ τῆς ἐκείνων ἀταφίας τὴν τῶν νοσούντων καὶ τετρωμένων ἀπόλειψιν οἰκτροτέραν οὖσαν ἤδη πρὸ ὀφθαλμῶν ἔχοντες, αὑτοὺς δὲ κἀκείνων ἐπιπονωτέρους ἡγούμενοι, μετὰ πλειόνων κακῶν ἐπὶ ταὐτὸ πάντως ἀφιξομένους τέλος.", "st": "Nic. 25.3"}, {"sp": "N", "t": "ὡρμημένων δ’ αὐτῶν ἀπαίρειν διὰ νυκτὸς οἱ μὲν περὶ τὸν Γύλιππον, ὁρῶντες ἐν θυσίαις καὶ πότοις τοὺς Συρακουσίους διά τε τὴν νίκην καὶ τὴν ἑορτὴν ὄντας, οὔτε πείσειν οὔτε βιάσεσθαι προσεδόκων ἀναστάντας ἤδη προσφέρεσθαι τοῖς πολεμίοις ἀπιοῦσιν, Ἑρμοκράτης δ’ αὐτὸς ἀφ’ ἑαυτοῦ συνθεὶς ἐπὶ τὸν Νικίαν ἀπάτην, ἔπεμψέ τινας τῶν ἑταίρων πρὸς αὐτόν, ἀπ’ ἐκείνων μὲν ἥκειν τῶν ἀνδρῶν φάσκοντας, οἳ καὶ πρότερον εἰώθεσαν κρύφα τῷ Νικίᾳ διαλέγεσθαι, παραινοῦντας δὲ μὴ πορεύεσθαι διὰ τῆς νυκτός, ὡς τῶν Συρακουσίων ἐνέδρας πεποιημένων αὐτοῖς καὶ προκατεχόντων τὰς παρόδους. τούτῳ δὲ καταστρατηγηθεὶς ὁ Νικίας ὑπέμενεν ἃ ψευδῶς ἔδεισεν ὑπὸ τῶν πολεμίων ἀληθῶς παθεῖν. προελθόντες γὰρ ἅμ’ ἡμέρα τὰς δυσχωρίας τῶν ὁδῶν κατέλαβον καὶ τὰς διαβάσεις τῶν ποταμῶν ἀπετείχισαν τάς τε γεφύρας ἀπέκοψαν, ἐν δὲ τοῖς ὁμαλοῖς καὶ πεδινοῖς τοὺς ἱππεῖς ἔταξαν, ὥστε μηδένα λελεῖφθαι τοῖς Ἀθηναίοις τόπον ἀμαχεὶ προελθεῖν.", "st": "Nic. 26.1"}, {"sp": "N", "t": "οἱ δὲ καὶ τὴν ἡμέραν ἐκείνην καὶ τὴν νύκτα τὴν ἑτέραν ἐπιμείναντες ἐπορεύοντο κλαυθμῷ καὶ ὀλοφυρμῷ, καθάπερ ἐκ πατρίδος, οὐ πολεμίας, ἀνιστάμενοι, διὰ τὰς ἀπορίας τῶν ἀναγκαίων καὶ τὰς ἀπολείψεις τῶν ἀδυνάτων φίλων καὶ συνήθων, ὅμως τὰ παρόντα κακὰ κουφότερα τῶν προσδοκωμένων νομίζοντες εἶναι. πολλῶν δὲ δεινῶν ἐν τῷ στρατοπέδῳ φαινομένων, οὐδὲν ἦν οἰκτρότερον αὐτοῦ Νικίου θέαμα, κεκακωμένου μὲν ὑπὸ τῆς ἀσθενείας, συνεσταλμένου δὲ παρ’ ἀξίαν εἰς ἀναγκαίαν δίαιταν καὶ τὰ μικρότατα τῶν ἐφοδίων εἰς τὸ σῶμα πολλῶν διὰ τὴν νόσον δεόμενον, πράττοντος δὲ μετ’ ἀρρωστίας καὶ καρτεροῦντος ἃ πολλοὶ τῶν ἐρρωμένων μόλις ὑπέμενον, καταφανοῦς δὲ πᾶσιν ὄντος οὐ δι’ αὑτὸν οὐδὲ τῷ φιλοψυχεῖν τοῖς πόνοις ἐμμένοντος, ἀλλὰ δι’ ἐκείνους τὴν ἐλπίδα μὴ προϊεμένου. καὶ γὰρ εἰς δάκρυα καὶ ὀδυρμοὺς τῶν ἄλλων ὑπὸ φόβου καὶ λύπης τρεπομένων, ἐκεῖνος, εἴ ποτε βιασθείη τοῦτο ποιῆσαι, δῆλος ἦν τὸ αἰσχρὸν καὶ τὸ ἀκλεὲς τῆς στρατείας ἀναλογιζόμενος πρὸς τὸ μέγεθος καὶ τὴν δόξαν ὧν ἤλπιζε κατορθώσειν.", "st": "Nic. 26.4"}, {"sp": "N", "t": "οὐ μόνον δ’ αὐτοῦ τὴν ὄψιν ὁρῶντες, ἀλλὰ καὶ τῶν λόγων μνημονεύοντες καὶ τῶν παραινέσεων ἃς ἐποιήσατο κωλύων τὸν ἔκπλουν, ἔτι μᾶλλον ἐνόμιζον ἀναξίως ταλαιπωρεῖν· καὶ πρὸς τὰς ἐκ θεῶν ἐλπίδας ἀθύμως εἶχον, ἐννοοῦντες ὡς ἀνὴρ θεοφιλὴς καὶ πολλὰ καὶ μεγάλα λαμπρυνάμενος πρὸς τὸ θεῖον οὐδενὸς ἐπιεικεστέρᾳ τύχῃ χρῆται τῶν κακίστων ἐν τῷ στρατεύματι καὶ ταπεινοτάτων.", "st": "Nic. 26.6"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὅ γε Νικίας ἐπειρᾶτο καὶ φωνῇ καὶ προσώπῳ καὶ δεξιώσει κρείττων ὁρᾶσθαι τῶν δεινῶν. καὶ παρὰ πᾶσάν γε τὴν πορείαν ἐφ’ ἡμέρας ὀκτὼ βαλλόμενος καὶ τραυματιζόμενος ὑπὸ τῶν πολεμίων ἀήττητον ἐφύλαττε τὴν σὺν αὐτῷ δύναμιν, ἄχρι οὗ Δημοσθένης ἑάλω καὶ τὸ μετ’ ἐκείνου στράτευμα, περὶ τὴν Πολυζήλειον αὐλὴν ἐν τῷ διαμάχεσθαι καὶ ὑπολείπεσθαι κυκλωθέν. αὐτὸς δὲ Δημοσθένης σπασάμενος τὸ ξίφος ἔπληξε μὲν ἑαυτόν, οὐ μὴν ἀπέθανε, ταχὺ τῶν πολεμίων περισχόντων καὶ συλλαβόντων αὐτόν.", "st": "Nic. 27.1"}, {"sp": "N", "t": "ὡς δὲ τῷ Νικίᾳ προσελάσαντες ἔφραζον οἱ Συρακούσιοι καὶ πέμψας ἱππέας ἔγνω τὴν ἐκείνου τοῦ στρατεύματος ἅλωσιν, ἠξίου σπείσασθαι πρὸς τὸν Γύλιππον, ὅπως ἀφῶσι τοὺς Ἀθηναίους ἐκ Σικελίας ὅμηρα λαβόντες ὑπὲρ τῶν χρημάτων ὅσα Συρακουσίοις ἀνάλωτο πρὸς τὸν πόλεμον. οἱ δ’ οὐ προσεῖχον, ἀλλὰ πρὸς ὕβριν καὶ μετ’ ὀργῆς ἀπειλοῦντες καὶ λοιδοροῦντες ἔβαλλον ἤδη πάντων ἐνδεῶς ἔχοντα τῶν ἀναγκαίων. οὐ μὴν ἀλλὰ καὶ τὴν νύκτα διεκαρτέρησε καὶ τὴν ἐπιοῦσαν ἡμέραν προῄει βαλλόμενος πρὸς τὸν Ἀσίναρον ποταμόν. ἐκεῖ δὲ τοὺς μὲν οἱ πολέμιοι συνενεγκόντες ἐνέσεισαν εἰς τὸ ῥεῖθρον, οἱ δὲ φθάνοντες ὑπὸ δίψους ἔρριπτον ἑαυτούς. καὶ πλεῖστος ἐνταῦθα μόρος ἦν καὶ ὠμότατος ἐν τῷ ποταμῷ πινόντων ἅμα καὶ σφαττομένων, ἄχρι Νικίας Γυλίππῳ προσπεσὼν εἶπεν· ἔλεος ὑμᾶς, ὦ Γύλιππε, λαβέτω νικῶντας, ἐμοῦ μὲν μηδείς, ὃς ἐπὶ τηλικαύταις εὐτυχίαις ὄνομα καὶ δόξαν ἔσχον, τῶν δ’ ἄλλων Ἀθηναίων, ἐννοηθέντας ὅτι κοιναὶ μὲν αἱ τύχαι τοῦ πολέμου, μετρίως δ’ αὐταῖς καὶ πρᾴως ἐχρήσαντο ἐν οἷς εὐτύχουν Ἀθηναῖοι πρὸς ὑμᾶς.", "st": "Nic. 27.3"}, {"sp": "N", "t": "τοιαῦτα τοῦ Νικίου λέγοντος ἔπαθε μέν τι καὶ πρὸς τὴν ὄψιν αὐτοῦ καὶ πρὸς τοὺς λόγους ὁ Γύλιππος· ᾔδει γὰρ τοὺς Λακεδαιμονίους εὖ πεπονθότας ὑπ’ αὐτοῦ περὶ τὰς γενομένας διαλύσεις· μέγα δ’ ἡγεῖτο πρὸς δόξαν εἰ ζῶντας ἀπαγάγοι τοὺς ἀντιστρατήγους. διὸ τόν τε Νικίαν ἀναλαβὼν ἐθάρρυνε καὶ τοὺς ἄλλους ζωγρεῖν παρήγγειλε. βραδέως δὲ τοῦ παραγγέλματος διϊκνουμένου πολλῷ τῶν φονευθέντων ἐλάττονες οἱ διασωθέντες ἐγένοντο· καίτοι πολλοὶ διεκλάπησαν ὑπὸ τῶν στρατιωτῶν.", "st": "Nic. 27.5"}, {"sp": "N", "t": "τοὺς δὲ φανερῶς ἑαλωκότας ἀθροίσαντες τὰ μὲν κάλλιστα καὶ μέγιστα δένδρα τῶν περὶ τὸν ποταμὸν ἀνέδησαν αἰχμαλώτοις πανοπλίαις, ἐστεφανωμένοι δὲ αὐτοὶ καὶ κοσμήσαντες τοὺς ἵππους διαπρεπῶς, κείραντες δὲ τοὺς τῶν πολεμίων εἰσήλαυνον εἰς τὴν πόλιν, ἀγῶνα λαμπρότατον ὧν Ἕλληνες πρὸς Ἕλληνας ἠγωνίσαντο καὶ νίκην τελεωτάτην κράτει πλείστῳ καὶ ῥώμῃ μεγίστῃ προθυμίας καὶ ἀρετῆς κατωρθωκότες.", "st": "Nic. 27.6"}, {"sp": "N", "t": "ἐκκλησίας δὲ πανδήμου Συρακουσίων καὶ τῶν συμμάχων γενομένης, Εὐρυκλῆς ὁ δημαγωγὸς ἔγραψε πρῶτον μὲν τὴν ἡμέραν ἐν ᾗ τὸν Νικίαν ἔλαβον, ἱερὰν ἔχειν, θύοντας καὶ σχολάζοντας ἔργων, Ἀσιναρίαν τὴν ἑορτὴν ἀπὸ τοῦ ποταμοῦ καλοῦντας· ἡμέρα δ’ ἦν τετρὰς φθίνοντος τοῦ Καρνείου μηνός, ὃν Ἀθηναῖοι Μεταγειτνιῶνα προσαγορεύουσι. τῶν δ’ Ἀθηναίων τοὺς μὲν οἰκέτας ἀποδόσθαι καὶ τοὺς ἄλλους συμμάχους, αὐτοὺς δὲ καὶ τοὺς ἀπὸ Σικελίας φρουρεῖν ἐμβαλόντας εἰς τὰς λατομίας, πλὴν τῶν στρατηγῶν, ἐκείνους δὲ ἀποκτεῖναι.", "st": "Nic. 28.1"}, {"sp": "N", "t": "ταῦτα προσδεχομένων τῶν Συρακουσίων, Ἑρμοκράτης μὲν εἰπὼν ὅτι τοῦ νικᾶν κρεῖττόν ἐστι τὸ καλῶς χρῆσθαι τῇ νίκῃ, οὐ μετρίως ἐθορυβήθη, Γύλιππον δὲ τοὺς στρατηγοὺς τῶν Ἀθηναίων ἐξαιτούμενον ζῶντας ἀγαγεῖν Λακεδαιμονίοις ὑβρίζοντες· ἤδη τοῖς εὐτυχήμασιν οἱ Συρακούσιοι κακῶς ἔλεγον, ἄλλως τε καὶ παρὰ τὸν πόλεμον αὐτοῦ τὴν τραχύτητα καὶ τὸ Λακωνικὸν τῆς ἐπιστασίας οὐ ῥᾳδίως ἐνηνοχότες, ὡς δὲ Τίμαιός φησι, καὶ μικρολογίαν τινὰ καὶ πλεονεξίαν κατεγνωκότες, ἀρρώστημα πατρῷον, ἐφ’ ᾧ καὶ Κλεανδρίδης ὁ πατὴρ αὐτοῦ δώρων ἁλοὺς ἔφυγε, καὶ οὗτος αὐτός, ἀπὸ τῶν χιλίων ταλάντων ἃ Λύσανδρος ἔπεμψεν εἰς Σπάρτην ὑφελόμενος τριάκοντα καὶ κρύψας ὑπὸ τὸν ὄροφον τῆς οἰκίας, εἶτα μηνυθείς, αἴσχιστα πάντων ἐξέπεσεν. ἀλλὰ ταῦτα μὲν ἐν τῷ Λυσάνδρου βίῳ μᾶλλον διηκρίβωται.", "st": "Nic. 28.3"}, {"sp": "N", "t": "Δημοσθένην δὲ καὶ Νικίαν ἀποθανεῖν Τίμαιος οὔ φησιν ὑπὸ Συρακουσίων κελευσθέντας, ὡς Φίλιστος ἔγραψε καὶ Θουκυδίδης, ἀλλ’ Ἑρμοκράτους πέμψαντος, ἔτι τῆς ἐκκλησίας συνεστώσης, καὶ δι’ ἑνὸς τῶν φυλάκων παρέντων αὐτοὺς δι’ αὑτῶν ἀποθανεῖν· τὰ μέντοι σώματα πρὸς ταῖς πύλαις ἐκβληθέντα κεῖσθαι φανερὰ τοῖς δεομένοις τοῦ θεάματος. πυνθάνομαι δὲ μέχρι νῦν ἐν Συρακούσαις ἀσπίδα κειμένην πρὸς ἱερῷ δείκνυσθαι, Νικίου μὲν λεγομένην, χρυσοῦ δὲ καὶ πορφύρας εὖ πως πρὸς ἄλληλα μεμιγμένων δι’ ὑφῆς συγκεκροτημένην.", "st": "Nic. 28.4"}, {"sp": "N", "t": "τῶν δ’ Ἀθηναίων οἱ μὲν πλεῖστοι διεφθάρησαν ἐν ταῖς λατομίαις ὑπὸ νόσου καὶ διαίτης πονηρᾶς, εἰς ἡμέραν ἑκάστην κοτύλας δύο κριθῶν λαμβάνοντες καὶ μίαν ὕδατος, οὐκ ὀλίγοι δ’ ἐπράθησαν διακλαπέντες ἢ καὶ διαλαθόντες ὡς οἰκέται. καὶ τούτους ὡς οἰκέτας ἐπώλουν, στίζοντες ἵππον εἰς τὸ μέτωπον· ἀλλ’ ἦσαν οἱ καὶ τοῦτο πρὸς τῷ δουλεύειν ὑπομένοντες.", "st": "Nic. 29.1"}, {"sp": "N", "t": "ἐβοήθει δὲ καὶ τούτοις ἥ τ’ αἰδὼς καὶ τὸ κόσμιον· ἢ γὰρ ἠλευθεροῦντο ταχέως ἢ τιμώμενοι παρέμενον τοῖς κεκτημένοις. ἔνιοι δὲ καὶ δι’ Εὐριπίδην ἐσώθησαν. μάλιστα γάρ, ὡς ἔοικε, τῶν ἐκτὸς Ἑλλήνων ἐπόθησαν αὐτοῦ τὴν μοῦσαν οἱ περὶ Σικελίαν· καὶ μικρὰ τῶν ἀφικνουμένων ἑκάστοτε δείγματα καὶ γεύματα κομιζόντων ἐκμανθάνοντες ἀγαπητῶς μετεδίδοσαν ἀλλήλοις. τότε γοῦν φασι τῶν σωθέντων οἴκαδε συχνοὺς ἀσπάσασθαι τὸν Εὐριπίδην φιλοφρόνως, καὶ διηγεῖσθαι τοὺς μέν, ὅτι δουλεύοντες ἀφείθησαν ἐκδιδάξαντες ὅσα τῶν ἐκείνου ποιημάτων ἐμέμνηντο, τοὺς δ’, ὅτι πλανώμενοι μετὰ τὴν μάχην τροφῆς καὶ ὕδατος μετέλαβον τῶν μελῶν ᾄσαντες. οὐ δεῖ δὴ θαυμάζειν ὅτι τοὺς Καυνίους φασὶ πλοίου προσφερομένου τοῖς λιμέσιν ὑπὸ λῃστρίδων διωκομένου μὴ δέχεσθαι τὸ πρῶτον, ἀλλ’ ἀπείργειν, εἶτα μέντοι διαπυνθανομένους εἰ γινώσκουσιν ᾄσματα τῶν Εὐριπίδου, φησάντων ἐκείνων, οὕτω παρεῖναι καὶ καταγαγεῖν τὸ πλοῖον.", "st": "Nic. 29.2"}, {"sp": "N", "t": "Ἀθηναίοις δέ φασι τὴν συμφορὰν οὐχ ἥκιστα διὰ τὸν ἄγγελον ἄπιστον γενέσθαι. ξένος γάρ τις, ὡς ἔοικεν, ἀποβὰς εἰς Πειραιᾶ καὶ καθίσας ἐπὶ κουρεῖον, ὡς ἐγνωκότων ἤδη τῶν Ἀθηναίων λόγους ἐποιεῖτο περὶ τῶν γεγονότων. ὁ δὲ κουρεὺς ἀκούσας, πρὶν ἄλλους πυνθάνεσθαι, δρόμῳ συντείνας εἰς τὸ ἄστυ καὶ προσβαλὼν τοῖς ἄρχουσιν εὐθὺς κατ’ ἀγορὰν ἐνέβαλε τὸν λόγον. ἐκπλήξεως δὲ καὶ ταραχῆς, ὡς εἰκός, γενομένης, οἱ μὲν ἄρχοντες ἐκκλησίαν συναγαγόντες εἰσήγαγον τὸν ἄνθρωπον· ὡς δ’ ἐρωτώμενος παρ’ οὗ πύθοιτο σαφὲς οὐδὲν εἶχε φράζειν, δόξας λογοποιὸς εἶναι καὶ ταράττειν τὴν πόλιν, εἰς τὸν τροχὸν καταδεθεὶς ἐστρεβλοῦτο πολὺν χρόνον, ἕως ἐπῆλθον οἱ τὸ πᾶν κακόν, ὡς εἶχεν, ἀπαγγέλλοντες. οὕτω μόλις ὁ Νικίας ἐπιστεύθη παθὼν ἃ πολλάκις αὐτοῖς προεῖπεν.", "st": "Nic. 30.1"}, {"sp": "HDR", "t": "Κράσσος"}, {"sp": "N", "t": "Μᾶρκος δὲ Κράσσος ἦν τιμητικοῦ καὶ θριαμβικοῦ πατρός, ἐτράφη δ’ ἐν οἰκίᾳ μικρᾷ μετὰ δυοῖν ἀδελφῶν. καὶ τοῖς ἀδελφοῖς αὐτοῦ γυναῖκες ἦσαν ἔτι τῶν γονέων ζώντων, καὶ πάντες ἐπὶ τὴν αὐτὴν ἐφοίτων τράπεζαν, ὅθεν οὐχ ἥκιστα δοκεῖ καὶ διὰ τοῦτο σώφρων καὶ μέτριος γενέσθαι περὶ τὴν δίαιταν. ἀποθανόντος δὲ τοῦ ἑτέρου τῶν ἀδελφῶν τῇ γυναικὶ συνῴκησε καὶ τοὺς παῖδας ἐξ ἐκείνης ἔσχεν, οὐδενὸς ἧττον καὶ περὶ ταῦτα Ῥωμαίων εὔτακτος γενόμενος. καίτοι προϊὼν καθ’ ἡλικίαν αἰτίαν ἔσχε Λικιννίᾳ συνιέναι τῶν Ἑστιάδων μιᾷ παρθένων· καὶ δίκην ἔφυγεν ἡ Λικιννία Πλωτίου τινὸς διώκοντος. ἦν δὲ προάστειον αὐτῇ καλόν, ὃ βουλόμενος λαβεῖν ὀλίγης τιμῆς ὁ Κράσσος καὶ διὰ τοῦτο προσκείμενος ἀεὶ τῇ γυναικὶ καὶ θεραπεύων, εἰς τὴν ὑποψίαν ἐκείνην ἐνέπεσε καὶ τρόπον τινὰ τῇ φιλοπλουτίᾳ τὴν αἰτίαν τῆς φθορᾶς ἀπολυσάμενος ὑπὸ τῶν δικαστῶν ἀφείθη, τὴν δὲ Λικιννίαν οὐκ ἀνῆκε πρότερον ἢ τοῦ κτήματος κρατῆσαι.", "st": "Crass. 1.1"}, {"sp": "N", "t": "Ῥωμαῖοι μὲν οὖν λέγουσι πολλαῖς ἀρεταῖς τοῦ Κράσσου κακίαν μόνην ἐπισκοτῆσαι τὴν φιλοπλουτίαν· ἔοικε δὲ μία πασῶν ἐρρωμενεστέρα τῶν ἐν αὐτῷ κακιῶν γενομένη τὰς ἄλλας ἀμαυρῶσαι. τεκμήρια δὲ τῆς φιλοπλουτίας αὑτοῦ μέγιστα ποιοῦνται τόν τε τρόπον τοῦ πορισμοῦ καὶ τῆς οὐσίας τὸ μέγεθος. τριακοσίων γὰρ οὐ πλείω κεκτημένος ἐν ἀρχῇ ταλάντων, εἶτα παρὰ τὴν ὑπατείαν ἀποθύσας μὲν τῷ Ἡρακλεῖ τὴν δεκάτην καὶ τόν δῆμον ἑστιάσας, τρεῖς δὲ μῆνας ἑκάστῳ Ῥωμαίων σιτηρέσιον ἐκ τῶν αὑτοῦ παρασχών, ὅμως πρὸ τῆς ἐπὶ Πάρθους στρατείας αὐτὸς αὐτῷ θέμενος ἐκλογισμὸν τῆς οὐσίας εὗρεν ἑκατὸν ταλάντων τίμημα πρὸς ἑπτακισχιλίοις. τὰ δὲ πλεῖστα τούτων, εἰ δεῖ μετὰ βλασφημίας εἰπεῖν τὸ ἀληθές, ἐκ πυρὸς συνήγαγε καὶ πολέμου, ταῖς κοιναῖς ἀτυχίαις προσόδῳ τῇ μεγίστῃ χρησάμενος.", "st": "Crass. 2.1"}, {"sp": "N", "t": "ὅτε γὰρ Σύλλας ἑλὼν τὴν πόλιν ἐπώλει τὰς οὐσίας τῶν ἀνῃρημένων ὑπ’ αὐτοῦ, λάφυρα καὶ νομίζων καὶ ὀνομάζων, καὶ βουλόμενος ὅτι πλείστοις καὶ κρατίστοις προσομόρξασθαι τὸ ἄγος, οὔτε λαμβάνων οὔτ’ ὠνούμενος ἀπεῖπε. πρὸς δὲ τούτοις ὁρῶν τὰς συγγενεῖς καὶ συνοίκους τῆς Ῥώμης κῆρας ἐμπρησμοὺς καὶ συνιζήσεις διὰ βάρος καὶ πλῆθος οἰκοδομημάτων, ἐωνεῖτο δούλους ἀρχιτέκτονας καὶ οἰκοδόμους, εἶτ’ ἔχων τούτους ὑπὲρ πεντακοσίους ὄντας, ἐξηγόραζε τὰ καιόμενα καὶ γειτνιῶντα τοῖς καιομένοις, διὰ φόβον καὶ ἀδηλότητα τῶν δεσποτῶν ἀπ’ ὀλίγης τιμῆς προϊεμένων, ὥστε τῆς Ῥώμης τὸ πλεῖστον μέρος ὑπ’ αὐτῷ γενέσθαι. τοσούτους δὲ κεκτημένος τεχνίτας οὐδὲν ᾠκοδόμησεν αὐτὸς ἢ τὴν ἰδίαν οἰκίαν, ἀλλ’ ἔλεγε τοὺς φιλοικοδόμους αὐτοὺς ὑφ’ ἑαυτῶν καταλύεσθαι χωρὶς ἀνταγωνιστῶν, ὄντων δ’ αὐτῷ παμπόλλων ἀργυρείων, πολυτιμήτου δὲ χώρας καὶ τῶν ἐργαζομένων ἐν αὐτῇ, ὅμως ἄν τις ἡγήσαιτο μηδὲν εἶναι ταῦτα πάντα πρὸς τὴν τῶν οἰκετῶν τιμήν· τοσούτους ἐκέκτητο καὶ τοιούτους, ἀναγνώστας, ὑπογραφεῖς, ἀργυρογνώμονας, διοικητάς, τραπεζοκόμους, αὐτὸς ἐπιστατῶν μανθάνουσι καὶ προσέχων καὶ διδάσκων καὶ ὅλως νομίζων τῷ δεσπότῃ προσήκειν μάλιστα τὴν περὶ τοὺς οἰκέτας ἐπιμέλειαν ὡς ὄργανα ἔμψυχα τῆς οἰκονομικῆς.", "st": "Crass. 2.4"}, {"sp": "N", "t": "καὶ τοῦτο μὲν ὀρθῶς ὁ Κράσσος, εἴπερ, ὡς ἔλεγεν, ἡγεῖτο τὰ μὲν ἄλλα διὰ τῶν οἰκετῶν χρῆναι, τοὺς δὲ οἰκέτας δι’ αὑτοῦ κυβερνᾶν τὴν γὰρ οἰκονομικήν ἐν ἀψύχοις χρηματιστικὴν οὖσαν, ἐν ἀνθρώποις πολιτικὴν γιγνομένην ὁρῶμεν ἐκεῖνο δὲ οὐκ εὖ, τὸ μηδένα νομίζειν μηδὲ φάσκειν εἶναι πλούσιον, ὃς οὐ δύναται τρέφειν ἀπὸ τῆς οὐσίας στρατόπεδον (ὁ γὰρ πόλεμος οὐ τεταγμένα σιτεῖται, κατὰ τόν Ἀρχίδαμον, ὥσθ’ ὁ πρὸς πόλεμον πλοῦτος ἀόριστος), καὶ πολὺ τῆς Μαρίου γνώμης ἀπηρτημένως. ἐκεῖνος γὰρ, ἐπεὶ κατ’ ἄνδρα νείμας ἑκάστῳ δέκα καὶ τέσσαρα πλέθρα γῆς ἔγνω πλέον ἐπιζητοῦντας, μηδείς, ἔφη, γένοιτο Ῥωμαίων ὀλίγην ἡγούμενος τὴν τρέφειν ἀρκοῦσαν.", "st": "Crass. 2.7"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ περὶ ξένους ἦν φιλότιμος ὁ Κράσσος· ἀνέῳκτο γὰρ ἡ οἰκία πᾶσι, καὶ τοῖς φίλοις ἐδάνειζεν ἄνευ τόκων, ἀπῄτει δ’ ἀποτόμως τοῦ χρόνου παρελθόντος εἰς ὃν ἐδάνεισε, καὶ τὸ προῖκα πολλῶν ἐγίνετο τόκων ἐπαχθέστερον. ἐν δὲ τοῖς δείπνοις ἡ μὲν κλῆσις ἦν ὡς τὰ πολλὰ δημοτικὴ καὶ λαώδης, ἡ δ’ εὐτέλεια τὴν καθαριότητα καὶ τὴν φιλοφροσύνην ἡδίονα τοῦ πολυτελοῦς εἶχε.", "st": "Crass. 3.1"}, {"sp": "N", "t": "παιδείας δὲ τῆς περὶ λόγον μάλιστα μὲν τὸ ῥητορικὸν καὶ χρειῶδες εἰς πολλοὺς ἤσκησε, καὶ γενόμενος δεινὸς εἰπεῖν ἐν τοῖς μάλιστα· Ῥωμαίων ἐπιμελείᾳ καὶ πόνῳ τοὺς εὐφυεστάτους ὑπερέβαλεν. οὐδεμίαν γὰρ οὕτω δίκην φασὶ μικράν οὐδ’ εὐκαταφρόνητον γενέσθαι πρὸς ἣν ἀπαράσκευος ἦλθεν, ἀλλὰ καὶ Πομπηΐου πολλάκις ὀκνοῦντος καὶ Καίσαρος ἐξαναστῆναι καὶ Κικέρωνος, ἐκεῖνος ἀνεπλήρου τὴν συνηγορίαν. καὶ διὰ τοῦτο μᾶλλον ἤρεσκεν ὡς ἐπιμελὴς καὶ βοηθητικός. ἤρεσκε δὲ καὶ τὸ περὶ τὰς δεξιώσεις καὶ προσαγορεύσεις φιλάνθρωπον αὐτοῦ καὶ δημοτικόν. οὐδενὶ γὰρ οὕτως ἀπήντησε Ῥωμαίων ἀδόξῳ καὶ ταπεινῷ Κράσσος ὃν ἀσπασάμενον οὐκ ἀντιπροσηγόρευσεν ἐξ ὀνόματος, λέγεται δὲ καὶ πολυμαθὴς καθ’ ἱστορίαν γενέσθαι, καί τι καὶ φιλοσοφῆσαι τοῖς Ἀριστοτέλους λόγοις προσθέμενος, ὧν διδάσκαλον εἶχεν Ἀλέξανδρον, ἄνθρωπον εὐκολίας καὶ πρᾳότητος ἀπόδειξιν διδόντα τὴν πρὸς Κράσσον συνήθειαν. οὐ γὰρ ἦν ἀποφήνασθαι ῥᾳδίως πότερον προσῆλθεν αὐτῷ πενέστερος ἢ προσελθὼν ἐγένετο. μόνος γοῦν ἀεὶ τῶν φίλων αὐτῷ συναποδημῶν στέγαστρον ἐλάμβανεν εἰς τὴν ὁδόν καὶ τοῦτ’ ἐπανελθὼν ἀπῃτεῖτο. ἀλλὰ ταῦτα μὲν ὕστερον.", "st": "Crass. 3.2"}, {"sp": "N", "t": "ἐπεὶ δὲ Κίννας καὶ Μάριος κρατήσαντες εὐθὺς ἦσαν ἔνδηλοι κατιόντες οὐκ ἐπ’ ἀγαθῷ τῆς πατρίδος, ἐπ’ ἀναιρέσει δ’ ἄντικρυς καὶ ὀλέθρῳ τῶν ἀρίστων, οἱ μέν ἐγκαταληφθέντες ἀπέθνῃσκον, ὧν ἦν καὶ ὁ πατὴρ Κράσσου καὶ ὁ ἀδελφός, αὐτὸς δὲ νέος ὢν παντάπασι τὸ μέν αὐτίκα δεινὸν ἐξέφυγε, πάντῃ δὲ περιβαλλόμενον ἑαυτὸν αἰσθανόμενος καὶ κυνηγετούμενον ὑπὸ τῶν τυράννων τρεῖς φίλους ἀναλαβὼν καὶ θεράποντας δέκα, τάχει δ’ ὑπερβάλλοντι χρησάμενος εἰς Ἰβηρίαν ἔφυγε, γεγονὼς πάλαι στρατηγοῦντος τοῦ πατρὸς αὐτόθι καὶ φίλους πεποιημένος. εὑρὼν δὲ πάντας περιδεεῖς καὶ τὴν ὠμότητα τὴν Μαρίου καθάπερ ἐφεστῶτος αὐτοῖς τρέμοντας, οὐδενὶ γενέσθαι φανερὸς ἐθάρρησεν, ἀλλ’ εἰς ἀγροὺς ἐμβαλὼν παραλίους Οὐιβίου Πακιανοῦ σπήλαιον ἔχοντας εὐμέγεθες, ἔκρυψεν ἑαυτόν, πρὸς δὲ τὸν Οὐίβιον ἔπεμψεν ἕνα δοῦλον ἀποπειρώμενος, ἤδη καὶ τῶν ἐφοδίων ἐπιλιπόντων. ὁ δὲ Οὐίβιος ἀκούσας ἥσθη τε σῳζομένῳ καὶ πυθόμενος τὸ πλῆθος τῶν σὺν αὐτῷ καὶ τὸν τόπον αὐτὸς μέν οὐκ ἦλθεν εἰς ὄψιν, τὸν δὲ τῶν χωρίων ἐπίτροπον προσαγαγὼν ἐγγὺς ἐκέλευσε καθ’ ἡμέραν δεῖπνον πεποιημένον κομίζειν, καὶ τιθέντα παρὰ τὴν πέτραν ἀπέρχεσθαι σιωπῇ καὶ μὴ πολυπραγμονεῖν μηδ’ ἐξετάζειν, προειπὼν πολυπραγμονοῦντι θάνατον, συμπράττοντι δὲ τοῦτο πιστῶς ἐλευθερίαν.", "st": "Crass. 4.1"}, {"sp": "N", "t": "τὸ δὲ σπήλαιον οὐκ ἄπωθεν μέν ἐστι θαλάσσης, κρημνοὶ δὲ περὶ αὐτὸ συμφερόμενοι λεπτὴν καὶ ἀσαφῆ παραπέμπουσι λαύραν ἄγουσαν εἴσω, παρελθόντι δ’ ὕψος τε θαυμαστὸν ἀναπέπταται, καὶ κατ’ εὖρος ἔχει κόλπους δι’ ἀλλήλων ἀνοιγομένους μεγάλαις περιφερείαις. ἀμοιρεῖ δ’ οὔτε ὕδατος οὔτε φωτός, ἀλλὰ πηγὴ μέν ἡδίστου νάματος ὑπορρεῖ παρὰ τὸν κρημνόν, αὐτοφυεῖς δὲ ῥωχμοὶ τῆς πέτρας ᾗ μάλιστα περιπίπτει τὸ φῶς ἔξωθεν ὑπολαμβάνουσι, καὶ καταλάμπεται ἡμέρας τὸ χωρίον, ὁ δ’ ἐντὸς ἀὴρ ἀστάλακτος καὶ καθαρός, πυκνότητι τῆς πέτρας τὸ νοτερὸν καὶ ἀποτηκόμενον εἰς τὴν πηγὴν ἐκπιεζούσης.", "st": "Crass. 4.4"}, {"sp": "N", "t": "ἐνταῦθα διατρίβοντι τῷ Κράσσῳ τὰ ἐπιτήδεια καθ’ ἡμέραν ἐφοίτα κομίζων ὁ ἄνθρωπος, αὐτὸς μὲν οὐχ ὁρῶν ἐκείνους οὐδὲ γινώσκων, ὑπ’ ἐκείνων δὲ καθορώμενος εἰδότων καί παραφυλαττόντων τὸν καιρόν. ἦν δ’ ἄφθονα καί πρὸς ἡδονήν, οὐ μόνον χρείαν, ποιούμενα τὰ πρὸς τὸ δεῖπνον. ἐγνώκει γὰρ ὁ Οὐίβιος ἁπάσῃ φιλοφροσύνῃ θεραπεύειν τὸν Κράσσον, ᾧ γε καί τὸ τῆς ὥρας ἐν νῷ λαβεῖν ἐπῆλθεν, ὡς παντάπασι νεανίας εἴη καί τι καί ταῖς καθ’ ἡλικίαν ἡδοναῖς αὐτοῦ χαριστέον, ἐπεὶ τήν γε χρείαν ἀναγκαίως μᾶλλον ἢ προθύμως ὑπουργοῦντος εἶναι, δύο δὴ θεραπαινίδας εὐπρεπεῖς ἀναλαβὼν ἐβάδιζεν ἐπὶ τήν θάλασσαν, ὡς δ’ ἦλθεν ἐπὶ τὸν τόπον, δείξας τήν ἄνοδον ἐκέλευεν εἴσω πορεύεσθαι καί θαρρεῖν. οἱ δὲ περὶ τὸν Κράσσον ἰδόντες προσερχομένας ἔδεισαν μὴ καταφανὲς καὶ γνώριμον εἴη τὸ χωρίον ἀνέκρινον οὖν αὐτάς τί βούλονται καί τίνες εἰσίν. ὡς δ’ ἀπεκρίναντο δεδιδαγμέναι δεσπότην ζητεῖν ἐνταῦθα κρυπτόμενον, μαθὼν ὁ Κράσσος τοῦ Οὐιβίου τήν πρὸς αὐτὸν παιδιὰν καί φιλοφροσύνην ἀνέλαβε τὰς παιδίσκας· καί συνῆσαν αὐτῷ τὸν λοιπὸν χρόνον, ὧν ἐδεῖτο φράζουσαι καί διαγγέλλουσαι πρὸς τὸν Οὐίβιον. τούτων φησὶ τήν ἑτέραν ἤδη πρεσβῦτιν οὖσαν ὁ Φαινεστέλλας ἰδεῖν αὐτός, καί πολλάκις ἀκοῦσαι μεμνημένης ταῦτα καί διεξιούσης προθύμως.", "st": "Crass. 5.1"}, {"sp": "N", "t": "ὁ δὲ Κράσσος ὀκτὼ μῆνας οὕτω διαγαγὼν καὶ διακλαπείς, ἅμα τῷ πυθέσθαι τὴν Κίννα τελευτὴν φανερὸς γενόμενος, συνδραμόντων πρὸς αὑτὸν οὐκ ὀλίγων ἀνθρώπων, ἐπιλεξάμενος δισχιλίους καὶ πεντακοσίους ἐπήρχετο τὰς πόλεις· καὶ μίαν γε διήρπασε Μαλάκην, ὡς πολλοὶ γεγράφασιν, αὐτὸν δέ φασιν ἀρνεῖσθαι καὶ διαμάχεσθαι πρὸς τοὺς λέγοντας. ἐκ τούτου συναγαγὼν πλοῖα καὶ διαπεράσας εἰς Λιβύην ἀφίκετο πρὸς Μέτελλον Πίον, ἔνδοξον ἄνδρα, συνειλοχότα στρατιὰν οὐκ εὐκαταφρόνητον. οὐ πολὺν δὲ χρόνον ἐνταῦθα παρέμεινεν, ἀλλὰ στασιάσας τῷ Μετέλλῳ πρὸς Σύλλαν ἀπῆρε, καὶ συνῆν ἐν τοῖς μάλιστα τιμώμενος, ἐπεὶ δὲ διαβὰς εἰς Ἰταλίαν ὁ Σύλλας πάντας ἐβούλετο τοὺς σὺν αὐτῷ νέους ἔχειν ἐνεργοὺς καὶ πρὸς ἄλλην ἄλλον ἔταττε πρᾶξιν, ἀποστελλόμενος εἰς Μαρσοὺς ἐπὶ στρατιὰν ὁ Κράσσος ᾔτει φύλακας· ἡ γὰρ πάροδος ἦν παρὰ τοὺς πολεμίους. εἰπόντος δὲ τοῦ Σύλλα σὺν ὀργῇ καὶ σφόδρα πρὸς αὐτόν, δίδωμί σοι φύλακας τὸν πατέρα, τὸν ἀδελφόν, τοὺς φίλους, τοὺς συγγενεῖς, ὧν παρανόμως καὶ ἀδίκως ἀναιρεθέντων ἐγὼ μετέρχομαι τοὺς φονεῖς, οὕτω παθών τι καὶ παροξυνθεὶς ὁ Κράσσος εὐθὺς ἐξῆλθε, καὶ διὰ τῶν πολεμίων ὠσάμενος εὐρώστως δύναμίν τε συχνὴν ἤθροισε καὶ πρόθυμον αὑτὸν ἐν τοῖς ἀγῶσι τῷ Σύλλᾳ παρεῖχεν.", "st": "Crass. 6.1"}, {"sp": "N", "t": "ἀπ’ ἐκείνων δὲ τῶν πράξεων λέγουσιν αὐτῷ πρῶτον ἐγγενέσθαι τὴν πρὸς Πομπήιον ὑπὲρ δόξης ἅμιλλαν καὶ φιλοτιμίαν. ὁ γὰρ Πομπήιος ἡλικίᾳ τε λειπόμενος αὐτοῦ καὶ πατρὸς γεγονὼς ἀδοξήσαντος ἐν Ῥώμῃ καὶ μισηθέντος ἔσχατον μῖσος ὑπὸ τῶν πολιτῶν, ἐν ἐκείνοις τοῖς πράγμασιν ἐξέλαμψε καὶ διεφάνη μέγας, ὥστε Σύλλαν, ἃ πρεσβυτέροις καὶ ἰσοτίμοις οὐ πάνυ πολλάκις παρεῖχεν, ὑπεξανίστασθαι προσιόντος αὐτοῦ καὶ κεφαλὴν ἀποκαλύπτεσθαι καὶ προσειπεῖν αὐτοκράτορα. ταῦτα διέκαιε καὶ παρώξυνε τὸν Κράσσον οὐκ ἀλόγως ἐλασσούμενον.", "st": "Crass. 6.4"}, {"sp": "N", "t": "Ἐμπειρίᾳς τε γὰρ ἐνδεὴς ἦν καὶ τῶν πράξεων αὐτοῦ τὴν χάριν ἀφῄρουν αἱ συγγενεῖς κῆρες ἐπιφερόμεναι, φιλοκέρδεια καὶ μικρολογία. καὶ γὰρ πόλιν Ὀμβρικὴν Τουδερτίαν ἑλών ἔδοξε πλεῖστα τῶν χρημάτων σφετερίσασθαι, καὶ διεβλήθη πρὸς Σύλλαν. ἀλλ’ ἔν γε τῷ περὶ τὴν Ῥώμην ἀγῶνι πάντων γενομένῳ μεγίστῳ καὶ τελευταίῳ Σύλλας μὲν ἡττήθη, τῶν κατ’ αὑτὸν ὠσθέντων καὶ συντριβέντων, Κράσσος δὲ τὸ δεξιὸν κέρας ἔχων ἐνίκησε καὶ μέχρι νυκτὸς διώξας τοὺς πολεμίους ἔπεμψε πρὸς Σύλλαν, δεῖπνον αἰτῶν τοῖς στρατιώταις καὶ τὸ κατόρθωμα φράζων. ἐν δὲ ταῖς προγραφαῖς καὶ δημεύσεσι πάλιν κακῶς ἤκουσεν, ὠνούμενός τε τιμῆς βραχείας μεγάλα πράγματα καὶ δωρεὰς αἰτῶν. ἐν δὲ Βρεττίοις λέγεται καὶ προγράψαι τινὰ οὐ Σύλλα κελεύσαντος, ἀλλ’ ἐπὶ χρηματισμῷ, δι’ ὃ καὶ Σύλλαν καταγνόντα πρὸς μηθὲν ἔτι χρῆσθαι δημόσιον αὐτῷ. καίτοι δεινότατος ἦν Κράσσος πάντας ἀνθρώπους κολακείᾳ κατεργάσασθαι, πάλιν δ’ αὐτὸς ὑπὸ πάντων διὰ κολακείας εὐάλωτος, ἴδιον δὲ κἀκεῖνο περὶ αὐτοῦ λέγεται, φιλοκερδέστατον ὄντα μάλιστα μισεῖν καὶ λοιδορεῖν τοὺς ὁμοίους.", "st": "Crass. 6.6"}, {"sp": "N", "t": "ἠνία δὲ Πομπήιος αὑτὸν εὐημερῶν ἐν ἡγεμονίαις καί πρὶν ἢ βουλῆς μεταλαβεῖν θριαμβεύων καὶ Μᾶγνος, ὅπερ ἐστὶ μέγας, ὑπὸ τῶν πολιτῶν ἀναγορευθείς, καί ποτε καί φήσαντός τινος ὡς Πομπήιος Μᾶγνος πρόσεισι, γελάσας ἠρώτησεν ὀπηλίκος. ἀπογνοὺς δὲ τοῖς πολεμικοῖς ἐξισώσασθαι πρὸς ἐκεῖνον, ὑπεδύετο τὴν πολιτείαν, σπουδαῖς καί συνηγορίαις καί δανεισμοῖς καί τῷ συμπαραγγέλλειν καί συνεξετάζεσθαι τοῖς δεομένοις τι τοῦ δήμου κτώμενος δύναμιν ἀντίπαλον καί δόξαν ᾗ Πομπήιος εἶχεν ἀπὸ πολλῶν καί μεγάλων στρατειῶν. καί πρᾶγμα συνέβαινεν αὐτοῖς ἴδιον. μεῖζον γὰρ ἦν ἀπόντος ὄνομα τοῦ Πομπηίου καί κράτος ἐν τῇ πόλει διὰ τὰς στρατείας· παρὼν δὲ πολλάκις ἠλαττοῦτο τοῦ Κράσσου, διὰ τὸν ὄγκον καί τὸ πρόσχημα τοῦ βίου φεύγων τὰ πλήθη καί ἀναδυόμενος ἐξ ἀγορᾶς, καί τῶν δεομένων ὀλίγοις καί μὴ πάνυ προθύμως βοηθῶν, ὡς ἀκμαιοτέραν ἔχοι τὴν δύναμιν ὑπὲρ αὑτοῦ χρώμενος. ὁ δὲ Κράσσος ἐνδελεχὲς τὸ χρήσιμον ἔχων καί σπάνιος οὐκ ὢν οὐδὲ δυσπρόσοδος, ἀλλ’ ἐν μέσαις ἀεὶ ταῖς σπουδαῖς ἀναστρεφόμενος, τῷ κοινῷ καί φιλανθρώπῳ περιεγίνετο τῆς ἐκείνου σεμνότητος, σώματος δὲ ἀξίωμα καί λόγου πειθὼ καί προσώπου χάριν ἀγωγὸν ἀμφοτέροις ὁμοίως προσεῖναι λέγουσιν.", "st": "Crass. 7.1"}, {"sp": "N", "t": "οὐ μέντοι πρὸς ἔχθραν τινὰ τὸν Κράσσον ἢ κακόνοιαν ἐξήνεγκεν οὗτος ὁ ζῆλος, ἀλλὰ καί Πομπηίῳ καί Καίσαρι τιμωμένοις μὲν ὑπὲρ αὑτὸν ἤχθετο, τῇ δὲ φιλοτιμίᾳ ταύτῃ δυσμένειαν ἢ κακοήθειαν οὐ συνῆπτε· καίτοι Καῖσαρ ὑπὸ λῃστῶν ἁλοὺς ἐν Ἀσίᾳ καὶ φρουρούμενος ἀνεβόησεν· ἡλίκης, ὦ Κράσσε, χαρᾶς ἀπολαύσεις πυθόμενος τὴν ἐμὴν ἅλωσιν. ἀλλ’ ὕστερόν γε φιλικῶς ἀλλήλοις προσεφέροντο· καί ποτε τῷ Καίσαρι μέλλοντι μὲν εἰς Ἰβηρίαν ἐξιέναι στρατηγῷ, χρήματα δ’ οὐκ ἔχοντι τῶν δανειστῶν ἐπιπεσόντων καί τῆς παρασκευῆς ἐπιλαμβανομένων ὁ Κράσσος οὐ περιεῖδεν, ἀλλ’ ἀπήλλαξεν ὑποθεὶς αὑτὸν ἔγγυον τριάκοντα καί ὀκτακοσίων ταλάντων. καθόλου δὲ τῆς Ῥώμης εἰς τρεῖς νενεμημένης δυνάμεις, τὴν Πομπηίου, τὴν Καίσαρος, τὴν Κράσσου Κάτωνος γὰρ ἡ δόξα μείζων ἦν τῆς δυνάμεως, καί τὸ θαυμαζόμενον πλέον ἴσχυεν, ἡ μὲν ἔμφρων καί καθεστῶσα μερὶς ἐν τῇ πόλει Πομπήιον ἐθεράπευε, τὸ δ’ ὀξὺ καί φερόμενον μετ’ εὐχερείας ταῖς Καίσαρος ἐλπίσιν ἐπηκολούθει, Κράσσος δὲ μέσος ὢν ἀμφοτέραις ἐχρῆτο, καί πλείστας μεταβολὰς ἐν τῇ πολιτείᾳ μεταβαλλόμενος οὔτε φίλος ἦν βέβαιος οὔτε ἀνήκεστος ἐχθρός, ἀλλὰ ῥᾳδίως καί χάριτος καί ὀργῆς ἐξέπιπτεν ὑπὸ τοῦ συμφέροντος, ὥστε πολλάκις μὲν ἀνθρώπων, πολλάκις δὲ νόμων ἐν ὀλίγῳ φανῆναι τῶν αὐτῶν συνήγορος καί ἀντίδικος. ἴσχυε δὲ καί χάριτι καί φόβῳ, φόβῳ δ’ οὐκ ἔλαττον. ὁ γοῦν πλεῖστα πράγματα παρασχὼν τοῖς καθ’ αὑτὸν ἄρχουσι καί δημαγωγοῖς, Σικίννιος, πρὸς τὸν εἰπόντα τί δὴ μόνον οὐ σπαράττει τὸν Κράσσον, ἀλλὰ παρίησι, χόρτον αὑτὸν ἔχειν ἔφησεν ἐπὶ τοῦ κέρατος, εἰώθεισαν δὲ Ῥωμαῖοι τὸν κυρίττοντα τῶν βοῶν ὑπὲρ τοῦ φυλάττεσθαι τοὺς ἐντυγχάνοντας χόρτῳ περιελίσσειν τὸ κέρας.", "st": "Crass. 7.5"}, {"sp": "N", "t": "ἡ δὲ τῶν μονομάχων ἐπανάστασις καὶ λεηλασία τῆς Ἰταλίας, ἣν οἱ πολλοὶ Σπαρτάκειον πόλεμον ὀνομάζουσιν, ἀρχὴν ἔλαβεν ἐκ τοιαύτης αἰτίας. Λέντλου τινὸς Βατιάτου μονομάχους ἐν Καπύῃ τρέφοντος, ὧν οἱ πολλοὶ Γαλάται καὶ Θρᾷκες ἦσαν, ἐξ αἰτιῶν οὐ πονηρῶν, ἀλλ’ ἀδικίᾳ τοῦ πριαμένου συνειρχθέντες ὑπ’ ἀνάγκης ἐπὶ τῷ μονομαχεῖν, ἐβουλεύσαντο μὲν διακόσιοι φεύγειν, γενομένης δὲ μηνύσεως οἱ προαισθόμενοι καὶ φθάσαντες ὀγδοήκοντα δυεῖν δέοντες ἔκ τινος ὀπτανείου κοπίδας ἀράμενοι καὶ ὀβελίσκους ἐξεπήδησαν, ἐντυχόντες δὲ κατὰ τὴν ὁδὸν ἁμάξαις ὅπλα κομιζούσαις μονομάχων εἰς ἑτέραν πόλιν ἀφήρπασαν καὶ ὡπλίσαντο· καὶ τόπον τινὰ καρτερὸν καταλαβόντες ἡγεμόνας εἵλοντο τρεῖς, ὧν πρῶτος ἦν Σπάρτακος, ἀνὴρ Θρᾷξ τοῦ Νομαδικοῦ γένους, οὐ μόνον φρόνημα μέγα καὶ ῥώμην ἔχων, ἀλλὰ καὶ συνέσει καὶ πρᾳότητι τῆς τύχης ἀμείνων καὶ τοῦ γένους Ἑλληνικώτερος. τούτῳ δὲ λέγουσιν, ὅτε πρῶτον εἰς Ῥώμην ὤνιος ἤχθη, δράκοντα κοιμωμένῳ περιπεπλεγμένον φανῆναι περὶ τὸ πρόσωπον, ἡ γυνὴ δ’ ὁμόφυλος οὖσα τοῦ Σπαρτάκου, μαντικὴ δὲ καὶ κάτοχος τοῖς περὶ τὸν Διόνυσον ὀργιασμοῖς, ἔφραζε τὸ σημεῖον εἶναι μεγάλης καὶ φοβερᾶς περὶ αὐτὸν εἰς εὐτυχὲς τέλος ἐσομένης δυνάμεως· ἣ καὶ τότε συνῆν αὐτῷ καὶ συνέφευγε.", "st": "Crass. 8.1"}, {"sp": "N", "t": "καὶ πρῶτον μὲν τούς ἐκ Καπύης ἐλθόντας ὠσάμενοι καὶ πολλῶν ὅπλων ἐπιλαβόμενοι πολεμιστηρίων ἄσμενοι ταῦτα μετελάμβανον, ἀπορρίψαντες ὡς ἄτιμα καὶ βάρβαρα τὰ τῶν μονομάχων ἔπειτα Κλωδίου στρατηγοῦ μετὰ τρισχιλίων πεμφθέντος ἐκ Ῥώμης καὶ πολιορκοῦντος αὐτοὺς ἐν ὄρει μίαν ἔχοντι καὶ χαλεπὴν καὶ στενὴν ἄνοδον, ἣν ὁ Κλώδιος ἐφρούρει, τὰ δ’ ἄλλα κρημνοὺς ἀποτόμους καὶ λισσάδας, ἄμπελον δὲ πολλὴν ἀγρίαν ἐπιπολῆς πεφυκυῖαν, ἔτεμνον τῶν κλημάτων τὰ χρήσιμα, καὶ συμπλέκοντες ἐξ αὐτῶν κλιμακίδας εὐτόνους καὶ βαθείας, ὥστ’ ἄνωθεν ἀνηρτημένας παρὰ τὸ κρημνῶδες ἅπτεσθαι τῶν ἐπιπέδων, κατέβαινον ἀσφαλῶς δι’ αὐτῶν πλὴν ἑνός. οὗτος δὲ τῶν ὅπλων ἕνεκα μείνας, ἐπεὶ κατέβησαν, ἠφίει κάτω τὰ ὅπλα καὶ βαλὼν ἅπαντα τελευταῖος ἀπεσῴζετο καὶ αὐτός. ταῦτ’ ἠγνόουν οἱ Ῥωμαῖοι· διὸ καὶ περιελθόντες αὐτοὺς ἐξέπληξαν τῷ αἰφνιδίῳ, καὶ φυγῆς γενομένης ἔλαβον τὸ στρατόπεδον. καὶ προσεγίνοντο πολλοὶ τῶν αὐτόθι βοτήρων καὶ ποιμένων αὐτοῖς, πλῆκται καὶ ποδώκεις ἄνδρες, ὧν τούς μὲν ὥπλιζον, τοῖς δὲ προδρόμοις καὶ ψιλοῖς ἐχρῶντο.", "st": "Crass. 9.1"}, {"sp": "N", "t": "δεύτερος ἐκπέμπεται πρὸς αὐτοὺς στρατηγὸς Πούπλιος Βαρῖνος, οὗ πρῶτα μὲν ὑποστράτηγόν τινα Φούριον ἔχοντα δισχιλίους στρατιώτας ἐτρέψαντο συμβαλόντες· ἔπειτα σύμβουλον αὐτῷ καὶ συνάρχοντα Κοσσίνιον ἀποσταλέντα μετὰ πολλῆς δυνάμεως ἐπιτηρήσας ὁ Σπάρτακος λουόμενον περὶ Σαλίνας, μικρὸν ἐδέησε συναρπάσαι. χαλεπῶς δὲ καὶ μόλις ἐκφυγόντος εὐθὺς μὲν ἐκράτησε τῆς ἀποσκευῆς, ἐκ ποδὸς δὲ κατέχων καὶ διώκων φόνῳ πολλῷ τὸ στρατόπεδον εἷλεν. ἔπεσε δὲ καὶ Κοσσίνιος. αὐτὸν δὲ τὸν στρατηγὸν ἄλλαις μάχαις πολλαῖς καταγωνισάμενος, τέλος δὲ τούς τε ῥαβδούχους καὶ τὸν ἵππον αὐτοῦ λαβὼν, ἤδη μὲν μέγας καὶ φοβερός ἦν, ἐφρόνει δὲ τὰ εἰκότα, καὶ μὴ προσδοκῶν ὑπερβαλέσθαι τὴν Ῥωμαίων δύναμιν ἦγεν ἐπὶ τὰς Ἄλπεις τὸν στρατόν, οἰόμενος δεῖν ὑπερβαλόντας αὐτὰς ἐπὶ τὰ οἰκεῖα χωρεῖν, τούς μὲν εἰς Θρᾴκην, τούς δ’ εἰς Γαλατίαν. οἱ δὲ πλήθει τε ὄντες ἰσχυροὶ καὶ μέγα φρονοῦντες οὐχ ὑπήκουον, ἀλλ’ ἐπόρθουν ἐπιπορευόμενοι τὴν Ἰταλίαν.", "st": "Crass. 9.4"}, {"sp": "N", "t": "οὐκέτ’ οὖν τὸ παρ’ ἀξίαν καὶ τὸ αἰσχρὸν ἠνώχλει τῆς ἀποστάσεως τὴν σύγκλητον, ἀλλὰ δὴ διὰ φόβον τε καὶ κίνδυνον ὡς πρὸς ἕνα τῶν δυσκολωτάτων πολέμων καὶ μεγίστων ἀμφοτέρους ἐξέπεμπον τούς ὑπάτους. ὧν Γέλλιος μὲν τὸ Γερμανικόν ὕβρει καὶ φρονήματι τῶν Σπαρτακείων ἀποσχισθέν ἐξαίφνης ἐμπεσὼν ἅπαν διέφθειρε, Λέντλου δὲ τὸν Σπάρτακον μεγάλοις στρατοπέδοις περιλαβόντος ὁρμήσας ὁμόσε καὶ μάχην συνάψας ἐκράτησε μὲν τῶν πρεσβευτῶν, ἔλαβε δὲ τὴν ἀποσκευὴν ἅπασαν, ὠθουμένῳ δ’ αὐτῷ πρὸς τὰς Ἄλπεις Κάσσιος ὁ τῆς περὶ Πάδον Γαλατίας στρατηγὸς ἔχων μυρίους ἀπήντησε· καὶ γενομένης μάχης κρατηθεὶς καὶ πολλοὺς ἀποβαλών μόλις αὐτὸς ἐξέφυγε.", "st": "Crass. 9.7"}, {"sp": "N", "t": "ταῦθ’ ἡ βουλὴ πυθομένη τοὺς μὲν ὑπάτους πρὸς ὀργὴν ἐκέλευσεν ἡσυχίαν ἄγειν, Κράσσον δὲ τοῦ πολέμου στρατηγὸν εἵλετο καὶ πολλοὶ διὰ δόξαν αὐτῷ καὶ φιλίαν συνεστράτευον τῶν ἐπιφανῶν, αὐτὸς μὲν οὖν ὑπέμεινε πρὸ τῆς Πικηνίδος ὡς τὸν Σπάρτακον ἐκεῖ φερόμενον δεξόμενος, Μόμμιον δὲ πρεσβευτὴν ἄγοντα δύο τάγματα κύκλῳ περιέπεμψεν, ἕπεσθαι κελεύσας τοῖς πολεμίοις, συμπλέκεσθαι δὲ μὴ μηδὲ ἁψιμαχεῖν. ὁ δ’ ἅμα τῷ πρῶτον ἐπ’ ἐλπίδος γενέσθαι μάχην θέμενος ἡττήθη· καὶ πολλοὶ μὲν ἔπεσον, πολλοὶ δὲ ἄνευ τῶν ὅπλων φεύγοντες ἐσώθησαν. ὁ δὲ Κράσσος αὐτόν τε τὸν Μόμμιον ἐδέξατο τραχέως, καὶ τοὺς στρατιώτας ὁπλίζων αὖθις ἐγγυητὰς ᾔτει τῶν ὅπλων, ὅτι φυλάξουσι, πεντακοσίους δὲ τοὺς πρώτους, καὶ μάλιστα τοὺς τρέσαντας, εἰς πεντήκοντα διανείμας δεκάδας ἀφ’ ἑκάστης ἀπέκτεινεν ἕνα τὸν κλήρῳ λαχόντα, πάτριόν τι τοῦτο διὰ πολλῶν χρόνων κόλασμα τοῖς στρατιώταις ἐπαγαγών. καὶ γὰρ αἰσχύνη τοῦ θανάτου τῷ τρόπῳ πρόσεστι, καὶ δρᾶται πολλὰ φρικώδη καὶ σκυθρωπὰ περὶ τὴν κόλασιν ἁπάντων θεωμένων.", "st": "Crass. 10.1"}, {"sp": "N", "t": "οὕτω δ’ ἐπιστρέψας τοὺς ἄνδρας ἦγεν ἐπὶ τοὺς πολεμίους. ὁ δὲ Σπάρτακος ὑπεξεχώρει διὰ Λευκανίας εἰς τὴν θάλασσαν ἐν δὲ πορθμῷ λῃστρίσι Κιλίσσαις ἐπιτυχὼν ὥρμησεν ἅψασθαι Σικελίας καὶ δισχιλίους ἄνδρας ἐμβαλὼν εἰς τὴν νῆσον αὖθις ἐκζωπυρῆσαι τὸν δουλικὸν ἐκεῖ πόλεμον, οὔπω πολὺν χρόνον ἀπεσβηκότα καὶ μικρῶν πάλιν ὑπεκκαυμάτων δεόμενον. ὁμολογήσαντες δὲ οἱ Κίλικες αὐτῷ καὶ δῶρα λαβόντες ἐξηπάτησαν καὶ ἀπέπλευσαν. οὕτω δὴ πάλιν ἀπὸ θαλάσσης ἀναζεύξας ἐκάθισε τὸν στρατὸν εἰς τὴν Ῥηγίνων χερρόνησον. ἐπελθὼν δ’ ὁ Κράσσος, καὶ τοῦ τόπου τὴν φύσιν ὁρῶν ὑφηγουμένην τὸ δέον, ὥρμησεν ἀποτειχίσαι τὸν ἰσθμόν, ἅμα καὶ τὴν σχολὴν τῶν στρατιωτῶν ὑφαιρῶν καὶ τὴν εὐπορίαν τῶν πολεμίων. μέγα μὲν οὖν ἦν καὶ χαλεπὸν τὸ ἔργον, ἤνυσε δὲ καὶ κατειργάσατο παρὰ δόξαν ἐν ὀλίγῳ χρόνῳ, τάφρον ἐμβαλὼν ἐκ θαλάσσης εἰς θάλασσαν διὰ τοῦ αὐχένος σταδίων τριακοσίων, εὖρος δὲ καὶ βάθος ἴσον πεντεκαίδεκα ποδῶν ὑπὲρ δὲ τῆς τάφρου τεῖχος ἔστησεν ὕψει καὶ ῥώμῃ θαυμαστόν. ὧν ὁ Σπάρτακος ἡμέλει καὶ κατεφρόνει τὸ πρῶτον ὡς δὲ τῆς λείας ἐπιλειπούσης προϊέναι βουλόμενος συνεῖδε τὸν ἀποτειχισμόν καὶ λαμβάνειν οὐδὲν ἦν ἐκ τῆς χερρονήσου, νύκτα νιφετώδη καὶ πνεῦμα τι χειμέριον παραφυλάξας ἔχωσε τῆς τάφρου μέρος οὐ πολὺ γῇ καὶ ὕλῃ καὶ κλάδοις δένδρων, ὥστε τῆς στρατιᾶς περαιῶσαι τὸ τρίτον.", "st": "Crass. 10.4"}, {"sp": "N", "t": "ἐφοβήθη μὲν οὖν ὁ Κράσσος μὴ λάβοι τις ὁρμὴ τὸν Σπάρτακον ἐπὶ τὴν Ῥώμην ἐλαύνειν, ἐθάρρησε δὲ πολλῶν ἐκ διαφορᾶς ἀποστάντων αὐτοῦ καὶ στρατοπεδευσαμένων καθ’ αὑτοὺς ἐπὶ Λευκανίδος λίμνης, ἥν φασι τρέπεσθαι διὰ χρόνου γινομένην γλυκεῖαν καὶ αὖθις ἁλμυρὰν καὶ ἄποτον. τούτοις ἐπελθὼν ὁ Κράσσος ἐξέωσε μὲν ἀπὸ τῆς λίμνης, ἀφῃρέθη δὲ τὸν φόνον καὶ τὴν δίωξιν αὐτῶν ἐπιφανέντος ὀξέως τοῦ Σπαρτάκου καὶ τὴν φυγὴν ἐπιστήσαντος.", "st": "Crass. 11.1"}, {"sp": "N", "t": "γεγραφὼς δὲ τῇ βουλῇ πρότερον ὡς χρὴ καὶ Λούκουλλον ἐκ Θρᾴκης καλεῖν καὶ Πομπήιον ἐξ Ἰβηρίας, μετενόει, καὶ πρὶν ἥκειν ἐκείνους ἔσπευδε διαπράξασθαι τὸν πόλεμον, εἰδὼς ὅτι τοῦ προσγενομένου καὶ βοηθήσαντος, οὐκ αὐτοῦ τὸ κατόρθωμα δόξει. πρῶτον μὲν οὖν διαγνοὺς τοῖς ἀφεστῶσι καὶ κατ’ ἰδίαν στρατευομένοις, ὧν ἀφηγοῦντο Γάιος Καννίκιος καὶ Κάστος, ἐπιθέσθαι, λόφον τινὰ προκαταληψομένους ἄνδρας ἑξακισχιλίους ἀπέστειλε, λανθάνειν πειρᾶσθαι κελεύσας. οἱ δ’ ἐπειρῶντο μὲν τὴν αἴσθησιν ἀποκρύπτειν τὰ κράνη καταμπέχοντες, ὀφθέντες δ’ ὑπὸ δυεῖν γυναικῶν προθυομένων τοῖς πολεμίοις ἐκινδύνευσαν, εἰ μὴ Κράσσος ὀξέως ἐπιφανεὶς μάχην ἔθετο πασῶν καρτερωτάτην, ἐν ᾗ τριακοσίους ἐπὶ δισχιλίοις καὶ μυρίοις καταβαλὼν δύο μόνους εὗρε κατὰ νώτου τετρωμένους, οἱ δ’ ἄλλοι πάντες ἑστῶτες ἐν τάξει καὶ μαχόμενοι τοῖς Ῥωμαίοις ἀπέθανον.", "st": "Crass. 11.2"}, {"sp": "N", "t": "Σπαρτάκῳ δὲ μετὰ τὴν τούτων ἧτταν ἀναχωροῦντι πρὸς τὰ ὄρη τὰ Πετηλῖνα, Κόιντος τῶν περὶ Κράσσον ἡγεμόνων καὶ Σκρώφας ταμίας ἐξαπτόμενοι παρηκολούθουν. ἐπιστρέψαντος δὲ γίνεται φυγὴ μεγάλη τῶν Ῥωμαίων, καὶ μόλις τρωθέντα τὸν ταμίαν ἁρπάσαντες ἀπεσώθησαν. τοῦτο τὸν Σπάρτακον ἀπώλεσε τὸ κατόρθωμα, φρονήματος ἐπιγενομένου τοῖς δραπέταις. οὐκέτι γὰρ ἠξίουν φυγομαχεῖν οὐδ’ ἐπείθοντο τοῖς ἄρχουσιν, ἀλλ’ ἤδη καθ’ ὁδὸν ὄντας ἐν τοῖς ὅπλοις περισχόντες ἠνάγκασαν αὖθις ὀπίσω διὰ τῆς Λευκανίας ἄγειν ἐπὶ τοὺς Ῥωμαίους, εἰς ταὐτὸ τῷ Κράσσῳ σπεύδοντες. ἤδη γὰρ ὁ Πομπήιος προσιὼν ἀπηγγέλλετο· καὶ δὴ ἀρχαιρεσιάζοντες ἦσαν οὐκ ὀλίγοι τὴν νίκην ἐκείνῳ τοῦ πολέμου προσήκειν ἐλθόντα γὰρ εὐθὺς μαχεῖσθαι καὶ καταλύσειν τὸν πόλεμον. ἐπειγόμενος οὖν διαγωνίσασθαι καὶ παραστρατοπεδεύσας τοῖς πολεμίοις ὤρυττε τάφρον, πρὸς ἣν ἐκπηδῶντες οἱ δοῦλοι προσεμάχοντο τοῖς ἐργαζομένοις. ἀεὶ δὲ πλειόνων ἑκατέρωθεν ἐκβοηθούντων ὁρῶν τὴν ἀνάγκην ὁ Σπάρτακος ἅπαν παρέταξε τὸ στράτευμα.", "st": "Crass. 11.4"}, {"sp": "N", "t": "καὶ πρῶτον μὲν τοῦ ἵππου προσαχθέντος αὐτῷ σπασάμενος τὸ ξίφος καὶ εἰπών ὅτι νικῶν μὲν ἔχοι πολλοὺς ἵππους καὶ καλοὺς τῶν πολεμίων, ἡττώμενος δὲ οὐ δεῖται, κατέσφαξε τὸν ἵππον· ἔπειτα πρὸς Κράσσον αὐτὸν ὠθούμενος διὰ πολλῶν ὅπλων καὶ τραυμάτων ἐκείνου μὲν οὐκ ἔτυχεν, ἑκατοντάρχας δὲ δύο συμπεσόντας ἀνεῖλε. τέλος δὲ φυγόντων τῶν περὶ αὐτόν, αὐτὸς ἑστὼς καὶ κυκλωθεὶς ὑπὸ πολλῶν ἀμυνόμενος κατεκόπη. Κράσσου δὲ τῇ τύχῃ χρησαμένου καὶ στρατηγήσαντος ἄριστα καὶ τὸ σῶμα τῷ κινδύνῳ παρασχόντος, ὅμως οὐ διέφυγε τὸ κατόρθωμα τὴν Πομπηΐου δόξαν. οἱ γὰρ διαφυγόντες ἐμπεσόντες αὐτῷ διεφθάρησαν, ὥστε καὶ γράψαι πρὸς τὴν σύγκλητον ὅτι μάχῃ μὲν τοὺς δραπέτας φανερᾷ Κράσσος νενίκηκεν, αὐτὸς δὲ τοῦ πολέμου τὴν ῥίζαν ἀνῄρηκε. Πομπήιος μὲν οὖν ἀπὸ Σερτωρίου καὶ Ἰβηρίας ἐπιφανῶς ἐθριάμβευσε, Κράσσος δὲ τὸν μὲν μέγαν θρίαμβον οὐδ’ αὐτὸς αἰτεῖν ἐπεχείρησεν, ἐδόκει δὲ καὶ τὸν πεζόν, ὀούαν δὲ καλούμενον, ἀγεννῶς καὶ παρ’ ἀξίαν ἐπὶ δουλικῷ πολέμῳ θριαμβεῦσαι. τί δ’ οὗτος ἐκείνου διαφέρει, καὶ περὶ τῆς κλήσεως, ἐν τῷ Μαρκέλλου βίῳ γέγραπται.", "st": "Crass. 11.7"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τοῦ Πομπηίου αὐτόθεν ἐπὶ τὴν ὑπατείαν καλουμένου, ἐλπίδας ἔχων ὁ Κράσσος συνάρξειν ὅμως οὐκ ὤκνησε τοῦ Πομπηίου δεηθῆναι. δεξάμενος δὲ τὴν χρείαν ἀσμένως ἐκεῖνος ἐπεθύμει γὰρ ἁμῶς γέ πως ἀεὶ χάριτός τινος ὀφειλέτην λαβεῖν τὸν Κράσσον ἐσπούδασε προθύμως, καὶ τέλος εἶπεν ἐκκλησιάζων ὡς οὐκ ἐλάττονα περὶ τοῦ συνάρχοντος ἕξει χάριν ἢ περὶ τῆς ἀρχῆς. οὐ μὴν ἔμειναν ἐπὶ ταύτης τῆς φιλοφροσύνης εἰς τὴν ἀρχὴν καταστάντες, ἀλλ’ ὀλίγου δεῖν περὶ πάντων διαφερόμενοι καὶ πάντα δυσκολαίνοντες ἀλλήλοις καὶ φιλονεικοῦντες ἀπολίτευτον καὶ ἄπρακτον αὑτοῖς τὴν ὑπατείαν ἐποίησαν, πλὴν ὅτι Κράσσος Ἡρακλεῖ μεγάλην θυσίαν ποιησάμενος εἱστίασε τὸν δῆμον ἀπὸ μυρίων τραπεζῶν καὶ σῖτον ἐμέτρησεν εἰς τρίμηνον. ἤδη δὲ τῆς ἀρχῆς αὑτοῖς τελευτώσης ἔτυχον μὲν ἐκκλησιάζοντες, ἀνὴρ δέ τις οὐ τῶν ἐπιφανῶν, ἱππεὺς Ῥωμαίων, ἀγροῖκος δὲ τῷ βίῳ καὶ ἰδιώτης, Ὀνότιος Αὐρήλιος, ἀναβὰς ἐπὶ τὸ βῆμα καὶ προελθὼν ὄψιν διηγεῖτο κατὰ τοὺς ὕπνους αὐτῷ γενομένην. ὁ γὰρ Ζεύς, ἔφη, μοι φανεὶς προσέταξεν εἰς κοινὸν εἰπεῖν ὅπως μὴ πρότερον περιίδητε τοὺς ὑπάτους ἀποθέσθαι τὴν ἀρχὴν ἢ φίλους γενέσθαι. ταῦτα λέγοντος τοῦ ἀνθρώπου καὶ τοῦ δήμου διαλλάττεσθαι κελεύοντος, ὁ μὲν Πομπήιος ἡσυχίαν ἦγεν ἑστώς, ὁ δὲ Κράσσος ἐμβαλὼν τὴν δεξιὰν αὐτῷ πρότερος, οὐδέν, εἶπεν, ὦ ἄνδρες, οἶμαι, πολῖται, ταπεινὸν πράττειν οὐδ’ ἀνάξιον ἐμαυτοῦ καταρχόμενος εὐνοίας καὶ φιλίας πρὸς Πομπήϊον, ὃν ὑμεῖς μήπω γενειῶντα Μέγαν ἀνηγορεύσατε καὶ μήπω μετέχοντι βουλῆς ἐψηφίσασθε θρίαμβον.", "st": "Crass. 12.1"}, {"sp": "N", "t": "ἡ μέν οὖν ὑπατεία τοῦ Κράσσου ταῦτ’ ἔσχεν ἄξια μνήμης, ἡ δὲ τιμητεία παντάπασιν ἀτελὴς καὶ ἄπρακτος αὐτῷ διῆλθεν, οὔτε γὰρ βουλῆς ἐξέτασιν οὔθ’ ἱππέων ἐπίσκεψιν οὔτ’ ἀποτίμησιν πολιτῶν ἐποιήσατο, καίτοι συνάρχοντα Ῥωμαίων ἔχοντι τὸν πρᾳότατον Λουτάτιον Κάτλον. ἀλλά φασιν ἐπὶ δεινὸν ὁρμήσαντι τῷ Κράσσῳ πολίτευμα καὶ βίαιον, Αἴγυπτον ποιεῖν ὑποτελῆ Ῥωμαίοις, ἀντιβῆναι τὸν Κάτλον ἐρρωμένως ἐκ δὲ τούτου γενομένης διαφορᾶς ἑκόντας ἀποθέσθαι τὴν ἀρχήν.", "st": "Crass. 13.1"}, {"sp": "N", "t": "ἐν δὲ τοῖς περὶ Κατιλίναν πράγμασι μεγάλοις καὶ μικροῦ δεήσασιν ἀνατρέψαι τὴν Ῥώμην, ἥψατο μέν τις ὑπόνοια τοῦ Κράσσου καὶ προσῆλθεν ἄνθρωπος ὀνομάζων ἀπὸ τῆς συνωμοσίας, οὐδεὶς δὲ ἐπίστευσεν. ὅμως δ’ ὁ Κικέρων ἔν τινι λόγῳ φανερός ἦν Κράσσῳ καὶ Καίσαρι τὴν αἰτίαν προστριβόμενος. ἀλλ’ οὗτος μέν ὁ λόγος ἐξεδόθη μετὰ τὴν ἀμφοῖν τελευτήν, ἐν δὲ τῷ Περὶ ὑπατείας ὁ Κικέρων νύκτωρ φησὶ τὸν Κράσσον ἀφικέσθαι πρὸς αὐτόν ἐπιστολὴν κομίζοντα τὰ περὶ τὸν Κατιλίναν ἐξηγουμένην, ὡς ἤδη βεβαιοῦντα τὴν συνωμοσίαν. ὁ δ’ οὖν Κράσσος ἀεὶ μέν ἐμίσει τὸν Κικέρωνα διὰ τοῦτο, τοῦ δὲ βλάπτειν ἀναφανδὸν ἐμποδὼν εἶχε τὸν υἱόν. ὁ γὰρ Πόπλιος ὢν φιλολόγος καὶ φιλομαθὴς ἐξήρτητο τοῦ Κικέρωνος, ὥστε καὶ συμμεταβαλεῖν αὐτῷ τὴν ἐσθῆτα κρινομένῳ καὶ τοὺς ἄλλους νέους ταὐτὰ ποιοῦντας παρασχεῖν. τέλος δὲ τὸν πατέρα πείσας φίλον ἐποίησεν.", "st": "Crass. 13.2"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ὡς ἐπανῆλθεν ἀπὸ τῆς ἐπαρχίας, παρασκευαζόμενος ὑπατείαν μετιέναι καὶ Κράσσον ὁρῶν καὶ Πομπήιον αὖθις ἐν διαφοραῖς πρὸς ἀλλήλους ὄντας, οὔτε θατέρου δεηθεὶς ἐβούλετο λαβεῖν ἐχθρὸν τὸν ἕτερον, οὔτε μηδετέρου συνεργοῦντος ἤλπιζε κατορθώσειν. ἔπραττεν οὖν διαλλαγὰς αὐτοῖς προσκείμενος καὶ διδάσκων ὡς καταλύοντες ἀλλήλους αὔξουσι Κικέρωνας καὶ Κάτλους καὶ Κάτωνας, ὧν οὐδεὶς λόγος, ἂν ἐκεῖνοι συνενεγκόντες εἰς ταὐτὸ τὰς φιλίας καὶ τὰς ἑταιρείας ἑνὶ κράτει καὶ μιᾷ γνώμῃ τήν πόλιν ἄγωσιν. πείσας δὲ καὶ διαλλάξας συνήγαγε καὶ συνέστησεν ἐκ τῶν τριῶν ἰσχὺν ἄμαχον, ᾗ κατέλυσε Ῥωμαίων τήν βουλὴν καὶ τὸν δῆμον, οὐκ ἐκείνους δι’ ἀλλήλων μείζονας, ἀλλὰ δι’ ἐκείνων ἑαυτὸν μέγιστον ἀπεργασάμενος. εὐθὺς γὰρ ἀρθεὶς ὑπ’ ἀμφοτέρων ὕπατος ἀπεδείχθη λαμπρῶς. ὑπατεύοντι δ’ αὐτῷ ψηφισάμενοι στρατευμάτων ἡγεμονίαν καὶ Γαλατίαν ἐγχειρίσαντες ὥσπερ εἰς ἀκρόπολιν κατέστησαν, οἰόμενοι καθ’ ἡσυχίαν νεμήσεσθαι τὰ λοιπὰ πρὸς ἀλλήλους ἐκείνῳ βεβαιοῦντες ἣν ἔλαχεν ἀρχήν.", "st": "Crass. 14.1"}, {"sp": "N", "t": "Πομπήιος μὲν οὖν ὑπὸ φιλαρχίας ἀμέτρου ταῦτ’ ἔπραττε· τῶν δὲ Κράσσου νοσημάτων τὸ ἀρχαῖον ἡ φιλοπλουτία καινὸν ἔρωτα προσλαβοῦσα καὶ ζῆλον ἐπὶ ταῖς Καίσαρος ἀριστείαις τροπαίων καὶ θριάμβων, οἷς γε μόνοις ἐλαττοῦσθαι προὔχοντα τοῖς ἄλλοις, αὐτὸν οὐκ ἀνῆκεν οὐδ’ ἐλώφησε πρὶν εἰς ὄλεθρον ἀκλεῆ καὶ δημοσίας συμφορὰς τελευτῆσαι. Καίσαρος γὰρ εἰς Λοῦκαν πόλιν ἐκ Γαλατίας καταβάντος ἄλλοι τε πολλοὶ Ῥωμαίων ἀφίκοντο, καὶ Πομπήιος καὶ Κράσσος ἰδίᾳ συγγενόμενοι πρὸς αὐτὸν ἔγνωσαν ἐγκρατέστερον ἔχεσθαι τῶν πραγμάτων καὶ πᾶσαν ὑφ’ ἑαυτοῖς ποιεῖσθαι τήν ἡγεμονίαν, Καίσαρος μὲν ἐν τοῖς ὅπλοις μένοντος, ἄλλας δὲ ἐπαρχίας καὶ στρατεύματα Πομπηίου καὶ Κράσσου λαβόντων. ἐνταῦθα δ’ ὁδὸς ἦν μία δευτέρας ὑπατείας αἴτησις ἣν μετιόντων ἐκείνων ἔδει συμπράττειν Καίσαρα, τοῖς τε φίλοις γράφοντα καὶ τῶν στρατιωτῶν πέμποντα πολλοὺς ἀρχαιρεσιάσοντας.", "st": "Crass. 14.4"}, {"sp": "N", "t": "ἐπὶ τούτοις οἱ περὶ Κράσσον εἰς Ῥώμην ἐπανελθόντες εὐθὺς ἦσαν ὕποπτοι, καί πολὺς ἐχώρει διὰ πάντων λόγος οὐκ ἐπ’ ἀγαθῷ γεγονέναι τὴν σύνοδον αὐτῶν, ἐν δὲ τῇ βουλῇ Μαρκελλίνου καί Δομιτίου Πομπήιον ἐρωτώντων εἰ μέτεισιν ὑπατείαν, ἀπεκρίνατο τυχὸν μὲν μετιέναι, τυχὸν δὲ μὴ μετιέναι· καί πάλιν ἐρωτώμενος ἔφη μετιέναι τοῖς δικαίοις πολίταις, μὴ μετιέναι δὲ τοῖς ἀδίκοις. τούτου δὲ δόξαντος ὑπερηφάνους ἀποκρίσεις καί τετυφωμένας ποιεῖσθαι μετριώτερον ὁ Κράσσος εἶπεν, εἰ τῇ πόλει συμφέρει, μετιέναι τὴν ἀρχήν, εἰ δὲ μή, ποιεῖσθαι. διὸ καί τινες ἐθάρρησαν ὑπατείαν μετελθεῖν, ὧν ἦν καί Δομίτιος. γενομένων δὲ φανερῶν ἐκείνων ἐν ταῖς παραγγελίαις οἱ μὲν ἄλλοι δείσαντες ἀπέστησαν, Δομίτιον δὲ Κάτων οἰκεῖον ὄντα καί φίλον ἐθάρρυνεν ἐγκελευόμενος καί παρορμῶν ἔχεσθαι τῆς ἐλπίδος ὡς ὑπερμαχοῦντα τῆς κοινῆς ἐλευθερίας· οὐ γὰρ ὑπατείας Πομπήιον δεῖσθαι καί Κράσσον, ἀλλὰ τυραννίδος, οὐδ’ ἀρχῆς αἴτησιν, ἀλλ’ ἁρπαγὴν ἐπαρχιῶν καί στρατοπέδων εἶναι τὰ πραττόμενα.", "st": "Crass. 15.1"}, {"sp": "N", "t": "ταῦτα δὲ καί λέγων οὕτω καί φρονῶν ὁ Κάτων μονονοὺ βίᾳ προῆγεν εἰς ἀγορὰν τὸν Δομίτιον, καί συνίσταντο πολλοὶ πρὸς αὐτούς, καί τὸ θαυμάζον οὐκ ὀλίγον ἦν, τί δὴ δευτέρας οὗτοι χρῄζουσιν ὑπατείας; τί δὲ πάλιν μετ’ ἀλλήλων; τί δ’ οὐ μεθ’ ἑτέρων; πολλοὶ δ’ εἰσὶν ἄνδρες ἡμῖν οὐκ ἀνάξιοι δήπου Κράσσῳ καί Πομπηίῳ συνάρχειν. ἐκ τούτου δείσαντες οἱ περὶ Πομπήϊον οὐδενὸς ἀπείχοντο τῶν ἀκοσμοτάτων καί βιαιοτάτων, ἀλλὰ πρὸς πᾶσι τοῖς ἄλλοις λόχον ὑφέντες τῷ Δομιτίῳ νυκτὸς ἔτι μετὰ τῶν ἄλλων κατερχομένῳ κτείνουσι μὲν τὸν ἀνέχοντα τὸ φῶς πρὸ αὐτοῦ, συντιτρώκουσι δὲ πολλούς, ὧν ἦν καί Κάτων, τρεψάμενοι δὲ καί κατακλείσαντες εἰς τὴν οἰκίαν ἐκείνους ἀνηγορεύθησαν ὕπατοι· καί μετ’ οὐ πολὺν χρόνον αὖθις ὅπλοις περισχόντες τὸ βῆμα καί τὸν Κάτωνα τῆς ἀγορᾶς ἐκβαλόντες καί τινας ὑποστάντας ἀποκτείναντες, Καίσαρι μὲν ἄλλην ἐπέδοσαν πενταετίαν τῆς ἀρχῆς, αὑτοῖς δὲ τῶν ἐπαρχιῶν ἐψηφίσαντο Συρίαν καὶ Ἰβηρίας συναμφοτέρας. κληρουμένων δὲ Συρίαν ἔλαχε Κράσσος, τὰ δ’ Ἰβηρικὰ Πομπήιος.", "st": "Crass. 15.3"}, {"sp": "N", "t": "ἦν δὲ οὐκ ἀκούσιος ὁ κλῆρος ἅπασιν. οἵ τε γὰρ πολλοὶ Πομπήϊον μὴ μακρὰν εἶναι τῆς πόλεως ἐβούλοντο, καὶ Πομπήϊος ἐρῶν τῆς γυναικὸς αὐτόθι τὰ πολλὰ διατρίβειν ἔμελλε, Κράσσος δὲ ὑπὸ χαρᾶς εὐθὺς ἐκπεσόντι τῷ κλήρῳ καταφανὴς ἦν οὐδὲν εὐτύχημα λαμπρότερον ἑαυτῷ γεγονέναι τοῦ παρόντος ἡγούμενος, ὡς μόλις ἐν ἀλλοτρίοις καὶ πολλοῖς ἡσυχίαν ἄγειν, πρὸς δὲ τοὺς συνήθεις πολλὰ κενὰ καὶ μειρακιώδη λέγειν παρ’ ἡλικίαν τὴν ἑαυτοῦ καὶ φύσιν, ἥκιστα κομπαστὴς ἢ σοβαρὸς τῷ βίῳ γεγονώς. τότε δ’ ἐπηρμένος κομιδῇ καὶ διεφθαρμένος οὐ Συρίαν οὐδὲ Πάρθους ὅρον ἐποιεῖτο τῆς εὐπραξίας, ἀλλ’ ὡς παιδιὰν ἀποφανῶν τὰ Λουκούλλου πρὸς Τιγράνην καὶ Πομπηΐου πρὸς Μιθριδάτην, ἄχρι Βακτρίων καὶ Ἰνδῶν καὶ τῆς ἔξω θαλάσσης ἀνῆγεν ἑαυτὸν ταῖς ἐλπίσι.", "st": "Crass. 16.1"}, {"sp": "N", "t": "καίτοι τῷ γραφέντι περὶ τούτων νόμῳ Παρθικὸς πόλεμος οὐ προσῆν. ᾔδεσαν δὲ πάντες ὅτι πρὸς τοῦτο Κράσσος ἐπτόηται· καὶ Καῖσαρ ἐκ Γαλατίας ἔγραφεν αὐτῷ τὴν ὁρμὴν ἐπαινῶν καὶ παροξύνων ἐπὶ τὸν πόλεμον. ἐπεὶ δὲ δημαρχῶν Ἀτήιος ἔμελλε πρὸς τὴν ἔξοδον ἐναντιώσεσθαι, καὶ συνίσταντο πολλοὶ χαλεπαίνοντες εἴ τις ἀνθρώποις οὐδὲν ἀδικοῦσιν, ἀλλ’ ἐνσπόνδοις, πολεμήσων ἄπεισι, δείσας ὁ Κράσσος ἐδεήθη Πομπηΐου παραγενέσθαι καὶ συμπροπέμψαι· μέγα γὰρ ἦν ἐκείνου τὸ πρὸς τὸν ὄχλον ἀξίωμα· καὶ τότε παρεσκευασμένους πολλοὺς ἐνίστασθαι καὶ καταβοᾶν ὁρώμενος πρὸ αὐτοῦ φαιδρῷ βλέμματι καὶ προσώπῳ κατεπράυνεν ὁ Πομπήιος, ὥσθ’ ὑπείκειν σιωπῇ δι’ αὐτῶν προϊοῦσιν. ὁ δ’ Ἀτήιος ἀπαντήσας πρῶτον μὲν ἀπὸ φωνῆς ἐκώλυε καὶ διεμαρτύρετο μὴ βαδίζειν, ἔπειτα τὸν ὑπηρέτην ἐκέλευεν ἁψάμενον τοῦ σώματος κατέχειν. ἄλλων δὲ δημάρχων οὐκ ἐώντων, ὁ μὲν ὑπηρέτης ἀφῆκε τὸν Κράσσον, ὁ δ’ Ἀτήιος προδραμὼν ἐπὶ τὴν πύλην ἔθηκεν ἐσχαρίδα καιομένην, καὶ τοῦ Κράσσου γενομένου κατ’ αὐτήν ἐπιθυμιῶν καὶ κατασπένδων ἀρὰς ἐπηρᾶτο δεινὰς μὲν αὐτὰς καὶ φρικώδεις, δεινοὺς δέ τινας θεοὺς καὶ ἀλλοκότους ἐπ’ αὐταῖς καλῶν καὶ ὀνομάζων· ταύτας φασὶ Ῥωμαῖοι τὰς ἀρὰς ἀποθέτους καὶ παλαιὰς τοιαύτην ἔχειν δύναμιν ὡς περιφυγεῖν μηδένα τῶν ἐνσχεθέντων αὐταῖς, κακῶς δὲ πράσσειν καὶ τὸν χρησάμενον, ὅθεν οὐκ ἐπὶ τοῖς τυχοῦσιν αὐτὰς οὐδ’ ὑπὸ πολλῶν ἀρᾶσθαι. καὶ τότ’ οὖν ἐμέμφοντο τὸν Ἀτήιον, εἰ δι’ ἣν ἐχαλέπαινε τῷ Κράσσῳ πόλιν, εἰς αὐτήν ἀρὰς ἀφῆκε καὶ δεισιδαιμονίαν τοσαύτην.", "st": "Crass. 16.3"}, {"sp": "N", "t": "ὁ δὲ Κράσσος εἰς Βρεντέσιον ἦλθεν. ἔτι δ’ ἀστατούσης χειμῶσι τῆς θαλάσσης οὐ περιέμεινεν, ἀλλ’ ἀνήχθη καὶ συχνὰ τῶν πλοίων ἀπέβαλε, τὴν δ’ ἄλλην ἀναλαβὼν δύναμιν ἠπείγετο πεζῇ διὰ Γαλατίας, εὑρὼν δὲ τὸν βασιλέα Δηιόταρον πάνυ μὲν ὄντα γηραιὸν ἤδη, κτίζοντα δὲ νέαν πόλιν, ἐπέσκωψεν εἰπών ὦ βασιλεῦ, δωδεκάτης ὥρας οἰκοδομεῖν ἄρχῃ. γελάσας δ’ ὁ Γαλάτης· ἀλλ’ οὐδ’ αὐτός, εἶπεν, ὦ αὐτόκρατορ, ὡς ὁρῶ, πρωὶ λίαν ἐπὶ Πάρθους ἐλαύνεις. ἦν δ’ ὁ Κράσσος ἑξήκοντα μὲν ἔτη παραλλάττων, πρεσβύτερος δὲ τὴν ὄψιν ἢ καθ’ ἡλικίαν. ἀφικόμενον δ’ αὐτὸν ἐδέξατο τὰ πράγματα τῆς ἐλπίδος ἀξίως τὸ πρῶτον. καὶ γὰρ ἔζευξε ῥᾳδίως τὸν Εὐφράτην καὶ διήγαγε τὸν στρατὸν ἀσφαλῶς, καὶ πόλεις πολλὰς ἐν τῇ Μεσοποταμίᾳ κατέσχεν ἑκουσίως προσθεμένας. ἐν μιᾷ δ’, ἧς Ἀπολλώνιός ἐτυράννει, στρατιωτῶν ἑκατὸν ἀναιρεθέντων ἐπαγαγὼν τὴν δύναμιν αὐτοῖς καὶ κρατήσας διήρπασε τὰ χρήματα καὶ τοὺς ἀνθρώπους ἀπέδοτο· Ζηνοδοτίαν ἐκάλουν τὴν πόλιν οἱ Ἕλληνες. ἐπὶ ταύτης ἀλούσης δεξάμενος αὐτοκράτωρ ὑπὸ τῆς στρατιᾶς ἀναγορευθῆναι πολλὴν ὦφλεν αἰσχύνην, καὶ ταπεινὸς ἐφάνη καὶ περὶ τὰ μείζονα δύσελπις οὕτω πλεονέκτημα μικρὸν ἠγαπηκώς. ἐμβαλὼν δὲ φρουρὰς ταῖς προσκεχωρηκυίαις πόλεσιν, ὧν ἀριθμὸς ἧν ἑπτακισχίλιοι πεζοί χίλιοι δ’ ἱππεῖς, ἀνεχώρησεν αὐτός ἐν Συρίᾳ διαχειμάσων καὶ δεξόμενος αὐτόθι τὸν υἱόν ἥκοντα παρὰ Καίσαρος ἐκ Γαλατίας αὐτόν τε κεκοσμημένον ἀριστείοις καὶ χιλίους ἱππεῖς ἐπιλέκτους ἄγοντα.", "st": "Crass. 17.1"}, {"sp": "N", "t": "τοῦτο πρῶτον ἁμαρτεῖν ἔδοξεν ὁ Κράσσος μετά γε τὴν στρατείαν αὐτήν μέγιστον ἁμάρτημα τῶν γενομένων, ὅτι πρόσω χωρεῖν δέον ἔχεσθαί τε Βαβυλῶνος καὶ Σελευκείας, δυσμενῶν ἀεὶ Πάρθοις πόλεων, χρόνον ἐνέδωκε τοῖς πολεμίοις παρασκευῆς. ἔπειτα τὰς ἐν Συρίᾳ διατριβὰς ᾐτιῶντο χρηματιστικὰς μᾶλλον οὔσας ἢ στρατηγικάς· οὐ γὰρ ὅπλων ἀριθμὸν ἐξετάζων οὐδὲ γυμνασιῶν ποιούμενος ἁμίλλας, ἀλλὰ προσόδους πόλεων ἐκλογιζόμενος καὶ τὰ χρήματα τῆς ἐν Ἱεραπόλει θεοῦ σταθμοῖς καὶ τρυτάναις μεταχειριζόμενος ἐπὶ πολλὰς ἡμέρας, ἐπιγράφων δὲ καὶ δήμοις καὶ δυνάσταις στρατιωτῶν καταλόγους, εἶτ’ ἀνιεὶς ἀργύριον διδόντας, ἠδόξει καὶ κατεφρονεῖτο τούτοις. γίνεται δὲ πρῶτον αὐτῷ σημεῖον ἀπὸ τῆς θεοῦ ταύτης, ἣν οἱ μὲν Ἀφροδίτην, οἱ δὲ Ἥραν, οἱ δὲ τὴν ἀρχὰς καὶ σπέρματα πᾶσιν ἐξ ὑγρῶν παρασχοῦσαν αἰτίαν καὶ φύσιν νομίζουσι, καὶ τὴν πάντων εἰς ἀνθρώπους ἀρχὴν ἀγαθῶν καταδείξασαν. ἐξιόντων γὰρ ἐκ τοῦ ἱεροῦ πρῶτος ἐσφάλη κατὰ τὰς πύλας ὁ νεανίας Κράσσος, εἶτ’ ἐπ’ αὐτῷ περιπεσὼν ὁ πρεσβύτερος.", "st": "Crass. 17.5"}, {"sp": "N", "t": "ἤδη δὲ τὰς δυνάμεις ἐκ τῶν χειμαδίων συναθροίζοντος αὐτοῦ πρέσβεις ἀφίκοντο παρ’ Ἀρσάκου βραχύν τινα λόγον κομίζοντες, ἔφασαν γάρ, εἰ μὲν ὑπὸ Ῥωμαίων ὁ στρατὸς ἀπέσταλται, πόλεμον ἄσπονδον εἶναι καί ἀδιάλλακτον, εἰ δὲ τῆς πατρίδος ἀκούσης, ὡς πυνθάνονται, Κράσσος ἰδίων ἕνεκα κερδῶν ὅπλα Πάρθοις ἐπενήνοχε καί χώραν κατείληφε, μετριάζειν Ἀρσάκην καὶ τὸ μὲν Κράσσου γῆρας οἰκτείρειν, ἀφιέναι δὲ Ῥωμαίοις τοὺς ἄνδρας, οὓς ἔχει φρουρουμένους μᾶλλον ἢ φρουροῦντας· πρὸς ταῦτα Κράσσου κομπάσαντος ὡς ἐν Σελευκείᾳ δώσει τὰς ἀποκρίσεις, γελάσας ὁ πρεσβύτατος τῶν πρέσβεων Οὐαγίσης καί τῆς χειρὸς ὑπτίας δείξας τὸ μέσον ἐντεῦθεν, εἶπεν, ὦ Κράσσε, φύσονται τρίχες πρότερον ἢ σὺ ὄψει Σελεύκειαν.", "st": "Crass. 18.1"}, {"sp": "N", "t": "οὗτοι μὲν οὖν ἀπήλαυνον ὡς βασιλέα Ὑρώδην πολεμητέα φράσοντες, ἐκ δὲ τῶν πόλεων ἃς ἐφρούρουν Ῥωμαῖοι τῆς Μεσοποταμίας, παραβόλως τινὲς διεκπεσόντες ἄξια φροντίδων ἀνήγγελλον, αὐτόπται μὲν γεγονότες τοῦ τε πλήθους τῶν πολεμίων καί τῶν ἀγώνων ὧν ἠγωνίσαντο προσμαχόμενοι ταῖς πόλεσιν, οἷα δὲ φιλεῖ πάντα πρὸς τὸ δεινότερον ἐξαγγέλλοντες, ὡς ἄφυκτοι μὲν οἱ ἄνδρες διώκοντες, ἄληπτοι δὲ φεύγοντες, βέλη δὲ καινὰ προθέοντα τῆς ὄψεως καί πρὶν ὀφθῆναι τὸν βάλλοντα χωροῦντα διὰ τοῦ προστυχόντος, τῶν δὲ καταφράκτων ὅπλα τὰ μὲν διὰ παντὸς ὠθεῖσθαι, τὰ δὲ πρὸς μηδὲν ἐνδιδόναι πεποιημένα. ταῦτα τῶν στρατιωτῶν ἀκουόντων τὸ θράσος ὑπέπιπτεν. πεπεισμένοι γὰρ οὐδὲν Ἀρμενίων διαφέρειν Πάρθους οὐδὲ Καππαδοκῶν, οὓς ἄγων καί φέρων Λούκουλλος ἀπεῖπε, καί τοῦ πολέμου τὸ χαλεπώτατον ἡγούμενοι μακρὰν ὁδὸν ἔσεσθαι καὶ δίωξιν ἀνθρώπων εἰς χεῖρας οὐκ ἀφιξομένων, παρ’ ἐλπίδας ἀγῶνα καί κίνδυνον μέγαν προσεδόκων, ὥστε καί τῶν ἐν τέλει τινὰς οἴεσθαι δεῖν ἐπισχόντα τὸν Κράσσον αὖθις ὑπὲρ τῶν ὅλων γνώμην προθέσθαι. τούτων ἦν Κάσσιος ὁ ταμίας. ἡσυχῇ δὲ παρεδήλουν καί οἱ μάντεις ὡς ἀεὶ πονηρὰ σημεῖα καί δυσέκθυτα προφαίνοιτο τῷ Κράσσῳ διὰ τῶν ἱερῶν, ἀλλ’ οὔτε τούτοις προσεῖχεν οὔτε τοῖς ἕτερόν τι πλὴν ἐπείγεσθαι παραινοῦσιν.", "st": "Crass. 18.3"}, {"sp": "N", "t": "οὐχ ἥκιστα δ’ αὐτὸν Ἀρταβάζης ὁ Ἀρμενίων βασιλεὺς ἐπέρρωσεν· ἦλθε γὰρ εἰς τὸ στρατόπεδον μεθ’ ἑξακισχιλίων ἱππέων. καὶ οὗτοι μὲν ἐλέγοντο φύλακες καὶ προπομποὶ βασιλέως· ἑτέρους δὲ μυρίους ὑπισχνεῖτο καταφράκτους καὶ τρισμυρίους πεζοὺς οἰκοσίτους. ἔπειθε δὲ Κράσσον ἐμβαλεῖν δι’ Ἀρμενίας εἰς τὴν Παρθίαν· οὐ γὰρ μόνον ἐν ἀφθόνοις διάξειν τὴν στρατιὰν αὐτοῦ παρέχοντος, ἀλλὰ καὶ πορεύσεσθαι δι’ ἀσφαλείας, ὄρη πολλὰ καὶ λόφους συνεχεῖς καὶ χωρία δύσιππα πρὸς τὴν ἵππον, ἣ μόνη Πάρθων ἀλκή, προβαλλόμενον. ὁ δὲ τὴν προθυμίαν αὐτοῦ καὶ τὴν λαμπρότητα τῆς βοηθείας μετρίως ἠγάπησε, βαδιεῖσθαι δ’ ἔφη διὰ Μεσοποταμίας, ὅπου πολλοὺς καὶ ἀγαθοὺς Ῥωμαίων ἄνδρας ἀπέλιπεν. ὁ μὲν οὖν Ἀρμένιος ἐπὶ τούτοις ἀπήλαυνεν.", "st": "Crass. 19.1"}, {"sp": "N", "t": "τῷ δὲ Κράσσῳ διαβιβάζοντι τὴν στρατιὰν κατὰ τὸ Ζεῦγμα πολλαὶ μὲν ὑπερφυεῖς βρονταὶ περιερρήγνυντο, πολλὰ δὲ καὶ ἤστραπτεν ἐναντία τῷ στρατῷ, πνεῦμα δὲ νέφει καὶ πρηστῆρι μεμιγμένον ἐρεῖσαν αὐτοῦ κατὰ τῆς σχεδίας ἀνέρρηξε πολλὰ καὶ συνέτριψεν· ἐβλήθη δὲ καὶ κεραυνοῖς δυσὶν ὁ χῶρος οὗ στρατοπεδεύειν ἔμελλεν. ἵππος δὲ τῶν στρατηγικῶν ἐπιφανῶς κεκοσμημένος βίᾳ συνεπισπάσας τὸν ἡνίοχον εἰς τὸ ῥεῖθρον ὑποβρύχιος ἠφανίσθη. λέγεται δὲ καὶ τῶν ἀετῶν ὁ πρῶτος ἀρθεὶς ἀπὸ ταὐτομάτου μεταστραφῆναι. πρὸς δὲ τούτοις συνέπεσε μετὰ τὴν διάβασιν μετρουμένοις τὰ ἐπιτήδεια τοῖς στρατιώταις πρῶτα πάντων δοθῆναι φακοὺς καὶ ἅλας, ἃ νομίζουσι Ῥωμαῖοι πένθιμα καὶ προτίθενται τοῖς νέκυσιν, αὐτοῦ τε Κράσσου δημηγοροῦντος ἐξέπεσε φωνή δεινῶς συγχέασα τὸν στρατόν. ἔφη γὰρ τὸ ζεῦγμα τοῦ ποταμοῦ διαλύειν ὅπως μηδεὶς αὐτῶν ἐπανέλθῃ. καὶ δέον, ὡς ᾔσθετο τοῦ ῥήματος τὴν ἀτοπίαν, ἀναλαβεῖν καὶ διασαφῆσαι πρὸς τοὺς ἀποδειλιῶντας τὸ εἰρημένον, ἠμέλησεν ὑπὸ αὐθαδείας. τέλος δὲ τὸν εἰθισμένον καθαρμὸν ἐσφαγιάζετο, καὶ τὰ σπλάγχνα τοῦ μάντεως αὐτῷ προσδόντος ἐξέβαλε τῶν χειρῶν ἐφ’ ᾧ καὶ μάλιστα δυσχεραίνοντας ἰδὼν τοὺς παρόντας ἐμειδίασε καὶ τοιοῦτον, ἔφη, τὸ γῆρας· ἀλλὰ τῶν γε ὅπλων οὐδὲν ἂν ἐκφύγοι τὰς χεῖρας.", "st": "Crass. 19.4"}, {"sp": "N", "t": "ἐκ τούτου παρὰ τὸν ποταμόν ἐξήλαυνεν ἑπτὰ μὲν ἔχων ὁπλιτῶν τάγματα καὶ τετρακισχιλίων ὀλίγον ἀποδέοντας ἱππεῖς, ψιλοὺς δὲ τοῖς ἱππεῦσι παραπλησίους, τῶν δὲ προδρόμων τινὲς ἀπὸ σκοπιᾶς ἐπανελθόντες ἤγγελλον ἀνθρώπων μὲν ἔρημον εἶναι τὴν χώραν, ἵππων δ’ ἐντετυχηκέναι πολλῶν ἴχνεσιν οἷον ἐκ μεταβολῆς ὀπίσω διωκομένων, ὅθεν αὐτός τε Κράσσος ἔτι μᾶλλον εὔελπις ἦν, καὶ τοῖς στρατιώταις παντάπασι τῶν Πάρθων παρέστη καταφρονεῖν, ὡς οὐκ ἀφιξομένων εἰς χεῖρας. ὅμως δ’ οἱ περὶ Κάσσιον αὖθις διελέγοντο τῷ Κράσσῳ, καὶ παρῄνουν μάλιστα μὲν ἐν πόλει τινὶ τῶν φρουρουμένων ἀναλαβεῖν τὴν δύναμιν, ἄχρι οὗ τι πύθηται περὶ τῶν πολεμίων βέβαιον, εἰ δὲ μή, χωρεῖν ἐπὶ Σελευκείας παρὰ τὸν ποταμόν εὐπορίαν γὰρ τὰ σιτηγὰ τῆς ἀγορᾶς παρέξειν ἅμα συγκαταίροντα πρὸς τὸ στρατόπεδον, καὶ φύλακα τοῦ μὴ κυκλωθῆναι τὸν ποταμόν ἔχοντας ἀπ’ ἴσης ἀεὶ πρὸς ἐναντίους μαχεῖσθαι τοὺς πολεμίους.", "st": "Crass. 20.1"}, {"sp": "N", "t": "ταῦτα τοῦ Κράσσου διασκοποῦντος ἔτι καὶ βουλευομένου παραγίνεται φύλαρχος Ἀράβων, Ἀριάμνης ὄνομα, δολερὸς καὶ παλίμβολος ἀνὴρ καὶ πάντων ὅσα συνήνεγκεν εἰς ὄλεθρον ἡ τύχη κακὰ, μέγιστον αὐτοῖς καὶ τελειότατον γενόμενος· τοῦτον δ’ ᾔδεσαν ἔνιοι τῶν Πομπηΐῳ συνεστρατευμένων ἀπολαύσαντά τι τῆς ἐκείνου φιλανθρωπίας καὶ δόξαντα φιλορρώμαιον εἶναι· τότε δ’ ὑφεῖτο τῷ Κράσσῳ μετὰ γνώμης τῶν βασιλέως στρατηγῶν, εἰ δύναιτο παρατρέψας αὐτὸν ἀπωτάτω τοῦ ποταμοῦ καὶ τῶν ὑπωρειῶν εἰς πεδίον ἐκβαλεῖν ἀχανὲς καὶ περιελαυνόμενον. πάντα γὰρ διενοοῦντο μᾶλλον ἢ κατὰ στόμα προσφέρεσθαι Ῥωμαίοις. ἐλθὼν οὖν πρὸς τὸν Κράσσον ὁ βάρβαρος ἦν δὲ καὶ πιθανὸς εἰπεῖν Πομπήϊον μὲν ὡς εὐεργέτην ἐπῄνει, Κράσσον δὲ, τῆς δυνάμεως μακαρίσας ἐμέμφετο τῆς διατριβῆς μέλλοντα καὶ παρασκευαζόμενον, ὥσπερ ὅπλων αὐτῷ δεῆσον, οὐ χειρῶν οὐδὲ ποδῶν τῶν ταχίστων ἐπ’ ἀνθρώπους οἳ πάλαι ζητοῦσιν ἁρπάσαντες τὰ τιμιώτατα τῶν χρημάτων καὶ σωμάτων εἰς Σκύθας ἢ Ὑρκανοὺς ἀναπτέσθαι. καίτοι μάχεσθαι μέλλοντας, ἔφη, σπεύδειν ἔδει, πρὶν ἅπασαν ἐν ταὐτῷ γενέσθαι τὴν δύναμιν ἀναθαρσήσαντος βασιλέως· ἐπεὶ νῦν γε Σουρήνας ὑμῖν προβέβληται καὶ Σιλλάκης ἐφ’ αὑτοὺς ἀναδεξάμενοι τὴν δίωξιν, ὁ δ’ οὐδαμῇ φανερός ἐστιν.", "st": "Crass. 21.1"}, {"sp": "N", "t": "ταῦτα δὲ ἦν ψευδῆ πάντα, διχῇ γὰρ εὐθὺς Ὑρώδης διελὼν τὴν δύναμιν αὐτὸς μὲν Ἀρμενίαν ἐπόρθει τιννύμενος Ἀρταουάσδην, Σουρήναν δ’ ἀφῆκεν ἐπὶ Ῥωμαίους, οὐχ ὑπερφροσύνῃ χρώμενος, ὡς ἔνιοί φασιν· οὐ γὰρ ἦν τοῦ αὐτοῦ Κράσσον μὲν ἀπαξιοῦν ἀνταγωνιστήν, ἄνδρα Ῥωμαίων πρῶτον, Ἀρταουάσδῃ δὲ προσπολεμεῖν καὶ ταῖς Ἀρμενίων ἐπιόντα κώμαις ἐξαιρεῖν ἀλλὰ καὶ πάνυ δοκεῖ καταδείσας τὸν κίνδυνον αὐτὸς μὲν ἐφεδρεύειν καὶ καραδοκεῖν τὸ μέλλον, Σουρήναν δὲ προκαθεῖναι πειρασόμενον μάχης καὶ περιέλξοντα τοὺς πολεμίους. οὐδὲ γὰρ ἦν τῶν τυχόντων ὁ Σουρήνας, ἀλλὰ πλούτῳ μὲν καὶ γένει καὶ δόξῃ μετὰ βασιλέα δεύτερος, ἀνδρείᾳ δὲ καὶ δεινότητι τῶν καθ’ αὑτὸν ἐν Πάρθοις πρῶτος ἔτι δὲ μεγέθει καὶ κάλλει σώματος ὡς οὐδεὶς ἕτερος, ἐξήλαυνε δὲ καθ’ ἑαυτὸν ἀεὶ χιλίαις σκευοφορούμενος καμήλοις, καὶ διακοσίας ἀπήνας ἐπήγετο παλλακίδων, ἱππεῖς δὲ κατάφρακτοι χίλιοι, πλείονες δὲ τῶν κούφων παρέπεμπον, εἶχε δὲ τοὺς σύμπαντας ἱππεῖς ὁμοῦ πελάτας τε καὶ δούλους μυρίων οὐκ ἀποδέοντας. κατὰ γένος μὲν οὖν ἐξ ἀρχῆς ἐκέκτητο βασιλεῖ γενομένῳ Πάρθων ἐπιτιθέναι τὸ διάδημα πρῶτος, Ὑρώδην δὲ τοῦτον αὐτὸν ἐξεληλαμένον εἰς Πάρθους κατήγαγε, καὶ Σελεύκειαν αὐτῷ τὴν μεγάλην εἷλε πρῶτος ἐπιβὰς τοῦ τείχους καὶ τρεψάμενος ἰδίᾳ χειρὶ τοὺς ἀντιστάντας. οὔπω δὲ γεγονὼς ἔτη τριάκοντα κατ’ ἐκεῖνον τὸν χρόνον εὐβουλίας καὶ συνέσεως δόξαν εἶχε μεγίστην, οἷς οὐχ ἥκιστα καὶ τὸν Κράσσον ἔσφηλε, διὰ θάρσος καὶ φρόνημα πρῶτον, εἶτα ὑπὸ δέους καὶ συμφορῶν ταῖς ἀπάταις εὐχείρωτον γενόμενον.", "st": "Crass. 21.5"}, {"sp": "N", "t": "τότ’ οὖν ὁ βάρβαρος, ὡς ἔπεισεν αὐτόν, ἀποσπάσας τοῦ ποταμοῦ διὰ μέσων ἦγε τῶν πεδίων ὁδὸν ἐπιεικῆ καὶ κούφην τὸ πρῶτον, εἶτα μοχθηράν, ἄμμου βαθείας ὑποδεχομένης καὶ πεδίων ἀδένδρων καὶ ἀνύδρων καὶ πρὸς οὐδὲν οὐδαμῇ πέρας ἐφικτὸν αἰσθήσει παυομένων, ὥστε μὴ μόνον δίψει καὶ χαλεπότητι τῆς πορείας ἀπαγορεύειν, ἀλλὰ καὶ τὸ τῆς ὄψεως ἀπαραμύθητον ἀθυμίαν παρέχειν οὐ φυτὸν ὁρῶσιν, οὐ ῥεῖθρον, οὐ προβολὴν ὄρους καθιέντος, οὐ πόαν διαβλαστάνουσαν, ἀλλ’ ἀτεχνῶς πελάγιόν τι χεῦμα θινῶν τινων ἐρήμων περιεχόντων τὸν στρατόν. ἦν μὲν οὖν καὶ ἀπὸ τούτων ὁ δόλος ὕποπτος· ἐπεὶ δὲ καὶ παρὰ Ἀρταουάσδου τοῦ Ἀρμενίου παρῆσαν ἄγγελοι φράζοντες ὡς πολλῷ συνέχοιτο πολέμῳ ῥυέντος ἐπ’ αὐτὸν Ὑρώδου, καὶ πέμπειν μὲν ἐκείνῳ βοήθειαν οὐ δύναται, παραινεῖ δὲ Κράσσῳ μάλιστα μὲν ἐκεῖ τραπέσθαι καὶ γενόμενον μετ’ Ἀρμενίων ὁμοῦ διαγωνίσασθαι πρὸς τὸν Ὑρώδην, εἰ δὲ μή, πορεύεσθαι καὶ στρατοπεδεύειν ἀεὶ τὰ ἱππάσιμα φεύγοντα καὶ προσχωροῦντα τοῖς ὀρεινοῖς, Κράσσος μὲν οὐδὲν ἀντιγράψας ὑπ’ ὀργῆς καὶ σκαιότητος ἀπεκρίνατο νῦν μὲν Ἀρμενίοις μὴ σχολάζειν, αὖθις δ’ ἀφίξεσθαι δίκην ἐπιθήσων Ἀρταουάσδῃ τῆς προδοσίας.", "st": "Crass. 22.1"}, {"sp": "N", "t": "οἱ δὲ περὶ Κάσσιον αὖθις ἠγανάκτουν, καὶ Κράσσον μὲν ἀχθόμενον αὐτοῖς ἐπαύσαντο νουθετοῦντες, ἰδίᾳ δὲ τὸν βάρβαρον ἐλοιδόρουν· τίς σε δαίμων πονηρός, ὦ κάκιστε ἀνθρώπων, ἤγαγε πρὸς ἡμᾶς; τίσι δὲ φαρμάκοις καὶ γοητείαις ἔπεισας Κράσσον εἰς ἐρημίαν ἀχανῆ καὶ βύθιον ἐκχέαντα τὴν στρατιὰν ὁδὸν ὁδεύειν Νομάδι λῃστάρχῃ μᾶλλον ἢ Ῥωμαίων αὐτοκράτορι προσήκουσας; ὁ δὲ βάρβαρος ἀνὴρ ὢν ποικίλος ἐκείνους μὲν ὑποπίπτων ἐθάρρυνε καὶ παρεκάλει μικρὸν ἔτι καρτερῆσαι, τοὺς δὲ στρατιώτας ἅμα συμπαραθέων καὶ παραβοηθῶν ἐπέσκωπτε μετὰ γέλωτος· ὑμεῖς δὲ διὰ Καμπανίας ὁδεύειν οἴεσθε κρήνας καὶ νάματα καὶ σκιὰς καὶ λουτρὰ δηλαδὴ καὶ πανδοκεῖα ποθοῦντες; οὐ μέμνησθε δὲ τὴν Ἀράβων διεξιόντες καὶ Ἀσσυρίων μεθορίαν; οὕτω μὲν ὁ βάρβαρος διεπαιδαγώγησε τοὺς Ῥωμαίους, καὶ πρὶν ἢ γενέσθαι φανερὸς ἐξαπατῶν ἀφίππευσεν, οὐ λαθὼν τὸν Κράσσον, ἀλλὰ καὶ τοῦτο πείσας, ὡς ὑπεργάσεται καὶ διαταράξει τὰ τῶν πολεμίων.", "st": "Crass. 22.4"}, {"sp": "N", "t": "λέγεται δὲ τῆς ἡμέρας ἐκείνης τὸν Κράσσον οὐχ ὥσπερ ἔθος ἐστὶ Ῥωμαίων στρατηγοῖς ἐν φοινικίδι προελθεῖν, ἀλλ’ ἐν ἱματίῳ μέλανι, καὶ τοῦτο μὲν εὐθὺς ἀλλάξαι προνήσαντα, τῶν δὲ σημαιῶν ἐνίας μόλις ὥσπερ πεπηγυίας πολλὰ παθόντας ἀνελέσθαι τοὺς φέροντας. ὧν ὁ Κράσσος καταγελῶν ἐπετάχυνε τὴν πορείαν, προσβιαζόμενος ἀκολουθεῖν τὴν φάλαγγα τοῖς ἱππεῦσι, πρίν γε δὴ τῶν ἐπὶ κατασκοπὴν ἀποσταλέντων ὀλίγοι προσπελάσαντες ἀπήγγειλαν ἀπολωλέναι τοὺς ἄλλους ὑπὸ τῶν πολεμίων, αὐτοὺς δὲ μόλις ἐκφυγεῖν, ἐπιέναι δὲ μαχουμένους πλήθει πολλῷ καὶ θάρσει τοὺς ἄνδρας. ἅπαντες μὲν οὖν ἐθορυβήθησαν, ὁ δὲ Κράσσος ἐξεπλάγη παντάπασι καὶ διὰ σπουδῆς οὐ πάνυ καθεστηκὼς παρέταττε, πρῶτον μέν, ὡς οἱ περὶ Κάσσιον ἠξίουν, ἀραιὰν τὴν φάλαγγα τῶν ὁπλιτῶν ἐπὶ πλεῖστον ἀνάγων τοῦ πεδίου πρὸς τὰς κυκλώσεις, τοὺς δ’ ἱππεῖς διανέμων τοῖς κέρασιν ἔπειτα μετέδοξε, καὶ συναγαγὼν ἀμφίστομον ἐποίησε καὶ βαθὺ πλινθίον ἐν δώδεκα σπείραις προερχομένης τῶν πλευρῶν ἑκάστης. παρὰ δὲ σπεῖραν ἴλην ἱππέων ἔταξεν, ὡς μηδὲν ἔχοι μέρος ἐνδεὲς ἱππικῆς βοηθείας, ἀλλὰ πανταχόθεν ὁμαλῶς προσφέροιτο πεφραγμένος. τῶν δὲ κεράτων τὸ μὲν Κασσίῳ, τὸ δὲ τῷ νέῳ Κράσσῳ παρέδωκεν, αὐτὸς δ’ εἰς μέσον κατέστη.", "st": "Crass. 23.1"}, {"sp": "N", "t": "καὶ προάγοντες οὕτως ἐπὶ ῥεῖθρον ἦλθον ὃ καλεῖται Βάλισσος, οὐ πολὺ μὲν ἄλλως οὐδὲ ἄφθονον, ἀσμένοις δὲ τότε τοῖς στρατιώταις φανὲν ἐν αὐχμῷ καὶ καύματι καὶ παρὰ τὴν ἄλλην ἐπίπονον καὶ ἄνυδρον πορείαν. οἱ μὲν οὖν πλεῖστοι τῶν ἡγεμόνων ᾤοντο δεῖν ἐνταῦθα καταυλισαμένους καὶ νυκτερεύσαντας καὶ πυθομένους, ἐφ’ ὅσον οἷόν τε, πλῆθος καὶ τάξιν τῶν πολεμίων, ἅμ’ ἡμέρᾳ χωρεῖν ἐπ’ αὐτούς· Κράσσος δὲ τῷ παιδὶ καὶ τοῖς περὶ αὐτὸν ἱππεῦσιν ἐγκελευομένοις ἄγειν καὶ συνάπτειν ἐπαρθείς ἐκέλευσεν ἑστῶτας ἐν τάξει φαγεῖν καὶ πιεῖν τοὺς δεομένους. καὶ πρὶν ἢ τοῦτο διὰ πάντων γενέσθαι καλῶς, ἦγεν οὐ σχέδην οὐδ’ ὡς ἐπὶ μάχην διαναπαύων, ἀλλ’ ὀξείᾳ καὶ συντόνῳ χρώμενος τῇ πορείᾳ μέχρι οὗ κατώφθησαν οἱ πολέμιοι, παρὰ δόξαν οὔτε πολλοὶ φανέντες οὔτε σοβαροὶ τοῖς Ῥωμαίοις. τὸ μὲν γὰρ πλῆθος ὑπέστειλε τοῖς προτάκτοις Σουρήνας, τὴν δὲ λαμπρότητα κατέκρυβε τῶν ὅπλων ἱμάτια καὶ διφθέρας προίσχεσθαι κελεύσας. ὡς δ’ ἐγγὺς ἐγένοντο καὶ σημεῖον ἤρθη παρὰ τοῦ στρατηγοῦ, πρῶτον μὲν ἐπίμπλαντο φθογγῆς βαρείας καὶ βρόμου φρικώδους τὸ πεδίον. Πάρθοι γὰρ οὐ κέρασιν οὐδὲ σάλπιγξιν ἐποτρύνουσιν ἑαυτοὺς εἰς μάχην, ἀλλὰ ῥόπτρα βυρσοπαγῆ καὶ κοῖλα περιτείναντες ἠχείοις χαλκοῖς ἅμα πολλαχόθεν ἐπιδουποῦσι, τὰ δὲ φθέγγεται βύθιόν τι καὶ δεινόν, ὠρυγῇ θηριώδει καὶ τραχύτητι βροντῆς μεμιγμένον, εὖ πως συνεωρακότες ὅτι τῶν αἰσθητηρίων ἀκοὴ ταρακτικώτατόν ἐστὶ τῆς ψυχῆς καὶ τὰ περὶ ταύτην πάθη τάχιστα κινεῖ καὶ μάλιστα ἐξίστησι τὴν διάνοιαν.", "st": "Crass. 23.5"}, {"sp": "N", "t": "ἐκπεπληγμένων δὲ τῶν Ῥωμαίων διὰ τὸν ἦχον, ἐξαίφνης τὰ προκαλύμματα τῶν ὅπλων καταβαλόντες ὤφθησαν αὐτοί τε φλογοειδεῖς κράνεσι καὶ θώραξι, τοῦ Μαργιανοῦ σιδήρου στίλβοντος ὀξὺ καὶ περιλαμπές, οἵ θ’ ἵπποι καταπεφραγμένοι χαλκοῖς καὶ σιδηροῖς σκεπάσμασιν, ὁ δὲ Σουρήνας μέγιστος καὶ κάλλιστος αὐτός, τῇ δὲ κατ’ ἀνδρείαν δόξῃ τὴν θηλύτητα τοῦ κάλλους οὐκ ἐοικώς, ἀλλὰ Μηδικώτερον ἐσκευασμένος ἐντρίμμασι προσώπου καὶ κόμης διακρίσει, τῶν ἄλλων Πάρθων ἔτι Σκυθικῶς ἐπὶ τὸ φοβερὸν τῷ ἀνασίλλῳ κομώντων. καὶ πρῶτον μὲν διενοοῦντο τοῖς κοντοῖς εἰσελαύνοντες ὠθεῖν καὶ βιάζεσθαι τοὺς προτάκτους· ὡς δ’ ἑώρων τό τε βάθος τοῦ συνασπισμοῦ καὶ τῶν ἀνδρῶν τὸ μόνιμον καὶ παρεστηκός, ἀνῆγον ὀπίσω καὶ σκίδνασθαι δοκοῦντες ἅμα καὶ διαλύειν τὴν τάξιν ἐλάνθανον ἐν κύκλῳ περιβάλλοντες τὸ πλινθίον αὐτῶν. Κράσσου δὲ τοὺς ψιλοὺς ἐκδραμεῖν κελεύσαντος, οὗτοι μὲν οὐ πολὺ προῆλθον, ἀλλὰ πολλοῖς τοξεύμασιν ἐντυχόντες ταχὺ καὶ συμπαρέντες αὖθις ἐνεδύοντο τοῖς ὁπλίταις, καὶ παρεῖχον ἀκοσμίας ἀρχὴν καὶ δέους, ὁρῶσι τὸν τόνον τῶν ὀιστῶν καὶ τὴν ῥώμην ὅπλα τε ῥηγνύντων καὶ διὰ παντὸς φερομένων ὁμοίως ἀντιτύπου καὶ μαλακοῦ στεγάσματος.", "st": "Crass. 24.1"}, {"sp": "N", "t": "οἱ δὲ Πάρθοι διαστάντες ἐκ μήκους ἤρξαντο τοξεύειν ἅμα πανταχόθεν, οὐ τὴν ἀκριβῆ τοξείαν ἡ γὰρ συνέχεια καὶ πυκνότης τῶν Ῥωμαίων οὐδὲ τῷ βουλομένῳ διαμαρτάνειν ἀνδρὸς παρεῖχεν, εὐτόνους δὲ τὰς πληγὰς καὶ βιαίους διδόντες ἀπὸ τόξων κραταιῶν καὶ μεγάλων καὶ τῇ σκολιότητι τῆς καμπῆς ἠναγκασμένον τὸ βέλος ἀποστελλόντων. ἦν οὖν αὐτόθεν ἤδη μοχθηρὰ τὰ Ῥωμαίων· καὶ γὰρ μένοντες ἐν τάξει συνετιτρώσκοντο, καὶ χωρεῖν ὁμόσε πειρώμενοι τοῦ μὲν ποιεῖν ἴσον ἀπεῖχον, ὁμοίως δ’ ἔπασχον. ὑπέφευγον γὰρ ἅμα βάλλοντες οἱ Πάρθοι, καὶ τοῦτο κράτιστα ποιοῦσι μετὰ Σκύθας· καὶ σοφώτατόν ἐστιν ἀμυνομένους ἔτι σῴζεσθαι καὶ τῆς φυγῆς ἀφαιρεῖν τὸ αἰσχρόν.", "st": "Crass. 24.5"}, {"sp": "N", "t": "ἄχρι μὲν οὖν ἤλπιζον αὐτοὺς ἐκχεαμένους τὰ βέλη σχήσεσθαι μάχης ἢ συνάψειν εἰς χεῖράς, ἐκαρτέρουν· ὡς δ’ ἔγνωσαν ὅτι πολλαὶ κάμηλοι παρεστᾶσι τοξευμάτων πλήρεις, ἀφ’ ὧν περιελαύνοντες οἱ πρῶτοι λαμβάνουσιν, οὐδὲν πέρας ὁρῶν ὁ Κράσσος ἠθύμει, καὶ σκοπεῖν ἐκέλευεν, ἀγγέλους πέμψας πρὸς τὸν υἱόν, ὅπως προσμῖξαι βιάσεται τοῖς ἐναντίοις πρὶν ἢ κυκλωθῆναι. μάλιστα γὰρ ἐκείνῳ προσέπιπτον καὶ περιίππευον τὸ κέρας ὡς κατὰ νώτου γενησόμενοι. λαβὼν οὖν ὁ νεανίας ἱππεῖς τε χιλίους τριακοσίους, ὧν οἱ χίλιοι παρὰ Καίσαρος ἦσαν, καὶ τοξότας πεντακοσίους καὶ τῶν ἔγγιστα θυρεοφόρων ὀκτὼ σπείρας συνήγαγεν εἰς ἐμβολήν. τῶν δὲ Πάρθων οἱ περιελαύνοντες, εἴτε τέλμασιν ἐντυχόντες, ὡς ἔνιοί φασιν, εἴτε λαβεῖν τὸν Κράσσον ἀπωτάτω τοῦ πατρὸς στρατηγοῦντες, ὀπίσω στρέψαντες ἐδίωκον. ὁ δὲ βοήσας ὡς οὐ μένουσιν οἱ ἄνδρες, ἤλαυνε, καὶ σὺν αὐτῷ Κηνσωρῖνός τε καὶ Μεγάβακχος, ὁ μὲν εὐψυχίᾳ καὶ ῥώμῃ διαφέρων, Κηνσωρῖνος δὲ βουλευτικὸν ἔχων ἀξίωμα καὶ δεινὸς εἰπεῖν, ἑταῖροι δὲ Κράσσου καὶ παραπλήσιοι καθ’ ἡλικίαν. ἐπισπομένων δὲ τῶν ἱππέων οὐδὲ τὸ πεζὸν ἀπελείπετο προθυμίᾳ καὶ χαρᾷ τῆς ἐλπίδος· νικᾶν γὰρ ᾤοντο καὶ διώκειν, ἄχρι οὗ πολὺ προελθόντες ᾔσθοντο τὴν ἀπάτην, μεταβαλλομένων ἅμα τῶν φεύγειν δοκούντων καὶ πλειόνων ἄλλων ἐπιφερομένων. ἐνταῦθα ἔστησαν, οἰόμενοι συνάψειν αὐτοῖς εἰς χεῖράς ὀλίγοις οὖσι τοὺς πολεμίους, οἱ δὲ τοὺς καταφράκτους προτάξαντες ἐναντίους τοῖς Ῥωμαίοις, τὴν δ’ ἄλλην ἵππον ἄτακτον περὶ αὐτοὺς ἐλαύνοντες, καὶ συνταράττοντες τὸ πεδίον, ἀνίστασαν ἐκ βυθοῦ θῖνας ἄμμου κονιορτὸν ἐπαγούσας ἄπλετον, ὡς μήτε διορᾶν ῥᾳδίως μήτε φθέγγεσθαι τοὺς Ῥωμαίους, εἱλουμένους δὲ ἐν ὀλίγῳ καὶ συμπίπτοντας ἀλλήλοις βάλλεσθαι καὶ ἀποθνῄσκειν οὐ ῥᾴδιον οὐδ’ ὀξὺν θάνατον, ἀλλ’ ὑπὸ σπασμοῦ καὶ ὀδύνης δυσανασχετοῦντας καὶ κυλινδουμένους περὶ τοῖς ὀιστοῖς ἐναποθραύειν τοῖς τραύμασι, βίᾳ τε πειρωμένους ἐξέλκειν ἠγκιστρωμένας ἀκίδας καὶ δεδυκυίας διὰ φλεβῶν καὶ νεύρων προσαναρρηγνύναι καὶ λυμαίνεσθαι σφᾶς αὐτούς.", "st": "Crass. 25.1"}, {"sp": "N", "t": "οὕτω δὲ πολλῶν ἀποθνῃσκόντων ἄπρακτοι καὶ οἱ ζῶντες ἦσαν πρὸς ἀλκήν· καὶ τοῦ Ποπλίου παρακαλοῦντος ἐμβαλεῖν εἰς τὴν κατάφρακτον, ἐπεδείκνυσαν ἑαυτῶν χεῖράς τε θυρεοῖς πεπερονημένας καὶ πόδας διαμπὰξ προσεληλαμένους πρὸς τοὔδαφος, ὥστε καὶ πρὸς φυγὴν ἀμηχάνους εἶναι καὶ πρὸς ἄμυναν. αὐτὸς οὖν τοὺς ἱππεῖς παρορμήσας προσέβαλε μὲν ἐρρωμένως καὶ συνῆψε τοῖς ἀνδράσιν, ἦν δὲ ἄνισος ἔν τε ταῖς πληγαῖς καὶ τῷ φυλάττεσθαι, παίων μὲν ἀσθενέσι καὶ μικροῖς δορατίοις θώρακας ὠμοβύρσους καὶ σιδηροῦς, παιόμενος δὲ κοντοῖς εἰς εὐσταλῆ καὶ γυμνὰ σώματα τῶν Γαλατῶν τούτοις γὰρ ἐθάρρει μάλιστα, καὶ μετὰ τούτων ἔργα θαυμαστὰ διεπράττετο. τῶν τε γὰρ κοντῶν ἐπελαμβάνοντο, καὶ συμπλεκόμενοι τοὺς ἄνδρας ἀπὸ τῶν ἵππων ἐώθουν τῇ βαρύτητι τοῦ ὁπλισμοῦ δυσκινήτους ὄντας, πολλοὶ δὲ τοὺς ἑαυτῶν ἀπολείποντες ἵππους καὶ ὑποδυόμενοι τοῖς ἐκείνων ἔτυπτον εἰς τὰς γαστέρας· οἱ δ’ ἀνεσκίρτων ὑπ’ ὀδύνης, καὶ συμπατοῦντες ἐν ταὐτῷ τοὺς ἐπιβάτας καὶ τοὺς πολεμίους ἀναπεφυρμένους ἀπέθνῃσκον. ἐπίεζε δὲ τοὺς Γαλάτας μάλιστα τό τε θάλπος καὶ τὸ δίψος, ἀμφοτέρων ἀήθεις ὄντας· καὶ τῶν ἵππων ἀπολώλεισαν οἱ πλεῖστοι πρὸς ἐναντίους ἐλαυνόμενοι τοὺς κοντούς, ἐβιάσθησαν οὖν ἀναχωρῆσαι πρὸς τοὺς ὁπλίτας, ἔχοντες τὸν Πόπλιον ὑπὸ τραυμάτων ἤδη κακῶς διακείμενον. ἰδόντες δὲ θῖνα βουνώδη πλησίον ἐχώρουν ἐπ’ αὐτήν, καὶ τοὺς μὲν ἵππους ἐν μέσῳ κατέδησαν, ἔξωθεν δὲ τοῖς θυρεοῖς συγκλείσαντες ᾤοντο ῥᾷον ἀμυνεῖσθαι τοὺς βαρβάρους. ἀπέβαινε δὲ τοὐναντίον, ἐν μὲν γὰρ τῷ ὁμαλῷ τοῖς ὄπισθεν ἁμῶς γέ πως παρέχουσιν οἱ πρότακτοι ῥᾳστώνην, ἐκεῖ δ’ ἄλλον ὑπὲρ ἄλλον διὰ τὴν ἀνωμαλίαν ἀνέχοντος τοῦ χωρίου καὶ μᾶλλον ἀεὶ τὸν κατόπιν ἐξαίροντος, οὐδὲν ἦν τὸ διαφεῦγον, ἀλλ’ ἐβάλλοντο πάντες ὁμαλῶς, ὀδυρόμενοι τὴν ἀκλεῆ καὶ ἄπρακτον αὑτῶν τελευτήν.", "st": "Crass. 25.6"}, {"sp": "N", "t": "ἦσαν δὲ περὶ τὸν Πόπλιον ἄνδρες Ἕλληνες δύο τῶν αὐτόθι κατοικούντων ἐν Κάρραις, Ἱερώνυμος καὶ Νικόμαχος, οἱ συνέπειθον αὐτὸν ὑπεξελθεῖν μετ’ αὑτῶν καὶ διαφεύγειν εἰς Ἴχνας, πόλιν ᾑρημένην τὰ Ῥωμαίων καὶ οὐ μακρὰν οὖσαν. ὁ δὲ φήσας οὐδένα δεινὸν οὕτως ἔσεσθαι θάνατον ὃν φοβηθεὶς Πόπλιος ἀπολείψει τοὺς ἀπολλυμένους δι’ αὑτόν, ἐκείνους μὲν ἐκέλευσε σῴζεσθαι καὶ δεξιωσάμενος ἀπέλυσεν, αὐτὸς δὲ τῇ χειρὶ χρήσασθαι μὴ δυνάμενος διελήλατο γὰρ βέλει, τὸν ὑπασπιστὴν ἐκέλευσε πατάξαι τῷ ξίφει, παρασχὼν τὸ πλευρόν. ὁμοίως δὲ καὶ Κηνσωρῖνον ἀποθανεῖν λέγουσιν· Μεγάβακχος δ’ αὐτὸς αὑτὸν διεχρήσατο, καὶ τῶν ἄλλων οἱ δοκιμώτατοι. τοὺς δ’ ὑπολελειμμένους ἀναβαίνοντες οἱ Πάρθοι τοῖς κοντοῖς διήλαυνον μαχομένους· ζῶντας δ’ οὐ πλείονας ἁλῶναι φασι πεντακοσίων, τὰς δὲ κεφαλὰς τῶν περὶ τὸν Πόπλιον ἀποκόψαντες ἤλαυνον εὐθὺς ἐπὶ τὸν Κράσσον.", "st": "Crass. 25.11"}, {"sp": "N", "t": "εἶχε δὲ τὰ κατ’ αὐτὸν οὕτως, ὡς ἐκέλευσε τόν υἱὸν ἐμβαλεῖν τοῖς Πάρθοις καί τις ἤγγειλεν αὐτῷ μακρὰν τροπὴν εἶναι καί δίωξιν ἰσχυρὰν τῶν πολεμίων, ἑώρα δὲ καί τοὺς καθ’ αὑτὸν οὐκέτι προσκειμένους ὁμοίως ἐκεῖ γὰρ ἐρρύησαν οἱ πλεῖστοι, μικρὸν ἀνεθάρρησε, καί συναγαγὼν ὑπέστειλεν ἐν χωρίοις προσάντεσι τόν στρατόν, αὐτίκα προσδοκῶν τόν υἱὸν ἐπανήξειν ἀπὸ τῆς διώξεως. τῶν δὲ πεμφθέντων ὑπὸ τοῦ Ποπλίου πρὸς αὐτόν, ὡς ἐκινδύνευεν, οἱ μὲν πρῶτοι διεφθάρησαν ἐμπεσόντες εἰς τοὺς βαρβάρους, οἱ δ’ ὕστεροι μόγις διαφυγόντες ἀπήγγελλον οἴχεσθαι τόν Πόπλιον, εἰ μὴ ταχεῖα καί πολλὴ βοήθεια παρ’ ἐκείνου γένοιτο. τόν δὲ Κράσσον ἅμα πολλὰ πάθη κατέσχε· καί λογισμῷ μὲν οὐδὲν ἔτι τῶν πραγμάτων ἑώρα, φόβῳ δὲ περὶ τοῦ σύμπαντος ἅμα καί πόθῳ τοῦ παιδὸς ἑλκόμενος βοηθεῖν καί μὴ βοηθεῖν, τέλος ὥρμησε προάγειν τὴν δύναμιν.", "st": "Crass. 26.1"}, {"sp": "N", "t": "ἐν τούτῳ δ’ οἱ πολέμιοι προσεφέροντο κλαγγῇ καί παιᾶνι φοβερώτεροι, καί πολλὰ τῶν τυμπάνων αὖθις περιεμυκᾶτο τοὺς Ῥωμαίους ἑτέρας μάχης ἀρχὴν προσδοκῶντας. οἱ δὲ τὴν κεφαλὴν τοῦ Ποπλίου κομίζοντες ὑπὲρ αἰχμῆς ἀναπεπηγυῖαν ἐγγὺς προσελάσαντες ἀνέδειξαν, ὕβρει πυνθανόμενοι τοκέας αὐτοῦ καί γένος· οὐ γὰρ δὴ πρέπειν γε Κράσσου πατρὸς ἀνανδροτάτου καί κακίστου γενναῖον οὕτω παῖδα καί λαμπρὸν ἀρετῇ γενέσθαι. τοῦτο τὸ θέαμα Ῥωμαίων ὑπὲρ ἅπαντα τἆλλα δεινὰ τὰς ψυχὰς κατέκλασε καί παρέλυσεν, οὐ θυμοῦ πρὸς ἄμυναν, ὥσπερ ἦν εἰκός, ἀλλὰ φρίκης καί τρόμου πᾶσιν ἐγγενομένου. καίτοι τόν γε Κράσσον αὑτοῦ λαμπρότατον ἐν τῷ τότε πάθει φανῆναι λέγουσιν· ἐβόα γὰρ ἐπιὼν τὰς τάξεις· ἐμὸν, ὦ Ῥωμαῖοι, τοῦτο τὸ πένθος ἴδιόν ἐστιν ἡ δὲ μεγάλη τύχη καί δόξα τῆς Ῥώμης ἐν ὑμῖν ἕστηκε σῳζομένοις ἄθραυστος καί ἀήττητος. εἰ δὲ καί ἐμοῦ τις οἶκτος ἀφῃρημένου παῖδα πάντων ἄριστον, ἐπιδείξασθε τοῦτο ὀργῇ πρὸς τοὺς πολεμίους, ἀφέλεσθε τὴν χαρὰν αὐτῶν, τιμωρήσασθε τὴν ὠμότητα, μὴ καταπλαγῆτε τοῖς γεγενημένοις, εἰ δεῖ τι καί παθεῖν μεγάλων ἐφιεμένους. οὐδὲ Λούκουλλος Τιγράνην ἀναιμωτὶ καθεῖλεν, οὐδὲ Σκηπίων Ἀντίοχον, χιλίας δὲ ναῦς οἱ παλαιοὶ περὶ Σικελίαν ἀπώλεσαν, ἐν δ’ Ἰταλίᾳ πολλοὺς αὐτοκράτορας καί στρατηγούς, ὧν οὐδεὶς προηττηθεὶς ἐκώλυσεν αὐτοὺς κρατῆσαι τῶν νενικηκότων. οὐ γὰρ εὐτυχίᾳ τὰ Ῥωμαίων, ἀλλὰ τλημοσύνῃ καί ἀρετῇ πρὸς τὰ δεινὰ χωρούντων εἰς τοῦτο προῆλθε δυνάμεως.", "st": "Crass. 26.4"}, {"sp": "N", "t": "τοιαῦτα λέγων καὶ παραθαρσύνων ὁ Κράσσος οὐ πολλοὺς ἑώρα προθύμως ὑπακούοντας, ἀλλὰ καὶ συναλαλάξαι κελεύσας ἤλεγξε τοῦ στρατοῦ τήν κατήφειαν, ὡς ἀσθενῆ καὶ ὀλίγην καὶ ἀνώμαλον κραυγὴν ἐποιήσαντο· ἡ δὲ παρὰ τῶν βαρβάρων λαμπρὰ καὶ θρασεῖα κατεῖχεν. τραπομένων δὲ πρὸς ἔργον οἱ μὲν ἱππόται πλάγιοι περιελαύνοντες ἐτόξευον, αὐτοὶ δὲ τοῖς κοντοῖς οἱ πρότακτοι χρώμενοι συνέστελλον εἰς ὀλίγον τοὺς Ῥωμαίους, πλὴν ὅσοι τὸν ὑπὸ τῶν τοξευμάτων φεύγοντες θάνατον ἀπετόλμων παραβόλως εἰς αὐτοὺς φέρεσθαι, μικρὰ μὲν βλάπτοντες, ὀξέως δὲ θνῄσκοντες ὑπὸ τραυμάτων μεγάλων καὶ καιρίων, παχὺν ἐπωθούντων τῷ σιδήρῳ τὸν κοντόν εἰς τοὺς ἵππους, πολλάκις δὲ καὶ διὰ δυεῖν ἀνδρῶν ὑπὸ ῥύμης διαπορευόμενον. οὕτω δὲ ἀγωνισάμενοι νυκτὸς ἐπιούσης ἀπηλλάγησαν, εἰπόντες ὅτι Κράσσῳ χαρίζονται νύκτα μίαν ἀποθρηνῆσαι τὸν υἱόν, ἢν ἄρα μὴ βέλτιον ὑπὲρ ἑαυτοῦ σκεψάμενος ἐλθεῖν μᾶλλον ἐθελήσῃ πρὸς Ἀρσάκην ἢ κομισθῆναι.", "st": "Crass. 27.1"}, {"sp": "N", "t": "οὗτοι μὲν οὖν ἐπαυλισάμενοι πλησίον ἐν ἐλπίσι μεγάλαις ἦσαν νὺξ δὲ χαλεπὴ τοὺς Ῥωμαίους κατελάμβανεν, οὔτε ταφῆς τῶν κειμένων οὔτε θεραπείας τῶν τετρωμένων καὶ ψυχορραγούντων ποιουμένους λόγον, ἑκάστου δ’ ἑαυτὸν ἀποκλαίοντος. ἄφυκτα γὰρ ἐφαίνετο τήν τε ἡμέραν αὐτοῦ προσμείνασι καὶ νύκτωρ εἰς πεδίον ἀχανὲς ἐμβαλοῦσιν· οἵ τε τραυματίαι πολλὴν ἀπορίαν παρεῖχον, καὶ κομίζειν, ἐμποδὼν τῷ τάχει τῆς φυγῆς ἐσόμενοι, καὶ ἀπολείπειν, βοῇ τήν ἀπόδρασιν ἐξαγγελοῦντες. τοῦ δὲ Κράσσου, καίπερ αἴτιον ἁπάντων νομίζοντες, ἐπόθουν ὅμως τήν τε ὄψιν καὶ τήν φωνήν. ὁ δὲ καθ’ ἑαυτὸν ἐγκεκαλυμμένος ὑπὸ σκότους ἔκειτο, παράδειγμα τοῖς πολλοῖς τύχης, τοῖς δ’ εὖ φρονοῦσιν ἀβουλίας καὶ φιλοτιμίας, δι’ ἣν οὐκ ἠγάπα πρῶτος ὢν καὶ μέγιστος ἐν μυριάσιν ἀνθρώπων τοσαύταις, ἀλλ’ ὅτι δυεῖν μόνον ἀνδρῶν ὕστερος ἐκρίνετο, τοῦ παντὸς ἀποδεῖν νομίζων.", "st": "Crass. 27.3"}, {"sp": "N", "t": "τότε δ’ οὖν αὑτὸν Ὀκταούϊος ὁ πρεσβευτὴς καὶ Κάσσιος ἀνίστασαν καὶ παρεθάρρυνον, ὡς δ’ ἀπηγορεύκει παντάπασιν, αὐτοὶ συγκαλέσαντες ἑκατοντάρχας καὶ λοχαγούς, ὡς ἔδοξε βουλευομένοις μὴ μένειν, ἀνίστασαν τὸν στρατὸν ἄνευ σάλπιγγος καὶ δι’ ἡσυχίας τὸ πρῶτον· εἶτ’ αἰσθομένων ὡς ἀπελείποντο τῶν ἀδυνάτων, ἀκοσμία δεινὴ καὶ σύγχυσις μετ’ οἰμωγῆς καὶ βοῆς τὸ στρατόπεδον κατεῖχεν. ἐκ τούτου δὲ ταραχὴ καὶ πτοία προϊόντας αὐτοὺς ὑπελάμβανεν, ὡς ἐπιφερομένων τῶν πολεμίων, καὶ πολλάκις μὲν ἐκτρεπόμενοι, πολλάκις δὲ εἰς τάξιν καθιστάμενοι, τῶν δὲ τραυματιῶν ὅσοι παρηκολούθουν τοὺς μὲν ἀναλαμβάνοντες, τοὺς δὲ ἀποτιθέμενοι, διατριβὴν εἶχον, πλὴν τριακοσίων ἱππέων, οὓς Ἰγνάτιος ἔχων προσέμιξε ταῖς Κάρραις περὶ μέσας νύκτας. φθεγξάμενος δὲ Ῥωμαϊστὶ τοῖς τειχοφυλακοῦσιν, ὡς ὑπήκουσαν, ἐκέλευσε Κοπωνίῳ τῷ ἄρχοντι φράζειν ὅτι γέγονε μάχη μεγάλη Κράσσῳ πρὸς Πάρθους, ἄλλο δ’ οὐδὲν εἰπὼν οὐδ’ αὑτὸν ὅστις ἦν ἀπήλαυνεν ἐπὶ τὸ Ζεῦγμα, καὶ διέσωσε μὲν τοὺς σὺν αὑτῷ, κακῶς δ’ ἤκουσε καταλιπὼν τὸν στρατηγόν. οὐ μὴν ἀλλ’ ὤνησέ γε τὸν Κράσσον ἡ προσριφεῖσα τότε τῷ Κοπωνίῳ φωνή· συμφρονήσας γὰρ ὅτι οὐδὲν χρηστὸν ἀγγέλλειν ἔχοντός ἐστι τὸ τάχος καὶ τὸ συγκεχυμένον τοῦ λόγου, παρήγγειλεν εὐθὺς ἐξοπλίζεσθαι τοὺς στρατιώτας· καὶ ἅμα τῷ πρῶτον αἰσθέσθαι τὸν Κράσσον ἐν ὁδῷ γεγενημένον ἀπαντήσας ἀνελάμβανε καὶ παρέπεμπε τήν στρατιὰν εἰς τήν πόλιν.", "st": "Crass. 27.5"}, {"sp": "N", "t": "οἱ δὲ Πάρθοι νυκτὸς μὲν αἰσθόμενοι τὴν ἀπόδρασιν οὐκ ἐδίωκον, ἅμα δ’ ἡμέρᾳ τοὺς μὲν ἐν τῷ στρατοπέδῳ καταλειφθέντας οὐ μείους τετρακισχιλίων ἐπελθόντες ἀπέσφαξαν, ἐν δὲ τῷ πεδίῳ πλανωμένους πολλοὺς ἱππασάμενοι συνέλαβον. τέσσαρας δ’ ὁμοῦ σπείρας, ἃς ἔτι νυκτὸς ἀπέρρηξε Βαργοντήιος ὁ πρεσβευτής, ἐκπεσούσας τῆς ὁδοῦ περισχόντες ἔν τινι λόφῳ διέφθειραν ἀμυνομένας, πλὴν ἀνδρῶν εἴκοσιν. τούτους δὲ γυμνοῖς τοῖς ξίφεσιν ὠθουμένους δι’ αὐτῶν θαυμάσαντες εἶξαν, καὶ διέξοδον ἀπιοῦσι βάδην εἰς τὰς Κάρρας ἐδίδοσαν.", "st": "Crass. 28.1"}, {"sp": "N", "t": "τῷ δὲ Σουρήνᾳ προσέπεσε ψευδὴς λόγος ἐκπεφευγέναι Κράσσον μετὰ τῶν ἀρίστων, τὸ δ’ εἰς Κάρρας συνερρυηκὸς ὄχλον εἶναι σύμμικτον οὐκ ἀξίων σπουδῆς ἀνθρώπων. οἰόμενος οὖν ἀποβεβληκέναι τὸ τῆς νίκης τέλος, ἔτι δ’ ἀμφιδοξῶν καὶ μαθεῖν βουλόμενος τἀληθές, ὅπως ἢ προσμένων ἐνταῦθα πολιορκοίη Κράσσον ἢ διώκοι χαίρειν ἐάσας Καρρηνούς, ὑποπέμπει τινὰ τῶν παρ’ αὐτῷ διγλώττων πρὸς τὰ τείχη, κελεύσας ἱέντα Ῥωμαϊκὴν διάλεκτον καλεῖν Κράσσον αὐτὸν ἢ Κάσσιον, ὡς Σουρήνα διὰ λόγων ἐθέλοντος αὐτοῖς συγγενέσθαι. ταῦτα τοῦ διγλώττου φράσαντος, ὡς ἀπηγγέλη τοῖς περὶ Κράσσον, ἐδέχοντο τὰς προκλήσεις· καὶ μετὰ μικρὸν ἧκον ἀπὸ τῶν βαρβάρων Ἄραβες, οἳ Κράσσον εὖ καὶ Κάσσιον ἀπ’ ὄψεως ἐγνώριζον, ἐν τῷ στρατοπέδῳ πρὸ τῆς μάχης γεγονότες. οὗτοι τὸν Κάσσιον ἰδόντες ἀπὸ τοῦ τείχους, ἔλεγον ὅτι Σουρήνας σπένδεται καὶ δίδωσιν αὐτοῖς φίλοις οὖσι βασιλέως σῴζεσθαι, Μεσοποταμίαν ἐκλιποῦσιν· τοῦτο γὰρ ὁρᾶν λυσιτελὲς ἀμφοτέροις πρὸ τῆς ἐσχάτης ἀνάγκης. δεξαμένου δὲ τοῦ Κασσίου, καὶ τόπον ὁρισθῆναι καὶ χρόνον ἀξιοῦντος, ἐν ᾧ συνίασι Σουρήνας καὶ Κράσσος, οὕτω φάμενοι ποιήσειν ἀπήλαυνον.", "st": "Crass. 28.3"}, {"sp": "N", "t": "ἡσθεὶς οὖν ὁ Σουρήνας ἐπὶ τῷ τοὺς ἄνδρας ἐνέχεσθαι τῇ πολιορκίᾳ, μεθ’ ἡμέραν ἐπῆγε τοὺς Πάρθους πολλὰ καθυβρίζοντας καὶ κελεύοντας, εἰ βούλονται τυχεῖν σπονδῶν Ῥωμαῖοι, Κράσσον ἐγχειρίσαι σφίσι καὶ Κάσσιον δεδεμένους. οἱ δ’ ἤχθοντο μὲν ἠπατημένοι, μακρὰς δὲ καὶ κενὰς τὰς Ἀρμενίων ἐλπίδας καταβάλλειν τῷ Κράσσῳ φράσαντες εἴχοντο δρασμοῦ· καὶ τοῦτ’ ἔδει μηδένα πρὸ καιροῦ Καρρηνῶν πυθέσθαι, πυνθάνεται δ’ ὁ πάντων ἀπιστότατος Ἀνδρόμαχος, ὑπὸ Κράσσου καὶ τοῦτο πιστευθεὶς καὶ τῆς ὁδοῦ τὴν ἡγεμονίαν. οὐδὲν οὖν ἔλαθε τοὺς Πάρθους, ἐξαγγέλλοντος τοῦ Ἀνδρομάχου καθ’ ἕκαστον. ἐπεὶ δὲ νυκτομαχεῖν οὐ πάτριον αὐτοῖς ἐστιν οὐδὲ ῥᾴδιον, ἐξῄει δὲ νύκτωρ ὁ Κράσσος, ὅπως μὴ καθυστερήσωσι πολὺ τῇ διώξει στρατηγῶν ὁ Ἀνδρόμαχος ἄλλοτε ἄλλας ὁδοὺς ὑφηγεῖτο, καὶ τέλος ἐξέτρεψεν εἰς ἕλη βαθέα καὶ χωρία τάφρων μεστὰ τὴν πορείαν, χαλεπὴν καὶ πολυπλανῆ γινομένην τοῖς ἐπισπομένοις. ἐγένοντο γάρ τινες οἳ μηδὲν ὑγιὲς τὸν Ἀνδρόμαχον στρέφειν καὶ περιελίττειν εἰκάσαντες οὐκ ἠκολούθησαν, ἀλλὰ Κάσσιος μὲν ἐπανῆλθεν εἰς Κάρρας πάλιν, καὶ τῶν ὁδηγῶν Ἄραβες δ’ ἦσαν ἀναμένειν κελευόντων ἄχρι ἂν σελήνη παραλλάξῃ τὸν σκορπίον, ἀλλ’ ἔγωγε, εἰπών, ἔτι τοῦτον μᾶλλον φοβοῦμαι τὸν τοξότην, ἀπήλαυνεν εἰς Συρίαν μεθ’ ἱππέων πεντακοσίων· ἄλλοι δὲ χρησάμενοι πιστοῖς ὁδηγοῖς ἐλάβοντο χωρίων ὀρεινῶν, ἃ καλεῖται Σίννακα, καὶ κατέστησαν ἐν ἀσφαλεῖ πρὸ ἡμέρας, οὗτοι περὶ πεντακισχιλίους ἦσαν ἡγεῖτο δ’ αὐτῶν ἀνὴρ ἀγαθὸς Ὀκταούϊος.", "st": "Crass. 29.1"}, {"sp": "N", "t": "τὸν δὲ Κράσσον ἡμέρα κατελάμβανεν ἐπιβουλευόμενον ὑπ’ Ἀνδρομάχου περὶ τὰς δυσχωρίας καὶ τὸ ἕλος. ἦσαν δὲ τέσσαρες σπεῖραι σὺν αὐτῷ θυρεαοφόρων, ἱππεῖς δὲ παντελῶς ὀλίγοι καὶ πέντε ῥαβδοῦχοι, μεθ’ ὧν ἐπιπόνως εἰς τὴν ὁδὸν καὶ μόλις καταστάς, ἤδη τῶν πολεμίων ἐπικειμένων, ὅσον δώδεκα σταδίους ἀπολιπὼν τοῦ συμμῖξαι τοῖς περὶ τὸν Ὀκταούϊον ἐπ’ ἄλλον ἀναφεύγει λόφον, οὐχ οὕτω μὲν ἄφιππον οὐδ’ ὀχυρόν, ὑποκείμενον δὲ τοῖς Σιννάκοις καὶ συνηρτημένον αὐχένι μακρῷ διὰ μέσου κατατείνοντι τοῦ πεδίου πρὸς τοῦτον, ἦν οὖν ἐν ὄψει τοῖς περὶ τὸν Ὀκταούϊον ὁ κίνδυνος αὐτοῦ. καὶ πρῶτος Ὀκταούϊος ἔθει μετ’ ὀλίγων ἄνωθεν ἐπιβοηθῶν, εἶτα οἱ λοιποὶ κακίσαντες ἑαυτοὺς ἐπεφέροντο, καὶ προσπεσόντες καὶ ὠσάμενοι τοὺς πολεμίους ἀπὸ τοῦ λόφου περιέσχον ἐν μέσῳ τὸν Κράσσον καὶ προεβάλλοντο τοὺς θυρεούς, μεγαληγοροῦντες ὡς οὐκ ἔστι Πάρθοις βέλος ὃ προσπεσεῖται τῷ σώματι τοῦ αὐτοκράτορος πρὶν ἢ σφᾶς ἅπαντας ὑπὲρ αὐτοῦ μαχομένους ἀποθανεῖν.", "st": "Crass. 29.6"}, {"sp": "N", "t": "ὁρῶν οὖν ὁ Σουρήνας τούς τε Πάρθους ἀμβλύτερον ἤδη κινδυνεύοντας, καὶ ἤν ἥ τε νὺξ ἐπίσχῃ καὶ τῶν ὀρῶν οἱ Ῥωμαῖοι λάβωνται, παντάπασιν αὐτοὺς ἐσομένους ἀλήπτους, ἐπῆγε τῷ Κράσσῳ δόλον. ἀφείθησαν μὲν γὰρ ἔνιοι τῶν αἰχμαλώτων ἀκηκοότες ἐν τῷ στρατοπέδῳ τῶν βαρβάρων πρὸς ἀλλήλους ἐπίτηδες διαλεγομένων ὡς οὐ βούλεται βασιλεὺς ἄσπονδον αὑτῷ τὸν πόλεμον εἶναι πρὸς Ῥωμαίους, τὴν δὲ φιλίαν ἀναλαβεῖν χάριτι, Κράσσῳ χρησάμενος φιλανθρώπως, ἔσχοντο δὲ μάχης οἱ βάρβαροι, Σουρήνας δὲ μετὰ τῶν ἀρίστων προσελάσας ἀτρέμα τῷ λόφῳ τοῦ μὲν τόξου τὸν τόνον ἀνῆκε, τὴν δὲ δεξιὰν προὔτεινεν, ἐκάλει δὲ τὸν Κράσσον ἐπὶ συμβάσεις, εἰπὼν ὅτι τῆς μὲν ἀνδρείας καὶ δυνάμεως ἄκοντος πεπείραται βασιλέως, πρᾳότητα δ’ αὐτοῖς καὶ φιλοφροσύνην ἑκὼν ἐπιδείκνυται σπενδόμενος ἀπιοῦσι καὶ παρέχων σῴζεσθαι.", "st": "Crass. 30.1"}, {"sp": "N", "t": "ταῦτα τοῦ Σουρήνα λέγοντος οἱ μὲν ἄλλοι προθύμως ἐδέξαντο καὶ περιχαρεῖς ἦσαν, ὁ δὲ Κράσσος οὐδὲν ὅ τι μὴ δι’ ἀπάτης ἐσφαλμένος ὑπ’ αὐτῶν, καὶ τὸ αἰφνίδιον τῆς μεταβολῆς ἄλογον ἡγούμενος, οὐχ ὑπήκουεν, ἀλλ’ ἐβουλεύετο. τῶν δὲ στρατιωτῶν βοώντων καὶ κελευόντων, εἶτα λοιδορούντων καὶ κακιζόντων ὡς προβάλλοντα μαχουμένους αὐτοὺς οἷς αὐτὸς ἀνόπλοις εἰς λόγους οὐ θαρρεῖ συνελθεῖν, πρῶτον μὲν ἐπειρᾶτο δεῖσθαι καὶ λέγειν ὅτι τὸ λειπόμενον μέρος τῆς ἡμέρας διακαρτερήσαντες ἐν τοῖς ὀρεινοῖς καὶ τραχέσι δύνανται διὰ νυκτὸς ἰέναι, καὶ τὴν ὁδὸν ἐδείκνυε, καὶ παρεκάλει τὴν ἐλπίδα μὴ προέσθαι τῆς σωτηρίας ἐγγὺς οὔσης. ὡς δὲ χαλεπαίνοντες αὐτῷ καὶ τὰ ὅπλα κρούοντες ἠπείλουν, φοβηθεὶς ἐχώρει, καὶ τοσοῦτον εἶπε μεταστραφείς Ὀκταούϊε καὶ Πετρώνιε καὶ ὅσοι πάρεστε Ῥωμαίων ἄρχοντες, ὑμεῖς ὁρᾶτε τῆς ἐμῆς ὁδοῦ τὴν ἀνάγκην, καὶ σύνιστε παρόντες ὡς αἰσχρὰ πάσχω καὶ βίαια τοῖς δ’ ἄλλοις ἅπασιν ἀνθρώποις λέγετε σωθέντες ὡς Κράσσος ἀπατηθεὶς ὑπὸ τῶν πολεμίων, οὐκ ἐκδοθεὶς ὑπὸ τῶν πολιτῶν ἀπώλετο.", "st": "Crass. 30.3"}, {"sp": "N", "t": "οὐ μὴν ἔμειναν οἱ περὶ τόν Ὀκταούϊον, ἀλλὰ συγκατέβαινον ἀπὸ τοῦ λόφου· τοὺς δὲ ῥαβδούχους ἑπομένους ὁ Κράσσος ἀπήλασεν. πρῶτοι δὲ τῶν βαρβάρων ἀπήντησαν αὐτῷ δύο μιξέλληνες, οἳ καὶ προσεκύνησαν τόν Κράσσον ἀπὸ τῶν ἵππων ἁλόμενοι, καὶ προσαγορεύσαντες ἑλλάδι φωνῇ παρεκάλουν προπέμψαι τινάς, οἷς ἐπιδείξεται Σουρήνας ἑαυτὸν καὶ τοὺς περὶ αὑτὸν ἀνόπλους καὶ ἀσιδήρους προσερχομένους. ὁ δὲ Κράσσος ἀπεκρίνατο μέν ὡς, εἰ καὶ τόν ἐλάχιστον εἶχε τοῦ ζῆν λόγον, οὐκ ἂν εἷς χεῖρας αὐτοῖς ἦλθεν, ὅμως δὲ δύο Ῥωσκίους ἀδελφοὺς ἔπεμψε πευσομένους ἐπί τίσι καὶ πόσοι συνίασιν. οὓς εὐθὺς συλλαβὼν ὁ Σουρήνας κατέσχεν, αὐτὸς δὲ μετὰ τῶν ἀρίστων ἱππότης προσῄει καὶ τί τοῦτ’, ἔφη, πεζὸς ὁ Ῥωμαίων αὐτοκράτωρ, ἡμεῖς δὲ ὀχούμεθα; καὶ προσαγαγεῖν ἐκέλευσεν ἵππον αὐτῷ. τοῦ δὲ Κράσσου φήσαντος οὔτε αὐτὸν ἁμαρτάνειν οὔτ’ ἐκεῖνον, ὡς ἑκατέρῳ πάτριόν ἐστι ποιουμένους τὴν σύνοδον, εἶναι μέν αὐτόθεν ἔφη σπονδὰς καὶ εἰρήνην ὁ Σουρήνας Ὑρώδῃ τε βασιλεῖ καὶ Ῥωμαίοις, δεῖν δὲ γράψασθαι τὰς συνθήκας ἐπὶ τόν ποταμὸν προσελθόντας· οὐ γὰρ ὑμεῖς γε, ἔφη, πάνυ μνήμονες ὁμολογιῶν οἱ Ῥωμαῖοι, καὶ προὔτεινε τὴν δεξιὰν αὐτῷ. μεταπεμπομένου δ’ ἵππον οὐδὲν ἔφη δεῖν βασιλεὺς γάρ σοι δίδωσι τοῦτον. ἅμα δ’ ἵππος τε τῷ Κράσσῳ παρέστη χρυσοχάλινος, οἵ τε ἀναβολεῖς αὐτὸν ἀράμενοι περιεβίβασαν καὶ παρείποντο πληγῇ τόν ἵππον ἐπιταχύνοντες. Ὀκταούϊος δὲ πρῶτος ἀντιλαμβάνεται τῶν χαλινῶν, καὶ μετ’ ἐκεῖνον εἷς τῶν χιλιάρχων Πετρώνιος, εἶτα οἱ λοιποὶ περιίσταντο τόν τε ἵππον ἀνακόπτειν πειρώμενοι καὶ τοὺς πιεζοῦντας τόν Κράσσον ἐξ ἐκατέρου μέρους ἀφέλκοντες. ὠθισμοῦ δὲ γενομένου καὶ ταραχῆς, εἶτα πληγῶν, Ὀκταούϊος μέν ἀνασπάσας τὸ ξίφος ἑνὸς τῶν βαρβάρων κτείνει τόν ἱπποκόμον, ἕτερος δὲ τόν Ὀκταούϊον ἐκ τῶν ὄπισθεν πατάξας. Πετρώνιος δὲ ὅπλου μέν οὐκ εὐπόρησεν, εἷς δὲ τόν θώρακα πληγεὶς ἀπεπήδησεν ἄτρωτος· τόν δὲ Κράσσον ὄνομα Πομαξάθρης Πάρθος ἀπέκτεινεν.", "st": "Crass. 31.1"}, {"sp": "N", "t": "οἱ δ’ οὔ φασιν, ἀλλ’ ἕτερον μέν εἶναι τόν ἀποκτείναντα, τοῦτον δὲ κειμένου τὴν κεφαλὴν ἀποκόψαι καὶ τὴν δεξιάν. εἰκάζεται δὲ ταῦτα μᾶλλον ἢ γινώσκεται· τῶν γὰρ παρόντων οἱ μέν ἐκεῖ μαχόμενοι περὶ τόν Κράσσον ἀνῃρέθησαν, οἱ δ’ εὐθὺς ἀνεπήδησαν ἐπὶ τόν λόφον. ἐπελθόντων δὲ τῶν Πάρθων καὶ λεγόντων ὅτι Κράσσος μέν δίκην δέδωκε, τοὺς δ’ ἄλλους κελεύει Σουρήνας κατιέναι θαρροῦντας, οἱ μέν ἐνεχείρισαν αὑτοὺς καταβάντες, οἱ δὲ τῆς νυκτὸς ἐσπάρησαν, καὶ τούτων ὀλίγοι παντάπασι διεσώθησαν· τοὺς δ’ ἄλλους ἐκθηρεύοντες οἱ Ἄραβες συνελάμβανον καὶ διέφθειρον. λέγονται δ’ οἱ πάντες δισμύριοι μέν ἀποθανεῖν, μύριοι δὲ ἁλῶναι ζῶντες.", "st": "Crass. 31.6"}, {"sp": "N", "t": "ὁ δὲ Σουρήνας τὴν κεφαλὴν τοῦ Κράσσου καὶ τὴν χεῖρα πρὸς Ὑρώδην ἔπεμψεν εἰς Ἀρμενίαν, αὐτὸς δὲ διαδοὺς λόγον ὑπ’ ἀγγέλων εἰς Σελεύκειαν ὡς ζῶντα Κράσσον ἄγοι, παρεσκευάζετο πομπήν τινα γελοίαν ὕβρει προσαγορεύων θρίαμβον. ὁ μὲν γὰρ ἐμφερέστατος Κράσσῳ τῶν αἰχμαλώτων Γάιος Πακκιανός, ἐσθῆτα βασιλικὴν γυναικὸς ἐνδὺς καὶ διδαχθεὶς Κράσσος ὑπακούειν καὶ αὐτοκράτωρ τοῖς καλοῦσιν, ἐφ’ ἵππου καθήμενος ἤγετο· πρὸ αὐτοῦ δὲ σαλπιγκταὶ καὶ ῥαβδοῦχοί τινες ὀχούμενοι καμήλοις ἤλαυνον· ἐξήρτητο δὲ τῶν ῥάβδων βαλάντια καὶ παρὰ τοὺς πελέκεις πρόσφατοι κεφαλαὶ Ῥωμαίων ἀποτετμημέναι. κατόπιν δ’ εἵποντο Σελευκίδες ἑταῖραι μουσουργοί, πολλὰ βωμολόχα καὶ γελοῖα δι’ ᾀσμάτων εἰς θηλύτητα καὶ ἀνανδρίαν τοῦ Κράσσου λέγουσαι.", "st": "Crass. 32.1"}, {"sp": "N", "t": "ταῦτά μὲν οὖν πάντες ἐθεῶντο. τὴν δὲ γερουσίαν τῶν Σελευκέων ἀθροίσας εἰσήνεγκεν ἀκόλαστα βιβλία τῶν Ἀριστείδου Μιλησιακῶν, οὔτι ταῦτά γε καταψευσάμενος· εὑρέθη γὰρ ἐν τοῖς Ῥωσκίου σκευοφόροις, καὶ παρέσχε τῷ Σουρήνᾳ καθυβρίσαι πολλὰ καὶ κατασκῶψαι τοὺς Ῥωμαίους, εἰ μηδὲ πολεμοῦντες ἀπέχεσθαι πραγμάτων καὶ γραμμάτων δύνανται τοιούτων. τοῖς μέντοι Σελευκεῦσιν ἐδόκει σοφὸς ἀνὴρ Αἴσωπος εἶναι, τὸν Σουρήναν ὁρῶσι τὴν τῶν Μιλησιακῶν ἀκολαστημάτων πήραν ἐξηρτημένον πρόσθεν, ὄπισθεν δὲ Παρθικὴν Σύβαριν ἐφελκόμενον ἐν τοσαύταις παλλακίδων ἁμάξαις, τρόπον τινὰ ταῖς λεγομέναις ἐχίδναις καὶ σκυτάλαις ἀντιμόρφως τὰ μὲν ἐμφανῆ καὶ πρόσθια μέρη φοβερὰ καὶ θηριώδη δόρασι καὶ τόξοις καὶ ἵπποις προβαλλομένην, κατ’ οὐρὰν δὲ τῆς φάλαγγος εἰς χορείας καὶ κρόταλα καὶ ψαλμοὺς καὶ παννυχίδας ἀκολάστους μετὰ γυναικῶν τελευτῶσαν. ψεκτὸς μὲν γὰρ ὁ Ῥώσκιος, ἀναιδεῖς δὲ Πάρθοι τὰ Μιλησιακὰ ψέγοντες, ὧν πολλοὶ βεβασιλεύκασιν ἐκ Μιλησίων καὶ Ἰωνίδων ἑταιρῶν γεγονότες Ἀρσακίδαι.", "st": "Crass. 32.4"}, {"sp": "N", "t": "τούτων δὲ πραττομένων Ὑρώδης ἐτύγχανεν ἤδη διηλλαγμένος Ἀρταουάσδῃ τῷ Ἀρμενίῳ καὶ τὴν ἀδελφὴν αὐτοῦ γυναῖκα Πακόρῳ τῷ παιδὶ καθωμολογημένος, ἑστιάσεις τε καὶ πότοι δι’ ἀλλήλων ἦσαν αὐτοῖς, καὶ πολλὰ παρεισήγετο τῶν ἀπὸ τῆς Ἑλλάδος ἀκουσμάτων. ἦν γὰρ οὔτε φωνῆς οὔτε γραμμάτων Ὑρώδης Ἑλληνικῶν ἄπειρος, ὁ δ’ Ἀρταοθάσδης καὶ τραγῳδίας ἐποίει καὶ λόγους ἔγραφε καὶ ἱστορίας, ὧν ἔνιαι διασῴζονται, τῆς δὲ κεφαλῆς τοῦ Κράσσου κομισθείσης ἐπὶ θύρας ἀπηρμέναι μὲν ἦσαν αἱ τράπεζαι, τραγῳδιῶν δὲ ὑποκριτὴς Ἰάσων ὄνομα Τραλλιανὸς ᾖδεν Εὐριπίδου Βακχῶν τὰ περὶ τὴν Ἀγαύην. εὐδοκιμοῦντος δ’ αὐτοῦ Σιλλάκης ἐπιστὰς τῷ ἀνδρῶνι καὶ προσκυνήσας προὔβαλεν εἰς μέσον τοῦ Κράσσου τὴν κεφαλήν. κρότῳ δὲ τῶν Πάρθων μετὰ κραυγῆς καὶ χαρᾶς ἀραμένων, τὸν μὲν Σιλλάκην κατέκλιναν οἱ ὑπηρέται βασιλέως κελεύσαντος, ὁ δ’ Ἰάσων τὰ μὲν τοῦ Πενθέως σκευοποιήματα παρέδωκέ τινι τῶν χορευτῶν, τῆς δὲ τοῦ Κράσσου κεφαλῆς λαβόμενος καὶ ἀναβακχεύσας ἐπέραινεν ἐκεῖνα τὰ μέλη μετ’ ἐνθουσιασμοῦ καὶ ᾠδῆς·", "st": "Crass. 33.1"}, {"sp": "N", "t": "φέρομεν ἐξ ὄρεος<br>ἕλικα νεότομον ἐπὶ μέλαθρα,<br>μακαρίαν θήραν.<br>καὶ ταῦτα μὲν πάντας ἔτερπεν·", "st": "Crass. 33.1b"}, {"sp": "N", "t": "ᾀδομένων δὲ τῶν ἐφεξῆς ἀμοιβαίων πρὸς τὸν χορόν,", "st": "Crass. 33.4"}, {"sp": "N", "t": "Χόρος<br>τίς ἐφόνευσεν;<br>Ἀγαύη", "st": "Crass. 33.4b"}, {"sp": "N", "t": "ἐμὸν τὸ γέρας·", "st": "Crass. 33.4c"}, {"sp": "N", "t": "ἀναπηδήσας ὁ Πομαξάθρης ἐτύγχανε δὲ δειπνῶν ἀντελαμβάνετο τῆς κεφαλῆς, ὡς ἑαυτῷ λέγειν ταῦτα μᾶλλον ἢ; ἐκείνῳ προσῆκον. ἡσθεὶς δ’ ὁ βασιλεὺς τὸν μὲν οἷς πάτριόν ἐστιν ἐδωρήσατο, τῷ δ’ Ἰάσονι τάλαντον ἔδωκεν. εἰς τοιοῦτό φασιν ἐξόδιον τὴν Κράσσου στρατηγίαν ὥσπερ τραγῳδίαν τελευτῆσαι.", "st": "Crass. 33.4d"}, {"sp": "N", "t": "δίκη μέντοι καὶ τῆς ὠμότητος Ὑρώδην καὶ τῆς ἐπιορκίας Σουρήναν ἀξία μετῆλθεν. Σουρήναν μὲν γὰρ οὐ μετὰ πολὺν χρόνον Ὑρώδης φθόνῳ τῆς δόξης ἀπέκτεινεν, Ὑρώδῃ δὲ ἀποβαλόντι Πάκορον ὑπὸ Ῥωμαίων μάχῃ κρατηθέντα, καὶ νοσήσαντι νόσον εἰς ὕδρωπα τραπεῖσαν, Φραάτης ὁ υἱὸς ἐπιβουλεύων ἀκόνιτον ἔδωκεν. ἀναδεξαμένης δὲ τῆς νόσου τὸ φάρμακον εἰς ἑαυτὴν, ὥστε συνεκκριθῆναι, καὶ τοῦ σώματος κουφισθέντος, ἐπὶ τὴν ταχίστην τῶν ὁδῶν ἐλθὼν ὁ Φραάτης ἀπέπνιξεν αὐτόν.", "st": "Crass. 33.5"}, {"sp": "HDR", "t": "Νικίου καὶ Κράσσου σύγκρισις"}, {"sp": "N", "t": "ἐν δὲ τῇ συγκρίσει πρῶτον ὁ Νικίου πλοῦτος τῷ Κράσσου παραβαλλόμενος ἀμεμπτοτέραν ἔχει τὴν κτῆσιν. ἄλλως μὲν γὰρ οὐκ ἄν τις δοκιμάσειε τὴν ἀπὸ μετάλλων ἐργασίαν, ἧς τὰ πλεῖστα περαίνεται διὰ κακούργων ἢ βαρβάρων, ἐνίων δεδεμένων καὶ φθειρομένων ἐν τόποις ὑπούλοις καὶ νοσεροῖς· παραβαλλομένη δὲ πρὸς τὰ Σύλλα δημιόπρατα καὶ τὰς περὶ τὸ πῦρ ἐργολαβίας, ἐπιεικεστέρα φανεῖται. ταύταις γὰρ ὁ Κράσσος ἀναφανδὸν ὡς τῷ γεωργεῖν ἐχρῆτο καὶ τῷ δανείζειν· ἃ δὲ ἔξαρνος ἦν ἐλεγχόμενος, ἐπὶ κέρδεσιν ἐν βουλῇ λέγειν καὶ τοὺς συμμάχους ἀδικεῖν καὶ γύναια περιιὼν κολακεύειν καὶ συνεπικρύπτειν τοὺς πονηρούς, τούτων αἰτίαν οὐδὲ ψευδῆ ποτε Νικίας ἔλαβεν, ἄλλως δὲ διδοὺς καὶ προϊέμενος ἀργύριον ὑπὸ δειλίας τοῖς συκοφάνταις ἐχλευάζετο, πρᾶγμα ποιῶν Περικλεῖ μὲν ἴσως καὶ Ἀριστείδῃ μὴ πρέπον, αὐτῷ δ’ ἀναγκαῖον οὐκ εὖ πεφυκότι πρὸς τὸ θαρρεῖν. ᾧ καὶ Λυκοῦργος ὕστερον ὁ ῥήτωρ ἐπαρρησιάσατο πρὸς τὸν δῆμον, αἰτίαν ἔχων ἐξωνήσασθαί τινα τῶν συκοφαντῶν· ἥδομαι γάρ, εἶπεν, εἰ τοσοῦτον χρόνον πεπολιτευμένος παρ’ ὑμῖν διδοὺς πεφώραμαι πρότερον ἢ λαμβάνων.", "st": "Comp. Nic.–Crass. 1.1"}, {"sp": "N", "t": "τὴν δὲ ταῖς δαπάναις πολιτικώτερος μὲν ὁ Νικίας ἀναθήμασι καὶ γυμνασιαρχίαις καὶ διδασκαλίαις χορῶν φιλοτιμούμενος, ὧν δ’ ὁ Κράσσος ἀνάλωσεν ἑστιάσας ἅμα τοσαύτας μυριάδας ἀνθρώπων, εἶτα θρέψας πάλιν, οὐδὲν ἦν μέρος ἃ Νικίας ἐκέκτητο σὺν οἷς ἀνάλωσεν, ὥστε θαυμάζειν, εἴ τινα λέληθε τὸ τὴν κακίαν ἀνωμαλίαν εἶναί τινα τρόπου καὶ ἀνομολογίαν, ὁρῶντα τοὺς αἰσχρῶς συλλέγοντας εἶτ’ ἀχρήστως ἐκχέοντας.", "st": "Comp. Nic.–Crass. 1.4"}, {"sp": "N", "t": "περὶ μὲν τοῦ πλούτου τοσαῦτα· τοῖς δὲ πολιτεύμασι τοῦ μὲν Νικίου πανοῦργον οὐδὲν οὐδὲ ἄδικον οὐδὲ βίαιον πρόσεστιν οὐδὲ θρασύτης, ἀλλ’ ἐξηπατᾶτο μᾶλλον ὑπὸ Ἀλκιβιάδου καὶ τῷ δήμῳ προσῄει μετ’ εὐλαβείας, τοῦ δὲ Κράσσου πολλὴν μὲν ἐν ταῖς πρὸς ἔχθραν καὶ φιλίαν μεταβολαῖς ἀπιστίαν καὶ ἀνελευθερίαν κατηγοροῦσι, βίᾳ δ’ οὐδ’ αὐτὸς ἠρνεῖτο τὴν ὑπατείαν μετιέναι, μισθωσάμενος ἄνδρας τοὺς Κάτωνι καὶ Δομιτίῳ τὰς χεῖρας προσοίσοντας. ἐν δὲ τῇ περί τῶν ἐπαρχιῶν ψηφοφορίᾳ τοῦ δήμου πολλοὶ μὲν ἐτρώθησαν, ἔπεσον δὲ τέσσαρες, αὐτὸς δ’, ὅπερ ἡμᾶς ἐν τῇ διηγήσει παρελήλυθε, Λεύκιον Ἀννάλιον, ἄνδρα βουλευτήν, ἀντιλέγοντα πὺξ πατάξας εἰς τὸ πρόσωπον ἐξέβαλεν ᾑμαγμένον.", "st": "Comp. Nic.–Crass. 2.1"}, {"sp": "N", "t": "ὡς δὲ περί ταῦτα βίαιος ὁ Κράσσος καὶ τυραννικός, οὕτως αὖ πάλιν ἐκείνου τὸ ψοφοδεὲς ἐν τῇ πολιτείᾳ καὶ ἄτολμον καὶ τοῖς κακίστοις ὑφειμένον τῶν μεγίστων ἐπιλήψεων ἄξιον ὁ δὲ Κράσσος ὑψηλὸς περί γε ταῦτα καὶ μεγαλόφρων, οὐ πρὸς Κλέωνας οὐδ’ Ὑπερβόλους, μὰ Δία, τοῦ ἀγῶνος ὄντος, ἀλλὰ πρὸς τὴν Καίσαρος λαμπρότητα καὶ τρεῖς τοῦ Πομπηΐου θριάμβους, οὐχ ὑπείξας, ἀλλ’ ἀντάρας ἑκατέρῳ τὴν δύναμιν, ἀξιώματι δὲ τῆς τιμητικῆς ἀρχῆς καὶ Πομπήιον ὑπερβαλόμενος. δεῖ γὰρ ἐπὶ μεγίστοις οὐ τὸ ἀνεπίφθονον, ἀλλὰ τὸ λαμπρὸν ἐν πολιτείᾳ λαμβάνειν, μεγέθει δυνάμεως ἐξαμαυροῦντα τὸν φθόνον. εἰ δ’ ἐξ ἅπαντος ἀγαπᾶς ἀσφάλειαν καὶ ἡσυχίαν, καὶ δέδιας Ἀλκιβιάδην μὲν ἐπὶ τοῦ βήματος, ἐν δὲ Πύλῳ Λακεδαιμονίους, Περδίκκαν δ’ ἐν Θρᾴκῃ, πολλὴν εὐρυχωρίαν ἡ πόλις ἔχει σχολῆς ἐκ μέσου γενόμενον καθῆσθαι πλέκοντα τῆς ἀταραξίας σεαυτῷ στέφανον, ὡς ἔνιοι σοφισταὶ λέγουσιν. ὁ μὲν γὰρ τῆς εἰρήνης ἔρως θεῖος ἦν ὡς ἀληθῶς, καὶ τὸ λῦσαι τὸν πόλεμον ἑλληνικώτατον πολίτευμα· καὶ τῆς πράξεως ἕνεκα ταύτης οὐκ ἄξιον Νικίᾳ παραβαλεῖν Κράσσον, οὐδ’ εἰ τὸ Κάσπιον φέρων πέλαγος ἢ τὸν Ἰνδὸν ὠκεανὸν τῇ Ῥωμαίων ἡγεμονίᾳ προσώρισεν.", "st": "Comp. Nic.–Crass. 2.3"}, {"sp": "N", "t": "πόλει μέντοι χρώμενον ἀρετῆς αἰσθανομένῃ καὶ κρείττονα ὄντα τῇ δυνάμει χώραν οὐ δοτέον τοῖς πονηροῖς οὐδ’ ἀρχὴν μὴ ἄρχουσιν οὐδὲ πίστιν ἀπιστουμένοις, ὅπερ ἐποίησεν ὁ Νικίας, τὸν Κλέωνα μηδὲν ὄντα πλέον ἐν τῇ πόλει τῆς ἀπὸ τοῦ βήματος ἀναισχυντίας καὶ κραυγῆς αὐτὸς εἰς τὸ στρατηγεῖν καταστήσας. οὐκ ἐπαινῶ μὲν γὰρ ἐγὼ τὸν Κράσσον ἐν τοῖς Σπαρτακείοις ἐπειχθέντα θᾶσσον ἢ ἀσφαλέστερον διαγωνίσασθαι, καίτοι φιλοτιμίας ἦν τὸ δεῖσαι μὴ Πομπήιος ἐλθὼν ἀφέληται τὴν δόξαν αὐτοῦ, καθάπερ ἀφείλετο Μετέλλου Μόμμιος τὴν Κόρινθον τὸ δὲ τοῦ Νικίου παντάπασιν ἄτοπον καὶ δεινόν. οὐ γὰρ ἐλπίδας οὐδὲ ῥᾳστώνην ἐχούσης ἐξέστη τῷ ἐχθρῷ φιλοτιμίας καὶ ἀρχῆς, ἀλλὰ κίνδυνον ὑφορώμενος ἐν τῇ στρατηγίᾳ μέγαν ἠγάπησε, τὸ καθ’ αὑτὸν ἐν ἀσφαλεῖ θέμενος, προέσθαι τὸ κοινόν· καίτοι ὅ γε Θεμιστοκλῆς, ἵνα μὴ φαῦλος ἄνθρωπος ἐν τοῖς Περσικοῖς καὶ ἄφρων στρατηγήσας ἀπολέσῃ τὴν πόλιν, ἀργυρίῳ τῆς ἀρχῆς ἀπέστησεν αὐτόν, καὶ Κάτων, ὅτε μάλιστα ἑώρα πράγματα καὶ κινδύνους ἔχουσαν ὑπὲρ τῆς πόλεως τὴν δημαρχίαν, μετῆλθεν· ὁ δ’ αὑτὸν ἐπὶ τὴν Μίνῳαν καὶ Κύθηρα καὶ Μηλίους τοὺς ταλαιπώρους φυλάττων στρατηγόν, εἰ δὲ δέοι μάχεσθαι Λακεδαιμονίοις, ἀποδυόμενος τὴν χλανύδα καὶ τῇ Κλέωνος ἀπειρίᾳ καὶ θρασύτητι ναῦς καὶ ἄνδρας καὶ ὅπλα καὶ στρατηγίαν ἐμπειρίας ἄκρας δεομένην παραδιδούς, οὐ τὴν ἑαυτοῦ προΐεται δόξαν, ἀλλὰ τὴν τῆς πατρίδος ἀσφάλειαν καὶ σωτηρίαν. ὅθεν ὕστερον οὐχ ἑκὼν οὐδὲ βουλόμενος Συρακουσίοις πολεμεῖν ἠναγκάζετο, δοκῶν οὐ λογισμῷ τοῦ συμφέροντος, ἀλλὰ ῥᾳστώνῃ καὶ μαλακίᾳ τὸ παρ’ αὑτὸν ἀποστερεῖν Σικελίας τὴν πόλιν.", "st": "Comp. Nic.–Crass. 3.1"}, {"sp": "N", "t": "ἐκεῖνο μέντοι μεγάλης ἐπιεικείας σημεῖον, ὅτι δυσχεραίνοντα τὸ πολεμεῖν ἀεὶ καὶ φεύγοντα τὸ στρατηγεῖν οὐκ ἐπαύοντο χειροτονοῦντες ὡς ἐμπειρότατον καὶ βέλτιστον· τῷ δὲ Κράσσῳ παρὰ πάντα τὸν χρόνον ἐφιεμένῳ στρατηγίας οὐχ ὑπῆρξε τυχεῖν, πλὴν ἐπὶ τὸν δουλικὸν πόλεμον ἐξ ἀνάγκης, Πομπηΐου καὶ Μετέλλου καὶ Λουκούλλων ἀμφοτέρων ἀπόντων, καίτοι τότε τιμωμένῳ μάλιστα καὶ δυναμένῳ πλεῖστον, ἀλλ’, ὡς ἔοικε, καὶ τοῖς σπουδάζουσι περὶ αὑτὸν ἐδόκει κατὰ τὸν κωμικὸν ἀνὴρ ἄριστος εἶναι τἆλλα πλὴν ἐν ἀσπίδι. καὶ τοῦτο Ῥωμαίους οὐδὲν ὤνησεν ἐκβιασθέντας ὑπὸ τῆς φιλαρχίας αὐτοῦ καὶ φιλοτιμίας. Ἀθηναῖοι μὲν γὰρ ἄκοντα Νικίαν ἐξέπεμψαν ἐπὶ τὸν πόλεμον. Ῥωμαίους δὲ Κράσσος ἄκοντας ἐξήγαγεν· καὶ διὰ μὲν τοῦτον ἡ πόλις, ἐκεῖνος δὲ διὰ τὴν πόλιν ἠτύχησεν.", "st": "Comp. Nic.–Crass. 3.6"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ μᾶλλον ἔστιν ἐν τούτοις τὸν Νικίαν ἐπαινεῖν ἢ ψέγειν τὸν Κράσσον. ὁ μὲν γὰρ ἐμπειρίᾳ καὶ λογισμῷ χρησάμενος ἡγεμόνος ἔμφρονος οὐ συνηπατήθη ταῖς ἐλπίσι τῶν πολιτῶν, ἀλλ’ ἀπεῖπε καὶ ἀπέγνω λήψεσθαι Σικελίαν· ὁ δ’ ὡς ἐπὶ ῥᾷστον ἔργον τὸν Παρθικὸν ὁρμήσας πόλεμον ἥμαρτεν. ὠρέχθη δὲ μεγάλων, Καίσαρος τὰ ἑσπέρια καὶ Κελτοὺς καὶ Γερμανοὺς καταστρεφομένου καὶ Βρεττανίαν, αὐτὸς ἐπὶ τὴν ἕω καὶ τὴν Ἰνδικὴν ἐλάσαι θάλασσαν καὶ προσεργάσασθαι τὴν Ἀσίαν οἷς Πομπήιος ἐπῆλθε καὶ Λούκουλλος ἀντέσχεν, ἄνδρες εὐμενεῖς καὶ πρὸς πάντας ἀγαθοὶ διαμείναντες, προελόμενοι δ’ ὅμοια Κράσσῳ καὶ τὰς αὐτὰς ὑποθέσεις λαβόντες, ἐπεὶ καὶ Πομπηΐῳ τῆς ἀρχῆς διδομένης ἡ σύγκλητος ἠναντιοῦτο, καὶ Καίσαρα μυριάδας τριάκοντα Γερμανῶν τρεψάμενον συνεβούλευεν ὁ Κάτων ἐκδοῦναι τοῖς ἡττημένοις καὶ τρέψαι τὸ μήνιμα τοῦ παρασπονδήματος εἰς ἐκεῖνον ὁ δὲ δῆμος ἐρρῶσθαι φράσας Κάτωνι, πεντεκαίδεκα ἡμέρας ἔθυεν ἐπινίκια καὶ περιχαρὴς ἦν. πῶς οὖν ἂν διετέθη καὶ πόσας ἔθυσεν ἡμέρας, εἰ Κράσσος ἐκ Βαβυλῶνος ἔγραψε νικᾶν, εἶτ’ ἐπελθὼν Μηδίαν, Περσίδα, Ὑρκανούς, Σοῦσα, Βάκτρα, Ῥωμαίων ἐπαρχίας ἀπέδειξεν; εἴπερ γὰρ ἀδικεῖν χρή, κατὰ τὸν Εὐριπίδην, ἡσυχίαν ἄγειν μὴ δυναμένους μηδὲ χρῆσθαι τοῖς παροῦσιν ἀγαθοῖς εἰδότας, οὐ Σκάνδειαν, οὐ Μένδην ἐκκοπτέον, οὐδὲ φεύγοντας Αἰγινήτας ἀπολελοιπότας τὴν ἑαυτῶν, ὥσπερ ὄρνιθας εἰς ἑτέραν χώραν ἀποκεκρυμμένους, ἐκθηρατέον, ἀλλὰ πολλοῦ τιμητέον τὸ ἀδικεῖν, μὴ ῥᾳδίως μηδ’ ἐπὶ τοῖς τυχοῦσιν, ὥς τι φαῦλον ἢ μικρὸν, προϊεμένους τὸ δίκαιον, οἱ δὲ τὴν μὲν τῆς Ἀλεξάνδρου στρατείας ὁρμὴν ἐπαινοῦντες, τὴν δὲ Κράσσου ψέγοντες, οὐκ εὖ τὰ πρῶτα κρίνουσιν ἀπὸ τῶν τελευταίων.", "st": "Comp. Nic.–Crass. 4.1"}, {"sp": "N", "t": "ἐν δὲ ταῖς στρατηγίαις αὐταῖς Νικίου μὲν οὐκ ὀλίγα γενναῖα· καὶ γὰρ μάχαις πολλαῖς ἐνίκησε τοὺς πολεμίους, καὶ τοῦ λαβεῖν Συρακούσας ὀλίγον ἐδέησε, καὶ πάντα δι’ αὑτὸν οὐκ ἔπταισεν, ἀλλὰ καὶ νόσον ἄν τις αἰτιάσαιτο καὶ φθόνον τῶν οἴκοι πολιτῶν Κράσσος δὲ διὰ πλῆθος ἁμαρτημάτων οὐδὲν τῇ τύχῃ χρηστὸν ἀποδείξασθαι παρῆκεν, ὥστε θαυμάζειν αὐτοῦ τὴν ἀβελτερίαν οὐ τῆς Πάρθων δυνάμεως ἡττηθεῖσαν, ἀλλὰ τῆς Ῥωμαίων εὐτυχίας περιγενομένην.", "st": "Comp. Nic.–Crass. 5.1"}, {"sp": "N", "t": "ἐπεὶ δ’ ὁ μὲν μηδενὸς τῶν ἀπὸ μαντικῆς καταφρονῶν, ὁ δὲ πάντα ὑπερορῶν ὁμοίως ἀπώλοντο, χαλεπὴ μὲν ἐν τούτοις ἡ ἀσφάλεια καὶ δύσκριτος, ἐπιεικέστερον δὲ τοῦ παρανόμου καὶ αὐθάδους τὸ μετὰ δόξης παλαιᾶς καὶ συνήθους δι’ εὐλάβειαν ἁμαρτανόμενον.", "st": "Comp. Nic.–Crass. 5.2"}, {"sp": "N", "t": "περὶ μέντοι τὴν τελευτὴν ἀμεμπτότερος ὁ Κράσσος οὐ παραδοὺς ἑαυτὸν οὐδὲ δεθεὶς οὐδὲ φενακισθείς, ἀλλ’ εἴξας τοῖς φίλοις δεομένοις καὶ παρασπονδηθεὶς ὑπὸ τῶν πολεμίων ὁ δὲ Νικίας αἰσχρᾶς καὶ ἀκλεοῦς ἐλπίδι σωτηρίας ὑποπεσὼν τοῖς πολεμίοις αἰσχίονα ἑαυτῷ τὸν θάνατον ἐποίησεν.", "st": "Comp. Nic.–Crass. 5.2b"}, {"sp": "HDR", "t": "Εὐμένης"}, {"sp": "N", "t": "εὐμενῆ δὲ τὸν Καρδιανὸν ἱστορεῖ Δοῦρις πατρὸς μὲν ἁμαξεύοντος ἐν Χερρονήσῳ διὰ πενίαν γενέσθαι, τραφῆναι δὲ ἐλευθερίως ἐν γράμμασι καὶ περὶ παλαίστραν· ἔτι δὲ παιδὸς ὄντος αὐτοῦ Φίλιππον παρεπιδημοῦντα καὶ σχολὴν ἄγοντα τὰ τῶν Καρδιανῶν θεάσασθαι παγκράτια μειρακίων καὶ παλαίσματα παίδων, ἐν οἷς εὐημερήσαντα τὸν Εὐμενῆ καὶ φανέντα συνετὸν καὶ ἀνδρεῖον ἀρέσαι τῷ Φιλίππῳ καὶ ἀναληφθῆναι. δοκοῦσι δὲ εἰκότα λέγειν μᾶλλον οἱ διὰ ξενίαν καὶ φιλίαν πατρῴαν τὸν Εὐμενῆ λέγοντες ὑπὸ τοῦ Φιλίππου προαχθῆναι. μετὰ δὲ τὴν ἐκείνου τελευτὴν οὔτε συνέσει τινὸς οὔτε πίστει λείπεσθαι δοκῶν τῶν περὶ Ἀλέξανδρον ἐκαλεῖτο μὲν ἀρχιγραμματεύς, τιμῆς δὲ ὥσπερ οἱ μάλιστα φίλοι καὶ συνήθεις ἐτύγχανεν, ὥστε καὶ στρατηγὸς ἀποσταλῆναι κατὰ τὴν Ἰνδικὴν ἐφ’ ἑαυτοῦ μετὰ δυνάμεως, καὶ τὴν Περδίκκου παραλαβεῖν ἱππαρχίαν, ὅτε Περδίκκας, ἀποθανόντος Ἡφαιστίωνος, εἰς τὴν ἐκείνου προῆλθε τάξιν. διὸ καὶ Νεοπτολέμου τοῦ ἀρχιυπασπιστοῦ μετὰ τὴν Ἀλεξάνδρου τελευτὴν λέγοντος ὡς αὐτὸς μὲν ἀσπίδα καὶ λόγχην, Εὐμενὴς δὲ γραφεῖον ἔχων καὶ πινακίδιον ἠκολούθει, κατεγέλων οἱ Μακεδόνες, μετὰ τῶν ἄλλων καλῶν τὸν Εὐμενῆ καὶ τῆς κατὰ τὸν γάμον οἰκειότητος ὑπὸ τοῦ βασιλέως εἰδότες ἀξιωθέντα. Βαρσίνην γὰρ τὴν Ἀρταβάζου πρώτην ἐν Ἀσίᾳ γνοὺς ὁ Ἀλέξανδρος, ἐξ ἧς υἱὸν ἔσχεν Ἡρακλέα, τῶν ταύτης ἀδελφῶν Πτολεμαίῳ μὲν Ἀπάμαν, Εὐμενεῖ δὲ Βαρσίνην ἐξέδωκεν, ὅτε καὶ τὰς ἄλλας Περσίδας διένειμε καὶ συνῴκισε τοῖς ἑταίροις.", "st": "Eum. 1.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ προσέκρουσε πολλάκις Ἀλεξάνδρῳ, καὶ παρεκινδύνευσε δι’ Ἡφαιστίωνα, πρῶτον μὲν γὰρ Εὐΐῳ τῷ αὐλητῇ τοῦ Ἡφαιστίωνος οἰκίαν κατανείμαντος ἣν οἱ παῖδες ἔτυχον τῷ Εὐμενεῖ προκατειληφότες, ἐλθὼν ὑπὸ ὀργῆς πρὸς τὸν Ἀλέξανδρον ὁ Εὐμενὴς ἐβόα μετὰ Μέντορος ὡς αὐλεῖν εἴη κράτιστον ἢ τραγῳδεῖν τὰ ὅπλα ῥίψαντας ἐκ τῶν χειρῶν, ὥστε Ἀλέξανδρον αὐτῷ συναγανακτεῖν καὶ λοιδορεῖσθαι τῷ Ἡφαιστίωνι.", "st": "Eum. 2.1"}, {"sp": "N", "t": "ταχὺ μέντοι μεταπεσὼν αὖθις εἶχε τὸν Εὐμενῆ δι’ ὀργῆς, ὡς ὕβρει μᾶλλον πρὸς ἑαυτὸν ἢ παρρησίᾳ πρὸς Ἡφαιστίωνα χρησάμενον. ἔπειτα Νέαρχον ἐκπέμπων μετὰ νεῶν ἐπὶ τὴν ἔξω θάλασσαν ᾔτει χρήματα τοὺς φίλους· οὐ γὰρ ἦν ἐν τῷ βασιλείῳ. τοῦ δ’ Εὐμενοῦς αἰτηθέντος μὲν τριακόσια τάλαντα, δόντος δὲ ἑκατὸν μόνα, καὶ ταῦτα γλίσχρως καὶ μόλις αὐτῷ συνειλέχθαι διὰ τῶν ἐπιτρόπων φάσκοντος, οὐδὲν ἐγκαλέσας οὐδὲ δεξάμενος ἐκέλευσε τοὺς παῖδας κρύφα τῇ σκηνῇ τοῦ Εὐμενοῦς πῦρ ἐνεῖναι, βουλόμενος ἐκκομιζομένων τῶν χρημάτων λαβεῖν ἐπ’ αὐτοφώρῳ ψευδόμενον. ἔφθη δὲ ἡ σκηνὴ καταφλεχθεῖσα, καὶ μετενόησε τῶν γραμμάτων διαφθαρέντων ὁ Ἀλέξανδρος, τὸ δὲ συγχυθὲν χρυσίον καὶ ἀργύριον ὑπὸ τοῦ πυρὸς ἀνευρέθη πλεῖον ἣ χιλίων ταλάντων, ἔλαβε δὲ οὐδέν, ἀλλὰ καὶ γράψας τοῖς πανταχοῦ σατράπαις καὶ στρατηγοῖς ἀντίγραφα τῶν διεφθαρμένων ἀποστέλλειν πάντα παραλαμβάνειν ἐκέλευσε τὸν Εὐμενῆ.", "st": "Eum. 2.2"}, {"sp": "N", "t": "πάλιν δὲ περὶ δωρεᾶς τινος εἰς διαφορὰν καταστὰς πρὸς τὸν Ἡφαιστίωνα, καὶ πολλὰ μὲν ἀκούσας κακῶς, πολλὰ δὲ εἰπών, τότε μὲν οὐκ ἔλαττον ἔσχε· μετ’ ὀλίγον δὲ τελευτήσαντος Ἡφαιστίωνος περιπαθῶν ὁ βασιλεύς καὶ πᾶσιν οὓς ἐδόκει ζῶντι μὲν ἐκείνῳ φθονεῖν ἐπιχαίρειν δὲ τεθνηκότι τραχέως ὁμιλῶν καὶ χαλεπὸς ὢν, μάλιστα τὸν Εὐμενῆ δι’ ὑποψίας εἶχε, καὶ προὔφερε πολλάκις τὰς διαφορὰς καὶ λοιδορίας ἐκείνας. ὁ δὲ πανοῦργος ὢν καὶ πιθανός ἐπεχείρησεν οἷς ἀπώλλυτο σῴζειν ἑαυτόν, κατέφυγε γὰρ εἰς τὴν πρὸς Ἡφαιστίωνα φιλοτιμίαν Ἀλεξάνδρου καὶ χάριν, ὑφηγούμενός τε τιμὰς αἳ μάλιστα κοσμεῖν ἔμελλον τὸν τεθνηκότα, καὶ χρήματα τελῶν εἰς τὴν τοῦ τάφου κατασκευὴν ἀφειδῶς καὶ προθύμως.", "st": "Eum. 2.4"}, {"sp": "N", "t": "ἀποθανόντος δὲ Ἀλεξάνδρου καί τῆς φάλαγγος διεστώσης πρὸς τοὺς ἑταίρους, τῇ μὲν γνώμῃ τούτοις προσένειμεν ἑαυτὸν ὁ Εὐμενής, τῷ δὲ λόγῳ κοινός τις ἦν πρὸς ἀμφοτέρους καί ἰδιώτης, ὡς οὐδὲν αὐτῷ προσῆκον ξένῳ ὄντι πολυπραγμονεῖν ἐν ταῖς Μακεδόνων διαφοραῖς. καί τῶν ἄλλων ἑταίρων ἐκ Βαβυλῶνος ἀνασκευασαμένων αὐτὸς ὑπολειφθεὶς ἐν τῇ πόλει κατεπράϋνε πολλοὺς τῶν πεζῶν καί πρὸς τὰς διαλύσεις ἡδίους ἐποίησεν. ἐπεὶ δὲ ἀναμιχθέντες ἀλλήλοις οἱ στρατηγοὶ καί καταστάντες ἐκ τῶν πρώτων ταραχῶν διενέμοντο σατραπείας καί στρατηγίας, Εὐμενὴς λαμβάνει Καππαδοκίαν καί Παφλαγονίαν καὶ τὴν ὑποκειμένην τῇ Ποντικῇ θαλάττῃ μέχρι Τραπεζοῦντος, οὔπω τότε Μακεδόνων οὖσαν, Ἀριαράθης γὰρ αὐτῆς ἐβασίλευεν, ἀλλ’ ἔδει Λεοννάτον καὶ Ἀντίγονον χειρὶ μεγάλῃ τὸν Εὐμενῆ κατάγοντας ἀποδεῖξαι τῆς χώρας σατράπην.", "st": "Eum. 3.1"}, {"sp": "N", "t": "Ἀντίγονος μὲν οὖν οὐ προσέσχε τοῖς γραφεῖσιν ὑπὸ Περδίκκου, μετέωρος ὢν ἤδη καί περιφρονῶν ἁπάντων, Λεοννάτος δὲ κατέβη μὲν ἄνωθεν εἰς Φρυγίαν ἀναδεξόμενος Εὐμενεῖ τὴν στρατείαν· Ἑκαταίου δὲ τοῦ Καρδιανῶν τυράννου συμμίξαντος αὐτῷ καί δεομένου βοηθεῖν μᾶλλον Ἀντιπάτρῳ καί Μακεδόνων τοῖς ἐν Λαμίᾳ πολιορκουμένοις, ὥρμητο διαβαίνειν καί τὸν Εὐμενῆ παρεκάλει καί διήλλαττε πρὸς τὸν Ἑκαταῖον. ἦν γὰρ αὐτοῖς πατρική τις ἐκ πολιτικῶν διαφορῶν ὑποψία πρὸς ἀλλήλους· καί πολλάκις ὁ Εὐμενὴς ἐγεγόνει φανερὸς κατηγορῶν τοῦ Ἑκαταίου τυραννοῦντος καί παρακαλῶν Ἀλέξανδρον ἀποδοῦναι τοῖς Καρδιανοῖς τὴν ἐλευθερίαν. διὸ καί τότε τοῦ Εὐμενοῦς παραιτουμένου τὴν ἐπὶ τοὺς Ἕλληνας στρατείαν, καὶ δεδιέναι φάσκοντος Ἀντίπατρον, μήπως Ἑκαταίῳ χαριζόμενος καί πάλαι μισῶν αὐτὸν ἀνέλῃ, πιστεύσας ὁ Λεόννατος οὐδὲν ὧν ἐφρόνει πρὸς αὐτὸν ἀπεκρύψατο. λόγος μὲν γὰρ ἦν ἡ βοήθεια καί πρόφασις, ἐγνώκει δὲ διαβὰς εὐθὺς ἀντιποιεῖσθαι Μακεδονίας· καί τινας ἐπιστολὰς ἔδειξε Κλεοπάτρας μεταπεμπομένης αὐτὸν εἰς Πέλλαν ὡς γαμησομένης. ὁ δ’ Εὐμενής, εἴτε τὸν Ἀντίπατρον δεδοικώς εἴτε τὸν Λεοννάτου ἔμπληκτον ὄντα καί φορᾶς μεστὸν ἀβεβαίου καί ὀξείας ἀπογνούς, νύκτωρ ἀνέζευξε τὴν ἑαυτοῦ λαβὼν ἀποσκευήν. εἶχε δὲ τριακοσίους μὲν ἱππεῖς, διακοσίους δὲ τῶν παίδων ὁπλοφόρους, ἐν δὲ χρυσοῖς εἰς ἀργυρίου λόγον τάλαντα πεντακισχίλια. φυγὼν δὲ οὕτως πρὸς Περδίκκαν καί τὰ Λεοννάτου βουλεύματα κατειπών εὐθὺς μὲν ἴσχυε μέγα παρ’ αὐτῷ καί τοῦ συνεδρίου μετεῖχεν, ὀλίγον δὲ ὕστερον εἰς Καππαδοκίαν κατήχθη μετὰ δυνάμεως, αὐτοῦ Περδίκκου παρόντος καί στρατηγοῦντος. Ἀριαράθου δὲ ληφθέντος αἰχμαλώτου καί τῆς χώρας ὑποχειρίου γενομένης ἀποδείκνυται σατράπης. καί τὰς μὲν πόλεις τοῖς ἑαυτοῦ φίλοις παρέδωκε, καί φρουράρχους ἐγκατέστησε καί δικαστὰς ἀπέλιπε καί διοικητὰς οὓς ἐβούλετο, τοῦ Περδίκκου μηδὲν ἐν τούτοις πολυπραγμονοῦντος, αὐτὸς δὲ συνανέζευξεν ἐκεῖνόν τε θεραπεύων καί τῶν βασιλέων ἀπολείπεσθαι μὴ βουλόμενος,", "st": "Eum. 3.3"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὁ Περδίκκας ἐφ’ ἃ μὲν ὥρμητο πιστεύων δι’ αὑτοῦ προσάξεσθαι, τὰ δὲ ὑπολειπόμενα δεῖσθαι δραστηρίου τε καὶ πιστοῦ φύλακος οἰόμενος, ἀπέπεμψεν ἐκ Κιλικίας τὸν Εὐμενῆ, λόγῳ μὲν ἐπὶ τὴν ἑαυτοῦ σατραπείαν, ἔργῳ δὲ τὴν ὅμορον Ἀρμενίαν τεταραγμένην ὑπὸ Νεοπτολέμου διὰ χειρὸς ἕξοντα. τοῦτον μὲν οὖν ὁ Εὐμενής, καίπερ ὄγκῳ τινὶ καὶ φρονήματι κενῷ διεφθαρμένον, ἐπειρᾶτο ταῖς ὁμιλίαις κατέχειν αὐτὸς δὲ τὴν φάλαγγα τῶν Μακεδόνων ἐπηρμένην καὶ θρασεῖαν εὑρών, ὥσπερ ἀντίταγμα κατεσκεύαζεν αὐτῇ δύναμιν ἱππικήν, τῶν μὲν ἐγχωρίων τοῖς ἱππεύειν δυναμένοις ἀνεισφορίας διδοὺς καὶ ἀτελείας, τῶν δὲ περὶ αὑτὸν οἷς μάλιστα ἐπίστευεν ὠνητοὺς διανέμων ἵππους, φιλοτιμίαις τε καὶ δωρεαῖς τὰ φρονήματα παροξύνων καὶ τὰ σώματα κινήσεσι καὶ μελέταις διαπονῶν, ὥστε τοὺς μὲν ἐκπλαγῆναι, τοὺς δὲ θαρρῆσαι τῶν Μακεδόνων, ὁρῶντας ὀλίγῳ χρόνῳ περὶ αὑτὸν ἠθροισμένους ἱππεῖς οὐκ ἐλάττους ἑξακισχιλίων καὶ τριακοσίων.", "st": "Eum. 4.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Κρατερὸς καὶ Ἀντίπατρος τῶν Ἑλλήνων περιγενόμενοι διέβαινον εἰς Ἀσίαν τὴν Περδίκκου καταλύσοντες ἀρχήν, καὶ προσηγγέλλοντο μέλλοντες ἐμβαλεῖν εἰς Καππαδοκίαν, ὁ Περδίκκας αὐτὸς ἐπὶ Πτολεμαῖον στρατεύων ἀπέδειξε τὸν Εὐμενῆ τῶν ἐν Ἀρμενίᾳ, καὶ Καππαδοκίᾳ δυνάμεων αὐτοκράτορα στρατηγόν· καὶ περὶ τούτων ἐπιστολὰς ἔπεμψεν, Ἀλκέταν μὲν καὶ Νεοπτόλεμον Εὐμενεῖ προσέχειν κελεύσας, Εὐμενῆ δὲ χρῆσθαι τοῖς πράγμασιν ὅπως αὐτὸς ἔγνωκεν. Ἀλκέτας μὲν οὖν ἄντικρυς ἀπείπατο τὴν στρατείαν, ὡς τῶν ὑπ’ αὐτῷ Μακεδόνων Ἀντιπάτρῳ μὲν αἰδουμένων μάχεσθαι, Κρατερὸν δὲ καὶ δέχεσθαι δι’ εὔνοιαν ἑτοίμων ὄντων· Νεοπτόλεμος δὲ βουλεύων μὲν ἐπ’ Εὐμενεῖ προδοσίαν οὐκ ἔλαθε, καλούμενος δὲ οὐχ ὑπήκουεν, ἀλλὰ παρέταττε τὴν δύναμιν. ἔνθα πρῶτον ὁ Εὐμενὴς ἀπέλαυσε τῆς ἑαυτοῦ προνοίας καὶ παρασκευῆς· ἡττώμενος γὰρ ἤδη κατὰ τὸ πεζόν ἐτρέψατο τοῖς ἱππεῦσι τὸν Νεοπτόλεμον καὶ τὴν ἀποσκευὴν ἔλαβεν αὐτοῦ, καὶ τῇ φάλαγγι διεσπαρμένῃ περὶ τὴν δίωξιν ἅθρους ἐπελάσας ἠνάγκασε τὰ ὅπλα θέσθαι καὶ δόντας καὶ λαβόντας ὅρκους αὐτῷ συστρατεύειν.", "st": "Eum. 5.1"}, {"sp": "N", "t": "ὁ μὲν οὖν Νεοπτόλεμος ὀλίγους τινὰς συναγαγὼν ἐκ τῆς τροπῆς ἔφυγε πρὸς Κρατερὸν καὶ Ἀντίπατρον. παρ’ ἐκείνων δὲ ἀπέσταλτο πρεσβεία πρὸς Εὐμενῆ παρακαλοῦσα μεταθέσθαι πρὸς αὐτούς, καρπούμενον μὲν ἃς εἶχε σατραπείας, προσλαβόντα δὲ στρατιὰν καὶ χώραν παρ’ αὐτῶν, Ἀντιπάτρῳ μὲν ἀντ’ ἐχθροῦ φίλον γενόμενον, Κρατερῷ δὲ μὴ γενόμενον ἐκ φίλου πολέμιον. ταῦτα ὁ Εὐμενὴς ἀκούσας Ἀντιπάτρῳ μὲν οὐκ ἂν ἔφη παλαιὸς ὢν ἐχθρὸς νῦν γενέσθαι φίλος, ὅτε αὐτὸν ὁρᾷ τοῖς φίλοις ὡς ἐχθροῖς χρώμενον, Κρατερὸν δὲ Περδίκκᾳ διαλλάττειν ἕτοιμος εἶναι καὶ συνάγειν ἐπὶ τοῖς ἴσοις καὶ δικαίοις· ἄρχοντος δὲ πλεονεξίας τῷ ἀδικουμένῳ βοηθήσειν μέχρι ἂν ἐμπνέῃ, καὶ μᾶλλον τὸ σῶμα καὶ τὸν βίον ἢ τὴν πίστιν προήσεσθαι.", "st": "Eum. 5.4"}, {"sp": "N", "t": "οἱ μὲν οὖν περὶ τὸν Ἀντίπατρον πυθόμενοι ταῦτα κατὰ σχολὴν ἐβουλεύοντο περὶ τῶν ὅλων, ὁ Νεοπτόλεμος δὲ μετὰ τήν φυγὴν ἀφικόμενος πρὸς αὐτούς τήν τε μάχην ἀπήγγελλε καὶ παρεκάλει βοηθεῖν, μάλιστα μὲν ἀμφοτέρους, πάντως δὲ Κρατερόν· ποθεῖσθαι γὰρ ὑπερφυῶς ἐκεῖνον ὑπὸ τῶν Μακεδόνων, κἂν μόνον ἴδωσι τήν καυσίαν αὐτοῦ καὶ τήν φωνὴν ἀκούσωσι, μετὰ τῶν ὅπλων ἥξειν φερομένους, καὶ γὰρ ἦν ὄντως ὄνομα τοῦ Κρατεροῦ μέγα, καὶ μετὰ τήν Ἀλεξάνδρου τελευτὴν τοῦτον ἐπόθησαν οἱ πολλοί, μνημονεύοντες ὅτι καὶ πρὸς Ἀλέξανδρον ὑπὲρ αὐτῶν ἀνεδέξατο πολλάκις ἀπεχθείας πολλάς, ὑποφερομένου πρὸς τὸν Περσικὸν ζῆλον ἀντιλαμβανόμενος, καὶ τοῖς πατρίοις ἀμύνων διὰ τρυφὴν καὶ ὄγκον ἤδη περιυβριζομένοις.", "st": "Eum. 6.1"}, {"sp": "N", "t": "τότε δὲ οὖν ὁ Κρατερὸς τὸν μὲν Ἀντίπατρον εἰς Κιλικίαν ἀπέστειλεν, αὐτὸς δὲ τῆς δυνάμεως ἀναλαβὼν πολύ μέρος ἐπὶ τὸν Εὐμενῆ μετὰ τοῦ Νεοπτολέμου προῆγεν, οἰόμενος οὐ προσδεχομένῳ καὶ μετὰ πρόσφατον νίκην ἐν ἀταξίᾳ καὶ περὶ πότους ἔχοντι τήν δύναμιν ἐπιπεσεῖσθαι. τὸ μὲν οὖν προαισθέσθαι τήν ἔφοδον αὐτοῦ τὸν Εὐμενῆ καὶ προπαρασκευάσασθαι νηφούσης ἄν τις ἡγεμονίας, οὐ μὴν ἄκρας θείη δεινότητος· τὸ δὲ μὴ μόνον τοὺς πολεμίους ἃ μὴ καλῶς εἶχεν αἰσθέσθαι διαφυγεῖν, ἀλλὰ καὶ τοὺς μετ’ ἀὐτοῦ στρατευομένους ἀγνοοῦντας ᾧ μαχοῦνται προενσεῖσαι τῷ Κρατερῷ καὶ ἀποκρύψαι τὸν ἀντιστράτηγον, ἴδιον δοκεῖ τούτου τοῦ ἡγεμόνος ἔργον γενέσθαι, διέδωκε μὲν οὖν λόγον ὡς Νεοπτόλεμος αὖθις ἐπίοι καὶ Πίγρης, ἔχοντες ἱππεῖς καὶ Καππαδοκῶν καὶ Παφλαγόνων. νυκτὸς δὲ ἀναζεῦξαι βουλόμενος, εἶτα καταδαρθών ὄψιν εἶδεν ἀλλόκοτον. ἐδόκει γὰρ ὁρᾶν Ἀλεξάνδρους δύο παρασκευαζομένους ἀλλήλοις μάχεσθαι, μιᾶς ἑκάτερον ἡγούμενον φάλαγγος· εἶτα τῷ μὲν τήν Ἀθηνᾶν, τῷ δὲ τήν Δήμητραν βοηθοῦσαν ἐλθεῖν, γενομένου δὲ ἀγῶνος ἰσχυροῦ κρατηθῆναι τὸν μετὰ τῆς Ἀθηνᾶς, τῷ δὲ νικῶντι σταχύων δρεπομένην τήν Δήμητραν συμπλέκειν στέφανον.", "st": "Eum. 6.3"}, {"sp": "N", "t": "αὐτόθεν μὲν οὖν τὴν ὄψιν εἴκαζεν εἶναι πρὸς αὑτοῦ, μαχομένου περὶ γῆς ἀρίστης καὶ τότε πολὺν καὶ καλὸν ἐχούσης ἐν κάλυκι στάχυν ἅπασα γὰρ κατέσπαρτο καὶ παρεῖχεν εἰρήνῃ πρέπουσαν ὄψιν, ἀμφιλαφῶς τῶν πεδίων κομώντων μᾶλλον δὲ ἐπερρώσθη πυθόμενος σύνθημα τοῖς πολεμίοις Ἀθηνᾶν καὶ Ἀλέξανδρον εἶναι, Δήμητραν δὴ καὶ αὐτὸς ἐδίδου σύνθημα καὶ Ἀλέξανδρον, ἀναδεῖσθαί τε πάντας ἐκέλευε καὶ καταστέφειν τὰ ὅπλα τῶν σταχύων λαμβάνοντας. ὁρμήσας δὲ πολλάκις ἐξαγορεῦσαι καὶ φράσαι τοῖς περὶ αὑτὸν ἡγεμόσι καὶ στρατηγοῖς πρὸς ὃν ἔμελλεν ὁ ἀγὼν ἔσεσθαι, καὶ μὴ μόνος ἐν αὑτῷ θέμενος ἀποκρύψαι καὶ κατασχεῖν ἀπόρρητον οὕτως ἀναγκαῖον, ὅμως ἐνέμεινε τοῖς λογισμοῖς καὶ διεπίστευσε τῇ γνώμῃ τὸν κίνδυνον.", "st": "Eum. 6.6"}, {"sp": "N", "t": "ἀντέταξε δὲ Κρατερῷ Μακεδόνων μὲν οὐδένα, δύο δὲ ἱππαρχίας ξενικάς, ὧν Φαρνάβαζος ὁ Ἀρταβάζου καὶ Φοῖνιξ ὁ Τενέδιος ἡγοῦντο, διακελευσάμενος ὀφθέντων τῶν πολεμίων ἐλαύνειν κατὰ τάχος καὶ συμπλέκεσθαι, μὴ διδόντας ἀναστροφὴν μηδὲ φωνὴν, μηδὲ κήρυκα πεμπόμενον προσιεμένους. ἐδεδίει γὰρ ἰσχυρῶς τοὺς Μακεδόνας, μὴ γνωρίσαντες τὸν Κρατερὸν οἴχωνται μεταβαλόμενοι πρὸς ἐκεῖνον. αὐτὸς δὲ τοὺς ἐρρωμενεστάτους ἱππεῖς τριακοσίους εἰς ἄγημα συντάξας καὶ παρελάσας ἐπὶ τὸ δεξιόν ἔμελλε τοῖς περὶ Νεοπτόλεμον ἐπιχειρεῖν. ὡς δὲ τὸν ἐν μέσῳ λόφον ὑπερβαλόντες ὤφθησαν ὀξεῖαν καὶ μεθ’ ὁρμῆς σφοδροτέρας ποιούμενοι τὴν ἔφοδον, ἐκπλαγεὶς ὁ Κρατερὸς καὶ πολλὰ λοιδορήσας τὸν Νεοπτόλεμον ὡς ἐξηπατημένος ὑπ’ αὐτοῦ περὶ τῆς τῶν Μακεδόνων μεταβολῆς, ἐγκελευσάμενος ἀνδραγαθεῖν τοῖς περὶ αὑτὸν ἡγεμόσιν ἀντεξήλασε.", "st": "Eum. 7.1"}, {"sp": "N", "t": "γενομένης δὲ τῆς πρώτης συρράξεως βαρείας καὶ τῶν δοράτων ταχὺ συντριβέντων, τοῦ δὲ ἀγῶνος ἐν τοῖς ξίφεσιν ὄντος, οὐ καταισχύνας ὁ Κρατερὸς τὸν Ἀλέξανδρον, ἀλλὰ πολλοὺς μὲν καταβαλών, πολλάκις δὲ τρεψάμενος τοὺς ἀντιτεταγμένους, τέλος δὲ πληγεὶς ὑπὸ Θρᾳκὸς ἐκ πλαγίων προσελάσαντος ἀπερρύη τοῦ ἵππου. πεσόντα δὲ αὑτὸν οἱ μὲν ἄλλοι παρήλασαν ἀγνοοῦντες, Γοργίας δὲ τῶν Εὐμενοῦς στρατηγῶν ἔγνω τε καὶ καταβὰς περιέστησε φρουρὰν τῷ σώματι κακῶς ἤδη διακειμένου καὶ δυσθανατοῦντος. ἐν τούτῳ δὲ καὶ Νεοπτόλεμος Εὐμενεῖ συνήρχετο. μισοῦντες γὰρ ἀλλήλους πάλαι καὶ δι’ ὀργῆς ἔχοντες ἐν μὲν δυσὶν ἀναστροφαῖς οὐ κατεῖδον, ἐν δὲ τῇ τρίτῃ γνωρίσαντες εὐθὺς ἤλαυνον, σπασάμενοι τὰ ἐγχειρίδια καὶ βοῶντες. τῶν δὲ ἵππων ἐξ ἐναντίας βίᾳ συμπεσόντων ὥσπερ τριήρων, τὰς ἡνίας ἀφέντες ἀλλήλων ἐπεδράξαντο ταῖς χερσί, τά τε κράνη περισπῶντες καὶ περιρρηγνύντες ἐκ τῶν ἐπωμίδων τοὺς θώρακας, πρὸς δὲ τὸν σπαραγμὸν ὑπεκδραμόντων ἅμα τῶν ἵππων, ἀπορρυέντες εἰς γῆν καὶ περιπεσόντες ἀλλήλοις ἐν λαβαῖς ἦσαν καὶ διεπάλαιον. εἶτα ὁ μὲν Εὐμενὴς τοῦ Νεοπτολέμου προεξανισταμένου τὴν ἰγνύαν ὑπέκοψεν αὐτὸς εἰς ὀρθὸν φθάσας καταστῆναι, ὁ δὲ Νεοπτόλεμος εἰς θάτερον ἐρεισάμενος γόνυ, θάτερον δὲ πεπηρωμένος, ἠμύνετο μὲν εὐρώστως κάτωθεν, οὐ θανασίμους δὲ πληγὰς ὑποφέρων, πληγεὶς δὲ παρὰ τὸν τράχηλον ἔπεσε καὶ παρείθη. τοῦ δὲ Εὐμενοῦς δι’ ὀργὴν καὶ μῖσος παλαιὸν τά τε ὅπλα περισπῶντος αὐτοῦ καὶ κακῶς λέγοντος, ἔτι τὸ ξίφος ἔχων ἔλαθεν ὑπὸ τὸν θώρακα τρώσας, ᾗ παρέψαυσε τοῦ βουβῶνος ἀποβάς. ἡ δὲ πληγὴ μᾶλλον ἐφόβησεν ἢ ἔβλαψε τὸν Εὐμενῆ, δι’ ἀσθένειαν ἀμυδρὰ γενομένη.", "st": "Eum. 7.3"}, {"sp": "N", "t": "σκυλεύσας δὲ τὸν νεκρόν εἶχε μὲν χαλεπῶς ὑπὸ τραυμάτων μηροὺς καὶ βραχίονας διακεκομμένος, ὅμως δὲ ἀναβληθεὶς ἐπὶ τὸν ἵππον ἐδίωκε πρὸς θάτερον κέρας, ὡς ἔτι συνεστώτων τῶν πολεμίων. πυθόμενος δὲ τὴν Κρατεροῦ τελευτὴν καὶ προσελάσας, ὡς εἶδεν ἐμπνέοντα καὶ συνιέντα, καταβὰς ἀπεδάκρυσε καὶ τὴν δεξιὰν ἐνέβαλε, καὶ πολλὰ μὲν ἐλοιδόρησε τὸν Νεοπτόλεμον, πολλὰ δὲ ἐκεῖνον μὲν ᾠκτίσατο τῆς τύχης, αὑτὸν δὲ τῆς ἀνάγκης, δι’ ἣν ἀνδρὶ φίλῳ καὶ συνήθει ταῦτα πεισόμενος ἢ δράσων συνηνέχθη.", "st": "Eum. 7.8"}, {"sp": "N", "t": "ταύτην τὴν μάχην Εὐμενὴς ἡμέραις δέκα σχεδόν τι μετὰ τὴν προτέραν ἐνίκησε· καί δόξῃ μὲν ἤρθη μέγας ἀπ’ αὐτῆς, ὡς τὰ μὲν σοφίᾳ, τὰ δὲ ἀνδρείᾳ κατειργασμένος, φθόνον δὲ πολὺν ἔσχε καί μῖσος ὁμαλῶς παρά τε τοῖς συμμάχοις καί τοῖς πολεμίοις, ὡς ἔπηλυς ἀνὴρ καί ξένος ὅπλοις καί χερσὶ τῶν Μακεδόνων τὸν πρῶτον αὐτῶν καί δοκιμώτατον ἀνῃρηκώς. ἀλλ’ εἰ μὲν ἔφθη Περδίκκας πυθόμενος τὴν Κρατεροῦ τελευτήν, οὐκ ἂν ἄλλος ἐπρώτευσε Μακεδόνων νυνὶ δὲ ἀνῃρημένου Περδίκκου κατὰ στάσιν ἐν Αἰγύπτῳ δυσὶν ἡμέραις πρότερον ἧκεν οὗτος ὁ περὶ τῆς μάχης λόγος εἰς τὸ στρατόπεδον, καί πρὸς ὀργὴν εὐθὺς οἱ Μακεδόνες θάνατον τοῦ Εὐμενοῦς κατέγνωσαν. ἀπεδείχθη δὲ τοῦ πολέμου τοῦ πρὸς αὐτὸν Ἀντίγονος μετὰ Ἀντιπάτρου στρατηγός.", "st": "Eum. 8.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Εὐμένης τοῖς βασιλικοῖς ἱπποφορβίοις περὶ τὴν Ἴδην νεμομένοις ἐπιτυχὼν καί λαβὼν ἵππους ὅσων ἔχρῃζε τοῖς ἐπιμεληταῖς τὴν γραφὴν ἔπεμψε, λέγεται γελάσαι τὸν Ἀντίπατρον καί εἰπεῖν ὅτι θαυμάζει τὸν Εὐμενῆ τῆς προνοίας, ἐλπίζοντα λόγον αὐτοῖς ἀποδώσειν τῶν βασιλικῶν ἢ λήψεσθαι παρ’ αὐτῶν. περὶ δὲ τὰς Σάρδεις ἐβούλετο μὲν ἱπποκρατῶν ὁ Εὐμένης τοῖς Λυδοῖς ἐναγωνίσασθαι πεδίοις, ἅμα καί τῇ Κλεοπάτρᾳ τὴν δύναμιν ἐπιδεῖξαι φιλοτιμούμενος· αὐτῆς δὲ ἐκείνης δεηθείσης ἐφοβεῖτο γὰρ αἰτίαν τινὰ λαβεῖν ὑπὸ τῶν Περὶ τὸν Ἀντίπατρον ἐξήλασεν εἰς τὴν ἄνω Φρυγίαν καί διεχείμαζεν ἐν Κελαιναῖς· ὅπου τῶν μὲν περὶ τὸν Ἀλκέταν καί Πολέμωνα καί Δόκιμον ὑπὲρ ἡγεμονίας διαφιλοτιμουμένων πρὸς αὐτόν, τοῦτο ἦν, ἔφη, τὸ λεγόμενον, ὀλέθρου δὲ οὐθεὶς λόγος. τοῖς δὲ στρατιώταις ὑποσχόμενος ἐν τρισὶν ἡμέραις τὸν μισθὸν ἀποδώσειν ἐπίπρασκεν ἐν αὐτοῖς τὰς κατὰ τὴν χώραν ἐπαύλεις καί τετραπυργίας σωμάτων καί βοσκημάτων γεμούσας. ὁ δὲ πριάμενος ἡγεμὼν τάγματος ἢ ξεναγός ὄργανα καί μηχανὰς τοῦ Εὐμένους παρέχοντος ἐξεπολιόρκει· καί πρὸς τὸν ὀφειλόμενον μισθὸν οἱ στρατιῶται διενέμοντο τῶν ἁλισκομένων ἕκαστον. ἐκ δὴ τούτου πάλιν ὁ Εὐμένης ἠγαπᾶτο καί ποτε γραμμάτων ἐν τῷ στρατοπέδῳ φανέντων ἃ διέρριψαν οἱ τῶν πολεμίων ἡγεμόνες, ἑκατὸν τάλαντα καί τιμὰς διδόντες τῷ κτείναντι τὸν Εὐμενῆ, σφόδρα παρωξύνθησαν οἱ Μακεδόνες, καί δόγμα ποιοῦνται χιλίους τῶν ἡγεμονικῶν Περὶ αὐτὸν ἀεὶ δορυφοροῦντας εἶναι καί φυλάττειν ἐν περιόδῳ καί παρανυκτερεύειν. οἱ δὲ ἐπείθοντο, καὶ τιμὰς ἠγάπων παρ’ αὐτοῦ λαμβάνοντες ἃς οἱ φίλοι παρά τῶν βασιλέων, ἐξῆν γὰρ Εὐμενεῖ καί καυσίας ἁλουργεῖς καί χλαμύδας διανέμειν, ἥτις ἦν δωρεὰ βασιλικωτάτη παρά Μακεδόσι.", "st": "Eum. 8.3"}, {"sp": "N", "t": "τὸ μὲν οὖν εὐτυχεῖν καὶ τοὺς φύσει μικροὺς συνεπικουφίζει τοῖς φρονήμασιν, ὥστε φαίνεσθαί τι μέγεθος περὶ αὑτοὺς καὶ ὄγκον ἐκ πραγμάτων ὑπερεχόντων ἀποβλεπομένους· ὁ δὲ ἀληθῶς μεγαλόφρων καὶ βέβαιος ἐν τοῖς σφάλμασι μᾶλλον καὶ ταῖς δυσημερίαις ἀναφέρων γίνεται κατάδηλος, ὥσπερ Εὐμενής. πρῶτον μὲν γὰρ ἐν Ὀρκυνίοις τῆς Καππαδοκίας ἡττηθεὶς ὑπὸ Ἀντιγόνου διὰ προδοσίας καὶ διωκόμενος οὺ παρῆκε τὸν προδότην ἐκ τῆς φυγῆς διαπεσεῖν πρὸς τοὺς πολεμίους, ἀλλὰ συλλαβὼν ἐκρέμασε. φεύγων δὲ τὴν ἐναντίαν ὁδὸν τοῖς διώκουσι μετέβαλε λαθὼν, καὶ παραλλάξας, ὡς ἦλθεν ἐπὶ τὸν τόπον οὗ τὴν μάχην συνέβη γενέσθαι, κατεστρατοπέδευσε, καὶ συναγαγὼν τοὺς νεκροὺς καὶ τῶν ἐν κύκλῳ κωμῶν τὰ θυρώματα κατασχίσας ἔκαυσεν ἰδίᾳ μὲν ἡγεμόνας, ἰδίᾳ δὲ τοὺς πολλούς, καὶ πολυάνδρια χώσας ἀπῆλθεν, ὥστε καὶ τὸν Ἀντίγονον ὕστερον ἐπελθόντα θαυμάζειν τὸ θάρσος αὐτοῦ καὶ τὴν εὐστάθειαν.", "st": "Eum. 9.1"}, {"sp": "N", "t": "ἔπειτα ταῖς ἀποσκευαῖς τοῦ Ἀντιγόνου περιπεσών, καὶ λαβεῖν ῥᾳδίως δυνάμενος πολλὰ μὲν ἐλεύθερα σώματα, πολλὴν δὲ θεραπείαν καὶ πλοῦτον ἐκ πολέμων τοσούτων καὶ λεηλασιῶν ἠθροισμένον, ἔδεισε μὴ καταπλησθέντες ὠφελείας καὶ λαφύρων οἱ σὺν αὐτῷ βαρεῖς γένωνται πρὸς τὴν φυγὴν, καὶ μαλακώτεροι τὰς πλάνας ὑπομένειν καὶ τὸν χρόνον, ἐν ὦ μάλιστα τοῦ πολέμου τὰς ἐλπίδας εἶχεν, ὡς ἀποστρέψων τὸν Ἀντίγονον. ἐπεὶ δὲ ἄντικρυς χαλεπὸν ἦν ἀποτρέπειν Μακεδόνας χρημάτων ἐν ἐφικτῷ παρόντων, ἐκέλευσε θεραπεύσαντας αὑτοὺς καὶ τοῖς ἵπποις χιλὸν ἐμβαλόντας οὕτω βαδίζειν ἐπὶ τοὺς πολεμίους, αὐτὸς δὲ πέμπει κρύφα πρὸς τὸν ἐπὶ τῆς ἀποσκευῆς τῶν πολεμίων Μένανδρον, ὡς κηδόμενος αὐτοῦ φίλου γεγονότος καὶ συνήθους, φυλάξασθαι παραινῶν καὶ ἀναχωρῆσαι τὴν ταχίστην ἐκ τῶν ἐπιδρόμων καὶ ταπεινῶν πρὸς τὴν ἐγγὺς ὑπώρειαν ἄφιππον οὖσαν καὶ κυκλώσεις οὐκ ἔχουσαν. τοῦ δὲ Μενάνδρου ταχὺ συμφρονήσαντος τὸν κίνδυνον καὶ ἀνασκευασαμένου, κατασκόπους ἔπεμπεν ὁ Εὐμενὴς φανερῶς, καὶ παρήγγειλε τοῖς στρατιώταις ὁπλίζεσθαι καὶ τοὺς ἵππους ἐγχαλινοῦν ὡς προσάξων τοῖς πολεμίοις. τῶν δὲ κατασκόπων ἀπαγγειλάντων ὅτι παντάπασιν ὁ Μένανδρος ἄληπτος εἴη καταπεφευγὼς εἰς τόπους χαλεπούς, ἄχθεσθαι προσποιούμενος ὁ Εὐμενὴς ἀπῆγε τὴν στρατιάν. λέγεται δέ, τοῦ Μενάνδρου ταῦτα μαρτυρήσαντος πρὸς τὸν Ἀντίγονον, καὶ τῶν Μακεδόνων ἐπαινούντων τὸν Εὐμενῆ καὶ φιλανθρωπότερον διατεθέντων, ὅτι καὶ παῖδας αὐτῶν ἀνδραποδίσασθαι καὶ γυναῖκας αἰσχῦναι παρόν ἐφείσατο καὶ παρῆκεν, ἄλλ’ ἐκεῖνός γε, φάναι τὸν Ἀντίγονον, οὐχ ὑμῶν, ὦ μακάριοι, κηδόμενος παρῆκεν, ἀλλ’ αὑτῷ φεύγοντι δεδιὼς περιθεῖναι πέδας τοσαύτας.", "st": "Eum. 9.3"}, {"sp": "N", "t": "ἐκ τούτου πλανώμενος ὁ Εὐμενὴς καὶ ὑποφεύγων ἔπεισε τοὺς πολλοὺς τῶν στρατιωτῶν ἀπελθεῖν, εἴτε κηδόμενος αὐτῶν εἴτε ἐφέλκεσθαι μή βουλόμενος ἐλάττονας μὲν τοῦ μάχεσθαι, πλείονας δὲ τοῦ λανθάνειν ὄντας, καταφυγὼν δὲ εἰς Νῶρα, χωρίον ἐν μεθορίῳ Λυκαονίας καὶ Καππαδοκίας, μετὰ πεντακοσίων ἱππέων καὶ διακοσίων ὁπλιτῶν, κἀντεῦθεν αὖθις, ὅσοι τῶν φίλων ἐδεήθησαν ἀφεθῆναι τοῦ χωρίου τὴν χαλεπότητα καὶ τῆς διαίτης τὴν ἀνάγκην οὐ φέροντες, πάντας ἀσπασάμενος καὶ φιλοφρονηθεὶς ἀπέπεμψεν. ὡς δὲ ἐπελθὼν ὁ Ἀντίγονος εἰς λόγους αὐτόν ἐκάλει πρὸ τῆς πολιορκίας, ἀπεκρίνατο πολλοὺς εἶναι τοὺς Ἀντιγόνου φίλους καὶ μετὰ Ἀντίγονον ἡγεμόνας, ὧν δὲ αὐτὸς προπολεμεῖ μηδένα λείπεσθαι μετ’ αὐτόν· ὁμήρους δὲ πέμπειν ἐκέλευσεν, εἰ χρῄζει διὰ λόγων αὐτῷ γενέσθαι, τοῦ δὲ Ἀντιγόνου κελεύοντος ὡς κρείττονι λαλεῖν, οὐδένα, εἶπεν, ἐμαυτοῦ κρείττονα νομίζω, μέχρι ἂν ὦ τοῦ ξίφους κύριος. ὅμως δὲ πέμψαντος τοῦ Ἀντιγόνου τὸν ἀδελφιδοῦν Πτολεμαῖον εἰς τὸ χωρίον, ὥσπερ ἠξίωσεν ὁ Εὐμενής, κατέβη, καὶ περιβαλόντες ἀλλήλους ἠσπάσαντο φιλικῶς καὶ οἰκείως, ἅτε δὴ ἀλλήλοις κεχρημένοι πολλὰ καὶ συνήθεις γεγονότες. λόγων δὲ γενομένων πολλῶν καὶ τοῦ Εὐμενοῦς οὐχ ὑπὲρ ἀσφαλείας μεμνημένου καὶ διαλύσεως, ἀλλὰ καὶ τὰς σατραπείας ἀξιοῦντος αὑτῷ βεβαιοῦσθαι καὶ τὰς δωρεὰς ἀποδίδοσθαι, θαῦμα τοὺς παρόντας εἶχε τὸ φρόνημα καὶ τὴν εὐτολμίαν ἀγαμένους. ἅμα δὲ πολλοὶ συνέτρεχον τῶν Μακεδόνων ἰδεῖν ὅστις ἐστὶ τὸν Εὐμενῆ ποθοῦντες· οὐ γὰρ ἑτέρου λόγος ἦν τοσοῦτος ἐν τῷ στρατῷ μετὰ τὴν τοῦ Κρατεροῦ τελευτήν. δείσας δὲ ὁ Ἀντίγονος ὑπὲρ αὐτοῦ, μή τι πάθῃ βίαιον, πρῶτον μὲν ἀπηγόρευε μή προσιέναι βοῶν, καὶ τοῖς λίθοις ἔβαλλε τοὺς ἐπιφερομένους, τέλος δὲ ταῖς χερσὶ τὸν Εὐμενῆ περιβαλὼν καὶ τὸν ὄχλον ἀπερύκων τοῖς δορυφόροις μόλις εἰς τὸ ἀσφαλὲς ἀποκατέστησε.", "st": "Eum. 10.1"}, {"sp": "N", "t": "τοὐντεῦθεν ὁ μὲν περιτειχίσας τὰ Νῶρα καὶ φρουρὰν καταλιπών ἀνέζευξεν Εὐμενὴς δὲ πολιορκούμενος ἐγκρατῶς, τοῦ χωρίου σῖτον καὶ ὕδωρ ἄφθονον καὶ ἅλας καὶ ἄλλο μηδὲν ἔχοντος ἐδώδιμον μηδὲ ἥδυσμα πρὸς τὸν σῖτον, ἐκ τῶν παρόντων ὅμως κατεσκεύαζε τοῖς συνοῦσιν ἱλαρὰν τὴν δίαιταν, ἐν μέρει τε παραλαμβάνων πάντας ἐπὶ τὴν αὑτοῦ τράπεζαν, καὶ τὸ συσσίτιον ὁμιλίᾳ χάριν ἐχούσῃ καὶ φιλοφροσύνην ἐφηδύνων. ἦν δὲ καὶ τὸ εἶδος ἡδύς, οὐ πολεμικῷ καὶ τετριμμένῳ δι’ ὅπλων ἐοικώς, ἀλλὰ γλαφυρὸς καὶ νεοπρεπὴς, καὶ πᾶν τὸ σῶμα διηρθρωμένος ὡς ὑπὸ τέχνης ἀκριβῶς τοῖς μέλεσι θαυμαστὴν συμμετρίαν ἔχουσιν, εἰπεῖν δὲ οὐ δεινός, αἱμύλος δὲ καὶ πιθανός, ὡς ἐκ τῶν ἐπιστολῶν συμβάλλειν ἐστίν.", "st": "Eum. 11.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τοὺς σὺν αὐτῷ πολιορκουμένους ἡ στενοχωρία μάλιστα πάντων ἔβλαπτεν, ἐν οἰκήμασι μικροῖς καὶ τόπῳ δυοῖν σταδίοιν ἔχοντι τὴν περίμετρον ἀναστρεφομένους, τροφὴν δὲ ἀγυμνάστους μὲν αὐτοὺς λαμβάνοντας, ἀργοῖς δὲ τοῖς ἵπποις προσφέροντας, οὐ μόνον τὸν ἄλυν αὐτῶν ὑπὸ τῆς ἀπραξίας μαραινομένων ἀπαλλάξαι βουλόμενος, ἀλλὰ καὶ πρὸς φυγήν, εἰ παραπέσοι καιρός, ἁμῶς γέ πως ἠσκημένοις χρήσασθαι, τοῖς μὲν ἀνθρώποις οἶκον, ὃς ἦν μέγιστος ἐν τῷ χωρίῳ, δεκατεσσάρων πηχῶν τὸ μῆκος, ἀπέδειξε περίπατον, κατὰ μικρὸν ἐπιτείνειν τὴν κίνησιν κελεύων, τῶν δὲ ἵππων ἕκαστον ῥυτῆρσι μεγάλοις εἰς τὴν ὀροφὴν ἀναδεδεμένοις ὑποζώσας ἐκ τῶν περὶ τὸν αὐχένα μερῶν ἐμετεώριζε καὶ παρήγειρε διὰ τροχιλίας, ὥστε τοῖς μὲν ὀπισθίοις σκέλεσιν ἐπὶ τῆς γῆς ἐρείδεσθαι, τοῖς δὲ ἐμπροσθίοις ποσὶν ἀκρωνύχους ἐπιψαύειν. οὕτω δὲ ἀνηρτημένους οἱ ἱπποκόμοι παρεστῶτες ἅμα ταῖς τε κραυγαῖς καὶ ταῖς μάστιξιν ἐπηρέθιζον οἱ δὲ πιμπλάμενοι θυμοῦ καὶ ὀργῆς τοῖς μὲν ὀπισθίοις ἐνήλλοντο καὶ διεσκίρτων σκέλεσι, τοῖς δὲ μετεώροις ἐφιέμενοι στηρίξασθαι καὶ κροτοῦντες τὸ ἔδαφος κατετείνοντο πᾶν τὸ σῶμα καὶ πολὺν ἠφίεσαν ἱδρῶτα καὶ σταλαγμόν, οὔτε πρὸς τάχος οὔτε πρὸς ῥώμην γυμναζόμενοι κακῶς, τὰς δὲ κριθὰς ἐνέβαλλον αὐτοῖς ἐπτισμένας, ἵνα κατεργάζωνται θᾶττον καὶ πέττωσι βέλτιον.", "st": "Eum. 11.3"}, {"sp": "N", "t": "ἤδη δὲ τῆς πολιορκίας χρόνον λαμβανούσης Ἀντίγονος τεθνηκέναι πυνθανόμενος Ἀντίπατρον ἐν Μακεδονίᾳ, καὶ τεταράχθαι τὰ πράγματα Κασάνδρου καὶ Πολυσπέρχοντος διαφερομένων, οὐδὲν ἔτι μικρὸν ἐλπίζων, ἀλλὰ τῇ γνώμῃ τὴν ὅλην περιβαλλόμενος ἡγεμονίαν· ἐβούλετο τὸν Εὐμενῆ φίλον ἔχειν καὶ συνεργὸν ἐπὶ τὰς πράξεις, διὸ πέμψας Ἱερώνυμον ἐσπένδετο τῷ Εὐμενεῖ, προτείνας ὅρκον, ὃν ὁ Εὐμενὴς διορθώσας ἐπέτρεψεν ἐπικρῖναι τοῖς πολιορκοῦσιν αὐτὸν Μακεδόσι, πότερος εἴη δικαιότερος. Ἀντίγονος μὲν γὰρ ἀφοσιώσεως ἕνεκεν ἐν ἀρχῇ τῶν βασιλέων ἐπιμνησθείς τὸν λοιπὸν ὅρκον εἰς ἑαυτὸν ὥρκιζεν, Εὐμένης δὲ πρώτην μὲν ἐνέγραψε τοῖς ὅρκοις Ὀλυμπιάδα μετὰ τῶν βασιλέων, ἔπειτα ὤμνυεν οὐκ Ἀντιγόνῳ μόνον εὐνοήσειν οὐδ’ ἐκείνῳ τὸν αὐτὸν ἐχθρὸν ἕξειν καὶ φίλον, ἀλλὰ καὶ Ὀλυμπιάδι καὶ τοῖς βασιλεῦσιν. ὧν δικαιοτέρων φανέντων, οἱ Μακεδόνες ταῦθ’ ὁρκίσαντες τὸν Εὐμενῆ τὴν πολιορκίαν ἔλυσαν, καὶ πρὸς τὸν Ἀντίγονον ἀπέστελλον, ὅπως καὶ αὐτὸς ἀποδῷ τῷ Εὐμενεῖ τὸν ὅρκον.", "st": "Eum. 12.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Εὐμενὴς ὅσους εἶχεν ἐν Νώροις τῶν Καππαδοκῶν ὁμήρους ἀπεδίδου, λαμβάνων ἵππους καὶ ὑποζύγια καὶ σκηνὰς παρὰ τῶν κομιζομένων, καὶ συνῆγε τῶν στρατιωτῶν ὅσοι διασπαρέντες ἀπὸ τῆς φυγῆς ἐπλανῶντο κατὰ τὴν χώραν, ὥστε περὶ αὐτὸν ἱππεῖς ὀλίγῳ τῶν χιλίων ἀποδέοντας γενέσθαι, μεθ’ ὧν ἐξελάσας ἔφυγεν, ὀρθῶς φοβηθεὶς τὸν Ἀντίγονον. οὐ γὰρ μόνον ἐκεῖνον ἐκέλευσε πολιορκεῖν αὖθις περιτειχίσαντας, ἀλλὰ καὶ τοῖς Μακεδόσι πικρῶς ἀντέγραψε δεξαμένοις τοῦ ὅρκου τὴν διόρθωσιν.", "st": "Eum. 12.3"}, {"sp": "N", "t": "φεύγοντι δὲ Εὐμενεῖ γράμματα κομίζεται παρὰ τῶν ἐν Μακεδονίᾳ τὴν Ἀντιγόνου δεδοικότων αὔξησιν, Ὀλυμπιάδος μὲν παρακαλούσης ἐλθόντα τὸ Ἀλεξάνδρου παιδίον παραλαβεῖν καὶ τρέφειν ὡς ἐπιβουλευόμενον, Πολυσπέρχοντος δὲ καὶ Φιλίππου τοῦ βασιλέως κελευόντων Ἀντιγόνῳ πολεμεῖν τῆς ἐν Καππαδοκίᾳ δυνάμεως ἄρχοντα, καὶ τῶν ἐν Κουΐνδοις χρημάτων πεντακόσια μὲν τάλαντα λαβεῖν εἰς τὴν τῶν ἰδίων ἐπανόρθωσιν, εἰς δὲ τὸν πόλεμον ὁπόσοις βούλεται χρῆσθαι. περὶ δὲ τούτων καὶ Ἀντιγένει καὶ Τευτάμῳ τοῖς τῶν ἀργυρασπίδων ἡγουμένοις ἐγεγράφεισαν. ἐπεὶ δὲ λαβόντες ἐκεῖνοι τὰ γράμματα τῷ μὲν λόγῳ φιλανθρώπως ἐδέξαντο τὸν Εὐμενῆ, φθόνου δὲ καὶ φιλονεικίας ἐφαίνοντο μεστοί, δευτερεύειν ἀπαξιοῦντες ἐκείνῳ, τὸν μὲν φθόνον ὁ Εὐμενὴς ἐθεράπευε τῷ τὰ χρήματα μὴ λαβεῖν ὡς οὐδὲν δεόμενος, ταῖς δὲ φιλονεικίαις καὶ φιλαρχίαις αὐτῶν μήτε ἡγεῖσθαι δυναμένων μήτε ἕπεσθαι βουλομένων ἐπῆγε δεισιδαιμονίαν.", "st": "Eum. 13.1"}, {"sp": "N", "t": "ἔφη γὰρ Ἀλέξανδρον αὐτῷ κατὰ τοὺς ὕπνους φανῆναι, καὶ δεῖξαί τινα σκηνὴν κατεσκευασμένην βασιλικῶς καὶ θρόνον ἐν αὐτῇ κείμενον· εἶτα εἰπεῖν ὡς ἐνταῦθα συνεδρεύουσιν αὐτοῖς καὶ χρηματίζουσιν αὐτὸς παρέσται καὶ συνεφάψεται βουλῆς τε πάσης καὶ πράξεως ἀρχομένοις ἀπ’ αὐτοῦ, ταῦτα ῥᾳδίως ἔπεισε τὸν Ἀντιγένη καὶ τὸν Τεύταμον, οὔτε ἐκείνων βαδίζειν βουλομένων πρὸς αὐτόν, οὔτε αὐτὸς ἀξιῶν ἐπὶ θύραις ἑτέρων ὁρᾶσθαι. καὶ τιθέντες οὕτω σκηνὴν βασιλικὴν καὶ θρόνον Ἀλεξάνδρῳ καταπεφημισμένον ἐκεῖ συνεπορεύοντο βουλευόμενοι περὶ τῶν μεγίστων.", "st": "Eum. 13.4"}, {"sp": "N", "t": "ἐπεὶ δὲ προϊοῦσιν αὐτοῖς εἰς τὴν ἄνω χώραν ὁ Πευκέστας μετὰ τῶν ἄλλων σατραπῶν ἀπήντησε φίλος ὢν καὶ συνεμίξαντο τὰς δυνάμεις, πλήθει μὲν ὅπλων καὶ λαμπρότητι παρασκευῆς ἐπέρρωσαν τοὺς Μακεδόνας, αὐτοὶ δὲ ἀνάγωγοι ταῖς ἐξουσίαις καὶ μαλακοὶ ταῖς διαίταις γεγονότες μετὰ τὴν Ἀλεξάνδρου τελευτήν, καὶ φρονήματα τυραννικὰ καὶ τεθραμμένα βαρβαρικαῖς ἀλαζονείαις ἐπὶ ταὐτὸ συνενεγκάμενοι, πρὸς μὲν ἀλλήλους βαρεῖς ἦσαν καὶ δυσάρμοστοι, τοὺς δὲ Μακεδόνας κολακεύοντες ἐκκεχυμένως καὶ καταχορηγοῦντες εἰς δεῖπνα καὶ θυσίας ὀλίγου χρόνου τὸ στρατόπεδον ἀσωτίας πανηγυριζούσης καταγώγιον ἐποίησαν καὶ δημαγωγούμενον ἐπὶ αἱρέσει στρατηγῶν ὄχλον, ὥσπερ ἐν ταῖς δημοκρατίαις. αἰσθόμενος δὲ ὁ Εὐμενὴς αὐτοὺς ἀλλήλων μὲν καταφρονοῦντας, αὐτὸν δὲ φοβουμένους καὶ παραφυλάττοντας ἀνελεῖν, εἰ γένοιτο καιρός, ἐσκήψατο χρημάτων δεῖσθαι καὶ συνεδανείσατο τάλαντα πολλὰ παρὰ τῶν μάλιστα μισούντων αὐτόν, ἵνα καὶ πιστεύωσι καὶ ἀπέχωνται περὶ τῶν δανείων ἀγωνιῶντες· ὥστε συνέβη τὸν ἀλλότριον πλοῦτον αὐτῷ φύλακα τοῦ σώματος ἔχειν, καὶ τῶν ἄλλων ἐπὶ σωτηρίᾳ διδόντων, μόνον ἐκ τοῦ λαβεῖν κτήσασθαι τὴν ἀσφάλειαν.", "st": "Eum. 13.5"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ οἱ Μακεδόνες ἀδείας μὲν οὔσης ἐφθείροντο πρὸς τοὺς διδόντας, καὶ τάς ἐκείνων θύρας ἐθεράπευον, δορυφορουμένων καὶ στρατηγιώντων· ἐπεὶ δὲ Ἀντίγονος αὑτοῖς παρεστρατοπέδευσε μετὰ πολλῆς δυνάμεως καὶ τὰ πράγματα φωνὴν ἀφιέντα τὸν ἀληθινὸν ἐκάλει στρατηγόν, οὐ μόνον οἱ στρατευόμενοι τῷ Εὐμενεῖ προσεῖχον, ἀλλὰ καὶ τῶν ἐν εἰρήνῃ καὶ τρυφῇ μεγάλων ἐκείνων ἕκαστος ἐνέδωκε καὶ παρεῖχεν ἑαυτὸν σιωπῇ τὴν δοθεῖσαν φυλάττοντα τάξιν. καὶ γάρ τοι περὶ τὸν Πασιτίγριν ποταμὸν ἐπιχειρήσαντα διαβαίνειν τὸν Ἀντίγονον οἱ μὲν ἄλλοι παραφυλάττοντες οὐδὲ ᾔσθοντο, μόνος δὲ Εὐμενὴς ὑπέστη, καὶ συνάψας μάχην πολλοὺς μὲν κατέβαλε καὶ νεκρῶν ἐνέπλησε τὸ ῥεῖθρον, ἔλαβε δὲ τετρακισχιλίους αἰχμαλώτους, μάλιστα δὲ οἱ Μακεδόνες περὶ τὴν συμβᾶσαν ἀρρωστίαν αὐτῷ καταφανεῖς ἐγένοντο τοὺς μὲν ἄλλους ἑστιᾶν λαμπρῶς καὶ πανηγυρίζειν, ἄρχειν δὲ καὶ πολεμεῖν δυνατὸν ἡγούμενοι μόνον ἐκεῖνον. ὁ μὲν γὰρ Πευκέστας ἐν τῇ Περσίδι λαμπρῶς αὐτοὺς ἑστιάσας καὶ κατ’ ἄνδρα διαδοὺς ἱερεῖον εἰς θυσίαν ἤλπιζεν εἶναι μέγιστος· ὀλίγαις δὲ ὕστερον ἡμέραις τῶν στρατιωτῶν ἐπὶ τοὺς πολεμίους βαδιζόντων, ἐτύγχανεν ὁ Εὐμενὴς ἐκ νόσου τινὸς ἐπισφαλοῦς ἐν φορείῳ κομιζόμενος ἔξω τοῦ στρατεύματος ἐν ἡσυχίᾳ διὰ τάς ἀγρυπνίας. μικρὸν δὲ προελθοῦσιν αὐτοῖς ἄφνω λόφους τινὰς ὑπερβάλλοντες ἐξεφάνησαν οἱ πολέμιοι, καταβαίνοντες εἰς τὸ πεδίον. ὡς οὖν αἵ τε τῶν χρυσῶν ὅπλων αὐγαὶ πρὸς τὸν ἥλιον ἐξέλαμψαν ἀπὸ τῶν ἄκρων τοῦ ἀγήματος ἐν τάξει πορευομένων, καὶ τῶν θηρίων τοὺς πύργους ἄνω καὶ τάς πορφύρας εἶδον, ὅσπερ ἦν αὐτοῖς κόσμος εἰς μάχην ἀγομένοις, ἐπιστήσαντες οἱ πρῶτοι τὴν πορείαν ἐβόων Εὐμενῆ καλεῖν αὑτοῖς, οὐ γὰρ ἂν προελθεῖν ἐκείνου μὴ στρατηγοῦντος, καὶ τὰ ὅπλα πρὸς τὴν γῆν ἐρείσαντες ἀλλήλοις μένειν διεκελεύοντο, καὶ τοῖς ἡγεμόσιν ἡσυχίαν ἔχειν, καὶ χωρὶς Εὐμενοῦς μὴ μάχεσθαι μηδὲ κινδυνεύειν πρὸς τοὺς πολεμίους. ἀκούσας δὲ ὁ Εὐμενὴς ἧκε πρὸς αὐτοὺς δρόμῳ τοὺς κομίζοντας ἐπιταχύνας, καὶ τοῦ φορείου τάς ἑκατέρωθεν αὐλαίας ἀνακαλύψας προὔτεινε τὴν δεξιὰν γεγηθώς. οἱ δὲ ὡς εἶδον, εὐθὺς ἀσπασάμενοι Μακεδονιστὶ τῇ φωνῇ τάς τε ἀσπίδας ἀνείλοντο καὶ ταῖς σαρίσαις ἐπιδουπήσαντες ἠλάλαξαν, προκαλούμενοι τοὺς πολεμίους ὠς τοῦ ἡγεμόνος αὐτοῖς παρόντος.", "st": "Eum. 14.1"}, {"sp": "N", "t": "Ἀντίγονος δὲ παρὰ τῶν ἁλισκομένων ἀκούων τὸν Εὐμενῆ νοσεῖν καὶ κομίζεσθαι κακῶς διακείμενον, οὐ μέγα ἔργον ἡγεῖτο συντρῖψαι τοὺς ἄλλους ἐκείνου νοσοῦντος. διὸ καὶ σπεύδων ἐπὶ τὴν μάχην προσῆγεν. ὡς δὲ τῶν πολεμίων εἰς τάξιν καθισταμένων παρελάσας κατεῖδε τὸ σχῆμα καὶ τὴν διακόσμησιν, ἐκπλαγεὶς ἐπέστη πλείω χρόνον εἶτα ὤφθη τὸ φορεῖον ἀπὸ θατέρου κέρως ἐπὶ θάτερον διαφερόμενον. γελάσας οὖν ὁ Ἀντίγονος, ὥσπερ εἰώθει, μέγα, καὶ πρὸς τοὺς φίλους εἰπὼν, τοῦτο ἦν τὸ φορεῖον, ὡς ἔοικε, τὸ ἀντιπαραταττόμενον ἡμῖν, εὐθὺς ἀπῆγε τὴν δύναμιν ὀπίσω καὶ κατεστρατοπέδευσεν.", "st": "Eum. 15.1"}, {"sp": "N", "t": "οἱ δὲ μικρὸν ἀναπνεύσαντες αὖθις ἐδημαγωγοῦντο, καὶ τοῖς ἡγεμόσιν ἐντρυφῶντες σχεδὸν ὅλην εἰς τὰ χειμάδια κατενείμαντο τὴν Γαβηνῶν, ὥστε τοὺς ἐσχάτους τῶν πρώτων ἀποσκηνοῦν ὁμοῦ τι χιλίους σταδίους. ταῦτα γνοὺς ὁ Ἀντίγονος ὥρμησεν ἐξαίφνης ἐπ’ αὐτοὺς ὑποστρέψας χαλεπὴν ὁδὸν καὶ ἄνυδρον, σύντομον δὲ καὶ βραχεῖαν, ἐλπίζων, εἰ διεσπαρμένοις ἐπιπέσοι περὶ τὰ χειμάδια, μηδ’ ἂν συνελθεῖν ἔτι τὸ πλῆθος ῥᾳδίως εἰς τὸ αὐτὸ τοῖς στρατηγοῖς. ἐμβαλόντι δὲ εἰς γῆν ἀοίκητον αὐτῷ πνεύματά τε δεινὰ καὶ κρύη μεγάλα διελυμαίνετο τὴν πορείαν ἐνοχλουμένου τοῦ στρατεύματος. ἦν οὖν ἀναγκαία βοήθεια πυρὰ πολλὰ καίειν ὅθεν οὐκ ἔλαθε τοὺς πολεμίους, ἀλλὰ τῶν βαρβάρων οἱ τὰ βλέποντα πρὸς τὴν ἀοίκητον ὄρη νεμόμενοι θαυμάσαντες τὸ τῶν πυρῶν πλῆθος ἔπεμψαν ἱππαστρίαις καμήλοις ἀγγέλους πρὸς Πευκέσταν. ὁ δὲ ὡς ἤκουσεν, αὐτός τε παντάπασιν ἔκφρων ὑπὸ δέους γενόμενος καὶ τοὺς ἄλλους ὁρῶν ὁμοίως ἔχοντας ὥρμητο φεύγειν, ἀναστήσας τοὺς καθ’ ὁδὸν ὄντας αὐτοῖς μάλιστα τῶν στρατιωτῶν· εὐμενὴς δὲ τὴν ταραχὴν ἀφῄρει καὶ τὸν φόβον, ὑπισχνούμενος ἐπιστήσειν τῶν πολεμίων τὸ τάχος, ὥστε τρισὶν ὕστερον ἡμέραις ἢ προσδοκῶνται παραγενέσθαι. πεισθέντων δὲ αὐτῶν ἅμα μὲν ἀγγέλους περιέπεμπε τὰς δυνάμεις ἐκ τῶν χειμαδίων καὶ τοὺς ἄλλους ἀθροίζεσθαι κατὰ τάχος κελεύων, ἅμα δὲ αὐτὸς ἐξιππασάμενος μετὰ τῶν ἄλλων ἡγεμόνων, καὶ τόπον ἐξ ἀπόπτου καταφανῆ τοῖς ὁδεύουσι τὴν ἔρημον περιβαλόμενος καὶ διαμετρήσας, ἐκέλευε πυρὰ πολλὰ καίειν ἐν διαστήμασιν, ὥσπερ οἱ στρατοπεδεύοντες. γενομένου δὲ τούτου καὶ τῶν πυρῶν τοῖς περὶ Ἀντίγονον ἐκ τῆς ὀρεινῆς καταφανέντων, ἄχθος ἔσχε καὶ δυσθυμία τὸν Ἀντίγονον, οἰόμενον ᾐσθημένους ἔκπαλαι τοὺς πολεμίους ἀπαντᾶν. ἵν’ οὖν μὴ κατάκοπος καὶ τετρυμένος ἐκ πορείας ἀναγκάζηται μάχεσθαι πρὸς ἀνθρώπους ἑτοίμους καὶ καλῶς κεχειμακότας, προέμενος τὴν σύντομον ἦγε διὰ κωμῶν καὶ πόλεων, καθ’ ἡσυχίαν ἀναλαμβάνων τὸ στράτευμα. μηδενὸς δὲ ἐμποδὼν ὄντος, ὥσπερ εἴωθεν ἀντικαθημένων πολεμίων, τῶν δὲ περιχώρων λεγόντων στράτευμα μηδὲν ὦφθαι, πυρῶν δὲ κεκαυμένων μεστὸν εἶναι τὸν τόπον, ᾔσθετο κατεστρατηγημένος ὑπὸ Εὐμένους, καὶ βαρέως φέρων προσῆγεν ὡς φανερᾷ μάχῃ κριθησόμενος.", "st": "Eum. 15.3"}, {"sp": "N", "t": "ἐν τούτῳ δὲ τῆς δυνάμεως περὶ τὸν Εὐμενῆ τὸ πλεῖστον ἠθροισμένον ἐθαύμαζε τὴν σύνεσιν αὐτοῦ, καὶ μόνον ἐκέλευεν ἄρχειν· ἐφ’ ᾧ λυπούμενοι καὶ φθονοῦντες οἱ τῶν ἀργυρασπίδων ἡγεμόνες, Ἀντιγένης καὶ Τεύταμος, ἐπεβούλευον αὐτῷ, καὶ τοὺς πλείστους τῶν τε σατραπῶν καὶ τῶν στρατηγῶν συναγαγόντες ἐβουλεύοντο πότε χρὴ καὶ πῶς τὸν Εὐμενῆ διαφθεῖραι. συνδόξαν δὲ πᾶσιν ἀποχρήσασθαι πρὸς τὴν μάχην αὐτῷ, μετὰ δὲ τὴν μάχην εὐθὺς ἀνελεῖν Εὔδαμος ὁ τῶν ἐλεφάντων ἡγεμὼν καὶ Φαίδιμος ἐξαγγέλλουσι,’, κρύφα τῷ Εὐμενεῖ τὰ δεδογμένα, δι’ εὔνοιαν μὲν οὐδεμίαν ἢ χάριν, εὐλαβούμενοι δὲ μὴ τῶν χρημάτων, ἃ δεδανείκεσαν αὐτῷ, στερηθῶσιν. εὐμενὴς δὲ τούτους μὲν ἐπῄνεσεν, εἰς δὲ τὴν σκηνὴν ἀπελθών καὶ πρὸς τοὺς φίλους εἰπὼν ὡς ἐν πανηγύρει θηρίων ἀναστρέφοιτο, διαθήκας ἔγραψε καὶ τὰ γραμματεῖα κατέσχισε καὶ διέφθειρεν, οὐ βουλόμενος αὐτοῦ τελευτήσαντος ἐκ τῶν ἀπορρήτων αἰτίας καὶ συκοφαντήματα τοῖς γράψασι γενέσθαι. ταῦτα διοικησάμενος ἐβουλεύετο τὴν νίκην παρεῖναι τοῖς ἐναντίοις, ἢ φυγὼν διὰ Μηδίας καὶ Ἀρμενίας ἐμβαλεῖν εἰς Καππαδοκίαν. οὐδὲν δὲ κυρώσας τῶν φίλων παρόντων, ἀλλ’ ἐπὶ πολλὰ τῇ γνώμῃ πολυτρόπῳ παρὰ τὰς τύχας οὔσῃ κινήσας αὑτόν, ἐξέταττε τὴν δύναμιν, τοὺς μὲν Ἕλληνας καὶ τοὺς βαρβάρους παρορμῶν, ὑπὸ δὲ τῆς φάλαγγος καὶ τῶν ἀργυρασπίδων αὐτὸς παρακαλούμενος θαρρεῖν, ὡς οὐ δεξομένων τῶν πολεμίων. καὶ γὰρ ἦσαν οἱ πρεσβύτατοι τῶν περὶ Φίλιππον καὶ Ἀλέξανδρον, ὥσπερ ἀθληταὶ πολέμων ἀήττητοι καὶ ἀπτῶτες εἰς ἐκεῖνο χρόνου, πολλοὶ μὲν ἑβδομήκοντα ἔτη γεγονότες, νεώτερος δὲ οὐδεὶς ἑξηκονταετοῦς. διὸ καὶ τοῖς περὶ τὸν Ἀντίγονον ἐπιόντες ἐβόων· ἐπὶ τοὺς πατέρας ἁμαρτάνετε, ὦ κακαὶ κεφαλαί· καὶ μετ’ ὀργῆς ἐμπεσόντες ὅλην ὁμοῦ τὴν φάλαγγα συνέτριψαν, οὐδενὸς ὑποστάντος αὐτούς, τῶν δὲ πλείστων ἐν χερσὶ διαφθαρέντων.", "st": "Eum. 16.1"}, {"sp": "N", "t": "ταύτῃ μὲν οὖν ὁ Ἀντίγονος ἡττᾶτο κατὰ κράτος, τοῖς δὲ ἱππεῦσιν ἐπεκράτει· τοῦ δὲ Πευκέστου παντάπασιν ἐκλελυμένως καὶ ἀγεννῶς ἀγωνισαμένου καὶ τὴν ἀποσκευὴν ἔλαβε πᾶσαν, αὑτῷ τε νήφοντι χρησάμενος παρὰ τὰ δεινὰ καὶ τοῦ τόπου συνεργοῦντος. ἀχανὲς γὰρ ἦν τὸ πεδίον, οὔτε βαθύτερον οὔτε ἀπόκροτον καὶ στερεόν, ἀλλὰ θινῶδες καὶ μεστὸν ἁλμυρίδος αὐχμηρᾶς, ἢ τοσούτων μὲν ἵππων τοσούτων δὲ ἀνθρώπων ξαινομένη δρόμοις ὑπὸ τὸν τῆς μάχης καιρόν ἐξήνθει κόνιν ὥσπερ ἄσβεστον, ἀπολευκαίνουσαν τὸν ἀέρα καὶ τὰς ὄψεις διαθολοῦσαν. ᾗ καὶ ῥᾴδιον λαθὼν ὁ Ἀντίγονος τῆς ἀποσκευῆς τῶν πολεμίων ἐκράτησε.", "st": "Eum. 16.5"}, {"sp": "N", "t": "παυσαμένης δὲ τῆς μάχης εὐθὺς οἱ περὶ τὸν Τεύταμον ἐπρεσβεύοντο περὶ τῆς ἀποσκευῆς. Ἀντιγόνου δὲ καὶ ταύτην ἀποδώσειν ὑπισχνουμένου τοῖς ἀργυράσπισι καὶ τἆλλα χρήσεσθαι φιλανθρώπως, εἰ παραλάβοι τὸν Εὐμενῆ, βούλευμα δεινὸν οἱ ἀργυράσπιδες ἐβουλεύσαντο, ἐγχειρίσαι ζῶντα τοῖς πολεμίοις τὸν ἄνδρα. καὶ πρῶτον μὲν ἀνυπόπτως προσεπέλαζον αὐτῷ καὶ παρεφύλαττον, οἱ μὲν ἀποδυρόμενοι περὶ τῆς ἀποσκευῆς, οἱ δὲ θαρρεῖν ὡς νενικηκότα κελεύοντες, οἱ δὲ τῶν ἄλλων ἡγεμόνων κατηγοροῦντες. ἔπειτα προσπεσόντες ἐξήρπασαν τὸ ἐγχειρίδιον αὐτοῦ καὶ τῇ ζώνῃ τὰς χεῖρας ἀποστρέψαντες ἔδησαν. ἐπεὶ δὲ ὑπὸ Ἀντιγόνου Νικάνωρ ἐπέμφθη παραληψόμενος αὐτόν, ἐδεῖτο λόγου τυχεῖν ἀγόμενος διὰ τῶν Μακεδόνων, οὐκ εἰς δέησιν ἢ παραίτησιν, ἀλλ’ ὡς περὶ τῶν ἐκείνοις συμφερόντων διαλεξόμενος.", "st": "Eum. 17.1"}, {"sp": "N", "t": "γενομένης δὲ σιωπῆς ἐν ὑψηλῷ τινι καταστὰς καὶ τὰς χεῖρας δεδεμένας προτείνας, ποῖον, εἶπεν, ὦ κάκιστοι Μακεδόνων, τρόπαιον Ἀντίγονος ἐθελήσας ἂν ἔστησε καθ’ ὑμῶν, οἷον ὑμεῖς καθ’ αὑτῶν ἀνίστατε τὸν στρατηγὸν αἰχμάλωτον ἐκδιδόντες; οὐκ ἄρα δεινὸν ἦν κρατοῦντας ὑμᾶς ἧτταν ἐξομολογεῖσθαι διὰ τὰς ἀποσκευάς, ὡς ἐν τοῖς χρήμασιν, οὐκ ἐν τοῖς ὅπλοις τοῦ κρατεῖν ὄντος, ἀλλὰ καὶ τὸν ἡγεμόνα πέμπετε λύτρον τῆς ἀποσκευῆς. ἐγώ μὲν οὖν ἀήττητος ἄγομαι, νικῶν τοὺς πολεμίους, ὑπὸ τῶν συμμάχων ἀπολλύμενος· ὑμεῖς δέ, πρὸς Διὸς στρατίου καὶ θεῶν ὁρκίων, ἐνταῦθά με δι’ αὑτῶν κτείνατε. πάντως κἀκεῖ κτεινόμενος ὑμέτερον ἔργον εἰμί. μέμψεται δὲ οὐδὲν Ἀντίγονος· νεκροῦ γὰρ Εὐμενοῦς δεῖται καὶ οὐ ζῶντος, εἰ δὲ φείδεσθε τῶν χειρῶν, ἀρκέσει τῶν ἐμῶν ἡ ἑτέρα λυθεῖσα πρᾶξαι τὸ ἔργον. εἰ δὲ οὐ πιστεύετέ μοι ξίφος, ὑπορρίψατε τοῖς θηρίοις δεδεμένον. καὶ ταῦτα πράξαντας ὑμᾶς ἀφίημι τῆς ἐπ’ ἐμοὶ δίκης ὡς ἄνδρας ὁσιωτάτους καὶ δικαιοτάτους περὶ τὸν αὑτῶν στρατηγὸν γενομένους.", "st": "Eum. 17.3"}, {"sp": "N", "t": "ταῦτα τοῦ Εὐμενοῦς λέγοντος τὸ μὲν ἄλλο πλῆθος ἄχθει κατείχετο καὶ κλαυθμὸς ἦν, οἱ δὲ ἀργυράσπιδες ἄγειν ἐβόων καὶ μὴ φλυαροῦντι προσέχειν οὐ γὰρ εἶναι δεινόν εἰ Χερρονησίτης ὄλεθρος οἰμώξεται μυρίοις γυμνάσας πολέμοις Μακεδόνας, ἀλλ’ εἰ τῶν Ἀλεξάνδρου καὶ Φιλίππου στρατιωτῶν οἱ κράτιστοι τοσαῦτα καμόντες ἐν γήρᾳ στέρονται τῶν ἐπάθλων καὶ τροφὴν παρ’ ἑτέρων λαμβάνουσιν, αἱ δὲ γυναῖκες αὐτῶν ἤδη τρίτην νύκτα τοῖς πολεμίοις συγκαθεύδουσιν. ἅμα δὲ ἦγον αὐτὸν ἐπιταχύνοντες.", "st": "Eum. 18.1"}, {"sp": "N", "t": "Ἀντίγονος δὲ δείσας τὸν ὄχλον ἀπελείφθη γὰρ οὐδεὶς ἐν τῷ στρατοπέδῳ δέκα τοὺς κρατιστεύοντας ἐλέφαντας ἐξέπεμψε καὶ λογχοφόρους συχνοὺς Μήδους καὶ Παρθυαίους διακρουσομένους τὸ πλῆθος, εἶτ’ αὐτὸς μὲν ἰδεῖν οὐχ ὑπέμεινε τὸν Εὐμενῆ διὰ τὴν προγεγενημένην φιλίαν καὶ συνήθειαν, πυνθανομένων δὲ τῶν παρειληφότων τὸ σῶμα πῶς φυλάξουσιν, οὕτως, εἶπεν, ὡς ἐλέφαντα ἣ ὡς λέοντα. μετὰ μικρὸν δὲ συμπαθὴς γενόμενος τῶν τε δεσμῶν τοὺς βαρεῖς ἐκέλευσεν ἀφελεῖν καὶ παῖδα παραδέξασθαι τῶν συνήθων, ὅπως ἀλείψαιτο, καὶ τῶν φίλων ἐφῆκε τῷ βουλομένῳ συνδιημερεύειν καὶ κομίζειν τὰ ἐπιτήδεια, βουλευόμενος δὲ περὶ αὐτοῦ πλείονας ἡμέρας προσίετο καὶ λόγους καὶ ὑποσχέσεις, Νεάρχου τε τοῦ Κρητὸς καὶ Δημητρίου τοῦ υἱοῦ φιλοτιμουμένων τὸν Εὐμενῆ σῶσαι, τῶν δὲ ἄλλων ὁμοῦ τι πάντων ἐνισταμένων καὶ κελευόντων ἀναιρεῖν.", "st": "Eum. 18.2"}, {"sp": "N", "t": "λέγεται δὲ τὸν Εὐμενῆ τοῦ φυλάσσοντος αὐτὸν Ὀνομάρχου πυθέσθαι τί δήποτε Ἀντίγονος ἐχθρὸν ἄνδρα καὶ πολέμιον λαβὼν ὑποχείριον οὔτε ἀποκτίννυσι ταχέως οὔτε εὐγενῶς ἀφίησι· τοῦ δὲ Ὀνομάρχου πρὸς ὕβριν εἰπόντος ὡς οὐ νῦν, ἀλλ’ ἐπὶ τῆς μάχης ἔδει πρὸς θάνατον ἔχειν εὐθαρσῶς, ναὶ μὰ τὸν Δία, φάναι τὸν Εὐμενῆ, καὶ τότε εἶχον ἐροῦ δὲ τοὺς εἰς χεῖρας ἐλθόντας· ἀλλ’ οὐδενὶ κρείττονι προστυχὼν οἶδα. καὶ τὸν Ὀνόμαρχον, οὐκοῦν ἐπεὶ νῦν, φάναι, τὸν κρείττονα εὕρηκας, τί οὐκ ἀναμένεις τὸν ἐκείνου καιρόν;", "st": "Eum. 18.4"}, {"sp": "N", "t": "τὸ δὲ οὖν ἔδοξε τῷ Ἀντιγόνῳ τὸν Εὐμενῆ κτείνειν, ἐκέλευσεν ἀὐτοῦ τὴν τροφὴν ἀφελεῖν. καὶ δύο μὲν ἡμέρας ἢ τρεῖς ἄσιτος οὕτω προσήγετο πρὸς τὴν τελευτήν. αἰφνίδιον δὲ ἀναζυγῆς γενομένης εἰσπέμψαντες ἄνθρωπον ἀποσφάττουσιν αὐτόν. τὸ δὲ σῶμα τοῖς φίλοις παραδοὺς ὁ Ἀντίγονος ἐπέτρεψε καῦσαι καὶ τὰ λείψανα συνθέντας εἰς ἀργυρᾶν ὑδρίαν κομίζειν, ἀποδοθησόμενα τῇ γυναικὶ καὶ τοῖς παισίν.", "st": "Eum. 19.1"}, {"sp": "N", "t": "οὕτω δὲ ἀποθανόντος Εὐμενοῦς οὐκ ἐπ’ ἄλλῳ τινὶ τὴν τιμωρίαν ἐποιήσατο τῶν προδόντων αὐτὸν ἡγεμόνων καὶ στρατιωτῶν τὸ δαιμόνιον, ἀλλ’ αὐτὸς Ἀντίγονος προβαλόμενος ὡς ἀσεβεῖς καὶ θηριώδεις τοὺς ἀργυράσπιδας παρέδωκε Σιβυρτίῳ τῷ διοικοῦντι τὴν Ἀραχωσίαν, πάντα τρόπον ἐκτρῖψαι καὶ καταφθεῖραι κελεύσας, ὅπως μηδεὶς αὐτῶν εἰς Μακεδονίαν ἄπεισι μηδὲ ὄψεται τὴν Ἑλληνικὴν θάλατταν.", "st": "Eum. 19.2"}, {"sp": "HDR", "t": "Σερτώριος"}, {"sp": "N", "t": "θαυμαστὸν μὲν ἴσως οὐκ ἔστιν, ἐν ἀπείρῳ τῷ χρόνῳ τῆς τύχης ἄλλοτε ἄλλως ῥεούσης, ἐπὶ ταὐτὰ συμπτώματα πολλάκις καταφέρεσθαι τὸ αὐτόματον. εἴτε γὰρ οὐκ ἔστι τῶν ὑποκειμένων ὡρισμένον τὸ πλῆθος, ἄφθονον ἔχει τῆς τῶν ἀποτελουμένων ὁμοιότητος χορηγὸν ἡ τύχη τὴν τῆς ὕλης εὐπειρίαν, εἴτ’ ἔκ τινων ὡρισμένων ἀριθμῷ συμπλέκεται τὰ πράγματα, πολλάκις ἀνάγκη ταὐτὰ γίνεσθαι διὰ τῶν αὑτῶν περαινόμενα. ἐπεὶ δ’ ἀγαπῶντες ἔνιοι τὰ τοιαῦτα συνάγουσιν ἱστορίᾳ καὶ ἀκοῇ τῶν κατὰ τύχην γεγονότων ὅσα λογισμοῦ καὶ προνοίας ἔργοις ἔοικεν, οἷον ὅτι δυεῖν Ἄττεων γενομένων ἐμφανῶν, τοῦ μὲν Σύρου, τοῦ δὲ Ἀρκάδος, ἑκάτερος ὑπὸ συὸς ἀπώλετο, δυεῖν δὲ Ἀκταιώνων, ὁ μὲν ὑπὸ τῶν κυνῶν, ὁ δ’ ὑπὸ τῶν ἐραστῶν διεσπάσθη, δυεῖν δὲ Σκηπιώνων, ὑφ’ οὗ μὲν ἐνικήθησαν Καρχηδόνιοι πρότερον, ὑφ’ οὗ δὲ ὕστερον ἄρδην ἀνῃρέθησαν, ἑάλω δὲ τὸ Ἴλιον ὑφ’ Ἡρακλέους διὰ τὰς Λαομέδοντος ἵππους καὶ ὑπὸ Ἀγαμέμνονος διὰ τοῦ δουρείου προσαγορευθέντος ἵππου, τρίτον δ’ ὑπὸ Χαριδήμου, ταῖς πύλαις ἵππου τινὸς ἐμπεσόντος ἀποκλεῖσαι ταχὺ τῶν Ἰλιέων μὴ δυνηθέντων δυεῖν δὲ ὁμωνύμων τοῖς εὐωδεστάτοις φυτοῖς πόλεων, Ἴου καὶ Σμύρνης, τὸν ποιητὴν Ὅμηρον ἐι ᾗ μὲν γενέσθαι λέγουσιν, ἐν ᾗ δὲ ἀποθανεῖν, φέρε καὶ τοῦτο προσθῶμεν αὐτοῖς, ὅτι καὶ τῶν στρατηγῶν οἱ πολεμικώτατοι καὶ πλεῖστα δόλῳ κατεργασάμενοι μετὰ δεινότητος ἑτερόφθαλμοι γεγόνασι, Φίλιππος, Ἀντίγονος, Ἀννίβας καὶ περὶ οὗ τόδε τὸ σύγγραμμα Σερτώριος, ὃν Φιλίππου μὲν ἄν τις ἀποφαίνοιτο σωφρονέστερον περὶ τὰς γυναῖκας, Ἀντιγόνου δὲ πιστότερον περὶ φίλους, Ἀννίβου δὲ ἡμερώτερον πρὸς πολεμίους, λειπόμενον δὲ συνέσει μὲν οὐδενὸς τούτων, τύχῃ δὲ πάντων, ᾗ πολὺ τῶν ἐμφανῶν πολεμίων χαλεπωτέρᾳ περὶ πάντα χρησάμενος ἐπανίσωσεν ἑαυτὸν ἐμπειρίᾳ μὲν τῇ Μετέλλου, τόλμῃ δὲ τῇ Πομπηΐου, τύχῃ δὲ τῇ Σύλλα, δυνάμει δὲ τῇ Ῥωμαίων, φυγὰς καὶ βαρβάρων ἔπηλυς ἄρχων ἀντιταξάμενος.", "st": "Sert. 1.1"}, {"sp": "N", "t": "τούτῳ δὴ μάλιστα τῶν Ἑλλήνων τὸν Καρδιανὸν ὁμοιοῦμεν Εὐμενῆ· ἀμφότεροι γὰρ ἀρχικοὶ καὶ σὺν δόλῳ πολεμικοί, καὶ τῆς μὲν αὑτῶν ἀποξενωθέντες, ἡγησάμενοι δ’ ἀλλοδαπῶν, τύχῃ δὲ χρησάμενοι βιαίῳ καὶ ἀδίκῳ περὶ τὴν τελευτήν ἐπιβουλευθέντες γὰρ ἀμφότεροι, μεθ’ ὧν τοὺς πολεμίους ἐνίκων, ὑπὸ τούτων ἀνῃρέθησαν.", "st": "Sert. 1.6"}, {"sp": "N", "t": "Κοΐντῳ Σερτωρίῳ γένος ἦν οὐκ ἀσημότατον ἐν πόλει Νούρσοις τῆς Σαβίνων τραφεὶς δὲ κοσμίως ὑπὸ μητρὶ χήρᾳ πατρὸς ὀρφανός ὑπερφυῶς δοκεῖ φιλομήτωρ γενέσθαι, ὄνομα τῆς μητρὸς Ῥέαν λέγουσιν. ἤσκητο μὲν οὖν καί περὶ δίκας ἱκανῶς, καί τινα καί δύναμιν ἐν τῇ πόλει μειράκιον ὢν ἀπὸ τοῦ λέγειν ἔσχεν αἱ δὲ περὶ τὰ στρατιωτικὰ λαμπρότητες αὐτοῦ καί κατορθώσεις ἐνταῦθα τὴν φιλοτιμίαν μετέστησαν.", "st": "Sert. 2.1"}, {"sp": "N", "t": "πρῶτον μὲν οὖν Κίμβρων καὶ Τευτόνων ἐμβεβληκότων εἰς Γαλατίαν στρατευόμενος ὑπὸ Καιπίωνι, κακῶς ἀγωνισαμένων τῶν Ῥωμαίων καὶ τροπῆς γενομένης ἀποβεβληκὼς τὸν ἵππον καὶ κατατετρωμένος τὸ σῶμα τὸν Ῥοδανὸν διεπέρασεν, αὐτῷ τε τῷ θώρακι καὶ θυρεῷ πρὸς ἐναντίον ῥεῦμα πολὺ νηχόμενος· οὕτω τὸ σῶμα ῥωμαλέον ἦν αὐτῷ καὶ διάπονον τῇ ἀσκήσει. δεύτερον δὲ τῶν αὑτῶν ἐπερχομένων μυριάσι πολλαῖς καὶ δειναῖς ἀπειλαῖς, ὥστε καὶ τὸ μένειν ἄνδρα Ῥωμαῖον ἐν τάξει τότε καὶ τ πείθεσθαι τῷ στρατηγῷ μέγα ἔργον εἶναι, Μάριος μὲν ἡγεῖτο, Σερτώριος δὲ κατασκοπὴν ὑπέστη τῶν πολεμίων, ἐσθῆτι δὲ Κελτικῇ σκευασάμενος καὶ τὰ κοινότατα τῆς διαλέκτου πρὸς ἔντευξιν ἐπὶ καιροῦ παραλαβών, ἀναμίγνυται τοῖς βαρβάροις· καὶ τὰ μὲν ἰδών, τὰ δ’ ἀκοῇ πυθόμενος τῶν ἐπειγόντων ἐπανῆλθε πρὸς Μάριον. τότε μὲν οὖν ἀριστείων ἔτυχεν· ἐν δὲ τῇ λοιπῇ στρατείᾳ πολλὰ καὶ συνέσεως ἔργα καὶ τόλμης ἀποδειξάμενος εἰς ὄνομα καὶ πίστιν ὑπὸ τοῦ στρατηγοῦ προήχθη, Μετὰ δὲ τὸν Κίμβρων καὶ Τευτόνων πόλεμον ἐκπεμφθεὶς ὑπὸ Δειδίῳ στρατηγῷ χιλίαρχος ἐπὶ Ἰβηρίας ἐν τῇ πόλει Κάστλωνι παρεχείμαζε τῆς Κελτιβήρων. ἐπεὶ δὲ τῶν στρατιωτῶν ἐν ἀφθόνοις ὑβριζόντων καὶ τὰ πολλὰ μεθυόντων καταφρονήσαντες οἱ βάρβαροι μετεπέμψαντο νυκτὸς ἐπικουρίαν παρὰ τῶν ἀστυγειτόνων Ὠριτανῶν καὶ κατ’ οἰκίας ἐπιόντες ἔκτεινον αὐτούς, ὑπεκδὺς ὁ Σερτώριος μετ’ ὀλίγων καὶ τοὺς ἐκπίπτοντας συναγαγών κύκλῳ τὴν πόλιν περιῆλθε· καὶ καθ’ ἃς οἱ βάρβαροι πύλας ἔλαθον παρεισπεσόντες ἀνεῳγμένας εὑρών, οὐ ταὐτὸν ἐκείνοις ἔπαθεν, ἀλλὰ φρουρὰς ἐπιστήσας καὶ καταλαβὼν πανταχόθεν τὴν πόλιν ἔκτεινε τοὺς ἐν ἡλικίᾳ πάντας. ὡς δὲ ἀνῃρέθησαν, ἐκέλευσε τοὺς στρατιώτας πάντας τὰ μὲν αὑτῶν ὅπλα καὶ τὴν ἐσθῆτα καταθέσθαι, τοῖς δὲ τῶν βαρβάρων ἐνσκευασαμένους ἕπεσθαι πρὸς τὴν πόλιν ἐκείνην ἐξ ἧς ἀπεστάλησαν οἱ νύκτωρ ἐπιπεσόντες αὐτοῖς. ψευσάμενος δὲ τῇ τῶν ὅπλων ὄψει τοὺς βαρβάρους τάς τε πύλας ἀνεῳγμένας εὗρε καὶ πλῆθος ἀνθρώπων ἔλαβεν οἰομένων ἀπαντᾶν εὖ πεπραχόσι φίλοις καὶ πολίταις. διὸ πλεῖστοι μὲν ὑπὸ τῶν Ῥωμαίων ἐσφάττοντο περὶ τὰς πύλας, οἱ δὲ λοιποὶ παραδόντες ἑαυτοὺς ἐπράθησαν.", "st": "Sert. 3.1"}, {"sp": "N", "t": "ἐκ τούτου Σερτώριος ἐν τῇ Ἰβηρίᾳ διεβοήθη· καὶ ὅτε πρῶτον ἐπανῆκεν εἰς Ῥώμην, ταμίας ἀποδείκνυται τῆς περὶ Πάδον Γαλατίας, ἐν δέοντι. τοῦ γὰρ Μαρσικοῦ πολέμου συνισταμένου, στρατιώτας τε προσταχθὲν αὐτῷ καταλέγειν καὶ ὅπλα ποιεῖσθαι, σπουδὴν καὶ τάχος προσθεὶς τῷ ἔργῳ παρὰ τὴν τῶν ἄλλων νέων βραδυτῆτα καὶ μαλακίαν ἀνδρὸς ἐμπράκτως βιωσομένου δόξαν ἔσχεν. οὐ μὴν ὑφήκατο τῆς στρατιωτικῆς τόλμης εἰς ἀξίωμα προεληλυθὼς ἡγεμόνος, ἀλλὰ καὶ χειρὸς ἐπιδεικνύμενος ἔργα θαυμαστὰ καὶ τὸ σῶμα τοῖς ἀγῶσιν ἀφειδῶς ἐπιδιδούς, τῶν ὄψεων ἀπέβαλε τὴν ἑτέραν ἐκκοπεῖσαν. ἐπὶ τούτῳ δὲ καὶ καλλωπιζόμενος ἀεὶ διετέλει. τοὺς μὲν γὰρ ἄλλους οὐκ ἀεὶ τὰ μαρτύρια τῶν ἀριστειῶν περιφέρειν, ἀλλὰ καὶ ἀποτίθεσθαι στρεπτὰ καὶ δόρατα καὶ στεφάνους, αὐτῷ δὲ τῆς ἀνδραγαθίας παραμένειν τὰ γνωρίσματα, τοὺς αὐτοὺς ἔχοντι τῆς ἀρετῆς ἅμα καὶ τῆς συμφορᾶς θεατάς. ἀπέδωκε δὲ καὶ ὁ δῆμος αὐτῷ τιμὴν πρέπουσαν. εἰσελθόντα γὰρ εἰς θέατρον ἐδέξαντό τε κρότῳ καὶ κατευφήμησαν, ὧν οὐδὲ τοῖς πάνυ προήκουσιν ἡλικίᾳ τε καὶ δόξῃ τυχεῖν ἦν ῥᾴδιον. δημαρχίαν μέντοι μετιών Σύλλα καταστασιάσαντος αὑτὸν ἐξέπεσε· διὸ καὶ δοκεῖ γενέσθαι μισοσύλλας. ἐπεὶ δὲ Μάριος μὲν ὑπὸ Σύλλα κρατηθεὶς ἔφευγε, Σύλλας δὲ Μιθριδάτῃ πολεμήσων ἀπῆρε, τῶν δὲ ὑπάτων Ὀκτάβιος μὲν ἐπὶ τῆς Σύλλα προαιρέσεως ἔμενε, Κίννας δὲ νεωτερίζων ὑποφερομένην ἀνεκαλεῖτο τὴν Μαρίου στάσιν, τούτῳ προσένειμεν αὑτὸν ὁ Σερτώριος, ἄλλως τε καὶ τὸν Ὀκτάβιον ὁρῶν αὑτὸν μὲν ἀμβλύτερον ὄντα, τοῖς δὲ Μαρίου φίλοις ἀπιστοῦντα. γενομένης δὲ τοῖς ὑπάτοις ἐν ἀγορᾷ μάχης μεγάλης Ὀκτάβιος μὲν ἐκράτησε, Κίννας δὲ καὶ Σερτώριος οὐ πολλῷ ἐλάττους τῶν μυρίων ἀποβαλόντες ἔφυγον καὶ τῶν περὶ τὴν Ἰταλίαν ἔτι διεσπαρμένων στρατοπέδων προσαγόμενοι τὰ πλεῖστα πειθοῖ ταχὺ κατέστησαν ἀξιόμαχοι τοῖς περὶ τὸν Ὀκτάβιον.", "st": "Sert. 4.1"}, {"sp": "N", "t": "Μαρίου δὲ καταπλεύσαντος ἐκ Λιβύης καὶ τῷ Κίννᾳ προστιθέντος ἑαυτὸν ὡς ἰδιώτην ὑπάτῳ, τοῖς μὲν ἄλλοις ἐδόκει δέχεσθαι, Σερτώριος δὲ ἀπηγόρευεν, εἴτε τὸν Κίνναν ἧττον οἰόμενος ἑαυτῷ προσέξειν ἀνδρὸς ἡγεμονικωτέρου παρόντος, εἴτε τὴν βαρύτητα τοῦ Μαρίου δεδοικώς, μὴ πάντα τὰ πράγματα συγχέῃ θυμῷ μέτρον οὐκ ἔχοντι, πέρα δίκης ἐν τῷ κρατεῖν προερχόμενος. ἔλεγεν οὖν μικρὸν εἶναι τὸ ὑπολειπόμενον ἔργον αὐτοῖς ἤδη κρατοῦσι, δεξαμένων δὲ τὸν Μάριον τὸ σύμπαν οἴσεσθαι τῆς δόξης ἐκεῖνον καὶ τῆς δυνάμεως, χαλεπὸν ὄντα πρὸς κοινωνίαν ἀρχῆς καὶ ἄπιστον. εἰπόντος δὲ τοῦ Κίννα ταῦτα μὲν ὀρθῶς ὑπολογίζεσθαι τὸν Σερτώριον, αἰδεῖσθαι δὲ καὶ διαπορεῖν ὅπως ἀπώσεται τὸν Μάριον αὐτὸς ἐπὶ κοινωνίᾳ πραγμάτων κεκληκώς, ὑπολαβὼν ὁ Σερτώριος εἶπεν ἀλλ’ ἐγὼ μὲν αὐτὸν ἀφ’ ἑαυτοῦ Μάριον ἥκειν νομίζων εἰς Ἰταλίαν τὸ συμφέρον ἐσκόπουν σοὶ δὲ τὴν ἀρχὴν οὐδὲ βουλεύεσθαι καλῶς εἶχεν ἥκοντος ὃν αὐτὸς ἐλθεῖν ἠξίωσας, ἀλλὰ χρῆσθαι καὶ δέχεσθαι, τῆς πίστεως μηδενὶ λογισμῷ χώραν διδούσης οὕτως μεταπέμπεται τὸν Μάριον Κίννας· καὶ τριχῇ τῆς δυνάμεως διανεμηθείσης ἦρχον οἱ τρεῖς.", "st": "Sert. 5.1"}, {"sp": "N", "t": "διαπολεμηθέντος δὲ τοῦ πολέμου καὶ τῶν περὶ τὸν Κίνναν καὶ Μάριον ἐμφορουμένων ὕβρεώς τε καὶ πικρίας ἁπάσης, ὥστε χρυσὸν ἀποδεῖξαι Ῥωμαίοις τὰ τοῦ πολέμου κακά, Σερτώριος λέγεται μόνος οὔτε ἀποκτεῖναί τινα πρὸς ὀργὴν οὔτε ἐνυβρίσαι κρατῶν, ἀλλὰ καὶ τῷ Μαρίῳ δυσχεραίνειν καὶ τὸν Κίνναν ἐντυγχάνων ἰδίᾳ καὶ δεόμενος μετριώτερον ποιεῖν. τέλος δὲ τῶν δούλων, οὓς Μάριος συμμάχους μὲν ἐν τῷ πολέμῳ δορυφόρους δὲ τῆς τυραννίδος ἔχων ἰσχυροὺς καὶ πλουσίους ἐποίησε, τὰ μὲν ἐκείνου διδόντος καὶ κελεύοντος, τὰ δὲ καὶ βίᾳ παρανομούντων εἰς τοὺς δεσπότας, σφαττόντων μὲν αὐτούς, ταῖς δὲ δεσποίναις πλησιαζόντων καὶ βιαζομένων τοὺς παῖδας, οὐκ ἀνασχετὰ ποιούμενος ὁ Σερτώριος ἅπαντας ἐν ταὐτῷ στρατοπεδεύοντας κατηκόντισεν, οὐκ ἐλάττους τετρακισχιλίων ὄντας.", "st": "Sert. 5.4"}, {"sp": "N", "t": "ἐπεὶ δὲ Μάριος μὲν ἐτελεύτησε καὶ Κίννας ἀνῃρέθη μικρὸν ὕστερον, ὁ δὲ νεανίας Μάριος ἄκοντος αὐτοῦ παρὰ τοὺς νόμους ὑπατείαν ἔλαβε, Κάρβωνες δὲ καὶ Νωρβανοὶ καὶ Σκηπίωνες ἐπιόντι Σύλλᾳ κακῶς ἐπολέμουν, καὶ τὰ μὲν ἀνανδρίᾳ καὶ μαλακίᾳ τῶν στρατηγῶν ἐφθείρετο, τὰ δὲ οἱ προδιδόντες ἀπώλλυσαν, ἔργον δὲ οὐδὲν ἦν αὐτοῦ παρόντος τοῖς πράγμασι μοχθηρῶς ὑποφερομένοις διὰ τὸ χεῖρον φρονεῖν τοὺς μᾶλλον δυναμένους, τέλος δὲ Σύλλας Σκηπίωνι παραστρατοπεδεύσας καὶ φιλοφρονούμενος, ὡς εἰρήνης ἐσομένης, διέφθειρε τὸ στράτευμα, καὶ ταῦτα προλέγων Σκηπίωνι καὶ διδάσκων Σερτώριος οὐκ ἔπειθε, παντάπασιν ἀπογνοὺς τὴν πόλιν ὥρμησεν εἰς Ἰβηρίαν, ὡς, εἰ φθάσει τὴν ἐκεῖ κρατυνάμενος ἀρχήν, καταφυγὴ τοῖς πταίουσιν ἐνταῦθα τῶν φίλων ἐσόμενος.", "st": "Sert. 6.1"}, {"sp": "N", "t": "χειμῶσι δὲ χαλεποῖς χρησάμενος ἐν χωρίοις ὀρεινοῖς ὑπὸ βαρβάρων ἐπράττετο τέλη καὶ μισθοὺς τοῦ παρελθεῖν τὴν ὁδόν. ἀγανακτούντων δὲ τῶν σὺν αὐτῷ, καὶ δεινολογουμένων εἰ Ῥωμαίων ἀνθύπατος τέλη καταβαλεῖ βαρβάροις ὀλέθροις, μικρὰ φροντίσας τοῦ δοκοῦντος αἰσχροῦ, καὶ καιρὸν ὠνεῖσθαι φήσας, οὗ σπανιώτερον οὐδὲν ἀνδρὶ μεγάλων ἐφιεμένῳ, τοὺς μὲν βαρβάρους ἐθεράπευσε χρήμασι, τὴν δ’ Ἰβηρίαν ἐπειχθεὶς κατέσχε. παραλαβὼν δὲ ἔθνη πλήθει μὲν καὶ ἡλικίᾳ ἀκμάζοντα, πλεονεξίᾳ δὲ καὶ ὕβρει τῶν πεμπομένων ἑκάστοτε στρατηγῶν πρὸς ὅλην κακῶς διακείμενα τὴν ἡγεμονίαν, ἀνελάμβανεν ὁμιλίᾳ τε τοὺς δυνατοὺς καὶ φόρων ἀνέσει τοὺς πολλούς, μάλιστα δὲ τῶν ἐπισταθμιῶν ἀπαλλάξας ἠγαπήθη· τοὺς γὰρ στρατιώτας ἠνάγκαζεν ἐν τοῖς προαστείοις χειμάδια πήγνυσθαι, πρῶτος αὐτὸς οὕτω κατασκηνῶν. οὐ μὴν ἐπὶ τῇ τῶν βαρβάρων εὐνοίᾳ τὸ πᾶν ἐποιήσατο, Ῥωμαίων δὲ τῶν αὐτόθι μετοικούντων τοὺς ἐν ἡλικίᾳ καθοπλίσας, μηχανάς τε παντοδαπὰς καὶ ναυπηγίας τριήρων ὑποβαλόμενος, διὰ χειρὸς εἶχε τὰς πόλεις, ἥμερος μὲν ὢν ἐν ταῖς εἰρηνικαῖς χρείαις, φοβερὸς δὲ τῇ παρασκευῇ κατὰ τῶν πολεμίων φαινόμενος.", "st": "Sert. 6.3"}, {"sp": "N", "t": "ὡς δὲ Σύλλαν μὲν ἐπυνθάνετο τῆς Ῥώμης κρατεῖν, ἔρρειν δὲ τὴν Μαρίου καὶ Κάρβωνος στάσιν, αὐτίκα προσδοκῶν στρατιὰν διαπολεμήσουσαν αὐτῷ μεθ’ ἡγεμόνος ἀφίξεσθαι φράγνυται τὰ Πυρηναῖα ὄρη διὰ Ἰουλίου Σαλινάτορος ἑξακισχιλίους ὁπλίτας ἔχοντος, καὶ μετ’ οὐ πολὺ Γάϊος Ἄννιος ἐκπεμφθεὶς ὑπὸ Σύλλα καὶ τὸν Ἰούλιον ἀπρόσμαχον ὁρῶν ἐν ἀπόρῳ καθῆστο παρὰ ταῖς ὑπωρείαις. Καλπουρνίου δέ τινος ἐπίκλησιν Λαναρίου δολοφονήσαντος τὸν Ἰούλιον καὶ τῶν στρατιωτῶν τὰ ἄκρα τῆς Πυρήνης ἐκλιπόντων, ὑπερβαλὼν Ἄννιος ἐπῄει χειρὶ μεγάλῃ τοὺς ἐμποδὼν ἀνιστάς. Σερτώριος δὲ οὐκ ὢν ἀξιόμαχος μετὰ τρισχιλίων εἰς Καρχηδόνα τὴν νέαν καταφυγών, κἀκεῖθεν ἐπιβὰς τῶν νεῶν καὶ διαπεράσας τὸ πέλαγος, Λιβύῃ κατὰ τὴν Μαυρουσίαν προσέσχεν. ἀφυλάκτοις δὲ τοῖς στρατιώταις ὑδρευομένοις τῶν βαρβάρων ἐπιπεσόντων, συχνοὺς ἀποβαλὼν αὖθις εἰς Ἰβηρίαν ἀπέπλει· καὶ ταύτης μὲν ἀποκρούεται, Κιλισσῶν δὲ λῃστρίδων αὐτῷ προσγενομένων Πιτυούσσῃ νήσῳ προσέβαλε, καὶ ἀπέβη τὴν παρ’ Ἀννίου φρουρὰν βιασάμενος. Ἄννιος δὲ μετ’ οὐ πολὺ παρῆν ναυσί τε πολλαῖς καὶ πεντακισχιλίοις ὁπλίταις, πρὸς ὃν ἐπεχείρησε μὲν διαναυμαχεῖν, καίπερ ἐλαφροῖς καὶ πρὸς τάχος, οὐ πρὸς ἀλκήν, πεποιημένοις σκάφεσι χρώμενος, ζεφύρῳ δὲ λαμπρῷ τοῦ πελάγους ἀνισταμένου καὶ τὰ πολλὰ τῶν τοῦ Σερτωρίου πλοίων ὑπὸ κουφότητος πλάγια ταῖς ῥαχίαις περιβάλλοντος, αὐτὸς ὀλίγαις ναυσὶ τῆς μὲν θαλάσσης ὑπὸ τοῦ χειμῶνος εἰργόμενος, τῆς δὲ γῆς ὑπὸ τῶν πολεμίων, ἡμέρας δέκα σαλεύων πρὸς ἐναντίον κῦμα καὶ κλύδωνα τραχὺν ἐπιπόνως διεκαρτέρησεν.", "st": "Sert. 7.1"}, {"sp": "N", "t": "ἐνδόντος δὲ τοῦ πνεύματος φερόμενος νήσοις τισὶν ἐναυλίζεται σποράσιν ἀνύδροις· κἀκεῖθεν ἄρας καὶ διεκβαλὼν τὸν Γαδειραῖον πορθμόν ἐν δεξιᾷ τοῖς ἐκτὸς ἐπιβάλλει τῆς Ἰβηρίας, μικρὸν ὑπὲρ τῶν τοῦ Βαίτιος ἐκβολῶν, ὃς εἰς τὴν Ἀτλαντικὴν ἐκφερόμενος θάλατταν ὄνομα τῇ περὶ αὐτὸν Ἰβηρίᾳ, παρέσχεν.", "st": "Sert. 8.1"}, {"sp": "N", "t": "ἐνταῦθα ναῦταί τινες ἐντυγχάνουσιν αὐτῷ νέον ἐκ τῶν Ἀτλαντικῶν νήσων ἀναπεπλευκότες, αἳ δύο μέν εἰσι λεπτῷ παντάπασι πορθμῷ διαιρούμεναι, μυρίους δ’ ἀπέχουσι Λιβύης σταδίους καὶ ὀνομάζονται Μακάρων. ὄμβροις δὲ χρώμεναι μετρίοις σπανίως, τὰ δὲ πλεῖστα πνεύμασι μαλακοῖς καὶ δροσοβόλοις, οὐ μόνον ἀροῦν καὶ φυτεύειν παρέχουσιν ἀγαθὴν καὶ πίονα χώραν, ἀλλὰ καὶ καρπὸν αὐτοφυῆ φέρουσιν ἀποχρῶντα πλήθει καὶ γλυκύτητι βόσκειν ἄνευ πόνων καὶ πραγματείας σχολάζοντα δῆμον. ἀὴρ δὲ ἄλυπος ὡρῶν τε κράσει καὶ μεταβολῆς μετριότητι κατέχει τὰς νήσους, οἱ μέν γὰρ ἐνθένδε τῆς γῆς ἀποπνέοντες ἔξω βορέαι καὶ ἀπηλιῶται διὰ μῆκος ἐκπεσόντες εἰς τόπον ἀχανῆ διασπείρονται καὶ προαπολείπουσι, πελάγιοι δὲ περιρρέοντες ἀργέσται καὶ ζέφυροι βληχροὺς μέν ὑετοὺς καὶ σποράδας ἐκ θαλάττης ἐπάγοντες, τὰ δὲ πολλὰ νοτεραῖς αἰθρίαις ἐπιψύχοντες ἡσυχῇ τρέφουσιν, ὥστε μέχρι τῶν βαρβάρων διῖχθαι πίστιν ἰσχυράν αὐτόθι τὸ Ἠλύσιον εἶναι πεδίον καὶ τὴν τῶν εὐδαιμόνων οἴκησιν, ἣν Ὅμηρος ὕμνησε.", "st": "Sert. 8.2"}, {"sp": "N", "t": "ταῦθ’ ὁ Σερτώριος ἀκούσας ἔρωτα θαυμαστὸν ἔσχεν οἰκῆσαι τὰς νήσους καὶ ζῆν ἐν ἡσυχίᾳ, τυραννίδος ἀπαλλαγεὶς καὶ πολέμων ἀπαύστων. αἰσθόμενοι δὲ οἱ Κίλικες, οὐθὲν εἰρήνης δεόμενοι καὶ σχολῆς, ἀλλὰ πλούτου καὶ λαφύρων, εἰς Λιβύην ἀπέπλευσαν, Ἄσκαλιν τὸν Ἴφθα κατάξοντες ἐπὶ τὴν Μαυρουσίων βασιλείαν. οὐ μὴν ἀπέκαμεν ὁ Σερτώριος, ἀλλὰ τοῖς πρὸς τὸν Ἄσκαλιν διαπολεμοῦσιν ἔγνω βοηθεῖν, ὡς οἱ σὺν αὐτῷ καινήν τινα λαβόντες ἐλπίδων ἀρχὴν καὶ πράξεων ἑτέρων ὑπόθεσιν μὴ διαλυθεῖεν ὑπὸ τῆς ἀπορίας, ἀσμένοις δὲ τοῖς Μαυρουσίοις ἀφικόμενος εἴχετο ἔργου, καὶ καταμαχεσάμενος τὸν Ἄσκαλιν ἐπολιόρκει. Σύλλα δὲ Πακκιανὸν ἐκπέμψαντος βοηθῆσαι τοῖς περὶ τὸν Ἄσκαλιν μετὰ δυνάμεως, συμβαλὼν ὁ Σερτώριος τὸν μὲν Πακκιανὸν ἀπέκτεινε, τὴν δὲ στρατιὰν κρατήσας προσηγάγετο, καὶ τὴν Τίγγιν, εἰς ἣν ὁ Ἄσκαλις συνέφυγε μετὰ τῶν ἀδελφῶν, ἐξεπολιόρκησεν.", "st": "Sert. 9.1"}, {"sp": "N", "t": "ἐνταῦθα τὸν Ἀνταῖον οἱ Λίβυες ἱστοροῦσι κεῖσθαι· καὶ τὸν τάφον αὐτοῦ Σερτώριος διέσκαψε τοῖς βαρβάροις ἀπιστῶν διὰ μέγεθος, ἐντυχὼν δὲ τῷ σώματι πηχῶν ἑξήκοντα μῆκος, ὥς φασι, κατεπλάγη, καὶ σφάγιον ἐντεμὼν συνέχωσε τὸ μνῆμα, καὶ τὴν περὶ αὐτοῦ τιμήν τε καὶ φήμην συνηύξησε. Τιγγῖται δὲ μυθολογοῦσιν Ἀνταίου τελευτήσαντος τὴν γυναῖκα Τίγγην Ἡρακλεῖ συνελθεῖν, Σόφακα δ’ ἐξ αὐτῶν γενόμενον βασιλεῦσαι τῆς χώρας καὶ πόλιν ἐπώνυμον τῆς μητρὸς ἀποδεῖξαι, Σόφακος δὲ παῖδα γενέσθαι Διόδωρον, ᾧ πολλὰ τῶν Λιβυκῶν ἐθνῶν ὑπήκουσεν Ἑλληνικὸν ἔχοντι στράτευμα τῶν αὐτόθι κατῳκισμένων ὑφ’ Ἡρακλέους Ὀλβιανῶν καὶ Μυκηναίων. ἀλλὰ ταῦτα μὲν ἀνακείσθω τῇ Ἰόβα χάριτι, τοῦ πάντων ἱστορικωτάτου βασιλέων· ἐκείνου γὰρ ἱστοροῦσι τοὺς προγόνους Διοδώρου καὶ Σόφακος ἀπογόνους εἶναι.", "st": "Sert. 9.4"}, {"sp": "N", "t": "Σερτώριος δὲ πάντων ἐγκρατὴς γενόμενος τοὺς δεηθέντας αὐτοῦ καὶ πιστεύσαντας οὐκ ἠδίκησεν, ἀλλὰ καὶ χρήματα καὶ πόλεις καὶ τὴν ἀρχὴν ἀπέδωκεν αὐτοῖς, ὅσα καλῶς εἶχε δεξάμενος διδόντων.", "st": "Sert. 9.4b"}, {"sp": "N", "t": "ἐντεῦθεν ὅποι χρὴ τραπέσθαι βουλευόμενον ἐκάλουν Λυσιτανοὶ πρέσβεις πέμψαντες ἐφ’ ἡγεμονίᾳ, πάντως μὲν ἄρχοντος ἀξίωμα μέγα καὶ ἐμπειρίαν ἔχοντος δεόμενοι πρὸς τὸν ἀπὸ Ῥωμαίων φόβον, ἐκείνῳ δὲ πιστεύοντες αὑτοὺς μόνῳ πυνθανόμενοι παρὰ τῶν συγγεγονότων τὸ ἦθος αὐτοῦ. λέγεται δὲ ὁ Σερτώριος οὔτε ὑφ’ ἡδονῆς οὔτε ὑπὸ δέους εὐάλωτος γενέσθαι, φύσει δὲ ἀνέκπληκτος ὢν παρὰ τὰ δεινά καὶ μέτριος εὐτυχίαν ἐνεγκεῖν· καὶ πρὸς μὲν εὐθυμαχίαν οὐδενὸς ἀτολμότερος τῶν καθ’ ἑαυτὸν ἡγεμόνων, ὅσα δὲ κλωπείας ἐν πολέμοις ἔργα καὶ πλεονεξίας περὶ τόπους ἐχυροὺς καὶ διαβάσεις τάχους δεομένας ἀπάτης τε καὶ ψευδῶν ἐν δέοντι, σοφιστὴς δεινότατος. ἐν δὲ ταῖς τιμαῖς τῶν ἀνδραγαθημάτων δαψιλὴς φαινόμενος, περὶ τὰς τιμωρίας ἐμετρίαζε τῶν ἁμαρτημάτων, καίτοι δοκεῖ περὶ τὸν ἔσχατον αὐτοῦ βίον ὠμότητος καὶ βαρυθυμίας τὸ περὶ τοὺς ὁμήρους πραχθὲν ἔργον ἐπιδεῖξαι τὴν φύσιν οὐκ οὖσαν ἥμερον, ἀλλ’ ἐπαμπεχομένην λογισμῷ διὰ τὴν ἀνάγκην. ἐμοὶ δὲ ἀρετὴν μὲν εἰλικρινῆ καὶ κατὰ λόγον συνεστῶσαν οὐκ ἄν ποτε δοκεῖ τύχη τις ἐκστῆσαι πρὸς τοὐναντίον, ἄλλως δὲ προαιρέσεις καὶ φύσεις χρηστὰς ὑπὸ συμφορῶν μεγάλων παρ’ ἀξίαν κακωθείσας οὐκ ἀδύνατον τῷ δαίμονι συμμεταβαλεῖν τὸ ἦθος. ὃ καὶ Σερτώριον οἶμαι παθεῖν ἤδη τῆς τύχης αὐτὸν ἐπιλειπούσης, ἐκτραχυνόμενον ὑπὸ τῶν πραγμάτων γινομένων πονηρῶν πρὸς τοὺς ἀδικοῦντας.", "st": "Sert. 10.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τότε γε τῶν Λυσιτανῶν καλούντων ἀπῆρεν ἐκ Λιβύης, καὶ τούτους συνέταττεν εὐθὺς αὐτοκράτωρ στρατηγὸς, καὶ τὴν ἐγγὺς Ἰβηρίαν ὑπήκοον ἐποιεῖτο, τῶν πλείστων ἑκουσίως προστιθεμένων, μάλιστα μὲν διὰ τὸ πρᾷον αὐτοῦ καὶ δραστήριον, ἔστι δὲ ἃ καὶ σοφιστικῶς αὐτὸς εἰς ἀπάτην καὶ κήλησιν ἐμηχανᾶτο. καὶ πρῶτόν γε πάντων τὸ περὶ τὴν ἔλαφον. ἦν δὲ τοιόνδε.", "st": "Sert. 11.1"}, {"sp": "N", "t": "Σπανὸς ἀνὴρ δημότης τῶν ἐπὶ χώρας βιούντων ἐλάφῳ νεοτόκῳ φευγούσῃ κυνηγέτας ἐπιτυχών αὐτῆς μὲν ἀπελείφθη, τὴν δὲ νεβρὸν, ἐκπλαγεὶς τῇ καινότητι τῆς χρόας λευκὴ γὰρ ἦν πᾶσα, λαμβάνει διώξας. κατὰ τύχην δὲ Σερτωρίου τοῖς τόποις ἐναυλισαμένου, καὶ πᾶν ὅ τις ἐξ ἄγρας ἢ γεωργίας ἥκοι κομίζων δῶρον ἀσμένως δεχομένου, καὶ φιλοφρόνως ἀμειβομένου τοὺς θεραπεύοντας, ἐγχειρίζει φέρων αὐτῷ τὴν νεβρὸν. ὁ δὲ δεξάμενος αὐτίκα μὲν ἥσθη μετρίως· χρόνῳ δὲ ποιησάμενος τιθασὸν οὕτω καὶ φιλάνθρωπον ὥστε καὶ καλοῦντος ἀκούειν, καὶ βαδίζοντί ποι παρακολουθεῖν, ὄχλου τε καὶ θορύβου παντὸς ἀνέχεσθαι στρατιωτικοῦ, κατὰ μικρὸν ἐξεθείαζε φάσκων Ἀρτέμιδος δῶρον τὴν ἔλαφον εἶναι, καὶ πολλὰ τῶν ἀδήλων ἐπεφήμιζεν αὐτῷ δηλοῦν, γινώσκων εὐάλωτον εἰς δεισιδαιμονίαν εἶναι φύσει τὸ βαρβαρικόν. ὁ δὲ καὶ προσετεχνᾶτο τοιάδε· γνοὺς γὰρ ἂν κρύφα τοὺς πολεμίους ἐμβεβληκότας ποι τῆς ὑπ’ αὐτὸν χώρας ἢ πόλιν ἀφιστάντας, προσεποιεῖτο τὴν ἔλαφον αὐτῷ κατὰ τοὺς ὕπνους διειλέχθαι, κελεύουσαν ἐν ἑτοίμῳ τὰς δυνάμεις ἔχειν, αὖθις δὲ νίκην τινὰ τῶν ἑαυτοῦ στρατηγῶν ἀκούσας τὸν μὲν ἄγγελον ἔκρυπτε, τὴν δὲ ἔλαφον ἐστεφανωμένην ἐπ’ εὐαγγελίοις προῆγεν, εὐθυμεῖσθαι παρακαλῶν καὶ τοῖς θεοῖς θύειν ὡς ἀγαθόν τι πευσομένους.", "st": "Sert. 11.2"}, {"sp": "N", "t": "οὕτως δὲ χειροήθεις ποιησάμενος αὐτούς ἐχρῆτο πρὸς ἅπαντα μετριωτέροις, οὐχ ὑπ’ ἀνδρὸς ἀλλοδαποῦ λογισμῶν, ἀλλ’ ὑπὸ θεοῦ στρατηγεῖσθαι πειθομένοις, ἅμα καὶ τῶν πραγμάτων ἐπιμαρτυρούντων τῷ παρὰ λόγον τὴν δύναμιν αὐξάνεσθαι. δισχιλίοις γὰρ ἑξακοσίοις οὓς ὠνόμαζε Ῥωμαίους, συμμείκτοις δὲ ἑπτακοσίοις Λιβύων εἰς Λυσιτανίαν αὐτῷ συνδιαβᾶσι πελταστὰς τετρακισχιλίους Λυσιτανῶν καὶ ἱππεῖς ἑπτακοσίους προσλαβὼν ἐπολέμει τέτταρσι Ῥωμαίων στρατηγοῖς, ὑφ’ οἷς ἦσαν πεζῶν μὲν δώδεκα μυριάδες, ἱππεῖς δὲ ἑξακισχίλιοι, τοξόται δὲ καὶ σφενδονῆται δισχίλιοι, πόλεις δὲ ἀναρίθμητοι τὸ πλῆθος, αὐτὸς εἴκοσι τὰς πάσας ἐν ἀρχῇ κεκτημένος. ἀλλ’ ὅμως ἀσθενὴς οὕτω καὶ μικρὸς ἀρξάμενος οὐ μόνον ἐθνῶν ἐκράτησε μεγάλων καὶ πόλεις εἷλε πολλάς, ἀλλὰ καὶ τῶν ἀντιστρατήγων Κότταν μὲν ἐν τῷ περὶ τὴν Μελλαρίαν πορθμῷ κατεναυμάχησε, Φουφίδιον δὲ τὸν ἄρχοντα τῆς Βαιτικῆς περὶ τὸν Βαῖτιν ἐτρέψατο δισχιλίους ἀποκτείνας Ῥωμαίων, Δομίτιον δὲ Λεύκιον ἀνθύπατον ὄντα τῆς ἑτέρας Ἰβηρίας διὰ τοῦ ταμίου καταγωνισάμενος, καὶ Θωράνιον, ἄλλον ἡγεμόνα τῶν ὑπὸ Μετέλλου πεμφθέντων μετὰ δυνάμεως, ἀνεῖλεν, αὐτόν τε τὸν Μέτελλον, ἄνδρα Ῥωμαίων ἐν τοῖς τότε μέγιστον καὶ δοκιμώτατον, οὐκ ὀλίγοις σφάλμασι περιβαλὼν εἰς τοσαύτην ἀπορίαν κατέστησεν ὥστε Λεύκιον μὲν Μάλλιον ἐκ τῆς περὶ Ναρβῶνα Γαλατίας ἐλθεῖν αὐτῷ βοηθόν, Πομπήϊον δὲ Μᾶγνον ἐκ Ῥώμης κατὰ τάχος ἀποσταλῆναι μετὰ δυνάμεως.", "st": "Sert. 12.1"}, {"sp": "N", "t": "οὐ γὰρ εἶχεν ὁ Μέτελλος ὅ τι χρήσαιτο προσπολεμῶν ἀνδρὶ τολμητῇ πάσης ἐξαναδυομένῳ φανερᾶς μάχης, πᾶσαν δὲ μεταβαλλομένῳ μεταβολὴν εὐσταλείᾳ καὶ κουφότητι τῆς Ἰβηρικῆς στρατιᾶς, αὐτὸς ὁπλιτικῶν καὶ νομίμων ἀσκητὴς γεγονὼς ἀγώνων καὶ στρατηγὸς ἐμβριθοῦς καὶ μονίμου φάλαγγος, ὤσασθαι μὲν εἰς χεῖρας ἐλθόντας πολεμίους καὶ καταβαλεῖν ἄριστα γεγυμνασμένης, ὀρειβατεῖν δὲ καὶ συνηρτῆσθαι διώξεσι καὶ φυγαῖς ἀπαύστοις ἀνθρώπων ὑπηνεμίων καὶ λιμὸν ἀνέχεσθαι καὶ δίαιταν ἄπυρον καὶ ἄσκηνον, ὥσπερ ἐκεῖνοι, μὴ δυναμένης.", "st": "Sert. 12.5"}, {"sp": "N", "t": "ἔτι δὲ αὐτὸς μὲν ἤδη πρεσβύτερος ἦν καί τι καί πρὸς ἀνειμένην ἤδη καί τρυφερὰν δίαιταν ἐκ πολλῶν ἀγώνων καί μεγάλων ἐνδεδωκώς, τῷ δὲ Σερτωρίῳ συνειστήκει πνεύματος ἀκμαίου γέμοντι καί κατεσκευασμένον ἔχοντι θαυμασίως τὸ σῶμα ῥώμῃ καί τάχει καί λιτότητι. μέθης μὲν γὰρ οὐδὲ ῥᾳθυμῶν ἥπτετο, πόνους δὲ μεγάλους καί μακρὰς ὁδοιπορίας καί συνεχεῖς ἀγρυπνίας ὀλίγοις εἴθιστο καί φαύλοις ἀρκούμενος σιτίοις διαφέρειν, πλάνοις δὲ χρώμενος ἀεὶ καί κυνηγεσίοις ὁπότε σχολάζοι, πάσης διεκδύσεως φεύγοντι καί διώκοντι κυκλώσεως ἀβάτων τε καί βασίμων τόπων ἐμπειρίαν προσειλήφει. διὸ τῷ μὲν εἰργομένῳ μάχης ὅσα νικώμενοι πάσχουσιν ἄνθρωποι βλάπτεσθαι συνέβαινεν, ὁ δὲ τῷ φεύγειν εἶχε τὰ τῶν διωκόντων.", "st": "Sert. 13.1"}, {"sp": "N", "t": "καί γὰρ ὑδρείας ἀπέκοπτε καί σιτολογίας εἶργε, καί προϊόντι μὲν ἐκποδὼν ἦν, ἐκίνει δὲ ἱδρυνθέντα, πολιορκοῦντι δὲ ἄλλους ἐπιφαινόμενος ἀντεπολιόρκει ταῖς τῶν ἀναγκαίων ἀπορίαις, ὥστε τοὺς στρατιώτας ἀπαγορεύειν, καί τοῦ Σερτωρίου μονομαχῆσαι προκαλουμένου τὸν Μέτελλον, βοᾶν καί κελεύειν μάχεσθαι στρατηγὸν στρατηγῷ καί Ῥωμαῖον Ῥωμαίῳ, ἀναδυόμενον δὲ χλευάζειν. ὁ δὲ τούτων μὲν, εὖ ποιῶν, κατεγέλα· στρατηγοῦ γὰρ, ὡς ἔφη Θεόφραστος, δεῖ θάνατον ἀποθνῄσκειν τὸν στρατηγόν, οὐ πελταστοῦ τοῦ τυχόντος, ὁρῶν δὲ τοὺς Λαγγοβρίγας οὐ μικρὰ τῷ Σερτωρίῳ συλλαμβανομένους, δίψῃ δὲ ὄντας εὐαλώτους ἓν γὰρ ἦν αὐτοῖς φρέαρ ἐν τῇ πόλει, τῶν δ’ ἐν τοῖς προαστείοις καί παρὰ τὰ τείχη ναμάτων ὁ πολιορκῶν ἐπικρατεῖν ἔμελλεν, ἧκεν ἐπὶ τὴν πόλιν ὡς ἡμέραις δυσὶ συναιρήσων τὴν πολιορκίαν, ὕδατος οὐκ ὄντος. διὸ καί πέντε ἡμερῶν ἐπιφέρεσθαι σιτία μόνον προείρητο τοῖς στρατιώταις. ὁ Σερτώριος δ’ ὀξέως βοηθήσας ἐκέλευσε δισχιλίους ἀσκοὺς ὕδατος ἐμπλῆσαι, καθ’ ἕκαστον ἀσκὸν ἀργύριον συχνὸν τάξας.", "st": "Sert. 13.3"}, {"sp": "N", "t": "καί πολλῶν μὲν Ἰβήρων, πολλῶν δὲ Μαυρουσίων ὑφισταμένων τὸ ἔργον, ἐπιλεξάμενος ἄνδρας εὐρώστους ἅμα καί ποδώκεις ἔπεμψε διὰ τῆς ὀρεινῆς, κελεύσας, ὅταν παραδῶσι τοὺς ἀσκοὺς τοῖς ἐν τῇ πόλει, τὸν ἄχρηστον ὑπεξαγαγεῖν ὄχλον, ὅπως ἐξαρκῇ τοῖς ἀμυνομένοις τὸ ποτόν. ἐκπύστου δὲ τούτου γενομένου πρὸς τὸν Μέτελλον, ἤχθετο μὲν ἤδη τὰ ἐπιτήδεια τῶν στρατιωτῶν ὑπαναλωκότων, ἐξέπεμψε δὲ ἐπὶ σιτολογίαν Ἀκυῗνον ἑξακισχιλίων ἡγούμενον. αἰσθόμενος δὲ ὁ Σερτώριος καί προλοχίσας τὴν ὁδόν ἐπανερχομένῳ τῷ Ἀκυΐνῳ τρισχιλίους ἄνδρας ἔκ τινος συσκίου χαράδρας ἐπανίστησιν, αὐτὸς δὲ κατὰ στόμα προσβαλὼν τρέπεται, καί τοὺς μὲν διαφθείρει, τοὺς δὲ λαμβάνει ζῶντας. Ἀκυῗνον δὲ μετὰ τῶν ὅπλων καί τὸν ἵππον ἀποβεβληκότα δεξάμενος Μέτελλος αἰσχρῶς ἀπῄει, πολλὰ χλευαζόμενος ὑπὸ τῶν Ἰβήρων.", "st": "Sert. 13.6"}, {"sp": "N", "t": "ἔκ τε δὴ τούτων θαυμαζόμενος ἠγαπᾶτο παρὰ τοῖς βαρβάροις ὁ Σερτώριος, καὶ ὅτι Ῥωμαϊκοῖς ὁπλισμοῖς καὶ τάξεσι καὶ συνθήμασιν ἀφαιρῶν τὸ μανικὸν καὶ θηριῶδες αὑτῶν τῆς ἀλκῆς ἀντὶ λῃστηρίου μεγάλου στρατὸν ἐποιεῖτο τὴν δύναμιν. ἔτι δ’ ἀργύρῳ χρώμενος ἀφειδῶς καὶ χρυσῷ κράνη τε κατεκόσμει καὶ θυρεοὺς αὑτῶν διεποίκιλλε, καὶ χλαμύσιν ἀνθιναῖς καὶ χιτῶσι χρῆσθαι διδάσκων καὶ χορηγῶν εἰς ταῦτα καὶ συμφιλοκαλῶν ἐδημαγώγει. μάλιστα δὲ εἷλεν αὐτοὺς τὰ τῶν παίδων, τοὺς γὰρ εὐγενεστάτους ἀπὸ τῶν ἐθνῶν συναγαγὼν εἰς Ὄσκαν, πόλιν μεγάλην, διδασκάλους ἐπιστήσας Ἑλληνικῶν τε καὶ Ῥωμαϊκῶν μαθημάτων ἔργῳ μὲν ἐξωμηρεύσατο, λόγῳ δὲ ἐπαίδευεν, ὡς ἀνδράσι γενομένοις πολιτείας τε μεταδώσων καὶ ἀρχῆς. οἱ δὲ πατέρες ἥδοντο θαυμαστῶς τοὺς παῖδας ἐν περιπορφύροις ὁρῶντες μάλα κοσμίως φοιτῶντας εἰς τὰ διδασκαλεῖα, καὶ τὸν Σερτώριον ὑπὲρ αὑτῶν μισθοὺς τελοῦντα, καὶ πολλάκις ἀποδείξεις λαμβάνοντα, καὶ γέρα τοῖς ἀξίοις νέμοντα, καὶ τὰ χρυσᾶ περιδέραια δωρούμενον ἃ Ῥωμαῖοι βούλλας καλοῦσιν. ἔθους δ’ ὄντος Ἰβηρικοῦ τοὺς περὶ τὸν ἄρχοντα τεταγμένους συναποθνῄσκειν αὐτῷ πεσόντι, καὶ τοῦτο τῶν ἐκεῖ βαρβάρων κατάσπεισιν ὀνομαζόντων, τοῖς μὲν ἄλλοις ἡγεμόσιν ὀλίγοι τῶν ὑπασπιστῶν καὶ τῶν ἑταίρων, Σερτωρίῳ δὲ πολλαὶ μυριάδες ἀνθρώπων κατεσπεικότων ἑαυτοὺς ἠκολούθουν. λέγεται δὲ πρός τινι πόλει τροπῆς γενομένης καὶ τῶν πολεμίων ἐπικειμένων τοὺς Ἴβηρας ἀμελήσαντας αὑτῶν τὸν Σερτώριον σῴζειν καὶ τοῖς ὤμοις ἐπαραμένους ἄλλους πρὸ ἄλλων ἀνακουφίσαι πρὸς τὰ τείχη, γενομένου δ’ ἐν ἀσφαλεῖ τοῦ ἄρχοντος, οὕτω τρέπεσθαι πρὸς φυγὴν ἕκαστον αὑτῶν.", "st": "Sert. 14.1"}, {"sp": "N", "t": "οὐ μόνον δὲ τοῖς Ἴβηρσιν ἦν ποθεινός, ἀλλὰ καὶ τοῖς ἐξ Ἰταλίας στρατευομένοις. Περπέννα γοῦν Οὐέντωνος ἀπὸ τῆς αὐτῆς Σερτωρίῳ στάσεως εἰς Ἰβηρίαν παραγενομένου μετὰ χρημάτων πολλῶν καὶ μεγάλης δυνάμεως, ἰδίᾳ δὲ καθ’ ἑαυτὸν ἐγνωκότος πολεμεῖν πρὸς τὸν Μέτελλον, ἐδυσχέραινον οἱ στρατιῶται, καὶ πολὺς ἦν τοῦ Σερτωρίου λόγος ἐν τῷ στρατοπέδῳ, τὸν Περπένναν ἀνιῶν εὐγενείᾳ καὶ πλούτῳ τετυφωμένον. οὐ μὴν ἀλλ’ ἐπεὶ Πομπήϊος ἠγγέλλετο τὴν Πυρήνην ὑπερβάλλων, ἀναλαβόντες οἱ στρατιῶται τὰ ὅπλα καὶ τὰ σημεῖα τῶν τάξεων ἀναρπάσαντες κατεβόησαν τοῦ Περπέννα, κελεύοντες ὡς τὸν Σερτώριον ἄγειν αὐτοὺς· εἰ δὲ μή, καταλιπόντες ἐκεῖνον ἠπείλουν αὐτοὶ βαδιεῖσθαι πρὸς ἄνδρα σώζεσθαι καὶ σῴζειν δυνάμενον. συγχωρήσας δὲ ὁ Περπέννας ἤγαγεν αὐτοὺς, καὶ συνέμιξε τῷ Σερτωρίῳ πεντήκοντα καὶ τρεῖς ἔχων σπείρας.", "st": "Sert. 15.1"}, {"sp": "N", "t": "Σερτώριος δέ, τῶν ἐντὸς Ἴβηρος αὐτῷ ποταμοῦ πάντων ὁμοῦ τι προστιθεμένων, πλήθει μὲν ἦν μέγας· ἐπέρρεον γὰρ ἀεὶ καὶ συνεφέροντο πανταχόθεν πρὸς αὑτόν· ἀταξίᾳ δὲ βαρβαρικῇ καὶ θρασύτητι ταραττόμενος ἐπιχειρεῖν τοῖς πολεμίοις βοώντων καὶ τὴν τριβὴν δυσανασχετούντων ἐπειρᾶτο παραμυθεῖσθαι διὰ λόγων. ὡς δὲ ἑώρα χαλεπαίνοντας καὶ βιαζομένους ἀκαίρως, προήκατο καὶ περιεῖδε συμπλεκομένους τοῖς πολεμίοις ἐν οἷς οὐ παντελῶς συντριβέντας, ἀλλὰ πληγὰς λαβόντας ἤλπιζε πρὸς τὰ λοιπὰ κατηκόους μᾶλλον ἕξειν. ὧν δὲ εἴκαζε γενομένων, ἐπιβοηθήσας ἀνέλαβέ τε φεύγοντας αὐτοὺς καὶ κατέστησεν ἀσφαλῶς εἰς τὸ στρατόπεδον. βουλόμενος δὲ καὶ τὴν ἀθυμίαν ἀφελεῖν, μεθ’ ἡμέρας ὀλίγας πάνδημον ἐκκλησίαν ἀθροίσας ἵππους εἰσήγαγε δύο, τὸν μὲν ἀσθενῆ τελέως καὶ πρεσβύτερον ἤδη, τὸν δὲ ἕτερον εὐμεγέθη μὲν αὐτὸν καὶ ἰσχυρόν, θαυμαστὴν δὲ πυκνότητι καὶ κάλλει τριχῶν οὐρὰν ἔχοντα, παρειστήκει δὲ τῷ μὲν ἀσθενεῖ μέγας ἀνὴρ καὶ ῥωμαλέος, τῷ δὲ ἰσχυρῷ μικρὸς ἕτερος καὶ τὴν ὄψιν εὐκαταφρόνητος, σημείου δὲ δοθέντος αὐτοῖς ὁ μὲν ἰσχυρὸς ἀμφοτέραις ταῖς χερσὶ τοῦ ἵππου τὴν κέρκον ὡς ἀπορρήξων εἷλκε βίᾳ πρὸς αὑτόν, ὁ δὲ ἀσθενὴς τοῦ ἰσχυροῦ κατὰ μίαν τῶν τριχῶν ἐξέτιλλεν. ἐπεὶ δὲ ὁ μὲν οὐκ ὀλίγα πράγματα μάτην ἑαυτῷ καὶ πολὺν γέλωτα τοῖς θεωμένοις παρασχὼν ἀπεῖπεν, ὁ δὲ ἀσθενὴς ἀκαρεὶ καὶ σὺν οὐδενὶ πόνῳ ψιλὴν τριχῶν ἀπέδειξε τὴν οὐράν, ἀναστὰς ὁ Σερτώριος, ὁρᾶτε, εἶπεν, ἄνδρες σύμμαχοι, τὴν ἐπιμονὴν ἀνυσιμωτέραν τῆς βίας οὖσαν, καὶ πολλὰ τῶν ἁθρόως ἀλήπτων ἐνδιδόντα τῷ κατὰ μικρόν. ἄμαχον γὰρ τὸ ἐνδελεχές, ᾧ πᾶσαν ἐπιὼν ὁ χρόνος αἱρεῖ καὶ κατεργάζεται δύναμιν, εὐμενὴς ὢν σύμμαχος τοῖς δεχομένοις λογισμῷ τὸν καιρὸν αὐτοῦ, τοῖς δὲ ἀκαίρως ἐπειγομένοις πολεμιώτατος. τοιαῦτα μὲν ὁ Σερτώριος ἑκάστοτε πλέκων παραμύθια τοῖς βαρβάροις διεπαιδαγώγει τὸν καιρόν.", "st": "Sert. 16.1"}, {"sp": "N", "t": "οὐδενὸς δὲ ἧττον αὐτοῦ τῶν πολεμικῶν ἔργων ἐθαυμάσθη τὸ περὶ τοὺς λεγομένους Χαρακιτανούς. εἰσὶ δὲ δῆμος ὑπὲρ τόν Ταγώνιον ποταμόν, οὐκ ἄστεσιν οὐδὲ κώμαις ἐνοικοῦντες, ἀλλὰ λόφος ἐστὶν εὐμεγέθης καὶ ὑψηλός ἄντρα καὶ κοιλώματα πετρῶν βλέποντα πρὸς βορέαν περιέχων, ἡ δ’ ὑποκειμένη πᾶσα χώρα πηλὸν ἀργιλώδη καὶ γῆν ὑπὸ χαυνότητος εὔθρυπτον ἀναδίδωσιν, οὔτε τοὺς ἐπιβαίνοντας ἀνέχεσθαι καρτεράν, καὶ μικρὸν ἁψαμένων, ὥσπερ ἄσβεστον ἢ τέφραν, ἐπὶ πολὺ διαχεομένην. τῶν οὖν βαρβάρων, ὁσάκις φόβῳ πολέμου καταδύντες εἰς τὰ σπήλαια καὶ τὴν λείαν εἴσω συναγαγόντες ἀτρεμοῖεν, ὄντων ἀλήπτων ὑπὸ βίας, τόν δὲ Σερτώριον τότε διακεκριμένον ἀπὸ τοῦ Μετέλλου καὶ καταστρατοπεδεύσαντα παρὰ τόν λόφον ὑπερφρονούντων ὡς κεκρατημένον, εἴτε ὑπ’ ὀργῆς ἐκεῖνος εἴτε μὴ δοκεῖν φεύγειν βουλόμενος ἅμ’ ἡμέρᾳ προσελάσας κατεσκέπτετο τόν τόπον. οὐδαμόθεν δὲ προσβολὴν ἔχοντος, ἄλλως ἀλύων καὶ κεναῖς χρώμενος ἀπειλαῖς ὁρᾷ τῆς γῆς ἐκείνης κονιορτὸν ἄνω πολὺν ὑπὸ πνεύματος ἐπ’ αὐτούς φερόμενον.", "st": "Sert. 17.1"}, {"sp": "N", "t": "τέτραπται μὲν γὰρ, ὡς ἔφην, τὰ σπήλαια πρὸς βορέαν, ὁ δὲ ἀπὸ τῆς ἄρκτου πνέων ἄνεμος, Καικίαν ἔνιοι καλοῦσιν, ἐπέχει μάλιστα καὶ πλεῖστός ἐστι τῶν ἐκεῖ πνευμάτων, ἐξ ὑγρῶν πεδίων καὶ νιφοβόλων συμφυσώμενος ὀρῶν· τότε δὲ καὶ θέρους ἀκμάζοντος ἰσχύων καὶ τρεφόμενος τῇ τῶν ὑπαρκτίων ἀνέσει πάγων ἥδιστος ἐπέπνει καὶ κατεῖχεν αὐτούς τε καὶ βοτὰ δι’ ἡμέρας ἀναψύχων. ταῦτα δὴ συλλογιζόμενος ὁ Σερτώριος καὶ παρὰ τῶν ἐγχωρίων ἀκούων, ἐκέλευσε τοὺς στρατιώτας τῆς ἀραιᾶς καὶ τεφρώδους γῆς ἐκείνης ἀποσπῶντας καὶ παραφέροντας καταντικρὺ τοῦ λόφου θῖνα ποιεῖν, ἣν οἱ βάρβαροι χώματος ἐπ’ αὐτούς εἶναι κατασκευὴν ὑπονοοῦντες ἐχλεύαζον. τότε μὲν οὖν ἐργασαμένους τοὺς στρατιώτας ἄχρι νυκτὸς ἀπήγαγεν·", "st": "Sert. 17.4"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ πρῶτον μὲν αὔρα μαλακὴ προαπέπνει διακινοῦσα τῆς συμπεφορημένης γῆς τὸ λειότατον ὥσπερ ἄχνην σκιδνάμενον, ἔπειτα σοβαροῦ τοῦ Καικίου πρὸς τόν ἥλιον ἐκχεομένου καὶ τῶν λόφων κονιωμένων ἐπιστάντες οἱ στρατιῶται τόν τε χοῦν ἀνέτρεπον διὰ βάθους καὶ τόν σπίλον ἔκοπτον, ἔνιοι δὲ καὶ τοὺς ἵππους ἄνω καὶ κάτω διεξήλασαν ἀνιστάντες τὸ χαύνωμα καὶ τῇ πνοῇ μετέωρον παραδιδόντες. ἡ δ’ ὑπολαμβάνουσα πᾶν τὸ θρυπτόμενον καὶ κινούμενον ἄνω προσέβαλλε τοῖς οἰκήμασι τῶν βαρβάρων, κατὰ θύρας δεχομένοις τόν Καικίαν, οἱ δέ, ἅτε δὴ τῶν σπηλαίων μίαν ἐκείνην ἀναπνοὴν ἐχόντων ᾗ τὸ πνεῦμα προσέπιπτε, ταχὺ μὲν ἀπεσκοτοῦντο τὰς ὄψεις, ταχὺ δ’ ἀνεπίμπλαντο πνιγώδους ἄσθματος, τραχὺν ἀέρα καὶ πολλῇ κόνει συμπεφυρμένον ἕλκοντες. ὅθεν ἡμέρας δύο μόλις ἀνασχόμενοι τῇ τρίτῃ παρέδωκαν ἑαυτούς, οὐ τοσοῦτον Σερτωρίῳ δυνάμεως ὅσον δόξης προσθέντες, ὡς τὰ δι’ ὅπλων ἀνάλωτα σοφίᾳ κατεργασαμένῳ.", "st": "Sert. 17.6"}, {"sp": "N", "t": "μέχρι μὲν οὖν τοῖς περὶ Μέτελλον ἐπολέμει, τὰ πλεῖστα κατευτυχεῖν ἐδόκει, γήρᾳ καὶ φυσικῇ βραδυτῆτι τοῦ Μετέλλου πρὸς ἄνδρα τολμητὴν καὶ λῃστρικῆς μᾶλλον ἢ στρατιωτικῆς ἡγούμενον δυνάμεως οὐκ ἀναφέροντος· ἐπεὶ δὲ καὶ Πομπηΐῳ τὴν Πυρήνην ὑπερβαλόντι παραστρατοπεδεύσας, καὶ πᾶσαν ἅμα μὲν διδοὺς, ἅμα δὲ λαμβάνων στρατηγικῶν παλαισμάτων πεῖραν, ἀντιτεχνώμενός τε καὶ φυλαττόμενος πλεῖον εἶχε, κομιδῇ διεβοήθη μέχρι Ῥώμης ὡς δεινότατος ὢν πόλεμον μεταχειρίσασθαι τῶν τότε στρατηγῶν. οὐ γάρ τι μικρὸν ἦν τὸ Πομπηΐου κλέος, ἀλλ’ ἤνθει τότε μάλιστα πρὸς δόξαν ἐκ τῶν περὶ Σύλλαν ἀνδραγαθημάτων, ἐφ’ οἷς καὶ Μᾶγνος ὑπ’ αὐτοῦ, τουτέστι Μέγας, ἐπωνομάσθη τιμῶν τε θριαμβικῶν οὔπω γενειῶν ἔτυχεν. ὅθεν καὶ πολλαὶ τῶν ὑπὸ Σερτωρίῳ πόλεων ἀποβλέψασαι πρὸς αὐτὸν ὁρμὴν μεταβολῆς ἔσχον, εἶτα ἐπαύσαντο, τοῦ περὶ Λαύρωνα πάθους παρὰ πᾶσαν ἐλπίδα συμβάντος.", "st": "Sert. 18.1"}, {"sp": "N", "t": "Σερτωρίου γὰρ πολιορκοῦντος αὑτοὺς ἧκε Πομπήϊος πανστρατιᾷ βοηθήσων εἶτα ὁ μὲν λόφον εὖ δοκοῦντα πεφυκέναι κατὰ τῆς πόλεως προληψόμενος, ὁ δὲ τοῦτο κωλύσων ἠπείγετο. τοῦ δὲ Σερτωρίου φθάσαντος ἐπιστήσας τὸν στρατὸν ὁ Πομπήϊος ἔχαιρε τῇ συντυχίᾳ, νομίζων ἐν μέσῳ τῆς πόλεως καὶ τῆς αὐτοῦ στρατιᾶς ἀπειλῆφθαι τὸν Σερτώριον καὶ πρὸς τοὺς Λαυρωνίτας εἰσέπεμψε θαρρεῖν κελεύων καὶ καθῆσθαι περὶ τὰ τείχη θεωμένους πολιορκούμενον Σερτώριον. ἐκεῖνος δ’ ἀκούσας ἐγέλασε, καὶ τὸν Σύλλα μαθητὴν οὕτω γὰρ τὸν Πομπήϊον ἐπισκώπτων προσηγόρευεν αὐτὸς ἔφη διδάξειν ὅτι δεῖ τὸν στρατηγὸν κατόπιν μᾶλλον ἢ κατὰ πρόσωπον βλέπειν. ταῦτα δὲ λέγων ἅμα τοῖς πολιορκουμένοις ἐπεδείκνυεν ἑξακισχιλίους ὁπλίτας ὑπ’ αὐτοῦ καταλελειμμένους ἐπὶ τοῦ προτέρου χάρακος, ὅθεν ὁρμηθεὶς κατειλήφει τὸν λόφον, ὅπως ἐπὶ σφᾶς τρεπομένῳ τῷ Πομπηΐῳ κατὰ νώτου προσπέσοιεν. ὃ δὴ καὶ Πομπήϊος ὀψὲ μάλα συμφρονήσας ἐπιχειρεῖν μὲν οὐκ ἐθάρρει κύκλωσιν δεδοικώς, ἀπολιπεῖν δὲ ᾐσχύνετο κινδυνεύοντας ἀνθρώπους, παρὼν δὲ καὶ καθήμενος ἠναγκάζετο ὁρᾶν ἀπολλυμένους· ἀπέγνωσαν γὰρ αὑτοὺς οἱ βάρβαροι καὶ τῷ Σερτωρίῳ παρέδωκαν. ὁ δὲ τῶν μὲν σωμάτων ἐφείσατο καὶ πάντας ἀφῆκε, τὴν δὲ πόλιν κατέπρησεν, οὐχ ὑπ’ ὀργῆς οὐδ’ ὠμότητος, ἐλάχιστα γὰρ δοκεῖ θυμῷ χαρίσασθαι τῶν στρατηγῶν οὗτος ἁνήρ, ἀλλ’ ἐπ’ αἰσχύνῃ καὶ κατηφείᾳ τῶν τεθαυμακότων Πομπήϊον, ἵνα ᾖ λόγος ἐν τοῖς βαρβάροις ὅτι παρὼν ἐγγὺς καὶ μονονοὺ θερμαινόμενος τῷ πυρὶ τῶν συμμάχων οὐ προσήμυνεν.", "st": "Sert. 18.3"}, {"sp": "N", "t": "ἧτται μὲν οὖν τῷ Σερτωρίῳ πλείονες συνέβαινον, αὑτὸν μὲν ἀήττητον ἀεὶ φυλάττοντι καὶ τοὺς καθ’ αὑτόν, θραυομένῳ δὲ περὶ τοὺς ἄλλους ἡγεμόνας· ἐκ δὲ ὧν ἐπηνωρθοῦτο τὰς ἥττας μᾶλλον ἐθαυμάζετο νικώντων τῶν ἀντιστρατήγων, οἷον ἐν τῇ περὶ Σούκρωνι μάχῃ πρός Πομπήϊον, καὶ πάλιν ἐν τῇ περὶ Τουρίαν πρός τε τοῦτον ὁμοῦ καὶ Μέτελλον. ἡ μὲν οὖν περὶ Σούκρωνι μάχη λέγεται γενέσθαι τοῦ Πομπηΐου κατεπείξαντος, ὡς μὴ μετάσχοι τῆς νίκης Μέτελλος. ὁ δὲ Σερτώριος ἐβούλετο μὲν τῷ Πομπηΐῳ, πρὶν ἐπελθεῖν τὸν Μέτελλον, διαγωνίσασθαι, παραγαγὼν δὲ ἑσπέρας ἤδη συνέβαλεν, οἰόμενος ξένοις οὖσι καὶ ἀπείροις τῶν χωρίων τοῖς πολεμίοις τὸ σκότος ἔσεσθαι καὶ φεύγουσιν ἐμπόδιον καὶ διώκουσι. γενομένης δὲ τῆς μάχης ἐν χερσίν ἔτυχε μὲν οὐ πρός Πομπήϊον αὐτός, ἀλλὰ πρός Ἀφράνιον ἐν ἀρχῇ συνεστηκώς ἔχοντα τὸ ἀριστερόν, αὐτὸς ἐπὶ τοῦ δεξιοῦ τεταγμένος, ἀκούσας δὲ τῷ Πομπηΐῳ τοὺς συνεστῶτας ὑποχωρεῖν ἐγκειμένῳ καὶ κρατεῖσθαι, τὸ μὲν δεξιὸν ἐπ’ ἄλλοις ἐποιήσατο στρατηγοῖς, πρός δὲ ἐκεῖνο τὸ νικώμενον αὐτὸς ἐβοηδρόμει. καὶ τοὺς μὲν ἤδη τρεπομένους τοὺς δὲ ἔτι μένοντας ἐν τάξει συναγαγὼν καὶ ἀναθαρρύνας, ἐξ ὑπαρχῆς ἐνέβαλε τῷ Πομπηΐῳ διώκοντι, καὶ φυγὴν ἐποιήσατο πολλήν, ὅτε καὶ Πομπήϊος ἐγγὺς ἐλθὼν ἀποθανεῖν καὶ τραυματισθείς παραλόγως διέφυγεν. οἱ γὰρ μετὰ Σερτωρίου Λίβυες, ὡς ἔλαβον αὐτοῦ τὸν ἵππον χρυσῷ κεκοσμημένον καὶ φαλάρων ἀνάπλεων πολυτελῶν, ἐν τῷ διανέμεσθαι καὶ διαφέρεσθαι πρός ἀλλήλους προήκαντο τὴν δίωξιν. Ἀφράνιος δὲ τοὺς ἀνθεστῶτας πρός αὑτὸν ἅμα τῷ Σερτώριον ἀπελθεῖν ἐπὶ θάτερα βοηθοῦντα τρεψάμενος εἰς τὸ στρατόπεδον κατήραξε· καὶ συνεισπεσὼν ἐπόρθει σκότους ἤδη ὄντος, μήτε τὴν Πομπηΐου φυγὴν εἰδώς μήτε τοὺς στρατιώτας τῆς ἁρπαγῆς ἐπισχεῖν δυνάμενος, ἐν τούτῳ δὲ Σερτώριος ἀνέστρεψε τὸ καθ’ αὑτὸν νενικηκώς· καὶ τοῖς Ἀφρανίου δι’ ἀταξίαν ταρασσομένοις ἐπιπεσών πολλοὺς διέφθειρε. πρωὶ δὲ αὖθις ἐξοπλισθεὶς ἐπὶ μάχην κατέβαινεν, εἶτα Μέτελλον αἰσθόμενος ἐγγὺς εἶναι λύσας τὴν τάξιν ἀνέζευξεν, εἰπών· ἀλλ’ ἔγωγε τὸν παῖδα τοῦτον, εἰ μὴ παρῆν ἡ γραῦς ἐκείνη, πληγαῖς ἂν νουθετήσας εἰς Ῥώμην ἀπεστάλκειν.", "st": "Sert. 19.1"}, {"sp": "N", "t": "ἠθύμει δὲ δεινῶς διὰ τὸ μηδαμοῦ φανερὰν τὴν ἔλαφον ἐκείνην εἶναι· μηχανῆς γὰρ ἐπὶ τοὺς βαρβάρους ἐστέρητο θαυμαστῆς, τότε δὴ μάλιστα παραμυθίας δεομένους, εἶτα μέντοι νυκτὸς ἄλλως πλανώμενοί τινες ἐπιτυγχάνουσιν αὐτῇ, καί γνωρίσαντες ἀπὸ τῆς χρόας λαμβάνουσιν. ἀκούσας δὲ ὁ Σερτώριος ἐκείνοις μὲν ὡμολόγησεν, ἂν μηδενὶ φράσωσι, χρήματα πολλὰ δώσειν, ἀποκρύψας δὲ τὴν ἔλαφον καί διαλιπὼν ὀλίγας ἡμέρας προῄει μάλα φαιδρὸς ἀπ’ ὄψεως ἐπὶ τὸ βῆμα, διηγούμενος τοῖς ἡγεμόσι τῶν βαρβάρων ὡς ἀγαθόν τι μέγα τοῦ θεοῦ προμηνύοντος αὐτῷ κατὰ τοὺς ὕπνους· εἶτα ἀναβὰς ἐπὶ τὸ βῆμα τοῖς ἐντυγχάνουσιν ἐχρημάτιζεν. ἡ δὲ ἔλαφος ὑπὸ τῶν φυλαττόντων αὐτὴν ἐγγὺς ἀφεθεῖσα καί κατιδοῦσα τὸν Σερτώριον ἐχώρει δρόμῳ περιχαρὴς πρὸς τὸ βῆμα, καί παραστᾶσα τὴν κεφαλὴν ἐπέθηκε ταῖς γόνασιν αὐτοῦ καί τῷ στόματι τῆς δεξιᾶς ἔψαυεν, εἰθισμένη καί πρότερον τοῦτο ποιεῖν. ἀντιφιλοφρονουμένου δὲ τοῦ Σερτωρίου πιθανῶς καί τι καί δακρύσαντος, ἔκπληξις εἶχε τοὺς παρόντας τὸ πρῶτον, εἶτα κρότῳ καί βοῇ τὸν Σερτώριον ὡς δαιμόνιον ἄνδρα καί θεοῖς φίλον οἴκαδε προπέμψαντες ἐν εὐθυμίαις καί χρησταῖς ἐλπίσιν ἦσαν.", "st": "Sert. 20.1"}, {"sp": "N", "t": "ἐν δὲ τοῖς τῶν Σεγουντίνων πεδίοις εἰς τὰς ἐσχάτας ἀπορίας κατακεκλεικὼς τούς πολεμίους, ἠναγκάσθη συμβαλεῖν αὐτοῖς καταβαίνουσιν ἐφ’ ἁρπαγὴν καὶ σιτολογίαν. ἠγωνίσθη δὲ λαμπρῶς παρ’ ἀμφοτέρων, καὶ Μέμμιος μὲν ὁ τῶν ὑπὸ Πομπηΐῳ στρατηγῶν ἡγεμονικώτατος ἐν τῷ καρτερωτάτῳ τῆς μάχης ἔπεσεν, ἐκράτει δὲ Σερτώριος καὶ φόνῳ πολλῷ τῶν ἔτι συνεστώτων ἐωθεῖτο πρὸς αὐτὸν Μέτελλον. ὁ δὲ παρ’ ἡλικίαν ὑποστὰς καὶ περιφανῶς ἀγωνιζόμενος παίεται δόρατι. τοῦτο τούς μὲν ἰδόντας τῶν Ῥωμαίων, τοὺς δὲ ἀκούσαντας αἰδὼς ἔσχεν ἐγκαταλιπεῖν τὸν ἡγεμόνα, καὶ θυμὸς ἅμα πρὸς τούς πολεμίους παρέστη. προθέμενοι δὲ τούς θυρεοὺς καὶ συνεξενεγκόντες εὐρώστως ἐξωθοῦσι τούς Ἴβηρας· καὶ γενομένης οὕτω παλιντρόπου τῆς νίκης, ὁ Σερτώριος ἐκείνοις τε φυγὰς ἀδεεῖς μηχανώμενος καὶ τεχνάζων ἑτέραν αὐτῷ δύναμιν συνελθεῖν ἐφ’ ἡσυχίας, εἰς πόλιν ὀρεινὴν καὶ καρτερὰν ἀναφυγὼν ἐφράγνυτο τὰ τείχη καὶ τὰς πύλας ὠχυροῦτο, πάντα μᾶλλον ἢ πολιορκίαν ὑπομένειν διανοούμενος, ἀλλ’ ἐξηπάτα τοὺς πολεμίους· ἐκείνῳ γὰρ προσκαθεζόμενοι καὶ τὸ χωρίον οὐ χαλεπῶς λήψεσθαι προσδοκῶντες, τούς τε φεύγοντας τῶν βαρβάρων προΐεντο καὶ τῆς ἀθροιζομένης αὖθις τῷ Σερτωρίῳ δυνάμεως ἠμέλησαν. ἠθροίζετο δέ, πέμψαντος ἡγεμόνας ἐπὶ τὰς πόλεις αὐτοῦ, καὶ κελεύοντος ὅταν ἤδη πολλοὺς ἔχωσιν, ἄγγελον ἀποστεῖλαι πρὸς αὐτόν. ἐπεὶ δὲ ἀπέστειλαν, σὺν οὐδενὶ πόνῳ διεκπαισάμενος τούς πολεμίους συνέμιξε τοῖς ἑαυτοῦ· καὶ πάλιν ἐπῄει πολὺς γεγονώς καὶ περιέκοπτεν αὐτῶν τὴν μὲν ἀπὸ τῆς γῆς εὐπορίαν ἐνέδραις καὶ κυκλώσεσι καὶ τῷ πανταχόσε φοιτᾶν ὀξὺς ἐπιών, τὰ δ’ ἐκ θαλάττης λῃστρικοῖς σκάφεσι κατέχων τὴν παραλίαν, ὥστε ἠναγκάσθησαν οἱ στρατηγοὶ διαλυθέντες ὁ μὲν εἰς Γαλατίαν ἀπελθεῖν, Πομπήϊος δὲ περὶ Βακκαίους διαχειμάσαι μοχθηρῶς ὑπὸ ἀχρηματίας, γράφων πρὸς τὴν σύγκλητον ὡς ἀπάξει τὸν στρατόν, εἰ μὴ πέμποιεν ἀργύριον αὐτῷ· καταναλωκέναι γὰρ ἤδη τὰ αὑτοῦ προπολεμῶν τῆς Ἰταλίας. καὶ πολὺς ἦν οὗτος ἐν Ῥώμῃ λόγος, ὡς Πομπηΐου πρότερος εἰς Ἰταλίαν ἀφίξοιτο Σερτώριος· εἰς τοσοῦτον τοὺς πρώτους καὶ δυνατωτάτους τῶν τότε στρατηγῶν ἡ Σερτωρίου δεινότης κατέστησεν.", "st": "Sert. 21.1"}, {"sp": "N", "t": "ἐδήλωσε δὲ καὶ Μέτελλος ἐκπεπληγμένος τὸν ἄνδρα καὶ μέγαν ἡγούμενος, ἐπεκήρυξε γὰρ, εἴ τις αὐτὸν ἀνέλοι Ῥωμαῖος, ἑκατὸν ἀργυρίου τάλαντα δώσειν καὶ πλέθρα δισμύρια γῆς· εἰ δὲ φυγάς, κάθοδον εἰς Ῥώμην, ὡς ἀπογνώσει φανερᾶς ἀμύνης ὠνούμενος τὸν ἄνδρα διὰ προδοσίας. ἔτι δὲ νικήσας ποτὲ μάχῃ τὸν Σερτώριον οὕτως ἐπήρθη καὶ τὴν εὐτυχίαν ἠγάπησεν ὥστε αὐτοκράτωρ ἀναγορευθῆναι, θυσίαις δ’ αὐτὸν αἱ πόλεις ἐπιφοιτῶντα καὶ βωμοῖς ἐδέχοντο. λέγεται δὲ καὶ στεφάνων ἀναδέσεις προσίεσθαι καὶ δείπνων σοβαρωτέρων ὑποδοχάς, ἐν οἷς ἐσθῆτα θριαμβικὴν ἔχων ἔπινε, καὶ Νῖκαι πεποιημέναι δι’ ὀργάνων ἐπιδρόμων χρύσεα τρόπαια καὶ στεφάνους διαφέρουσαι κατήγοντο, καὶ χοροὶ παίδων καὶ γυναικῶν ἐπινικίους ὕμνους ᾖδον εἰς αὐτόν. ἐφ’ οἷς εἰκότως ἦν καταγέλαστος, εἰ δραπέτην Σύλλα καὶ λείψανον τῆς Κάρβωνος φυγῆς ἀποκαλῶν τὸν Σερτώριον οὕτω κεχαύνωται καὶ περιχαρὴς γέγονεν, ὑποχωρήσαντος αὐτοῦ περιγενόμενος.", "st": "Sert. 22.1"}, {"sp": "N", "t": "μεγαλοφροσύνης δὲ τοῦ Σερτωρίου πρῶτον μὲν τὸ τοὺς φεύγοντας ἀπὸ Ῥώμης βουλευτὰς καὶ παρ’ αὐτῷ διατρίβοντας σύγκλητον ἀναγορεῦσαι, ταμίας τε καὶ στρατηγοὺς ἐξ ἐκείνων ἀποδεικνύναι, καὶ πάντα τοῖς πατρίοις νόμοις τὰ τοιαῦτα κοσμεῖν ἔπειτα τὸ χρώμενον ὅπλοις καὶ χρήμασι καὶ πόλεσι ταῖς Ἰβήρων μηδ’ ἄχρι λόγου τῆς ἄκρας ἐξουσίας ὑφίεσθαι πρὸς αὐτούς, Ῥωμαίους δὲ καθιστάναι στρατηγοὺς καὶ ἄρχοντας αὐτῶν, ὡς Ῥωμαίοις ἀνακτώμενον τὴν ἐλευθερίαν, οὐκ ἐκείνους αὔξοντα κατὰ Ῥωμαίων. καὶ γὰρ ἦν ἀνὴρ φιλόπατρις καὶ πολὺν ἔχων ἵμερον τοῦ κατελθεῖν ἀλλὰ δυσπραγῶν μὲν ἠνδραγάθει καὶ ταπεινὸν οὐδὲν ἔπραττε πρὸς τοὺς πολεμίους, ἐν δὲ ταῖς νίκαις διεπέμπετο πρὸς Μέτελλον καὶ πρὸς Πομπήϊον ἕτοιμος ὢν τὰ ὅπλα καταθέσθαι καὶ βιοῦν ἰδιώτης καθόδου τυχών μᾶλλον γὰρ ἐθέλειν ἀσημότατος ἐν Ῥώμῃ πολίτης ἢ φεύγων τὴν ἑαυτοῦ πάντων ὁμοῦ τῶν ἄλλων αὐτοκράτωρ ἀναγορεύεσθαι.", "st": "Sert. 22.4"}, {"sp": "N", "t": "λέγεται δὲ οὐχ ἥκιστα τῆς πατρίδος ἐπιθυμεῖν διὰ τὴν μητέρα, τραφεὶς ὀρφανὸς ὑπ’ αὐτῇ καὶ τὸ σύμπαν ἀνακείμενος ἐκείνῃ, καλούντων δὲ τῶν περὶ τὴν Ἰβηρίαν φίλων αὐτὸν ἐφ’ ἡγεμονίᾳ, πυθόμενος τὴν τελευτὴν τῆς μητρὸς ὀλίγον ἐδέησεν ὑπὸ λύπης προέσθαι τὸν βίον. ἑπτὰ γὰρ ἡμέρας οὔτε σύνθημα δοὺς οὔτε ὀφθείς τινι τῶν φίλων ἔκειτο, καὶ μόλις οἱ συστράτηγοι καὶ ὁμότιμοι τὴν σκηνὴν περιστάντες ἠνάγκασαν αὐτὸν προελθόντα τοῖς στρατιώταις ἐντυχεῖν καὶ τῶν πραγμάτων εὖ φερομένων ἀντιλαμβάνεσθαι. διὸ καὶ πολλοῖς ἔδοξεν ἥμερος ἀνὴρ φύσει γεγονὼς καὶ πρὸς ἡσυχίαν ἔχων ἐπιεικῶς δι’ αἰτίας παρὰ γνώμην ταῖς στρατηγικαῖς ἀρχαῖς χρῆσθαι, καὶ μὴ τυγχάνων ἀδείας, ἀλλὰ συνελαυνόμενος ὑπὸ τῶν ἐχθρῶν εἰς τὰ ὅπλα φρουρὰν ἀναγκαίαν τοῦ σώματος περιβάλλεσθαι τὸν πόλεμον.", "st": "Sert. 22.6"}, {"sp": "N", "t": "ἦν δὲ καὶ τὰ πρὸς Μιθριδάτην αὐτοῦ πολιτεύματα μεγαλοφροσύνης, ἐπεὶ γὰρ ἐκ τοῦ κατὰ Σύλλαν σφάλματος ὁ Μιθριδάτης ὥσπερ εἰς πάλαισμα δεύτερον ἀνιστάμενος αὖθις ἐπεχείρησε τῇ Ἀσίᾳ, μέγα δὲ ἤδη τὸ Σερτωρίου κλέος ἐφοίτα πανταχόσε καὶ τῶν περὶ αὐτοῦ λόγων ὥσπερ φορτίων ξενικῶν οἱ πλέοντες ἀπὸ τῆς ἑσπέρας ἀναπεπλήκεσαν τὸν Πόντον, ὥρμητο διαπρεσβεύεσθαι πρὸς αὐτόν, ἐπηρμένος μάλιστα ταῖς τῶν κολάκων ἀλαζονείαις, οἳ τὸν μὲν Σερτώριον Ἀννίβᾳ, τὸν δὲ Μιθριδάτην Πύρρῳ παρεικάζοντες οὐκ ἂν ἔφασαν Ῥωμαίους πρὸς τηλικαύτας ὁμοῦ φύσεις τε καὶ δυνάμεις ἐπιχειρουμένους διχόθεν ἀντισχεῖν, τοῦ δεινοτάτου στρατηγοῦ τῷ μεγίστῳ τῶν βασιλέων προσγενομένου. πέμπει δὴ πρέσβεις ὁ Μιθριδάτης εἰς Ἰβηρίαν γράμματα Σερτωρίῳ καὶ λόγους κομίζοντας, δι’ ὧν αὐτὸς μὲν ἐπηγγέλλετο χρήματα καὶ ναῦς παρέξειν εἰς τὸν πόλεμον, ὑπ’ ἐκείνου δὲ ἠξίου τὴν Ἀσίαν αὐτῷ βεβαιοῦσθαι πᾶσαν, ἧς ὑπεχώρησε Ῥωμαίοις κατὰ τὰς πρὸς Σύλλαν γενομένας συνθήκας. ἀθροίσαντος δὲ Σερτωρίου βουλήν, ἣν σύγκλητον ὠνόμαζε, καὶ τῶν ἄλλων δέχεσθαι τὰς προκλήσεις καὶ ἀγαπᾶν κελευόντων ὄνομα γὰρ καὶ γράμμα κενὸν αἰτουμένους περὶ τῶν οὐκ ὄντων ἐπ’ αὐτοῖς, ἀντὶ τούτων λαμβάνειν ὧν μάλιστα δεόμενοι τυγχάνουσιν, οὐκ ἠνέσχετο ὁ Σερτώριος, ἀλλὰ Βιθυνίαν μὲν ἔφη καὶ Καππαδοκίαν λαμβάνοντι Μιθριδάτῃ μὴ φθονεῖν, ἔθνη βασιλευόμενα καὶ μηδὲν προσήκοντα Ῥωμαίοις, ἣν δὲ τῷ δικαιοτάτῳ τρόπῳ Ῥωμαίων κεκτημένων ἐπαρχίαν ἀφελόμενος καὶ κατασχών πολεμῶν μὲν ἐξέπεσεν ὑπὸ Φιμβρίου, σπενδόμενος δὲ πρὸς Σύλλαν ἀφῆκε, ταύτην οὐκ ἔφη περιόψεσθαι πάλιν ὑπ’ ἐκείνῳ γενομένην δεῖν γὰρ αὔξεσθαι τὴν πόλιν ὑπ’ αὐτοῦ κρατοῦντος, οὐκ ἐλαττώσει τῶν ἐκείνης κρατεῖν αὐτόν γενναίῳ γὰρ ἀνδρὶ μετὰ τοῦ καλοῦ νικᾶν αἱρετόν, αἰσχρῶς δὲ οὐδὲ σῴζεσθαι.", "st": "Sert. 23.1"}, {"sp": "N", "t": "ταῦτα ἀπαγγελθέντα Μιθριδάτης διὰ θάμβους ἐποιεῖτο· καὶ λέγεται μὲν εἰπεῖν πρὸς τοὺς φίλους· τί δῆτα προστάξει Σερτώριος ἐν Παλατίῳ καθεζόμενος, εἰ νῦν εἰς τὴν Ἀτλαντικὴν ἐξεωσμένος θάλασσαν ὅρους ἡμῶν τῇ βασιλείᾳ τίθησι καὶ πειρωμένοις Ἀσίας ἀπειλεῖ πόλεμον; οὐ μὴν ἀλλὰ γίνονταί γε συνθῆκαι καὶ ὅρκοι, Καππαδοκίαν καὶ Βιθυνίαν ἔχειν Μιθριδάτην· Σερτωρίου στρατηγὸν αὐτῷ καὶ στρατιώτας πέμποντος, Σερτώριον δὲ παρὰ Μιθριδάτου λαβεῖν τρισχίλια τάλαντα καὶ τεσσαράκοντα ναῦς. πέμπεται δὲ καὶ στρατηγὸς εἰς Ἀσίαν ὑπὸ Σερτωρίου τῶν ἀπὸ βουλῆς πεφευγότων πρὸς αὐτὸν Μᾶρκος Μάριος, ᾧ συνεξελών τινας πόλεις τῶν Ἀσιάδων ὁ Μιθριδάτης εἰσελαύνοντι μετὰ ῥάβδων καὶ πελέκεων αὐτὸς εἵπετο δευτέραν τάξιν καὶ σχῆμα θεραπεύοντος ἑκουσίως ἀνειληφώς. ὁ δὲ τὰς μὲν ἠλευθέρου, ταῖς δὲ ἀτέλειαν γράφων χάριτι Σερτωρίου κατήγγελεν, ὥστε τὴν Ἀσίαν αὖθις ἐνοχλουμένην μὲν ὑπὸ τῶν τελωνῶν, βαρυνομένην δὲ ταῖς πλεονεξίαις καὶ ὑπερηφανίαις τῶν ἐπισκήνων, ἀναπτοηθῆναι πρὸς τὴν ἐλπίδα καὶ ποθεῖν τὴν προσδοκωμένην μεταβολὴν τῆς ἡγεμονίας.", "st": "Sert. 24.1"}, {"sp": "N", "t": "ἐν δ’ Ἰβηρίᾳ τῶν περὶ Σερτώριον συγκλητικῶν καὶ ἰσοτίμων, ὡς πρῶτον εἰς ἀντίπαλον ἐλπίδα κατέστησαν, ἐπανέντος τοῦ φόβου, φθόνος ἥπτετο καὶ ζῆλος ἀνόητος τῆς ἐκείνου δυνάμεως, ἐνῆγε δὲ Περπέννας δι’ εὐγένειαν ἐπαιρόμενος φρονήματι κενῷ πρὸς τὴν ἡγεμονίαν, καὶ λόγους μοχθηροὺς διεδίδου κρύφα τοῖς ἐπιτηδείοις· τίς ἄρα πονηρὸς ἡμᾶς ὑπολαβὼν ἐκ κακῶν εἰς χείρονα φέρει δαίμων, οἳ Σύλλᾳ μὲν ὁμοῦ τι συμπάσης ἄρχοντι γῆς καὶ θαλάττης ποιεῖν τὸ προσταττόμενον οὐκ ἠξιοῦμεν οἴκοι μένοντες, δεῦρο δὲ φθαρέντες ὡς ἐλεύθεροι βιωσόμενοι δουλεύομεν ἑκουσίως τὴν Σερτωρίου δορυφοροῦντες φυγήν, ὄνομα χλευαζόμενον ὑπὸ τῶν ἀκουόντων, σύγκλητος, ὄντες, ὕβρεις δὲ καὶ προστάγματα καὶ πόνους οὐκ ἐλάττονας Ἰβήρων καὶ Λυσιτανῶν ὑπομένοντες; τοιούτων ἀναπιμπλάμενοι λόγων οἱ πολλοὶ φανερῶς μὲν οὐκ ἀφίσταντο, δεδοικότες αὐτοῦ τὴν δύναμιν, κρύφα δὲ τάς τε πράξεις ἐλυμαίνοντο, καὶ τοὺς βαρβάρους ἐκάκουν κολάζοντες πικρῶς καὶ δασμολογοῦντες, ὡς Σερτωρίου κελεύοντος. ἐξ ὧν ἀποστάσεις ἐγίνοντο καὶ ταραχαὶ περὶ τάς πόλεις. οἱ δὲ πεμπόμενοι ταῦτα θεραπεύειν καὶ ἀποπραΰνειν ἐπανήρχοντο πλείονας ἐξειργασμένοι πολέμους καὶ τάς ὑπαρχούσας ηὐξηκότες ἀπειθείας, ὥστε τὸν Σερτώριον ἐκ τῆς προτέρας ἐπιεικείας καὶ πρᾳότητος μεταβαλόντα περὶ τοὺς ἐν Ὄσκῃ τρεφομένους παρανομῆσαι παῖδας τῶν Ἰβήρων, τοὺς μὲν ἀνελόντα, τοὺς δὲ ἀποδόμενον.", "st": "Sert. 25.1"}, {"sp": "N", "t": "ὁ δ’ οὖν Περπέννας πλείονας ἐνωμότους ἔχων πρὸς τὴν ἐπίθεσιν προσάγεται καί Μάλλιον, ἕνα τῶν ἐφ’ ἡγεμονίας, οὗτος ἐρῶν τινος τῶν ἐν ὥρᾳ μειρακίου καί φιλοφρονούμενος πρὸς αὐτό φράζει τὴν ἐπιβουλήν, κελεύων ἀμελήσαντα τῶν ἄλλων ἐραστῶν αὐτῷ μόνῳ προσέχειν ὡς ἐντὸς ἡμερῶν ὀλίγων μεγάλῳ γενησομένῳ. τὸ δὲ μειράκιον ἑτέρῳ τινὶ τῶν ἐραστῶν Αὐφιδίῳ μᾶλλον προσπεπονθὸς ἐκφέρει τὸν λόγον. ἀκούσας δὲ ὁ Αὐφίδιος ἐξεπλάγη· καί γὰρ αὐτὸς μετεῖχε τῆς ἐπὶ Σερτώριον συνωμοσίας, οὐ μέντοι τὸν Μάλλιον ἐγίνωσκε μετέχοντα, Περπένναν δὲ καί Γραικῖνον καί τινας ἄλλους, ὧν αὐτὸς ᾔδει συνωμοτῶν, ὀνομάζοντος τοῦ μειρακίου, διαταραχθεὶς πρὸς ἐκεῖνον μὲν ἐξεφλαύριζε τὸν λόγον, καὶ παρεκάλει τοῦ Μαλλίου καταφρονεῖν ὡς κενοῦ καί ἀλαζόνος, αὐτὸς δὲ πρὸς τὸν Περπένναν πορευθεὶς καί φράσας τὴν ὀξύτητα τοῦ καιροῦ καί τὸν κίνδυνον ἐκέλευσεν ἐπιχειρεῖν. οἱ δὲ ἐπείθοντο, καί παρασκευάσαντες ἄνθρωπον γράμματα κομίζοντα τῷ Σερτωρίῳ προσήγαγον. ἐδήλου δὲ τὰ γράμματα νίκην τινὸς τῶν ὑπ’ αὐτῷ στρατηγῶν καί φόνον πολὺν τῶν πολεμίων, ἐφ’ οἷς τοῦ Σερτωρίου περιχαροῦς ὄντος καί θύοντος εὐαγγέλια, Περπέννας ἑστίασιν αὐτῷ καί τοῖς παροῦσι φίλοις (οὗτοι δὲ ἦσαν ἐκ τῆς συνωμοσίας) ἐπηγγέλλετο, καί πολλὰ λιπαρήσας ἔπεισεν ἐλθεῖν.", "st": "Sert. 26.1"}, {"sp": "N", "t": "ἀεὶ μὲν οὖν τὰ μετὰ Σερτωρίου δεῖπνα πολλὴν εἶχεν αἰδῶ καί κόσμον, οὔτε ὁρᾶν τι τῶν αἰσχρῶν οὔτε ἀκούειν ὑπομένοντος, ἀλλὰ καί τοὺς συνόντας εὐτάκτοις καί ἀνυβρίστοις παιδιαῖς χρῆσθαι καί φιλοφροσύναις ἐθίζοντος· τότε δέ, τοῦ πότου μεσοῦντος, ἀρχὴν ἁψιμαχίας ζητοῦντες ἀναφανδὸν ἀκολάστοις ἐχρῶντο ῥήμασι, καί πολλὰ προσποιούμενοι μεθύειν ἠσέλγαινον ὡς παροξυνοῦντες ἐκεῖνον. ὁ δὲ εἴτε δυσχεραίνων τὴν ἀκοσμίαν, εἴτε τὴν διάνοιαν αὐτῶν τῇ θρασύτητι τῆς λαλιᾶς καί τῇ παρὰ τὸ εἰωθὸς ὀλιγωρίᾳ συμφρονήσας, μετέβαλε τὸ σχῆμα τῆς κλισίας, ὕπτιον ἀνεὶς ἑαυτὸν, ὡς οὔτε προσέχων οὔτε κατακούων. ἐπεὶ δὲ ὁ Περπέννας φιάλην τινὰ λαβὼν ἀκράτου μεταξὺ πίνων ἀφῆκεν ἐκ τῶν χειρῶν καί ψόφον ἐποίησεν, ὅπερ ἦν αὐτοῖς σύμβολον, Ἀντώνιος ὑπερκατακείμενος παίει τῷ ξίφει τὸν Σερτώριον. ἀναστρέψαντος δὲ πρὸς τὴν πληγὴν ἐκείνου καί συνεξανισταμένου, περιπεσὼν εἰς τὸ στῆθος κατέλαβε τὰς χεῖρας ἀμφοτέρας, ὥστε μηδὲ ἀμυνόμενον πολλῶν παιόντων ἀποθανεῖν.", "st": "Sert. 26.4"}, {"sp": "N", "t": "οἱ μὲν οὖν πλεῖστοι τῶν Ἰβήρων εὐθὺς ᾤχοντο καὶ παρέδωκαν ἑαυτοὺς ἐπιπρεσβευσάμενοι τοῖς περὶ Πομπήϊον καὶ Μέτελλον τοὺς δὲ συμμείναντας ὁ Περπέννας ἀναλαβὼν ἐπεχείρει τι πράττειν. χρησάμενος δὲ ταῖς Σερτωρίου παρασκευαῖς ὅσον ἐνασχημονῆσαι καὶ φανερὸς γενέσθαι μήτε ἄρχειν μήτε ἄρχεσθαι πεφυκώς, Πομπηΐῳ συνέβαλε· καὶ ταχὺ συντριβεὶς ὑπ’ αὐτοῦ καὶ γενόμενος αἰχμάλωτος οὐδὲ τὴν ἐσχάτην ὑπέμεινε συμφορὰν ἡγεμονικῶς, ἀλλὰ τῶν Σερτωρίου γραμμάτων κύριος γεγονώς ὑπισχνεῖτο Πομπηΐῳ δείξειν ὑπατικῶν ἀνδρῶν καὶ μέγιστον ἐν Ῥώμῃ δυναμένων αὐτογράφους ἐπιστολάς, καλούντων Σερτώριον εἰς Ἰταλίαν, ὡς πολλῶν ποθούντων τὰ παρόντα κινῆσαι καὶ μεταβαλεῖν τὴν πολιτείαν. ἔργον οὖν ὁ Πομπήϊος οὐ νέας φρενός, ἀλλ’ εὖ μάλα βεβηκυίας καὶ κατηρτυμένης ἐργασάμενος μεγάλων ἀπήλλαξε τὴν Ῥώμην φόβων καὶ νεωτερισμῶν, τὰς μὲν γὰρ ἐπιστολὰς ἐκείνας καὶ τὰ γράμματα τοῦ Σερτωρίου συναγαγὼν ἅπαντα κατέκαυσεν οὔτε αὐτὸς ἀναγνοὺς οὔτε ἐάσας ἕτερον· αὐτὸν δὲ τὸν Περπένναν κατὰ τάχος ἀνεῖλε, φοβηθεὶς μὴ τῶν ὀνομάτων ἐξενεχθέντων πρός τινας ἀποστάσεις καὶ ταραχαὶ γένωνται.", "st": "Sert. 27.1"}, {"sp": "N", "t": "τῶν δὲ τῷ Περπέννᾳ συνομοσαμένων οἱ μὲν ἐπὶ Πομπήϊον ἀναχθέντες διεφθάρησαν, οἱ δὲ φεύγοντες εἰς Λιβύην ὑπὸ Μαυρουσίων κατηκοντίσθησαν. διέφυγε δ’ οὐδεὶς πλὴν Αὐφίδιος ὁ τοῦ Μαλλίου ἀντεραστής· οὗτος δὲ ἢ λαθὼν ἢ παραμεληθεὶς ἔν τινι βαρβάρῳ κώμῃ πενόμενος καὶ μισούμενος κατεγήρασεν.", "st": "Sert. 27.4"}, {"sp": "HDR", "t": "Σερτωρίου καὶ Εὐμένους σύγκρισις"}, {"sp": "N", "t": "ταῦτα ἔστιν ἃ περὶ Εὐμενοῦς καὶ Σερτωρίου μνήμης ἄξια παρειλήφαμεν. ἐν δὲ τῇ συγκρίσει κοινὸν μὲν ἀμφοτέροις ὑπάρχει τὸ ξένους καὶ ἀλλοδαποὺς καὶ φυγάδας ὄντας ἐθνῶν τε παντοδαπῶν καὶ στρατευμάτων μαχίμων τε καὶ μεγάλων ἡγουμένους διατελεῖν, ἴδιον δὲ Σερτωρίῳ μὲν τὸ παρὰ πάντων τῶν συμμάχων δεδομένην ἔχειν διὰ τὸ ἀξίωμα τὴν ἀρχήν, Εὐμενεῖ δὲ τὸ πολλῶν διαφερομένων περὶ τῆς ἡγεμονίας πρὸς αὐτὸν ἐκ τῶν πράξεων λαμβάνειν τὸ πρωτεῖον καὶ τῷ μὲν ἄρχεσθαι βουλόμενοι δικαίως εἵποντο, τῷ δὲ ἄρχειν μὴ δυνάμενοι πρὸς τὸ συμφέρον ὑπήκουον. καὶ γὰρ ὁ μὲν Ἰβήρων καὶ Λυσιτανῶν Ῥωμαῖος, ὁ δὲ Χερρονησίτης Μακεδόνων ἦρχεν, ὧν οἱ μὲν ἔκπαλαι Ῥωμαίοις ἐδούλευον, οἱ δὲ τότε πάντας ἀνθρώπους ἐδουλοῦντο. καὶ Σερτώριος μὲν ἀπὸ βουλῆς καὶ στρατηγίας θαυμαζόμενος, Εὐμενὴς δὲ διὰ τὴν γραμματείαν καταφρονούμενος ἐφ’ ἡγεμονίαν προῆλθεν. οὐ μόνον τοίνυν ἐλάττοσι πρὸς τὴν ἀρχὴν ἀφορμαῖς, ἀλλὰ καὶ μείζοσι πρὸς τὴν αὔξησιν ἐχρήσατο κωλύμασιν Εὐμενής. καὶ γὰρ ἄντικρυς τοὺς ἐνισταμένους καὶ κρύφα τοὺς ἐπιβουλεύοντας εἶχε πολλούς, οὐχ ὥσπερ τῷ ἑτέρῳ φανερῶς μὲν οὐδείς, λάθρα δὲ ὕστερον καὶ ὀλίγοι τῶν συμμάχων ἐπανέστησαν. διὸ τῷ μὲν ἦν πέρας τοῦ κινδυνεύειν τὸ νικᾶν τοὺς πολεμίους, τῷ δὲ ἐκ τοῦ νικᾶν ὁ κίνδυνος ὑπὸ τῶν φθονούντων.", "st": "Comp. Eum.–Sert. 1.1"}, {"sp": "N", "t": "τὰ μὲν οὖν κατὰ τὴν στρατηγίαν ἐφάμιλλα καὶ παράλληλα· τῷ δὲ ἄλλῳ τρόπῳ φιλοπόλεμος μὲν ὁ Εὐμενὴς καὶ φιλόνεικος, ἡσυχίας δὲ καὶ πρᾳότητος οἰκεῖος ὁ Σερτώριος. ὁ μὲν γὰρ, ἀσφαλῶς καὶ μετὰ τιμῆς βιοῦν ἐξὸν ἐκποδὼν γενομένῳ τοῖς πρώτοις, μαχόμενος καὶ κινδυνεύων διετέλεσε, τῷ δὲ οὐδὲν δεομένῳ πραγμάτων ὑπὲρ αὐτῆς τῆς τοῦ σώματος ἀσφαλείας πρὸς οὐκ ἐῶντας εἰρήνην ἄγειν ἦν ὁ πόλεμος. Εὐμενεῖ μὲν γὰρ Ἀντίγονος ἐκστάντι τῶν ὑπὲρ τοῦ πρωτεύειν ἀγώνων ἡδέως ἂν ἐχρῆτο τὴν μετ’ αὐτὸν ἀγαπῶντι τάξιν, Σερτωρίῳ δὲ οἱ περὶ Πομπήϊον οὐδὲ ζῆν ἀπραγμόνως ἐπέτρεπον. διὸ τῷ μὲν ἑκοντὶ συνέβαινε πολεμεῖν ἐπ’ ἀρχῇ, τῷ δὲ ἀκουσίως ἄρχειν διὰ τὸ πολεμεῖσθαι. φιλοπόλεμος μὲν οὖν ὁ τῆς ἀσφαλείας τὴν πλεονεξίαν προτιμῶν, πολεμικὸς δὲ ὁ τῷ πολέμῳ κτώμενος τὴν ἀσφάλειαν.", "st": "Comp. Eum.–Sert. 2.1"}, {"sp": "N", "t": "καὶ μὴν θανεῖν γε συνέβη τῷ μὲν οὐ προαισθομένῳ, τῷ δὲ καὶ προσδεχομένῳ τὴν τελευτήν, ὧν τὸ μὲν ἐπιεικείας, φίλοις γὰρ ἐδόκει πιστεύειν, τὸ δὲ ἀσθενείας, βουλόμενος γὰρ φυγεῖν συνελήφθη. καὶ τοῦ μὲν οὐ κατῄσχυνε τὸν βίον ὁ θάνατος, πάσχοντος ὑπὸ τῶν συμμάχων ἃ τῶν πολεμίων αὐτὸν οὐδεὶς ἐποίησεν ὁ δὲ φεύγειν μὲν πρὸ αἰχμαλωσίας μὴ δυνηθείς, ζῆν δὲ μετ’ αἰχμαλωσίαν βουληθείς, οὔτε ἐφυλάξατο καλῶς τὴν τελευτὴν οὔθ’ ὑπέμεινεν, ἀλλὰ προσλιπαρῶν καὶ δεόμενος τοῦ σώματος μόνου κρατεῖν δοκοῦντα τὸν πολέμιον καὶ τῆς ψυχῆς αὑτοῦ κύριον ἐποίησεν.", "st": "Comp. Eum.–Sert. 2.4"}], []);})();
